const SELL_ONLY_LOGS = process.env.SELL_ONLY_LOGS === "1";
const LOG_HUMAN = process.env.LOG_HUMAN !== "0";
const LOG_HEARTBEAT_EVERY = Math.max(1, Number(process.env.LOG_HEARTBEAT_EVERY || 5));
const LOG_STRAT_OUT_EVERY = Math.max(1, Number(process.env.LOG_STRAT_OUT_EVERY || 3));

let cpuSampleLastHrNs = process.hrtime.bigint();
let cpuSampleLastUsage = process.cpuUsage();
let cpuSampleLastPct = 0;
const CPU_SAMPLE_MIN_INTERVAL_NS = 500_000_000;
const CPU_SAMPLE_EMA_ALPHA = 0.35;
type CpuWorkBucket =
  | "main_loop"
  | "bot_runtime"
  | "quote"
  | "http_homepage"
  | "http_state"
  | "http_bots"
  | "http_focused_live_session"
  | "http_live_markers"
  | "http_session_history"
  | "http_chart_history"
  | "http_compare"
  | "http_portfolio"
  | "http_markets"
  | "http_run_audit"
  | "http_drive_audit"
  | "http_operator"
  | "http_readonly_proxy"
  | "http_other";
const CPU_WORK_WINDOW_MS = Math.max(10_000, Number(process.env.CPU_WORK_WINDOW_MS || 60_000));
const CPU_WORK_SAMPLES_MAX = Math.max(256, Number(process.env.CPU_WORK_SAMPLES_MAX || 10_000));
const CPU_WORK_BUCKET_META: Array<{ key: CpuWorkBucket; label: string; page: string }> = [
  { key: "main_loop", label: "runtime loop", page: "Core loop" },
  { key: "bot_runtime", label: "bot runtime", page: "Execution panels" },
  { key: "quote", label: "quote feed", page: "Live chart" },
  { key: "http_homepage", label: "page shell", page: "Homepage refresh" },
  { key: "http_state", label: "state + health", page: "Health panel" },
  { key: "http_bots", label: "bot api", page: "Market rail + focus" },
  { key: "http_focused_live_session", label: "focused live session", page: "Focused live chart bundle" },
  { key: "http_live_markers", label: "live markers", page: "Live chart markers" },
  { key: "http_session_history", label: "history api", page: "History API" },
  { key: "http_chart_history", label: "chart history", page: "History traces" },
  { key: "http_compare", label: "compare", page: "Compare + run dash" },
  { key: "http_portfolio", label: "portfolio", page: "Drawer portfolio" },
  { key: "http_markets", label: "markets", page: "Markets + strategies" },
  { key: "http_run_audit", label: "run audits", page: "Audit panels" },
  { key: "http_drive_audit", label: "drive audit", page: "Drive audit" },
  { key: "http_operator", label: "operator", page: "Notices + summary" },
  { key: "http_readonly_proxy", label: "readonly proxy wait", page: "Readonly proxy wait" },
  { key: "http_other", label: "other http", page: "Other API" },
];
const CPU_WORK_BUCKET_LABELS: Record<string, { label: string; page: string }> = Object.fromEntries(
  CPU_WORK_BUCKET_META.map((row) => [row.key, { label: row.label, page: row.page }])
);
const cpuWorkSamples: Array<{ t: number; bucket: CpuWorkBucket; durationMs: number }> = [];
const cpuWorkTotalsByBucket = new Map<CpuWorkBucket, number>();

function sampleProcessCpuPct() {
  const nowHrNs = process.hrtime.bigint();
  const usageNow = process.cpuUsage();
  const wallNs = Number(nowHrNs - cpuSampleLastHrNs);
  if (Number.isFinite(wallNs) && wallNs > 0 && wallNs < CPU_SAMPLE_MIN_INTERVAL_NS) {
    return cpuSampleLastPct;
  }
  const cpuMicros =
    (Number(usageNow.user) - Number(cpuSampleLastUsage.user))
    + (Number(usageNow.system) - Number(cpuSampleLastUsage.system));
  if (Number.isFinite(wallNs) && wallNs > 0 && Number.isFinite(cpuMicros) && cpuMicros >= 0) {
    const rawPct = (cpuMicros / (wallNs / 1000)) * 100;
    cpuSampleLastPct =
      Number.isFinite(Number(cpuSampleLastPct)) && Number(cpuSampleLastPct) > 0
        ? (Number(cpuSampleLastPct) * (1 - CPU_SAMPLE_EMA_ALPHA)) + (rawPct * CPU_SAMPLE_EMA_ALPHA)
        : rawPct;
  }
  cpuSampleLastHrNs = nowHrNs;
  cpuSampleLastUsage = usageNow;
  return cpuSampleLastPct;
}

function pruneCpuWorkSamples(now = nowMs()): void {
  while (cpuWorkSamples.length > 0) {
    const head = cpuWorkSamples[0];
    if ((now - Number(head?.t || 0)) <= CPU_WORK_WINDOW_MS && cpuWorkSamples.length <= CPU_WORK_SAMPLES_MAX) break;
    cpuWorkSamples.shift();
    const bucket = head.bucket;
    const prev = Number(cpuWorkTotalsByBucket.get(bucket) || 0);
    const next = Math.max(0, prev - Math.max(0, Number(head.durationMs || 0)));
    if (next > 0) cpuWorkTotalsByBucket.set(bucket, next);
    else cpuWorkTotalsByBucket.delete(bucket);
  }
}

function recordCpuWork(bucket: CpuWorkBucket, durationMsRaw: any): void {
  const durationMs = Number(durationMsRaw);
  if (!Number.isFinite(durationMs) || durationMs <= 0) return;
  const clampedMs = Math.max(0, Math.min(durationMs, CPU_WORK_WINDOW_MS));
  const t = nowMs();
  cpuWorkSamples.push({ t, bucket, durationMs: clampedMs });
  cpuWorkTotalsByBucket.set(bucket, Number(cpuWorkTotalsByBucket.get(bucket) || 0) + clampedMs);
  pruneCpuWorkSamples(t);
}

function cpuWorkBucketForPathname(pathnameLike: any): CpuWorkBucket {
  const raw = String(pathnameLike || "").trim();
  const pathname = (raw.split("?")[0] || "").trim();
  if (pathname === "/") return "http_homepage";
  if (pathname === "/api/health" || pathname === "/api/state" || pathname === "/api/frontend-config") return "http_state";
  if (/^\/api\/operator-notices\b/i.test(pathname) || /^\/api\/stats\/summary\b/i.test(pathname)) return "http_operator";
  if (/^\/api\/run-audits\/review\b/i.test(pathname) || /^\/api\/session-audits\/review\b/i.test(pathname)) return "http_run_audit";
  if (/^\/api\/v2\/strategies\b/i.test(pathname) || /^\/api\/v2\/markets\b/i.test(pathname)) return "http_markets";
  if (/^\/api\/v2\/portfolio\b/i.test(pathname)) return "http_portfolio";
  if (/^\/api\/v2\/drive\/audit\b/i.test(pathname)) return "http_drive_audit";
  if (/^\/api\/compare\/run-dashboard\b/i.test(pathname)) return "http_compare";
  if (/^\/api\/chart-history\b/i.test(pathname)) return "http_chart_history";
  if (/^\/api\/session-history\b/i.test(pathname)) return "http_session_history";
  if (/^\/api\/v2\/bots\/[^/]+\/continuity-history\b/i.test(pathname)) return "http_session_history";
  if (/^\/api\/v2\/bots\/[^/]+\/focused-live-session\b/i.test(pathname)) return "http_focused_live_session";
  if (/^\/api\/v2\/bots\/[^/]+\/live-markers\b/i.test(pathname)) return "http_live_markers";
  if (/^\/api\/v2\/bots\/[^/]+\/rollover-ready\b/i.test(pathname)) return "http_other";
  if (/^\/api\/v2\/bots\b/i.test(pathname)) return "http_bots";
  return "http_other";
}

function buildProcessCpuBreakdown(processCpuPctRaw: any): any {
  const processCpuPct = Number(processCpuPctRaw);
  const now = nowMs();
  pruneCpuWorkSamples(now);
  const waitBuckets = new Set<CpuWorkBucket>(["http_readonly_proxy"]);
  const itemsRaw = Object.entries(CPU_WORK_BUCKET_LABELS)
    .map(([bucket, meta]) => ({
      key: String(bucket),
      label: String(meta?.label || bucket),
      page: String(meta?.page || ""),
      busyMs: Math.max(0, Number(cpuWorkTotalsByBucket.get(bucket as CpuWorkBucket) || 0)),
    }));
  const cpuItemsRaw = itemsRaw.filter((row) => !waitBuckets.has(row.key as CpuWorkBucket));
  const waitItems = itemsRaw
    .filter((row) => waitBuckets.has(row.key as CpuWorkBucket))
    .map((row) => ({
      ...row,
      busyMs: Number(row.busyMs.toFixed(1)),
    }));
  const waitBusyMs = waitItems.reduce((sum, row) => sum + row.busyMs, 0);
  const totalBusyMs = cpuItemsRaw.reduce((sum, row) => sum + row.busyMs, 0);
  if (!(Number.isFinite(processCpuPct) && processCpuPct >= 0)) {
    return {
      windowMs: CPU_WORK_WINDOW_MS,
      totalBusyMs: Number(totalBusyMs.toFixed(1)),
      items: cpuItemsRaw.map((row) => ({
        ...row,
        busyMs: Number(row.busyMs.toFixed(1)),
        pct: null,
      })),
      waitBusyMs: Number(waitBusyMs.toFixed(1)),
      waitItems,
      otherPct: null,
    };
  }
  if (!(totalBusyMs > 0)) {
    return {
      windowMs: CPU_WORK_WINDOW_MS,
      totalBusyMs: 0,
      items: cpuItemsRaw.map((row) => ({
        ...row,
        busyMs: Number(row.busyMs.toFixed(1)),
        pct: 0,
      })),
      waitBusyMs: Number(waitBusyMs.toFixed(1)),
      waitItems,
      otherPct: Number(processCpuPct.toFixed(1)),
    };
  }
  const items = cpuItemsRaw
    .map((row) => ({
      ...row,
      busyMs: Number(row.busyMs.toFixed(1)),
      pct: Number((processCpuPct * (row.busyMs / totalBusyMs)).toFixed(1)),
    }))
    .sort((a, b) => Number(b.pct || 0) - Number(a.pct || 0));
  const assignedPct = items.reduce((sum, row) => sum + (Number(row.pct) || 0), 0);
  return {
    windowMs: CPU_WORK_WINDOW_MS,
    totalBusyMs: Number(totalBusyMs.toFixed(1)),
    items,
    waitBusyMs: Number(waitBusyMs.toFixed(1)),
    waitItems,
    otherPct: Number(Math.max(0, processCpuPct - assignedPct).toFixed(1)),
    otherLabel: "unattributed",
  };
}

const _rawConsole = {
  log: console.log.bind(console),
  warn: console.warn.bind(console),
  error: console.error.bind(console),
};
const _suppressedByKey = new Map<string, number>();
const _seenByKey = new Map<string, number>();

function _redactSensitiveText(raw: string): string {
  let out = String(raw || "");
  const jsonKeys = [
    "POLY_API_KEY",
    "POLY_PASSPHRASE",
    "POLY_SECRET",
    "POLY_SIGNATURE",
    "signature",
    "passphrase",
    "secret",
    "authorization",
  ];
  for (const key of jsonKeys) {
    out = out.replace(new RegExp(`("${key}"\\s*:\\s*")[^"]+(")`, "gi"), `$1<redacted>$2`);
  }
  const queryKeys = ["POLY_API_KEY", "POLY_PASSPHRASE", "POLY_SECRET", "POLY_SIGNATURE"];
  for (const key of queryKeys) {
    out = out.replace(new RegExp(`(${key}=)[^\\s&]+`, "gi"), `$1<redacted>`);
  }
  return out;
}

function _argToText(a: any): string {
  if (a instanceof Error) return String(a.stack || a.message || a);
  if (typeof a === "string") return a;
  if (typeof a === "number" || typeof a === "boolean" || a == null) return String(a);
  try {
    return JSON.stringify(a);
  } catch {
    return String(a);
  }
}

function _sellOnlyAllowed(msg: string): boolean {
  const m = msg.toUpperCase();
  return m.includes("SELL") || m.includes("EXIT") || m.includes("STOP");
}

function _normalizeTag(rawTag: string): string {
  const t = rawTag.trim();
  if (t.startsWith("HEARTBEAT")) return "HEARTBEAT";
  if (t.startsWith("STRAT OUT")) return "STRAT OUT";
  return t;
}

function _extractTag(msg: string): { tag: string; rest: string } {
  const trimmed = msg.trim();
  if (trimmed.startsWith("[")) {
    const i = trimmed.indexOf("]");
    if (i > 1) {
      const rawTag = trimmed.slice(1, i);
      return { tag: _normalizeTag(rawTag), rest: trimmed.slice(i + 1).trim() };
    }
  }
  return { tag: "LOG", rest: trimmed };
}

function _throttleEveryForTag(tag: string): number {
  if (tag === "HEARTBEAT") return LOG_HEARTBEAT_EVERY;
  if (tag === "STRAT OUT") return LOG_STRAT_OUT_EVERY;
  return 1;
}

function _formatLine(level: "log" | "warn" | "error", msg: string): string {
  if (!LOG_HUMAN) return msg;
  const { tag, rest } = _extractTag(msg);
  const ts = new Date().toISOString().slice(11, 19);
  const lv = level === "error" ? "ERR" : level === "warn" ? "WRN" : "INF";
  return `${ts} ${lv} ${tag.padEnd(12)} | ${rest}`;
}

function _emitLog(level: "log" | "warn" | "error", args: any[]) {
  const rawMsg = _redactSensitiveText(args.map(_argToText).join(" "));
  if (SELL_ONLY_LOGS && !_sellOnlyAllowed(rawMsg)) return;

  const { tag } = _extractTag(rawMsg);
  const every = _throttleEveryForTag(tag);
  const key = `${level}:${tag}`;
  const seen = (_seenByKey.get(key) || 0) + 1;
  _seenByKey.set(key, seen);
  if (every > 1 && seen % every !== 1) {
    _suppressedByKey.set(key, (_suppressedByKey.get(key) || 0) + 1);
    return;
  }

  const suppressed = _suppressedByKey.get(key) || 0;
  if (suppressed > 0) {
    _suppressedByKey.set(key, 0);
    _rawConsole[level](_formatLine(level, `[${tag}] suppressed ${suppressed} similar lines`));
  }
  _rawConsole[level](_formatLine(level, rawMsg));
}

console.log = (...args: any[]) => _emitLog("log", args);
console.warn = (...args: any[]) => _emitLog("warn", args);
console.error = (...args: any[]) => _emitLog("error", args);

function logInfo(msg: string) {
  console.log(msg);
}

function logWarn(msg: string) {
  console.warn(msg);
}

function logError(msg: string) {
  console.error(msg);
}

function fmt2(v: any): string {
  const n = Number(v);
  return Number.isFinite(n) ? n.toFixed(2) : "—";
}


function resolveOriginalServerStrategyPath(): string {
  const cwdOriginal = path.resolve(process.cwd(), "strategy_external.js");
  if (fs.existsSync(cwdOriginal)) return cwdOriginal;
  const srcOriginal = path.resolve(process.cwd(), "src/strategy_external.js");
  if (fs.existsSync(srcOriginal)) return srcOriginal;
  const cwdDerisk = path.resolve(process.cwd(), "strategy_external_single_instance_derisk.js");
  if (fs.existsSync(cwdDerisk)) return cwdDerisk;
  return path.resolve(process.cwd(), "src/strategy_external_single_instance_derisk.js");
}

