let DERISK_STRICT_DERISK_THR = clamp01(Number(process.env.DERISK_STRICT_DERISK_THR || 0.69));
let DERISK_STRICT_TP_THR = clamp01(Number(process.env.DERISK_STRICT_TP_THR || 0.96));
let DERISK_STRICT_STOP_THR = clamp01(Number(process.env.DERISK_STRICT_STOP_THR || 0.4));
let DERISK_STRICT_RUNNER_STOP_THR = clamp01(
  Number(process.env.DERISK_STRICT_RUNNER_STOP_THR || process.env.DERISK_STRICT_STOP_THR || 0.43)
);

function syncDeriskCanonicalFromStrategy(reason: string): void {
  try {
    const deriskPath = resolveBotStrategyPath("derisk", null);
    const factory = loadStrategyFactoryFromFile(deriskPath);
    const strat = factory({});
    const snap = (strat && typeof (strat as any).snapshot === "function") ? (strat as any).snapshot() : null;
    const cfg = snap && typeof snap === "object" ? (snap as any).cfg : null;
    if (!cfg || typeof cfg !== "object") return;
    const e = clamp01(Number((cfg as any).buyThr));
    const d = clamp01(Number((cfg as any).deriskThr));
    const tp = clamp01(Number((cfg as any).sellThr));
    const st = clamp01(Number((cfg as any).stopThr));
    const runnerSt = clamp01(Number((cfg as any).runnerStopThr));
    if (Number.isFinite(e)) DERISK_STRICT_ENTRY_THR = e;
    if (Number.isFinite(d)) DERISK_STRICT_DERISK_THR = d;
    if (Number.isFinite(tp)) DERISK_STRICT_TP_THR = tp;
    if (Number.isFinite(st)) DERISK_STRICT_STOP_THR = st;
    if (Number.isFinite(runnerSt)) DERISK_STRICT_RUNNER_STOP_THR = runnerSt;
    else if (Number.isFinite(st)) DERISK_STRICT_RUNNER_STOP_THR = st;
  } catch (e: any) {
    console.warn(`[DERISK CANONICAL SYNC FAIL] reason=${reason} err=${String(e?.message ?? e)}`);
  }
}

function normalizeStrategyId(raw: any): StrategyId {
  const v = String(raw || "momentum_hc").trim().toLowerCase();
  if (v === "momentum_hc_trade3_latency") return "momentum_hc_trade3_latency";
  if (v === "momentum_hc_trade3_100") return "momentum_hc_trade3_100";
  if (v === "momentum_hc_trade3_b") return "momentum_hc_trade3_b";
  if (v === "momentum_hc_trade3") return "momentum_hc_trade3";
  if (v === "hc_entrygate80") return "hc_entrygate80";
  if (v === "latency_touch_55_60") return "latency_touch_55_60";
  if (v === "profit_locker") return "profit_locker";
  if (v === "kalman") return "kalman";
  if (v === "profit_locker_inflection") return "profit_locker_inflection";
  if (v === "inflection_100") return "inflection_100";
  if (v === "inflection_positive_slope") return "inflection_positive_slope";
  if (v === "inflection_positive_slope_500_2000") return "inflection_positive_slope_500_2000";
  if (v === "inflection_positive_slope_200_750") return "inflection_positive_slope_200_750";
  if (v === "inflection_positive_iteration") return "inflection_positive_iteration";
  if (v === "derisk") return "derisk";
  if (v === "derisk_trade3") return "derisk_trade3";
  if (v === "confidence_b_phase1") return "confidence_b_phase1";
  if (v === "confidence_c_pmodel") return "confidence_c_pmodel";
  return "momentum_hc";
}

