// ===== Helpers =====
function floorTo5mEpoch(tsSec: number) {
  return tsSec - (tsSec % 300);
}
function nowMs() {
  return Date.now();
}
function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}
async function promiseOrTimeout<T>(work: Promise<T>, timeoutMs: number, fallback: T): Promise<T> {
  let timer: NodeJS.Timeout | null = null;
  try {
    return await Promise.race<T>([
      work,
      new Promise<T>((resolve) => {
        timer = setTimeout(() => resolve(fallback), Math.max(1, Number(timeoutMs) || 1));
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}
function clamp(x: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, x));
}
function isDeriskModeLabel(v: any): boolean {
  return /DERISK/.test(String(v || "").toUpperCase());
}
function strategyAllowsDualLaneEntries(modeHint?: string | null): boolean {
  if (["1", "true", "yes", "on"].includes(PAPER_DUAL_LANE_ENTRIES)) return true;
  if (["0", "false", "no", "off"].includes(PAPER_DUAL_LANE_ENTRIES)) return false;
  if (isDeriskModeLabel(modeHint)) return true;
  if (isDeriskModeLabel((TradeStrategy as any)?.VERSION)) return true;
  const p = String(path.basename(String(STRATEGY_PATH || ""))).toLowerCase();
  return p.includes("derisk");
}
function activeEntryPriceCapPx(): number | null {
  return strategyAllowsDualLaneEntries() ? DERISK_MAX_ENTRY_PX : null;
}
function clampEntryBuyPx(px: number): number {
  const c = activeEntryPriceCapPx();
  const v = clamp01(px);
  if (Number.isFinite(Number(c)) && Number(c) > 0) return clamp01(Math.min(v, Number(c)));
  return v;
}
function shouldRearmLiveEntryAfterError(errMsg: string): boolean {
  const m = String(errMsg || "").toLowerCase();
  const unfilled =
    m.includes("not filled within ttlms") ||
    m.includes("ttl expired") ||
    m.includes("cancel not confirmed") ||
    m.includes("not filled by untiltsms") ||
    m.includes("no match") ||
    m.includes("no fill") ||
    m.includes("not enough balance") ||
    m.includes("insufficient") ||
    m.includes("allowance");
  return (
    unfilled ||
    m.includes("below exchange minimum") ||
    m.includes("buy limit failed") ||
    m.includes("invalid order payload") ||
    m.includes("did not return orderid") ||
    m.includes("invalid buy price") ||
    m.includes("invalid notionalusd") ||
    m.includes("invalid calculated size")
  );
}
function shouldRearmLiveEntryAfterErrorForStrategy(strategyIdLike: any, errMsg: string): boolean {
  const strategyId = normalizeStrategyId(String(strategyIdLike || "").trim().toLowerCase());
  if (isLatencyProbeStrategy(strategyId) || isMhc3LatencyStrategy(strategyId)) return false;
  return shouldRearmLiveEntryAfterError(errMsg);
}
function isLikelyUnfilledLiveBuy(errMsg: string): boolean {
  const m = String(errMsg || "").toLowerCase();
  return (
    m.includes("not filled within ttlms") ||
    m.includes("ttl expired") ||
    m.includes("cancel not confirmed") ||
    m.includes("not filled by untiltsms") ||
    m.includes("no match") ||
    m.includes("no fill")
  );
}
function isoNow() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
}

async function getJson(url: string, params?: Record<string, any>) {
  const u = new URL(url);
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null) u.searchParams.set(k, String(v));
    }
  }
  const r = await fetch(u.toString(), { method: "GET" });
  if (!r.ok) {
    const text = await r.text().catch(() => "");
    throw new Error(`GET ${u} -> ${r.status} ${r.statusText} ${text}`.slice(0, 600));
  }
  return r.json();
}

async function getJsonWithTimeout(url: string, params: Record<string, any> | undefined, timeoutMs: number) {
  const u = new URL(url);
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null) u.searchParams.set(k, String(v));
    }
  }
  const ctrl = new AbortController();
  const to = setTimeout(() => ctrl.abort("timeout"), timeoutMs);
  try {
    const r = await fetch(u.toString(), { method: "GET", signal: ctrl.signal });
    if (!r.ok) {
      const text = await r.text().catch(() => "");
      throw new Error(`GET ${u} -> ${r.status} ${r.statusText} ${text}`.slice(0, 600));
    }
    return await r.json();
  } finally {
    clearTimeout(to);
  }
}

function clamp01(px: number) {
  return SharedExec.clampProb(px, { strictPriceBand: true });
}
function inferSideBid(
  side: OutcomeSide,
  upBA: { bid: number | null },
  dnBA: { bid: number | null }
): number | null {
  return SharedExec.inferSideBid(side, upBA?.bid, dnBA?.bid, { strictPriceBand: true });
}
function shouldTriggerStop(
  ui: UiConfig,
  side: OutcomeSide,
  px: number,
  elapsedSec: number,
  engine: Engine,
  source: "generic" | "strategy" | "resting_server" | "resting_stop"
): boolean {
  const shouldStop = SharedExec.shouldTriggerStop(ui, px, elapsedSec);
  if (shouldStop) return true;
  if (!ui.useStop || !ui.useStopTimeGate) return false;
  if (!Number.isFinite(px) || px > ui.stop) return false;
  if (elapsedSec >= ui.stopStartSec) return false;

  console.log(
    `[STOP BLOCKED by gate] engine=${engine} source=${source} side=${side} ` +
    `elapsed=${elapsedSec.toFixed(2)}s stopStartSec=${ui.stopStartSec} px=${px} stop=${ui.stop}`
  );
  return false;
}

function buyPxForSide(
  side: OutcomeSide,
  upBA: { bid: number | null; ask?: number | null },
  dnBA: { bid: number | null; ask?: number | null },
  limitPx: number
) {
  const ask = side === "UP" ? upBA.ask : dnBA.ask;
  const bid = side === "UP" ? upBA.bid : dnBA.bid;
  const limit = clampEntryBuyPx(limitPx);
  const pxRaw = Number.isFinite(ask as any) ? Math.min(Number(ask), limit) : limit;
  const px = clampEntryBuyPx(pxRaw);
  // Loud debug if we’re about to place a non-marketable order
  console.log(`[BUY PX] side=${side} bid=${bid} ask=${ask} chosen=${px} limit=${limit}`);
  return px;
}

function configuredEntryLimitPx(ui: UiConfig): number {
  return clampEntryBuyPx(Number(ui.entry) + LIVE_ENTRY_AGGRESSIVE_BUFFER);
}

function latencyMarketBuyPriceForSide(
  side: OutcomeSide,
  fallbackPxLike: number | null | undefined
): number | null {
  const fallbackPx = Number(fallbackPxLike);
  const pair = getCachedQuotePair(String(current.upToken || ""), String(current.downToken || ""), Number.POSITIVE_INFINITY);
  const askPx =
    side === "UP"
      ? Number((pair as any)?.upAsk)
      : Number((pair as any)?.downAsk);
  const basePx =
    Number.isFinite(askPx) && askPx > 0
      ? askPx
      : (Number.isFinite(fallbackPx) && fallbackPx > 0 ? fallbackPx : NaN);
  if (!(Number.isFinite(basePx) && basePx > 0)) return null;
  return floorTo6(clamp01(Math.min(LIVE_MARKET_PRICE_CAP, basePx + LIVE_MARKET_PRICE_BUFFER)));
}

function configuredTakeProfitGuardPx(ui: UiConfig): number | null {
  const tpPx = Number(ui?.exit);
  return Number.isFinite(tpPx) && tpPx > 0 && tpPx < 1.1 ? tpPx : null;
}

function entryAtOrAboveTakeProfitMeta(
  entryPxLike: number | null | undefined,
  ui: UiConfig,
  strategyIdLike?: string | null
): { entryPx: number; tpPx: number } | null {
  const strategyId = String(strategyIdLike || "").trim().toLowerCase();
  if (
    strategyId === "inflection_positive_slope" ||
    strategyId === "inflection_positive_slope_500_2000" ||
    strategyId === "inflection_positive_slope_200_750" ||
    strategyId === "inflection_positive_iteration"
  ) {
    return null;
  }
  const entryPx = Number(entryPxLike);
  const tpPx = configuredTakeProfitGuardPx(ui);
  if (!(Number.isFinite(entryPx) && Number.isFinite(tpPx))) return null;
  if (entryPx < (tpPx - 1e-9)) return null;
  return { entryPx, tpPx };
}

function assertEntryBelowTakeProfit(
  entryPxLike: number | null | undefined,
  ui: UiConfig,
  context: string,
  strategyIdLike?: string | null
): void {
  const meta = entryAtOrAboveTakeProfitMeta(entryPxLike, ui, strategyIdLike);
  if (!meta) return;
  throw new Error(
    `[ENTRY TP GUARD] context=${context} entryPx=${roundTo6(meta.entryPx)} tpPx=${roundTo6(meta.tpPx)}`
  );
}

async function rejectInvalidFilledLiveBuyAtOrAboveTp(
  side: OutcomeSide,
  filledPxLike: number | null | undefined,
  sharesLike: number | null | undefined,
  ui: UiConfig,
  tokenId: string,
  context: string,
  strategyIdLike?: string | null
): Promise<void> {
  const meta = entryAtOrAboveTakeProfitMeta(filledPxLike, ui, strategyIdLike);
  if (!meta) return;
  const shares = Number(sharesLike);
  const safeShares = Number.isFinite(shares) && shares > 0 ? Number(shares) : 0;
  const msg =
    `[ENTRY TP GUARD] invalid live fill context=${context} side=${side} ` +
    `entryPx=${roundTo6(meta.entryPx)} tpPx=${roundTo6(meta.tpPx)} shares=${roundTo6(safeShares)}`;
  console.error(msg);
  broadcast({ type: "status", t: nowMs(), status: msg });
  if (safeShares > 1e-9) {
    try {
      const snapshot = {
        side,
        shares: safeShares,
        entryPx: meta.entryPx,
        positionTokenId: tokenId,
      } as TradeState;
      await executeLiveVerifiedMarketExit(side, safeShares, ui, snapshot, `${context}_entry_at_or_above_tp`);
    } catch (flattenErr: any) {
      const flattenMsg =
        `[ENTRY TP GUARD] flatten failed context=${context} side=${side} ` +
        `err=${String(flattenErr?.message ?? flattenErr)}`;
      console.error(flattenMsg);
      broadcast({ type: "status", t: nowMs(), status: flattenMsg });
    }
  }
  throw new Error(msg);
}

