function isSinglePartialExitTypeRaw(v: any): boolean {
  const s = String(v || "").trim().toUpperCase();
  return s.includes("PARTIAL");
}
function isInflectionPositiveIterationStrategy(strategyIdRaw: any): boolean {
  return String(strategyIdRaw || "").trim().toLowerCase() === "inflection_positive_iteration";
}
const INFLECTION_POSITIVE_ITERATION_PARTIAL_QTY_PCT = 0.20;
const INFLECTION_POSITIVE_ITERATION_PARTIAL_TARGET_PCT = 27;
const INFLECTION_POSITIVE_ITERATION_RUNNER_TP_PX = 0.98;
const PAPER_TP_TOUCH_FILL_EPSILON = 0.0005;
const SINGLE_PARTIAL_EXIT_QTY_PCT = 0.20;
function resolveRequestedExitShares(
  currentSharesRaw: number,
  requestedSharesRaw: number,
  qtyPctRaw: number,
  exitTypeRaw?: any
): number {
  const currentShares = Math.max(0, Number(currentSharesRaw || 0));
  if (!(currentShares > 1e-9)) return 0;
  let requestedShares = currentShares;
  if (Number.isFinite(Number(requestedSharesRaw)) && Number(requestedSharesRaw) > 0) {
    requestedShares = Math.min(currentShares, Number(requestedSharesRaw));
  } else if (Number.isFinite(Number(qtyPctRaw)) && Number(qtyPctRaw) > 0) {
    requestedShares = Math.min(currentShares, currentShares * Math.min(1, Number(qtyPctRaw)));
  }
  if (isSinglePartialExitTypeRaw(exitTypeRaw)) {
    const partialCapShares = floorTo6(Math.max(0, currentShares * SINGLE_PARTIAL_EXIT_QTY_PCT));
    if (!(partialCapShares > 1e-9)) return 0;
    requestedShares = Math.min(requestedShares, partialCapShares);
    if (!(requestedShares > 1e-9)) requestedShares = partialCapShares;
  }
  return floorTo6(Math.max(0, Math.min(currentShares, requestedShares)));
}

function paperLimitTouched(sideBidRaw: any, limitPxRaw: any): boolean {
  const sideBid = Number(sideBidRaw);
  const limitPx = Number(limitPxRaw);
  if (!(Number.isFinite(sideBid) && Number.isFinite(limitPx))) return false;
  return sideBid + PAPER_TP_TOUCH_FILL_EPSILON >= limitPx;
}
function paperSinglePartialCompletedForCurrentPosition(st: TradeState, side?: OutcomeSide | null): boolean {
  return (
    !!side &&
    String(st.paperPartialCompletedSessionSlug || "") === String(current.slug || "") &&
    String(st.paperPartialCompletedSide || "").toUpperCase() === String(side || "").toUpperCase() &&
    Number.isFinite(Number(st.paperPartialCompletedEntryTsMs)) &&
    Number.isFinite(Number(st.entryTsMs)) &&
    Math.abs(Number(st.paperPartialCompletedEntryTsMs) - Number(st.entryTsMs)) <= 1
  );
}
function markPaperSinglePartialCompleted(st: TradeState, side?: OutcomeSide | null): void {
  if (!(side === "UP" || side === "DOWN")) return;
  st.paperPartialCompletedSessionSlug = String(current.slug || "");
  st.paperPartialCompletedSide = side;
  st.paperPartialCompletedEntryTsMs = Number(st.entryTsMs ?? nowMs());
}
function resetPaperDeriskExecutionState(st: TradeState) {
  st.paperDeriskCompletedSessionSlug = null;
  st.paperDeriskCompletedSide = null;
  st.paperDeriskCompletedEntryTsMs = null;
  st.paperPartialCompletedSessionSlug = null;
  st.paperPartialCompletedSide = null;
  st.paperPartialCompletedEntryTsMs = null;
  st.pendingTpArmedPositionShares = null;
  st.pendingTpFillLockId = null;
}
function clearPendingStop(st: TradeState) {
  st.pendingStopLimitPx = null;
  st.pendingStopPlacedAtMs = null;
  st.pendingStopExpiresAtMs = null;
  st.pendingStopShares = null;
  st.pendingStopOrderId = null;
}

function markEntrySignalLatency(
  st: TradeState,
  engine: Engine,
  side: OutcomeSide,
  lane: StrategyLane | null,
  source: string,
  signalPx: number | null,
  signalTsMsOverride?: number | null
) {
  const ctx = ((st as any).__entryLatencyCtx && typeof (st as any).__entryLatencyCtx === "object")
    ? (st as any).__entryLatencyCtx
    : {};
  if (Number.isFinite(Number(signalTsMsOverride)) && Number(signalTsMsOverride) > 0) {
    ctx.signalTsMs = Number(signalTsMsOverride);
  } else if (!Number.isFinite(Number(ctx.signalTsMs))) {
    ctx.signalTsMs = nowMs();
  }
  ctx.engine = engine;
  ctx.side = side;
  ctx.lane = lane || null;
  ctx.source = String(source || "entry");
  ctx.signalPx = Number.isFinite(Number(signalPx)) ? Number(signalPx) : null;
  (st as any).__entryLatencyCtx = ctx;
}

function markEntrySubmitLatency(st: TradeState, submitTsMsOverride?: number | null) {
  const ctx = ((st as any).__entryLatencyCtx && typeof (st as any).__entryLatencyCtx === "object")
    ? (st as any).__entryLatencyCtx
    : {};
  if (!Number.isFinite(Number(ctx.signalTsMs))) ctx.signalTsMs = nowMs();
  ctx.submitTsMs =
    Number.isFinite(Number(submitTsMsOverride)) && Number(submitTsMsOverride) > 0
      ? Number(submitTsMsOverride)
      : nowMs();
  (st as any).__entryLatencyCtx = ctx;
}

function getCurrentEntryQuoteFreshness(): {
  fresh: boolean;
  pairAgeMs: number | null;
  upBid: number | null;
  downBid: number | null;
} {
  const upToken = String(current?.upToken || "").trim();
  const downToken = String(current?.downToken || "").trim();
  if (!upToken || !downToken) {
    return { fresh: false, pairAgeMs: null, upBid: null, downBid: null };
  }
  const pairFresh = getCachedQuotePair(upToken, downToken, QUOTE_MAX_STALE_MS);
  const pairAny = pairFresh || getCachedQuotePair(upToken, downToken, Number.POSITIVE_INFINITY);
  const pairAgeMsRaw =
    Number.isFinite(Number(pairAny?.tsMs)) && Number(pairAny?.tsMs) > 0
      ? Math.max(0, nowMs() - Number(pairAny?.tsMs))
      : null;
  const lastGoodAgeMs =
    Number.isFinite(Number(lastGoodObservedBids.tsMs)) && Number(lastGoodObservedBids.tsMs) > 0
      ? Math.max(0, nowMs() - Number(lastGoodObservedBids.tsMs))
      : null;
  const canHoldLastGood =
    Number.isFinite(Number(lastGoodAgeMs)) &&
    Number(lastGoodAgeMs) <= QUOTE_HOLD_LAST_GOOD_MS &&
    Number.isFinite(Number(lastGoodObservedBids.upBid)) &&
    Number.isFinite(Number(lastGoodObservedBids.downBid));
  if (!!pairFresh && Number.isFinite(Number(pairFresh?.upBid)) && Number.isFinite(Number(pairFresh?.downBid))) {
    return {
      fresh: true,
      pairAgeMs: pairAgeMsRaw,
      upBid: Number(pairFresh.upBid),
      downBid: Number(pairFresh.downBid),
    };
  }
  if (canHoldLastGood) {
    return {
      // Keep entry eligibility aligned with the main loop's held-good quote path.
      fresh: true,
      pairAgeMs: Number(lastGoodAgeMs),
      upBid: Number(lastGoodObservedBids.upBid),
      downBid: Number(lastGoodObservedBids.downBid),
    };
  }
  return {
    fresh: false,
    pairAgeMs: pairAgeMsRaw,
    upBid: Number.isFinite(Number(pairAny?.upBid)) ? Number(pairAny?.upBid) : null,
    downBid: Number.isFinite(Number(pairAny?.downBid)) ? Number(pairAny?.downBid) : null,
  };
}

async function refreshCurrentEntryQuoteFreshness(maxAttempts = ENTRY_STALE_RETRY_ATTEMPTS): Promise<{
  fresh: boolean;
  pairAgeMs: number | null;
  upBid: number | null;
  downBid: number | null;
  retryCount: number;
}> {
  let freshness = getCurrentEntryQuoteFreshness();
  let retryCount = 0;
  if (freshness.fresh || !(maxAttempts > 0)) {
    return { ...freshness, retryCount };
  }
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    retryCount = attempt;
    await quotePumpTick();
    freshness = getCurrentEntryQuoteFreshness();
    if (freshness.fresh) break;
    const lagForFallback =
      Number.isFinite(Number(freshness.pairAgeMs))
        ? Math.max(Number(freshness.pairAgeMs), QUOTE_FALLBACK_TRIGGER_MS + 1)
        : (QUOTE_FALLBACK_TRIGGER_MS + 1);
    await triggerQuoteFallbackIfLagged(lagForFallback, `entry_stale_retry:${attempt}`);
    if (ENTRY_STALE_RETRY_SLEEP_MS > 0) {
      await sleep(ENTRY_STALE_RETRY_SLEEP_MS);
    }
    freshness = getCurrentEntryQuoteFreshness();
    if (freshness.fresh) break;
  }
  return { ...freshness, retryCount };
}

function getCurrentEntryQuoteFreshnessNonBlocking(reason = "entry_stale_async"): {
  fresh: boolean;
  pairAgeMs: number | null;
  upBid: number | null;
  downBid: number | null;
  retryCount: number;
} {
  const freshness = getCurrentEntryQuoteFreshness();
  if (freshness.fresh) {
    return { ...freshness, retryCount: 0 };
  }
  void quotePumpTick();
  const lagForFallback =
    Number.isFinite(Number(freshness.pairAgeMs))
      ? Math.max(Number(freshness.pairAgeMs), QUOTE_FALLBACK_TRIGGER_MS + 1)
      : (QUOTE_FALLBACK_TRIGGER_MS + 1);
  void triggerQuoteFallbackIfLagged(lagForFallback, reason);
  return { ...freshness, retryCount: 0 };
}

function finalizeEntryLatency(st: TradeState, fillTsMs?: number | null, detail?: Record<string, any>) {
  const ctx = ((st as any).__entryLatencyCtx && typeof (st as any).__entryLatencyCtx === "object")
    ? (st as any).__entryLatencyCtx
    : null;
  if (!ctx) return;
  const signalTsMs = Number(ctx.signalTsMs);
  const submitTsMs = Number(ctx.submitTsMs);
  const resolvedFillTs = Number.isFinite(Number(fillTsMs)) ? Number(fillTsMs) : nowMs();
  const sideRaw = String(ctx.side || "").toUpperCase();
  const side = sideRaw === "UP" || sideRaw === "DOWN" ? (sideRaw as OutcomeSide) : null;
  const laneRaw = String(ctx.lane || "").toUpperCase();
  const lane = laneRaw === "BASE" || laneRaw === "NO_CROSS_WINNER" ? (laneRaw as StrategyLane) : null;
  const engineRaw = String(ctx.engine || "").toLowerCase();
  const engine: Engine = engineRaw === "live" ? "live" : "paper";
  const localDetail = { ...(detail || {}), clockDomain: "local_observed" };
  const venueSignalTsMs = toFiniteOrNull((detail as any)?.venueSignalTsMs ?? (detail as any)?.marketTsMs ?? null);
  const venueFillTsMs = toFiniteOrNull((detail as any)?.venueFillTsMs ?? (detail as any)?.actualFillTsMs ?? null);
  if (Number.isFinite(signalTsMs) && Number.isFinite(submitTsMs) && submitTsMs >= signalTsMs) {
    recordLatencySample(engine, "entry_signal_to_submit", submitTsMs - signalTsMs, localDetail, side, lane);
  }
  if (Number.isFinite(submitTsMs) && resolvedFillTs >= submitTsMs) {
    recordLatencySample(engine, "entry_submit_to_fill", resolvedFillTs - submitTsMs, localDetail, side, lane);
  }
  if (Number.isFinite(signalTsMs) && resolvedFillTs >= signalTsMs) {
    recordLatencySample(engine, "entry_signal_to_observed_fill", resolvedFillTs - signalTsMs, localDetail, side, lane);
  }
  if (
    Number.isFinite(Number(venueSignalTsMs)) &&
    Number.isFinite(Number(venueFillTsMs)) &&
    Number(venueFillTsMs) >= Number(venueSignalTsMs)
  ) {
    recordLatencySample(
      engine,
      "entry_signal_to_fill",
      Number(venueFillTsMs) - Number(venueSignalTsMs),
      { ...(detail || {}), clockDomain: "venue" },
      side,
      lane
    );
  } else if (Number.isFinite(signalTsMs) && resolvedFillTs >= signalTsMs) {
    recordLatencySample(engine, "entry_signal_to_fill", resolvedFillTs - signalTsMs, localDetail, side, lane);
  }
  delete (st as any).__entryLatencyCtx;
}

function clearEntryLatency(st: TradeState) {
  delete (st as any).__entryLatencyCtx;
}

