function finalizeExitLatency(st: TradeState, fillTsMs?: number | null, detail?: Record<string, any>) {
  const ctx = ((st as any).__exitLatencyCtx && typeof (st as any).__exitLatencyCtx === "object")
    ? (st as any).__exitLatencyCtx
    : null;
  if (!ctx) return;
  const signalTsMs = Number(ctx.signalTsMs);
  const submitTsMs = Number(ctx.submitTsMs);
  const resolvedFillTs = Number.isFinite(Number(fillTsMs)) ? Number(fillTsMs) : nowMs();
  const sideRaw = String(ctx.side || "").toUpperCase();
  const side = sideRaw === "UP" || sideRaw === "DOWN" ? (sideRaw as OutcomeSide) : null;
  const laneRaw = String(ctx.lane || "").toUpperCase();
  const lane = laneRaw === "BASE" || laneRaw === "NO_CROSS_WINNER" ? (laneRaw as StrategyLane) : null;
  const engineRaw = String(ctx.engine || "").toLowerCase();
  const engine: Engine = engineRaw === "live" ? "live" : "paper";
  const exitType = String(ctx.exitType || "EXIT").toUpperCase();
  const metricPrefix = exitType.includes("STOP") ? "stop" : "exit";
  const localDetail = { ...(detail || {}), clockDomain: "local_observed" };
  const venueSignalTsMs = toFiniteOrNull((detail as any)?.venueSignalTsMs ?? (detail as any)?.marketTsMs ?? null);
  const venueFillTsMs = toFiniteOrNull((detail as any)?.venueFillTsMs ?? (detail as any)?.actualFillTsMs ?? null);
  if (Number.isFinite(signalTsMs) && Number.isFinite(submitTsMs) && submitTsMs >= signalTsMs) {
    recordLatencySample(engine, `${metricPrefix}_signal_to_submit`, submitTsMs - signalTsMs, localDetail, side, lane);
  }
  if (Number.isFinite(submitTsMs) && resolvedFillTs >= submitTsMs) {
    recordLatencySample(engine, `${metricPrefix}_submit_to_fill`, resolvedFillTs - submitTsMs, localDetail, side, lane);
  }
  if (Number.isFinite(signalTsMs) && resolvedFillTs >= signalTsMs) {
    recordLatencySample(engine, `${metricPrefix}_signal_to_observed_fill`, resolvedFillTs - signalTsMs, localDetail, side, lane);
  }
  if (
    Number.isFinite(Number(venueSignalTsMs)) &&
    Number.isFinite(Number(venueFillTsMs)) &&
    Number(venueFillTsMs) >= Number(venueSignalTsMs)
  ) {
    recordLatencySample(
      engine,
      `${metricPrefix}_signal_to_fill`,
      Number(venueFillTsMs) - Number(venueSignalTsMs),
      { ...(detail || {}), clockDomain: "venue" },
      side,
      lane
    );
  } else if (Number.isFinite(signalTsMs) && resolvedFillTs >= signalTsMs) {
    recordLatencySample(engine, `${metricPrefix}_signal_to_fill`, resolvedFillTs - signalTsMs, localDetail, side, lane);
  }
  delete (st as any).__exitLatencyCtx;
}

