function quoteStreamFreshAgeMsNow(): number | null {
  if (Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0) {
    return Math.max(0, nowMs() - Number(quoteStreamLastPriceMsgMs));
  }
  if (Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0) {
    return Math.max(0, nowMs() - Number(quoteStreamLastMsgMs));
  }
  return null;
}

function currentQuoteLagSnapshotAt(atTsMs: number): QuoteLagTimelineRow {
  const upLagMs = current?.upToken ? quoteAgeMs(String(current.upToken)) : null;
  const downLagMs = current?.downToken ? quoteAgeMs(String(current.downToken)) : null;
  const pairLagMs =
    quotePairCache &&
    String(quotePairCache.upToken) === String(current?.upToken || "") &&
    String(quotePairCache.downToken) === String(current?.downToken || "")
      ? Math.max(0, atTsMs - Number(quotePairCache.tsMs || 0))
      : null;
  const streamLastMsgAgeMs =
    Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
      ? Math.max(0, atTsMs - Number(quoteStreamLastMsgMs))
      : null;
  const streamLastPriceMsgAgeMs =
    Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
      ? Math.max(0, atTsMs - Number(quoteStreamLastPriceMsgMs))
      : null;
  return {
    tsMs: atTsMs,
    upLagMs: Number.isFinite(Number(upLagMs)) ? Number(upLagMs) : null,
    downLagMs: Number.isFinite(Number(downLagMs)) ? Number(downLagMs) : null,
    pairLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null,
    streamLastMsgAgeMs: Number.isFinite(Number(streamLastMsgAgeMs)) ? Number(streamLastMsgAgeMs) : null,
    streamLastPriceMsgAgeMs: Number.isFinite(Number(streamLastPriceMsgAgeMs)) ? Number(streamLastPriceMsgAgeMs) : null,
    fallbackTriggered: Number.isFinite(Number(quoteFallbackTriggerCount)) ? Number(quoteFallbackTriggerCount) : null,
    streamReconnectCount: Number.isFinite(Number(quoteStreamReconnectCount)) ? Number(quoteStreamReconnectCount) : null,
    healTriggerCount: Number.isFinite(Number(quoteKpiHealTriggerCount)) ? Number(quoteKpiHealTriggerCount) : null,
    broadcastGapMsLatest: Number.isFinite(Number(quoteBroadcastGapMsLatest)) ? Number(quoteBroadcastGapMsLatest) : null,
    broadcastGapMsMax: Number.isFinite(Number(quoteBroadcastGapMsMax)) ? Number(quoteBroadcastGapMsMax) : null,
    gapViolationStreak: Number.isFinite(Number(quoteBroadcastGapViolationStreak)) ? Number(quoteBroadcastGapViolationStreak) : null,
    gapViolationCount: Number.isFinite(Number(quoteBroadcastGapViolationCount)) ? Number(quoteBroadcastGapViolationCount) : null,
  };
}

function sampleQuoteLagTimeline(tsMs = nowMs()) {
  if (
    Number.isFinite(Number(quoteLagTimelineLastSampleMs)) &&
    Number(quoteLagTimelineLastSampleMs) > 0 &&
    (tsMs - Number(quoteLagTimelineLastSampleMs)) < QUOTE_LAG_TIMELINE_SAMPLE_MIN_MS
  ) {
    return;
  }
  quoteLagTimelineLastSampleMs = tsMs;
  quoteLagTimeline.push(currentQuoteLagSnapshotAt(tsMs));
  const cutoff = tsMs - QUOTE_LAG_TIMELINE_RETENTION_MS;
  while (quoteLagTimeline.length > 1 && Number(quoteLagTimeline[0]?.tsMs || 0) < cutoff) {
    quoteLagTimeline.shift();
  }
}

function summarizeFiniteSeries(vals: Array<number | null | undefined>) {
  const xs = vals.map((v) => Number(v)).filter((v) => Number.isFinite(v));
  if (!xs.length) return { count: 0, minMs: null, maxMs: null, avgMs: null };
  const sum = xs.reduce((acc, v) => acc + v, 0);
  return {
    count: xs.length,
    minMs: Math.min(...xs),
    maxMs: Math.max(...xs),
    avgMs: sum / xs.length,
  };
}

function buildEntryLagWindowSnapshot(centerTsMs: number, radiusMs: number) {
  const startMs = Math.max(0, centerTsMs - radiusMs);
  const endMs = centerTsMs + radiusMs;
  const rows = quoteLagTimeline.filter((row) => row.tsMs >= startMs && row.tsMs <= endMs);
  const atEvent = (() => {
    const candidates = rows.filter((row) => row.tsMs <= centerTsMs);
    return candidates.length ? candidates[candidates.length - 1] : null;
  })();
  return {
    centerTsMs,
    radiusMs,
    windowStartMs: startMs,
    windowEndMs: endMs,
    sampleCount: rows.length,
    atEvent,
    before: {
      pairLag: summarizeFiniteSeries(rows.filter((r) => r.tsMs <= centerTsMs).map((r) => r.pairLagMs)),
      streamLastMsgAge: summarizeFiniteSeries(rows.filter((r) => r.tsMs <= centerTsMs).map((r) => r.streamLastMsgAgeMs)),
      streamLastPriceMsgAge: summarizeFiniteSeries(rows.filter((r) => r.tsMs <= centerTsMs).map((r) => r.streamLastPriceMsgAgeMs)),
    },
    after: {
      pairLag: summarizeFiniteSeries(rows.filter((r) => r.tsMs >= centerTsMs).map((r) => r.pairLagMs)),
      streamLastMsgAge: summarizeFiniteSeries(rows.filter((r) => r.tsMs >= centerTsMs).map((r) => r.streamLastMsgAgeMs)),
      streamLastPriceMsgAge: summarizeFiniteSeries(rows.filter((r) => r.tsMs >= centerTsMs).map((r) => r.streamLastPriceMsgAgeMs)),
    },
    samples: rows,
  };
}

function entryLagWindowRadiusMsForStrategy(strategyIdLike: string | null | undefined) {
  const id = String(strategyIdLike || "").trim().toLowerCase();
  if (id === "inflection_positive_slope_200_750") return 1500;
  return 1500;
}

function isQuoteStreamHealthyForPairUse(streamAgeMsRaw?: any): boolean {
  const streamAgeMs =
    Number.isFinite(Number(streamAgeMsRaw))
      ? Number(streamAgeMsRaw)
      : quoteStreamFreshAgeMsNow();
  return (
    QUOTE_STREAM_ENABLED &&
    quoteStreamConnected &&
    Number.isFinite(Number(streamAgeMs)) &&
    Number(streamAgeMs) <= QUOTE_STREAM_HEALTHY_MAX_AGE_MS
  );
}
