async function getCanonicalParityState(): Promise<CanonicalParityStateRow | null> {
  if (!PARITY_CANONICAL_ENABLED) return null;
  const now = nowMs();
  if (
    canonicalParityStateCache &&
    Number.isFinite(Number(canonicalParityStateCache.fetchedAtMs)) &&
    (now - Number(canonicalParityStateCache.fetchedAtMs)) <= PARITY_CANONICAL_CACHE_MS
  ) {
    return canonicalParityStateCache;
  }
  if (canonicalParityStateFetchInFlight) return canonicalParityStateFetchInFlight;
  canonicalParityStateFetchInFlight = (async () => {
    try {
      const botsPayload = await getJsonWithTimeout(
        `http://127.0.0.1:${PARITY_CANONICAL_SOURCE_PORT}/api/v2/bots`,
        undefined,
        PARITY_CANONICAL_TIMEOUT_MS
      );
      const canonicalBot = Array.isArray(botsPayload?.items)
        ? botsPayload.items.find((item: any) => {
            const runtime = item?.runtime || {};
            return (
              String(item?.status || "").trim().toLowerCase() === "running" &&
              Number.isFinite(Number(runtime?.upBid)) &&
              Number.isFinite(Number(runtime?.downBid)) &&
              String(item?.marketSlug || "").trim().length > 0
            );
          }) || null
        : null;
      if (canonicalBot) {
        const runtime = canonicalBot.runtime || {};
        const row: CanonicalParityStateRow = {
          slug: String(canonicalBot?.marketSlug || "").trim() || null,
          startMs: Number.isFinite(Number(runtime?.marketStartMs)) ? Number(runtime.marketStartMs) : null,
          endMs: Number.isFinite(Number(runtime?.marketEndMs)) ? Number(runtime.marketEndMs) : null,
          upBid: Number(runtime.upBid),
          downBid: Number(runtime.downBid),
          upstreamTsMs: Number.isFinite(Number(runtime?.lastTickMs)) ? Number(runtime.lastTickMs) : null,
          fetchedAtMs: nowMs(),
          sourcePort: PARITY_CANONICAL_SOURCE_PORT,
        };
        canonicalParityStateCache = row;
        return row;
      }
      const payload = await getJsonWithTimeout(
        `http://127.0.0.1:${PARITY_CANONICAL_SOURCE_PORT}/api/state`,
        undefined,
        PARITY_CANONICAL_TIMEOUT_MS
      );
      const row: CanonicalParityStateRow = {
        slug: String(payload?.current?.slug || "").trim() || null,
        startMs: Number.isFinite(Number(payload?.current?.startMs)) ? Number(payload.current.startMs) : null,
        endMs: Number.isFinite(Number(payload?.current?.endMs)) ? Number(payload.current.endMs) : null,
        upBid: Number.isFinite(Number(payload?.up?.bid)) ? Number(payload.up.bid) : null,
        downBid: Number.isFinite(Number(payload?.down?.bid)) ? Number(payload.down.bid) : null,
        upstreamTsMs: Number.isFinite(Number(payload?.t)) ? Number(payload.t) : null,
        fetchedAtMs: nowMs(),
        sourcePort: PARITY_CANONICAL_SOURCE_PORT,
      };
      canonicalParityStateCache = row;
      return row;
    } catch (e: any) {
      console.warn(`[PARITY CANONICAL FETCH FAIL] port=${PARITY_CANONICAL_SOURCE_PORT} err=${String(e?.message ?? e)}`);
      return canonicalParityStateCache;
    } finally {
      canonicalParityStateFetchInFlight = null;
    }
  })();
  return canonicalParityStateFetchInFlight;
}

function shouldUseCanonicalParityForBot(instance: BotInstance): boolean {
  if (!PARITY_CANONICAL_ENABLED) return false;
  if (String(instance?.mode || "").trim().toLowerCase() !== "live") return false;
  const sid = String(instance?.strategyId || "").trim().toLowerCase();
  return sid === "momentum_hc_trade3";
}

function shouldUseAggressiveLiveMarketEntry(strategyIdLike?: string | null): boolean {
  const loadedStrategyId = normalizeStrategyId(
    String(
      strategyIdLike ||
      (strategyLive as any)?.STRATEGY_ID ||
      (strategyPaper as any)?.STRATEGY_ID ||
      ""
    )
  );
  return (
    loadedStrategyId === "momentum_hc_trade3" ||
    loadedStrategyId === "momentum_hc_trade3_latency" ||
    loadedStrategyId === "momentum_hc_trade3_100" ||
    loadedStrategyId === "momentum_hc_trade3_b" ||
    loadedStrategyId === "latency_touch_55_60" ||
    loadedStrategyId === "inflection_positive_slope" ||
    loadedStrategyId === "inflection_positive_slope_500_2000" ||
    loadedStrategyId === "inflection_positive_slope_200_750" ||
    loadedStrategyId === "inflection_positive_iteration"
  );
}

function shouldUseLatencyCriticalLivePath(strategyIdLike?: string | null): boolean {
  return (
    isLatencyProbeStrategy(strategyIdLike) ||
    isMhc3LatencyStrategy(strategyIdLike) ||
    isInflectionPositiveSlopeFamilyStrategy(strategyIdLike)
  );
}

function liveEntryAttemptCooldownMsForStrategy(strategyIdLike?: string | null): number {
  if (isLatencyProbeStrategy(strategyIdLike) || isMhc3LatencyStrategy(strategyIdLike)) return 250;
  if (isInflectionPositiveSlopeFamilyStrategy(strategyIdLike)) return 500;
  return 3000;
}

function liveMarketBuySubmitTimeoutMsForStrategy(strategyIdLike?: string | null): number {
  if (isInflectionPositiveSlopeFamilyStrategy(strategyIdLike)) return 7000;
  if (isLatencyProbeStrategy(strategyIdLike) || isMhc3LatencyStrategy(strategyIdLike)) return 9000;
  return 12000;
}

function requiresOrderTimelineLatency(strategyIdLike?: string | null): boolean {
  return isLatencyProbeStrategy(strategyIdLike);
}

function liveMarketOrderTypeForStrategy(strategyIdLike?: string | null): OrderType.FOK | OrderType.FAK {
  return shouldUseLatencyCriticalLivePath(strategyIdLike) ? LATENCY_MARKET_ORDER_TYPE : OrderType.FOK;
}

const EVENT_LOOP_MONITOR_INTERVAL_MS = Math.max(25, Number(process.env.EVENT_LOOP_MONITOR_INTERVAL_MS || 100));
let eventLoopMonitorStarted = false;
let mainLoopLastBeatMs = nowMs();
let mainLoopGapMsLatest = 0;
let mainLoopGapMsMax = 0;
let watchdogHealCount = 0;
let watchdogAlertCount = 0;
let watchdogLastHealMs = 0;
let watchdogLastReason: string | null = null;
const liveLatencyAlertLastWarnByMetric = new Map<string, number>();
const LIVE_LATENCY_ALERT_COOLDOWN_MS = 5000;

