const chronologyAlerts: ChronologyAlert[] = [];
const paperLiveParityExpectations: PaperLiveParityExpectation[] = [];
const paperLiveParityAlerts: PaperLiveParityAlert[] = [];
let chronologyViolationCount = 0;

function latencyMetricBucketKey(metric: string, engine: Engine): string {
  return `${engine}:${metric}`;
}

function pushLatencySample(sample: LatencySample) {
  liveLatencySamples.push(sample);
  if (liveLatencySamples.length > LIVE_LATENCY_SAMPLE_LIMIT) {
    liveLatencySamples.splice(0, liveLatencySamples.length - LIVE_LATENCY_SAMPLE_LIMIT);
  }
  const key = latencyMetricBucketKey(sample.metric, sample.engine);
  const bucket = liveLatencySamplesByMetricKey.get(key) || [];
  bucket.push(sample);
  if (bucket.length > LIVE_LATENCY_PER_METRIC_LIMIT) {
    bucket.splice(0, bucket.length - LIVE_LATENCY_PER_METRIC_LIMIT);
  }
  liveLatencySamplesByMetricKey.set(key, bucket);
}

function pushChronologyAlert(alert: ChronologyAlert) {
  chronologyAlerts.push(alert);
  if (chronologyAlerts.length > CHRONOLOGY_EVENT_LIMIT) {
    chronologyAlerts.splice(0, chronologyAlerts.length - CHRONOLOGY_EVENT_LIMIT);
  }
}

function pushPaperLiveParityAlert(alert: PaperLiveParityAlert) {
  paperLiveParityAlerts.push(alert);
  if (paperLiveParityAlerts.length > PAPER_LIVE_PARITY_ALERT_LIMIT) {
    paperLiveParityAlerts.splice(0, paperLiveParityAlerts.length - PAPER_LIVE_PARITY_ALERT_LIMIT);
  }
}

function paperLiveParityPhaseForAction(actionRaw: string): { phase: PaperLiveParityPhase | null; side: OutcomeSide | null } {
  const action = String(actionRaw || "").toUpperCase();
  const side =
    action.includes("_UP_") || action.endsWith("_UP") ? "UP"
    : action.includes("_DOWN_") || action.endsWith("_DOWN") ? "DOWN"
    : null;
  if (/^ENTER_(UP|DOWN)_(PAPER|LIVE)$/.test(action)) return { phase: "entry", side };
  if (/^STOP_(UP|DOWN)_(PAPER|LIVE)$/.test(action)) return { phase: "stop", side };
  return { phase: null, side: null };
}

function trackPaperLiveParity(payload: any): void {
  const engine = String(payload?.engine || "").trim().toLowerCase();
  if (engine !== "paper" && engine !== "live") return;
  const action = String(payload?.action || "").trim().toUpperCase();
  const slug = String(payload?.market?.slug || payload?.st?.marketSlug || "").trim();
  const t = Number(payload?.t);
  const { phase, side } = paperLiveParityPhaseForAction(action);
  const blockedSide =
    action.includes("_UP_") || action.endsWith("_UP") ? "UP"
    : action.includes("_DOWN_") || action.endsWith("_DOWN") ? "DOWN"
    : null;
  const blockedPhase =
    /^ENTER_BLOCKED_(UP|DOWN)_LIVE$/.test(action) ? "entry"
    : /^STOP_BLOCKED_(UP|DOWN)_LIVE$/.test(action) ? "stop"
    : null;
  if (blockedPhase && blockedSide && slug && Number.isFinite(t)) {
    const pending = paperLiveParityExpectations.find(
      (x) => !x.matched && !x.alerted && x.key === `${blockedPhase}|${slug}|${blockedSide}`
    );
    if (pending) {
      pending.blockedCode = String(
        payload?.execution?.entryBlockCode ||
        payload?.execution?.stopBlockCode ||
        payload?.execution?.entryBlockReason ||
        payload?.execution?.stopReason ||
        "UNKNOWN"
      );
      pending.blockedAtMs = t;
    }
    return;
  }

  if (!phase || !side || !slug || !Number.isFinite(t)) return;

  const key = `${phase}|${slug}|${side}`;
  if (engine === "paper") {
    if (!uiLive.enabled) return;
    paperLiveParityExpectations.push({
      key,
      phase,
      slug,
      side,
      createdMs: t,
      timeoutMs: phase === "entry" ? PAPER_LIVE_ENTRY_MISS_TIMEOUT_MS : PAPER_LIVE_STOP_MISS_TIMEOUT_MS,
      paperAction: action,
      paperPx: toFiniteOrNull(payload?.execution?.actualPx ?? payload?.execution?.signalPx),
      matched: false,
      alerted: false,
      liveAction: null,
      liveMatchedMs: null,
      blockedCode: null,
      blockedAtMs: null,
    });
    if (paperLiveParityExpectations.length > PAPER_LIVE_PARITY_EVENT_LIMIT) {
      paperLiveParityExpectations.splice(0, paperLiveParityExpectations.length - PAPER_LIVE_PARITY_EVENT_LIMIT);
    }
    return;
  }

  if (engine !== "live") return;
  const pending = paperLiveParityExpectations.find((x) => !x.matched && !x.alerted && x.key === key);
  if (!pending) return;
  pending.matched = true;
  pending.liveAction = action;
  pending.liveMatchedMs = t;
}

function flushPaperLiveParityWatchdog(): void {
  if (!paperLiveParityExpectations.length) return;
  const now = nowMs();
  for (const item of paperLiveParityExpectations) {
    if (item.matched || item.alerted) continue;
    if (now - item.createdMs < item.timeoutMs) continue;
    item.alerted = true;
    const alert: PaperLiveParityAlert = {
      t: now,
      iso: isoNow(),
      phase: item.phase,
      slug: item.slug,
      side: item.side,
      reason: item.phase === "entry" ? "paper_entry_without_live_fill" : "paper_stop_without_live_fill",
      paperAction: item.paperAction,
      paperPx: item.paperPx,
      blockedCode: item.blockedCode,
      liveState: {
        enabled: !!uiLive.enabled,
        entered: !!stLive.entered,
        exited: !!stLive.exited,
        side: stLive.side ?? null,
        shares: Number.isFinite(Number(stLive.shares)) ? Number(stLive.shares) : null,
        enterInFlight: !!stLive.enterInFlight,
        exitInFlight: !!stLive.exitInFlight,
        tpOrderId: String(stLive.tpOrderId || "").trim() || null,
      },
    };
    pushPaperLiveParityAlert(alert);
    console.warn(
      `[PAPER/LIVE MISS] phase=${item.phase} slug=${item.slug} side=${item.side} ` +
      `blocked=${item.blockedCode ?? "-"} liveEntered=${stLive.entered} liveSide=${stLive.side ?? "-"} ` +
      `shares=${roundTo6(Number(stLive.shares ?? 0))}`
    );
    broadcast({
      type: "status",
      t: now,
      status:
        `PAPER_LIVE_MISS phase=${item.phase} slug=${item.slug} side=${item.side} ` +
        `blocked=${item.blockedCode ?? "-"} liveSide=${stLive.side ?? "-"} shares=${roundTo6(Number(stLive.shares ?? 0))}`,
    });
    if (item.phase === "stop") {
      void reconcileLivePositionMaybe(true, "paper_live_stop_miss_watchdog");
    }
  }

  for (let i = paperLiveParityExpectations.length - 1; i >= 0; i -= 1) {
    const item = paperLiveParityExpectations[i];
    const ageMs = now - Number(item.createdMs || 0);
    if (item.matched && ageMs > 30_000) {
      paperLiveParityExpectations.splice(i, 1);
      continue;
    }
    if (item.alerted && ageMs > 60_000) {
      paperLiveParityExpectations.splice(i, 1);
    }
  }
}

function triggerRuntimeSelfHeal(reason: string, meta?: Record<string, any>): void {
  const n = nowMs();
  if ((n - watchdogLastHealMs) < LATENCY_HEAL_COOLDOWN_MS) return;
  watchdogLastHealMs = n;
  watchdogHealCount += 1;
  watchdogLastReason = reason;
  const key = String(reason || "watchdog_heal");
  const last = Number(((triggerRuntimeSelfHeal as any).__lastWarnMs?.get(key) ?? 0));
  if (!Number.isFinite(last) || (n - last) >= 15000) {
    if (!(triggerRuntimeSelfHeal as any).__lastWarnMs) (triggerRuntimeSelfHeal as any).__lastWarnMs = new Map<string, number>();
    (triggerRuntimeSelfHeal as any).__lastWarnMs.set(key, n);
    console.warn(`[WATCHDOG HEAL] reason=${reason} count=${watchdogHealCount}`);
    if (meta && Object.keys(meta).length) {
      try {
        console.warn(`[WATCHDOG HEAL META] ${JSON.stringify(meta)}`);
      } catch {}
    }
  }
  void quotePumpTick();
  const pairLagNow = Number.isFinite(Number(quotePairCache?.tsMs))
    ? Math.max(0, n - Number(quotePairCache?.tsMs))
    : (QUOTE_FALLBACK_TRIGGER_MS + 1);
  const hasSeenStreamMsg =
    Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0;
  const wsState = quoteStreamWs ? Number(quoteStreamWs.readyState) : -1;
  const connectAgeMs =
    Number.isFinite(Number(quoteStreamConnectStartedMs)) && Number(quoteStreamConnectStartedMs) > 0
      ? Math.max(0, n - Number(quoteStreamConnectStartedMs))
      : Number.POSITIVE_INFINITY;
  const withinConnectGrace = wsState === WebSocket.CONNECTING && connectAgeMs <= QUOTE_STREAM_CONNECT_GRACE_MS;
  const streamAgeNow =
    Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
      ? Math.max(0, n - Number(quoteStreamLastPriceMsgMs))
      : (
        hasSeenStreamMsg
          ? Math.max(0, n - Number(quoteStreamLastMsgMs))
          : Number.POSITIVE_INFINITY
      );
  void triggerQuoteFallbackIfLagged(pairLagNow, `watchdog_heal:${reason}`);
  const reconnectReason = String(reason || "").toLowerCase();
  const actualStreamStale = hasSeenStreamMsg && Number.isFinite(streamAgeNow) && streamAgeNow >= QUOTE_STREAM_HARD_RECONNECT_MS;
  const actualPairStale = Number.isFinite(pairLagNow) && pairLagNow >= QUOTE_STREAM_HARD_RECONNECT_MS;
  const disconnectedAndUnhealthy = !quoteStreamConnected && (actualPairStale || (hasSeenStreamMsg && Number.isFinite(streamAgeNow)));
  const shouldReconnect =
    !withinConnectGrace && (
      (
        reconnectReason.includes("quote_feed") ||
        reconnectReason.includes("stream") ||
        reconnectReason.includes("socket") ||
        reconnectReason.includes("disconnect") ||
        reconnectReason.includes("stale")
      )
        ? (actualStreamStale || actualPairStale || disconnectedAndUnhealthy)
        : (actualStreamStale || actualPairStale)
    );
  if (shouldReconnect) {
    forceQuoteStreamReconnect(
      `watchdog_heal:${reason} pairLagMs=${Math.round(pairLagNow)} streamAgeMs=${Math.round(streamAgeNow)}`
    );
  }
  broadcast({
    type: "status",
    t: n,
    status: `WATCHDOG_HEAL reason=${reason} healCount=${watchdogHealCount}`,
  });
}

function recordLatencySample(
  engine: Engine,
  metric: string,
  latencyMsRaw: number,
  detail?: Record<string, any> | null,
  side?: OutcomeSide | null,
  lane?: StrategyLane | null
) {
  const latencyMs = Number(latencyMsRaw);
  if (!Number.isFinite(latencyMs) || latencyMs < 0) return;
  const t = nowMs();
  const sample: LatencySample = {
    t,
    iso: isoNow(),
    engine,
    metric,
    latencyMs,
    targetMs: LIVE_LATENCY_TARGET_MS,
    aboveTarget: latencyMs > LIVE_LATENCY_TARGET_MS,
    marketSlug: String(current?.slug || "") || null,
    side: side ?? null,
    lane: lane ?? null,
    runId: Number(SERVER_RUN_ID),
    detail: detail || null,
  };
  pushLatencySample(sample);
  if (engine !== "live") return;
  if (!uiLive.enabled && !hasActiveRealLiveExecutionBots()) return;
  if (sample.aboveTarget) {
    liveLatencyViolationStreak += 1;
    liveLatencyViolationCount += 1;
    watchdogAlertCount += 1;
    if (liveLatencyViolationStreak >= LIVE_LATENCY_ALERT_STREAK) {
      const alertKey = `${metric}`;
      const lastWarnMs = Number(liveLatencyAlertLastWarnByMetric.get(alertKey) || 0);
      if (!Number.isFinite(lastWarnMs) || (t - lastWarnMs) >= LIVE_LATENCY_ALERT_COOLDOWN_MS) {
        liveLatencyAlertLastWarnByMetric.set(alertKey, t);
        console.warn(
          `[LIVE LATENCY ALERT] metric=${metric} latencyMs=${Math.round(latencyMs)} ` +
          `targetMs=${LIVE_LATENCY_TARGET_MS} streak=${liveLatencyViolationStreak}`
        );
        broadcast({
          type: "status",
          t,
          status:
            `LIVE_LATENCY_ALERT metric=${metric} latencyMs=${Math.round(latencyMs)} ` +
            `targetMs=${LIVE_LATENCY_TARGET_MS} streak=${liveLatencyViolationStreak}`,
        });
      }
    }
    if (liveLatencyViolationStreak >= LIVE_LATENCY_UNHEALTHY_STREAK) {
      if (!Number.isFinite(Number(liveLatencyUnhealthySinceMs))) liveLatencyUnhealthySinceMs = t;
      triggerRuntimeSelfHeal(`live_latency_${metric}`, { latencyMs, streak: liveLatencyViolationStreak });
    }
  } else {
    liveLatencyViolationStreak = 0;
    liveLatencyUnhealthySinceMs = null;
  }
}

function updateMainLoopHeartbeat(tMs: number) {
  const n = Number(tMs);
  if (!Number.isFinite(n) || n <= 0) return;
  if (Number.isFinite(Number(mainLoopLastBeatMs)) && Number(mainLoopLastBeatMs) > 0) {
    const gap = Math.max(0, n - Number(mainLoopLastBeatMs));
    mainLoopGapMsLatest = gap;
    if (!Number.isFinite(Number(mainLoopGapMsMax)) || gap > Number(mainLoopGapMsMax)) {
      mainLoopGapMsMax = gap;
    }
  }
  mainLoopLastBeatMs = n;
}

function startEventLoopMonitor() {
  if (eventLoopMonitorStarted) return;
  eventLoopMonitorStarted = true;
  setInterval(() => {
    const n = nowMs();
    const lag = Math.max(0, n - eventLoopMonitorLastMs - EVENT_LOOP_MONITOR_INTERVAL_MS);
    eventLoopLagMsLatest = lag;
    if (!Number.isFinite(Number(eventLoopLagMsMax)) || lag > Number(eventLoopLagMsMax)) {
      eventLoopLagMsMax = lag;
    }
    eventLoopMonitorLastMs = n;
  }, EVENT_LOOP_MONITOR_INTERVAL_MS);
}

function parseStreamTsMs(v: any): number {
  if (typeof v === "number" && Number.isFinite(v)) {
    if (v > 1_000_000_000_000) return Math.floor(v);
    if (v > 1_000_000_000) return Math.floor(v * 1000);
  }
  if (typeof v === "string") {
    const n = Number(v);
    if (Number.isFinite(n)) return parseStreamTsMs(n);
    const t = Date.parse(v);
    if (Number.isFinite(t)) return Math.floor(t);
  }
  return nowMs();
}

function quoteAgeMs(tokenId: string): number | null {
  const row = quoteCacheByToken.get(String(tokenId || ""));
  if (!row || !Number.isFinite(Number(row.tsMs))) return null;
  if (Number(row.tsMs) <= 0) return null;
  return Math.max(0, nowMs() - Number(row.tsMs));
}

function getCachedBestBidAsk(tokenId: string, maxStaleMs: number): { bid: number | null; ask: number | null } | null {
  const row = quoteCacheByToken.get(String(tokenId || ""));
  if (!row) return null;
  const ageMs = quoteAgeMs(tokenId);
  if (!Number.isFinite(Number(ageMs))) return null;
  if (Number(ageMs) > maxStaleMs) return null;
  return { bid: row.bid, ask: row.ask };
}

function getCachedQuotePair(
  upToken: string,
  downToken: string,
  maxStaleMs: number
): {
  upBid: number;
  downBid: number;
  upAsk: number | null;
  downAsk: number | null;
  tsMs: number;
  source?: string | null;
  upstreamTsMs?: number | null;
  observedAtMs?: number | null;
  synthetic?: boolean;
  pure?: boolean;
  seq?: number | null;
} | null {
  const now = nowMs();
  if (
    quotePairCache &&
    String(quotePairCache.upToken) === String(upToken) &&
    String(quotePairCache.downToken) === String(downToken)
  ) {
    const ageMs = Math.max(0, now - Number(quotePairCache.tsMs || 0));
    if (Number.isFinite(ageMs) && ageMs <= maxStaleMs) {
      return {
        upBid: Number(quotePairCache.upBid),
        downBid: Number(quotePairCache.downBid),
        upAsk: Number.isFinite(Number(quotePairCache.upAsk)) ? Number(quotePairCache.upAsk) : null,
        downAsk: Number.isFinite(Number(quotePairCache.downAsk)) ? Number(quotePairCache.downAsk) : null,
        tsMs: Number(quotePairCache.tsMs),
        source: String(quotePairCache.source || "") || null,
        upstreamTsMs: Number.isFinite(Number(quotePairCache.upstreamTsMs)) ? Number(quotePairCache.upstreamTsMs) : null,
        observedAtMs: Number.isFinite(Number(quotePairCache.observedAtMs)) ? Number(quotePairCache.observedAtMs) : null,
        synthetic: !!quotePairCache.synthetic,
        pure: !!quotePairCache.pure,
        seq: Number.isFinite(Number(quotePairCache.seq)) ? Number(quotePairCache.seq) : null,
      };
    }
  }
  const upRow = quoteCacheByToken.get(String(upToken));
  const downRow = quoteCacheByToken.get(String(downToken));
  if (!upRow || !downRow) return null;
  const upBid = Number(upRow.bid);
  const downBid = Number(downRow.bid);
  if (!Number.isFinite(upBid) || !Number.isFinite(downBid)) return null;
  const upTs = Number(upRow.tsMs || 0);
  const downTs = Number(downRow.tsMs || 0);
  if (!Number.isFinite(upTs) || !Number.isFinite(downTs) || upTs <= 0 || downTs <= 0) return null;
  const upAge = Math.max(0, now - upTs);
  const downAge = Math.max(0, now - downTs);
  if (upAge > maxStaleMs || downAge > maxStaleMs) return null;
  const skewMs = Math.abs(upTs - downTs);
  if (skewMs > QUOTE_PAIR_SKEW_MAX_MS) return null;
  return {
    upBid: clamp01(upBid),
    downBid: clamp01(downBid),
    upAsk: Number.isFinite(Number(upRow.ask)) ? Number(upRow.ask) : null,
    downAsk: Number.isFinite(Number(downRow.ask)) ? Number(downRow.ask) : null,
    tsMs: Math.max(upTs, downTs),
    source:
      String(upRow.source || "") === "ws_direct" && String(downRow.source || "") === "ws_direct"
        ? "ws_direct"
        : "token_cache_mixed",
    upstreamTsMs:
      Number.isFinite(Number(upRow.upstreamTsMs)) || Number.isFinite(Number(downRow.upstreamTsMs))
        ? Math.max(Number(upRow.upstreamTsMs || 0), Number(downRow.upstreamTsMs || 0))
        : null,
    observedAtMs:
      Number.isFinite(Number(upRow.observedAtMs)) || Number.isFinite(Number(downRow.observedAtMs))
        ? Math.max(Number(upRow.observedAtMs || 0), Number(downRow.observedAtMs || 0))
        : null,
    synthetic: !(String(upRow.source || "") === "ws_direct" && String(downRow.source || "") === "ws_direct"),
    pure: String(upRow.source || "") === "ws_direct" && String(downRow.source || "") === "ws_direct",
    seq: null,
  };
}

function maybeUpdatePairCacheFromTokenRows(upToken: string, downToken: string): void {
  const upRow = quoteCacheByToken.get(String(upToken));
  const downRow = quoteCacheByToken.get(String(downToken));
  if (!upRow || !downRow) return;
  const upBid = Number(upRow.bid);
  const downBid = Number(downRow.bid);
  const upTs = Number(upRow.tsMs || 0);
  const downTs = Number(downRow.tsMs || 0);
  if (!Number.isFinite(upBid) || !Number.isFinite(downBid)) return;
  if (!Number.isFinite(upTs) || !Number.isFinite(downTs) || upTs <= 0 || downTs <= 0) return;
  if (Math.abs(upTs - downTs) > QUOTE_PAIR_SKEW_MAX_MS) return;
  const isPureWs =
    String(upRow.source || "") === "ws_direct" &&
    String(downRow.source || "") === "ws_direct";
  quotePairCache = {
    upToken: String(upToken),
    downToken: String(downToken),
    upBid: clamp01(upBid),
    downBid: clamp01(downBid),
    upAsk: Number.isFinite(Number(upRow.ask)) ? Number(upRow.ask) : null,
    downAsk: Number.isFinite(Number(downRow.ask)) ? Number(downRow.ask) : null,
    tsMs: Math.max(upTs, downTs),
    source: isPureWs ? "ws_direct" : "token_cache_mixed",
    upstreamTsMs:
      Number.isFinite(Number(upRow.upstreamTsMs)) || Number.isFinite(Number(downRow.upstreamTsMs))
        ? Math.max(Number(upRow.upstreamTsMs || 0), Number(downRow.upstreamTsMs || 0))
        : null,
    observedAtMs: nowMs(),
    synthetic: !isPureWs,
    pure: isPureWs,
    seq: ++quotePairSeq,
  };
  if (
    String(current?.slug || "").trim() &&
    String(current?.upToken || "") === String(upToken || "") &&
    String(current?.downToken || "") === String(downToken || "")
  ) {
    recordCanonicalQuoteSample(
      String(current.slug || ""),
      current?.startMs,
      quotePairCache.tsMs,
      clamp01(upBid),
      clamp01(downBid)
    );
  }
}

function cacheQuoteFromStream(tokenId: string, bid: number | null, ask: number | null, tsMsRaw: any): void {
  const token = String(tokenId || "");
  if (!token) return;
  const now = nowMs();
  const parsedTsMs = parseStreamTsMs(tsMsRaw);
  const prev = quoteCacheByToken.get(token);
  const prevTsMs = Number(prev?.tsMs || 0);
  let tsMs = Number.isFinite(parsedTsMs) && parsedTsMs > 0 ? parsedTsMs : now;
  // WS payload timestamps can be stale/out-of-order near session rollovers.
  // Normalize to wall-clock when timestamp drift is implausible.
  if (tsMs < (now - QUOTE_STREAM_TS_MAX_AGE_MS) || tsMs > (now + QUOTE_STREAM_TS_MAX_FUTURE_MS)) {
    tsMs = now;
  }
  // Monotonic per-token timestamp prevents lag spikes from retrograde messages.
  if (Number.isFinite(prevTsMs) && prevTsMs > 0 && tsMs < prevTsMs) {
    tsMs = Math.max(prevTsMs, now);
  }
  quoteCacheByToken.set(token, {
    bid: Number.isFinite(Number(bid)) ? clamp01(Number(bid)) : (prev?.bid ?? null),
    ask: Number.isFinite(Number(ask)) ? clamp01(Number(ask)) : (prev?.ask ?? null),
    tsMs,
    fetchMs: prev?.fetchMs ?? null,
    lastErrMs: null,
    lastErrMsg: null,
    source: "ws_direct",
    upstreamTsMs: Number.isFinite(parsedTsMs) && parsedTsMs > 0 ? parsedTsMs : tsMs,
    observedAtMs: now,
    synthetic: false,
  });
  if (current?.upToken && current?.downToken) {
    if (token === String(current.upToken) || token === String(current.downToken)) {
      quoteStreamLastPriceMsgMs = now;
    }
    maybeUpdatePairCacheFromTokenRows(String(current.upToken), String(current.downToken));
    if (
      quotePairCache &&
      String(quotePairCache.upToken || "") === String(current.upToken || "") &&
      String(quotePairCache.downToken || "") === String(current.downToken || "")
    ) {
      triggerRealtimeQuoteTriggeredBotTicks(quotePairCache, "quote_stream_pair");
    }
  }
}

function noteQuoteLagIfNeeded(sideLabel: "UP" | "DOWN", tokenId: string, ageMs: number | null, source: string) {
  if (source === "pump_skip_stream_healthy") return;
  if (!Number.isFinite(Number(ageMs))) return;
  const lag = Number(ageMs);
  if (lag <= QUOTE_MAX_STALE_MS) return;
  const key = `quote_lag:${sideLabel}:${tokenId}`;
  const now = nowMs();
  const last = Number(((noteQuoteLagIfNeeded as any).__lastWarnMs?.get(key) ?? 0));
  if (!Number.isFinite(last) || now - last >= QUOTE_LAG_WARN_COOLDOWN_MS) {
    if (!(noteQuoteLagIfNeeded as any).__lastWarnMs) (noteQuoteLagIfNeeded as any).__lastWarnMs = new Map<string, number>();
    (noteQuoteLagIfNeeded as any).__lastWarnMs.set(key, now);
    console.warn(`[QUOTE LAG] side=${sideLabel} lagMs=${Math.round(lag)} maxStaleMs=${QUOTE_MAX_STALE_MS} source=${source}`);
  }
}

function isQuoteTimeoutError(err: any): boolean {
  const name = String(err?.name || "").toLowerCase();
  const msg = String(err?.message || err || "").toLowerCase();
  return name === "aborterror" || msg.includes("timeout");
}

async function fetchAndCacheBestBidAsk(
  tokenId: string,
  sideLabel: "UP" | "DOWN",
  timeoutMs = QUOTE_FETCH_TIMEOUT_MS
): Promise<{ bid: number | null; ask: number | null }> {
  const started = nowMs();
  try {
    let book: any = null;
    try {
      book = await getJsonWithTimeout(`${CLOB_BASE}/book`, { token_id: tokenId }, timeoutMs);
    } catch (firstErr: any) {
      if (!isQuoteTimeoutError(firstErr)) throw firstErr;
      const retryTimeoutMs = Math.max(250, Math.floor(timeoutMs * 0.75));
      book = await getJsonWithTimeout(`${CLOB_BASE}/book`, { token_id: tokenId }, retryTimeoutMs);
    }
    const ba = bestBidAskFromBook(book);
    quoteCacheByToken.set(String(tokenId), {
      bid: ba.bid,
      ask: ba.ask,
      tsMs: nowMs(),
      fetchMs: Math.max(0, nowMs() - started),
      lastErrMs: null,
      lastErrMsg: null,
      source: "rest_book",
      upstreamTsMs: null,
      observedAtMs: nowMs(),
      synthetic: true,
    });
    return ba;
  } catch (e: any) {
    const prev = quoteCacheByToken.get(String(tokenId));
    quoteCacheByToken.set(String(tokenId), {
      bid: prev?.bid ?? null,
      ask: prev?.ask ?? null,
      tsMs: Number(prev?.tsMs ?? 0),
      fetchMs: prev?.fetchMs ?? null,
      lastErrMs: nowMs(),
      lastErrMsg: String(e?.message ?? e),
      source: prev?.source ?? null,
      upstreamTsMs: Number.isFinite(Number(prev?.upstreamTsMs)) ? Number(prev?.upstreamTsMs) : null,
      observedAtMs: Number.isFinite(Number(prev?.observedAtMs)) ? Number(prev?.observedAtMs) : null,
      synthetic: !!prev?.synthetic,
    });
    throw e;
  }
}

type FillEstimate = {
  wouldFill: boolean | null;
  scorePct: number | null;
  requiredShares: number | null;
  fillableShares: number | null;
  fillableNotionalUsd: number | null;
  estVwapPx: number | null;
};

type FillCapacityBand = {
  slipCents: number;
  priceLimit: number | null;
  fillableShares: number | null;
  fillableNotionalUsd: number | null;
  estVwapPx: number | null;
};

type FillCapacitySnapshot = {
  side: "buy" | "sell";
  targetPx: number | null;
  bestBid: number | null;
  bestAsk: number | null;
  bands: FillCapacityBand[];
};

const PAPER_FILL_CAP_TRACK_PORTS = new Set<number>([8790, 8791]);
const PAPER_FILL_CAP_SLIP_CENTS = [0, 1, 2, 3, 5];

function toFiniteNum(v: any): number | null {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function clampPct01(v: number): number {
  if (!Number.isFinite(v)) return 0;
  return Math.max(0, Math.min(1, v));
}

function shouldTrackPaperFillCapacity(engine: Engine): boolean {
  return engine === "paper" && PAPER_FILL_CAP_TRACK_PORTS.has(PORT);
}

function summarizeFillCapacityEstimate(est: any): any | null {
  if (!est || typeof est !== "object") return null;
  const bands = Array.isArray(est?.bands) ? est.bands : [];
  const pickBand = (slipCents: number) =>
    bands.find((b: any) => Number(b?.slipCents) === slipCents) || null;
  const mk = (band: any) => ({
    slipCents: Number.isFinite(Number(band?.slipCents)) ? Number(band.slipCents) : null,
    priceLimit: Number.isFinite(Number(band?.priceLimit)) ? Number(band.priceLimit) : null,
    fillableShares: Number.isFinite(Number(band?.fillableShares)) ? Number(band.fillableShares) : null,
    fillableNotionalUsd: Number.isFinite(Number(band?.fillableNotionalUsd)) ? Number(band.fillableNotionalUsd) : null,
    estVwapPx: Number.isFinite(Number(band?.estVwapPx)) ? Number(band.estVwapPx) : null,
  });
  return {
    side: String(est?.side || "").trim().toLowerCase() || null,
    targetPx: Number.isFinite(Number(est?.targetPx)) ? Number(est.targetPx) : null,
    bestBid: Number.isFinite(Number(est?.bestBid)) ? Number(est.bestBid) : null,
    bestAsk: Number.isFinite(Number(est?.bestAsk)) ? Number(est.bestAsk) : null,
    atTarget: mk(pickBand(0)),
    plus1c: mk(pickBand(1)),
    plus2c: mk(pickBand(2)),
    plus3c: mk(pickBand(3)),
    plus5c: mk(pickBand(5)),
  };
}

function normalizeBookLevels(
  book: any,
  side: "buy" | "sell"
): Array<{ px: number; sz: number }> {
  const rows = side === "buy"
    ? (Array.isArray(book?.asks) ? book.asks : [])
    : (Array.isArray(book?.bids) ? book.bids : []);
  return rows
    .map((row: any) => ({
      px: toFiniteNum(row?.price),
      sz: toFiniteNum(row?.size ?? row?.quantity ?? row?.amount),
    }))
    .filter((r: any) => Number.isFinite(r.px) && Number.isFinite(r.sz) && r.sz > 0)
    .sort((a: any, b: any) => side === "buy" ? Number(a.px) - Number(b.px) : Number(b.px) - Number(a.px));
}

function summarizeFillCapacityBand(
  levels: Array<{ px: number; sz: number }>,
  side: "buy" | "sell",
  targetPx: number,
  slipCents: number
): FillCapacityBand {
  const priceLimit = side === "buy"
    ? clamp01(targetPx + slipCents / 100)
    : clamp01(targetPx - slipCents / 100);
  const eligible = levels.filter((lvl) => side === "buy" ? lvl.px <= priceLimit : lvl.px >= priceLimit);
  let fillableShares = 0;
  let fillableNotionalUsd = 0;
  for (const lvl of eligible) {
    fillableShares += Number(lvl.sz);
    fillableNotionalUsd += Number(lvl.sz) * Number(lvl.px);
  }
  return {
    slipCents,
    priceLimit,
    fillableShares: fillableShares > 0 ? fillableShares : 0,
    fillableNotionalUsd: fillableNotionalUsd > 0 ? fillableNotionalUsd : 0,
    estVwapPx: fillableShares > 0 ? (fillableNotionalUsd / fillableShares) : null,
  };
}

async function estimateFillCapacitySnapshot(
  tokenId: string,
  side: "buy" | "sell",
  targetPx: number
): Promise<FillCapacitySnapshot | null> {
  const px = toFiniteNum(targetPx);
  if (!Number.isFinite(px) || px <= 0) return null;
  try {
    const book = await getBook(tokenId);
    const levels = normalizeBookLevels(book, side);
    const ba = bestBidAskFromBook(book);
    return {
      side,
      targetPx: px,
      bestBid: toFiniteNum(ba.bid),
      bestAsk: toFiniteNum(ba.ask),
      bands: PAPER_FILL_CAP_SLIP_CENTS.map((slipCents) =>
        summarizeFillCapacityBand(levels, side, Number(px), slipCents)
      ),
    };
  } catch {
    return null;
  }
}

function normalizeFillEstimate(raw: any): FillEstimate | null {
  if (!raw || typeof raw !== "object") return null;
  const wouldFillRaw = raw.wouldFill;
  const wouldFill = typeof wouldFillRaw === "boolean" ? wouldFillRaw : null;
  return {
    wouldFill,
    scorePct: toFiniteNum(raw.scorePct),
    requiredShares: toFiniteNum(raw.requiredShares),
    fillableShares: toFiniteNum(raw.fillableShares),
    fillableNotionalUsd: toFiniteNum(raw.fillableNotionalUsd),
    estVwapPx: toFiniteNum(raw.estVwapPx),
  };
}

async function estimateBuyLimitFillability(tokenId: string, limitPx: number, requiredShares: number): Promise<FillEstimate> {
  const lim = toFiniteNum(limitPx);
  const req = toFiniteNum(requiredShares);
  if (!Number.isFinite(lim) || lim <= 0 || !Number.isFinite(req) || req <= 0) {
    return {
      wouldFill: null,
      scorePct: null,
      requiredShares: toFiniteNum(requiredShares),
      fillableShares: null,
      fillableNotionalUsd: null,
      estVwapPx: null,
    };
  }

  try {
    const book = await getBook(tokenId);
    const asks = Array.isArray(book?.asks) ? book.asks : [];
    const eligible = asks
      .map((row: any) => ({
        px: toFiniteNum(row?.price),
        sz: toFiniteNum(row?.size ?? row?.quantity ?? row?.amount),
      }))
      .filter((r: any) => Number.isFinite(r.px) && Number.isFinite(r.sz) && r.sz > 0 && r.px <= lim)
      .sort((a: any, b: any) => Number(a.px) - Number(b.px));

    let remaining = req;
    let filledShares = 0;
    let filledNotional = 0;
    for (const lvl of eligible) {
      if (remaining <= 0) break;
      const take = Math.min(remaining, Number(lvl.sz));
      filledShares += take;
      filledNotional += take * Number(lvl.px);
      remaining -= take;
    }

    const estVwap = filledShares > 0 ? filledNotional / filledShares : null;
    const coverage = clampPct01(filledShares / req);
    return {
      wouldFill: coverage >= 0.999,
      scorePct: Math.round(coverage * 1000) / 10,
      requiredShares: req,
      fillableShares: filledShares,
      fillableNotionalUsd: filledNotional,
      estVwapPx: estVwap,
    };
  } catch {
    return {
      wouldFill: null,
      scorePct: null,
      requiredShares: req,
      fillableShares: null,
      fillableNotionalUsd: null,
      estVwapPx: null,
    };
  }
}

async function estimateSellLimitFillability(tokenId: string, limitPx: number, requiredShares: number): Promise<FillEstimate> {
  const lim = toFiniteNum(limitPx);
  const req = toFiniteNum(requiredShares);
  if (!Number.isFinite(lim) || lim <= 0 || !Number.isFinite(req) || req <= 0) {
    return {
      wouldFill: null,
      scorePct: null,
      requiredShares: toFiniteNum(requiredShares),
      fillableShares: null,
      fillableNotionalUsd: null,
      estVwapPx: null,
    };
  }

  try {
    const book = await getBook(tokenId);
    const bids = Array.isArray(book?.bids) ? book.bids : [];
    const eligible = bids
      .map((row: any) => ({
        px: toFiniteNum(row?.price),
        sz: toFiniteNum(row?.size ?? row?.quantity ?? row?.amount),
      }))
      .filter((r: any) => Number.isFinite(r.px) && Number.isFinite(r.sz) && r.sz > 0 && r.px >= lim)
      .sort((a: any, b: any) => Number(b.px) - Number(a.px));

    let remaining = req;
    let filledShares = 0;
    let filledNotional = 0;
    for (const lvl of eligible) {
      if (remaining <= 0) break;
      const take = Math.min(remaining, Number(lvl.sz));
      filledShares += take;
      filledNotional += take * Number(lvl.px);
      remaining -= take;
    }

    const estVwap = filledShares > 0 ? filledNotional / filledShares : null;
    const coverage = clampPct01(filledShares / req);
    return {
      wouldFill: coverage >= 0.999,
      scorePct: Math.round(coverage * 1000) / 10,
      requiredShares: req,
      fillableShares: filledShares,
      fillableNotionalUsd: filledNotional,
      estVwapPx: estVwap,
    };
  } catch {
    return {
      wouldFill: null,
      scorePct: null,
      requiredShares: req,
      fillableShares: null,
      fillableNotionalUsd: null,
      estVwapPx: null,
    };
  }
}

async function getBestBidAsk(tokenId: string): Promise<{ bid: number | null; ask: number | null }> {
  const book = await getBook(tokenId);
  return bestBidAskFromBook(book);
}

function isTransientBookFetchError(err: any): boolean {
  const msg = String(err?.message ?? err ?? "").toLowerCase();
  return (
    msg.includes(" 502 ") ||
    msg.includes(" 503 ") ||
    msg.includes(" 504 ") ||
    msg.includes("bad gateway") ||
    msg.includes("gateway timeout") ||
    msg.includes("fetch failed") ||
    msg.includes("etimedout") ||
    msg.includes("econnreset")
  );
}

async function getBestBidAskSafe(tokenId: string, sideLabel: "UP" | "DOWN"): Promise<{ bid: number | null; ask: number | null }> {
  const fresh = getCachedBestBidAsk(tokenId, QUOTE_MAX_STALE_MS);
  if (fresh) return fresh;
  try {
    const ba = await fetchAndCacheBestBidAsk(tokenId, sideLabel, QUOTE_FETCH_TIMEOUT_MS);
    const ageMs = quoteAgeMs(tokenId);
    noteQuoteLagIfNeeded(sideLabel, tokenId, ageMs, "direct_fetch");
    return ba;
  } catch (e: any) {
    const transient = isTransientBookFetchError(e) || String(e?.name || "").toLowerCase() === "aborterror";
    const key = `book:${sideLabel}:${tokenId}`;
    const now = nowMs();
    const last = ((getBestBidAskSafe as any).__lastWarnMs?.get(key) ?? 0) as number;
    if (now - last > 2500) {
      if (!(getBestBidAskSafe as any).__lastWarnMs) (getBestBidAskSafe as any).__lastWarnMs = new Map<string, number>();
      (getBestBidAskSafe as any).__lastWarnMs.set(key, now);
      const tag = transient ? "BOOK FETCH TRANSIENT" : "BOOK FETCH ERROR";
      console.warn(`[${tag}] side=${sideLabel} token=${tokenId} err=${String(e?.message ?? e)}`);
    }
    const stale = getCachedBestBidAsk(tokenId, Number.POSITIVE_INFINITY);
    if (stale) {
      const ageMs = quoteAgeMs(tokenId);
      noteQuoteLagIfNeeded(sideLabel, tokenId, ageMs, "stale_cache_fallback");
      return stale;
    }
    return { bid: null, ask: null };
  }
}

function prewarmQuotePairForTokens(upTokenLike: any, downTokenLike: any, reason: string): void {
  const upToken = String(upTokenLike || "").trim();
  const downToken = String(downTokenLike || "").trim();
  if (!upToken || !downToken) return;
  void Promise.allSettled([
    fetchAndCacheBestBidAsk(upToken, "UP", QUOTE_FETCH_TIMEOUT_MS),
    fetchAndCacheBestBidAsk(downToken, "DOWN", QUOTE_FETCH_TIMEOUT_MS),
  ]).then((results) => {
    const upRes = results[0];
    const downRes = results[1];
    const upBest = upRes.status === "fulfilled" ? upRes.value : getCachedBestBidAsk(upToken, Number.POSITIVE_INFINITY);
    const downBest = downRes.status === "fulfilled" ? downRes.value : getCachedBestBidAsk(downToken, Number.POSITIVE_INFINITY);
    const reconciled = reconcileBinaryBidPair(upBest || null, downBest || null);
    const upBid = Number(reconciled.up?.bid);
    const downBid = Number(reconciled.down?.bid);
    if (Number.isFinite(upBid) && Number.isFinite(downBid)) {
      quotePairCache = {
        upToken,
        downToken,
        upBid: clamp01(upBid),
        downBid: clamp01(downBid),
        upAsk: Number.isFinite(Number(reconciled.up?.ask)) ? Number(reconciled.up?.ask) : null,
        downAsk: Number.isFinite(Number(reconciled.down?.ask)) ? Number(reconciled.down?.ask) : null,
        tsMs: nowMs(),
        source: "rest_prewarm",
        upstreamTsMs: null,
        observedAtMs: nowMs(),
        synthetic: true,
        pure: false,
        seq: ++quotePairSeq,
      };
      if (String(current?.slug || "").trim()) {
        recordCanonicalQuoteSample(
          String(current.slug || ""),
          current?.startMs,
          quotePairCache.tsMs,
          clamp01(upBid),
          clamp01(downBid)
        );
      }
    }
    noteQuoteLagIfNeeded("UP", upToken, quoteAgeMs(upToken), `prewarm:${reason}`);
    noteQuoteLagIfNeeded("DOWN", downToken, quoteAgeMs(downToken), `prewarm:${reason}`);
  }).catch((e: any) => {
    const msg = String(e?.message ?? e);
    if (!isTransientBookFetchError(e)) {
      console.warn(`[QUOTE PREWARM ERROR] reason=${reason} up=${upToken} down=${downToken} err=${msg}`);
    }
  });
}

async function quotePumpTick(): Promise<void> {
  if (quotePumpInFlight) return;
  if (!current?.upToken || !current?.downToken) return;
  const workStartedAtMs = nowMs();
  const upToken = String(current.upToken);
  const downToken = String(current.downToken);
  const cachedPair = getCachedQuotePair(upToken, downToken, Number.POSITIVE_INFINITY);
  const cachedPairFresh = getCachedQuotePair(upToken, downToken, QUOTE_MAX_STALE_MS);
  const streamAgeMs = quoteStreamFreshAgeMsNow();
  const streamHealthy = isQuoteStreamHealthyForPairUse(streamAgeMs);
  const cachedPairUsable =
    !!cachedPair &&
    Number.isFinite(Number(cachedPair?.upBid)) &&
    Number.isFinite(Number(cachedPair?.downBid));
  if (streamHealthy && !!cachedPairFresh && cachedPairUsable) {
    noteQuoteLagIfNeeded("UP", upToken, quoteAgeMs(upToken), "pump_skip_stream_healthy");
    noteQuoteLagIfNeeded("DOWN", downToken, quoteAgeMs(downToken), "pump_skip_stream_healthy");
    return;
  }
  quotePumpInFlight = true;
  try {
    const [upRes, downRes] = await Promise.allSettled([
      fetchAndCacheBestBidAsk(upToken, "UP", QUOTE_FETCH_TIMEOUT_MS),
      fetchAndCacheBestBidAsk(downToken, "DOWN", QUOTE_FETCH_TIMEOUT_MS),
    ]);
    if (upRes.status === "rejected") {
      const key = `pump_err:UP:${upToken}`;
      const now = nowMs();
      const last = Number(((quotePumpTick as any).__lastErrWarnMs?.get(key) ?? 0));
      if (!Number.isFinite(last) || now - last >= QUOTE_LAG_WARN_COOLDOWN_MS) {
        if (!(quotePumpTick as any).__lastErrWarnMs) (quotePumpTick as any).__lastErrWarnMs = new Map<string, number>();
        (quotePumpTick as any).__lastErrWarnMs.set(key, now);
        console.warn(`[QUOTE FETCH ERROR] side=UP token=${upToken} err=${String((upRes as PromiseRejectedResult).reason?.message ?? (upRes as PromiseRejectedResult).reason)}`);
      }
    }
    if (downRes.status === "rejected") {
      const key = `pump_err:DOWN:${downToken}`;
      const now = nowMs();
      const last = Number(((quotePumpTick as any).__lastErrWarnMs?.get(key) ?? 0));
      if (!Number.isFinite(last) || now - last >= QUOTE_LAG_WARN_COOLDOWN_MS) {
        if (!(quotePumpTick as any).__lastErrWarnMs) (quotePumpTick as any).__lastErrWarnMs = new Map<string, number>();
        (quotePumpTick as any).__lastErrWarnMs.set(key, now);
        console.warn(`[QUOTE FETCH ERROR] side=DOWN token=${downToken} err=${String((downRes as PromiseRejectedResult).reason?.message ?? (downRes as PromiseRejectedResult).reason)}`);
      }
    }
    const upBest =
      upRes.status === "fulfilled"
        ? upRes.value
        : getCachedBestBidAsk(upToken, Number.POSITIVE_INFINITY);
    const downBest =
      downRes.status === "fulfilled"
        ? downRes.value
        : getCachedBestBidAsk(downToken, Number.POSITIVE_INFINITY);
    const reconciled = reconcileBinaryBidPair(upBest || null, downBest || null);
    const upBid = Number(reconciled.up?.bid);
    const downBid = Number(reconciled.down?.bid);
    if (Number.isFinite(upBid) && Number.isFinite(downBid)) {
      quotePairCache = {
        upToken,
        downToken,
        upBid: clamp01(upBid),
        downBid: clamp01(downBid),
        upAsk: Number.isFinite(Number(reconciled.up?.ask)) ? Number(reconciled.up?.ask) : null,
        downAsk: Number.isFinite(Number(reconciled.down?.ask)) ? Number(reconciled.down?.ask) : null,
        tsMs: nowMs(),
        source: "rest_pump",
        upstreamTsMs: null,
        observedAtMs: nowMs(),
        synthetic: true,
        pure: false,
        seq: ++quotePairSeq,
      };
      if (String(current?.slug || "").trim()) {
        recordCanonicalQuoteSample(
          String(current.slug || ""),
          current?.startMs,
          quotePairCache.tsMs,
          clamp01(upBid),
          clamp01(downBid)
        );
      }
    }
    noteQuoteLagIfNeeded("UP", String(current.upToken), quoteAgeMs(String(current.upToken)), "pump");
    noteQuoteLagIfNeeded("DOWN", String(current.downToken), quoteAgeMs(String(current.downToken)), "pump");
  } finally {
    quotePumpInFlight = false;
    recordCpuWork("quote", nowMs() - workStartedAtMs);
  }
}

async function triggerQuoteFallbackIfLagged(lagMs: number | null, reason: string): Promise<void> {
  if (!current?.upToken || !current?.downToken) return;
  const lag = Number(lagMs);
  if (!Number.isFinite(lag) || lag <= QUOTE_FALLBACK_TRIGGER_MS) return;
  const now = nowMs();
  if (quoteFallbackInFlight) return;
  if (now - quoteFallbackLastMs < QUOTE_FALLBACK_COOLDOWN_MS) return;
  const workStartedAtMs = nowMs();
  quoteFallbackInFlight = true;
  quoteFallbackLastMs = now;
  quoteFallbackTriggerCount += 1;
  const upToken = String(current.upToken);
  const downToken = String(current.downToken);
  try {
    const [upRes, downRes] = await Promise.allSettled([
      fetchAndCacheBestBidAsk(upToken, "UP", QUOTE_FALLBACK_TIMEOUT_MS),
      fetchAndCacheBestBidAsk(downToken, "DOWN", QUOTE_FALLBACK_TIMEOUT_MS),
    ]);
    const upBest =
      upRes.status === "fulfilled"
        ? upRes.value
        : getCachedBestBidAsk(upToken, Number.POSITIVE_INFINITY);
    const downBest =
      downRes.status === "fulfilled"
        ? downRes.value
        : getCachedBestBidAsk(downToken, Number.POSITIVE_INFINITY);
    const reconciled = reconcileBinaryBidPair(upBest || null, downBest || null);
    const upBid = Number(reconciled.up?.bid);
    const downBid = Number(reconciled.down?.bid);
    if (Number.isFinite(upBid) && Number.isFinite(downBid)) {
      quotePairCache = {
        upToken,
        downToken,
        upBid: clamp01(upBid),
        downBid: clamp01(downBid),
        upAsk: Number.isFinite(Number(reconciled.up?.ask)) ? Number(reconciled.up?.ask) : null,
        downAsk: Number.isFinite(Number(reconciled.down?.ask)) ? Number(reconciled.down?.ask) : null,
        tsMs: nowMs(),
        source: "rest_fallback",
        upstreamTsMs: null,
        observedAtMs: nowMs(),
        synthetic: true,
        pure: false,
        seq: ++quotePairSeq,
      };
      if (String(current?.slug || "").trim()) {
        recordCanonicalQuoteSample(
          String(current.slug || ""),
          current?.startMs,
          quotePairCache.tsMs,
          clamp01(upBid),
          clamp01(downBid)
        );
      }
      quoteFallbackSuccessCount += 1;
      return;
    }
    quoteFallbackErrorCount += 1;
    const key = `fallback_miss:${current.slug}`;
    const last = Number(((triggerQuoteFallbackIfLagged as any).__lastWarnMs?.get(key) ?? 0));
    if (!Number.isFinite(last) || now - last >= 2000) {
      if (!(triggerQuoteFallbackIfLagged as any).__lastWarnMs) (triggerQuoteFallbackIfLagged as any).__lastWarnMs = new Map<string, number>();
      (triggerQuoteFallbackIfLagged as any).__lastWarnMs.set(key, now);
      console.warn(`[QUOTE FALLBACK MISS] reason=${reason} lagMs=${Math.round(lag)} fallbackTimeoutMs=${QUOTE_FALLBACK_TIMEOUT_MS}`);
    }
  } catch {
    quoteFallbackErrorCount += 1;
  } finally {
    quoteFallbackInFlight = false;
    recordCpuWork("quote", nowMs() - workStartedAtMs);
  }
}

function startQuotePump() {
  if (quotePumpStarted) return;
  quotePumpStarted = true;
  const loop = () => {
    void quotePumpTick().finally(() => {
      const nextDelayMs = isQuoteStreamHealthyForPairUse()
        ? QUOTE_PUMP_HEALTHY_INTERVAL_MS
        : QUOTE_PUMP_INTERVAL_MS;
      quotePumpTimer = setTimeout(loop, nextDelayMs);
    });
  };
  loop();
}

function desiredQuoteStreamTokens(): string[] {
  const out: string[] = [];
  const up = String(current?.upToken || "").trim();
  const down = String(current?.downToken || "").trim();
  if (up) out.push(up);
  if (down) out.push(down);
  return Array.from(new Set(out));
}

function isQuoteStreamHealthy(): boolean {
  if (!QUOTE_STREAM_ENABLED) return false;
  if (!quoteStreamConnected) return false;
  if (!Number.isFinite(Number(quoteStreamLastMsgMs))) return false;
  return (nowMs() - Number(quoteStreamLastMsgMs)) <= 1500;
}

function forceQuoteStreamReconnect(reason: string): void {
  if (!QUOTE_STREAM_ENABLED) return;
  const now = nowMs();
  if (now - quoteStreamForceReconnectLastMs < QUOTE_STREAM_FORCE_RECONNECT_COOLDOWN_MS) return;
  quoteStreamForceReconnectLastMs = now;
  quoteStreamStaleReconnectCount += 1;
  const ws = quoteStreamWs;
  quoteStreamConnected = false;
  quoteStreamWs = null;
  quoteStreamConnectStartedMs = null;
  quoteStreamSubscribedTokens = new Set<string>();
  if (quoteStreamReconnectTimer) {
    clearTimeout(quoteStreamReconnectTimer);
    quoteStreamReconnectTimer = null;
  }
  try {
    if (
      ws &&
      (ws.readyState === WebSocket.OPEN ||
        ws.readyState === WebSocket.CONNECTING ||
        ws.readyState === WebSocket.CLOSING)
    ) {
      ws.terminate?.();
    }
  } catch {}
  try {
    if (ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING)) ws.close();
  } catch {}
  scheduleQuoteStreamReconnect();
  console.warn(
    `[QUOTE STREAM RECONNECT] reason=${reason} staleReconnects=${quoteStreamStaleReconnectCount} ` +
    `desiredTokens=${desiredQuoteStreamTokens().join(",")} subscribedTokens=${Array.from(quoteStreamSubscribedTokens).join(",")}`
  );
}

function ensureQuoteStreamProgress(): void {
  if (!QUOTE_STREAM_ENABLED) return;
  const now = nowMs();
  const wsState = quoteStreamWs ? Number(quoteStreamWs.readyState) : -1;
  const connectAgeMs =
    Number.isFinite(Number(quoteStreamConnectStartedMs)) && Number(quoteStreamConnectStartedMs) > 0
      ? Math.max(0, now - Number(quoteStreamConnectStartedMs))
      : Number.POSITIVE_INFINITY;
  const connectingTooLong = wsState === WebSocket.CONNECTING && connectAgeMs > QUOTE_STREAM_CONNECT_GRACE_MS;
  const hasSeenStreamMsg =
    Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0;
  const streamMsgAgeMs =
    hasSeenStreamMsg
      ? Math.max(0, now - Number(quoteStreamLastMsgMs))
      : Number.POSITIVE_INFINITY;
  const streamPriceAgeMs =
    Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
      ? Math.max(0, now - Number(quoteStreamLastPriceMsgMs))
      : Number.POSITIVE_INFINITY;
  const staleAge = Number.isFinite(streamPriceAgeMs) ? streamPriceAgeMs : streamMsgAgeMs;
  if (!quoteStreamConnected) {
    const disconnectedStale = Number.isFinite(streamMsgAgeMs) && streamMsgAgeMs > QUOTE_STREAM_STALE_RECONNECT_MS;
    if (
      wsState < 0 ||
      wsState === WebSocket.CLOSED ||
      wsState === WebSocket.CLOSING ||
      connectingTooLong ||
      (wsState === WebSocket.CONNECTING && disconnectedStale && connectAgeMs > QUOTE_STREAM_CONNECT_GRACE_MS)
    ) {
      forceQuoteStreamReconnect(
        `disconnected state=${wsState} ageMs=${Math.round(streamMsgAgeMs)} connectAgeMs=${Math.round(connectAgeMs)}`
      );
      return;
    }
  }
  if (Number.isFinite(staleAge) && staleAge > QUOTE_STREAM_STALE_RECONNECT_MS) {
    void quotePumpTick();
    void triggerQuoteFallbackIfLagged(staleAge, "stream_stale");
  }
  if (
    Number.isFinite(streamMsgAgeMs) &&
    streamMsgAgeMs > QUOTE_STREAM_HARD_RECONNECT_MS &&
    (wsState !== WebSocket.CONNECTING || connectAgeMs > QUOTE_STREAM_CONNECT_GRACE_MS)
  ) {
    forceQuoteStreamReconnect(
      `hard_stale ageMs=${Math.round(streamMsgAgeMs)} connectAgeMs=${Math.round(connectAgeMs)}`
    );
    return;
  }
  if (
    quoteStreamConnected &&
    quoteStreamLastDesiredTokensKey &&
    quoteStreamLastSubscribedTokensKey &&
    quoteStreamLastDesiredTokensKey !== quoteStreamLastSubscribedTokensKey &&
    Number.isFinite(streamMsgAgeMs) &&
    streamMsgAgeMs > QUOTE_STREAM_STALE_RECONNECT_MS
  ) {
    forceQuoteStreamReconnect(
      `subscription_mismatch desired=${quoteStreamLastDesiredTokensKey} subscribed=${quoteStreamLastSubscribedTokensKey}`
    );
  }
}

function inRolloverCriticalWindow(now = nowMs()): boolean {
  return Number.isFinite(Number(sessionRolloverCriticalUntilMs)) && Number(sessionRolloverCriticalUntilMs) > Number(now);
}

function buildQuoteBroadcastPayload() {
  const now = nowMs();
  const upToken = String(current?.upToken || "");
  const downToken = String(current?.downToken || "");
  const pairFresh = (upToken && downToken) ? getCachedQuotePair(upToken, downToken, QUOTE_MAX_STALE_MS) : null;
  const pairAny = pairFresh || ((upToken && downToken) ? getCachedQuotePair(upToken, downToken, Number.POSITIVE_INFINITY) : null);
  const pairLagMs =
    Number.isFinite(Number(pairAny?.tsMs)) && Number(pairAny?.tsMs) > 0
      ? Math.max(0, now - Number(pairAny?.tsMs))
      : null;
  const streamLastMsgAgeMs =
    Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
      ? Math.max(0, now - Number(quoteStreamLastMsgMs))
      : null;
  const streamLastPriceMsgAgeMs =
    Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
      ? Math.max(0, now - Number(quoteStreamLastPriceMsgMs))
      : null;
  return {
    type: "quote",
    t: now,
    up: { bid: Number.isFinite(Number(pairAny?.upBid)) ? Number(pairAny?.upBid) : null },
    down: { bid: Number.isFinite(Number(pairAny?.downBid)) ? Number(pairAny?.downBid) : null },
    market: { slug: current.slug, startMs: current.startMs, endMs: current.endMs, volumeUsd: current.volumeUsd },
    health: {
      quoteFeed: {
        maxStaleMs: QUOTE_MAX_STALE_MS,
        pairLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null,
        streamEnabled: QUOTE_STREAM_ENABLED,
        streamConnected: quoteStreamConnected,
        streamLastMsgAgeMs,
        streamLastPriceMsgAgeMs,
      },
      userStream: {
        enabled: USER_STREAM_ENABLED,
        connected: userStreamConnected,
        marketsKey: userStreamLastDesiredMarketsKey || null,
        lastMsgAgeMs:
          Number.isFinite(Number(userStreamLastMsgMs)) && Number(userStreamLastMsgMs) > 0
            ? Math.max(0, now - Number(userStreamLastMsgMs))
            : null,
        msgCount: userStreamMsgCount,
        errCount: userStreamErrCount,
        reconnectCount: userStreamReconnectCount,
      },
    },
  };
}

function startQuoteBroadcast() {
  if (quoteBroadcastStarted) return;
  quoteBroadcastStarted = true;
  const scheduleNext = (delayMsRaw: any) => {
    const delayMs = Math.max(25, Number(delayMsRaw) || QUOTE_BROADCAST_INTERVAL_MS);
    const timer = setTimeout(tick, delayMs);
    try { timer.unref?.(); } catch {}
  };
  const nextQuoteBroadcastDelayMs = (tickNow: number) => {
    if (!hasOpenWsClients()) return QUOTE_BROADCAST_IDLE_INTERVAL_MS;
    if (inRolloverCriticalWindow(tickNow)) return QUOTE_BROADCAST_ROLLOVER_INTERVAL_MS;
    if (isQuoteStreamHealthy()) return QUOTE_BROADCAST_HEALTHY_INTERVAL_MS;
    return QUOTE_BROADCAST_INTERVAL_MS;
  };
  const tick = () => {
    const workStartedAtMs = nowMs();
    const tickNow = nowMs();
    const runtimeUptimeMs = Math.max(0, tickNow - Number(SERVER_RUN_START_MS || tickNow));
    const withinWatchdogStartupGrace = runtimeUptimeMs < WATCHDOG_EXIT_STARTUP_GRACE_MS;
    const hasClients = hasOpenWsClients();
    const inRolloverCritical = inRolloverCriticalWindow(tickNow);
    const shouldEnforceGapKpi = hasClients && !inRolloverCritical;
    if (quoteBroadcastLastMs != null && Number.isFinite(Number(quoteBroadcastLastMs)) && Number(quoteBroadcastLastMs) > 0) {
      const gapMs = Math.max(0, tickNow - Number(quoteBroadcastLastMs));
      quoteBroadcastGapMsLatest = gapMs;
      if (!Number.isFinite(Number(quoteBroadcastGapMsMax)) || gapMs > Number(quoteBroadcastGapMsMax)) {
        quoteBroadcastGapMsMax = gapMs;
      }
      if (shouldEnforceGapKpi && gapMs > QUOTE_KPI_TARGET_MS) {
        quoteBroadcastGapViolationStreak += 1;
        quoteBroadcastGapViolationCount += 1;
      } else {
        quoteBroadcastGapViolationStreak = 0;
      }
      recordLatencySample("live", "quote_broadcast_gap", gapMs, {
        quoteKpiTargetMs: QUOTE_KPI_TARGET_MS,
      });
    }
    quoteBroadcastLastMs = tickNow;
    const mainLoopAgeMs =
      Number.isFinite(Number(mainLoopLastBeatMs)) && Number(mainLoopLastBeatMs) > 0
        ? Math.max(0, tickNow - Number(mainLoopLastBeatMs))
        : Number.POSITIVE_INFINITY;
    if (Number.isFinite(mainLoopAgeMs)) {
      recordLatencySample("live", "main_loop_age", mainLoopAgeMs, {
        mainLoopStallSoftHealMs: MAIN_LOOP_STALL_SOFT_HEAL_MS,
      });
      if (mainLoopAgeMs > MAIN_LOOP_STALL_SOFT_HEAL_MS) {
        triggerRuntimeSelfHeal("main_loop_stall", {
          ageMs: Math.round(mainLoopAgeMs),
          softHealMs: MAIN_LOOP_STALL_SOFT_HEAL_MS,
        });
      }
    }
    ensureQuoteStreamSubscription();
    ensureQuoteStreamProgress();
    const payload = buildQuoteBroadcastPayload();
    const pairLagMs = Number(payload?.health?.quoteFeed?.pairLagMs);
    const streamAgeMs = Number(
      payload?.health?.quoteFeed?.streamLastPriceMsgAgeMs ?? payload?.health?.quoteFeed?.streamLastMsgAgeMs
    );
    const feedLagMs = Math.max(
      Number.isFinite(pairLagMs) ? pairLagMs : 0,
      Number.isFinite(streamAgeMs) ? streamAgeMs : 0
    );
    const hasFreshPair = Number.isFinite(pairLagMs) && pairLagMs <= QUOTE_FEED_HARD_FAIL_MS;
    const quotePathActuallyStale =
      feedLagMs >= QUOTE_FEED_HARD_FAIL_MS ||
      (Number.isFinite(streamAgeMs) && streamAgeMs >= QUOTE_FEED_HARD_FAIL_MS) ||
      (!quoteStreamConnected && !hasFreshPair);
    recordLatencySample("live", "quote_feed_lag", feedLagMs, {
      pairLagMs: Number.isFinite(pairLagMs) ? pairLagMs : null,
      streamAgeMs: Number.isFinite(streamAgeMs) ? streamAgeMs : null,
    });
    if (feedLagMs > QUOTE_KPI_TARGET_MS) {
      quoteBroadcastFeedViolationStreak += 1;
    } else {
      quoteBroadcastFeedViolationStreak = 0;
    }
    const kpiViolationStreak = Math.max(quoteBroadcastGapViolationStreak, quoteBroadcastFeedViolationStreak);
    const kpiReconnectStreak = quoteBroadcastFeedViolationStreak;
    if (kpiReconnectStreak >= QUOTE_KPI_RECONNECT_STREAK) {
      if (!Number.isFinite(Number(quoteKpiUnhealthySinceMs))) quoteKpiUnhealthySinceMs = tickNow;
    } else if (kpiReconnectStreak <= 0) {
      quoteKpiUnhealthySinceMs = null;
    }
    if (kpiReconnectStreak >= QUOTE_KPI_RECONNECT_STREAK) {
      quoteKpiHealTriggerCount += 1;
      const shouldKickRestRecovery =
        quotePathActuallyStale ||
        !quoteStreamConnected ||
        (Number.isFinite(streamAgeMs) && streamAgeMs >= QUOTE_FALLBACK_TRIGGER_MS);
      if (shouldKickRestRecovery) {
        void quotePumpTick();
        void triggerQuoteFallbackIfLagged(feedLagMs || QUOTE_FALLBACK_TRIGGER_MS + 1, "kpi_violation");
      }
      const wsState = quoteStreamWs ? Number(quoteStreamWs.readyState) : -1;
      const connectAgeMs =
        Number.isFinite(Number(quoteStreamConnectStartedMs)) && Number(quoteStreamConnectStartedMs) > 0
          ? Math.max(0, tickNow - Number(quoteStreamConnectStartedMs))
          : Number.POSITIVE_INFINITY;
      const withinConnectGrace = wsState === WebSocket.CONNECTING && connectAgeMs <= QUOTE_STREAM_CONNECT_GRACE_MS;
      const hasSeenStreamMsg =
        Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0;
      const unhealthyForMs =
        Number.isFinite(Number(quoteKpiUnhealthySinceMs)) && Number(quoteKpiUnhealthySinceMs) > 0
          ? Math.max(0, tickNow - Number(quoteKpiUnhealthySinceMs))
          : 0;
      const shouldReconnect =
        !withinConnectGrace && (
          (!quoteStreamConnected && unhealthyForMs >= QUOTE_KPI_RECONNECT_MIN_UNHEALTHY_MS) ||
          (hasSeenStreamMsg && Number.isFinite(streamAgeMs) && streamAgeMs >= QUOTE_KPI_RECONNECT_MIN_STREAM_AGE_MS) ||
          (
            feedLagMs >= QUOTE_KPI_RECONNECT_MIN_FEED_LAG_MS &&
            unhealthyForMs >= QUOTE_KPI_RECONNECT_MIN_UNHEALTHY_MS
          )
        );
      if (shouldReconnect && !inRolloverCritical) {
        forceQuoteStreamReconnect(
          `kpi_violation streak=${kpiReconnectStreak} gap=${Math.round(Number(quoteBroadcastGapMsLatest || 0))} ` +
          `feedLag=${Math.round(feedLagMs)} unhealthyForMs=${Math.round(unhealthyForMs)}`
        );
      }
    }
    if (kpiReconnectStreak >= QUOTE_KPI_UNHEALTHY_STREAK) {
      if (!Number.isFinite(Number(quoteKpiUnhealthySinceMs))) quoteKpiUnhealthySinceMs = tickNow;
    } else if (kpiReconnectStreak < QUOTE_KPI_RECONNECT_STREAK) {
      quoteKpiUnhealthySinceMs = null;
    }
    const unhealthyForMs =
      Number.isFinite(Number(quoteKpiUnhealthySinceMs)) && Number(quoteKpiUnhealthySinceMs) > 0
        ? Math.max(0, tickNow - Number(quoteKpiUnhealthySinceMs))
        : 0;
    const quoteFeedHardUnhealthy = quotePathActuallyStale;
    if (
      WATCHDOG_EXIT_ON_MAIN_LOOP_STALL &&
      Number.isFinite(mainLoopAgeMs) &&
      mainLoopAgeMs > MAIN_LOOP_STALL_HARD_FAIL_MS &&
      watchdogHealCount >= WATCHDOG_EXIT_MIN_HEAL_ATTEMPTS &&
      !withinWatchdogStartupGrace &&
      quotePathActuallyStale
    ) {
      console.error(
        `[WATCHDOG EXIT] reason=main_loop_hard_stall ageMs=${Math.round(mainLoopAgeMs)} ` +
        `hardFailMs=${MAIN_LOOP_STALL_HARD_FAIL_MS} healCount=${watchdogHealCount} ` +
        `feedLagMs=${Math.round(feedLagMs)} streamConnected=${quoteStreamConnected} hasFreshPair=${hasFreshPair}`
      );
      setTimeout(() => process.exit(42), 25);
      return;
    }
    if (
      WATCHDOG_EXIT_ON_QUOTE_FEED_STALE &&
      quoteFeedHardUnhealthy &&
      unhealthyForMs >= QUOTE_FEED_HARD_EXIT_MIN_UNHEALTHY_MS &&
      !withinWatchdogStartupGrace &&
      !inRolloverCritical
    ) {
      console.error(
        `[WATCHDOG EXIT] reason=quote_feed_hard_stale unhealthyForMs=${Math.round(unhealthyForMs)} ` +
        `feedLagMs=${Math.round(feedLagMs)} streamAgeMs=${Math.round(Number.isFinite(streamAgeMs) ? streamAgeMs : -1)} ` +
        `streamConnected=${quoteStreamConnected} hasFreshPair=${hasFreshPair} thresholdMs=${QUOTE_FEED_HARD_FAIL_MS} ` +
        `startupGraceMs=${WATCHDOG_EXIT_STARTUP_GRACE_MS}`
      );
      setTimeout(() => process.exit(43), 25);
      return;
    }
    if (QUOTE_CLIENT_BROADCAST_ENABLED) {
      broadcast(payload);
    }
    recordCpuWork("quote", nowMs() - workStartedAtMs);
    scheduleNext(nextQuoteBroadcastDelayMs(tickNow));
  };
  tick();
}

function sendQuoteStreamSubscription(tokens: string[], operation?: "subscribe" | "unsubscribe"): void {
  if (!quoteStreamWs || quoteStreamWs.readyState !== WebSocket.OPEN) return;
  if (!tokens.length) return;
  const payload: any = { type: "market", assets_ids: tokens, custom_feature_enabled: true };
  if (operation) payload.operation = operation;
  try {
    quoteStreamWs.send(JSON.stringify(payload));
  } catch {
    // no-op
  }
}

function ensureQuoteStreamSubscription(): void {
  if (!QUOTE_STREAM_ENABLED) return;
  const desiredTokens = desiredQuoteStreamTokens();
  quoteStreamLastDesiredTokensKey = desiredTokens.join(",");
  if (!quoteStreamWs || quoteStreamWs.readyState !== WebSocket.OPEN) {
    startQuoteStream();
    return;
  }
  const desired = new Set(desiredTokens);
  const toAdd = Array.from(desired).filter((t) => !quoteStreamSubscribedTokens.has(t));
  const toRemove = Array.from(quoteStreamSubscribedTokens).filter((t) => !desired.has(t));
  if (toAdd.length) sendQuoteStreamSubscription(toAdd, "subscribe");
  if (toRemove.length) sendQuoteStreamSubscription(toRemove, "unsubscribe");
  quoteStreamSubscribedTokens = desired;
  quoteStreamLastSubscribedTokensKey = Array.from(quoteStreamSubscribedTokens).join(",");
}

function processQuoteStreamMessage(msg: any): void {
  if (!msg || typeof msg !== "object") return;
  const evt = String(msg.event_type || msg.type || "").toLowerCase();
  if (evt === "book") {
    const token = String(msg.asset_id || msg.token_id || "");
    if (!token) return;
    const ba = bestBidAskFromBook(msg);
    cacheQuoteFromStream(token, ba.bid, ba.ask, msg.timestamp || msg.ts || msg.t);
    return;
  }
  if (evt === "price_change") {
    const rows = Array.isArray(msg.price_changes) ? msg.price_changes : [];
    for (const row of rows) {
      const token = String(row?.asset_id || row?.token_id || "");
      if (!token) continue;
      cacheQuoteFromStream(token, Number(row?.best_bid), Number(row?.best_ask), row?.timestamp || msg.timestamp || msg.ts);
    }
    return;
  }
  // best_bid_ask and compatible payloads
  const token = String(msg.asset_id || msg.token_id || "");
  if (!token) return;
  const bid = Number(msg.best_bid ?? msg.bid);
  const ask = Number(msg.best_ask ?? msg.ask);
  cacheQuoteFromStream(token, bid, ask, msg.timestamp || msg.ts || msg.t);
}

function scheduleQuoteStreamReconnect(): void {
  if (quoteStreamReconnectTimer) return;
  const delayMs = Math.max(250, quoteStreamReconnectBackoffMs);
  quoteStreamReconnectTimer = setTimeout(() => {
    quoteStreamReconnectTimer = null;
    startQuoteStream();
  }, delayMs);
  quoteStreamReconnectBackoffMs = Math.min(8000, Math.floor(quoteStreamReconnectBackoffMs * 1.6));
}

function startQuoteStream(): void {
  if (!QUOTE_STREAM_ENABLED) return;
  try {
    if (quoteStreamWs && quoteStreamWs.readyState === WebSocket.OPEN) return;
    if (quoteStreamWs && quoteStreamWs.readyState === WebSocket.CONNECTING) return;
    quoteStreamConnectStartedMs = nowMs();
    const ws = new WebSocket(QUOTE_STREAM_URL);
    quoteStreamWs = ws;
    ws.on("open", () => {
      quoteStreamConnected = true;
      quoteStreamConnectStartedMs = null;
      quoteStreamReconnectBackoffMs = 500;
      quoteStreamReconnectCount += 1;
      quoteStreamSubscribedTokens = new Set<string>();
      quoteStreamLastSubscribedTokensKey = "";
      ensureQuoteStreamSubscription();
      console.log(`[QUOTE STREAM] connected url=${QUOTE_STREAM_URL}`);
    });
    ws.on("message", (raw: any) => {
      quoteStreamLastMsgMs = nowMs();
      quoteStreamMsgCount += 1;
      let parsed: any = null;
      try {
        parsed = JSON.parse(typeof raw === "string" ? raw : raw?.toString?.("utf8"));
      } catch {
        return;
      }
      if (Array.isArray(parsed)) {
        for (const m of parsed) processQuoteStreamMessage(m);
      } else {
        processQuoteStreamMessage(parsed);
      }
    });
    ws.on("error", (e: any) => {
      quoteStreamErrCount += 1;
      const key = "quote_stream_error";
      const now = nowMs();
      const last = Number(((startQuoteStream as any).__lastErrWarnMs?.get(key) ?? 0));
      if (!Number.isFinite(last) || now - last > 2000) {
        if (!(startQuoteStream as any).__lastErrWarnMs) (startQuoteStream as any).__lastErrWarnMs = new Map<string, number>();
        (startQuoteStream as any).__lastErrWarnMs.set(key, now);
        console.warn(`[QUOTE STREAM ERROR] ${String(e?.message ?? e)}`);
      }
    });
    ws.on("close", () => {
      quoteStreamConnected = false;
      quoteStreamConnectStartedMs = null;
      quoteStreamWs = null;
      quoteStreamSubscribedTokens = new Set<string>();
      quoteStreamLastSubscribedTokensKey = "";
      scheduleQuoteStreamReconnect();
    });
  } catch {
    quoteStreamConnectStartedMs = null;
    scheduleQuoteStreamReconnect();
  }
}

function reconcileBinaryBidPair(
  upLike: { bid: number | null; ask: number | null } | null | undefined,
  downLike: { bid: number | null; ask: number | null } | null | undefined
): {
  up: { bid: number | null; ask: number | null };
  down: { bid: number | null; ask: number | null };
  synthetic: boolean;
} {
  const upBidRaw = Number(upLike?.bid);
  const dnBidRaw = Number(downLike?.bid);
  const upBidDirect = Number.isFinite(upBidRaw) ? clamp01(upBidRaw) : null;
  const dnBidDirect = Number.isFinite(dnBidRaw) ? clamp01(dnBidRaw) : null;

  let upBid = upBidDirect;
  let dnBid = dnBidDirect;
  let synthetic = false;
  if (upBid != null && dnBid != null) {
    // Keep direct observed bids when both sides are available.
    upBid = clamp01(Number(upBid));
    dnBid = clamp01(Number(dnBid));
  } else if (upBid == null && dnBid != null) {
    upBid = clamp01(1 - Number(dnBid));
    synthetic = true;
  } else if (dnBid == null && upBid != null) {
    dnBid = clamp01(1 - Number(upBid));
    synthetic = true;
  } else {
    synthetic = true;
  }
  return {
    up: { bid: upBid, ask: Number.isFinite(Number(upLike?.ask)) ? Number(upLike!.ask) : null },
    down: { bid: dnBid, ask: Number.isFinite(Number(downLike?.ask)) ? Number(downLike!.ask) : null },
    synthetic,
  };
}

function parseIsoZ(s: string): Date {
  const t = s.endsWith("Z") ? s.slice(0, -1) + "+00:00" : s;
  return new Date(t);
}

// ===== LIVE CLOB CLIENT (unified & fixed) =====
let __clobClient: ClobClient | null = null;
let __lastLivePosSyncMs = 0;
const LIVE_POS_SYNC_MS = Math.max(500, Number(process.env.LIVE_POS_SYNC_MS || 2000));
let __livePosSyncInFlight = false;
let __lastLivePosTradeProbeMs = 0;
const LIVE_POS_TRADES_FALLBACK_MS = Math.max(
  LIVE_POS_SYNC_MS,
  Number(process.env.LIVE_POS_TRADES_FALLBACK_MS || 10000)
);
const BUY_FAST_CONFIRM_WINDOW_MS = Math.max(300, Number(process.env.BUY_FAST_CONFIRM_WINDOW_MS || 1500));

async function getClobClient(): Promise<ClobClient> {
  if (__clobClient) return __clobClient;

  const chainId = Number(process.env.POLY_CHAIN_ID || 137);
  const priv = process.env.POLY_PRIVATE_KEY;
  if (!priv) throw new Error("POLY_PRIVATE_KEY is required for live trading");

  const signer = new Wallet(priv);

  const signatureType = Number(process.env.POLY_SIGNATURE_TYPE ?? "2");
  const funder = process.env.POLY_FUNDER_ADDRESS;

  if (signatureType === 2 && !funder) {
    throw new Error("POLY_FUNDER_ADDRESS is required when POLY_SIGNATURE_TYPE=2 (Gnosis Safe / proxy wallet)");
  }

  console.log(`[CLOB INIT]`.padEnd(20) + `signatureType = ${signatureType}`);
  console.log(`[CLOB INIT]`.padEnd(20) + `signer EOA    = ${signer.address}`);
  console.log(`[CLOB INIT]`.padEnd(20) + `funder/proxy  = ${funder || signer.address}`);
  console.log(
    `[CLOB INIT]`.padEnd(20) +
      `using provided API creds: ${!!(process.env.POLY_API_KEY && process.env.POLY_SECRET && process.env.POLY_PASSPHRASE)}`
  );

  let apiCreds;
  if (process.env.POLY_API_KEY && process.env.POLY_SECRET && process.env.POLY_PASSPHRASE) {
    apiCreds = {
      key: process.env.POLY_API_KEY,
      secret: process.env.POLY_SECRET,
      passphrase: process.env.POLY_PASSPHRASE,
    };
  } else {
    console.log("[CLOB] No API creds in env → deriving fresh ones...");
    const tempClient = new ClobClient(CLOB_BASE, chainId, signer);
    apiCreds = await tempClient.createOrDeriveApiKey();
  }

  const client = new ClobClient(CLOB_BASE, chainId, signer, apiCreds, signatureType, funder || undefined);
  __clobClient = client;
  void ensureUserStreamStarted(client).catch(() => {});
  return client;
}

function extractConditionIdFromGammaMarket(raw: any): string | null {
  const candidates = [
    raw?.conditionId,
    raw?.condition_id,
    raw?.conditionID,
    raw?.condition,
    raw?.market,
  ];
  for (const candidate of candidates) {
    const out = String(candidate || "").trim();
    if (out) return out;
  }
  return null;
}

async function resolveConditionIdForSlug(slug: string): Promise<string | null> {
  const key = String(slug || "").trim();
  if (!key) return null;
  const cached = userStreamConditionCache.get(key) || null;
  const now = nowMs();
  if (cached && (now - Number(cached.fetchedAtMs || 0)) <= USER_STREAM_CONDITION_CACHE_MS) {
    return cached.conditionId || null;
  }
  let conditionId: string | null = null;
  try {
    const evt = await gammaEventBySlug(key);
    const mkt = Array.isArray(evt?.markets) && evt.markets.length ? evt.markets[0] : null;
    conditionId = extractConditionIdFromGammaMarket(mkt) || extractConditionIdFromGammaMarket(evt);
  } catch {}
  userStreamConditionCache.set(key, { conditionId, fetchedAtMs: now });
  return conditionId;
}

function desiredUserStreamSlugs(): string[] {
  const out = new Set<string>();
  if (String(current.slug || "").trim()) out.add(String(current.slug).trim());
  for (const bot of botInstances.values()) {
    if (String(bot.mode || "").trim().toLowerCase() !== "live") continue;
    if (!isBotActive(bot.status) && bot.status !== "starting") continue;
    const slug = String((bot as any)?.runtime?.marketSlug || bot.marketSlug || "").trim();
    if (slug) out.add(slug);
  }
  return Array.from(out);
}

async function desiredUserStreamConditionIds(): Promise<string[]> {
  const slugs = desiredUserStreamSlugs();
  const ids = await Promise.all(slugs.map((slug) => resolveConditionIdForSlug(slug).catch(() => null)));
  return Array.from(new Set(ids.map((v) => String(v || "").trim()).filter(Boolean)));
}

function pruneUserStreamOrderStateCache(): void {
  const cutoff = nowMs() - USER_STREAM_STATE_TTL_MS;
  for (const [orderId, row] of userStreamOrderStateByOrderId.entries()) {
    if (Number(row.lastSeenAtMs || 0) >= cutoff) continue;
    userStreamOrderStateByOrderId.delete(orderId);
    userStreamWaitersByOrderId.delete(orderId);
  }
}

function notifyUserStreamWaiters(orderId: string): void {
  const key = String(orderId || "").trim();
  if (!key) return;
  const waiters = userStreamWaitersByOrderId.get(key);
  if (!waiters || !waiters.size) return;
  for (const fn of Array.from(waiters)) {
    try {
      fn();
    } catch {}
  }
}

function upsertUserStreamOrderState(
  orderId: string,
  updater: (state: UserStreamOrderState) => void
): UserStreamOrderState {
  const key = String(orderId || "").trim();
  const base =
    userStreamOrderStateByOrderId.get(key) ||
    {
      orderId: key,
      marketId: null,
      assetId: null,
      side: null,
      placedAtMs: null,
      lastOrderUpdateAtMs: null,
      firstMatchedAtMs: null,
      lastMatchedAtMs: null,
      minedAtMs: null,
      confirmedAtMs: null,
      lastSeenAtMs: nowMs(),
      orderEventType: null,
      tradeStatus: null,
      orderMatchedShares: 0,
      totalMatchedShares: 0,
      fillPx: null,
      matchKeys: new Set<string>(),
    };
  updater(base);
  base.lastSeenAtMs = nowMs();
  userStreamOrderStateByOrderId.set(key, base);
  notifyUserStreamWaiters(key);
  pruneUserStreamOrderStateCache();
  return base;
}

function getUserStreamOrderState(orderId: string | null | undefined): UserStreamOrderState | null {
  const key = String(orderId || "").trim();
  if (!key) return null;
  return userStreamOrderStateByOrderId.get(key) || null;
}

async function waitForUserStreamOrderState(
  orderId: string,
  predicate: (state: UserStreamOrderState | null) => boolean,
  timeoutMs: number
): Promise<UserStreamOrderState | null> {
  const key = String(orderId || "").trim();
  if (!key) return null;
  const currentState = getUserStreamOrderState(key);
  if (predicate(currentState)) return currentState;
  return await new Promise<UserStreamOrderState | null>((resolve) => {
    let settled = false;
    const finish = (state: UserStreamOrderState | null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      const waiters = userStreamWaitersByOrderId.get(key);
      if (waiters) {
        waiters.delete(check);
        if (!waiters.size) userStreamWaitersByOrderId.delete(key);
      }
      resolve(state);
    };
    const check = () => {
      const latest = getUserStreamOrderState(key);
      if (predicate(latest)) finish(latest);
    };
    const timer = setTimeout(() => finish(getUserStreamOrderState(key)), Math.max(1, timeoutMs));
    const waiters = userStreamWaitersByOrderId.get(key) || new Set<() => void>();
    waiters.add(check);
    userStreamWaitersByOrderId.set(key, waiters);
  });
}

function extractUserStreamTsMs(raw: any): number | null {
  const parsed = parseEpochMsLike(raw);
  if (Number.isFinite(Number(parsed)) && Number(parsed) > 0) return Number(parsed);
  return null;
}

function isUserStreamTradeFillLikeStatus(statusRaw: any): boolean {
  const status = String(statusRaw || "").trim().toUpperCase();
  return status === "MATCHED" || status === "MINED" || status === "CONFIRMED";
}

function processUserStreamOrderMessage(msg: any): void {
  const orderId = extractOrderIdLike(msg);
  if (!orderId) return;
  const tsMs =
    extractUserStreamTsMs(msg?.timestamp) ??
    extractUserStreamTsMs(msg?.created_at) ??
    extractUserStreamTsMs(msg?.last_update) ??
    extractUserStreamTsMs(msg?.updated_at) ??
    null;
  const eventType = String(msg?.type || msg?.status || "").trim().toUpperCase() || null;
  const matchedSharesRaw = Number(
    msg?.size_matched ??
    msg?.matched_size ??
    msg?.filled_size ??
    msg?.filledSize ??
    msg?.sizeFilled ??
    NaN
  );
  const matchedShares = Number.isFinite(matchedSharesRaw) && matchedSharesRaw > 0 ? matchedSharesRaw : 0;
  const fillPxRaw = Number(msg?.price ?? msg?.avgPrice ?? msg?.avg_fill_price ?? msg?.matched_price ?? NaN);
  const fillPx = Number.isFinite(fillPxRaw) && fillPxRaw > 0 ? fillPxRaw : null;
  upsertUserStreamOrderState(orderId, (state) => {
    state.marketId = String(msg?.market || state.marketId || "").trim() || state.marketId;
    state.assetId = String(msg?.asset_id || msg?.assetId || state.assetId || "").trim() || state.assetId;
    state.side = String(msg?.side || state.side || "").trim().toUpperCase() || state.side;
    state.orderEventType = eventType;
    if (tsMs != null) {
      if (eventType === "PLACEMENT" && !Number.isFinite(Number(state.placedAtMs))) state.placedAtMs = tsMs;
      state.lastOrderUpdateAtMs = Number.isFinite(Number(state.lastOrderUpdateAtMs))
        ? Math.max(Number(state.lastOrderUpdateAtMs), tsMs)
        : tsMs;
    }
    if (matchedShares > 0) {
      state.orderMatchedShares = Math.max(Number(state.orderMatchedShares || 0), matchedShares);
      if (tsMs != null && !Number.isFinite(Number(state.firstMatchedAtMs))) state.firstMatchedAtMs = tsMs;
      if (tsMs != null) {
        state.lastMatchedAtMs = Number.isFinite(Number(state.lastMatchedAtMs))
          ? Math.max(Number(state.lastMatchedAtMs), tsMs)
          : tsMs;
      }
    }
    if (fillPx != null) state.fillPx = fillPx;
  });
}

function processUserStreamTradeMessage(msg: any): void {
  const status = String(msg?.status || msg?.type || "").trim().toUpperCase() || null;
  const fillLikeStatus = isUserStreamTradeFillLikeStatus(status);
  const tradeId = String(msg?.id || msg?.trade_id || "").trim();
  const matchedAtMs =
    extractUserStreamTsMs(msg?.match_time) ??
    extractUserStreamTsMs(msg?.matchTime) ??
    extractUserStreamTsMs(msg?.matchtime) ??
    extractUserStreamTsMs(msg?.timestamp) ??
    extractUserStreamTsMs(msg?.created_at) ??
    extractUserStreamTsMs(msg?.last_update) ??
    null;
  const priceRaw = Number(msg?.price ?? msg?.avgPrice ?? msg?.avg_fill_price ?? msg?.matched_price ?? NaN);
  const price = Number.isFinite(priceRaw) && priceRaw > 0 ? priceRaw : null;
  const takerOrderId = String(msg?.taker_order_id || msg?.takerOrderId || "").trim();
  const tradeOwner = String(msg?.trade_owner || msg?.owner || "").trim();
  const makerOrders = Array.isArray(msg?.maker_orders) ? msg.maker_orders : [];
  const linked: Array<{ orderId: string; shares: number | null }> = [];
  const takerSharesRaw = Number(msg?.size ?? msg?.matched_amount ?? msg?.amount ?? NaN);
  const takerShares = Number.isFinite(takerSharesRaw) && takerSharesRaw > 0 ? takerSharesRaw : null;
  if (takerOrderId) linked.push({ orderId: takerOrderId, shares: takerShares });
  for (const maker of makerOrders) {
    const makerOrderId = String(maker?.order_id || maker?.orderId || maker?.id || "").trim();
    if (!makerOrderId) continue;
    const makerOwner = String(maker?.owner || "").trim();
    if (tradeOwner && makerOwner && makerOwner !== tradeOwner) continue;
    const makerSharesRaw = Number(maker?.matched_amount ?? maker?.size ?? msg?.size ?? NaN);
    const makerShares = Number.isFinite(makerSharesRaw) && makerSharesRaw > 0 ? makerSharesRaw : null;
    linked.push({ orderId: makerOrderId, shares: makerShares });
  }
  for (const row of linked) {
    upsertUserStreamOrderState(row.orderId, (state) => {
      state.marketId = String(msg?.market || state.marketId || "").trim() || state.marketId;
      state.assetId = String(msg?.asset_id || msg?.assetId || state.assetId || "").trim() || state.assetId;
      state.side = String(msg?.side || state.side || "").trim().toUpperCase() || state.side;
      state.tradeStatus = status;
      if (price != null) state.fillPx = price;
      const resolvedShares =
        Number.isFinite(Number(row.shares)) && Number(row.shares) > 0
          ? Number(row.shares)
          : Math.max(Number(state.orderMatchedShares || 0), 0);
      if (fillLikeStatus) {
        const matchKey =
          tradeId
            ? `trade:${tradeId}:${row.orderId}`
            : `trade:${matchedAtMs ?? 0}:${price ?? 0}:${resolvedShares ?? 0}:${row.orderId}`;
        if (!state.matchKeys.has(matchKey) && resolvedShares > 0) {
          state.matchKeys.add(matchKey);
          state.totalMatchedShares += resolvedShares;
        }
        if (
          matchedAtMs != null &&
          (
            resolvedShares > 0 ||
            Number(state.orderMatchedShares || 0) > 0 ||
            Number(state.totalMatchedShares || 0) > 0
          )
        ) {
          state.firstMatchedAtMs = Number.isFinite(Number(state.firstMatchedAtMs))
            ? Math.min(Number(state.firstMatchedAtMs), matchedAtMs)
            : matchedAtMs;
          state.lastMatchedAtMs = Number.isFinite(Number(state.lastMatchedAtMs))
            ? Math.max(Number(state.lastMatchedAtMs), matchedAtMs)
            : matchedAtMs;
        }
      }
      if (status === "MINED" && matchedAtMs != null) {
        state.minedAtMs = Number.isFinite(Number(state.minedAtMs))
          ? Math.min(Number(state.minedAtMs), matchedAtMs)
          : matchedAtMs;
      } else if (status === "CONFIRMED" && matchedAtMs != null) {
        state.confirmedAtMs = Number.isFinite(Number(state.confirmedAtMs))
          ? Math.min(Number(state.confirmedAtMs), matchedAtMs)
          : matchedAtMs;
      }
    });
  }
}

function processUserStreamMessage(msg: any): void {
  if (!msg || typeof msg !== "object") return;
  const eventType = String(msg?.event_type || "").trim().toLowerCase();
  const msgType = String(msg?.type || "").trim().toUpperCase();
  if (msgType === "PONG") return;
  if (eventType === "order") {
    processUserStreamOrderMessage(msg);
    return;
  }
  if (eventType === "trade") {
    processUserStreamTradeMessage(msg);
    return;
  }
}

function userStreamReconnectSoon(): void {
  if (userStreamReconnectTimer) return;
  const delayMs = Math.max(250, userStreamReconnectBackoffMs);
  userStreamReconnectTimer = setTimeout(() => {
    userStreamReconnectTimer = null;
    void ensureUserStreamStarted().catch(() => {});
  }, delayMs);
  userStreamReconnectBackoffMs = Math.min(USER_STREAM_RECONNECT_MAX_MS, Math.floor(userStreamReconnectBackoffMs * 1.6));
}

async function ensureUserStreamStarted(client?: ClobClient | null): Promise<boolean> {
  if (!USER_STREAM_ENABLED) return false;
  if (!process.env.POLY_PRIVATE_KEY) return false;
  const useClient = client || __clobClient || await getClobClient().catch(() => null);
  if (!useClient) return false;
  const markets = await desiredUserStreamConditionIds().catch(() => []);
  if (!markets.length) return false;
  const desiredKey = markets.slice().sort().join(",");
  if (
    desiredKey &&
    userStreamLastDesiredMarketsKey &&
    desiredKey !== userStreamLastDesiredMarketsKey &&
    userStreamWs &&
    (userStreamWs.readyState === WebSocket.OPEN || userStreamWs.readyState === WebSocket.CONNECTING)
  ) {
    try {
      userStreamWs.close();
    } catch {}
    return false;
  }
  if (userStreamWs && userStreamWs.readyState === WebSocket.OPEN && desiredKey === userStreamLastDesiredMarketsKey) return true;
  if (userStreamWs && userStreamWs.readyState === WebSocket.CONNECTING && desiredKey === userStreamLastDesiredMarketsKey) return true;

  const creds = (useClient as any)?.creds;
  if (!creds?.key || !creds?.secret || !creds?.passphrase) return false;
  const ws = new WebSocket(USER_STREAM_URL);
  userStreamWs = ws;
  userStreamLastDesiredMarketsKey = desiredKey;
  ws.on("open", () => {
    userStreamConnected = true;
    userStreamReconnectBackoffMs = 500;
    userStreamReconnectCount += 1;
    const payload = {
      type: "user",
      auth: {
        apiKey: String(creds.key),
        secret: String(creds.secret),
        passphrase: String(creds.passphrase),
      },
      markets,
    };
    try {
      ws.send(JSON.stringify(payload));
      console.log(`[USER STREAM] connected url=${USER_STREAM_URL} markets=${markets.length}`);
    } catch (sendErr: any) {
      console.warn(`[USER STREAM SEND ERROR] ${String(sendErr?.message ?? sendErr)}`);
    }
  });
  ws.on("message", (raw: any) => {
    userStreamLastMsgMs = nowMs();
    userStreamMsgCount += 1;
    let parsed: any = null;
    try {
      parsed = JSON.parse(typeof raw === "string" ? raw : raw?.toString?.("utf8"));
    } catch {
      return;
    }
    if (Array.isArray(parsed)) {
      for (const msg of parsed) processUserStreamMessage(msg);
    } else {
      processUserStreamMessage(parsed);
    }
  });
  ws.on("error", (err: any) => {
    userStreamErrCount += 1;
    console.warn(`[USER STREAM ERROR] ${String(err?.message ?? err)}`);
  });
  ws.on("close", () => {
    userStreamConnected = false;
    userStreamWs = null;
    userStreamReconnectSoon();
  });
  return true;
}

async function maybeWarmUserStream(): Promise<void> {
  if (!USER_STREAM_ENABLED) return;
  if (!process.env.POLY_PRIVATE_KEY) return;
  const shouldWarm =
    !!uiLive.enabled ||
    !!pendingUiLive?.enabled ||
    Array.from(botInstances.values()).some((bot) => String(bot.mode || "").trim().toLowerCase() === "live" && bot.status !== "stopped");
  if (!shouldWarm) return;
  const now = nowMs();
  if (userStreamConnected) return;
  if (userStreamWs && userStreamWs.readyState === WebSocket.CONNECTING) return;
  if (now - Number(userStreamLastWarmAttemptMs || 0) < USER_STREAM_WARM_COOLDOWN_MS) return;
  userStreamLastWarmAttemptMs = now;
  try {
    await ensureUserStreamStarted();
  } catch {}
}

function signedTradeDeltaForMe(tr: any, myAddrs: Set<string>): number {
  const side = String(tr?.side || "").toUpperCase();
  const sz = Number(tr?.size ?? 0);
  if (!Number.isFinite(sz) || sz <= 0) return 0;

  const owner = String(tr?.owner || tr?.taker || tr?.taker_address || tr?.trader || "").toLowerCase();
  const maker = String(tr?.maker_address || tr?.maker || "").toLowerCase();
  const traderSide = String(tr?.trader_side || "").toUpperCase();

  const isMyTaker = myAddrs.has(owner) && traderSide !== "MAKER";
  const isMyMaker = myAddrs.has(maker) && traderSide === "MAKER";
  if (!traderSide) {
    // If trader_side is missing, treat owner/taker as taker by default.
    if (myAddrs.has(owner)) return side === "BUY" ? sz : side === "SELL" ? -sz : 0;
    if (myAddrs.has(maker)) return side === "BUY" ? -sz : side === "SELL" ? sz : 0;
  }
  if (!isMyTaker && !isMyMaker) return 0;

  if (isMyTaker) return side === "BUY" ? sz : side === "SELL" ? -sz : 0;
  return side === "BUY" ? -sz : side === "SELL" ? sz : 0;
}

function coerceTradesList(raw: any): any[] {
  if (Array.isArray(raw)) return raw;
  if (Array.isArray(raw?.data)) return raw.data;
  if (Array.isArray(raw?.items)) return raw.items;
  if (Array.isArray(raw?.trades)) return raw.trades;
  return [];
}

function tradeTsMs(tr: any): number | null {
  const candidates = [
    tr?.match_time,
    tr?.matchTime,
    tr?.matchtime,
    tr?.timestamp,
    tr?.created_at,
    tr?.createdAt,
    tr?.last_update,
    tr?.updated_at,
    tr?.time,
  ];
  for (const candidate of candidates) {
    const parsed = parseEpochMsLike(candidate);
    if (Number.isFinite(Number(parsed)) && Number(parsed) > 0) return Number(parsed);
  }
  return null;
}

