type OperatorNoticeLevel = "info" | "warn" | "error" | "success";
type OperatorNotice = {
  id: string;
  text: string;
  source: string;
  level: OperatorNoticeLevel;
  createdAtMs: number;
  sticky: boolean;
  hostPort: string;
};
function normalizeOperatorNoticeLevel(levelLike: any): OperatorNoticeLevel {
  const level = String(levelLike || "").trim().toLowerCase();
  if (level === "warn" || level === "error" || level === "success") return level;
  return "info";
}
function readOperatorNoticesPayload(): { updatedAtMs: number; items: OperatorNotice[] } {
  try {
    if (!fs.existsSync(OPERATOR_NOTICES_PATH)) return { updatedAtMs: 0, items: [] };
    const parsed = JSON.parse(fs.readFileSync(OPERATOR_NOTICES_PATH, "utf8"));
    const items = Array.isArray(parsed?.items) ? parsed.items : [];
    return {
      updatedAtMs: Number(parsed?.updatedAtMs || 0),
      items: items
        .map((row: any) => ({
          id: String(row?.id || ""),
          text: String(row?.text || "").trim(),
          source: String(row?.source || "operator").trim() || "operator",
          level: normalizeOperatorNoticeLevel(row?.level),
          createdAtMs: Number(row?.createdAtMs || 0),
          sticky: row?.sticky === true,
          hostPort: String(row?.hostPort || PORT),
        }))
        .filter((row: OperatorNotice) => !!row.id && !!row.text),
    };
  } catch {
    return { updatedAtMs: 0, items: [] };
  }
}
function writeOperatorNoticesPayload(payloadLike: any): { updatedAtMs: number; items: OperatorNotice[] } {
  const payload = payloadLike && typeof payloadLike === "object" ? payloadLike : {};
  const items = Array.isArray(payload?.items) ? payload.items : [];
  const normalized = {
    updatedAtMs: Number(payload?.updatedAtMs || nowMs()),
    items: items.slice(0, 20),
  };
  fs.mkdirSync(path.dirname(OPERATOR_NOTICES_PATH), { recursive: true });
  fs.writeFileSync(OPERATOR_NOTICES_PATH, JSON.stringify(normalized, null, 2) + "\n", "utf8");
  return normalized;
}
function appendOperatorNotice(inputLike: any): { updatedAtMs: number; items: OperatorNotice[] } {
  const input = inputLike && typeof inputLike === "object" ? inputLike : {};
  const text = String(input?.text || "").trim();
  if (!text) return readOperatorNoticesPayload();
  const existing = readOperatorNoticesPayload();
  const nextItem: OperatorNotice = {
    id: `note_${nowMs()}_${Math.random().toString(36).slice(2, 8)}`,
    text,
    source: String(input?.source || "operator").trim() || "operator",
    level: normalizeOperatorNoticeLevel(input?.level),
    createdAtMs: nowMs(),
    sticky: input?.sticky === true,
    hostPort: String(PORT),
  };
  const nextItems = [nextItem, ...existing.items].slice(0, 20);
  return writeOperatorNoticesPayload({
    updatedAtMs: nowMs(),
    items: nextItems,
  });
}
