function cloneRecentTradeEventPayload(payloadLike: any) {
  const payload = payloadLike && typeof payloadLike === "object" ? payloadLike : null;
  if (!payload) return null;
  return {
    type: "trade",
    t: Number(payload.t ?? nowMs()),
    iso: payload.iso ?? null,
    event: payload.event ?? null,
    engine: payload.engine ?? null,
    executionMode: payload.executionMode ?? null,
    action: payload.action ?? null,
    strategyLane: payload.strategyLane ?? null,
    market: payload.market && typeof payload.market === "object" ? { ...payload.market } : null,
    st: payload.st && typeof payload.st === "object" ? { ...payload.st } : null,
    ui: payload.ui && typeof payload.ui === "object" ? { ...payload.ui } : null,
    execution: payload.execution && typeof payload.execution === "object" ? { ...payload.execution } : null,
    instanceId: payload.instanceId ?? null,
    bot: payload.bot && typeof payload.bot === "object" ? { ...payload.bot } : null,
    side: payload.side ?? null,
    exitSide: payload.exitSide ?? null,
    exitType: payload.exitType ?? null,
    price: payload.price ?? null,
    entryPx: payload.entryPx ?? null,
    exitPx: payload.exitPx ?? null,
    fillPx: payload.fillPx ?? null,
    actualFillPx: payload.actualFillPx ?? null,
    shares: payload.shares ?? null,
    sharesClosed: payload.sharesClosed ?? null,
    pnlUsd: payload.pnlUsd ?? null,
    notionalUsd: payload.notionalUsd ?? null,
    eventTsMs: payload.eventTsMs ?? null,
    actualFillTsMs: payload.actualFillTsMs ?? null,
    fillTsMs: payload.fillTsMs ?? null,
    signalTsMs: payload.signalTsMs ?? null,
    attemptTsMs: payload.attemptTsMs ?? null,
    entryTsMs: payload.entryTsMs ?? null,
    exitTsMs: payload.exitTsMs ?? null,
    marketSlug: payload.marketSlug ?? null,
    runId: payload.runId ?? null,
    runStartMs: payload.runStartMs ?? null,
    runStartIso: payload.runStartIso ?? null,
  };
}

function recordRecentTradeEvent(instanceIdLike: any, payloadLike: any) {
  const instanceId = String(instanceIdLike || "").trim();
  if (!instanceId) return;
  const event = cloneRecentTradeEventPayload(payloadLike);
  if (!event) return;
  const rows = botRecentTradeEvents.get(instanceId) || [];
  rows.push(event);
  if (rows.length > BOT_RECENT_TRADE_EVENTS_MAX) {
    rows.splice(0, rows.length - BOT_RECENT_TRADE_EVENTS_MAX);
  }
  botRecentTradeEvents.set(instanceId, rows);
}

function getRecentTradeEventsForInstance(instanceIdLike: any) {
  const instanceId = String(instanceIdLike || "").trim();
  if (!instanceId) return [];
  const rows = botRecentTradeEvents.get(instanceId) || [];
  return rows.map((row) => cloneRecentTradeEventPayload(row)).filter(Boolean);
}

function getRecentTradeMarkerVersionForInstance(instanceIdLike: any): number | null {
  const rows = getRecentTradeEventsForInstance(instanceIdLike);
  if (!rows.length) return null;
  const last = rows[rows.length - 1];
  const t = Number(last?.t ?? last?.eventTsMs ?? last?.entryTsMs ?? last?.exitTsMs);
  return Number.isFinite(t) ? t : null;
}

function cloneLiveTradeMarker(markerLike: any) {
  const marker = markerLike && typeof markerLike === "object" ? markerLike : null;
  if (!marker) return null;
  const slug = String(marker.slug ?? marker.sessionSlug ?? "").trim() || null;
  const source = String(marker.source ?? "").trim().toLowerCase() || "trade_event";
  return {
    instanceId: marker.instanceId ?? null,
    slug,
    sessionSlug: slug,
    tsMs: Number(marker.tsMs ?? nowMs()),
    side: marker.side ?? null,
    type: marker.type ?? null,
    markerType: marker.markerType ?? null,
    price: Number.isFinite(Number(marker.price)) ? Number(marker.price) : null,
    shares: Number.isFinite(Number(marker.shares)) ? Number(marker.shares) : null,
    pnlUsd: Number.isFinite(Number(marker.pnlUsd)) ? Number(marker.pnlUsd) : null,
    usdValue: Number.isFinite(Number(marker.usdValue)) ? Number(marker.usdValue) : null,
    seq: Number.isFinite(Number(marker.seq)) ? Number(marker.seq) : null,
    exitType: marker.exitType ?? null,
    event: marker.event ?? null,
    key: marker.key ?? null,
    label: marker.label ?? null,
    source,
  };
}

function getLiveTradeMarkerSeqForInstance(instanceIdLike: any): number {
  const instanceId = String(instanceIdLike || "").trim();
  if (!instanceId) return 0;
  return Math.max(0, Math.floor(Number(botLiveMarkerSeqByInstance.get(instanceId) || 0)));
}

function recordLiveTradeMarker(instanceIdLike: any, markerLike: any) {
  const instanceId = String(instanceIdLike || "").trim();
  if (!instanceId) return null;
  const marker = cloneLiveTradeMarker(markerLike);
  if (!marker) return null;
  const nextSeq = getLiveTradeMarkerSeqForInstance(instanceId) + 1;
  marker.instanceId = instanceId;
  marker.seq = nextSeq;
  marker.key =
    String(marker.key || "").trim() ||
    `${instanceId}:${String(marker.slug || "")}:${String(marker.type || marker.markerType || "event")}:${nextSeq}`;
  const rows = botLiveMarkersByInstance.get(instanceId) || [];
  rows.push(marker);
  if (rows.length > BOT_LIVE_MARKERS_MAX) {
    rows.splice(0, rows.length - BOT_LIVE_MARKERS_MAX);
  }
  botLiveMarkersByInstance.set(instanceId, rows);
  botLiveMarkerSeqByInstance.set(instanceId, nextSeq);
  return cloneLiveTradeMarker(marker);
}

function appendLiveMarkerToCurrentSessionTrace(slugLike: any, markerLike: any) {
  const slug = String(slugLike || "").trim();
  const marker = cloneLiveTradeMarker(markerLike);
  if (!slug || !marker) return false;
  let appended = false;
  const applyToMem = (memMap: Map<string, SessionTraceSeries>) => {
    const mem = memMap.get(slug);
    if (!mem) return;
    const rows = Array.isArray(mem.markers) ? mem.markers : [];
    const key = String(marker.key || "").trim();
    const seq = Math.floor(Number(marker.seq || 0));
    const existingIdx = rows.findIndex((row) => {
      const rowKey = String(row?.key || "").trim();
      if (key && rowKey && rowKey === key) return true;
      const rowSeq = Math.floor(Number(row?.seq || 0));
      return seq > 0 && rowSeq > 0 && rowSeq === seq;
    });
    if (existingIdx >= 0) {
      rows[existingIdx] = marker;
    } else {
      rows.push(marker);
      rows.sort((a, b) => Number(a?.tsMs || 0) - Number(b?.tsMs || 0));
      if (rows.length > BOT_LIVE_MARKERS_MAX) {
        rows.splice(0, rows.length - BOT_LIVE_MARKERS_MAX);
      }
      appended = true;
    }
    mem.markers = rows;
    memMap.set(slug, mem);
  };
  applyToMem(sessionAlgoInputTraceMem);
  applyToMem(sessionTraceMem);
  return appended;
}

function liveTradeMarkerSemanticKey(markerLike: any): string {
  const marker = markerLike && typeof markerLike === "object" ? markerLike : null;
  if (!marker) return "";
  const markerType = String(marker?.markerType || marker?.type || "").trim().toLowerCase();
  const side = String(marker?.side || "").trim().toUpperCase();
  const tsMs = Math.floor(Number(marker?.tsMs || 0));
  const price = Number(marker?.price);
  const exitType = String(marker?.exitType || "").trim().toLowerCase();
  return [
    markerType || "event",
    side || "-",
    Number.isFinite(tsMs) ? String(tsMs) : "0",
    Number.isFinite(price) ? price.toFixed(6) : "nan",
    exitType || "-",
  ].join("|");
}

function ensureRuntimeEntryLiveMarker(
  instanceIdLike: any,
  slugLike: any,
  runtimeLike: any,
  markersLike: any[]
): any[] {
  const instanceId = String(instanceIdLike || "").trim();
  const slug = String(slugLike || "").trim();
  const runtime = runtimeLike && typeof runtimeLike === "object" ? runtimeLike : null;
  const markers = (Array.isArray(markersLike) ? markersLike : [])
    .map((row) => cloneLiveTradeMarker(row))
    .filter(Boolean);
  if (!instanceId || !slug || !runtime || !runtime.entered) return markers;
  const sideRaw = String(runtime?.side || "").trim().toUpperCase();
  const side = sideRaw === "UP" || sideRaw === "DOWN" ? sideRaw : "";
  const entryTsMs = Number(runtime?.entryTsMs);
  const entryPx = Number.isFinite(Number(runtime?.entryPx))
    ? Number(runtime.entryPx)
    : (side === "UP" ? Number(runtime?.upBid) : Number(runtime?.downBid));
  if (!side || !(Number.isFinite(entryTsMs) && entryTsMs > 946684800000) || !Number.isFinite(entryPx)) return markers;
  const alreadyHasEntry = markers.some((row) => {
    if (String(row?.markerType || "").trim().toLowerCase() !== "entry_filled") return false;
    if (String(row?.slug || row?.sessionSlug || "").trim() !== slug) return false;
    const rowSide = String(row?.side || "").trim().toUpperCase();
    return !rowSide || rowSide === side;
  });
  if (alreadyHasEntry) return markers;
  const runtimeMarker = cloneLiveTradeMarker({
    instanceId,
    slug,
    sessionSlug: slug,
    tsMs: entryTsMs,
    side,
    type: "entry_filled",
    markerType: "entry_filled",
    price: entryPx,
    shares: Number.isFinite(Number(runtime?.shares)) ? Number(runtime.shares) : null,
    usdValue:
      Number.isFinite(Number(runtime?.shares)) && Number.isFinite(entryPx)
        ? Number(runtime.shares) * entryPx
        : null,
    event: "enter_runtime_open",
    key: `runtime_open:${instanceId}:${slug}:entry_filled:${Math.floor(entryTsMs)}:${side}:${entryPx.toFixed(6)}`,
    source: "runtime_open_state",
  });
  if (!runtimeMarker) return markers;
  const merged = new Map<string, any>();
  for (const row of markers) {
    const key = String(row?.key || "").trim() || liveTradeMarkerSemanticKey(row);
    if (!key) continue;
    merged.set(key, row);
  }
  const runtimeKey = String(runtimeMarker.key || "").trim() || liveTradeMarkerSemanticKey(runtimeMarker);
  if (runtimeKey) merged.set(runtimeKey, runtimeMarker);
  return Array.from(merged.values()).sort((a, b) => Number(a?.tsMs || 0) - Number(b?.tsMs || 0));
}

function getLiveTradeMarkersForInstance(
  instanceIdLike: any,
  slugLike: any,
  sinceSeqLike: any = null
): any[] {
  const instanceId = String(instanceIdLike || "").trim();
  const slug = String(slugLike || "").trim();
  if (!instanceId || !slug) return [];
  const sinceSeq = Math.max(0, Math.floor(Number(sinceSeqLike || 0)));
  const rows = botLiveMarkersByInstance.get(instanceId) || [];
  return rows
    .filter((row) => String(row?.slug || "").trim() === slug)
    .filter((row) => Math.floor(Number(row?.seq || 0)) > sinceSeq)
    .map((row) => cloneLiveTradeMarker(row))
    .filter(Boolean);
}

async function probeManagedServerPort(portLike: any) {
  const port = Math.floor(Number(portLike));
  const active = HOST_MANAGED_SERVER_PORTS.includes(port);
  if (!active) {
    return {
      port,
      active: false,
      ok: false,
      self: port === Number(PORT),
      slug: null,
      pairLagMs: null,
      streamAgeMs: null,
      quoteGapMs: null,
      streamConnected: null,
    };
  }
  try {
    const { data } = await axios.get(`http://127.0.0.1:${port}/api/health?lite=1`, {
      timeout: 700,
      httpAgent: axios.defaults.httpAgent,
      httpsAgent: axios.defaults.httpsAgent,
      validateStatus: () => true,
    });
    const quote = data?.health?.quoteFeed || {};
    return {
      port,
      active: data?.ok === true,
      ok: data?.ok === true,
      self: port === Number(PORT),
      slug: String(data?.current?.slug || "").trim() || null,
      pairLagMs: Number.isFinite(Number(quote?.pairLagMs)) ? Number(quote.pairLagMs) : null,
      streamAgeMs: Number.isFinite(Number(quote?.streamLastMsgAgeMs)) ? Number(quote.streamLastMsgAgeMs) : null,
      quoteGapMs: Number.isFinite(Number(quote?.quoteGapMsLatest ?? quote?.quoteBroadcastGapMsLatest)) ? Number(quote?.quoteGapMsLatest ?? quote?.quoteBroadcastGapMsLatest) : null,
      streamConnected: quote?.streamConnected === true,
    };
  } catch {
    return {
      port,
      active: false,
      ok: false,
      self: port === Number(PORT),
      slug: null,
      pairLagMs: null,
      streamAgeMs: null,
      quoteGapMs: null,
      streamConnected: null,
    };
  }
}
