function recordBotTickGap(instanceId: string, gapMsRaw: number): void {
  const t = nowMs();
  const gapMs = Number(gapMsRaw);
  if (!Number.isFinite(gapMs) || gapMs < 0) return;
  botTickGapSamples.push({ t, gapMs, instanceId: String(instanceId || "") });
  const cutoff = t - BOT_TICK_GAP_WINDOW_MS;
  while (botTickGapSamples.length && Number(botTickGapSamples[0]?.t || 0) < cutoff) {
    botTickGapSamples.shift();
  }
}

function recordBotTickDuration(instanceId: string, durationMsRaw: number): void {
  const t = nowMs();
  const durationMs = Number(durationMsRaw);
  if (!Number.isFinite(durationMs) || durationMs < 0) return;
  botTickDurationSamples.push({ t, durationMs, instanceId: String(instanceId || "") });
  const cutoff = t - BOT_TICK_GAP_WINDOW_MS;
  while (botTickDurationSamples.length && Number(botTickDurationSamples[0]?.t || 0) < cutoff) {
    botTickDurationSamples.shift();
  }
}

function botTickDurationStatsNow() {
  const now = nowMs();
  const cutoff = now - BOT_TICK_GAP_WINDOW_MS;
  while (botTickDurationSamples.length && Number(botTickDurationSamples[0]?.t || 0) < cutoff) {
    botTickDurationSamples.shift();
  }
  const vals = botTickDurationSamples
    .map((row) => Number(row?.durationMs))
    .filter((v) => Number.isFinite(v))
    .sort((a, b) => a - b);
  if (!vals.length) {
    return {
      windowMs: BOT_TICK_GAP_WINDOW_MS,
      sampleCount: 0,
      latestMs: null as number | null,
      p50Ms: null as number | null,
      p95Ms: null as number | null,
      maxMs: null as number | null,
    };
  }
  const latestMs = Number(botTickDurationSamples[botTickDurationSamples.length - 1]?.durationMs);
  return {
    windowMs: BOT_TICK_GAP_WINDOW_MS,
    sampleCount: vals.length,
    latestMs: Number.isFinite(latestMs) ? latestMs : null,
    p50Ms: percentileFromSorted(vals, 0.5),
    p95Ms: percentileFromSorted(vals, 0.95),
    maxMs: Number.isFinite(vals[vals.length - 1]) ? vals[vals.length - 1] : null,
  };
}

function shouldUseRealtimeQuoteTriggerForBotInstance(instance: Pick<BotInstance, "strategyId" | "status"> | null | undefined): boolean {
  if (!instance) return false;
  if (!BOT_REALTIME_QUOTE_TRIGGER_ENABLED) return false;
  if (!isBotActive(String(instance.status || ""))) return false;
  return shouldUseRealtimeQuoteTriggerForStrategy(instance.strategyId);
}

function scheduleRealtimeQuoteTriggeredBotTick(instanceIdRaw: any, triggerCtxRaw: Partial<QuoteTickTriggerContext> | null | undefined): void {
  const instanceId = String(instanceIdRaw || "").trim();
  if (!instanceId) return;
  const instance = botInstances.get(instanceId);
  if (!instance || !shouldUseRealtimeQuoteTriggerForBotInstance(instance) || String(instance.status || "") === "stopped") return;
  const rt = botRuntimes.get(instanceId) || null;
  const targetSlug = String(rt?.marketSlug || instance.marketSlug || "").trim();
  if (current?.slug && targetSlug && targetSlug !== String(current.slug)) return;
  const triggerCtx: QuoteTickTriggerContext = {
    reason: String(triggerCtxRaw?.reason || "quote_realtime_tick"),
    pairTsMs: Number.isFinite(Number(triggerCtxRaw?.pairTsMs)) ? Number(triggerCtxRaw?.pairTsMs) : null,
    pairSeq: Number.isFinite(Number(triggerCtxRaw?.pairSeq)) ? Number(triggerCtxRaw?.pairSeq) : null,
    source: String(triggerCtxRaw?.source || "") || null,
    pure: !!triggerCtxRaw?.pure,
    synthetic: !!triggerCtxRaw?.synthetic,
    observedAtMs: Number.isFinite(Number(triggerCtxRaw?.observedAtMs)) ? Number(triggerCtxRaw?.observedAtMs) : null,
  };
  const state = botRealtimeQuoteTriggerStateByInstance.get(instanceId) || {
    running: false,
    queued: false,
    lastStartedMs: 0,
    lastPairTsMs: null,
    lastPairSeq: null,
    pendingCtx: null,
  };
  if (
    triggerCtx.pairSeq != null &&
    Number.isFinite(Number(state.lastPairSeq)) &&
    Number(state.lastPairSeq) === triggerCtx.pairSeq &&
    state.running
  ) {
    state.queued = true;
    state.pendingCtx = triggerCtx;
    botRealtimeQuoteTriggerStateByInstance.set(instanceId, state);
    return;
  }
  if (
    Number.isFinite(Number(state.lastStartedMs)) &&
    (nowMs() - Number(state.lastStartedMs)) < BOT_REALTIME_TRIGGER_MIN_MS
  ) {
    state.queued = true;
    if (triggerCtx.pairTsMs != null) state.lastPairTsMs = triggerCtx.pairTsMs;
    if (triggerCtx.pairSeq != null) state.lastPairSeq = triggerCtx.pairSeq;
    state.pendingCtx = triggerCtx;
    botRealtimeQuoteTriggerStateByInstance.set(instanceId, state);
    return;
  }
  if (state.running) {
    state.queued = true;
    if (triggerCtx.pairTsMs != null) state.lastPairTsMs = triggerCtx.pairTsMs;
    if (triggerCtx.pairSeq != null) state.lastPairSeq = triggerCtx.pairSeq;
    state.pendingCtx = triggerCtx;
    botRealtimeQuoteTriggerStateByInstance.set(instanceId, state);
    return;
  }
  state.running = true;
  state.queued = false;
  state.lastStartedMs = nowMs();
  if (triggerCtx.pairTsMs != null) state.lastPairTsMs = triggerCtx.pairTsMs;
  if (triggerCtx.pairSeq != null) state.lastPairSeq = triggerCtx.pairSeq;
  state.pendingCtx = triggerCtx;
  botRealtimeQuoteTriggerStateByInstance.set(instanceId, state);
  setImmediate(() => {
    void tickBotRuntime(instance, triggerCtx)
      .catch(() => {})
      .finally(() => {
        const latest = botRealtimeQuoteTriggerStateByInstance.get(instanceId);
        if (!latest) return;
        const rerun = latest.queued;
        const rerunCtx = latest.pendingCtx;
        latest.running = false;
        latest.queued = false;
        botRealtimeQuoteTriggerStateByInstance.set(instanceId, latest);
        if (rerun && rerunCtx) {
          scheduleRealtimeQuoteTriggeredBotTick(instanceId, {
            ...rerunCtx,
            reason: `${String(rerunCtx.reason || triggerCtx.reason || "quote_realtime_tick")}:queued`,
          });
        }
      });
  });
}

function triggerRealtimeQuoteTriggeredBotTicks(pairRowRaw: Partial<QuotePairCacheRow> | null | undefined, reason: string): void {
  if (!BOT_REALTIME_QUOTE_TRIGGER_ENABLED) return;
  for (const instance of botInstances.values()) {
    if (!shouldUseRealtimeQuoteTriggerForBotInstance(instance)) continue;
    scheduleRealtimeQuoteTriggeredBotTick(instance.instanceId, {
      reason,
      pairTsMs: Number.isFinite(Number(pairRowRaw?.tsMs)) ? Number(pairRowRaw?.tsMs) : null,
      pairSeq: Number.isFinite(Number(pairRowRaw?.seq)) ? Number(pairRowRaw?.seq) : null,
      source: String(pairRowRaw?.source || "") || null,
      pure: !!pairRowRaw?.pure,
      synthetic: !!pairRowRaw?.synthetic,
      observedAtMs: Number.isFinite(Number(pairRowRaw?.observedAtMs)) ? Number(pairRowRaw?.observedAtMs) : null,
    });
  }
}

function botTickGapStatsNow() {
  const now = nowMs();
  const cutoff = now - BOT_TICK_GAP_WINDOW_MS;
  while (botTickGapSamples.length && Number(botTickGapSamples[0]?.t || 0) < cutoff) {
    botTickGapSamples.shift();
  }
  let maxGapMs: number | null = null;
  let latestGapMs: number | null = null;
  for (let i = 0; i < botTickGapSamples.length; i++) {
    const g = Number(botTickGapSamples[i]?.gapMs);
    if (!Number.isFinite(g)) continue;
    if (!Number.isFinite(Number(maxGapMs)) || g > Number(maxGapMs)) maxGapMs = g;
    latestGapMs = g;
  }
  let activeMaxRuntimeAgeMs: number | null = null;
  for (const b of botInstances.values()) {
    if (!isBotActive(b.status) || b.status === "stopped") continue;
    const rt = botRuntimes.get(b.instanceId);
    const last = Number(rt?.lastTickMs);
    if (!Number.isFinite(last) || last <= 0) continue;
    const age = Math.max(0, now - last);
    if (!Number.isFinite(Number(activeMaxRuntimeAgeMs)) || age > Number(activeMaxRuntimeAgeMs)) {
      activeMaxRuntimeAgeMs = age;
    }
  }
  return {
    windowMs: BOT_TICK_GAP_WINDOW_MS,
    sampleCount: botTickGapSamples.length,
    maxGapMs: Number.isFinite(Number(maxGapMs)) ? Number(maxGapMs) : null,
    latestGapMs: Number.isFinite(Number(latestGapMs)) ? Number(latestGapMs) : null,
    activeMaxRuntimeAgeMs: Number.isFinite(Number(activeMaxRuntimeAgeMs)) ? Number(activeMaxRuntimeAgeMs) : null,
  };
}
