function getBotStrategyIntegrity(instance: BotInstance, srt?: BotStrategyRuntime | null): {
  ok: boolean;
  expectedStrategyId: StrategyId;
  expectedStrategyPath: string;
  expectedStrategyHash: string | null;
  loadedStrategyId: string | null;
  loadedStrategyPath: string | null;
  loadedStrategyHash: string | null;
  reason: string | null;
} {
  const expectedStrategyId = normalizeStrategyId(instance?.strategyId);
  const canonical = getCanonicalStrategyArtifact(expectedStrategyId);
  const expectedStrategyPath = String((instance as any)?.strategyPath || canonical.path || "").trim();
  const expectedStrategyHash =
    String((instance as any)?.expectedStrategyHash || "").trim() ||
    String(canonical.hash || "").trim() ||
    null;
  const loadedStrategyId = srt
    ? (String(srt.declaredStrategyId || "").trim() || String(srt.strategyId || "").trim() || null)
    : null;
  const loadedStrategyPath = srt ? String(srt.strategyPath || "").trim() || null : null;
  const loadedStrategyHash = srt ? String(srt.strategyHash || "").trim() || null : null;
  let reason: string | null = null;
  if (!srt) {
    reason = "runtime_missing";
  } else if (loadedStrategyId !== expectedStrategyId) {
    reason = "strategy_id_mismatch";
  } else if (loadedStrategyPath !== expectedStrategyPath) {
    reason = "strategy_path_mismatch";
  } else if (expectedStrategyHash && loadedStrategyHash !== expectedStrategyHash) {
    reason = "strategy_hash_mismatch";
  } else if (!srt.strategy) {
    reason = "strategy_factory_missing";
  } else if (srt.lastError) {
    reason = "runtime_error";
  }
  return {
    ok: !reason,
    expectedStrategyId,
    expectedStrategyPath,
    expectedStrategyHash,
    loadedStrategyId,
    loadedStrategyPath,
    loadedStrategyHash,
    reason,
  };
}

function makeId(prefix: string): string {
  const t = Date.now().toString(36);
  const r = Math.random().toString(36).slice(2, 8);
  return `${prefix}_${t}_${r}`;
}

