function getCanonicalStrategyArtifact(strategyIdRaw: any): {
  strategyId: StrategyId;
  path: string;
  hash: string | null;
} {
  const strategyId = normalizeStrategyId(strategyIdRaw);
  const cacheKey = String(strategyId || "");
  const cached = strategyArtifactCache.get(cacheKey) || null;
  if (cached && cached.path) {
    return {
      strategyId: cached.strategyId,
      path: cached.path,
      hash: cached.hash,
    };
  }
  const pathResolved = String(resolveBotStrategyPath(strategyId, null) || "").trim();
  const hash = pathResolved ? readStrategyFileHash(pathResolved) : null;
  const row = {
    strategyId,
    path: pathResolved,
    hash,
    computedAtMs: nowMs(),
  };
  strategyArtifactCache.set(cacheKey, row);
  return {
    strategyId,
    path: pathResolved,
    hash,
  };
}

function canonicalStrategyPathForDisplay(strategyIdRaw: any, currentPathRaw?: any): string {
  const strict = parseStrategyIdStrict(strategyIdRaw);
  if (strict) return getCanonicalStrategyArtifact(strict).path;
  return String(currentPathRaw || "").trim();
}

function isStrategyAllowedOnThisHost(strategyIdRaw: any): boolean {
  const sid = normalizeStrategyId(strategyIdRaw);
  if (!HOST_STRATEGY_LOCK) return true;
  return sid === HOST_STRATEGY_LOCK;
}

function buildBotStrategyParams(instance: BotInstance): any {
  const rtAny = botRuntimes.get(instance.instanceId) as any;
  const profile = strategyProfileOf(instance.strategyId);
  const savedStrategyState =
    isInflectionPositiveSlopeFamilyStrategy(instance.strategyId)
      ? cloneJsonLike(botStrategyRuntimes.get(instance.instanceId)?.lastSnapshot?.state ?? null, null)
      : null;
  // Strategy-specific param maps prevent accidental cross-pollination.
  if (profile.family === "locker") {
    return {
      // Profit Locker strategy file consumes Kalman-style keys.
      entryBreakoutThr: instance.entry,
      crossReentryThr: instance.entry,
      minEntrySec: instance.minEntrySec,
      // Optional tuning hooks kept explicit for this strategy family.
      hardTpKalman: instance.exit,
      stopLossPx: instance.stop,
      stop: instance.stop,
      // Sizing
      bet: instance.betUsd,
      maxBetUsd: instance.maxBetUsd,
      sizingProfile: String((instance as any).sizingProfile || "").trim().toLowerCase() || null,
      strategyId: instance.strategyId,
      mode: instance.mode,
      initialState: savedStrategyState,
    };
  }
  // Momentum/HC strategy file consumes the noCross + threshold keys.
  const isDerisk = isDeriskFamilyStrategy(instance.strategyId);
  if (isDerisk) {
    return {
      bet: instance.betUsd,
      maxBetUsd: instance.maxBetUsd,
      strategyId: instance.strategyId,
      mode: instance.mode,
    };
  }
  return {
    buyThr: instance.entry,
    deriskThr: undefined,
    sellThr: instance.exit,
    stopThr: instance.stop,
    runnerStopThr: undefined,
    useStop: instance.useStop,
    minEntrySec: instance.minEntrySec,
    stopStartSec: instance.stopStartSec,
    bet: instance.betUsd,
    maxBetUsd: instance.maxBetUsd,
    allowLateBackfill: isLatencyProbeStrategy(instance.strategyId) ? true : undefined,
    noCrossMinSpread: uiPaper.highConfidenceSpread,
    noCrossMinBid: HC_OPPOSITE_MIN_BID,
    strategyId: instance.strategyId,
    mode: instance.mode,
    initialState: isLatencyProbeStrategy(instance.strategyId)
      ? cloneJsonLike(rtAny?.__latencyStrategyState ?? null, null)
      : (isMhc3LatencyStrategy(instance.strategyId)
        ? cloneJsonLike(rtAny?.__mhc3LatencyState ?? null, null)
        : null),
  };
}

function botEntryThresholdForFallback(instance: BotInstance): number {
  if (isLatencyProbeStrategy(instance.strategyId) || isMhc3LatencyStrategy(instance.strategyId)) {
    const botEntry = Number(instance.entry);
    if (Number.isFinite(botEntry)) return botEntry;
  }
  return Number(DERISK_STRICT_ENTRY_THR);
}

function ensureBotStrategyRuntime(instance: BotInstance): BotStrategyRuntime {
  const existing = botStrategyRuntimes.get(instance.instanceId);
  if (
    existing &&
    existing.strategy &&
    existing.strategyId === instance.strategyId &&
    String(existing.strategyPath || "").trim() === String(instance.strategyPath || "").trim() &&
    String(existing.strategyHash || "").trim() === String(instance.expectedStrategyHash || "").trim()
  ) {
    return existing;
  }
  const params = buildBotStrategyParams(instance);
  const out: BotStrategyRuntime = {
    instanceId: instance.instanceId,
    strategyId: instance.strategyId,
    strategyPath: instance.strategyPath,
    strategyHash: null,
    declaredStrategyId: null,
    executionModel: null,
    strategy: null,
    params,
    loadedAtMs: null,
    lastSnapshot: null,
    lastSnapshotAtMs: null,
    lastError: null,
  };
  try {
    const loaded = loadStrategyModuleFromFile(instance.strategyPath);
    const strategy = loaded.factory(params);
    if (!strategy || typeof strategy.onTick !== "function") throw new Error("makeStrategy() must return { onTick() }");
    out.strategyHash = loaded.strategyHash;
    out.declaredStrategyId = loaded.declaredStrategyId;
    out.executionModel = loaded.executionModel;
    out.strategy = strategy;
    out.loadedAtMs = nowMs();
    out.lastError = null;
  } catch (e: any) {
    out.strategy = null;
    out.loadedAtMs = nowMs();
    out.lastError = String(e?.message || e || "strategy load error");
  }
  botStrategyRuntimes.set(instance.instanceId, out);
  return out;
}

function shouldUseDedicatedLatencyEntryExecutor(
  instance: Pick<BotInstance, "strategyId" | "mode" | "watchOnly">
): boolean {
  return isLatencyProbeStrategy(instance.strategyId) && isRealLiveCapableBotInstance(instance);
}

function latencyStrategyStateForRuntime(rt: BotRuntime | null | undefined): any {
  const rtAny = rt as any;
  return cloneJsonLike(rtAny?.__latencyStrategyState ?? null, null);
}

function mhc3LatencyStateForRuntime(rt: BotRuntime | null | undefined): any {
  const rtAny = rt as any;
  return cloneJsonLike(rtAny?.__mhc3LatencyState ?? null, null);
}

function sanitizeMhc3LatencyStateAfterEntryError(stateRaw: any, reasonLike: any): any {
  const state = cloneJsonLike(stateRaw, null);
  if (!state || typeof state !== "object") return null;
  const shared = state.shared && typeof state.shared === "object" ? state.shared : {};
  const pendingEntry = state.pendingEntry && typeof state.pendingEntry === "object" ? state.pendingEntry : null;
  const activeTrade = state.activeTrade && typeof state.activeTrade === "object" ? state.activeTrade : null;
  const prevMode = String(pendingEntry?.mode || activeTrade?.mode || "").toUpperCase();
  const prevSideRaw = String(pendingEntry?.side || activeTrade?.side || "").toUpperCase();
  const prevSide = prevSideRaw === "UP" || prevSideRaw === "DOWN" ? prevSideRaw : null;

  if (prevMode === "BASE") {
    const momentumSide = String(shared.momentumSide || "").toUpperCase();
    if (!shared.momentumStopped && prevSide && momentumSide === prevSide) {
      shared.momentumEntered = false;
      shared.momentumSide = null;
      shared.momentumStopped = false;
      shared.momentumStopElapsedSec = null;
    }
  } else if (prevMode === "NO_CROSS_WINNER") {
    shared.hcEntered = false;
  }

  state.shared = shared;
  state.pendingEntry = null;
  state.activeTrade = null;
  state.lastEntry = null;
  state.lastDecision = {
    kind: "ENTRY_PENDING_RESET",
    reason: String(reasonLike ?? "entry_live_error"),
    prevMode: prevMode || null,
    prevSide: prevSide || null,
  };
  return state;
}

function latencyStrategyAttemptForRuntime(rt: BotRuntime | null | undefined): number {
  const state = latencyStrategyStateForRuntime(rt);
  const attempt = Math.floor(Number(state?.armedAttempt || 1));
  return Math.max(1, Number.isFinite(attempt) ? attempt : 1);
}

function buildLatencyStrategyStateAfterWorkerFill(rt: BotRuntime, payload: any): any {
  const prev = latencyStrategyStateForRuntime(rt) || {};
  const attempt = Math.max(1, Math.floor(Number(payload?.attempt || prev?.armedAttempt || 1)));
  const signalElapsedSec = Number.isFinite(Number(payload?.signalElapsedSec)) ? Number(payload.signalElapsedSec) : null;
  const entryElapsedSec = Number.isFinite(Number(payload?.entryElapsedSec)) ? Number(payload.entryElapsedSec) : signalElapsedSec;
  const side = payload?.side === "UP" || payload?.side === "DOWN" ? payload.side : null;
  const signalPx = Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null;
  const fillPx = Number.isFinite(Number(payload?.fillPx)) ? Number(payload.fillPx) : null;
  const buyThr = Number.isFinite(Number(payload?.buyThr)) ? Number(payload.buyThr) : Number(prev?.activeTrade?.threshold);
  const lastSignal =
    side && signalPx != null
      ? {
          atSec: signalElapsedSec,
          side,
          signalPx,
          threshold: Number.isFinite(buyThr) ? buyThr : null,
          attempt,
        }
      : cloneJsonLike(prev?.lastSignal ?? null, null);
  const lastEntry =
    side && fillPx != null
      ? {
          atSec: entryElapsedSec,
          side,
          entryPx: fillPx,
          attempt,
          threshold: Number.isFinite(buyThr) ? buyThr : null,
          signal: cloneJsonLike(lastSignal, null),
        }
      : cloneJsonLike(prev?.lastEntry ?? null, null);
  const activeTrade =
    side
      ? {
          attempt,
          threshold: Number.isFinite(buyThr) ? buyThr : null,
          side,
          signalSec: signalElapsedSec,
          signalPx,
          entrySec: entryElapsedSec,
          entryPx: fillPx,
        }
      : null;
  return {
    armedAttempt: attempt,
    pendingEntry: false,
    pendingExit: false,
    wasEntered: true,
    activeTrade,
    completedTrades: Array.isArray(prev?.completedTrades) ? cloneJsonLike(prev.completedTrades, []) : [],
    lastSignal,
    lastEntry,
    lastExit: cloneJsonLike(prev?.lastExit ?? null, null),
    lastObservedUp:
      Number.isFinite(Number(payload?.lastObservedUp))
        ? Number(payload.lastObservedUp)
        : (Number.isFinite(Number(prev?.lastObservedUp)) ? Number(prev.lastObservedUp) : null),
    lastObservedDown:
      Number.isFinite(Number(payload?.lastObservedDown))
        ? Number(payload.lastObservedDown)
        : (Number.isFinite(Number(prev?.lastObservedDown)) ? Number(prev.lastObservedDown) : null),
    lastElapsedSec: entryElapsedSec,
  };
}

function applyLatencyEntryWorkerLiveFill(instance: BotInstance, rt: BotRuntime, payload: any): void {
  const side = payload?.side === "UP" || payload?.side === "DOWN" ? payload.side : null;
  const fillPx = Number(payload?.fillPx);
  const shares = Number(payload?.shares);
  if (!side || !(Number.isFinite(fillPx) && fillPx > 0) || !(Number.isFinite(shares) && shares > 0)) return;
  const rtAny = rt as any;
  const actualFillTsMs =
    Number.isFinite(Number(payload?.actualFillTsMs)) && Number(payload.actualFillTsMs) > 0
      ? Number(payload.actualFillTsMs)
      : null;
  const eventTsMs =
    Number.isFinite(Number(payload?.eventTsMs)) && Number(payload.eventTsMs) > 0
      ? Number(payload.eventTsMs)
      : actualFillTsMs;
  const localDetectedAtMs =
    Number.isFinite(Number(payload?.localDetectedAtMs)) && Number(payload.localDetectedAtMs) > 0
      ? Number(payload.localDetectedAtMs)
      : null;
  const localSubmitAtMs =
    Number.isFinite(Number(payload?.localSubmitAtMs)) && Number(payload.localSubmitAtMs) > 0
      ? Number(payload.localSubmitAtMs)
      : null;
  const localAcceptedAtMs =
    Number.isFinite(Number(payload?.localAcceptedAtMs)) && Number(payload.localAcceptedAtMs) > 0
      ? Number(payload.localAcceptedAtMs)
      : null;
  const localFillObservedAtMs =
    Number.isFinite(Number(payload?.localFillObservedAtMs)) && Number(payload.localFillObservedAtMs) > 0
      ? Number(payload.localFillObservedAtMs)
      : (
          Number.isFinite(Number(eventTsMs)) && Number(eventTsMs) > 0
            ? Number(eventTsMs)
            : nowMs()
        );
  const marketTsMs =
    Number.isFinite(Number(payload?.marketTsMs)) && Number(payload.marketTsMs) > 0
      ? Number(payload.marketTsMs)
      : null;
  const actualNotionalUsd =
    Number.isFinite(Number(payload?.actualNotionalUsd)) && Number(payload.actualNotionalUsd) > 0
      ? Number(payload.actualNotionalUsd)
      : (shares * fillPx);
  rt.entered = true;
  rt.side = side;
  rt.entryPx = fillPx;
  rt.entryTsMs = actualFillTsMs ?? nowMs();
  rt.shares = shares;
  rt.notionalUsd = actualNotionalUsd;
  rtAny.buyFilledAtMs = actualFillTsMs ?? eventTsMs ?? nowMs();
  const existingTpOrderId = String(rtAny.tpOrderId || "").trim() || null;
  const existingPendingTpLimitPx =
    Number.isFinite(Number(rtAny.pendingTpLimitPx)) && Number(rtAny.pendingTpLimitPx) > 0
      ? Number(rtAny.pendingTpLimitPx)
      : null;
  const existingPendingTpShares =
    Number.isFinite(Number(rtAny.pendingTpShares)) && Number(rtAny.pendingTpShares) > 0
      ? Number(rtAny.pendingTpShares)
      : null;
  const existingPendingTpExitType = String(rtAny.pendingTpExitType || rtAny.pendingExitType || "").trim() || null;
  const existingTpOrderInFlight = !!rtAny.tpOrderInFlight;
  rtAny.__latencyEntryAttemptedSlug =
    String(payload?.marketSlug || rt.marketSlug || instance.marketSlug || "").trim() ||
    latencyEntryAttemptSlugForRuntime(rt);
  rtAny.__latencyEntryAttemptedSide = side;
  rtAny.__lastLiveEntryResolvedAtMs = nowMs();
  rtAny.positionTokenId = runtimeTokenIdForSide(rt, side) || rtAny.positionTokenId || null;
  rtAny.__pendingEntryLimit = null;
  rtAny.__pendingExitLimit = null;
  rtAny.pendingTpLimitPx = existingPendingTpLimitPx;
  rtAny.pendingTpShares = existingPendingTpShares;
  rtAny.pendingTpExitType = existingPendingTpExitType;
  rtAny.pendingExitType = existingPendingTpExitType;
  rtAny.tpOrderId = existingTpOrderId;
  rtAny.tpOrderInFlight = existingTpOrderInFlight;
  rtAny.__tpAccountedFilledShares = 0;
  clearBotRuntimeRunnerTpArtifacts(rt);
  rtAny.__liveExitInProgress = false;
  rtAny.__lastEntryMode = "LATENCY_TOUCH";
  rtAny.__lastEntrySubtype = null;
  rtAny.__lastExitSide = null;
  rtAny.__lastExitType = null;
  rtAny.__lastExitTsMs = null;
  rtAny.__lastExitSlug = null;
  rtAny.__hcFallbackSameSideStreak = 0;
  rtAny.__latencyStrategyState = buildLatencyStrategyStateAfterWorkerFill(rt, payload);
  botStrategyRuntimes.delete(instance.instanceId);
  markEntrySignalLatency(
    stLive,
    "live",
    side,
    null,
    "latency_worker_fill",
    Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null,
    localDetectedAtMs ?? payload?.signalTsMs ?? null
  );
  markEntrySubmitLatency(stLive, localSubmitAtMs ?? localAcceptedAtMs ?? null);
  finalizeEntryLatency(stLive, localFillObservedAtMs, {
    via: "latency_worker_live_fill",
    entryStyle: String(payload?.entryStyle || "dedicated_worker"),
    orderId: String(payload?.orderId || "").trim() || null,
    signalPx: Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null,
    fillPx,
    localDetectedAtMs,
    localSubmitAtMs,
    localAcceptedAtMs,
    localFillObservedAtMs,
    venueSignalTsMs: marketTsMs,
    venueFillTsMs: actualFillTsMs,
    fillSource: String(payload?.fillSource || "live_exchange"),
  });
  syncHostLiveStateFromBotRuntime(instance, rt, {
    actualFillTsMs,
    entryMode: "LATENCY_TOUCH",
    entrySubtype: null,
    positionTokenId: rtAny.positionTokenId,
  });
  appendBotRunEvent(instance, rt, {
    event: "enter",
    side,
    entryPx: fillPx,
    notionalUsd: actualNotionalUsd,
    shares,
    mode: "LATENCY_TOUCH",
    hcSubtype: null,
    actualFillPx: fillPx,
    executionMode: String(payload?.executionMode || "real"),
    fillSource: String(payload?.fillSource || "live_exchange"),
    signalPx: Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null,
    intendedPx: Number.isFinite(Number(payload?.intendedPx)) ? Number(payload.intendedPx) : null,
    orderType: "MARKET",
    entryStyle: String(payload?.entryStyle || "dedicated_worker"),
    orderId: payload?.orderId ?? null,
    actualFillTsMs,
    eventTsMs: localFillObservedAtMs,
    marketTsMs,
    localDetectedAtMs,
    localSubmitAtMs,
    localAcceptedAtMs,
    localFillObservedAtMs,
    rowTimestampSource: String(payload?.rowTimestampSource || "local_fill_observed"),
  });
  void armInflectionPositiveIterationEntryTpOrders(instance, rt, {
    side,
    entryPx: fillPx,
    shares,
    acceptedAtMs: localAcceptedAtMs,
    actualFillTsMs,
    orderId: payload?.orderId ?? null,
    eventTsMs: localFillObservedAtMs,
    executionMode: String(payload?.executionMode || "real"),
    fillSource: String(payload?.fillSource || "live_exchange"),
    source: "latency_worker_fill",
  });
  rt.lastAction = `enter_${side.toLowerCase()}`;
  rt.lastError = null;
}

function applyLatencyEntryReconciledFill(instance: BotInstance, rt: BotRuntime, payload: any): void {
  const side = payload?.side === "UP" || payload?.side === "DOWN" ? payload.side : null;
  const fillPx = Number(payload?.fillPx);
  const shares = Number(payload?.shares);
  if (!side || !(Number.isFinite(fillPx) && fillPx > 0) || !(Number.isFinite(shares) && shares > 0)) return;
  const rtAny = rt as any;
  const actualFillTsMs =
    Number.isFinite(Number(payload?.actualFillTsMs)) && Number(payload.actualFillTsMs) > 0
      ? Number(payload.actualFillTsMs)
      : null;
  const eventTsMs =
    Number.isFinite(Number(payload?.eventTsMs)) && Number(payload.eventTsMs) > 0
      ? Number(payload.eventTsMs)
      : actualFillTsMs;
  const localDetectedAtMs =
    Number.isFinite(Number(payload?.localDetectedAtMs)) && Number(payload.localDetectedAtMs) > 0
      ? Number(payload.localDetectedAtMs)
      : null;
  const localSubmitAtMs =
    Number.isFinite(Number(payload?.localSubmitAtMs)) && Number(payload.localSubmitAtMs) > 0
      ? Number(payload.localSubmitAtMs)
      : null;
  const localAcceptedAtMs =
    Number.isFinite(Number(payload?.localAcceptedAtMs)) && Number(payload.localAcceptedAtMs) > 0
      ? Number(payload.localAcceptedAtMs)
      : null;
  const localFillObservedAtMs =
    Number.isFinite(Number(payload?.localFillObservedAtMs)) && Number(payload.localFillObservedAtMs) > 0
      ? Number(payload.localFillObservedAtMs)
      : (
          Number.isFinite(Number(eventTsMs)) && Number(eventTsMs) > 0
            ? Number(eventTsMs)
            : nowMs()
        );
  const marketTsMs =
    Number.isFinite(Number(payload?.marketTsMs)) && Number(payload.marketTsMs) > 0
      ? Number(payload.marketTsMs)
      : null;
  const actualNotionalUsd =
    Number.isFinite(Number(payload?.actualNotionalUsd)) && Number(payload.actualNotionalUsd) > 0
      ? Number(payload.actualNotionalUsd)
      : (shares * fillPx);
  rt.entered = true;
  rt.side = side;
  rt.entryPx = fillPx;
  rt.entryTsMs = actualFillTsMs ?? nowMs();
  rt.shares = shares;
  rt.notionalUsd = actualNotionalUsd;
  rtAny.buyFilledAtMs = actualFillTsMs ?? eventTsMs ?? nowMs();
  const existingTpOrderId = String(rtAny.tpOrderId || "").trim() || null;
  const existingPendingTpLimitPx =
    Number.isFinite(Number(rtAny.pendingTpLimitPx)) && Number(rtAny.pendingTpLimitPx) > 0
      ? Number(rtAny.pendingTpLimitPx)
      : null;
  const existingPendingTpShares =
    Number.isFinite(Number(rtAny.pendingTpShares)) && Number(rtAny.pendingTpShares) > 0
      ? Number(rtAny.pendingTpShares)
      : null;
  const existingPendingTpExitType = String(rtAny.pendingTpExitType || rtAny.pendingExitType || "").trim() || null;
  const existingTpOrderInFlight = !!rtAny.tpOrderInFlight;
  rtAny.__latencyEntryAttemptedSlug =
    String(payload?.marketSlug || rt.marketSlug || instance.marketSlug || "").trim() ||
    latencyEntryAttemptSlugForRuntime(rt);
  rtAny.__latencyEntryAttemptedSide = side;
  rtAny.__lastLiveEntryResolvedAtMs = nowMs();
  rtAny.positionTokenId = runtimeTokenIdForSide(rt, side) || rtAny.positionTokenId || null;
  rtAny.__pendingEntryLimit = null;
  rtAny.__pendingExitLimit = null;
  rtAny.pendingTpLimitPx = existingPendingTpLimitPx;
  rtAny.pendingTpShares = existingPendingTpShares;
  rtAny.pendingTpExitType = existingPendingTpExitType;
  rtAny.pendingExitType = existingPendingTpExitType;
  rtAny.tpOrderId = existingTpOrderId;
  rtAny.tpOrderInFlight = existingTpOrderInFlight;
  rtAny.__tpAccountedFilledShares = 0;
  clearBotRuntimeRunnerTpArtifacts(rt);
  rtAny.__liveExitInProgress = false;
  rtAny.__lastEntryMode = "LATENCY_TOUCH";
  rtAny.__lastEntrySubtype = null;
  rtAny.__latencyStrategyState = buildLatencyStrategyStateAfterWorkerFill(rt, payload);
  botStrategyRuntimes.delete(instance.instanceId);
  markEntrySignalLatency(
    stLive,
    "live",
    side,
    null,
    "latency_worker_reconciled_fill",
    Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null,
    localDetectedAtMs ?? payload?.signalTsMs ?? null
  );
  markEntrySubmitLatency(stLive, localSubmitAtMs ?? localAcceptedAtMs ?? null);
  finalizeEntryLatency(stLive, localFillObservedAtMs, {
    via: "latency_worker_reconciled_fill",
    entryStyle: String(payload?.entryStyle || "order_id_reconciled"),
    orderId: String(payload?.orderId || "").trim() || null,
    signalPx: Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null,
    fillPx,
    localDetectedAtMs,
    localSubmitAtMs,
    localAcceptedAtMs,
    localFillObservedAtMs,
    venueSignalTsMs: marketTsMs,
    venueFillTsMs: actualFillTsMs,
    fillSource: String(payload?.fillSource || "live_exchange"),
  });
  syncHostLiveStateFromBotRuntime(instance, rt, {
    actualFillTsMs,
    entryMode: "LATENCY_TOUCH",
    entrySubtype: null,
    positionTokenId: rtAny.positionTokenId,
  });
  appendBotRunEvent(instance, rt, {
    event: "enter",
    side,
    entryPx: fillPx,
    notionalUsd: actualNotionalUsd,
    shares,
    mode: "LATENCY_TOUCH",
    actualFillPx: fillPx,
    executionMode: String(payload?.executionMode || "real"),
    fillSource: String(payload?.fillSource || "live_exchange"),
    signalPx: Number.isFinite(Number(payload?.signalPx)) ? Number(payload.signalPx) : null,
    intendedPx: Number.isFinite(Number(payload?.intendedPx)) ? Number(payload.intendedPx) : null,
    orderType: "MARKET",
    entryStyle: String(payload?.entryStyle || "order_id_reconciled"),
    orderId: payload?.orderId ?? null,
    actualFillTsMs,
    eventTsMs: localFillObservedAtMs,
    marketTsMs,
    localDetectedAtMs,
    localSubmitAtMs,
    localAcceptedAtMs,
    localFillObservedAtMs,
    rowTimestampSource: String(payload?.rowTimestampSource || "local_fill_observed"),
  });
  void armInflectionPositiveIterationEntryTpOrders(instance, rt, {
    side,
    entryPx: fillPx,
    shares,
    acceptedAtMs: localAcceptedAtMs,
    actualFillTsMs,
    orderId: payload?.orderId ?? null,
    eventTsMs: localFillObservedAtMs,
    executionMode: String(payload?.executionMode || "real"),
    fillSource: String(payload?.fillSource || "live_exchange"),
    source: "latency_reconciled_fill",
  });
  rt.lastAction = `enter_${side.toLowerCase()}_reconciled`;
  rt.lastError = null;
}

function stopLatencyEntryWorker(instanceIdRaw: any, reason: string): void {
  const instanceId = String(instanceIdRaw || "").trim();
  if (!instanceId) return;
  cancelLatencyLiveOrderResolution(instanceId);
  const record = latencyEntryWorkerByInstance.get(instanceId);
  if (!record) return;
  latencyEntryWorkerByInstance.delete(instanceId);
  try {
    record.child.send?.({ type: "stop", reason });
  } catch {}
  setTimeout(() => {
    try {
      record.child.kill("SIGTERM");
    } catch {}
  }, 25);
}

function latencyLiveOrderResolutionKey(instanceIdRaw: any, orderIdRaw: any): string {
  return `${String(instanceIdRaw || "").trim()}::${String(orderIdRaw || "").trim()}`;
}

function cancelLatencyLiveOrderResolution(instanceIdRaw: any, orderIdRaw?: any): void {
  const instanceId = String(instanceIdRaw || "").trim();
  if (!instanceId) return;
  if (orderIdRaw != null) {
    const key = latencyLiveOrderResolutionKey(instanceId, orderIdRaw);
    latencyLiveOrderResolutionByKey.delete(key);
    return;
  }
  for (const key of Array.from(latencyLiveOrderResolutionByKey.keys())) {
    if (key.startsWith(`${instanceId}::`)) latencyLiveOrderResolutionByKey.delete(key);
  }
}

function hasPendingLatencyLiveOrderResolution(instanceIdRaw: any): boolean {
  const instanceId = String(instanceIdRaw || "").trim();
  if (!instanceId) return false;
  for (const key of latencyLiveOrderResolutionByKey.keys()) {
    if (key.startsWith(`${instanceId}::`)) return true;
  }
  return false;
}

function hasLiveEnterEventForOrder(instance: BotInstance, orderIdRaw: any): boolean {
  const orderId = String(orderIdRaw || "").trim();
  if (!orderId) return false;
  try {
    return readBotRunEventsCached(instance.runNum).some((row) =>
      String(row?.marketSlug || "").trim() === String(instance.marketSlug || "").trim() &&
      String(row?.event || "").trim().toLowerCase() === "enter" &&
      String(row?.orderId || "").trim() === orderId
    );
  } catch {
    return false;
  }
}

async function resolveLatencyLiveOrderFillByOrderId(instance: BotInstance, meta: LatencyLiveOrderResolutionRecord): Promise<void> {
  const key = latencyLiveOrderResolutionKey(instance.instanceId, meta.orderId);
  if (latencyLiveOrderResolutionByKey.has(key)) return;
  latencyLiveOrderResolutionByKey.set(key, meta);
  try {
    const deadline = nowMs() + LATENCY_LIVE_ORDER_RESOLVE_WINDOW_MS;
    while (nowMs() <= deadline) {
      if (!latencyLiveOrderResolutionByKey.has(key)) return;
      const latestInstance = botInstances.get(instance.instanceId) || instance;
      const rt = botRuntimes.get(instance.instanceId);
      if (!rt) return;
      if (rt.entered || hasLiveEnterEventForOrder(latestInstance, meta.orderId)) {
        latencyLiveOrderResolutionByKey.delete(key);
        return;
      }
      const wsFill = userStreamPrimaryFillSnapshot(meta.orderId);
      if (wsFill) {
        applyLatencyEntryWorkerLiveFill(latestInstance, rt, {
          side: meta.side,
          signalPx: meta.signalPx,
          intendedPx: meta.intendedPx,
          signalTsMs: meta.signalTsMs,
          marketTsMs: meta.marketSignalTsMs,
          localDetectedAtMs: meta.localDetectedAtMs,
          localSubmitAtMs: meta.localSubmitAtMs,
          localAcceptedAtMs: meta.localAcceptedAtMs,
          localFillObservedAtMs: nowMs(),
          fillPx: wsFill.filledPx,
          shares: wsFill.shares,
          orderId: meta.orderId,
          actualFillTsMs: wsFill.filledAtMs,
          eventTsMs: nowMs(),
          executionMode: "real",
          fillSource: "live_exchange",
          entryStyle: "server_user_ws_matched",
          rowTimestampSource: "local_fill_observed",
          actualNotionalUsd:
            Number.isFinite(Number(meta.notionalUsd)) && Number(meta.notionalUsd) > 0
              ? Number(meta.notionalUsd)
              : Number(wsFill.shares) * Number(wsFill.filledPx),
        });
        latencyLiveOrderResolutionByKey.delete(key);
        return;
      }
      const remainingWaitMs = Math.max(1, Math.min(LATENCY_LIVE_ORDER_RESOLVE_POLL_MS, deadline - nowMs()));
      const waitedState = await waitForUserStreamOrderState(
        meta.orderId,
        (state) => {
          if (!state) return false;
          return (
            Number.isFinite(Number(state.firstMatchedAtMs)) &&
            Number(state.firstMatchedAtMs) > 0 &&
            Number.isFinite(Number(state.fillPx)) &&
            Number(state.fillPx) > 0 &&
            Math.max(Number(state.totalMatchedShares || 0), Number(state.orderMatchedShares || 0)) > 0
          );
        },
        remainingWaitMs
      );
      const waitedWsFill = waitedState ? userStreamPrimaryFillSnapshot(meta.orderId) : null;
      if (waitedWsFill) {
        applyLatencyEntryWorkerLiveFill(latestInstance, rt, {
          side: meta.side,
          signalPx: meta.signalPx,
          intendedPx: meta.intendedPx,
          signalTsMs: meta.signalTsMs,
          marketTsMs: meta.marketSignalTsMs,
          localDetectedAtMs: meta.localDetectedAtMs,
          localSubmitAtMs: meta.localSubmitAtMs,
          localAcceptedAtMs: meta.localAcceptedAtMs,
          localFillObservedAtMs: nowMs(),
          fillPx: waitedWsFill.filledPx,
          shares: waitedWsFill.shares,
          orderId: meta.orderId,
          actualFillTsMs: waitedWsFill.filledAtMs,
          eventTsMs: nowMs(),
          executionMode: "real",
          fillSource: "live_exchange",
          entryStyle: "server_user_ws_matched",
          rowTimestampSource: "local_fill_observed",
          actualNotionalUsd:
            Number.isFinite(Number(meta.notionalUsd)) && Number(meta.notionalUsd) > 0
              ? Number(meta.notionalUsd)
              : Number(waitedWsFill.shares) * Number(waitedWsFill.filledPx),
        });
        latencyLiveOrderResolutionByKey.delete(key);
        return;
      }
      try {
        const client = await getClobClient();
        const tokenId = runtimeTokenIdForSide(rt, meta.side) || null;
        const resolvedFill = await resolveLiveOrderFillSnapshot(
          client as any,
          meta.orderId,
          tokenId,
          meta.startedAtMs
        );
        if (
          resolvedFill &&
          Number.isFinite(Number(resolvedFill.filledPx)) &&
          Number(resolvedFill.filledPx) > 0 &&
          Number.isFinite(Number(resolvedFill.shares)) &&
          Number(resolvedFill.shares) > 0
        ) {
          applyLatencyEntryWorkerLiveFill(latestInstance, rt, {
            side: meta.side,
            signalPx: meta.signalPx,
            intendedPx: meta.intendedPx,
            signalTsMs: meta.signalTsMs,
            marketTsMs: meta.marketSignalTsMs,
            localDetectedAtMs: meta.localDetectedAtMs,
            localSubmitAtMs: meta.localSubmitAtMs,
            localAcceptedAtMs: meta.localAcceptedAtMs,
            localFillObservedAtMs: nowMs(),
            fillPx: Number(resolvedFill.filledPx),
            shares: Number(resolvedFill.shares),
            orderId: meta.orderId,
            actualFillTsMs:
              Number.isFinite(Number(resolvedFill.filledAtMs)) && Number(resolvedFill.filledAtMs) > 0
                ? Number(resolvedFill.filledAtMs)
                : null,
            eventTsMs: nowMs(),
            executionMode: "real",
            fillSource:
              resolvedFill.source === "trade_history"
                ? "live_exchange_trade_history"
                : "live_exchange",
            entryStyle:
              resolvedFill.source === "trade_history"
                ? "server_trade_history_order_id"
                : (resolvedFill.source === "order_status" ? "order_id_resolver" : "server_user_ws_matched"),
            rowTimestampSource: "local_fill_observed",
            actualNotionalUsd:
              Number.isFinite(Number(meta.notionalUsd)) && Number(meta.notionalUsd) > 0
                ? Number(meta.notionalUsd)
                : Number(resolvedFill.shares) * Number(resolvedFill.filledPx),
          });
          latencyLiveOrderResolutionByKey.delete(key);
          return;
        }
      } catch {}
      await sleep(LATENCY_LIVE_ORDER_RESOLVE_POLL_MS);
    }
  } finally {
    latencyLiveOrderResolutionByKey.delete(key);
  }
}

function shouldKeepFilledLatencyEntryWorker(record: LatencyEntryWorkerRecord | null | undefined): boolean {
  if (!record || record.phase !== "filled") return false;
  return (nowMs() - Number(record.phaseAtMs || 0)) <= LATENCY_ENTRY_WORKER_KEEP_FILLED_MS;
}

function latencyEntryAttemptSlugForRuntime(rt: BotRuntime | null | undefined): string | null {
  const slug = String((rt as any)?.__latencyEntryAttemptedSlug || "").trim();
  return slug || null;
}

function markLatencyEntryAttemptForRuntime(
  rt: BotRuntime | null | undefined,
  slugLike: any,
  sideLike: any
): void {
  if (!rt) return;
  const slug = String(slugLike || "").trim();
  if (!slug) return;
  const sideRaw = String(sideLike || "").trim().toUpperCase();
  const side = sideRaw === "UP" || sideRaw === "DOWN" ? sideRaw : null;
  (rt as any).__latencyEntryAttemptedSlug = slug;
  if (side) (rt as any).__latencyEntryAttemptedSide = side;
}

function handleLatencyEntryWorkerMessage(instanceIdRaw: any, workerIdRaw: any, msg: any): void {
  const instanceId = String(instanceIdRaw || "").trim();
  const workerId = String(workerIdRaw || "").trim();
  if (!instanceId || !workerId || !msg || typeof msg !== "object") return;
  const record = latencyEntryWorkerByInstance.get(instanceId);
  if (!record || record.workerId !== workerId) return;
  const instance = botInstances.get(instanceId);
  const rt = botRuntimes.get(instanceId);
  if (!instance || !rt) return;
  const rtAny = rt as any;
  if (msg.type === "event") {
    const ev = String(msg?.event?.event || "").toLowerCase();
    if (ev) {
      logInfo(
        `LATENCY WORKER EVENT | inst=${instance.instanceId} run=${instance.runNum} ` +
        `event=${ev} side=${String(msg?.event?.side || "") || "-"} ` +
        `reason=${String(msg?.event?.reason || msg?.event?.entryBlockReason || "") || "-"}`
      );
    }
    const sideRaw = String(msg?.event?.side || "").trim().toUpperCase();
    const side = sideRaw === "UP" || sideRaw === "DOWN" ? (sideRaw as OutcomeSide) : null;
    const signalPx = Number.isFinite(Number(msg?.event?.signalPx)) ? Number(msg.event.signalPx) : null;
    const localDetectedAtMs =
      Number.isFinite(Number(msg?.event?.localDetectedAtMs)) && Number(msg.event.localDetectedAtMs) > 0
        ? Number(msg.event.localDetectedAtMs)
        : (
            Number.isFinite(Number(msg?.event?.signalTsMs)) && Number(msg.event.signalTsMs) > 0
              ? Number(msg.event.signalTsMs)
              : null
          );
    const localSubmitAtMs =
      Number.isFinite(Number(msg?.event?.localSubmitAtMs)) && Number(msg.event.localSubmitAtMs) > 0
        ? Number(msg.event.localSubmitAtMs)
        : null;
    if (ev === "enter_signal" || ev === "enter_order" || ev === "entry_blocked") {
      (rt as any).__latencyMeasuredSessionSlug = String(rt.marketSlug || instance.marketSlug || "").trim() || null;
    }
    if (ev === "enter_signal" && side) {
      markLatencyEntryAttemptForRuntime(
        rt,
        String(msg?.event?.marketSlug || rt.marketSlug || instance.marketSlug || "").trim(),
        side
      );
      stLive.buyAttemptedSessionSlug =
        String(msg?.event?.marketSlug || rt.marketSlug || instance.marketSlug || "").trim() ||
        stLive.buyAttemptedSessionSlug ||
        null;
      stLive.buyAttemptedThisSession = true;
      markEntrySignalLatency(stLive, "live", side, null, "latency_worker_signal", signalPx, localDetectedAtMs);
    } else if (ev === "enter_order") {
      if (side) {
        markEntrySignalLatency(stLive, "live", side, null, "latency_worker_signal", signalPx, localDetectedAtMs);
      }
      markEntrySubmitLatency(
        stLive,
        localSubmitAtMs ??
          (
            Number.isFinite(Number(msg?.event?.localAcceptedAtMs)) && Number(msg.event.localAcceptedAtMs) > 0
              ? Number(msg.event.localAcceptedAtMs)
              : null
          )
      );
    } else if (ev === "entry_blocked" || ev === "enter_order_cancel") {
      clearEntryLatency(stLive);
    }
    appendBotRunEvent(instance, rt, msg.event || {});
    if (ev === "enter_order") {
      stLive.buyAttemptedSessionSlug = String(rt.marketSlug || instance.marketSlug || "").trim() || stLive.buyAttemptedSessionSlug || null;
      stLive.buyAttemptedThisSession = true;
      markLatencyEntryAttemptForRuntime(
        rt,
        String(msg?.event?.marketSlug || rt.marketSlug || instance.marketSlug || "").trim() ||
          latencyEntryAttemptSlugForRuntime(rt),
        side || rtAny.__latencyEntryAttemptedSide || null
      );
      const orderId = String(msg?.event?.orderId || "").trim();
      if (orderId && side) {
        const earlyTpEntryPx =
          Number.isFinite(Number(msg?.event?.intendedPx)) && Number(msg.event.intendedPx) > 0
            ? Number(msg.event.intendedPx)
            : (Number.isFinite(Number(signalPx)) && Number(signalPx) > 0 ? Number(signalPx) : NaN);
        const earlyTpNotionalUsd =
          Number.isFinite(Number(msg?.event?.notionalUsd)) && Number(msg.event.notionalUsd) > 0
            ? Number(msg.event.notionalUsd)
            : Math.max(1, Number(instance.betUsd || 1));
        const earlyTpShares = estimatedLiveSharesForNotional(earlyTpNotionalUsd, earlyTpEntryPx);
        const acceptedAtMs =
          Number.isFinite(Number(msg?.event?.localAcceptedAtMs)) && Number(msg.event.localAcceptedAtMs) > 0
            ? Number(msg.event.localAcceptedAtMs)
            : (
                Number.isFinite(Number(msg?.event?.venueOrderAcceptedAtMs)) && Number(msg.event.venueOrderAcceptedAtMs) > 0
                  ? Number(msg.event.venueOrderAcceptedAtMs)
                  : null
              );
        if (requiresImmediateVenueTpProtection(instance.strategyId) && earlyTpShares > 0) {
          void armBotRuntimeImmediateTpOrder(instance, rt, {
            side,
            entryPx: earlyTpEntryPx,
            shares: earlyTpShares,
            enterModeLike: "LATENCY_TOUCH",
            acceptedAtMs,
            buyOrderId: orderId,
            source: "latency_worker_enter_order",
            retryAttempts: 2,
          });
        }
        void resolveLatencyLiveOrderFillByOrderId(instance, {
          instanceId: instance.instanceId,
          runNum: instance.runNum,
          marketSlug: String(msg?.event?.marketSlug || rt.marketSlug || instance.marketSlug || "").trim(),
          side,
          orderId,
          signalPx,
          signalTsMs:
            Number.isFinite(Number(msg?.event?.signalTsMs)) && Number(msg.event.signalTsMs) > 0
              ? Number(msg.event.signalTsMs)
              : (
                  Number.isFinite(Number(localDetectedAtMs)) && Number(localDetectedAtMs) > 0
                    ? Number(localDetectedAtMs)
                    : null
                ),
          marketSignalTsMs:
            Number.isFinite(Number(msg?.event?.marketTsMs)) && Number(msg.event.marketTsMs) > 0
              ? Number(msg.event.marketTsMs)
              : null,
          localDetectedAtMs,
          intendedPx: Number.isFinite(Number(msg?.event?.intendedPx)) ? Number(msg.event.intendedPx) : null,
          notionalUsd: Number.isFinite(Number(msg?.event?.notionalUsd)) ? Number(msg.event.notionalUsd) : null,
          orderPlacedAtMs:
            Number.isFinite(Number(msg?.event?.venueOrderAcceptedAtMs)) && Number(msg.event.venueOrderAcceptedAtMs) > 0
              ? Number(msg.event.venueOrderAcceptedAtMs)
              : null,
          localSubmitAtMs,
          localAcceptedAtMs:
            Number.isFinite(Number(msg?.event?.localAcceptedAtMs)) && Number(msg.event.localAcceptedAtMs) > 0
              ? Number(msg.event.localAcceptedAtMs)
              : null,
          startedAtMs: nowMs(),
        });
      }
    }
    return;
  }
  if (msg.type === "ready") {
    record.phase = "running";
    record.phaseAtMs = nowMs();
    latencyEntryWorkerByInstance.set(instanceId, record);
    rt.lastAction = "latency_worker_ready";
    logInfo(`LATENCY WORKER READY | inst=${instance.instanceId} run=${instance.runNum} worker=${workerId}`);
    return;
  }
  if (msg.type === "filled") {
    record.phase = "filled";
    record.phaseAtMs = nowMs();
    latencyEntryWorkerByInstance.set(instanceId, record);
    cancelLatencyLiveOrderResolution(instanceId, msg?.payload?.orderId);
    (rt as any).__latencyMeasuredSessionSlug = String(rt.marketSlug || instance.marketSlug || "").trim() || null;
    applyLatencyEntryWorkerLiveFill(instance, rt, msg.payload || {});
    return;
  }
  if (msg.type === "done") {
    record.phase = "done";
    record.phaseAtMs = nowMs();
    latencyEntryWorkerByInstance.set(instanceId, record);
    rt.lastAction = `latency_worker_${String(msg.reason || "done")}`;
    logInfo(
      `LATENCY WORKER DONE | inst=${instance.instanceId} run=${instance.runNum} ` +
      `worker=${workerId} reason=${String(msg.reason || "done")}`
    );
    if (String(msg.reason || "").trim() !== "filled_confirmed") clearEntryLatency(stLive);
    return;
  }
  if (msg.type === "fatal") {
    rt.lastError = String(msg.error || "latency_worker_error");
    rt.lastAction = "latency_worker_error";
    instance.lastError = rt.lastError;
    botInstances.set(instanceId, instance);
    logWarn(
      `LATENCY WORKER FATAL | inst=${instance.instanceId} run=${instance.runNum} ` +
      `worker=${workerId} error=${rt.lastError}`
    );
    clearEntryLatency(stLive);
    return;
  }
}

async function ensureLatencyEntryWorkerForBot(instance: BotInstance, rt: BotRuntime): Promise<void> {
  if (!shouldUseDedicatedLatencyEntryExecutor(instance)) return;
  if (!shouldUseRealLiveExecutionForBot(instance) || instance.watchOnly || rt.entered) return;
  await resolveRuntimeMarketMeta(rt);
  const upToken = String(rt.upToken || "").trim();
  const downToken = String(rt.downToken || "").trim();
  const marketSlug = String(rt.marketSlug || "").trim();
  if (!upToken || !downToken || !marketSlug) return;
  if (latencyEntryAttemptSlugForRuntime(rt) === marketSlug) return;
  if ((stLive.buyAttemptedSessionSlug ?? null) === marketSlug) {
    if (stLive.buyAttemptedThisSession || stLive.buyFilledThisSession) return;
  }
  if (String((rt as any).__latencyMeasuredSessionSlug || "").trim() === marketSlug) return;
  const conditionId = await resolveConditionIdForSlug(marketSlug).catch(() => null);
  if (!conditionId) return;
  const state = latencyStrategyStateForRuntime(rt);
  const attempt = latencyStrategyAttemptForRuntime(rt);
  const configKey = [
    marketSlug,
    upToken,
    downToken,
    conditionId,
    String(attempt),
    roundTo6(Number(instance.entry || 0)),
    roundTo6(Number(instance.exit || 0)),
    roundTo6(Number(instance.betUsd || 0)),
  ].join("|");
  const existing = latencyEntryWorkerByInstance.get(instance.instanceId);
  if (existing && existing.configKey === configKey) return;
  if (existing) stopLatencyEntryWorker(instance.instanceId, "config_changed");
  const lastSpawnMs = Number((rt as any).__latencyEntryWorkerLastSpawnMs || 0);
  if (Number.isFinite(lastSpawnMs) && (nowMs() - lastSpawnMs) < LATENCY_ENTRY_WORKER_SPAWN_COOLDOWN_MS) return;
  const workerId = makeId("latw");
  const cfg = {
    workerId,
    instanceId: instance.instanceId,
    runNum: instance.runNum,
    marketSlug,
    marketStartMs: rt.marketStartMs,
    marketEndMs: rt.marketEndMs,
    conditionId,
    upToken,
    downToken,
    buyThr: Number(instance.entry),
    sellThr: Number(instance.exit),
    stopThr: Number(instance.stop),
    betUsd: Number(instance.betUsd),
    allowLateBackfill: isLatencyProbeStrategy(instance.strategyId),
    attempt,
    lastObservedUp: Number.isFinite(Number(state?.lastObservedUp)) ? Number(state.lastObservedUp) : null,
    lastObservedDown: Number.isFinite(Number(state?.lastObservedDown)) ? Number(state.lastObservedDown) : null,
  };
  const child = fork(LATENCY_ENTRY_WORKER_FILE, [], {
    cwd: process.cwd(),
    env: {
      ...process.env,
      LATENCY_ENTRY_WORKER_CONFIG: JSON.stringify(cfg),
    },
    stdio: ["ignore", "pipe", "pipe", "ipc"],
  });
  child.stdout?.on("data", (buf: Buffer | string) => {
    const text = String(buf || "").trim();
    if (text) logInfo(`[LATENCY WORKER ${instance.instanceId}] ${text}`);
  });
  child.stderr?.on("data", (buf: Buffer | string) => {
    const text = String(buf || "").trim();
    if (text) logWarn(`[LATENCY WORKER ${instance.instanceId}] ${text}`);
  });
  child.on("message", (msg: any) => {
    handleLatencyEntryWorkerMessage(instance.instanceId, workerId, msg);
  });
  child.on("exit", (code: number | null, signal: NodeJS.Signals | null) => {
    const currentRecord = latencyEntryWorkerByInstance.get(instance.instanceId);
    if (currentRecord && currentRecord.workerId === workerId) {
      latencyEntryWorkerByInstance.delete(instance.instanceId);
    }
    const liveRt = botRuntimes.get(instance.instanceId);
    if (
      liveRt &&
      !(currentRecord && currentRecord.phase === "filled") &&
      String(signal || "") !== "SIGTERM" &&
      Number(code ?? 0) !== 0
    ) {
      liveRt.lastError = `latency_worker_exit code=${String(code)} signal=${String(signal || "")}`;
      liveRt.lastAction = "latency_worker_exit";
    }
  });
  latencyEntryWorkerByInstance.set(instance.instanceId, {
    workerId,
    child,
    configKey,
    marketSlug,
    attempt,
    phase: "starting",
    phaseAtMs: nowMs(),
  });
  (rt as any).__latencyEntryWorkerLastSpawnMs = nowMs();
}

type ServerManagedDeriskConfig = {
  buyThr: number;
  deriskThr: number;
  deriskMode: "notional" | "fraction";
  deriskFraction: number;
  sellThr: number;
  stopThr: number;
  runnerStopThr: number;
  trade3Enabled: boolean;
  trade3EntryThr: number;
  trade3SellThr: number;
  trade3StopThr: number;
  strategyHash: string | null;
};

function getServerManagedDeriskConfig(
  instance: BotInstance,
  srt: BotStrategyRuntime
): ServerManagedDeriskConfig {
  let snap: any = srt?.lastSnapshot ?? null;
  if (!snap && srt?.strategy && typeof srt.strategy.snapshot === "function") {
    try {
      snap = srt.strategy.snapshot();
      srt.lastSnapshot = snap;
    } catch {
      snap = null;
    }
  }
  const cfg = snap && typeof snap === "object" ? (snap as any).cfg : null;
  const isTrade3 = normalizeStrategyId(instance.strategyId) === "derisk_trade3";
  const buyThr = clamp01(Number((cfg as any)?.buyThr));
  const deriskThr = clamp01(Number((cfg as any)?.deriskThr));
  const sellThr = clamp01(Number((cfg as any)?.sellThr));
  const stopThr = clamp01(Number((cfg as any)?.stopThr));
  const runnerStopThr = clamp01(Number((cfg as any)?.runnerStopThr));
  const trade3EntryThr = clamp01(Number((cfg as any)?.trade3EntryThr));
  const trade3SellThr = clamp01(Number((cfg as any)?.trade3SellThr));
  const trade3StopThr = clamp01(Number((cfg as any)?.trade3StopThr));
  const deriskModeRaw = String((cfg as any)?.deriskMode || "").trim().toLowerCase();
  const deriskFractionRaw = Number((cfg as any)?.deriskFraction);
  return {
    buyThr: Number.isFinite(buyThr) ? buyThr : DERISK_STRICT_ENTRY_THR,
    deriskThr: Number.isFinite(deriskThr) ? deriskThr : DERISK_STRICT_DERISK_THR,
    deriskMode: deriskModeRaw === "fraction" ? "fraction" : "notional",
    deriskFraction:
      Number.isFinite(deriskFractionRaw) && deriskFractionRaw > 0
        ? Math.max(0, Math.min(1, deriskFractionRaw))
        : 0.75,
    sellThr: Number.isFinite(sellThr) ? sellThr : DERISK_STRICT_TP_THR,
    stopThr: Number.isFinite(stopThr) ? stopThr : DERISK_STRICT_STOP_THR,
    runnerStopThr: Number.isFinite(runnerStopThr) ? runnerStopThr : DERISK_STRICT_RUNNER_STOP_THR,
    trade3Enabled: Boolean((cfg as any)?.trade3Enabled) && isTrade3,
    trade3EntryThr: Number.isFinite(trade3EntryThr) ? trade3EntryThr : 0.68,
    trade3SellThr: Number.isFinite(trade3SellThr) ? trade3SellThr : 0.96,
    trade3StopThr: Number.isFinite(trade3StopThr) ? trade3StopThr : 0.39,
    strategyHash: String(srt?.strategyHash || "").trim() || null,
  };
}

function computeDeriskSharesToSell(
  shares: number,
  entryPx: number,
  deriskPx: number,
  notionalUsd: number,
  deriskMode: "notional" | "fraction",
  deriskFraction: number
): number {
  const curShares = Number(shares);
  const epx = Number(entryPx);
  const dpx = Number(deriskPx);
  if (!(Number.isFinite(curShares) && curShares > 0 && Number.isFinite(dpx) && dpx > 0)) return 0;
  if (deriskMode === "fraction") {
    const frac = Number.isFinite(Number(deriskFraction)) ? Math.max(0, Math.min(1, Number(deriskFraction))) : 0.75;
    return Math.max(0, Math.min(curShares, curShares * frac));
  }
  let principalUsd = Number(notionalUsd);
  if (!(Number.isFinite(principalUsd) && principalUsd > 0) && Number.isFinite(epx) && epx > 0) {
    principalUsd = curShares * epx;
  }
  if (!(Number.isFinite(principalUsd) && principalUsd > 0)) return 0;
  return Math.max(0, Math.min(curShares, principalUsd / dpx));
}

function activeBotInstances(): BotInstance[] {
  return Array.from(botInstances.values()).filter((b) => b.status !== "stopped");
}

function hasActiveLiveBotInstances(): boolean {
  return activeBotInstances().some((b) => String(b?.mode || "").toLowerCase() === "live");
}

function hasActiveExecutionBotInstances(): boolean {
  return activeBotInstances().some((b) => isBotActive(b.status) && b.status !== "stopped" && !b.watchOnly);
}

function hasActiveRealLiveExecutionBots(): boolean {
  return activeBotInstances().some((b) => shouldUseRealLiveExecutionForBot(b));
}

function hostGlobalLiveEngineHasVisibleState(): boolean {
  return !!(
    uiLive.enabled ||
    (stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) ||
    !!stLive.enterInFlight ||
    !!stLive.exitInFlight ||
    !!stLive.tpOrderInFlight ||
    !!String(stLive.tpOrderId || "").trim() ||
    !!String(stLive.lastAction || "").trim() ||
    !!String(stLive.lastError || "").trim()
  );
}

function shouldRunHostGlobalLiveMaintenance(): boolean {
  return !!(
    uiLive.enabled ||
    hasActiveRealLiveExecutionBots() ||
    hostGlobalLiveEngineHasVisibleState()
  );
}

async function disableOrphanHostGlobalLiveEngine(reason: string): Promise<void> {
  const resolvedReason = String(reason || "no_active_live_bots").trim() || "no_active_live_bots";
  if (!uiLive.enabled && !hostGlobalLiveEngineHasVisibleState()) return;
  console.warn(`[LIVE HOST FAILSAFE] disabling orphan host-global live engine reason=${resolvedReason}`);
  uiLive.enabled = false;
  if (pendingUiLive) pendingUiLive.enabled = false;
  liveManualEnabledOverride = false;
  stLive.enterInFlight = false;
  stLive.exitInFlight = false;
  stLive.tpOrderInFlight = false;
  stLive.lastError = liveKillSwitchErrorMessage(`${resolvedReason}:host_global_without_live_bot`);
  stLive.lastAction = "host_global_live_autodisabled_no_active_bot";
  try {
    await enforceLiveDisableKillSwitch(`${resolvedReason}_host_global_without_live_bot`);
  } catch (e: any) {
    console.warn(`[LIVE HOST FAILSAFE] flatten err=${String(e?.message ?? e)}`);
  }
  persistMultiMarketState();
  broadcastState();
  writeRuntimeStateSnapshot();
}

let liveManualEnabledOverride: boolean | null = null;

function ensureLiveEngineEnabledForActiveLiveBots(reason: string): void {
  if (!hasActiveLiveBotInstances()) return;
  console.log(
    `[LIVE AUTO-ENABLE BLOCKED] reason=${reason} liveEnabled=${uiLive.enabled} ` +
    `manualOverride=${liveManualEnabledOverride === null ? "null" : String(liveManualEnabledOverride)} ` +
    `(active live bots do not force-enable live trading)`
  );
}

function countByStrategy(strategyId: StrategyId): number {
  return activeBotInstances().filter((b) => b.strategyId === strategyId).length;
}

function currentGlobalOpenNotionalUsd(): number {
  let total = 0;
  for (const rt of botRuntimes.values()) {
    if (rt.entered && Number.isFinite(Number(rt.notionalUsd))) total += Number(rt.notionalUsd);
  }
  return total;
}

function botRunDir(runNum: number): string {
  return path.join(TRADE_LOG_DIR, "multi_runs", `run_${Math.floor(runNum)}`);
}

function maxPersistedBotRunNum(): number {
  try {
    const multiRunsDir = path.join(TRADE_LOG_DIR, "multi_runs");
    if (!fs.existsSync(multiRunsDir)) return 0;
    let maxRunNum = 0;
    for (const name of fs.readdirSync(multiRunsDir)) {
      const m = /^run_(\d+)$/i.exec(String(name || "").trim());
      if (!m) continue;
      const runNum = Math.floor(Number(m[1]));
      if (Number.isFinite(runNum) && runNum > maxRunNum) maxRunNum = runNum;
    }
    return maxRunNum;
  } catch {
    return 0;
  }
}

function allocateNextBotRunNum(): number {
  const persistedMax = maxPersistedBotRunNum();
  const nextRunNum = Math.max(0, Number(BOT_RUN_SEQ || 0), Number(persistedMax || 0)) + 1;
  BOT_RUN_SEQ = nextRunNum;
  return nextRunNum;
}

function botRunTelemetryPath(runNum: number): string {
  return path.join(botRunDir(runNum), "telemetry.jsonl");
}

function botRunSessionParityDir(runNum: number): string {
  return path.join(botRunDir(runNum), "session_parity");
}

function botRunSessionParityJsonPath(runNum: number): string {
  return path.join(botRunSessionParityDir(runNum), "latest.json");
}

function botRunSessionParityHtmlPath(runNum: number): string {
  return path.join(botRunSessionParityDir(runNum), "latest.html");
}

function botRunSessionParityGoodJsonPath(runNum: number): string {
  return path.join(botRunSessionParityDir(runNum), "latest_good.json");
}

function botRunSessionParityGoodHtmlPath(runNum: number): string {
  return path.join(botRunSessionParityDir(runNum), "latest_good.html");
}

function atomicWriteUtf8(filePath: string, content: string): void {
  const dir = path.dirname(filePath);
  fs.mkdirSync(dir, { recursive: true });
  const tmpPath = `${filePath}.tmp_${process.pid}_${Date.now()}`;
  fs.writeFileSync(tmpPath, content, "utf8");
  fs.renameSync(tmpPath, filePath);
}

function botRunSessionVenueTruthPath(runNum: number): string {
  return path.join(botRunDir(runNum), "session_venue_truth.jsonl");
}

function sanitizeFileSegment(v: any): string {
  return String(v ?? "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, "_")
    .replace(/^_+|_+$/g, "") || "unknown";
}

function botRunIndexPath(strategyId: string, runNum: number): string {
  const sid = sanitizeFileSegment(strategyId);
  const rn = Math.floor(Number(runNum));
  return path.join(botRunDir(rn), `index_${sid}_run_${rn}.json`);
}

function expectedLatestClosedSessionSlugForInstance(instance: BotInstance | null | undefined): string {
  try {
    const currentSlug = String(instance?.marketSlug || "").trim().toLowerCase();
    const prefix = currentSlug.replace(/-\d{10}$/, "");
    if (!prefix) return "";
    const intervalMs = inferSessionIntervalMsFromSlug(currentSlug || prefix);
    if (!(Number.isFinite(intervalMs) && intervalMs > 0)) return "";
    const latestClosedStartMs = (Math.floor(Date.now() / intervalMs) * intervalMs) - intervalMs;
    if (!(Number.isFinite(latestClosedStartMs) && latestClosedStartMs > 0)) return "";
    return `${prefix}-${Math.floor(latestClosedStartMs / 1000)}`;
  } catch {
    return "";
  }
}

function runIndexNeedsRefresh(instance: BotInstance | null | undefined, payloadLike: any): boolean {
  try {
    const expectedSlug = expectedLatestClosedSessionSlugForInstance(instance);
    if (!expectedSlug) return false;
    const rows = Array.isArray(payloadLike?.sessions) ? payloadLike.sessions : [];
    if (!rows.length) return true;
    const newestSlug = String(rows[0]?.slug || "").trim().toLowerCase();
    if (!newestSlug) return true;
    const expectedSec = Number(expectedSlug.match(/-(\d{10})$/)?.[1] || 0);
    const newestSec = Number(newestSlug.match(/-(\d{10})$/)?.[1] || 0);
    if (!(expectedSec > 0 && newestSec > 0)) return false;
    return newestSec < expectedSec;
  } catch {
    return false;
  }
}

function ensureFreshBotRunIndex(instance: BotInstance | null | undefined, rt: BotRuntime | null): string {
  const runNum = Math.floor(Number(instance?.runNum));
  const strategyId = String(instance?.strategyId || "").trim();
  if (!(Number.isFinite(runNum) && runNum > 0 && strategyId)) return "";
  const idxPath = botRunIndexPath(strategyId, runNum);
  const payload = fs.existsSync(idxPath) ? (readRunIndexPayloadCached(idxPath) || null) : null;
  if (HOT_SERVICE_MODE && fs.existsSync(idxPath)) return idxPath;
  if (!fs.existsSync(idxPath) || runIndexNeedsRefresh(instance, payload)) {
    try { writeBotRunIndex(instance as BotInstance, rt); } catch {}
  }
  return idxPath;
}

function pairRunSessionsFromEvents(rows: any[]): any[] {
  const resolvedEventTs = (row: any, fallbackOrdinal = 0): number | null => {
    const rawTs = Number(row?.t);
    if (Number.isFinite(rawTs) && rawTs > 946684800000) return rawTs;
    const slug = String(row?.marketSlug || "").trim();
    const slugStartMs = inferSessionStartMsFromSlug(slug);
    if (Number.isFinite(Number(slugStartMs)) && Number(slugStartMs) > 946684800000) {
      return Number(slugStartMs) + Math.max(0, Math.floor(Number(fallbackOrdinal) || 0));
    }
    return null;
  };
  const openBySlugSide = new Map<string, any[]>();
  const outBySlug = new Map<string, any>();
  const sorted = (Array.isArray(rows) ? rows.slice() : [])
    .sort((a, b) => Number(a?.t || 0) - Number(b?.t || 0));
  const laneKey = (slug: string, sideLike: any) => {
    const side = String(sideLike || "").trim().toUpperCase();
    if (side === "UP" || side === "DOWN") return `${slug}|${side}`;
    return `${slug}|*`;
  };
  const pushOpen = (slug: string, sideLike: any, row: any) => {
    const key = laneKey(slug, sideLike);
    const arr = openBySlugSide.get(key) || [];
    arr.push(row);
    openBySlugSide.set(key, arr);
  };
  const shiftOpen = (slug: string, sideLike: any): any | null => {
    const keyed = laneKey(slug, sideLike);
    const wildcard = laneKey(slug, "*");
    const candidates = [keyed, wildcard];
    for (const key of candidates) {
      const arr = openBySlugSide.get(key) || [];
      if (!arr.length) continue;
      const v = arr.shift() || null;
      openBySlugSide.set(key, arr);
      return v;
    }
    return null;
  };
  const ensureBucket = (slug: string) => {
    const prev = outBySlug.get(slug);
    if (prev) return prev;
    const row = {
      slug,
      firstTsMs: null as number | null,
      lastTsMs: null as number | null,
      pnlUsd: 0,
      balanceUsd: null as number | null,
      lanes: [] as any[],
      laneCount: 0,
    };
    outBySlug.set(slug, row);
    return row;
  };
  const updateBucketMeta = (bucket: any, entryTsMs: number, exitTsMs: number, pnlUsd: number, balanceUsdLike: any) => {
    if (Number.isFinite(entryTsMs)) {
      bucket.firstTsMs = Number.isFinite(Number(bucket.firstTsMs))
        ? Math.min(Number(bucket.firstTsMs), entryTsMs)
        : entryTsMs;
    }
    if (Number.isFinite(exitTsMs)) {
      bucket.lastTsMs = Number.isFinite(Number(bucket.lastTsMs))
        ? Math.max(Number(bucket.lastTsMs), exitTsMs)
        : exitTsMs;
    }
    if (Number.isFinite(pnlUsd)) bucket.pnlUsd = Number(bucket.pnlUsd || 0) + pnlUsd;
    if (Number.isFinite(Number(balanceUsdLike))) bucket.balanceUsd = Number(balanceUsdLike);
  };
  for (let idx = 0; idx < sorted.length; idx++) {
    const r = sorted[idx];
    const ev = String(r?.event || "").toLowerCase();
    const slug = String(r?.marketSlug || "").trim();
    const side = String(r?.side || "").trim().toUpperCase();
    if (!slug) continue;
    if (ev === "enter") {
      const eventTs = resolvedEventTs(r, idx);
      pushOpen(slug, side, Number.isFinite(Number(eventTs)) ? { ...r, t: Number(eventTs) } : r);
      continue;
    }
    if (ev !== "exit" && ev !== "exit_partial") continue;
    const en = shiftOpen(slug, side);
    const entryTsMs = Number(resolvedEventTs(en, idx));
    const exitTsMs = Number(resolvedEventTs(r, idx + 1));
    const pnlUsd = Number(r?.pnlUsd);
    const sharesClosed = Number(r?.sharesClosed);
    const sharesRemaining = Number(r?.sharesRemaining);
    const entryShares = Number(en?.shares);
    const effectiveShares = Number.isFinite(sharesClosed)
      ? sharesClosed
      : (ev === "exit_partial" ? (Number.isFinite(entryShares) ? entryShares : null) : (Number.isFinite(entryShares) ? entryShares : null));
    const isPartial = ev === "exit_partial";
    const lane = {
      entryTsMs: Number.isFinite(entryTsMs) ? entryTsMs : null,
      exitTsMs: Number.isFinite(exitTsMs) ? exitTsMs : null,
      side: String(r?.side || en?.side || "").toUpperCase() || null,
      entryPx: Number.isFinite(Number(en?.entryPx)) ? Number(en.entryPx) : null,
      exitPx: Number.isFinite(Number(r?.exitPx)) ? Number(r.exitPx) : null,
      shares: Number.isFinite(Number(effectiveShares)) ? Number(effectiveShares) : (Number.isFinite(entryShares) ? entryShares : null),
      notionalUsd: Number.isFinite(Number(en?.notionalUsd)) ? Number(en.notionalUsd) : null,
      pnlUsd: Number.isFinite(pnlUsd) ? pnlUsd : null,
      exitType: isPartial ? "derisk" : (String(r?.exitType || "") || null),
      exitReasonRaw: String(r?.exitReasonRaw || "") || null,
      balanceUsd: Number.isFinite(Number(r?.balanceUsd)) ? Number(r.balanceUsd) : null,
      event: ev,
      partial: isPartial,
      sharesClosed: Number.isFinite(sharesClosed) ? sharesClosed : null,
      sharesRemaining: Number.isFinite(sharesRemaining) ? sharesRemaining : null,
    };
    const bucket = ensureBucket(slug);
    updateBucketMeta(bucket, entryTsMs, exitTsMs, pnlUsd, r?.balanceUsd);
    bucket.lanes = Array.isArray(bucket.lanes) ? bucket.lanes : [];
    bucket.lanes.push(lane);
    bucket.laneCount = bucket.lanes.length;
    outBySlug.set(slug, bucket);
    if (isPartial) {
      const remaining = Number.isFinite(sharesRemaining) ? sharesRemaining : NaN;
      if (Number.isFinite(remaining) && remaining > 0 && en) {
        pushOpen(slug, side, {
          ...en,
          shares: remaining,
          t: Number.isFinite(entryTsMs) ? entryTsMs : Number(r?.t || nowMs()),
        });
      }
    }
  }
  return Array.from(outBySlug.values()).sort((a, b) => Number(b?.lastTsMs || 0) - Number(a?.lastTsMs || 0));
}

function sanitizeIndexedSessionsForInstance(instance: BotInstance, sessionsLike: any[]): any[] {
  const sessions = Array.isArray(sessionsLike) ? sessionsLike.map((s) => ({ ...(s || {}) })) : [];
  const isLive = String(instance?.mode || "").trim().toLowerCase() === "live";
  const seenLaneKeys = new Set<string>();
  return sessions.map((sess) => {
    const issues = new Set<string>(Array.isArray(sess?.auditIssues) ? sess.auditIssues.map((x: any) => String(x)) : []);
    const slug = String(sess?.slug || "").trim();
    const lanesRaw = Array.isArray(sess?.lanes) ? sess.lanes : [];
    if (!isLive || !slug || !lanesRaw.length) {
      return {
        ...sess,
        auditIssues: issues.size ? Array.from(issues) : (Array.isArray(sess?.auditIssues) ? sess.auditIssues : []),
      };
    }
    const validLanes = lanesRaw.filter((ln: any) => {
      const side = String(ln?.side || "").trim().toUpperCase();
      const entryTsMs = Number(ln?.entryTsMs);
      const exitTsMs = Number(ln?.exitTsMs);
      const entryPx = Number(ln?.entryPx);
      const exitPx = Number(ln?.exitPx);
      const shares = Number(ln?.shares);
      const notionalUsd = Number(ln?.notionalUsd);
      const pnlUsd = Number(ln?.pnlUsd);
      const key = [
        slug,
        side,
        Number.isFinite(entryTsMs) ? Math.round(entryTsMs) : "na",
        Number.isFinite(exitTsMs) ? Math.round(exitTsMs) : "na",
        Number.isFinite(entryPx) ? entryPx.toFixed(6) : "na",
        Number.isFinite(exitPx) ? exitPx.toFixed(6) : "na",
        Number.isFinite(pnlUsd) ? pnlUsd.toFixed(6) : "na",
        String(ln?.exitType || "").trim().toLowerCase(),
      ].join("|");
      if (seenLaneKeys.has(key)) {
        issues.add("duplicate_terminal_lane");
        return false;
      }
      if (!(side === "UP" || side === "DOWN")) {
        issues.add("invalid_lane_side");
        return false;
      }
      if (!(Number.isFinite(entryTsMs) && entryTsMs > 946684800000)) {
        issues.add("lane_missing_entry");
        return false;
      }
      if (!(Number.isFinite(exitTsMs) && exitTsMs >= entryTsMs)) {
        issues.add("lane_missing_or_invalid_exit");
        return false;
      }
      if (!(Number.isFinite(entryPx) && entryPx >= 0 && entryPx <= 1)) {
        issues.add("lane_entry_px_invalid");
        return false;
      }
      if (!(Number.isFinite(exitPx) && exitPx >= 0 && exitPx <= 1.1)) {
        issues.add("lane_exit_px_invalid");
        return false;
      }
      if (!(Number.isFinite(shares) && shares > 0)) {
        issues.add("lane_shares_invalid");
        return false;
      }
      if (!(Number.isFinite(notionalUsd) && notionalUsd > 0)) {
        issues.add("lane_notional_invalid");
        return false;
      }
      const expectedShares = entryPx > 0 ? (notionalUsd / entryPx) : NaN;
      if (Number.isFinite(expectedShares) && expectedShares > 0 && shares > (expectedShares * 2 + 1e-6)) {
        issues.add("lane_share_notional_impossible");
        return false;
      }
      seenLaneKeys.add(key);
      return true;
    });
    if (!validLanes.length) {
      issues.add("live_session_invalid_or_not_real");
      return {
        ...sess,
        firstTsMs: null,
        lastTsMs: null,
        pnlUsd: 0,
        balanceUsd: null,
        lanes: [],
        laneCount: 0,
        excludeFromPnl: true,
        auditIssues: Array.from(issues),
      };
    }
    const ordered = validLanes.slice().sort((a: any, b: any) => Number(a?.entryTsMs || 0) - Number(b?.entryTsMs || 0));
    const pnlUsd = ordered.reduce((sum: number, ln: any) => sum + (Number(ln?.pnlUsd) || 0), 0);
    const balanceUsd = (() => {
      for (let i = ordered.length - 1; i >= 0; i--) {
        const v = Number(ordered[i]?.balanceUsd);
        if (Number.isFinite(v)) return v;
      }
      return Number.isFinite(Number(sess?.balanceUsd)) ? Number(sess.balanceUsd) : null;
    })();
    return {
      ...sess,
      firstTsMs: Number.isFinite(Number(ordered[0]?.entryTsMs)) ? Number(ordered[0].entryTsMs) : sess?.firstTsMs,
      lastTsMs: Number.isFinite(Number(ordered[ordered.length - 1]?.exitTsMs)) ? Number(ordered[ordered.length - 1].exitTsMs) : sess?.lastTsMs,
      pnlUsd,
      balanceUsd,
      lanes: ordered,
      laneCount: ordered.length,
      excludeFromPnl: !!sess?.excludeFromPnl || issues.size > 0,
      auditIssues: issues.size ? Array.from(issues) : (Array.isArray(sess?.auditIssues) ? sess.auditIssues : []),
    };
  });
}

function mergeClosedNoTradeSessionsFromTraces(instance: BotInstance, sessionsLike: any[]): any[] {
  const baseSessions = Array.isArray(sessionsLike) ? sessionsLike.map((s) => ({ ...(s || {}) })) : [];
  const seenSlugs = new Set(
    baseSessions
      .map((row: any) => String(row?.slug || "").trim())
      .filter(Boolean)
  );
  const launchedAtMs = Number(instance?.launchedAtMs);
  const sinceMs = Number.isFinite(launchedAtMs) && launchedAtMs > 0
    ? Math.max(0, launchedAtMs - 5 * 60_000)
    : Math.max(0, Date.now() - 24 * 60 * 60 * 1000);
  const tracesBySlug = readSessionTracesBySlug(sinceMs, null);
  const backfilled: any[] = [];
  for (const [slug, trace] of tracesBySlug.entries()) {
    const safeSlug = String(slug || "").trim();
    if (!safeSlug || seenSlugs.has(safeSlug)) continue;
    const startMs = inferSessionStartMsFromSlug(safeSlug);
    const durationMs = inferSessionDurationMsFromSlug(safeSlug);
    const endMs = Number.isFinite(Number(startMs)) ? Number(startMs) + durationMs - 1000 : null;
    if (!(Number.isFinite(Number(startMs)) && Number.isFinite(Number(endMs)))) continue;
    if (Number(startMs) < sinceMs) continue;
    if (Number(endMs) > Date.now()) continue;
    const xMs = Array.isArray(trace?.xMs) ? trace.xMs.map((v: any) => Number(v)).filter((v: number) => Number.isFinite(v)) : [];
    if (!xMs.length) continue;
    const firstTsMs = Number(xMs[0]);
    const lastTsMs = Number(xMs[xMs.length - 1]);
    backfilled.push({
      slug: safeSlug,
      firstTsMs: Number.isFinite(firstTsMs) ? firstTsMs : Number(startMs),
      lastTsMs: Number.isFinite(lastTsMs) ? lastTsMs : Number(endMs),
      startMs: Number(startMs),
      endMs: Number(endMs),
      pnlUsd: 0,
      balanceUsd: null,
      lanes: [],
      laneCount: 0,
      closed: true,
      noTrade: true,
      excludeFromPnl: false,
      auditIssues: [],
      traceSource: String((trace as any)?.sourceFile || "session_trace_runlog"),
    });
    seenSlugs.add(safeSlug);
  }
  if (!backfilled.length) return baseSessions;
  return baseSessions
    .concat(backfilled)
    .sort((a: any, b: any) => Number(b?.lastTsMs || b?.endMs || 0) - Number(a?.lastTsMs || a?.endMs || 0));
}

function mergeExpectedClosedSessionBuckets(instance: BotInstance, sessionsLike: any[]): any[] {
  const baseSessions = Array.isArray(sessionsLike) ? sessionsLike.map((s) => ({ ...(s || {}) })) : [];
  const normalizedBase = baseSessions.map((row: any) => {
    const next = { ...(row || {}) };
    const slug = String(next?.slug || "").trim();
    const startMs = inferSessionStartMsFromSlug(slug);
    const durationMs = inferSessionDurationMsFromSlug(slug);
    const endMs = Number.isFinite(Number(startMs)) ? Number(startMs) + durationMs - 1000 : null;
    if (!Number.isFinite(Number(next?.startMs)) && Number.isFinite(Number(startMs))) next.startMs = Number(startMs);
    if (!Number.isFinite(Number(next?.endMs)) && Number.isFinite(Number(endMs))) next.endMs = Number(endMs);
    if (!Number.isFinite(Number(next?.firstTsMs)) && Number.isFinite(Number(startMs))) next.firstTsMs = Number(startMs);
    if (!Number.isFinite(Number(next?.lastTsMs)) && Number.isFinite(Number(endMs))) next.lastTsMs = Number(endMs);
    if (next?.closed == null && Number.isFinite(Number(endMs)) && Number(endMs) <= Date.now()) next.closed = true;
    return next;
  });
  const prefix = String(String(instance?.marketSlug || "").trim().toLowerCase().replace(/-\d{10}$/, ""));
  const intervalMs = inferSessionIntervalMsFromSlug(prefix || String(instance?.marketSlug || ""));
  const launchedAtMs = Number(instance?.launchedAtMs);
  if (!prefix || !(Number.isFinite(intervalMs) && intervalMs > 0) || !(Number.isFinite(launchedAtMs) && launchedAtMs > 0)) {
    return normalizedBase;
  }
  const firstClosedStartMs = Math.ceil(Number(launchedAtMs) / intervalMs) * intervalMs;
  const latestClosedStartMs = (Math.floor(Date.now() / intervalMs) * intervalMs) - intervalMs;
  if (!(Number.isFinite(firstClosedStartMs) && Number.isFinite(latestClosedStartMs)) || latestClosedStartMs < firstClosedStartMs) {
    return normalizedBase;
  }
  const seenSlugs = new Set(
    normalizedBase
      .map((row: any) => String(row?.slug || "").trim())
      .filter(Boolean)
  );
  const synthetic: any[] = [];
  for (let startMs = firstClosedStartMs; startMs <= latestClosedStartMs; startMs += intervalMs) {
    const slug = `${prefix}-${Math.floor(startMs / 1000)}`;
    if (seenSlugs.has(slug)) continue;
    synthetic.push({
      slug,
      firstTsMs: startMs,
      lastTsMs: startMs + intervalMs - 1000,
      startMs,
      endMs: startMs + intervalMs - 1000,
      pnlUsd: 0,
      balanceUsd: null,
      lanes: [],
      laneCount: 0,
      closed: true,
      noTrade: true,
      excludeFromPnl: false,
      auditIssues: [],
      traceSource: null,
    });
    seenSlugs.add(slug);
  }
  if (!synthetic.length) return normalizedBase;
  return normalizedBase
    .concat(synthetic)
    .sort((a: any, b: any) => Number(b?.lastTsMs || b?.endMs || 0) - Number(a?.lastTsMs || a?.endMs || 0));
}

function overlayIndexedSessionsWithEventPairs(instance: BotInstance, sessionsLike: any[]): any[] {
  const baseSessions = Array.isArray(sessionsLike) ? sessionsLike.map((s) => ({ ...(s || {}) })) : [];
  const runNum = Math.floor(Number(instance?.runNum));
  if (!(Number.isFinite(runNum) && runNum > 0)) return baseSessions;
  const pairedSessions = pairRunSessionsFromEvents(readBotRunEventsCached(runNum));
  if (!Array.isArray(pairedSessions) || !pairedSessions.length) return baseSessions;
  const bySlug = new Map<string, any>();
  for (const row of baseSessions) {
    const slug = String(row?.slug || "").trim();
    if (!slug) continue;
    bySlug.set(slug, { ...row });
  }
  for (const row of pairedSessions) {
    const slug = String(row?.slug || "").trim();
    if (!slug) continue;
    const prev = bySlug.get(slug) || {};
    bySlug.set(slug, {
      ...prev,
      ...row,
      slug,
      noTrade: false,
      closed: true,
      firstTsMs: Number.isFinite(Number(row?.firstTsMs)) ? Number(row.firstTsMs) : prev?.firstTsMs ?? null,
      lastTsMs: Number.isFinite(Number(row?.lastTsMs)) ? Number(row.lastTsMs) : prev?.lastTsMs ?? null,
      lanes: Array.isArray(row?.lanes) ? row.lanes : (Array.isArray(prev?.lanes) ? prev.lanes : []),
      laneCount: Number.isFinite(Number(row?.laneCount))
        ? Number(row.laneCount)
        : (Array.isArray(row?.lanes) ? row.lanes.length : (Number(prev?.laneCount) || 0)),
      balanceUsd: Number.isFinite(Number(row?.balanceUsd))
        ? Number(row.balanceUsd)
        : (Number.isFinite(Number(prev?.balanceUsd)) ? Number(prev.balanceUsd) : null),
    });
  }
  return Array.from(bySlug.values()).sort((a: any, b: any) => {
    const ta = Number(a?.lastTsMs || a?.endMs || a?.startMs || 0);
    const tb = Number(b?.lastTsMs || b?.endMs || b?.startMs || 0);
    return tb - ta;
  });
}

function prepareIndexedSessionsForDisplay(instance: BotInstance, sessionsLike: any[]): any[] {
  return applyIgnoredSessionsToIndexedSessions(
    instance,
    sanitizeIndexedSessionsForInstance(
      instance,
      mergeExpectedClosedSessionBuckets(instance, overlayIndexedSessionsWithEventPairs(instance, sessionsLike))
    )
  );
}

function botRunIgnoredSessionsPath(runNum: number): string {
  return path.join(botRunDir(runNum), "ignored_sessions.json");
}

function readBotRunIgnoredSessions(runNum: number): Record<string, { reason: string | null; updatedAtMs: number | null }> {
  try {
    const p = botRunIgnoredSessionsPath(runNum);
    if (!fs.existsSync(p)) return {};
    const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
    const raw = parsed?.ignoredBySlug && typeof parsed.ignoredBySlug === "object" ? parsed.ignoredBySlug : {};
    const out: Record<string, { reason: string | null; updatedAtMs: number | null }> = {};
    for (const [slugRaw, metaRaw] of Object.entries(raw)) {
      const slug = String(slugRaw || "").trim();
      if (!slug) continue;
      const meta = metaRaw && typeof metaRaw === "object" ? (metaRaw as any) : {};
      out[slug] = {
        reason: String(meta?.reason || "").trim() || "manual_ignore",
        updatedAtMs: Number.isFinite(Number(meta?.updatedAtMs)) ? Number(meta.updatedAtMs) : null,
      };
    }
    return out;
  } catch {
    return {};
  }
}

function writeBotRunIgnoredSessions(
  runNum: number,
  ignoredBySlug: Record<string, { reason: string | null; updatedAtMs: number | null }>
): void {
  try {
    const dir = botRunDir(runNum);
    fs.mkdirSync(dir, { recursive: true });
    const p = botRunIgnoredSessionsPath(runNum);
    fs.writeFileSync(
      p,
      JSON.stringify(
        {
          schemaVersion: "ignored-sessions.v1",
          updatedAtMs: nowMs(),
          ignoredBySlug,
        },
        null,
        2
      ) + "\n",
      "utf8"
    );
  } catch {}
}

function setBotRunSessionIgnored(runNum: number, slugRaw: any, ignored: boolean, reasonRaw?: any): boolean {
  const slug = String(slugRaw || "").trim();
  if (!(Number.isFinite(Number(runNum)) && Number(runNum) > 0 && slug)) return false;
  const store = readBotRunIgnoredSessions(Math.floor(Number(runNum)));
  if (ignored) {
    store[slug] = {
      reason: String(reasonRaw || "").trim() || "manual_ignore",
      updatedAtMs: nowMs(),
    };
  } else {
    delete store[slug];
  }
  writeBotRunIgnoredSessions(Math.floor(Number(runNum)), store);
  return true;
}

function getBotRunIgnoredSessionMeta(
  runNum: number,
  slugRaw: any
): { reason: string | null; updatedAtMs: number | null } | null {
  const slug = String(slugRaw || "").trim();
  if (!(Number.isFinite(Number(runNum)) && Number(runNum) > 0 && slug)) return null;
  const store = readBotRunIgnoredSessions(Math.floor(Number(runNum)));
  return store[slug] ?? null;
}

function applyIgnoredSessionsToIndexedSessions(instance: BotInstance, sessionsLike: any[]): any[] {
  const runNum = Math.floor(Number(instance?.runNum));
  const baseSessions = Array.isArray(sessionsLike) ? sessionsLike.map((s) => ({ ...(s || {}) })) : [];
  if (!(Number.isFinite(runNum) && runNum > 0)) return baseSessions;
  const ignoredBySlug = readBotRunIgnoredSessions(runNum);
  const sessions = baseSessions.map((sess) => {
    const slug = String(sess?.slug || "").trim();
    const meta = slug ? ignoredBySlug[slug] : null;
    const issues = new Set<string>(Array.isArray(sess?.auditIssues) ? sess.auditIssues.map((x: any) => String(x)) : []);
    if (meta) issues.add("manual_ignore");
    return {
      ...sess,
      manuallyIgnored: !!meta,
      ignoreReason: meta?.reason ?? null,
      ignoreUpdatedAtMs: meta?.updatedAtMs ?? null,
      excludeFromPnl: !!sess?.excludeFromPnl || !!meta,
      auditIssues: Array.from(issues),
    };
  });

  const ordered = sessions
    .slice()
    .sort(
      (a, b) =>
        Number(a?.lastTsMs || a?.exitTsMs || a?.entryTsMs || a?.attemptTsMs || 0) -
        Number(b?.lastTsMs || b?.exitTsMs || b?.entryTsMs || b?.attemptTsMs || 0)
    );
  let runningBalance = Number.isFinite(Number(instance?.startBalanceUsd))
    ? Number(instance.startBalanceUsd)
    : 100;
  if (!Number.isFinite(runningBalance)) runningBalance = 100;
  for (const s of ordered) {
    const pnl = Number(s?.pnlUsd);
    const terminalTs = Number(s?.lastTsMs || s?.exitTsMs || s?.entryTsMs || s?.attemptTsMs);
    if (!(Number.isFinite(pnl) && Number.isFinite(terminalTs) && terminalTs > 0)) continue;
    if (!(s as any).excludeFromPnl) {
      runningBalance += pnl;
    }
    s.balanceUsd = round4(Number(runningBalance));
  }
  return sessions;
}

function writeBotRunIndex(instance: BotInstance, rt: BotRuntime | null) {
  try {
    const runNum = Math.floor(Number(instance.runNum));
    if (!Number.isFinite(runNum) || runNum <= 0) return;
    const dir = botRunDir(runNum);
    fs.mkdirSync(dir, { recursive: true });
    const summary = readBotRunSummary(runNum);
    const events = readBotRunEventsCached(runNum);
    const eventPairedSessions = pairRunSessionsFromEvents(events);
    const indexedSourceSessions = mergeExpectedClosedSessionBuckets(
      instance,
      HOT_SERVICE_MODE
        ? eventPairedSessions
        : mergeClosedNoTradeSessionsFromTraces(instance, eventPairedSessions)
    );
    const sessions = applyIgnoredSessionsToIndexedSessions(
      instance,
      sanitizeIndexedSessionsForInstance(
        instance,
        indexedSourceSessions
      )
    );
    const srt = botStrategyRuntimes.get(instance.instanceId) || null;
    const identity = rt ? recoverBotOpenEntryIdentity(instance, rt, srt?.lastSnapshot ?? null) : null;
    const payload = {
      schemaVersion: "run-index.v1",
      generatedAtMs: nowMs(),
      generatedAtIso: new Date().toISOString(),
      run: {
        runId: instance.runId,
        runNum: runNum,
        runAuditIdentity: {
          runNum,
          runId: instance.runId,
          startedAtMs: instance.launchedAtMs,
        },
        instanceId: instance.instanceId,
        strategyId: instance.strategyId,
        strategyPath: instance.strategyPath,
        marketSlug: instance.marketSlug,
        marketTitle: instance.marketTitle,
        mode: instance.mode,
        launchedAtMs: instance.launchedAtMs,
        stoppedAtMs: instance.stoppedAtMs,
      },
      summary: summary || null,
      latestRuntime: rt
        ? {
            entered: rt.entered,
            side: rt.side,
            entryPx: rt.entryPx,
            entryMode: identity?.mode ?? normalizeRecoveredBotEntryMode((rt as any)?.__lastEntryMode),
            entrySubtype: identity?.hcSubtype ?? normalizeRecoveredBotEntrySubtype((rt as any)?.__lastEntrySubtype),
            upBid: rt.upBid,
            downBid: rt.downBid,
            balanceUsd: rt.balanceUsd,
            realizedPnlUsd: rt.realizedPnlUsd,
            lastAction: rt.lastAction,
            lastExitType: rt.lastExitType,
            sessionSlug: rt.sessionSlug,
          }
        : null,
      latestStrategySnapshot: rt ? reconcileBotStrategySnapshotForRuntime(instance, rt, srt?.lastSnapshot ?? null) : (srt?.lastSnapshot ?? null),
      files: {
        eventsJsonl: path.join(dir, "events.jsonl"),
        telemetryJsonl: botRunTelemetryPath(runNum),
        summaryJson: path.join(dir, "summary.json"),
        ignoredSessionsJson: botRunIgnoredSessionsPath(runNum),
      },
      ignoredSessions: readBotRunIgnoredSessions(runNum),
      sessions,
      // Realized session/accounting only. Historical traces live in the dedicated
      // trace stores and are loaded on demand so the trading hot path does not
      // rebuild/embed trace payloads into the run index on every event.
      tracesBySlug: {},
    };
    const outPath = botRunIndexPath(instance.strategyId, runNum);
    atomicWriteUtf8(outPath, JSON.stringify(payload, null, 2) + "\n");
    // Closed-session canonical artifacts must be materialized for every run so
    // historical cards remain rebuildable after restarts, even when the host is
    // running in hot mode. The work itself stays deferred behind a timer.
    scheduleClosedSessionCanonicalArtifactMaterialization(instance, sessions);
    // Build compact historical-card artifacts after close. This stays deferred
    // behind a timer and writes one lightweight artifact per session.
    scheduleClosedSessionCardMaterialization(instance, sessions);
    scheduleSessionParityWarmRefresh(instance, sessions);
  } catch {}
}

const BOT_RUN_INDEX_REFRESH_TIMERS = new Map<string, NodeJS.Timeout>();
const BOT_RUN_INDEX_REFRESH_DEBOUNCE_MS = Math.max(
  100,
  Number(process.env.BOT_RUN_INDEX_REFRESH_DEBOUNCE_MS || 350)
);

function scheduleBotRunIndexRefresh(instance: BotInstance, rt: BotRuntime | null): void {
  try {
    if (HOT_SERVICE_MODE) return;
    const instanceId = String(instance?.instanceId || "").trim();
    const runNum = Math.floor(Number(instance?.runNum));
    if (!instanceId || !(Number.isFinite(runNum) && runNum > 0)) return;
    const key = `${runNum}:${instanceId}`;
    const prior = BOT_RUN_INDEX_REFRESH_TIMERS.get(key);
    if (prior) clearTimeout(prior);
    const timer = setTimeout(() => {
      BOT_RUN_INDEX_REFRESH_TIMERS.delete(key);
      const nextInstance = botInstances.get(instanceId) || instance;
      const nextRuntime = botRuntimes.get(instanceId) || rt || null;
      writeBotRunIndex(nextInstance, nextRuntime);
    }, BOT_RUN_INDEX_REFRESH_DEBOUNCE_MS);
    BOT_RUN_INDEX_REFRESH_TIMERS.set(key, timer);
  } catch {}
}

function sanitizeRunIndexPayload(instance: BotInstance, payload: any): { payload: any; changed: boolean } {
  const base = payload && typeof payload === "object" ? { ...payload } : {};
  const sessionsBefore = Array.isArray(base?.sessions) ? base.sessions : [];
  const sessionsAfter = prepareIndexedSessionsForDisplay(instance, sessionsBefore);
  const ignoredSessions = readBotRunIgnoredSessions(Math.floor(Number(instance?.runNum)));
  const beforeJson = JSON.stringify(sessionsBefore);
  const afterJson = JSON.stringify(sessionsAfter);
  const ignoredBeforeJson = JSON.stringify(base?.ignoredSessions && typeof base.ignoredSessions === "object" ? base.ignoredSessions : {});
  const ignoredAfterJson = JSON.stringify(ignoredSessions);
  if (beforeJson === afterJson && ignoredBeforeJson === ignoredAfterJson) return { payload: base, changed: false };
  return {
    payload: {
      ...base,
      ignoredSessions,
      sessions: sessionsAfter,
      files: {
        ...(base?.files && typeof base.files === "object" ? base.files : {}),
        ignoredSessionsJson: botRunIgnoredSessionsPath(Math.floor(Number(instance?.runNum))),
      },
    },
    changed: true,
  };
}

function appendBotRunTelemetry(instance: BotInstance, rt: BotRuntime, strategySnapshot: any) {
  try {
    if (!BOT_RUN_TELEMETRY_ENABLED) return;
    const runNum = Math.floor(Number(instance.runNum));
    if (!Number.isFinite(runNum) || runNum <= 0) return;
    const dir = botRunDir(runNum);
    fs.mkdirSync(dir, { recursive: true });
    const p = botRunTelemetryPath(runNum);
    const rtAny = rt as any;
    const identity = recoverBotOpenEntryIdentity(instance, rt, strategySnapshot);
    const botTickStats = botTickGapStatsNow();
    const rssMb = process.memoryUsage().rss / (1024 * 1024);
    const processCpuPct = sampleProcessCpuPct();
    const runtimeLagMs =
      Number.isFinite(Number(botTickStats?.activeMaxRuntimeAgeMs))
        ? Number(botTickStats.activeMaxRuntimeAgeMs)
        : (Number.isFinite(Number(botTickStats?.latestGapMs)) ? Number(botTickStats.latestGapMs) : null);
    const row = {
      t: nowMs(),
      iso: new Date().toISOString(),
      instanceId: instance.instanceId,
      runId: instance.runId,
      runNum: runNum,
      strategyId: instance.strategyId,
      marketSlug: instance.marketSlug,
      sessionSlug: rt.sessionSlug,
      upBid: rt.upBid,
      downBid: rt.downBid,
      entered: rt.entered,
      side: rt.side,
      entryPx: rt.entryPx,
      shares: Number.isFinite(Number(rt.shares)) ? Number(rt.shares) : null,
      notionalUsd: Number.isFinite(Number(rt.notionalUsd)) ? Number(rt.notionalUsd) : null,
      balanceUsd: rt.balanceUsd,
      realizedPnlUsd: rt.realizedPnlUsd,
      processCpuPct: Number.isFinite(processCpuPct) ? Number(processCpuPct.toFixed(1)) : null,
      rssMb: Number.isFinite(rssMb) ? Number(rssMb.toFixed(1)) : null,
      runtimeLagMs: Number.isFinite(Number(runtimeLagMs)) ? Number(runtimeLagMs) : null,
      lastAction: String(rt.lastAction || "") || null,
      lastError: String(rt.lastError || "") || null,
      entryMode: normalizeRecoveredBotEntryMode(rtAny.__lastEntryMode) ?? identity.mode,
      entrySubtype: normalizeRecoveredBotEntrySubtype(rtAny.__lastEntrySubtype) ?? identity.hcSubtype,
      strategySnapshot: cloneJsonLike(
        reconcileBotStrategySnapshotForRuntime(instance, rt, strategySnapshot),
        null
      ),
    };
    enqueueBufferedAppend(p, JSON.stringify(row) + "\n", "bot telemetry append error");
  } catch {}
}

function readJsonlSafe(p: string): any[] {
  try {
    if (!fs.existsSync(p)) return [];
    const txt = fs.readFileSync(p, "utf8");
    return txt
      .split(/\r?\n/)
      .map((s) => s.trim())
      .filter(Boolean)
      .map((ln) => {
        try { return JSON.parse(ln); } catch { return null; }
      })
      .filter(Boolean);
  } catch {
    return [];
  }
}

function isValidPersistedEventTsMs(v: any): boolean {
  const x = Number(v);
  return Number.isFinite(x) && x > 946684800000;
}

function roundRepairPx(v: any): number | null {
  const x = Number(v);
  return Number.isFinite(x) ? Number(x.toFixed(6)) : null;
}

function flattenCompactAuditTimelineForRepair(compact: any): any[] {
  const out: any[] = [];
  const sideAudit = compact?.sideAudit && typeof compact.sideAudit === "object" ? compact.sideAudit : {};
  for (const side of ["UP", "DOWN"]) {
    const rows = Array.isArray(sideAudit?.[side]?.timeline) ? sideAudit[side].timeline : [];
    for (const row of rows) {
      if (!row || typeof row !== "object") continue;
      out.push({
        side,
        event: String(row?.event || "").toLowerCase(),
        tsMs: isValidPersistedEventTsMs(row?.tsMs) ? Number(row.tsMs) : null,
        fillTsMs: isValidPersistedEventTsMs(row?.fillTsMs) ? Number(row.fillTsMs) : null,
        entryPx: roundRepairPx(row?.entryPx ?? row?.actualFillPx ?? row?.signalPx ?? row?.intendedPx),
        exitPx: roundRepairPx(row?.exitPx ?? row?.actualFillPx),
        orderId: String(row?.orderId || "").trim(),
        executionMode: String(row?.executionMode || "").trim().toLowerCase(),
        fillSource: String(row?.fillSource || "").trim().toLowerCase(),
        tsInferred: row?.tsInferred === true,
      });
    }
  }
  out.sort((a, b) => Number(a?.tsMs || 0) - Number(b?.tsMs || 0));
  return out;
}

function scoreLegacyRepairCandidate(row: any, candidate: any): number {
  if (!candidate || typeof candidate !== "object") return Number.NEGATIVE_INFINITY;
  const rowEvent = String(row?.event || "").trim().toLowerCase();
  if (!rowEvent || rowEvent !== String(candidate?.event || "").trim().toLowerCase()) {
    return Number.NEGATIVE_INFINITY;
  }
  const rowSide = String(row?.side || "").trim().toUpperCase();
  const candSide = String(candidate?.side || "").trim().toUpperCase();
  if (rowSide && candSide && rowSide !== candSide) return Number.NEGATIVE_INFINITY;
  let score = 0;
  if (rowSide && candSide && rowSide === candSide) score += 50;
  const rowOrderId = String(row?.orderId || row?.tpOrderId || "").trim();
  const candOrderId = String(candidate?.orderId || "").trim();
  if (rowOrderId && candOrderId) {
    if (rowOrderId !== candOrderId) return Number.NEGATIVE_INFINITY;
    score += 100;
  }
  const rowEntryPx = roundRepairPx(row?.entryPx ?? row?.actualFillPx ?? row?.signalPx ?? row?.intendedPx);
  const candEntryPx = roundRepairPx(candidate?.entryPx);
  if (rowEntryPx != null && candEntryPx != null) {
    if (Math.abs(rowEntryPx - candEntryPx) <= 0.000001) score += 20;
    else score -= 10;
  }
  const rowExitPx = roundRepairPx(row?.exitPx ?? row?.actualFillPx);
  const candExitPx = roundRepairPx(candidate?.exitPx);
  if (rowExitPx != null && candExitPx != null) {
    if (Math.abs(rowExitPx - candExitPx) <= 0.000001) score += 20;
    else score -= 10;
  }
  const rowExecutionMode = String(row?.executionMode || "").trim().toLowerCase();
  if (rowExecutionMode && rowExecutionMode === String(candidate?.executionMode || "").trim().toLowerCase()) score += 5;
  const rowFillSource = String(row?.fillSource || "").trim().toLowerCase();
  if (rowFillSource && rowFillSource === String(candidate?.fillSource || "").trim().toLowerCase()) score += 5;
  if (candidate?.tsInferred === false) score += 2;
  return score;
}

function repairLegacyBotRunEventRowFromCompact(row: any, compactTimeline: any[], usedCandidateIdx: Set<number>): { row: any; changed: boolean } {
  if (isValidPersistedEventTsMs(row?.t)) return { row, changed: false };
  if (!Array.isArray(compactTimeline) || !compactTimeline.length) return { row, changed: false };
  let bestIdx = -1;
  let bestScore = Number.NEGATIVE_INFINITY;
  for (let idx = 0; idx < compactTimeline.length; idx++) {
    if (usedCandidateIdx.has(idx)) continue;
    const score = scoreLegacyRepairCandidate(row, compactTimeline[idx]);
    if (score > bestScore) {
      bestScore = score;
      bestIdx = idx;
    }
  }
  if (!(bestIdx >= 0) || !Number.isFinite(bestScore) || bestScore < 0) {
    return { row, changed: false };
  }
  const matched = compactTimeline[bestIdx];
  const repairedTsMs =
    isValidPersistedEventTsMs(matched?.tsMs)
      ? Number(matched.tsMs)
      : (isValidPersistedEventTsMs(matched?.fillTsMs) ? Number(matched.fillTsMs) : null);
  if (!isValidPersistedEventTsMs(repairedTsMs)) return { row, changed: false };
  usedCandidateIdx.add(bestIdx);
  const ev = String(row?.event || "").trim().toLowerCase();
  const repairedFillTsMs =
    isValidPersistedEventTsMs(matched?.fillTsMs)
      ? Number(matched.fillTsMs)
      : repairedTsMs;
  const next = {
    ...(row && typeof row === "object" ? row : {}),
    t: repairedTsMs,
    iso: new Date(repairedTsMs).toISOString(),
    fillTimestampSource: matched?.tsInferred ? "session_audit_inferred" : "session_audit_exact",
    fillTimestampExact: matched?.tsInferred !== true,
    timestampRepairSource: "session_audit_timeline",
  };
  if (!isValidPersistedEventTsMs(next.eventTsMs)) next.eventTsMs = repairedTsMs;
  if (ev === "enter_signal" && !isValidPersistedEventTsMs(next.signalTsMs)) next.signalTsMs = repairedTsMs;
  if ((ev === "enter_order" || ev === "exit_order") && !isValidPersistedEventTsMs(next.orderPlacedAtMs)) {
    next.orderPlacedAtMs = repairedTsMs;
  }
  if (ev === "enter") {
    if (!isValidPersistedEventTsMs(next.entryTsMs)) next.entryTsMs = repairedFillTsMs;
    if (!isValidPersistedEventTsMs(next.actualFillTsMs)) next.actualFillTsMs = repairedFillTsMs;
  }
  if (ev === "exit" || ev === "exit_partial") {
    if (!isValidPersistedEventTsMs(next.exitTsMs)) next.exitTsMs = repairedFillTsMs;
    if (!isValidPersistedEventTsMs(next.actualFillTsMs)) next.actualFillTsMs = repairedFillTsMs;
  }
  if (!String(next.orderId || "").trim() && String(matched?.orderId || "").trim()) {
    next.orderId = String(matched.orderId).trim();
  }
  return { row: next, changed: true };
}

function repairLegacyBotRunEventsFromSessionAudits(runNum: number, rows: any[]): { rows: any[]; changed: boolean } {
  if (!Array.isArray(rows) || !rows.length) return { rows: Array.isArray(rows) ? rows : [], changed: false };
  let changed = false;
  const compactTimelineBySlug = new Map<string, any[]>();
  const usedCandidateIdxBySlug = new Map<string, Set<number>>();
  const repairedRows = rows.map((row) => {
    if (isValidPersistedEventTsMs(row?.t)) return row;
    const slug = String(row?.marketSlug || "").trim();
    if (!slug) return row;
    if (!compactTimelineBySlug.has(slug)) {
      const compact = readSessionAuditCompact(runNum, slug);
      compactTimelineBySlug.set(slug, flattenCompactAuditTimelineForRepair(compact));
      usedCandidateIdxBySlug.set(slug, new Set<number>());
    }
    const timeline = compactTimelineBySlug.get(slug) || [];
    const used = usedCandidateIdxBySlug.get(slug) || new Set<number>();
    const repaired = repairLegacyBotRunEventRowFromCompact(row, timeline, used);
    if (repaired.changed) changed = true;
    usedCandidateIdxBySlug.set(slug, used);
    return repaired.row;
  });
  return { rows: repairedRows, changed };
}

function readBotRunEvents(runNum: number): any[] {
  const p = path.join(botRunDir(runNum), "events.jsonl");
  return readJsonlSafe(p);
}

const botRunEventsCache = new Map<number, { mtimeMs: number; size: number; rows: any[] }>();

function appendBotRunEventCacheRow(runNum: number, row: any): void {
  const rn = Math.floor(Number(runNum));
  if (!Number.isFinite(rn) || rn <= 0 || !row || typeof row !== "object") return;
  const prev = botRunEventsCache.get(rn);
  if (!prev || !Array.isArray(prev.rows)) return;
  prev.rows.push(row);
  prev.size = Number(prev.size || 0) + Buffer.byteLength(`${JSON.stringify(row)}\n`, "utf8");
  prev.mtimeMs = Date.now();
  botRunEventsCache.set(rn, prev);
}
const SESSION_AUDIT_COMPACT_CACHE_MAX_ENTRIES = 128;
const SESSION_CARD_ARTIFACT_CACHE_MAX_ENTRIES = 128;
const sessionAuditCompactCache = new Map<string, { mtimeMs: number; size: number; row: any | null }>();
const sessionCardArtifactCache = new Map<string, { mtimeMs: number; size: number; row: any | null }>();
let serverRestartRowsCache: { mtimeMs: number; size: number; rows: any[] } | null = null;
const JSON_FILE_CACHE_MAX_ENTRIES = 64;
const JSON_FILE_CACHE_MAX_SIZE_BYTES = 16 * 1024 * 1024;
const jsonFileCache = new Map<string, {
  mtimeMs: number;
  size: number;
  touchedAtMs: number;
  exists: boolean;
  value: any | null;
}>();

function trimSessionAuditCompactCache(): void {
  if (sessionAuditCompactCache.size <= SESSION_AUDIT_COMPACT_CACHE_MAX_ENTRIES) return;
  const rows = Array.from(sessionAuditCompactCache.entries())
    .sort((a, b) => Number(a?.[1]?.mtimeMs || 0) - Number(b?.[1]?.mtimeMs || 0));
  while (sessionAuditCompactCache.size > SESSION_AUDIT_COMPACT_CACHE_MAX_ENTRIES && rows.length) {
    const row = rows.shift();
    if (!row) break;
    sessionAuditCompactCache.delete(row[0]);
  }
}

function trimSessionCardArtifactCache(): void {
  if (sessionCardArtifactCache.size <= SESSION_CARD_ARTIFACT_CACHE_MAX_ENTRIES) return;
  const rows = Array.from(sessionCardArtifactCache.entries())
    .sort((a, b) => Number(a?.[1]?.mtimeMs || 0) - Number(b?.[1]?.mtimeMs || 0));
  while (sessionCardArtifactCache.size > SESSION_CARD_ARTIFACT_CACHE_MAX_ENTRIES && rows.length) {
    const row = rows.shift();
    if (!row) break;
    sessionCardArtifactCache.delete(row[0]);
  }
}

function trimJsonFileCache(): void {
  if (jsonFileCache.size <= JSON_FILE_CACHE_MAX_ENTRIES) return;
  const rows = Array.from(jsonFileCache.entries())
    .sort((a, b) => Number(a?.[1]?.touchedAtMs || 0) - Number(b?.[1]?.touchedAtMs || 0));
  while (jsonFileCache.size > JSON_FILE_CACHE_MAX_ENTRIES && rows.length) {
    const row = rows.shift();
    if (!row) break;
    jsonFileCache.delete(row[0]);
  }
}

function fileStatSignature(filePath: string): { mtimeMs: number; size: number } | null {
  try {
    const st = fs.statSync(filePath);
    return {
      mtimeMs: Number(st?.mtimeMs || 0),
      size: Number(st?.size || 0),
    };
  } catch {
    return null;
  }
}

function fileCacheSignature(filePath: string): string {
  const sig = fileStatSignature(filePath);
  if (!sig) return `${filePath}:missing`;
  return `${filePath}:${Math.floor(Number(sig.mtimeMs || 0))}:${Math.floor(Number(sig.size || 0))}`;
}

function readJsonFileCached<T = any>(filePath: string): T | null {
  const now = nowMs();
  const sig = fileStatSignature(filePath);
  const cached = jsonFileCache.get(filePath) || null;
  if (!sig) {
    if (cached) {
      cached.touchedAtMs = now;
      if (!cached.exists) return cached.value as T | null;
    }
    jsonFileCache.set(filePath, {
      mtimeMs: 0,
      size: 0,
      touchedAtMs: now,
      exists: false,
      value: null,
    });
    trimJsonFileCache();
    return null;
  }
  if (
    cached &&
    cached.exists &&
    Number(cached.mtimeMs || 0) === Number(sig.mtimeMs || 0) &&
    Number(cached.size || 0) === Number(sig.size || 0)
  ) {
    cached.touchedAtMs = now;
    return cached.value as T | null;
  }
  try {
    const value = JSON.parse(fs.readFileSync(filePath, "utf8"));
    if (Number(sig.size || 0) > JSON_FILE_CACHE_MAX_SIZE_BYTES) {
      jsonFileCache.delete(filePath);
      return value as T;
    }
    jsonFileCache.set(filePath, {
      mtimeMs: Number(sig.mtimeMs || 0),
      size: Number(sig.size || 0),
      touchedAtMs: now,
      exists: true,
      value,
    });
    trimJsonFileCache();
    return value as T;
  } catch {
    jsonFileCache.set(filePath, {
      mtimeMs: Number(sig.mtimeMs || 0),
      size: Number(sig.size || 0),
      touchedAtMs: now,
      exists: true,
      value: null,
    });
    trimJsonFileCache();
    return null;
  }
}

function readRunIndexPayloadCached(idxPath: string): any | null {
  return readJsonFileCached(idxPath);
}

function readBotRunSummaryCached(runNum: number): any | null {
  try {
    const p = path.join(botRunDir(runNum), "summary.json");
    return readJsonFileCached(p);
  } catch {
    return null;
  }
}

function readBotRunEventsCached(runNum: number): any[] {
  const rn = Math.floor(Number(runNum));
  if (!Number.isFinite(rn) || rn <= 0) return [];
  const p = path.join(botRunDir(rn), "events.jsonl");
  try {
    const st = fs.statSync(p);
    const mtimeMs = Number(st.mtimeMs || 0);
    const size = Number(st.size || 0);
    const prev = botRunEventsCache.get(rn);
    if (prev && Number(prev.mtimeMs) === mtimeMs && Number(prev.size) === size && Array.isArray(prev.rows)) {
      return prev.rows;
    }
    let rows = readJsonlSafe(p);
    const repaired = repairLegacyBotRunEventsFromSessionAudits(rn, rows);
    if (repaired.changed) {
      rows = repaired.rows;
      try {
        const txt = rows.map((row) => JSON.stringify(row)).join("\n");
        fs.writeFileSync(p, txt ? `${txt}\n` : "", "utf8");
        const st2 = fs.statSync(p);
        botRunEventsCache.set(rn, {
          mtimeMs: Number(st2.mtimeMs || mtimeMs),
          size: Number(st2.size || size),
          rows,
        });
        return rows;
      } catch {}
    }
    botRunEventsCache.set(rn, { mtimeMs, size, rows });
    return rows;
  } catch {
    botRunEventsCache.delete(rn);
    return [];
  }
}

function classifyLiveMarkerType(row: any): "entry_filled" | "partial_exit" | "tp" | "stop_loss" | "final_exit" | null {
  const ev = String(row?.event || row?.action || "").trim().toLowerCase();
  const exitType = String(row?.exitType || "").trim().toLowerCase();
  if (
    ev === "enter" ||
    ev === "entry_fill" ||
    ev === "enter_fill_confirmed" ||
    ev === "enter_first_fill_seen"
  ) return "entry_filled";
  if (
    ev === "exit_partial" ||
    ev === "partial_exit" ||
    ev === "derisk_fill"
  ) return "partial_exit";
  if (
    ev === "stop_fill" ||
    ev === "stop_fill_confirmed" ||
    ((ev === "exit" || ev === "exit_fill" || ev === "exit_fill_confirmed") &&
      (exitType === "stop" || exitType.includes("stop")))
  ) return "stop_loss";
  if (
    (ev === "exit" || ev === "exit_fill" || ev === "exit_fill_confirmed") &&
    (exitType === "tp" || exitType.includes("tp"))
  ) return "tp";
  if (
    ev === "exit" ||
    ev === "exit_fill" ||
    ev === "exit_fill_confirmed" ||
    ev === "final_exit" ||
    ev === "settle"
  ) return "final_exit";
  if (ev !== "exit") return null;
  if (exitType === "stop" || exitType.includes("stop")) return "stop_loss";
  if (exitType === "tp" || exitType.includes("tp")) return "tp";
  return "final_exit";
}

function resolveLiveMarkerPrice(row: any): number | null {
  const candidates = [
    row?.actualFillPx,
    row?.fillPx,
    row?.entryPx,
    row?.exitPx,
    row?.price,
    row?.st?.entryPx,
    row?.st?.exitPx,
    row?.execution?.fillPx,
    row?.execution?.actualFillPx,
    row?.execution?.entryPx,
    row?.execution?.exitPx,
    row?.ui?.entry,
    row?.ui?.exit,
    row?.runtime?.entryPx,
    row?.runtime?.exitPx,
  ];
  for (const candidate of candidates) {
    if (candidate == null || candidate === "") continue;
    const n = Number(candidate);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return null;
}

function resolveLiveMarkerTsMs(row: any): number | null {
  const candidates = [
    row?.actualFillTsMs,
    row?.eventTsMs,
    row?.fillTsMs,
    row?.entryTsMs,
    row?.exitTsMs,
    row?.st?.entryTsMs,
    row?.st?.exitTsMs,
    row?.execution?.actualFillTsMs,
    row?.execution?.fillTsMs,
    row?.execution?.entryTsMs,
    row?.execution?.exitTsMs,
    row?.t,
  ];
  for (const candidate of candidates) {
    if (candidate == null || candidate === "") continue;
    const n = Number(candidate);
    if (Number.isFinite(n) && n > 946684800000) return n;
  }
  return null;
}

function recordBotRunRowAsLiveTradeArtifacts(instanceIdLike: any, rowLike: any): void {
  const instanceId = String(instanceIdLike || "").trim();
  const row = rowLike && typeof rowLike === "object" ? rowLike : null;
  if (!instanceId || !row) return;
  recordRecentTradeEvent(instanceId, row);
  const markerType = classifyLiveMarkerType(row);
  const tsMs = resolveLiveMarkerTsMs(row);
  const price = resolveLiveMarkerPrice(row);
  if (!markerType || !Number.isFinite(Number(tsMs)) || !Number.isFinite(Number(price))) return;
  const slug = String(row?.marketSlug || row?.market?.slug || "").trim();
  if (!slug) return;
  const side = String(row?.side || row?.runtime?.side || "").trim().toUpperCase();
  const marker = {
    instanceId,
    slug,
    sessionSlug: slug,
    tsMs: Number(tsMs),
    side: side === "UP" || side === "DOWN" ? side : null,
    type:
      markerType === "entry_filled"
        ? "entry_filled"
        : markerType === "partial_exit"
        ? "partial_filled"
        : markerType === "stop_loss"
        ? "exit_filled"
        : markerType === "tp"
        ? "exit_filled"
        : "settle",
    markerType,
    price: Number(price),
    shares: Number.isFinite(Number(row?.sharesClosed ?? row?.shares ?? row?.runtime?.shares))
      ? Number(row?.sharesClosed ?? row?.shares ?? row?.runtime?.shares)
      : null,
    pnlUsd: Number.isFinite(Number(row?.pnlUsd ?? row?.runtime?.realizedPnlUsd))
      ? Number(row?.pnlUsd ?? row?.runtime?.realizedPnlUsd)
      : null,
    usdValue: Number.isFinite(Number(row?.sharesClosed ?? row?.shares ?? row?.runtime?.shares))
      ? Number(row?.sharesClosed ?? row?.shares ?? row?.runtime?.shares) * Number(price)
      : null,
    exitType: String(row?.exitType || "").trim().toLowerCase() || null,
    event: String(row?.event || markerType).trim().toLowerCase() || markerType,
    key: `${instanceId}:${slug}:${markerType}:${Math.floor(Number(tsMs))}:${String(row?.event || "")}`,
    source: "trade_event",
  };
  const recordedMarker = recordLiveTradeMarker(instanceId, marker);
  if (recordedMarker) appendLiveMarkerToCurrentSessionTrace(slug, recordedMarker);
}

function deriveLiveTradeMarkerRow(payloadLike: any): any | null {
  const payload = payloadLike && typeof payloadLike === "object" ? payloadLike : null;
  if (!payload) return null;
  const instanceId = String(payload?.instanceId || "").trim();
  const slug = String(payload?.marketSlug || payload?.market?.slug || "").trim();
  if (!instanceId || !slug) return null;
  const exec = payload?.execution && typeof payload.execution === "object" ? payload.execution : null;
  const action = String(payload?.action || "").trim();
  const eventName = String(payload?.event || "").trim();
  const actionUpper = action.toUpperCase();
  const eventUpper = eventName.toUpperCase();
  const phase = String(exec?.phase || payload?.phase || "").trim().toLowerCase();
  const exitTypeRaw = String(payload?.exitType || exec?.exitType || "").trim();
  const exitType = exitTypeRaw.toLowerCase();
  const sideRaw = String(payload?.side || exec?.side || payload?.st?.side || "").trim().toUpperCase();
  const side = sideRaw === "UP" || sideRaw === "DOWN" ? sideRaw : null;
  const tsMs = resolveLiveMarkerTsMs(payload);
  if (!Number.isFinite(Number(tsMs))) return null;
  const price = resolveLiveMarkerPrice(payload);
  const shares = Number(payload?.sharesClosed ?? payload?.filledShares ?? payload?.shares ?? payload?.st?.shares ?? NaN);
  const pnlUsd = Number(payload?.pnlUsd ?? payload?.st?.pnlUsd ?? NaN);
  const partial =
    payload?.partial === true ||
    (Number.isFinite(Number(payload?.remainingShares)) && Number(payload.remainingShares) > 1e-6) ||
    exitType.includes("derisk");

  let type = "";
  let markerType = "";
  if (
    phase === "entry_order" ||
    phase === "enter_submit_start" ||
    phase === "enter_submit_return" ||
    /^ENTER_SUBMIT_(START|ACCEPTED|RETURN)_/.test(actionUpper) ||
    /^ENTER_ORDER$/.test(eventUpper)
  ) {
    type = "entry_placed";
  } else if (
    phase === "enter_fill_confirmed" ||
    phase === "entry_fill" ||
    phase === "enter_first_fill_seen" ||
    eventUpper === "ENTER" ||
    eventUpper === "ENTRY_FILL" ||
    eventUpper === "ENTER_FILL_CONFIRMED" ||
    eventUpper === "ENTER_FIRST_FILL_SEEN"
  ) {
    type = "entry_filled";
    markerType = "entry_filled";
  } else if ((phase === "exit_order" || eventUpper === "EXIT_ORDER") && exitType.includes("derisk")) {
    type = "partial_armed";
  } else if (
    (phase === "exit_fill_confirmed" || phase === "exit_fill" || eventUpper === "EXIT_PARTIAL" || eventUpper === "PARTIAL_EXIT" || eventUpper === "DERISK_FILL") &&
    partial
  ) {
    type = "partial_filled";
    markerType = "partial_exit";
  } else if (phase === "stop_signal" || phase === "stop_submit_start" || eventUpper === "STOP_SIGNAL") {
    type = "stop_fired";
  } else if (
    (phase === "exit_fill_confirmed" || phase === "exit_fill" || phase === "stop_fill_confirmed" || phase === "stop_fill" || eventUpper === "SETTLE" || eventUpper === "FINAL_EXIT") &&
    exitType.includes("settle")
  ) {
    type = "settle";
    markerType = "final_exit";
  } else if (
    phase === "stop_fill_confirmed" ||
    phase === "stop_fill" ||
    eventUpper === "STOP_FILL" ||
    eventUpper === "STOP_FILL_CONFIRMED" ||
    exitType.includes("stop")
  ) {
    type = "exit_filled";
    markerType = "stop_loss";
  } else if (
    phase === "exit_fill_confirmed" ||
    phase === "exit_fill" ||
    eventUpper === "EXIT" ||
    eventUpper === "EXIT_FILL" ||
    eventUpper === "EXIT_FILL_CONFIRMED" ||
    eventUpper === "SETTLE" ||
    eventUpper === "FINAL_EXIT"
  ) {
    type = "exit_filled";
    markerType =
      exitType.includes("tp")
        ? "tp"
        : (eventUpper === "SETTLE" || eventUpper === "FINAL_EXIT" ? "final_exit" : "final_exit");
  }
  if (!type) return null;
  return {
    instanceId,
    slug,
    sessionSlug: slug,
    tsMs: Number(tsMs),
    side,
    type,
    markerType: markerType || null,
    price: Number.isFinite(Number(price)) ? Number(price) : null,
    shares: Number.isFinite(shares) ? shares : null,
    pnlUsd: Number.isFinite(pnlUsd) ? pnlUsd : null,
    usdValue:
      Number.isFinite(shares) && Number.isFinite(Number(price))
        ? (Number(shares) * Number(price))
        : null,
    exitType: exitTypeRaw || null,
    event: String(action || eventName || type).trim().toLowerCase() || type,
    source: "trade_event",
  };
}

function buildLiveMarkersForInstanceSession(instance: BotInstance, slugLike: any): any[] {
  const slug = String(slugLike || "").trim();
  const runNum = Math.floor(Number(instance?.runNum || 0));
  if (!(runNum > 0) || !slug) return [];
  const persistedRows = readBotRunEventsCached(runNum);
  const recentRows = getRecentTradeEventsForInstance(instance?.instanceId);
  const rows = [
    ...(Array.isArray(persistedRows) ? persistedRows : []),
    ...(Array.isArray(recentRows) ? recentRows : []),
  ];
  if (!rows.length) return [];
  const markerMap = new Map<string, any>();
  rows
    .filter((row) => String(row?.instanceId || "").trim() === String(instance.instanceId || "").trim())
    .filter((row) => String(row?.marketSlug || row?.market?.slug || "").trim() === slug)
    .map((row, idx) => {
      const markerType = classifyLiveMarkerType(row);
      const tsMs = resolveLiveMarkerTsMs(row);
      const price = resolveLiveMarkerPrice(row);
      if (!markerType || !Number.isFinite(Number(tsMs)) || !Number.isFinite(Number(price))) return null;
      const shares = Number(row?.sharesClosed ?? row?.shares ?? NaN);
      const usdValue = Number.isFinite(shares) ? (shares * Number(price)) : null;
      return {
        key: `${String(instance.instanceId || "")}:${slug}:${markerType}:${Math.floor(Number(tsMs))}:${idx}`,
        markerType,
        slug,
        sessionSlug: slug,
        tsMs: Number(tsMs),
        price: Number(price),
        side: String(row?.side || row?.runtime?.side || "").trim().toUpperCase() || null,
        exitType: String(row?.exitType || "").trim().toLowerCase() || null,
        pnlUsd: Number.isFinite(Number(row?.pnlUsd)) ? Number(row.pnlUsd) : null,
        usdValue: Number.isFinite(Number(usdValue)) ? Number(usdValue) : null,
        event: String(row?.event || "").trim().toLowerCase() || null,
        source: "trade_event",
      };
    })
    .filter((row): row is any => !!row)
    .forEach((row) => {
      const key = `${String(instance.instanceId || "")}:${slug}:${String(row?.markerType || "")}:${Math.floor(Number(row?.tsMs || 0))}:${String(row?.side || "")}:${String(row?.exitType || "")}`;
      markerMap.set(key, row);
    });
  return Array.from(markerMap.values()).sort((a, b) => Number(a.tsMs || 0) - Number(b.tsMs || 0));
}

function buildContinuitySessionsForInstance(instance: BotInstance, includeTrace: boolean, maxSessions: number | null = null): { strategyId: string; runNum: number; continuityRuns: any[]; sessions: any[]; sig: string } {
  const instanceId = String(instance.instanceId || "").trim();
  const strategyId = String(instance.strategyId || "").trim();
  const currentRunNum = Math.floor(Number(instance.runNum));
  const runNums: number[] = [];
  const sigParts: string[] = [];
  if (Number.isFinite(currentRunNum) && currentRunNum > 0) {
    const prevRunNum = currentRunNum - 1;
    const prevIdxPath = botRunIndexPath(strategyId, prevRunNum);
    if (prevRunNum > 0 && fs.existsSync(prevIdxPath)) {
      runNums.push(prevRunNum);
      sigParts.push(fileCacheSignature(prevIdxPath));
    }
    runNums.push(currentRunNum);
    sigParts.push(fileCacheSignature(botRunIndexPath(strategyId, currentRunNum)));
  }
  const bySlug = new Map<string, any>();
  const continuityRuns: any[] = [];
  let continuityTraceSinceMs = Date.now() - 24 * 60 * 60 * 1000;
  for (const rn of runNums) {
    const idxPath = botRunIndexPath(strategyId, rn);
    if (!fs.existsSync(idxPath)) continue;
    const payload = readRunIndexPayloadCached(idxPath) || {};
    const summary = payload?.summary || {};
    continuityRuns.push({
      runNum: Number(summary?.runNum ?? rn),
      runId: String(summary?.runId || `run_${rn}`),
      strategyId: String(summary?.strategyId || strategyId),
      startedAtMs: Number.isFinite(Number(summary?.startedAtMs)) ? Number(summary.startedAtMs) : null,
      endedAtMs: Number.isFinite(Number(summary?.endedAtMs)) ? Number(summary.endedAtMs) : null,
    });
    if (includeTrace) {
      const startedAtMs = Number(summary?.startedAtMs);
      if (Number.isFinite(startedAtMs) && startedAtMs > 0) {
        continuityTraceSinceMs = Math.min(Number(continuityTraceSinceMs), Number(startedAtMs) - 5 * 60_000);
      }
    }
  }
  const continuityRunTraceBySlug = includeTrace
    ? readSessionTracesBySlug(Math.max(0, Number(continuityTraceSinceMs) || 0), null)
    : new Map<string, any>();
  for (const rn of runNums) {
    const idxPath = botRunIndexPath(strategyId, rn);
    if (!fs.existsSync(idxPath)) continue;
    const payload = readRunIndexPayloadCached(idxPath) || {};
    const summary = payload?.summary || {};
    const tracesBySlug = payload?.tracesBySlug && typeof payload.tracesBySlug === "object" ? payload.tracesBySlug : {};
    const sessions = Array.isArray(payload?.sessions) ? payload.sessions : [];
    for (const raw of sessions) {
      const slug = String(raw?.slug || "").trim();
      if (!slug) continue;
      const inferredStartMs = inferSessionStartMsFromSlug(slug);
      const inferredEndMs = Number.isFinite(Number(inferredStartMs))
        ? Number(inferredStartMs) + inferSessionDurationMsFromSlug(slug) - 1000
        : null;
      const rawEndMs = Number(raw?.endMs);
      const closeCandidateMs = Number.isFinite(rawEndMs) ? rawEndMs : inferredEndMs;
      const closed =
        raw?.closed === true
        || Number.isFinite(Number(raw?.exitTsMs))
        || (Number.isFinite(Number(closeCandidateMs)) && Number(closeCandidateMs) <= Date.now());
      const traceRaw = tracesBySlug[slug] || null;
      const traceIndex = compactSessionTraceForHistory(traceRaw);
      const traceRun = includeTrace ? compactSessionTraceForHistory(continuityRunTraceBySlug.get(slug) || null) : null;
      const traceCsv = compactSessionTraceForHistory(readSessionTraceFromCsv(slug));
      const traceCurrent = includeTrace ? compactSessionTraceForHistory(getCurrentSessionTraceForSlug(slug)) : null;
      const accountingTrace = choosePreferredClosedSessionTrace(slug, closed, traceCurrent, traceRun, traceCsv, traceIndex);
      const trace = includeTrace ? accountingTrace : null;
      const continuityRaw = {
        ...(raw && typeof raw === "object" ? raw : {}),
        startMs: Number.isFinite(Number(raw?.startMs)) ? Number(raw.startMs) : inferredStartMs,
        endMs: Number.isFinite(Number(raw?.endMs)) ? Number(raw.endMs) : inferredEndMs,
      };
      const normalizedBase = sanitizeContinuitySessionPayload(continuityRaw);
      const normalized = closed
        ? overlaySyntheticSettleIntoContinuitySession(normalizedBase, accountingTrace || null)
        : normalizedBase;
      const compact = readSessionAuditCompact(rn, slug);
      const compactCorrected = correctedAccountingFromCompactAuditSummary(compact);
      const corrected = closed
        ? (
            compactCorrected
            || buildExplicitPendingExitCorrectedAccountingFromCompact(compact, accountingTrace || null)
            || buildCorrectedSessionAccountingFromCompact(normalized, compact, accountingTrace || null)
            || buildCorrectedSessionAccountingFromEvents(rn, slug, accountingTrace || null)
          )
        : null;
      const synthSettleLane = Array.isArray(normalized?.lanes)
        ? normalized.lanes.find((ln: any) => String(ln?.via || "").trim().toLowerCase() === "continuity_synthesized_settle")
        : null;
      const synthesizedSettleLegPnlUsd = Number(synthSettleLane?.pnlUsd);
      const synthesizedSettlePnlUsd = Number(normalized?.correctedPnlUsd ?? normalized?.pnlUsd);
      const synthesizedSettleGrossPnlUsd = Number(normalized?.grossPnlUsd);
      const synthesizedSettleFeesUsd = Number(normalized?.feesUsd);
      const actualNetPnlUsd = Number.isFinite(Number(raw?.pnlUsd))
        ? Number(raw.pnlUsd)
        : (Number.isFinite(Number(normalizedBase?.pnlUsd)) ? Number(normalizedBase.pnlUsd) : null);
      const actualGrossPnlUsd = Number.isFinite(Number(raw?.grossPnlUsd))
        ? Number(raw.grossPnlUsd)
        : (Number.isFinite(Number(normalizedBase?.grossPnlUsd)) ? Number(normalizedBase.grossPnlUsd) : null);
      const actualFeesUsd = Number.isFinite(Number(raw?.feesUsd))
        ? Number(raw.feesUsd)
        : (Number.isFinite(Number(normalizedBase?.feesUsd)) ? Number(normalizedBase.feesUsd) : null);
      const hasSynthesizedSettle =
        String(normalized?.correctedExitStrategy || "").trim().toLowerCase() === "settle_remaining"
        && Number.isFinite(synthesizedSettlePnlUsd)
        && Array.isArray(normalized?.lanes)
        && normalized.lanes.some((ln: any) => String(ln?.via || "").trim().toLowerCase() === "continuity_synthesized_settle");
      const correctedNetPnlUsd = hasSynthesizedSettle
        ? (
            Number.isFinite(actualNetPnlUsd) && Number.isFinite(synthesizedSettleLegPnlUsd)
              ? Number((Number(actualNetPnlUsd) + Number(synthesizedSettleLegPnlUsd)).toFixed(10))
              : synthesizedSettlePnlUsd
          )
        : (corrected?.correctedNetPnlUsd ?? null);
      const correctedGrossPnlUsd = hasSynthesizedSettle
        ? (Number.isFinite(synthesizedSettleGrossPnlUsd) ? synthesizedSettleGrossPnlUsd : synthesizedSettlePnlUsd)
        : (corrected?.correctedGrossPnlUsd ?? null);
      const correctedFeesUsd = hasSynthesizedSettle
        ? (Number.isFinite(synthesizedSettleFeesUsd) ? synthesizedSettleFeesUsd : 0)
        : (corrected?.correctedFeesUsd ?? null);
      const correctedExitStrategy = hasSynthesizedSettle
        ? "settle_remaining"
        : (corrected?.correctedExitStrategy ?? null);
      const historicalCardReady = !closed
        ? true
        : ensureAccurateCanonicalSessionArtifactForHistory(instance, rn, normalized);
      if (closed && historicalCardReady === false) continue;
      const sess = {
        ...normalized,
        actualPnlUsd: corrected?.actualNetPnlUsd ?? actualNetPnlUsd,
        actualGrossPnlUsd: corrected?.actualGrossPnlUsd ?? actualGrossPnlUsd,
        actualFeesUsd: corrected?.actualFeesUsd ?? actualFeesUsd,
        correctedPnlUsd: correctedNetPnlUsd,
        correctedGrossPnlUsd: correctedGrossPnlUsd,
        correctedFeesUsd: correctedFeesUsd,
        settleNetPnlUsd: hasSynthesizedSettle
          ? (
              Number.isFinite(synthesizedSettleLegPnlUsd)
                ? Number(synthesizedSettleLegPnlUsd.toFixed(10))
                : (corrected?.settleNetPnlUsd ?? 0)
            )
          : (corrected?.settleNetPnlUsd ?? 0),
        correctedExitStrategy,
        pnlUsd: correctedNetPnlUsd ?? normalized?.pnlUsd ?? null,
        grossPnlUsd: correctedGrossPnlUsd ?? normalized?.grossPnlUsd ?? null,
        feesUsd: correctedFeesUsd ?? normalized?.feesUsd ?? null,
        instanceId,
        runNum: rn,
        runId: String(summary?.runId || `run_${rn}`),
        strategyMode: strategyId,
        startMs: Number.isFinite(Number(continuityRaw?.startMs))
          ? Number(continuityRaw.startMs)
          : inferredStartMs,
        endMs: Number.isFinite(Number(continuityRaw?.endMs))
          ? Number(continuityRaw.endMs)
          : inferredEndMs,
        humanLabel: (() => {
          const start = inferSessionStartMsFromSlug(slug);
          if (Number.isFinite(Number(start))) {
            const base = slug.replace(/-\d{10}$/, "");
            return `${base} @ ${new Date(Number(start)).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}`;
          }
          return slug;
        })(),
        historicalCardReady,
        trace,
        traceSource: includeTrace && accountingTrace ? String((accountingTrace as any)?.source || "run_index_trace") : null,
      };
      bySlug.set(slug, sess);
    }
  }
  const sessionsAll = Array.from(bySlug.values()).sort((a: any, b: any) => {
    const sa = Number(a?.startMs ?? inferSessionStartMsFromSlug(a?.slug));
    const sb = Number(b?.startMs ?? inferSessionStartMsFromSlug(b?.slug));
    return sb - sa;
  });
  const sessions = maxSessions != null && sessionsAll.length > maxSessions ? sessionsAll.slice(0, maxSessions) : sessionsAll;
  return {
    strategyId,
    runNum: currentRunNum,
    continuityRuns,
    sessions,
    sig: sigParts.length ? sigParts.join("||") : `${instanceId}|empty`,
  };
}

function buildRolloverReadyPayloadForInstance(instance: BotInstance): any {
  const instanceId = String(instance.instanceId || "").trim();
  const currentSlug = String(instance.marketSlug || "").trim();
  const derived = buildContinuitySessionsForInstance(instance, true, 12);
  const cacheKey = `${instanceId}|${currentSlug}|rollover-ready`;
  const cached = rolloverReadyCache.get(cacheKey);
  if (cached && String(cached.sig || "") === String(derived.sig || "")) {
    return cached.payload;
  }
  const previousSession = derived.sessions.find((row: any) => {
    const slug = String(row?.slug || "").trim();
    if (!slug || slug === currentSlug) return false;
    const hasTrace = Array.isArray(row?.trace?.xMs) && row.trace.xMs.length >= 2;
    const hasPnl = Number.isFinite(Number(row?.pnlUsd)) && Math.abs(Number(row.pnlUsd)) > 0.000001;
    return !!row?.closed || hasTrace || hasPnl;
  }) || null;
  const payload = {
    ok: true,
    instanceId,
    strategyId: derived.strategyId,
    runNum: derived.runNum,
    currentSlug,
    previousSession: previousSession ? {
      ...previousSession,
      liveMarkers: buildLiveMarkersForInstanceSession(instance, String(previousSession?.slug || "").trim()),
    } : null,
  };
  rolloverReadyCache.set(cacheKey, { sig: String(derived.sig || ""), payload });
  return payload;
}

function readSessionAuditCompact(runNum: number, slug: string): any | null {
  try {
    const rn = Math.floor(Number(runNum));
    const sg = String(slug || "").trim();
    if (!Number.isFinite(rn) || rn <= 0 || !sg) return null;
    const candidateBaseDirs = Array.from(new Set([
      path.resolve(botRunDir(rn)),
      SESSION_CARD_SOURCE_TRADE_LOG_DIR
        ? path.resolve(path.join(SESSION_CARD_SOURCE_TRADE_LOG_DIR, "multi_runs", `run_${rn}`))
        : "",
      path.resolve(path.join(TRADE_LOG_ROOT, "hosts", `host_${PORT}`, "multi_runs", `run_${rn}`)),
    ].filter(Boolean)));
    for (const baseDir of candidateBaseDirs) {
      const p = path.join(baseDir, "session_audits", `${sg}.compact.json`);
      if (!fs.existsSync(p)) continue;
      const key = `${p}:${sg}`;
      const st = fs.statSync(p);
      const mtimeMs = Number(st.mtimeMs || 0);
      const size = Number(st.size || 0);
      const prev = sessionAuditCompactCache.get(key);
      if (prev && Number(prev.mtimeMs) === mtimeMs && Number(prev.size) === size) {
        try { syncSessionAuditPnlTradeLog(rn, sg, prev.row ?? null); } catch {}
        return prev.row ?? null;
      }
      const row = JSON.parse(fs.readFileSync(p, "utf8"));
      sessionAuditCompactCache.set(key, { mtimeMs, size, row });
      trimSessionAuditCompactCache();
      try { syncSessionAuditPnlTradeLog(rn, sg, row); } catch {}
      if (row && typeof row === "object") return row;
    }
    return null;
  } catch {
    return null;
  }
}

const SESSION_AUDIT_PNL_ACTION_PAPER = "SESSION_AUDIT_PNL_PAPER";
const SESSION_AUDIT_PNL_ACTION_RE = /^SESSION_AUDIT_PNL_(PAPER|LIVE)$/i;
const sessionAuditTradeLogSigByKey = new Map<string, string>();
const sessionAuditRunBackfillSigByRun = new Map<number, string>();

function inferSessionEndMsFromSlug(slugLike: any): number | null {
  const startMs = inferSessionStartMsFromSlug(slugLike);
  if (!(Number.isFinite(Number(startMs)) && Number(startMs) > 0)) return null;
  const durationMs = inferSessionDurationMsFromSlug(slugLike);
  if (!(Number.isFinite(Number(durationMs)) && Number(durationMs) > 0)) return null;
  return Number(startMs) + Number(durationMs) - 1000;
}

function latestAuditAccountingFromCompact(compactLike: any): {
  actualNetPnlUsd: number | null;
  correctedNetPnlUsd: number | null;
  correctedGrossPnlUsd: number | null;
  correctedFeesUsd: number | null;
  correctedDeltaUsd: number | null;
  projectedFillNetPnlUsd: number | null;
  settleNetPnlUsd: number | null;
  correctedExitStrategy: string | null;
} | null {
  const compact = compactLike && typeof compactLike === "object" ? compactLike : null;
  if (!compact) return null;
  const corrected =
    correctedAccountingFromCompactAuditSummary(compact)
    || buildExplicitPendingExitCorrectedAccountingFromCompact(compact, null);
  const sessionSummary = compact?.sessionSummary && typeof compact.sessionSummary === "object"
    ? compact.sessionSummary
    : {};
  const actualNetPnlUsd = Number.isFinite(Number(sessionSummary?.pnlUsd))
    ? Number(sessionSummary.pnlUsd)
    : (corrected?.actualNetPnlUsd ?? null);
  const correctedNetPnlUsd = corrected?.correctedNetPnlUsd ?? actualNetPnlUsd;
  if (!Number.isFinite(Number(correctedNetPnlUsd))) return null;
  return {
    actualNetPnlUsd: Number.isFinite(Number(actualNetPnlUsd)) ? Number(actualNetPnlUsd) : null,
    correctedNetPnlUsd: Number(correctedNetPnlUsd),
    correctedGrossPnlUsd: Number.isFinite(Number(corrected?.correctedGrossPnlUsd))
      ? Number(corrected?.correctedGrossPnlUsd)
      : null,
    correctedFeesUsd: Number.isFinite(Number(corrected?.correctedFeesUsd))
      ? Number(corrected?.correctedFeesUsd)
      : null,
    correctedDeltaUsd: Number.isFinite(Number(corrected?.correctedDeltaUsd))
      ? Number(corrected?.correctedDeltaUsd)
      : null,
    projectedFillNetPnlUsd: Number.isFinite(Number(corrected?.projectedFillNetPnlUsd))
      ? Number(corrected?.projectedFillNetPnlUsd)
      : null,
    settleNetPnlUsd: Number.isFinite(Number(corrected?.settleNetPnlUsd))
      ? Number(corrected?.settleNetPnlUsd)
      : null,
    correctedExitStrategy: corrected?.correctedExitStrategy != null
      ? String(corrected.correctedExitStrategy)
      : null,
  };
}

function syncSessionAuditPnlTradeLog(runNum: number, slugLike: any, compactLike: any): any | null {
  try {
    const rn = Math.floor(Number(runNum));
    const slug = String(slugLike || "").trim().toLowerCase();
    const compact = compactLike && typeof compactLike === "object" ? compactLike : null;
    if (!(Number.isFinite(rn) && rn > 0 && slug && compact)) return null;
    const accounting = latestAuditAccountingFromCompact(compact);
    if (!accounting || !Number.isFinite(Number(accounting.correctedNetPnlUsd))) return null;
    const generatedAtMsRaw = Date.parse(String(compact?.generatedAtIso || ""));
    const generatedAtMs = Number.isFinite(generatedAtMsRaw) && generatedAtMsRaw > 0
      ? Number(generatedAtMsRaw)
      : nowMs();
    const signature = JSON.stringify({
      generatedAtMs,
      correctedNetPnlUsd: Number(accounting.correctedNetPnlUsd),
      actualNetPnlUsd: Number.isFinite(Number(accounting.actualNetPnlUsd)) ? Number(accounting.actualNetPnlUsd) : null,
      correctedDeltaUsd: Number.isFinite(Number(accounting.correctedDeltaUsd)) ? Number(accounting.correctedDeltaUsd) : null,
      excludeFromPnl: !!compact?.excludeFromPnl,
      issues: Array.isArray(compact?.issues) ? compact.issues : [],
    });
    const sigKey = `${rn}:${slug}`;
    if (sessionAuditTradeLogSigByKey.get(sigKey) === signature) return null;
    sessionAuditTradeLogSigByKey.set(sigKey, signature);

    const summary = readBotRunSummary(rn) || null;
    const sessionSummary = compact?.sessionSummary && typeof compact.sessionSummary === "object"
      ? compact.sessionSummary
      : {};
    const sessionStartMs = Number.isFinite(Number(sessionSummary?.startMs))
      ? Number(sessionSummary.startMs)
      : inferSessionStartMsFromSlug(slug);
    const sessionEndMs = Number.isFinite(Number(sessionSummary?.endMs))
      ? Number(sessionSummary.endMs)
      : (
          Number.isFinite(Number(sessionSummary?.exitTsMs))
            ? Number(sessionSummary.exitTsMs)
            : inferSessionEndMsFromSlug(slug)
        );
    const payload = {
      type: "trade",
      runId: rn,
      runStartMs: Number.isFinite(Number(summary?.startedAtMs)) ? Number(summary.startedAtMs) : CURRENT_RUN_START_MS,
      runStartIso: String(summary?.startedAtIso || summary?.startedAt || CURRENT_RUN_START_ISO || ""),
      t: generatedAtMs,
      iso: new Date(generatedAtMs).toISOString(),
      engine: "paper" as Engine,
      executionMode: "audit",
      action: SESSION_AUDIT_PNL_ACTION_PAPER,
      instanceId: String(compact?.instanceId || summary?.instanceId || "").trim() || null,
      strategyId: String(compact?.strategyId || summary?.strategyId || "").trim() || null,
      market: {
        slug,
        startMs: Number.isFinite(Number(sessionStartMs)) ? Number(sessionStartMs) : null,
        endMs: Number.isFinite(Number(sessionEndMs)) ? Number(sessionEndMs) : null,
        volumeUsd: null,
      },
      st: {
        marketSlug: slug,
        entered: false,
        exited: true,
        side: null,
        entryTsMs: Number.isFinite(Number(sessionStartMs)) ? Number(sessionStartMs) : null,
        exitTsMs: Number.isFinite(Number(sessionEndMs)) ? Number(sessionEndMs) : null,
        entryPx: null,
        exitPx: null,
        shares: null,
        notionalUsd: null,
        grossPnlUsd: Number.isFinite(Number(accounting.correctedGrossPnlUsd)) ? Number(accounting.correctedGrossPnlUsd) : null,
        entryFeeUsd: null,
        exitFeeUsd: null,
        totalFeesUsd: Number.isFinite(Number(accounting.correctedFeesUsd)) ? Number(accounting.correctedFeesUsd) : null,
        pnlUsd: Number(accounting.correctedNetPnlUsd),
        roiPct: null,
        holdSec: null,
        balanceUsd: null,
        stopFallbackTriggered: false,
      },
      sessionAudit: {
        source: "compact_audit",
        generatedAtIso: String(compact?.generatedAtIso || new Date(generatedAtMs).toISOString()),
        completedAtMs: generatedAtMs,
        sessionStartMs: Number.isFinite(Number(sessionStartMs)) ? Number(sessionStartMs) : null,
        sessionEndMs: Number.isFinite(Number(sessionEndMs)) ? Number(sessionEndMs) : null,
        actualNetPnlUsd: Number.isFinite(Number(accounting.actualNetPnlUsd)) ? Number(accounting.actualNetPnlUsd) : null,
        correctedNetPnlUsd: Number(accounting.correctedNetPnlUsd),
        correctedDeltaUsd: Number.isFinite(Number(accounting.correctedDeltaUsd)) ? Number(accounting.correctedDeltaUsd) : null,
        projectedFillNetPnlUsd: Number.isFinite(Number(accounting.projectedFillNetPnlUsd)) ? Number(accounting.projectedFillNetPnlUsd) : null,
        settleNetPnlUsd: Number.isFinite(Number(accounting.settleNetPnlUsd)) ? Number(accounting.settleNetPnlUsd) : null,
        correctedExitStrategy: accounting.correctedExitStrategy,
        excludeFromPnl: !!compact?.excludeFromPnl,
        issues: Array.isArray(compact?.issues) ? compact.issues.slice() : [],
      },
    };
    appendTradeLog(payload);
    return payload;
  } catch {
    return null;
  }
}

function syncSessionAuditPnlTradeLogsForRun(runNum: number): void {
  try {
    const rn = Math.floor(Number(runNum));
    if (!(Number.isFinite(rn) && rn > 0)) return;
    const auditDir = path.join(botRunDir(rn), "session_audits");
    if (!fs.existsSync(auditDir)) return;
    const files = fs.readdirSync(auditDir)
      .filter((name) => /\.compact\.json$/i.test(String(name || "")))
      .map((name) => path.join(auditDir, name))
      .filter((p) => fs.existsSync(p))
      .sort();
    let newestMtimeMs = 0;
    for (const filePath of files) {
      try {
        newestMtimeMs = Math.max(newestMtimeMs, Number(fs.statSync(filePath).mtimeMs || 0));
      } catch {}
    }
    const signature = `${files.length}:${newestMtimeMs}`;
    if (sessionAuditRunBackfillSigByRun.get(rn) === signature) return;
    sessionAuditRunBackfillSigByRun.set(rn, signature);
    for (const filePath of files) {
      try {
        const compact = JSON.parse(fs.readFileSync(filePath, "utf8"));
        const slug = String(path.basename(filePath).replace(/\.compact\.json$/i, "") || "").trim().toLowerCase();
        if (!slug) continue;
        syncSessionAuditPnlTradeLog(rn, slug, compact);
      } catch {}
    }
  } catch {}
}

function compactAuditHasExplicitPendingExitOrders(compactLike: any): boolean {
  try {
    const compact = compactLike && typeof compactLike === "object" ? compactLike : null;
    const sideAudit = compact?.sideAudit && typeof compact.sideAudit === "object" ? compact.sideAudit : {};
    for (const side of ["UP", "DOWN"]) {
      const audit = sideAudit?.[side];
      if (!audit || typeof audit !== "object") continue;
      const timeline = Array.isArray(audit?.timeline) ? audit.timeline : [];
      for (const row of timeline) {
        const ev = String(row?.event || "").trim().toLowerCase();
        if (ev !== "exit_order") continue;
        const px =
          Number(row?.intendedPx ?? row?.px ?? row?.signalPx ?? row?.exitPx ?? row?.actualFillPx);
        const shares =
          Number(row?.sharesActual ?? row?.sharesRequested ?? row?.sharesClosed ?? row?.soldShares ?? row?.shares);
        if (Number.isFinite(px) && px >= 0 && px <= 1.1 && Number.isFinite(shares) && shares > 1e-6) {
          return true;
        }
      }
    }
  } catch {}
  return false;
}

function correctedAccountingFromCompactAuditSummary(compactLike: any): {
  actualNetPnlUsd: number | null;
  actualGrossPnlUsd: number | null;
  actualFeesUsd: number | null;
  correctedNetPnlUsd: number;
  correctedGrossPnlUsd: number | null;
  correctedFeesUsd: number | null;
  correctedDeltaUsd: number | null;
  projectedFillNetPnlUsd: number;
  settleNetPnlUsd: number;
  correctedExitStrategy: string;
} | null {
  const compact = compactLike && typeof compactLike === "object" ? compactLike : null;
  const summary = compact && compact.correctedSummary && typeof compact.correctedSummary === "object"
    ? compact.correctedSummary
    : null;
  if (!summary) return null;
  const correctedExitStrategy = String(summary.correctedExitStrategy || "actual_fills_only");
  if (
    /settle_remaining/i.test(correctedExitStrategy)
    && compactAuditHasExplicitPendingExitOrders(compact)
  ) {
    return null;
  }
  const correctedNetPnlUsd = Number(summary.correctedNetPnlUsd);
  if (!Number.isFinite(correctedNetPnlUsd)) return null;
  return {
    actualNetPnlUsd: Number.isFinite(Number(summary.actualNetPnlUsd)) ? Number(summary.actualNetPnlUsd) : null,
    actualGrossPnlUsd: Number.isFinite(Number(summary.actualGrossPnlUsd)) ? Number(summary.actualGrossPnlUsd) : null,
    actualFeesUsd: Number.isFinite(Number(summary.actualFeesUsd)) ? Number(summary.actualFeesUsd) : null,
    correctedNetPnlUsd,
    correctedGrossPnlUsd: Number.isFinite(Number(summary.correctedGrossPnlUsd)) ? Number(summary.correctedGrossPnlUsd) : null,
    correctedFeesUsd: Number.isFinite(Number(summary.correctedFeesUsd)) ? Number(summary.correctedFeesUsd) : null,
    correctedDeltaUsd: Number.isFinite(Number(summary.correctedDeltaUsd)) ? Number(summary.correctedDeltaUsd) : null,
    projectedFillNetPnlUsd: Number.isFinite(Number(summary.projectedFillNetPnlUsd)) ? Number(summary.projectedFillNetPnlUsd) : 0,
    settleNetPnlUsd: Number.isFinite(Number(summary.settleNetPnlUsd)) ? Number(summary.settleNetPnlUsd) : 0,
    correctedExitStrategy,
  };
}

function buildExplicitPendingExitCorrectedAccountingFromCompact(compactLike: any, traceLike: any): any | null {
  try {
    const compact = compactLike && typeof compactLike === "object" ? compactLike : null;
    if (!compact || !compactAuditHasExplicitPendingExitOrders(compact)) return null;
    const toFinite = (v: any): number | null => {
      const n = Number(v);
      return Number.isFinite(n) ? n : null;
    };
    const isSyntheticSettle = (rowLike: any): boolean => {
      const row = rowLike && typeof rowLike === "object" ? rowLike : null;
      if (!row) return false;
      const exitType = String(row?.exitType || "").trim().toLowerCase();
      const fillSource = String(row?.fillSource || "").trim().toLowerCase();
      return row?.synthetic === true || exitType === "settle" || /synthesized_settle/.test(fillSource);
    };
    const sideAudit = compact?.sideAudit && typeof compact.sideAudit === "object" ? compact.sideAudit : {};
    const sessionSummary = compact?.sessionSummary && typeof compact.sessionSummary === "object" ? compact.sessionSummary : {};
    const actualNetPnlUsd = Number.isFinite(Number(sessionSummary?.pnlUsd)) ? Number(sessionSummary.pnlUsd) : 0;
    const actualFeesUsd = Number.isFinite(Number(sessionSummary?.feesUsd)) ? Number(sessionSummary.feesUsd) : 0;
    const actualGrossPnlUsd = Number.isFinite(Number(sessionSummary?.grossPnlUsd))
      ? Number(sessionSummary.grossPnlUsd)
      : Number(actualNetPnlUsd) + Number(actualFeesUsd);
    let correctedNetPnlUsd = Number(actualNetPnlUsd) || 0;
    let correctedGrossPnlUsd = Number(actualGrossPnlUsd) || 0;
    let projectedFillNetPnlUsd = 0;
    let settleNetPnlUsd = 0;
    const correctedBits = new Set<string>();

    for (const side of ["UP", "DOWN"] as OutcomeSide[]) {
      const audit = sideAudit?.[side] && typeof sideAudit[side] === "object" ? sideAudit[side] : {};
      const fills = audit?.fills && typeof audit.fills === "object" ? audit.fills : {};
      const timeline = Array.isArray(audit?.timeline) ? audit.timeline : [];
      const entryFill =
        (fills?.entry && typeof fills.entry === "object" ? fills.entry : null)
        || timeline.find((row: any) => String(row?.event || "").trim().toLowerCase() === "enter")
        || null;
      const entryPx =
        toFinite(entryFill?.entryPx)
        ?? toFinite(entryFill?.actualFillPx)
        ?? toFinite(entryFill?.fillPx)
        ?? toFinite(entryFill?.signalPx)
        ?? null;
      const entryShares =
        toFinite(entryFill?.shares)
        ?? toFinite(entryFill?.sharesRequested)
        ?? null;
      if (!(Number.isFinite(Number(entryPx)) && Number(entryPx) > 0 && Number.isFinite(Number(entryShares)) && Number(entryShares) > 1e-6)) {
        continue;
      }
      let remainingShares = Number(entryShares);
      const actualExitFills = [
        fills?.derisk && typeof fills.derisk === "object" ? fills.derisk : null,
        fills?.exit && typeof fills.exit === "object" ? fills.exit : null,
      ].filter((row: any) => row && !isSyntheticSettle(row));
      for (const fill of actualExitFills) {
        const sharesClosed = Math.max(0, Number(toFinite(fill?.sharesClosed) ?? toFinite(fill?.soldShares) ?? toFinite(fill?.shares) ?? 0));
        if (sharesClosed > 1e-6) remainingShares = Math.max(0, remainingShares - sharesClosed);
      }
      const exitOrders = timeline
        .filter((row: any) => String(row?.event || "").trim().toLowerCase() === "exit_order")
        .sort((a: any, b: any) => Number(a?.tsMs || 0) - Number(b?.tsMs || 0));
      for (const row of exitOrders) {
        if (!(remainingShares > 1e-6)) break;
        const px =
          toFinite(row?.exitPx)
          ?? toFinite(row?.intendedPx)
          ?? toFinite(row?.actualFillPx)
          ?? toFinite(row?.fillPx)
          ?? null;
        const requestedShares =
          toFinite(row?.sharesRequested)
          ?? toFinite(row?.sharesActual)
          ?? toFinite(row?.sharesClosed)
          ?? toFinite(row?.shares)
          ?? null;
        if (!(Number.isFinite(Number(px)) && Number(px) >= 0 && Number(px) <= 1.1)) continue;
        const sharesClosed = Math.max(
          0,
          Math.min(
            remainingShares,
            Number.isFinite(Number(requestedShares)) && Number(requestedShares) > 0 ? Number(requestedShares) : remainingShares
          )
        );
        if (!(sharesClosed > 1e-6)) continue;
        const gross = (Number(px) - Number(entryPx)) * sharesClosed;
        projectedFillNetPnlUsd += gross;
        correctedGrossPnlUsd += gross;
        correctedNetPnlUsd += gross;
        remainingShares = Math.max(0, remainingShares - sharesClosed);
        correctedBits.add("projected_exit_fill");
      }
      if (remainingShares > 1e-6) {
        const settlePx = correctedSettlePxForOutcomeTrace(traceLike, side);
        if (Number.isFinite(Number(settlePx))) {
          const settleGross = (Number(settlePx) - Number(entryPx)) * remainingShares;
          settleNetPnlUsd += settleGross;
          correctedGrossPnlUsd += settleGross;
          correctedNetPnlUsd += settleGross;
          correctedBits.add("settle_remaining");
        }
      }
    }

    return {
      actualNetPnlUsd: Number(Number(actualNetPnlUsd || 0).toFixed(10)),
      actualGrossPnlUsd: Number(Number(actualGrossPnlUsd || 0).toFixed(10)),
      actualFeesUsd: Number(Number(actualFeesUsd || 0).toFixed(4)),
      correctedNetPnlUsd: Number(Number(correctedNetPnlUsd || 0).toFixed(10)),
      correctedGrossPnlUsd: Number(Number(correctedGrossPnlUsd || 0).toFixed(10)),
      correctedFeesUsd: Number(Number(actualFeesUsd || 0).toFixed(4)),
      correctedDeltaUsd: Number(Number((correctedNetPnlUsd || 0) - (actualNetPnlUsd || 0)).toFixed(10)),
      projectedFillNetPnlUsd: Number(Number(projectedFillNetPnlUsd || 0).toFixed(10)),
      settleNetPnlUsd: Number(Number(settleNetPnlUsd || 0).toFixed(10)),
      correctedExitStrategy: correctedBits.size ? Array.from(correctedBits.values()).join(" + ") : "actual_fills_only",
    };
  } catch {
    return null;
  }
}

function humanizeNoTradeReason(rawLike: any): string | null {
  const raw = String(rawLike || "").trim();
  if (!raw) return null;
  const key = raw.toUpperCase();
  const exactMap: Record<string, string> = {
    ENTRY_QUOTES_STALE: "entry blocked because live gap was too high",
    NO_STRATEGY_ENTER_SIDE: "no EMA cross was detected",
    NO_EMA_CROSS_DETECTED: "no EMA cross was detected",
    ENTRY_AT_OR_ABOVE_TP: "entry blocked because price was already at take-profit",
    ENTRY_AT_OR_ABOVE_DERISK: "entry blocked because price was already at derisk",
    OPEN_POSITION_ACTIVE: "entry blocked because a position was already open",
    OPEN_OR_CLOSING_POSITION: "entry blocked because a position was open or closing",
    TP_REARM_REQUIRED: "entry blocked until TP rearm was complete",
    DERISK_SIDE_ALREADY_ENTERED: "entry blocked because that side had already entered",
    LIVE_SIDE_ALREADY_ATTEMPTED: "entry blocked because that live side was already attempted",
    BUY_ATTEMPTED_THIS_SESSION: "entry blocked because a buy was already attempted this session",
    BUY_FILLED_THIS_SESSION: "entry blocked because a buy had already filled this session",
    SIDE_ALREADY_ENTERED_THIS_SESSION: "entry blocked because that side already entered this session",
    LANE_ALREADY_ENTERED_THIS_SESSION: "entry blocked because that lane already entered this session",
    ENTER_IN_FLIGHT: "entry blocked because an entry was already in flight",
    ENTER_ATTEMPT_COOLDOWN: "entry blocked because entry cooldown was active",
    STARTUP_MID_SESSION_GUARD: "entry blocked by startup mid-session guard",
    NON_POSITIVE_NOTIONAL: "entry blocked because notional was non-positive",
    INSUFFICIENT_SAMPLES: "insufficient samples for a valid signal",
    NONFINITE_POINT: "signal window contained non-finite data",
    NOT_STRICTLY_INCREASING: "signal window was not strictly increasing enough for the EMA entry gate",
    INFERRED_TOUCH_NO_EXPLICIT_SIGNAL: "price touched the level but no explicit entry signal was recorded",
    DERISK_TOUCH_NO_DERISK_FILL: "derisk touched but no derisk fill was recorded",
  };
  if (exactMap[key]) return exactMap[key];
  let text = raw
    .replace(/^ENTRY_BLOCKED[_:\s-]*/i, "")
    .replace(/^NO[_:\s-]*/i, "no ")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
  if (!text) return null;
  text = text.replace(/\bema\b/g, "EMA");
  text = text.replace(/\btp\b/g, "TP");
  text = text.replace(/\bsl\b/g, "SL");
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function summarizeNoTradeReasonFromCompactAudit(compact: any): string | null {
  try {
    const root = compact && typeof compact === "object" ? compact : null;
    const sideAudit = root?.sideAudit && typeof root.sideAudit === "object" ? root.sideAudit : {};
    const candidates: string[] = [];
    for (const side of ["UP", "DOWN"]) {
      const audit = sideAudit?.[side];
      if (!audit || typeof audit !== "object") continue;
      const timeline = Array.isArray(audit?.timeline) ? audit.timeline : [];
      for (let i = timeline.length - 1; i >= 0; i -= 1) {
        const row = timeline[i];
        const ev = String(row?.event || "").trim().toLowerCase();
        if (ev !== "entry_blocked") continue;
        const reason =
          humanizeNoTradeReason(row?.entryBlockReason)
          || humanizeNoTradeReason(row?.entryBlockCode)
          || humanizeNoTradeReason(row?.reason);
        if (reason) candidates.push(reason);
      }
      const inferred = Array.isArray(audit?.inferredBlockers) ? audit.inferredBlockers : [];
      for (const blocker of inferred) {
        const reason = humanizeNoTradeReason(blocker);
        if (reason) candidates.push(reason);
      }
    }
    return candidates.find(Boolean) || null;
  } catch {
    return null;
  }
}

function summarizeNoTradeReasonFromEventRows(rowsLike: any[]): string | null {
  try {
    const rows = (Array.isArray(rowsLike) ? rowsLike : [])
      .filter((row) => row && typeof row === "object")
      .slice()
      .sort((a, b) => Number(a?.t || 0) - Number(b?.t || 0));
    if (!rows.length) return null;
    for (let i = rows.length - 1; i >= 0; i -= 1) {
      const row = rows[i];
      if (String(row?.event || "").trim().toLowerCase() !== "entry_blocked") continue;
      const reason =
        humanizeNoTradeReason(row?.entryBlockReason)
        || humanizeNoTradeReason(row?.entryBlockCode)
        || humanizeNoTradeReason(row?.reason);
      if (reason) return reason;
    }
    const hasEntryAttempt = rows.some((row) => {
      const ev = String(row?.event || "").trim().toLowerCase();
      return ev === "enter_signal" || ev === "enter_order" || ev === "enter";
    });
    if (!hasEntryAttempt) {
      for (let i = rows.length - 1; i >= 0; i -= 1) {
        const snap = rows[i]?.decisionSnapshot;
        if (!snap || typeof snap !== "object") continue;
        const upFailure = humanizeNoTradeReason(extractDecisionWindowFromSnapshot(snap, "UP")?.failureReason);
        const downFailure = humanizeNoTradeReason(extractDecisionWindowFromSnapshot(snap, "DOWN")?.failureReason);
        if (upFailure && downFailure) {
          if (upFailure === downFailure) return upFailure;
          return `UP: ${upFailure} / DOWN: ${downFailure}`;
        }
        if (upFailure || downFailure) return upFailure || downFailure;
      }
    }
    const last = rows[rows.length - 1] || null;
    return (
      humanizeNoTradeReason(last?.entryBlockReason)
      || humanizeNoTradeReason(last?.entryBlockCode)
      || humanizeNoTradeReason(last?.reason)
      || null
    );
  } catch {
    return null;
  }
}

function buildNoTradeReasonMapForRun(runNumLike: any): Map<string, string> {
  const out = new Map<string, string>();
  try {
    const runNum = Math.floor(Number(runNumLike));
    if (!(runNum > 0)) return out;
    const bySlug = new Map<string, any[]>();
    for (const row of readBotRunEventsCached(runNum)) {
      const slug = String(row?.marketSlug || row?.market?.slug || "").trim();
      if (!slug) continue;
      const rows = bySlug.get(slug) || [];
      rows.push(row);
      bySlug.set(slug, rows);
    }
    for (const [slug, rows] of bySlug.entries()) {
      const reason = summarizeNoTradeReasonFromEventRows(rows);
      if (reason) out.set(slug, reason);
    }
    return out;
  } catch {
    return out;
  }
}

