  String(process.env.BTC_5M_DATA_DIR || path.resolve(process.cwd(), "btc_5m_data")).trim()
  || path.resolve(process.cwd(), "btc_5m_data");
const BTC_5M_RECORD_ENABLED = process.env.BTC_5M_RECORD_ENABLED !== "0";
const BTC_5M_RECORD_MIN_INTERVAL_MS = Math.max(
  HOT_HOST_TRACE_LIGHT_MODE ? 250 : 0,
  Number(process.env.BTC_5M_RECORD_MIN_INTERVAL_MS || 50)
);
const BTC_5M_CSV_HEADER = "seconds,UP Price,Down Price";
const btc5mCsvLastWriteMsBySlug = new Map<string, number>();
const btc5mCsvHeaderEnsured = new Set<string>();
const sessionTraceLastSampleMsBySlug = new Map<string, number>();
const sessionAlgoInputLastSampleMsBySlug = new Map<string, number>();

function ensureBtc5mDataDir() {
  try {
    fs.mkdirSync(BTC_5M_DATA_DIR, { recursive: true });
  } catch {}
}

function sessionCsvFileNameFromSlug(slugRaw: any): string | null {
  const slug = String(slugRaw || "");
  const m = slug.match(/-(\d{10})$/);
  if (!m) return null;
  const startSec = Number(m[1]);
  if (!Number.isFinite(startSec)) return null;
  const endSec = startSec + 300;

  const d = new Date(startSec * 1000);
  const month = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    month: "long",
  }).format(d);
  const day = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    day: "numeric",
  }).format(d);
  const fromLabel = buildEtSessionLabel(startSec);
  const toLabel = buildEtSessionLabel(endSec);
  return `Bitcoin Up or Down - ${month} ${day}, ${fromLabel}-${toLabel} ET.csv`;
}

function sessionCsvWritePathFromSlug(slugRaw: any): string | null {
  const fileName = sessionCsvFileNameFromSlug(slugRaw);
  if (!fileName) return null;
  return path.resolve(BTC_5M_DATA_DIR, fileName);
}

function ensureBtc5mCsvHeader(filePath: string) {
  if (btc5mCsvHeaderEnsured.has(filePath)) return;
  ensureBtc5mDataDir();
  try {
    const exists = fs.existsSync(filePath);
    const size = exists ? Number(fs.statSync(filePath).size || 0) : 0;
    if (!exists || size <= 0) {
      fs.writeFileSync(filePath, `${BTC_5M_CSV_HEADER}\n`, "utf8");
    } else {
      const raw = fs.readFileSync(filePath, "utf8");
      const lines = raw.split(/\r?\n/);
      const header = String(lines[0] || "").trim();
      if (header !== BTC_5M_CSV_HEADER) {
        const migratedRows = lines
          .slice(1)
          .map((line) => String(line || "").trim())
          .filter(Boolean)
          .map((line) => {
            const cols = line.split(",");
            if (cols.length >= 3) return cols.slice(0, 3).join(",");
            return "";
          })
          .filter(Boolean);
        const migratedRaw = `${BTC_5M_CSV_HEADER}\n${migratedRows.join("\n")}${migratedRows.length ? "\n" : ""}`;
        fs.writeFileSync(filePath, migratedRaw, "utf8");
      }
    }
    btc5mCsvHeaderEnsured.add(filePath);
  } catch (err) {
    console.error(`[${isoNow()}] btc_5m_data header ensure error:`, err);
  }
}

function appendBtc5mCsvTracePoint(
  slugRaw: any,
  startMsRaw: any,
  tMsRaw: any,
  upBidRaw: any,
  downBidRaw: any,
  lagSnapshotRaw?: any
) {
  if (!BTC_5M_RECORD_ENABLED) return;
  const slug = String(slugRaw || "").trim();
  if (!slug) return;
  const tMs = Number(tMsRaw);
  const upBidNum = toFiniteOrNull(upBidRaw);
  const downBidNum = toFiniteOrNull(downBidRaw);
  const upBid =
    Number.isFinite(Number(upBidNum)) && Number(upBidNum) > 0 && Number(upBidNum) <= 1 ? Number(upBidNum) : null;
  const downBid =
    Number.isFinite(Number(downBidNum)) && Number(downBidNum) > 0 && Number(downBidNum) <= 1 ? Number(downBidNum) : null;
  if (!Number.isFinite(tMs) || !Number.isFinite(upBid) || !Number.isFinite(downBid)) return;

  const lastWriteMs = Number(btc5mCsvLastWriteMsBySlug.get(slug) || 0);
  if (Number.isFinite(lastWriteMs) && lastWriteMs > 0 && (tMs - lastWriteMs) < BTC_5M_RECORD_MIN_INTERVAL_MS) return;

  const startMs =
    Number.isFinite(Number(startMsRaw)) && Number(startMsRaw) > 0
      ? Number(startMsRaw)
      : slugStartMsFromSlug(slug);
  if (!Number.isFinite(startMs) || startMs <= 0) return;

  const elapsedMs = Math.max(0, tMs - startMs);
  if (elapsedMs > (5 * 60 * 1000) + 5000) return;

  const filePath = sessionCsvWritePathFromSlug(slug);
  if (!filePath) return;
  ensureBtc5mCsvHeader(filePath);
  btc5mCsvLastWriteMsBySlug.set(slug, tMs);
  const row =
    `${(elapsedMs / 1000).toFixed(3)},${Number(upBid).toFixed(6)},${Number(downBid).toFixed(6)}\n`;
  enqueueBufferedAppend(filePath, row, "btc_5m_data append error");
}

function recordSessionTracePoint(slug: string, tMs: number, upBid: number | null, downBid: number | null) {
  const s = String(slug || "");
  if (!s) return;
  const normTraceBid = (v: any): number | null => {
    const x = toFiniteOrNull(v);
    return Number.isFinite(Number(x)) && Number(x) > 0 && Number(x) <= 1 ? Number(x) : null;
  };
  const up = normTraceBid(upBid);
  const down = normTraceBid(downBid);
  if (!Number.isFinite(up) && !Number.isFinite(down)) return;
  const t = Number(tMs);
  if (!Number.isFinite(t)) return;
  const mem = sessionTraceMem.get(s) || {
    xMs: [],
    up: [],
    down: [],
    seq: [],
    markers: [],
    sourceFile: "session_trace_runlog",
  };
  const lastIdx = mem.xMs.length - 1;
  const lastT = lastIdx >= 0 ? Number(mem.xMs[lastIdx]) : NaN;
  const lastSampleT = Number(sessionTraceLastSampleMsBySlug.get(s) || 0);
  const shouldMergeIntoLast =
    Number.isFinite(lastT) &&
    (
      t <= lastT ||
      (
        Number.isFinite(lastSampleT) &&
        lastSampleT > 0 &&
        (t - lastSampleT) < SESSION_TRACE_MAIN_LOOP_SAMPLE_MIN_MS
      )
    );
  if (shouldMergeIntoLast) {
    mem.up[lastIdx] = Number.isFinite(up) ? Number(up) : NaN;
    mem.down[lastIdx] = Number.isFinite(down) ? Number(down) : NaN;
    if (Array.isArray(mem.seq)) mem.seq[lastIdx] = lastIdx + 1;
    sessionTraceMem.set(s, mem);
    if (Number.isFinite(t) && t > 0) sessionTraceLastSampleMsBySlug.set(s, t);
    return;
  }
  mem.xMs.push(t);
  mem.up.push(Number.isFinite(up) ? Number(up) : NaN);
  mem.down.push(Number.isFinite(down) ? Number(down) : NaN);
  if (Array.isArray(mem.seq)) mem.seq.push(mem.xMs.length);
  if (mem.xMs.length > SESSION_TRACE_MEM_MAX_POINTS) {
    mem.xMs.splice(0, mem.xMs.length - SESSION_TRACE_MEM_MAX_POINTS);
    mem.up.splice(0, mem.up.length - SESSION_TRACE_MEM_MAX_POINTS);
    mem.down.splice(0, mem.down.length - SESSION_TRACE_MEM_MAX_POINTS);
    if (Array.isArray(mem.seq)) mem.seq.splice(0, mem.seq.length - SESSION_TRACE_MEM_MAX_POINTS);
  }
  sessionTraceMem.set(s, mem);
  sessionTraceLastSampleMsBySlug.set(s, t);

  const lastWrite = lastSessionTraceWriteMsBySlug.get(s) || 0;
  if (t - lastWrite < SESSION_TRACE_WRITE_MIN_MS) return;
  lastSessionTraceWriteMsBySlug.set(s, t);
  appendSessionTraceLogPoint({
    t,
    runId: SERVER_RUN_ID,
    slug: s,
    seq: Array.isArray(mem.seq) && mem.seq.length ? mem.seq[mem.seq.length - 1] : mem.xMs.length,
    upBid: Number.isFinite(up) ? Number(up) : null,
    downBid: Number.isFinite(down) ? Number(down) : null,
    source: "session_trace_runlog",
  });
}

function recordAlgoInputTracePoint(slug: string, tMs: number, upBid: number | null, downBid: number | null) {
  const s = String(slug || "");
  if (!s) return;
  const normTraceBid = (v: any): number | null => {
    const x = toFiniteOrNull(v);
    return Number.isFinite(Number(x)) && Number(x) > 0 && Number(x) <= 1 ? Number(x) : null;
  };
  const up = normTraceBid(upBid);
  const down = normTraceBid(downBid);
  if (!Number.isFinite(up) && !Number.isFinite(down)) return;
  const t = Number(tMs);
  if (!Number.isFinite(t)) return;
  const now = nowMs();
  const pairLagMs =
    quotePairCache &&
    String(quotePairCache.upToken) === String(current?.upToken || "") &&
    String(quotePairCache.downToken) === String(current?.downToken || "")
      ? Math.max(0, now - Number(quotePairCache.tsMs || 0))
      : null;
  const streamLastMsgAgeMs =
    Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
      ? Math.max(0, now - Number(quoteStreamLastMsgMs))
      : null;
  const streamLastPriceMsgAgeMs =
    Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
      ? Math.max(0, now - Number(quoteStreamLastPriceMsgMs))
      : null;
  const mem = sessionAlgoInputTraceMem.get(s) || {
    xMs: [],
    up: [],
    down: [],
    seq: [],
    markers: [],
    sourceFile: "algo_input_feed",
    pairLagMs: [],
    streamLastMsgAgeMs: [],
    streamLastPriceMsgAgeMs: [],
    fallbackTriggered: [],
    streamReconnectCount: [],
    healTriggerCount: [],
    broadcastGapMsLatest: [],
    broadcastGapMsMax: [],
    gapViolationStreak: [],
    gapViolationCount: [],
  };
  const lastIdx = mem.xMs.length - 1;
  const lastT = lastIdx >= 0 ? Number(mem.xMs[lastIdx]) : NaN;
  const lastSampleT = Number(sessionAlgoInputLastSampleMsBySlug.get(s) || 0);
  const shouldMergeIntoLast =
    Number.isFinite(lastT) &&
    (
      t <= lastT ||
      (
        Number.isFinite(lastSampleT) &&
        lastSampleT > 0 &&
        (t - lastSampleT) < ALGO_INPUT_TRACE_SAMPLE_MIN_MS
      )
    );
  if (shouldMergeIntoLast) {
    mem.up[lastIdx] = Number.isFinite(up) ? Number(up) : NaN;
    mem.down[lastIdx] = Number.isFinite(down) ? Number(down) : NaN;
    if (Array.isArray(mem.pairLagMs)) mem.pairLagMs[lastIdx] = Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : NaN;
    if (Array.isArray(mem.streamLastMsgAgeMs)) mem.streamLastMsgAgeMs[lastIdx] = Number.isFinite(Number(streamLastMsgAgeMs)) ? Number(streamLastMsgAgeMs) : NaN;
    if (Array.isArray(mem.streamLastPriceMsgAgeMs)) mem.streamLastPriceMsgAgeMs[lastIdx] = Number.isFinite(Number(streamLastPriceMsgAgeMs)) ? Number(streamLastPriceMsgAgeMs) : NaN;
    if (Array.isArray(mem.fallbackTriggered)) mem.fallbackTriggered[lastIdx] = Number.isFinite(Number(quoteFallbackTriggerCount)) ? Number(quoteFallbackTriggerCount) : NaN;
    if (Array.isArray(mem.streamReconnectCount)) mem.streamReconnectCount[lastIdx] = Number.isFinite(Number(quoteStreamReconnectCount)) ? Number(quoteStreamReconnectCount) : NaN;
    if (Array.isArray(mem.healTriggerCount)) mem.healTriggerCount[lastIdx] = Number.isFinite(Number(watchdogHealCount)) ? Number(watchdogHealCount) : NaN;
    if (Array.isArray(mem.broadcastGapMsLatest)) mem.broadcastGapMsLatest[lastIdx] = Number.isFinite(Number(quoteBroadcastGapMsLatest)) ? Number(quoteBroadcastGapMsLatest) : NaN;
    if (Array.isArray(mem.broadcastGapMsMax)) mem.broadcastGapMsMax[lastIdx] = Number.isFinite(Number(quoteBroadcastGapMsMax)) ? Number(quoteBroadcastGapMsMax) : NaN;
    if (Array.isArray(mem.gapViolationStreak)) mem.gapViolationStreak[lastIdx] = Number.isFinite(Number(quoteBroadcastGapViolationStreak)) ? Number(quoteBroadcastGapViolationStreak) : NaN;
    if (Array.isArray(mem.gapViolationCount)) mem.gapViolationCount[lastIdx] = Number.isFinite(Number(quoteBroadcastGapViolationCount)) ? Number(quoteBroadcastGapViolationCount) : NaN;
    if (Array.isArray(mem.seq)) mem.seq[lastIdx] = lastIdx + 1;
    sessionAlgoInputTraceMem.set(s, mem);
    if (Number.isFinite(t) && t > 0) sessionAlgoInputLastSampleMsBySlug.set(s, t);
  } else {
    mem.xMs.push(t);
    mem.up.push(Number.isFinite(up) ? Number(up) : NaN);
    mem.down.push(Number.isFinite(down) ? Number(down) : NaN);
    if (Array.isArray(mem.seq)) mem.seq.push(mem.xMs.length);
    if (Array.isArray(mem.pairLagMs)) mem.pairLagMs.push(Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : NaN);
    if (Array.isArray(mem.streamLastMsgAgeMs)) mem.streamLastMsgAgeMs.push(Number.isFinite(Number(streamLastMsgAgeMs)) ? Number(streamLastMsgAgeMs) : NaN);
    if (Array.isArray(mem.streamLastPriceMsgAgeMs)) mem.streamLastPriceMsgAgeMs.push(Number.isFinite(Number(streamLastPriceMsgAgeMs)) ? Number(streamLastPriceMsgAgeMs) : NaN);
    if (Array.isArray(mem.fallbackTriggered)) mem.fallbackTriggered.push(Number.isFinite(Number(quoteFallbackTriggerCount)) ? Number(quoteFallbackTriggerCount) : NaN);
    if (Array.isArray(mem.streamReconnectCount)) mem.streamReconnectCount.push(Number.isFinite(Number(quoteStreamReconnectCount)) ? Number(quoteStreamReconnectCount) : NaN);
    if (Array.isArray(mem.healTriggerCount)) mem.healTriggerCount.push(Number.isFinite(Number(watchdogHealCount)) ? Number(watchdogHealCount) : NaN);
    if (Array.isArray(mem.broadcastGapMsLatest)) mem.broadcastGapMsLatest.push(Number.isFinite(Number(quoteBroadcastGapMsLatest)) ? Number(quoteBroadcastGapMsLatest) : NaN);
    if (Array.isArray(mem.broadcastGapMsMax)) mem.broadcastGapMsMax.push(Number.isFinite(Number(quoteBroadcastGapMsMax)) ? Number(quoteBroadcastGapMsMax) : NaN);
    if (Array.isArray(mem.gapViolationStreak)) mem.gapViolationStreak.push(Number.isFinite(Number(quoteBroadcastGapViolationStreak)) ? Number(quoteBroadcastGapViolationStreak) : NaN);
    if (Array.isArray(mem.gapViolationCount)) mem.gapViolationCount.push(Number.isFinite(Number(quoteBroadcastGapViolationCount)) ? Number(quoteBroadcastGapViolationCount) : NaN);
    if (mem.xMs.length > SESSION_ALGO_INPUT_MEM_MAX_POINTS) {
      mem.xMs.splice(0, mem.xMs.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      mem.up.splice(0, mem.up.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      mem.down.splice(0, mem.down.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.seq)) mem.seq.splice(0, mem.seq.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.pairLagMs)) mem.pairLagMs.splice(0, mem.pairLagMs.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.streamLastMsgAgeMs)) mem.streamLastMsgAgeMs.splice(0, mem.streamLastMsgAgeMs.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.streamLastPriceMsgAgeMs)) mem.streamLastPriceMsgAgeMs.splice(0, mem.streamLastPriceMsgAgeMs.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.fallbackTriggered)) mem.fallbackTriggered.splice(0, mem.fallbackTriggered.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.streamReconnectCount)) mem.streamReconnectCount.splice(0, mem.streamReconnectCount.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.healTriggerCount)) mem.healTriggerCount.splice(0, mem.healTriggerCount.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.broadcastGapMsLatest)) mem.broadcastGapMsLatest.splice(0, mem.broadcastGapMsLatest.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.broadcastGapMsMax)) mem.broadcastGapMsMax.splice(0, mem.broadcastGapMsMax.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.gapViolationStreak)) mem.gapViolationStreak.splice(0, mem.gapViolationStreak.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
      if (Array.isArray(mem.gapViolationCount)) mem.gapViolationCount.splice(0, mem.gapViolationCount.length - SESSION_ALGO_INPUT_MEM_MAX_POINTS);
    }
    sessionAlgoInputTraceMem.set(s, mem);
    sessionAlgoInputLastSampleMsBySlug.set(s, t);
  }

  const lastWrite = lastAlgoInputTraceWriteMsBySlug.get(s) || 0;
  if (t - lastWrite >= SESSION_TRACE_WRITE_MIN_MS) {
    lastAlgoInputTraceWriteMsBySlug.set(s, t);
    appendSessionTraceLogPoint({
      t,
      runId: SERVER_RUN_ID,
      slug: s,
      seq: Array.isArray(mem.seq) && mem.seq.length ? mem.seq[mem.seq.length - 1] : mem.xMs.length,
      upBid: Number.isFinite(up) ? Number(up) : null,
      downBid: Number.isFinite(down) ? Number(down) : null,
      pairLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null,
      streamLastMsgAgeMs: Number.isFinite(Number(streamLastMsgAgeMs)) ? Number(streamLastMsgAgeMs) : null,
      streamLastPriceMsgAgeMs: Number.isFinite(Number(streamLastPriceMsgAgeMs)) ? Number(streamLastPriceMsgAgeMs) : null,
      fallbackTriggered: Number.isFinite(Number(quoteFallbackTriggerCount)) ? Number(quoteFallbackTriggerCount) : null,
      streamReconnectCount: Number.isFinite(Number(quoteStreamReconnectCount)) ? Number(quoteStreamReconnectCount) : null,
      healTriggerCount: Number.isFinite(Number(watchdogHealCount)) ? Number(watchdogHealCount) : null,
      broadcastGapMsLatest: Number.isFinite(Number(quoteBroadcastGapMsLatest)) ? Number(quoteBroadcastGapMsLatest) : null,
      broadcastGapMsMax: Number.isFinite(Number(quoteBroadcastGapMsMax)) ? Number(quoteBroadcastGapMsMax) : null,
      gapViolationStreak: Number.isFinite(Number(quoteBroadcastGapViolationStreak)) ? Number(quoteBroadcastGapViolationStreak) : null,
      gapViolationCount: Number.isFinite(Number(quoteBroadcastGapViolationCount)) ? Number(quoteBroadcastGapViolationCount) : null,
      source: "algo_input_feed",
    });
  }

  recordSessionTracePoint(slug, tMs, upBid, downBid);
}

function listSessionTraceLogFiles(): string[] {
  ensureTradeLogDir();
  return fs
    .readdirSync(TRADE_LOG_DIR)
    .filter((f) => /^(?:05_)?session_trace_run_\d+\.jsonl$/.test(f))
    .map((f) => path.join(TRADE_LOG_DIR, f))
    .sort();
}

function readSessionTracesBySlug(
  sinceMs: number,
  runId?: number | null
): Map<string, {
  xMs: number[];
  up: number[];
  down: number[];
  seq?: number[];
  pairLagMs?: number[];
  streamLastMsgAgeMs?: number[];
  streamLastPriceMsgAgeMs?: number[];
  fallbackTriggered?: number[];
  streamReconnectCount?: number[];
  healTriggerCount?: number[];
  broadcastGapMsLatest?: number[];
  broadcastGapMsMax?: number[];
  gapViolationStreak?: number[];
  gapViolationCount?: number[];
  sourceFile: string;
}> {
  const out = new Map<string, {
    xMs: number[];
    up: number[];
    down: number[];
    seq?: number[];
    pairLagMs?: number[];
    streamLastMsgAgeMs?: number[];
    streamLastPriceMsgAgeMs?: number[];
    fallbackTriggered?: number[];
    streamReconnectCount?: number[];
    healTriggerCount?: number[];
    broadcastGapMsLatest?: number[];
    broadcastGapMsMax?: number[];
    gapViolationStreak?: number[];
    gapViolationCount?: number[];
    sourceFile: string;
  }>();
  const runIdFilter =
    runId == null
      ? null
      : (Number.isFinite(Number(runId)) && Number(runId) > 0 ? Number(runId) : null);
  const files = listSessionTraceLogFiles();
  for (const fp of files) {
    let raw = "";
    try {
      raw = fs.readFileSync(fp, "utf8");
    } catch {
      continue;
    }
    const lines = raw.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
    for (const ln of lines) {
      let row: any = null;
      try {
        row = JSON.parse(ln);
      } catch {
        continue;
      }
      const t = Number(row?.t);
      if (!Number.isFinite(t) || t < sinceMs) continue;
      if (runIdFilter != null && Number(row?.runId) !== Number(runIdFilter)) continue;
      const slug = String(row?.slug || "");
      if (!slug) continue;
      const up = toFiniteOrNull(row?.upBid);
      const down = toFiniteOrNull(row?.downBid);
      if (!Number.isFinite(up) && !Number.isFinite(down)) continue;
      const cur = out.get(slug) || {
        xMs: [],
        up: [],
        down: [],
        seq: [],
        pairLagMs: [],
        streamLastMsgAgeMs: [],
        streamLastPriceMsgAgeMs: [],
        fallbackTriggered: [],
        streamReconnectCount: [],
        healTriggerCount: [],
        broadcastGapMsLatest: [],
        broadcastGapMsMax: [],
        gapViolationStreak: [],
        gapViolationCount: [],
        sourceFile: String(row?.source || "session_trace_runlog"),
      };
      cur.xMs.push(t);
      cur.up.push(Number.isFinite(up) ? Number(up) : NaN);
      cur.down.push(Number.isFinite(down) ? Number(down) : NaN);
      cur.seq!.push(Number.isFinite(Number(row?.seq)) ? Number(row?.seq) : cur.xMs.length);
      cur.pairLagMs!.push(Number.isFinite(Number(row?.pairLagMs)) ? Number(row?.pairLagMs) : NaN);
      cur.streamLastMsgAgeMs!.push(
        Number.isFinite(Number(row?.streamLastMsgAgeMs)) ? Number(row?.streamLastMsgAgeMs) : NaN
      );
      cur.streamLastPriceMsgAgeMs!.push(
        Number.isFinite(Number(row?.streamLastPriceMsgAgeMs)) ? Number(row?.streamLastPriceMsgAgeMs) : NaN
      );
      cur.fallbackTriggered!.push(
        Number.isFinite(Number(row?.fallbackTriggered)) ? Number(row?.fallbackTriggered) : NaN
      );
      cur.streamReconnectCount!.push(
        Number.isFinite(Number(row?.streamReconnectCount)) ? Number(row?.streamReconnectCount) : NaN
      );
      cur.healTriggerCount!.push(
        Number.isFinite(Number(row?.healTriggerCount)) ? Number(row?.healTriggerCount) : NaN
      );
      cur.broadcastGapMsLatest!.push(
        Number.isFinite(Number(row?.broadcastGapMsLatest)) ? Number(row?.broadcastGapMsLatest) : NaN
      );
      cur.broadcastGapMsMax!.push(
        Number.isFinite(Number(row?.broadcastGapMsMax)) ? Number(row?.broadcastGapMsMax) : NaN
      );
      cur.gapViolationStreak!.push(
        Number.isFinite(Number(row?.gapViolationStreak)) ? Number(row?.gapViolationStreak) : NaN
      );
      cur.gapViolationCount!.push(
        Number.isFinite(Number(row?.gapViolationCount)) ? Number(row?.gapViolationCount) : NaN
      );
      out.set(slug, cur);
    }
  }

  const allowMemForRun = runIdFilter == null || Number(runIdFilter) === Number(SERVER_RUN_ID);
  const mergeMemTrace = (slug: string, mem: SessionTraceSeries) => {
    const cur = out.get(slug) || {
      xMs: [],
      up: [],
      down: [],
      seq: [],
      pairLagMs: [],
      streamLastMsgAgeMs: [],
      streamLastPriceMsgAgeMs: [],
      fallbackTriggered: [],
      streamReconnectCount: [],
      healTriggerCount: [],
      broadcastGapMsLatest: [],
      broadcastGapMsMax: [],
      gapViolationStreak: [],
      gapViolationCount: [],
      sourceFile: String(mem?.sourceFile || "session_trace_runlog"),
    };
    if (/algo_input_feed/i.test(String(mem?.sourceFile || ""))) {
      cur.sourceFile = String(mem.sourceFile);
    }
    for (let i = 0; i < mem.xMs.length; i++) {
      const t = Number(mem.xMs[i]);
      if (!Number.isFinite(t) || t < sinceMs) continue;
      cur.xMs.push(t);
      cur.up.push(Number.isFinite(mem.up[i]) ? Number(mem.up[i]) : NaN);
      cur.down.push(Number.isFinite(mem.down[i]) ? Number(mem.down[i]) : NaN);
      cur.seq!.push(Number.isFinite(Number(mem.seq?.[i])) ? Number(mem.seq?.[i]) : cur.xMs.length);
      cur.pairLagMs!.push(Number.isFinite(Number(mem.pairLagMs?.[i])) ? Number(mem.pairLagMs?.[i]) : NaN);
      cur.streamLastMsgAgeMs!.push(
        Number.isFinite(Number(mem.streamLastMsgAgeMs?.[i])) ? Number(mem.streamLastMsgAgeMs?.[i]) : NaN
      );
      cur.streamLastPriceMsgAgeMs!.push(
        Number.isFinite(Number(mem.streamLastPriceMsgAgeMs?.[i])) ? Number(mem.streamLastPriceMsgAgeMs?.[i]) : NaN
      );
      cur.fallbackTriggered!.push(
        Number.isFinite(Number(mem.fallbackTriggered?.[i])) ? Number(mem.fallbackTriggered?.[i]) : NaN
      );
      cur.streamReconnectCount!.push(
        Number.isFinite(Number(mem.streamReconnectCount?.[i])) ? Number(mem.streamReconnectCount?.[i]) : NaN
      );
      cur.healTriggerCount!.push(
        Number.isFinite(Number(mem.healTriggerCount?.[i])) ? Number(mem.healTriggerCount?.[i]) : NaN
      );
      cur.broadcastGapMsLatest!.push(
        Number.isFinite(Number(mem.broadcastGapMsLatest?.[i])) ? Number(mem.broadcastGapMsLatest?.[i]) : NaN
      );
      cur.broadcastGapMsMax!.push(
        Number.isFinite(Number(mem.broadcastGapMsMax?.[i])) ? Number(mem.broadcastGapMsMax?.[i]) : NaN
      );
      cur.gapViolationStreak!.push(
        Number.isFinite(Number(mem.gapViolationStreak?.[i])) ? Number(mem.gapViolationStreak?.[i]) : NaN
      );
      cur.gapViolationCount!.push(
        Number.isFinite(Number(mem.gapViolationCount?.[i])) ? Number(mem.gapViolationCount?.[i]) : NaN
      );
    }
    out.set(slug, cur);
  };
  for (const [slug, mem] of sessionAlgoInputTraceMem.entries()) {
    if (!allowMemForRun) continue;
    mergeMemTrace(slug, mem);
  }
  for (const [slug, mem] of sessionTraceMem.entries()) {
    if (!allowMemForRun) continue;
    mergeMemTrace(slug, mem);
  }

  for (const [slug, tr] of out.entries()) {
    const zipped = tr.xMs.map((t, i) => ({
      t,
      up: tr.up[i],
      down: tr.down[i],
      seq: tr.seq?.[i],
      pairLagMs: tr.pairLagMs?.[i],
      streamLastMsgAgeMs: tr.streamLastMsgAgeMs?.[i],
      streamLastPriceMsgAgeMs: tr.streamLastPriceMsgAgeMs?.[i],
      fallbackTriggered: tr.fallbackTriggered?.[i],
      streamReconnectCount: tr.streamReconnectCount?.[i],
      healTriggerCount: tr.healTriggerCount?.[i],
      broadcastGapMsLatest: tr.broadcastGapMsLatest?.[i],
      broadcastGapMsMax: tr.broadcastGapMsMax?.[i],
      gapViolationStreak: tr.gapViolationStreak?.[i],
      gapViolationCount: tr.gapViolationCount?.[i],
    })).filter((p) => Number.isFinite(p.t));
    zipped.sort((a, b) => a.t - b.t);
    const dedup: Array<{
      t: number;
      up: number;
      down: number;
      seq?: number;
      pairLagMs?: number;
      streamLastMsgAgeMs?: number;
      streamLastPriceMsgAgeMs?: number;
      fallbackTriggered?: number;
      streamReconnectCount?: number;
      healTriggerCount?: number;
      broadcastGapMsLatest?: number;
      broadcastGapMsMax?: number;
      gapViolationStreak?: number;
      gapViolationCount?: number;
    }> = [];
    for (const p of zipped) {
      const last = dedup[dedup.length - 1];
      if (last && Math.abs(last.t - p.t) < 1) {
        last.up = p.up;
        last.down = p.down;
        last.seq = p.seq;
        last.pairLagMs = p.pairLagMs;
        last.streamLastMsgAgeMs = p.streamLastMsgAgeMs;
        last.streamLastPriceMsgAgeMs = p.streamLastPriceMsgAgeMs;
        last.fallbackTriggered = p.fallbackTriggered;
        last.streamReconnectCount = p.streamReconnectCount;
        last.healTriggerCount = p.healTriggerCount;
        last.broadcastGapMsLatest = p.broadcastGapMsLatest;
        last.broadcastGapMsMax = p.broadcastGapMsMax;
        last.gapViolationStreak = p.gapViolationStreak;
        last.gapViolationCount = p.gapViolationCount;
        continue;
      }
      dedup.push(p);
    }
    out.set(slug, {
      xMs: dedup.map((p) => p.t),
      up: dedup.map((p) => p.up),
      down: dedup.map((p) => p.down),
      seq: dedup.map((p) => (Number.isFinite(Number(p.seq)) ? Number(p.seq) : NaN)),
      pairLagMs: dedup.map((p: any) => (Number.isFinite(Number(p.pairLagMs)) ? Number(p.pairLagMs) : NaN)),
      streamLastMsgAgeMs: dedup.map((p: any) => (
        Number.isFinite(Number(p.streamLastMsgAgeMs)) ? Number(p.streamLastMsgAgeMs) : NaN
      )),
      streamLastPriceMsgAgeMs: dedup.map((p: any) => (
        Number.isFinite(Number(p.streamLastPriceMsgAgeMs)) ? Number(p.streamLastPriceMsgAgeMs) : NaN
      )),
      fallbackTriggered: dedup.map((p: any) => (
        Number.isFinite(Number(p.fallbackTriggered)) ? Number(p.fallbackTriggered) : NaN
      )),
      streamReconnectCount: dedup.map((p: any) => (
        Number.isFinite(Number(p.streamReconnectCount)) ? Number(p.streamReconnectCount) : NaN
      )),
      healTriggerCount: dedup.map((p: any) => (
        Number.isFinite(Number(p.healTriggerCount)) ? Number(p.healTriggerCount) : NaN
      )),
      broadcastGapMsLatest: dedup.map((p: any) => (
        Number.isFinite(Number(p.broadcastGapMsLatest)) ? Number(p.broadcastGapMsLatest) : NaN
      )),
      broadcastGapMsMax: dedup.map((p: any) => (
        Number.isFinite(Number(p.broadcastGapMsMax)) ? Number(p.broadcastGapMsMax) : NaN
      )),
      gapViolationStreak: dedup.map((p: any) => (
        Number.isFinite(Number(p.gapViolationStreak)) ? Number(p.gapViolationStreak) : NaN
      )),
      gapViolationCount: dedup.map((p: any) => (
        Number.isFinite(Number(p.gapViolationCount)) ? Number(p.gapViolationCount) : NaN
      )),
      sourceFile: String((tr as any)?.sourceFile || "session_trace_runlog"),
    });
  }

  return out;
}

function getCurrentSessionTraceForSlug(
  slugRaw: any,
  instanceIdRaw?: any
): {
  slug: string;
  xMs: number[];
  up: number[];
  down: number[];
  seq?: number[];
  pairLagMs?: number[];
  streamLastMsgAgeMs?: number[];
  streamLastPriceMsgAgeMs?: number[];
  fallbackTriggered?: number[];
  streamReconnectCount?: number[];
  healTriggerCount?: number[];
  broadcastGapMsLatest?: number[];
  broadcastGapMsMax?: number[];
  gapViolationStreak?: number[];
  gapViolationCount?: number[];
  markers?: any[];
  source: string;
} | null {
  const slug = String(slugRaw || "").trim();
  const instanceId = String(instanceIdRaw || "").trim();
  const activeSlug = String((current as any)?.slug || "").trim();
  const activeStartMs = Number((current as any)?.startMs);
  const activeEndMs = Number((current as any)?.endMs);
  const activeOpen = !!activeSlug && Number.isFinite(activeEndMs) && Date.now() < activeEndMs;
  if (!slug || !activeOpen || slug !== activeSlug) return null;
  // For the active session, prefer a merged view of persisted run trace plus
  // in-memory trace. Watchdog heals can restart the child mid-session and wipe
  // some in-memory points, so using the persisted run trace here preserves raw
  // fidelity across those recoveries.
  const traceSinceMs = Number.isFinite(activeStartMs)
    ? Math.max(0, Number(activeStartMs) - 60_000)
    : Math.max(0, Date.now() - 15 * 60_000);
  const persisted =
    readSessionTracesBySlug(traceSinceMs, SERVER_RUN_ID).get(slug)
    || null;
  const mem = choosePreferredSessionTrace(
    persisted,
    sessionAlgoInputTraceMem.get(slug) || null,
    sessionTraceMem.get(slug) || null
  );
  if (!mem) return null;
  const xMs: number[] = [];
  const up: number[] = [];
  const down: number[] = [];
  const seq: number[] = [];
  const pairLagMs: number[] = [];
  const streamLastMsgAgeMs: number[] = [];
  const streamLastPriceMsgAgeMs: number[] = [];
  const fallbackTriggered: number[] = [];
  const streamReconnectCount: number[] = [];
  const healTriggerCount: number[] = [];
  const broadcastGapMsLatest: number[] = [];
  const broadcastGapMsMax: number[] = [];
  const gapViolationStreak: number[] = [];
  const gapViolationCount: number[] = [];
  for (let i = 0; i < mem.xMs.length; i++) {
    const t = Number(mem.xMs[i]);
    if (!Number.isFinite(t)) continue;
    xMs.push(t);
    up.push(Number.isFinite(Number(mem.up[i])) ? Number(mem.up[i]) : NaN);
    down.push(Number.isFinite(Number(mem.down[i])) ? Number(mem.down[i]) : NaN);
    seq.push(Number.isFinite(Number(mem.seq?.[i])) ? Number(mem.seq?.[i]) : i + 1);
    pairLagMs.push(Number.isFinite(Number(mem.pairLagMs?.[i])) ? Number(mem.pairLagMs?.[i]) : NaN);
    streamLastMsgAgeMs.push(Number.isFinite(Number(mem.streamLastMsgAgeMs?.[i])) ? Number(mem.streamLastMsgAgeMs?.[i]) : NaN);
    streamLastPriceMsgAgeMs.push(Number.isFinite(Number(mem.streamLastPriceMsgAgeMs?.[i])) ? Number(mem.streamLastPriceMsgAgeMs?.[i]) : NaN);
    fallbackTriggered.push(Number.isFinite(Number(mem.fallbackTriggered?.[i])) ? Number(mem.fallbackTriggered?.[i]) : NaN);
    streamReconnectCount.push(Number.isFinite(Number(mem.streamReconnectCount?.[i])) ? Number(mem.streamReconnectCount?.[i]) : NaN);
    healTriggerCount.push(Number.isFinite(Number(mem.healTriggerCount?.[i])) ? Number(mem.healTriggerCount?.[i]) : NaN);
    broadcastGapMsLatest.push(Number.isFinite(Number(mem.broadcastGapMsLatest?.[i])) ? Number(mem.broadcastGapMsLatest?.[i]) : NaN);
    broadcastGapMsMax.push(Number.isFinite(Number(mem.broadcastGapMsMax?.[i])) ? Number(mem.broadcastGapMsMax?.[i]) : NaN);
    gapViolationStreak.push(Number.isFinite(Number(mem.gapViolationStreak?.[i])) ? Number(mem.gapViolationStreak?.[i]) : NaN);
    gapViolationCount.push(Number.isFinite(Number(mem.gapViolationCount?.[i])) ? Number(mem.gapViolationCount?.[i]) : NaN);
  }
  if (xMs.length < 2) return null;
  let markers = Array.isArray((mem as any)?.markers)
    ? (mem as any).markers.map((row: any) => cloneLiveTradeMarker(row)).filter(Boolean)
    : [];
  if ((!Array.isArray(markers) || !markers.length) && instanceId && slug) {
    markers = getLiveTradeMarkersForInstance(instanceId, slug, 0);
  }
  if ((!Array.isArray(markers) || !markers.length) && instanceId && slug) {
    const inst = botInstances.get(instanceId) || null;
    if (inst) {
      markers = buildLiveMarkersForInstanceSession(inst, slug);
    }
  }
  return {
    slug,
    xMs,
    up,
    down,
    seq,
    pairLagMs,
    streamLastMsgAgeMs,
    streamLastPriceMsgAgeMs,
    fallbackTriggered,
    streamReconnectCount,
    healTriggerCount,
    broadcastGapMsLatest,
    broadcastGapMsMax,
    gapViolationStreak,
    gapViolationCount,
    markers,
    source: String((mem as any).sourceFile || "session_trace_runlog"),
  };
}

function getCurrentSessionDisplayTraceForSlug(
  slugRaw: any
): {
  slug: string;
  xMs: number[];
  up: number[];
  down: number[];
  source: string;
} | null {
  const slug = String(slugRaw || "").trim();
  const activeSlug = String((current as any)?.slug || "").trim();
  const activeEndMs = Number((current as any)?.endMs);
  const activeStartMs = Number((current as any)?.startMs);
  const activeOpen = !!activeSlug && Number.isFinite(activeEndMs) && Date.now() < activeEndMs;
  if (!slug || !activeOpen || slug !== activeSlug) return null;
  const traceSinceMs = Number.isFinite(activeStartMs)
    ? Math.max(0, Number(activeStartMs) - 60_000)
    : Math.max(0, Date.now() - 15 * 60_000);
  const persisted =
    readSessionTracesBySlug(traceSinceMs, SERVER_RUN_ID).get(slug)
    || null;
  const algoMem = choosePreferredSessionTrace(
    persisted,
    sessionAlgoInputTraceMem.get(slug) || null
  );
  if (algoMem && Array.isArray(algoMem.xMs) && algoMem.xMs.length >= 2) {
    const built = buildDisplayContinuousTrace({
      xMs: algoMem.xMs,
      up: algoMem.up,
      down: algoMem.down,
      source: String((algoMem as any)?.sourceFile || "algo_input_feed"),
    });
    if (built) return { slug, ...built };
  }
  const mem = sessionTraceMem.get(slug) || null;
  if (!mem) return null;
  const xMs: number[] = [];
  const up: number[] = [];
  const down: number[] = [];
  for (let i = 0; i < mem.xMs.length; i++) {
    const t = Number(mem.xMs[i]);
    if (!Number.isFinite(t)) continue;
    xMs.push(t);
    up.push(Number.isFinite(Number(mem.up[i])) ? Number(mem.up[i]) : NaN);
    down.push(Number.isFinite(Number(mem.down[i])) ? Number(mem.down[i]) : NaN);
  }
  if (xMs.length < 2) return null;
  return {
    slug,
    xMs,
    up,
    down,
    source: String((mem as any)?.sourceFile || "session_trace_runlog"),
  };
}

function buildDisplayContinuousTrace(traceLike: any): { xMs: number[]; up: number[]; down: number[]; source: string } | null {
  const trace = traceLike && typeof traceLike === "object" ? traceLike : null;
  const xMsRaw = Array.isArray(trace?.xMs) ? trace.xMs : [];
  const upRaw = Array.isArray(trace?.up) ? trace.up : [];
  const downRaw = Array.isArray(trace?.down) ? trace.down : [];
  const rows: Array<{ xMs: number; up: number | null; down: number | null }> = [];
  for (let i = 0; i < xMsRaw.length; i++) {
    const xMs = Number(xMsRaw[i]);
    const up = Number(upRaw[i]);
    const down = Number(downRaw[i]);
    if (!Number.isFinite(xMs)) continue;
    rows.push({
      xMs,
      up: Number.isFinite(up) ? up : null,
      down: Number.isFinite(down) ? down : null,
    });
  }
  if (rows.length < 2) return null;
  rows.sort((a, b) => Number(a.xMs) - Number(b.xMs));
  const firstMs = Number(rows[0]?.xMs || 0);
  const lastMs = Number(rows[rows.length - 1]?.xMs || 0);
  if (!(Number.isFinite(firstMs) && Number.isFinite(lastMs) && lastMs > firstMs)) return null;
  const bucketMs = 100;
  const maxPoints = 3600;
  const outX: number[] = [];
  const outUp: number[] = [];
  const outDown: number[] = [];
  const pushPoint = (xMs: number, up: number | null, down: number | null) => {
    outX.push(Number(xMs));
    outUp.push(Number.isFinite(Number(up)) ? Number(up) : NaN);
    outDown.push(Number.isFinite(Number(down)) ? Number(down) : NaN);
  };
  let prev = rows[0];
  pushPoint(prev.xMs, prev.up, prev.down);
  for (let i = 1; i < rows.length; i++) {
    const next = rows[i];
    if (!next) continue;
    if (Number(next.xMs) <= Number(prev.xMs)) {
      prev = next;
      continue;
    }
    for (let fillMs = Number(prev.xMs) + bucketMs; fillMs < Number(next.xMs); fillMs += bucketMs) {
      pushPoint(fillMs, prev.up, prev.down);
      if (outX.length >= maxPoints) break;
    }
    if (outX.length >= maxPoints) break;
    pushPoint(next.xMs, next.up, next.down);
    prev = next;
  }
  if (outX.length > maxPoints) {
    outX.splice(0, outX.length - maxPoints);
    outUp.splice(0, outUp.length - maxPoints);
    outDown.splice(0, outDown.length - maxPoints);
  }
  return {
    xMs: outX,
    up: outUp,
    down: outDown,
    source: `${String(trace?.source || "session_trace_runlog")}:display_continuous`,
  };
}

function compactFocusedDisplayTrace(traceRaw: any, maxPoints = 600): { xMs: number[]; up: number[]; down: number[]; source: string } | null {
  const compact = compactSessionTraceForHistory(traceRaw, maxPoints);
  if (!compact) return null;
  return {
    xMs: Array.isArray(compact?.xMs) ? compact.xMs : [],
    up: Array.isArray(compact?.up) ? compact.up : [],
    down: Array.isArray(compact?.down) ? compact.down : [],
    source: String(compact?.source || traceRaw?.source || "focused_live_session:compact"),
  };
}

function focusedLiveRuntimeLagMsNow(): number | null {
  const botTick = botTickGapStatsNow();
  return Number.isFinite(Number(botTick?.activeMaxRuntimeAgeMs))
    ? Number(botTick.activeMaxRuntimeAgeMs)
    : (Number.isFinite(Number(botTick?.latestGapMs)) ? Number(botTick.latestGapMs) : null);
}

function traceGapStatsMs(traceLike: any): { min: number | null; max: number | null; avg: number | null } {
  const xs = Array.isArray(traceLike?.xMs) ? traceLike.xMs.map((v: any) => Number(v)) : [];
  const deltas: number[] = [];
  for (let i = 1; i < xs.length; i++) {
    const prev = Number(xs[i - 1]);
    const cur = Number(xs[i]);
    if (Number.isFinite(prev) && Number.isFinite(cur) && cur >= prev) deltas.push(cur - prev);
  }
  if (!deltas.length) return { min: null, max: null, avg: null };
  const sum = deltas.reduce((acc, v) => acc + v, 0);
  return {
    min: Math.min(...deltas),
    max: Math.max(...deltas),
    avg: sum / deltas.length,
  };
}

function buildFocusedLiveSessionInvariants(bot: any, runtime: any, rawTrace: any, displayTrace: any, markersLike: any[]): any {
  const markers = Array.isArray(markersLike) ? markersLike : [];
  const markerTypes = new Set(
    markers
      .map((row) => String(row?.markerType || "").trim().toLowerCase())
      .filter(Boolean)
  );
  const runtimeTickMs = Number(runtime?.lastTickMs);
  const rawXs = Array.isArray(rawTrace?.xMs) ? rawTrace.xMs : [];
  const displayXs = Array.isArray(displayTrace?.xMs) ? displayTrace.xMs : [];
  const rawGapStats = traceGapStatsMs(rawTrace);
  const displayGapStats = traceGapStatsMs(displayTrace);
  const rawLastMs = rawXs.length ? Number(rawXs[rawXs.length - 1]) : NaN;
  const displayLastMs = displayXs.length ? Number(displayXs[displayXs.length - 1]) : NaN;
  const entered = !!runtime?.entered;
  const side = String(runtime?.side || "").trim().toUpperCase();
  const hasEntryMarker = markerTypes.has("entry_filled");
  const quoteMeta = runtime && typeof runtime === "object" ? (runtime as any).__lastQuoteMeta || null : null;
  const quoteFeed = runtime?.quoteFeed && typeof runtime.quoteFeed === "object" ? runtime.quoteFeed : null;
  const pairSource = String(quoteFeed?.pairSource || "").trim() || null;
  const streamEnabled = quoteFeed?.streamEnabled === true ? true : QUOTE_STREAM_ENABLED;
  const streamConnected = quoteFeed?.streamConnected === true ? true : quoteStreamConnected;
  const pairLagMs = Number.isFinite(Number(quoteFeed?.pairLagMs))
    ? Number(quoteFeed?.pairLagMs)
    : (Number.isFinite(Number(quoteMeta?.pairAgeMs)) ? Number(quoteMeta?.pairAgeMs) : NaN);
  const pairObservedAgeMs = Number.isFinite(Number(quoteFeed?.pairObservedAgeMs))
    ? Number(quoteFeed?.pairObservedAgeMs)
    : NaN;
  const streamLastMsgAgeMs = Number.isFinite(Number(quoteFeed?.streamLastMsgAgeMs))
    ? Number(quoteFeed?.streamLastMsgAgeMs)
    : (Number.isFinite(Number(quoteStreamLastMsgMs)) ? Math.max(0, Date.now() - Number(quoteStreamLastMsgMs)) : NaN);
  const streamLastPriceMsgAgeMs = Number.isFinite(Number(quoteFeed?.streamLastPriceMsgAgeMs))
    ? Number(quoteFeed?.streamLastPriceMsgAgeMs)
    : (Number.isFinite(Number(quoteStreamLastPriceMsgMs)) ? Math.max(0, Date.now() - Number(quoteStreamLastPriceMsgMs)) : NaN);
  const websocketHealthy =
    streamEnabled &&
    streamConnected &&
    pairSource === "ws_direct" &&
    (!Number.isFinite(pairLagMs) || pairLagMs <= 100) &&
    (!Number.isFinite(streamLastPriceMsgAgeMs) || streamLastPriceMsgAgeMs <= 100);
  const staleMs =
    Number.isFinite(runtimeTickMs) && Number.isFinite(rawLastMs)
      ? Math.max(0, Number(runtimeTickMs) - Number(rawLastMs))
      : NaN;
  return {
    instanceId: String(bot?.instanceId || "").trim() || null,
    slug: String(rawTrace?.slug || runtime?.marketSlug || bot?.marketSlug || "").trim() || null,
    entered,
    side: side === "UP" || side === "DOWN" ? side : null,
    rawTracePointCount: rawXs.length,
    displayTracePointCount: displayXs.length,
    rawTraceGapMinMs: Number.isFinite(Number(rawGapStats.min)) ? Number(rawGapStats.min) : null,
    rawTraceGapMaxMs: Number.isFinite(Number(rawGapStats.max)) ? Number(rawGapStats.max) : null,
    rawTraceGapAvgMs: Number.isFinite(Number(rawGapStats.avg)) ? Number(rawGapStats.avg) : null,
    displayTraceGapMinMs: Number.isFinite(Number(displayGapStats.min)) ? Number(displayGapStats.min) : null,
    displayTraceGapMaxMs: Number.isFinite(Number(displayGapStats.max)) ? Number(displayGapStats.max) : null,
    displayTraceGapAvgMs: Number.isFinite(Number(displayGapStats.avg)) ? Number(displayGapStats.avg) : null,
    markerCount: markers.length,
    hasEntryMarker,
    missingEntryMarkerWhileEntered: entered && !hasEntryMarker,
    traceStaleVsRuntimeTickMs: Number.isFinite(staleMs) ? Number(staleMs) : null,
    runtimeLagMs: focusedLiveRuntimeLagMsNow(),
    continuityHealthy:
      displayXs.length >= rawXs.length &&
      (!Number.isFinite(staleMs) || Number(staleMs) <= 2500) &&
      (!entered || hasEntryMarker),
    quoteFeedHealthy: websocketHealthy,
    quoteFeed: {
      pairSource: pairSource || (String(quoteMeta?.source || "").trim() || null),
      streamEnabled,
      streamConnected,
      pairLagMs: Number.isFinite(pairLagMs) ? Number(pairLagMs) : null,
      pairObservedAgeMs: Number.isFinite(pairObservedAgeMs) ? Number(pairObservedAgeMs) : null,
      streamLastMsgAgeMs: Number.isFinite(streamLastMsgAgeMs) ? Number(streamLastMsgAgeMs) : null,
      streamLastPriceMsgAgeMs: Number.isFinite(streamLastPriceMsgAgeMs) ? Number(streamLastPriceMsgAgeMs) : null,
      degradedReason:
        !streamEnabled ? "stream_disabled"
        : !streamConnected ? "stream_disconnected"
        : pairSource !== "ws_direct" ? "non_websocket_source"
        : (Number.isFinite(pairLagMs) && pairLagMs > 100) ? "pair_lag_too_high"
        : (Number.isFinite(streamLastPriceMsgAgeMs) && streamLastPriceMsgAgeMs > 100) ? "stream_price_age_too_high"
        : null,
    },
    sources: {
      rawTrace: String(rawTrace?.source || "") || null,
      displayTrace: String(displayTrace?.source || "") || null,
    },
    rawLastMs: Number.isFinite(rawLastMs) ? Number(rawLastMs) : null,
    displayLastMs: Number.isFinite(displayLastMs) ? Number(displayLastMs) : null,
    runtimeTickMs: Number.isFinite(runtimeTickMs) ? Number(runtimeTickMs) : null,
  };
}

function listTradeLogFiles(): string[] {
  ensureTradeLogDir();
  return fs
    .readdirSync(TRADE_LOG_DIR)
    .filter((f) => /^(?:03_)?\d{4}-\d{2}-\d{2}_trades\.jsonl$/.test(f))
    .map((f) => path.join(TRADE_LOG_DIR, f))
    .sort();
}

type RunPathName = "MOMENTUM_FIRST" | "HC_SOLO" | "HC_SECOND_SAME" | "HC_SECOND_OPPOSITE";
type RunPathTrade = {
  slug: string;
  side: OutcomeSide | null;
  entryPx: number | null;
  exitPx: number | null;
  pnlUsd: number | null;
  cumulativeBalanceUsd: number | null;
  entryIso: string | null;
  exitIso: string | null;
};
type RunPathSummary = {
  runId: number;
  tradeCount: number;
  totalPnlUsd: number;
  byPath: Record<RunPathName, { count: number; totalPnlUsd: number; trades: RunPathTrade[] }>;
};

function summarizeRunPathsFromTradeRows(rows: any[], runId: number): RunPathSummary {
  type Sess = {
    slug: string;
    base: {
      side: OutcomeSide | null;
      entryPx: number | null;
      exitPx: number | null;
      pnlUsd: number | null;
      balanceUsd: number | null;
      entryTs: number | null;
      exitTs: number | null;
      entryIso: string | null;
      exitIso: string | null;
    };
    hc: {
      side: OutcomeSide | null;
      entryPx: number | null;
      exitPx: number | null;
      pnlUsd: number | null;
      balanceUsd: number | null;
      entryTs: number | null;
      exitTs: number | null;
      entryIso: string | null;
      exitIso: string | null;
    };
  };

  const bySession = new Map<string, Sess>();
  for (const r of rows) {
    const rr = Number(r?.runId);
    if (!Number.isFinite(rr) || rr !== runId) continue;
    const slug = String(r?.market?.slug || r?.st?.marketSlug || "");
    if (!slug) continue;
    const exec = r?.execution;
    const mode = String(exec?.mode || "").toUpperCase();
    const phase = String(exec?.phase || "").toLowerCase();
    if (mode !== "BASE" && mode !== "NO_CROSS_WINNER") continue;
    if (phase !== "entry_fill" && phase !== "exit_fill" && phase !== "stop_fill") continue;

    const s =
      bySession.get(slug) ||
      {
        slug,
        base: { side: null, entryPx: null, exitPx: null, pnlUsd: null, balanceUsd: null, entryTs: null, exitTs: null, entryIso: null, exitIso: null },
        hc: { side: null, entryPx: null, exitPx: null, pnlUsd: null, balanceUsd: null, entryTs: null, exitTs: null, entryIso: null, exitIso: null },
      };
    const lane = mode === "BASE" ? s.base : s.hc;
    const t = Number(r?.t);
    const iso = String(r?.iso || "");
    const sideRaw = String(exec?.side || r?.st?.side || "").toUpperCase();
    const side = sideRaw === "UP" || sideRaw === "DOWN" ? (sideRaw as OutcomeSide) : null;

    if (phase === "entry_fill") {
      lane.entryTs = Number.isFinite(t) ? t : lane.entryTs;
      lane.entryIso = iso || lane.entryIso;
      lane.entryPx = toFiniteOrNull(exec?.actualPx ?? exec?.actualFillPx ?? r?.st?.entryPx);
      lane.side = side ?? lane.side;
    } else {
      lane.exitTs = Number.isFinite(t) ? t : lane.exitTs;
      lane.exitIso = iso || lane.exitIso;
      lane.exitPx = toFiniteOrNull(exec?.actualPx ?? exec?.actualFillPx ?? r?.st?.exitPx);
      lane.pnlUsd = toFiniteOrNull(r?.st?.pnlUsd);
      lane.balanceUsd = toFiniteOrNull(r?.st?.balanceUsd);
      lane.side = side ?? lane.side;
    }
    bySession.set(slug, s);
  }

  const emptyBucket = () => ({ count: 0, totalPnlUsd: 0, trades: [] as RunPathTrade[] });
  const byPath: Record<RunPathName, { count: number; totalPnlUsd: number; trades: RunPathTrade[] }> = {
    MOMENTUM_FIRST: emptyBucket(),
    HC_SOLO: emptyBucket(),
    HC_SECOND_SAME: emptyBucket(),
    HC_SECOND_OPPOSITE: emptyBucket(),
  };

  const pushTrade = (path: RunPathName, t: RunPathTrade) => {
    byPath[path].count += 1;
    if (Number.isFinite(Number(t.pnlUsd))) byPath[path].totalPnlUsd += Number(t.pnlUsd);
    byPath[path].trades.push(t);
  };

  for (const s of bySession.values()) {
    const hasBase = Number.isFinite(Number(s.base.entryTs)) && Number.isFinite(Number(s.base.exitTs));
    const hasHc = Number.isFinite(Number(s.hc.entryTs)) && Number.isFinite(Number(s.hc.exitTs));

    if (hasBase) {
      pushTrade("MOMENTUM_FIRST", {
        slug: s.slug,
        side: s.base.side,
        entryPx: s.base.entryPx,
        exitPx: s.base.exitPx,
        pnlUsd: s.base.pnlUsd,
        cumulativeBalanceUsd: s.base.balanceUsd,
        entryIso: s.base.entryIso,
        exitIso: s.base.exitIso,
      });
    }

    if (!hasHc) continue;
    if (!hasBase) {
      pushTrade("HC_SOLO", {
        slug: s.slug,
        side: s.hc.side,
        entryPx: s.hc.entryPx,
        exitPx: s.hc.exitPx,
        pnlUsd: s.hc.pnlUsd,
        cumulativeBalanceUsd: s.hc.balanceUsd,
        entryIso: s.hc.entryIso,
        exitIso: s.hc.exitIso,
      });
      continue;
    }

    const same = s.hc.side != null && s.base.side != null && s.hc.side === s.base.side;
    pushTrade(same ? "HC_SECOND_SAME" : "HC_SECOND_OPPOSITE", {
      slug: s.slug,
      side: s.hc.side,
      entryPx: s.hc.entryPx,
      exitPx: s.hc.exitPx,
      pnlUsd: s.hc.pnlUsd,
      cumulativeBalanceUsd: s.hc.balanceUsd,
      entryIso: s.hc.entryIso,
      exitIso: s.hc.exitIso,
    });
  }

  const tradeCount =
    byPath.MOMENTUM_FIRST.count + byPath.HC_SOLO.count + byPath.HC_SECOND_SAME.count + byPath.HC_SECOND_OPPOSITE.count;
  const totalPnlUsd =
    byPath.MOMENTUM_FIRST.totalPnlUsd +
    byPath.HC_SOLO.totalPnlUsd +
    byPath.HC_SECOND_SAME.totalPnlUsd +
    byPath.HC_SECOND_OPPOSITE.totalPnlUsd;

  // Keep trades chronologically ordered inside each path.
  for (const k of Object.keys(byPath) as RunPathName[]) {
    byPath[k].trades.sort((a, b) => Number(new Date(a.entryIso || 0)) - Number(new Date(b.entryIso || 0)));
    byPath[k].totalPnlUsd = round4(byPath[k].totalPnlUsd);
  }

  return {
    runId,
    tradeCount,
    totalPnlUsd: round4(totalPnlUsd),
    byPath,
  };
}

function readJsonlFiles(files: string[]): any[] {
  const rows: any[] = [];
  for (const fp of files) {
    let raw = "";
    try {
      raw = fs.readFileSync(fp, "utf8");
    } catch {
      continue;
    }
    const lines = raw.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
    for (const ln of lines) {
      try {
        rows.push(JSON.parse(ln));
      } catch {}
    }
  }
  return rows;
}

function buildEtSessionLabel(tsSec: number): string {
  const d = new Date(tsSec * 1000);
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  }).formatToParts(d);
  const hour = parts.find((p) => p.type === "hour")?.value || "12";
  const minute = parts.find((p) => p.type === "minute")?.value || "00";
  const dayPeriod = (parts.find((p) => p.type === "dayPeriod")?.value || "AM").toUpperCase();
  return `${hour}_${minute}${dayPeriod}`;
}

function resolveSessionCsvPathFromSlug(slug: string): string | null {
  const m = String(slug || "").match(/-(\d{10})$/);
  if (!m) return null;
  const startSec = Number(m[1]);
  if (!Number.isFinite(startSec)) return null;
  const endSec = startSec + 300;

  const d = new Date(startSec * 1000);
  const month = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    month: "long",
  }).format(d);
  const day = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    day: "numeric",
  }).format(d);
  const fromLabel = buildEtSessionLabel(startSec);
  const toLabel = buildEtSessionLabel(endSec);
  const fileName = `Bitcoin Up or Down - ${month} ${day}, ${fromLabel}-${toLabel} ET.csv`;

  const envDir = String(process.env.BTC_5M_DATA_DIR || "").trim();
  const candidates = [
    envDir ? path.resolve(envDir, fileName) : null,
    path.resolve("/Users/aliathar/btc_5m_data", fileName),
    path.resolve("/Users/aliathar/polymarket-bot/src/btc_5m_data", fileName),
    path.resolve("/home/ec2-user/polymarket-bot/src/btc_5m_data", fileName),
    path.resolve(process.cwd(), "src", "btc_5m_data", fileName),
    path.resolve(__dirname, "btc_5m_data", fileName),
    path.resolve(process.cwd(), "btc_5m_data", fileName),
    path.resolve(__dirname, "../btc_5m_data", fileName),
  ].filter((p): p is string => !!p);
  for (const p of candidates) {
    if (fs.existsSync(p)) return p;
  }
  return null;
}

function traceRecordedHealthCount(traceLike: any): number {
  if (!traceLike || typeof traceLike !== "object") return 0;
  const series = [
    Array.isArray(traceLike?.pairLagMs) ? traceLike.pairLagMs : [],
    Array.isArray(traceLike?.streamLastMsgAgeMs) ? traceLike.streamLastMsgAgeMs : [],
    Array.isArray(traceLike?.streamLastPriceMsgAgeMs) ? traceLike.streamLastPriceMsgAgeMs : [],
  ];
  let count = 0;
  for (const arr of series) {
    for (const v of arr) {
      if (Number.isFinite(Number(v))) count += 1;
    }
  }
  return count;
}

function choosePreferredSessionTrace(...candidates: any[]): any | null {
  const valid = candidates.filter((tr) => !!tr && Array.isArray(tr?.xMs) && tr.xMs.length > 0);
  if (!valid.length) return null;
  const sourceScore = (srcRaw: any) => {
    const src = String(srcRaw || "").toLowerCase();
    if (/canonical_session|session_audit_trace_replacement|canonical_session_high_fidelity|canonical_session_low_fidelity/.test(src)) return 5;
    if (/algo_input_feed/.test(src)) return 4;
    if (/btc_5m_data/.test(src) || /bitcoin up or down/.test(src) || /\.csv$/.test(src)) return 3;
    if (/session_trace_runlog/.test(src)) return 2;
    if (/run_index_trace/.test(src)) return 1;
    return 0;
  };
  valid.sort((a, b) => {
    const bySource = sourceScore((b as any)?.source || (b as any)?.sourceFile) - sourceScore((a as any)?.source || (a as any)?.sourceFile);
    if (bySource) return bySource;
    const byHealth = traceRecordedHealthCount(b) - traceRecordedHealthCount(a);
    if (byHealth) return byHealth;
    return (Array.isArray((b as any)?.xMs) ? (b as any).xMs.length : 0) - (Array.isArray((a as any)?.xMs) ? (a as any).xMs.length : 0);
  });
  return valid[0] || null;
}

function choosePreferredClosedSessionTrace(slugLike: any, closedLike: any, ...candidates: any[]): any | null {
  const slug = String(slugLike || "").trim();
  const closed = closedLike === true;
  if (!closed || !slug) return choosePreferredSessionTrace(...candidates);
  const canonical = chooseCanonicalRunAuditTrace(slug);
  return choosePreferredSessionTrace(canonical?.trace || null, ...candidates);
}

function sessionTracePointCount(traceLike: any): number {
  return Array.isArray(traceLike?.xMs) ? traceLike.xMs.length : 0;
}

function readSessionTraceFromCsv(slug: string) {
  const filePath = resolveSessionCsvPathFromSlug(slug);
  if (!filePath) return null;
  const m = String(slug || "").match(/-(\d{10})$/);
  const startSec = m ? Number(m[1]) : NaN;
  if (!Number.isFinite(startSec)) return null;
  const csvCache = ((readSessionTraceFromCsv as any).__cache ||= new Map<string, {
    mtimeMs: number;
    size: number;
    value: any | null;
  }>());

  try {
    let statSig: { mtimeMs: number; size: number } | null = null;
    try {
      const st = fs.statSync(filePath);
      statSig = {
        mtimeMs: Number(st.mtimeMs || 0),
        size: Number(st.size || 0),
      };
      const cached = csvCache.get(filePath);
      if (
        cached &&
        Number(cached.mtimeMs) === Number(statSig.mtimeMs) &&
        Number(cached.size) === Number(statSig.size)
      ) {
        return cached.value || null;
      }
    } catch {}
    const raw = fs.readFileSync(filePath, "utf8");
    const lines = raw.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
    if (lines.length < 2) return null;
    const xMs: number[] = [];
    const up: number[] = [];
    const down: number[] = [];
    const pairLagMs: number[] = [];
    const streamLastMsgAgeMs: number[] = [];
    const streamLastPriceMsgAgeMs: number[] = [];
    const fallbackTriggered: number[] = [];
    const streamReconnectCount: number[] = [];
    const healTriggerCount: number[] = [];
    const broadcastGapMsLatest: number[] = [];
    const broadcastGapMsMax: number[] = [];
    const gapViolationStreak: number[] = [];
    const gapViolationCount: number[] = [];
    const parsePx = (raw: any) => {
      const s = String(raw ?? "").trim();
      if (!s.length) return NaN;
      const n = Number(s);
      return Number.isFinite(n) ? n : NaN;
    };
    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(",");
      if (cols.length < 3) continue;
      const sec = Number(cols[0]);
      const upPx = parsePx(cols[1]);
      const downPx = parsePx(cols[2]);
      const pairLag = parsePx(cols[3]);
      const streamAge = parsePx(cols[4]);
      const priceStreamAge = parsePx(cols[5]);
      const fallbackCount = parsePx(cols[6]);
      const reconnectCount = parsePx(cols[7]);
      const healCount = parsePx(cols[8]);
      const gapLatest = parsePx(cols[9]);
      const gapMax = parsePx(cols[10]);
      const violationStreak = parsePx(cols[11]);
      const violationCount = parsePx(cols[12]);
      if (!Number.isFinite(sec) || (!Number.isFinite(upPx) && !Number.isFinite(downPx))) continue;
      xMs.push(Math.round((startSec + sec) * 1000));
      up.push(Number.isFinite(upPx) ? upPx : NaN);
      down.push(Number.isFinite(downPx) ? downPx : NaN);
      pairLagMs.push(Number.isFinite(pairLag) ? pairLag : NaN);
      streamLastMsgAgeMs.push(Number.isFinite(streamAge) ? streamAge : NaN);
      streamLastPriceMsgAgeMs.push(Number.isFinite(priceStreamAge) ? priceStreamAge : NaN);
      fallbackTriggered.push(Number.isFinite(fallbackCount) ? fallbackCount : NaN);
      streamReconnectCount.push(Number.isFinite(reconnectCount) ? reconnectCount : NaN);
      healTriggerCount.push(Number.isFinite(healCount) ? healCount : NaN);
      broadcastGapMsLatest.push(Number.isFinite(gapLatest) ? gapLatest : NaN);
      broadcastGapMsMax.push(Number.isFinite(gapMax) ? gapMax : NaN);
      gapViolationStreak.push(Number.isFinite(violationStreak) ? violationStreak : NaN);
      gapViolationCount.push(Number.isFinite(violationCount) ? violationCount : NaN);
    }
    if (!xMs.length) return null;
    const parsed = {
      xMs,
      up,
      down,
      pairLagMs,
      streamLastMsgAgeMs,
      streamLastPriceMsgAgeMs,
      fallbackTriggered,
      streamReconnectCount,
      healTriggerCount,
      broadcastGapMsLatest,
      broadcastGapMsMax,
      gapViolationStreak,
      gapViolationCount,
      sourceFile: filePath,
    };
    if (statSig) {
      csvCache.set(filePath, {
        mtimeMs: Number(statSig.mtimeMs),
        size: Number(statSig.size),
        value: parsed,
      });
    }
    return parsed;
  } catch {
    return null;
  }
}

function isTraceUsable(
  tr: { xMs: number[]; up: number[]; down: number[] } | null | undefined,
  minPoints = 10,
  minSpanMs = 30_000
) {
  if (!tr || !Array.isArray(tr.xMs) || !Array.isArray(tr.up) || !Array.isArray(tr.down)) return false;
  if (tr.xMs.length < minPoints || tr.up.length !== tr.xMs.length || tr.down.length !== tr.xMs.length) return false;
  const t0 = Number(tr.xMs[0]);
  const t1 = Number(tr.xMs[tr.xMs.length - 1]);
  if (!Number.isFinite(t0) || !Number.isFinite(t1)) return false;
  return (t1 - t0) >= minSpanMs;
}

function isTraceUsableForSession(
  tr: { xMs: number[]; up: number[]; down: number[] } | null | undefined,
  sessionLike: any,
  minPoints = 10
) {
  if (!tr || !Array.isArray(tr.xMs) || !Array.isArray(tr.up) || !Array.isArray(tr.down)) return false;
  if (tr.xMs.length < minPoints || tr.up.length !== tr.xMs.length || tr.down.length !== tr.xMs.length) return false;
  const t0 = Number(tr.xMs[0]);
  const t1 = Number(tr.xMs[tr.xMs.length - 1]);
  if (!Number.isFinite(t0) || !Number.isFinite(t1) || t1 < t0) return false;
  const observedSpan = t1 - t0;
  const startMs = Number(sessionLike?.startMs);
  const endMs = Number(sessionLike?.endMs);
  const expectedSpan = Number.isFinite(startMs) && Number.isFinite(endMs) && endMs > startMs
    ? (endMs - startMs)
    : inferSessionDurationMsFromSlug(sessionLike?.slug);
  const isClosed = !!sessionLike?.closed;
  const minSpanMs = isClosed
    ? Math.max(30_000, Math.floor(expectedSpan * 0.8))
    : 30_000;
  return observedSpan >= minSpanMs;
}

function buildSessionTraceFromRecordedLogs(rows: any[], slug: string, engine: Engine, runId?: number) {
  let entryPoint: { t: number; side: OutcomeSide; px: number } | null = null;
  let exitPoint: { t: number; side: OutcomeSide; px: number } | null = null;
  for (const r of rows) {
    if (r?.engine !== engine) continue;
    if (Number.isFinite(Number(runId)) && Number(r?.runId) !== Number(runId)) continue;
    if (String(r?.market?.slug || "") !== slug) continue;
    const t = Number(r?.t);
    if (!Number.isFinite(t)) continue;
    const phase = String(r?.execution?.phase || "").toLowerCase();
    if (phase !== "entry_fill" && phase !== "exit_fill" && phase !== "stop_fill") continue;

    const action = String(r?.action || "").toUpperCase();
    const sideRaw =
      String(r?.execution?.side || "").toUpperCase() ||
      (action.includes("_UP_") ? "UP" : action.includes("_DOWN_") ? "DOWN" : "");
    const side = sideRaw === "UP" || sideRaw === "DOWN" ? (sideRaw as OutcomeSide) : null;
    if (!side) continue;

    const actualPx = toFiniteOrNull(r?.execution?.actualPx ?? r?.execution?.actualFillPx ?? r?.actualFillPx ?? r?.fillPx);
    const stPx =
      side === "UP"
        ? toFiniteOrNull(r?.st?.entryPx ?? r?.st?.exitPx)
        : toFiniteOrNull(r?.st?.entryPx ?? r?.st?.exitPx);
    const sidePx = actualPx ?? stPx;
    if (!Number.isFinite(sidePx)) continue;
    const p = clamp01(sidePx);
    if (phase === "entry_fill") {
      if (!entryPoint || t < entryPoint.t) entryPoint = { t, side, px: p };
      continue;
    }
    if (phase === "exit_fill" || phase === "stop_fill") {
      if (!exitPoint || t > exitPoint.t) exitPoint = { t, side, px: p };
      continue;
    }
  }

  if (!entryPoint) return null;
  const endPoint = exitPoint ?? { t: entryPoint.t + 1000, side: entryPoint.side, px: entryPoint.px };

  const entryUp = entryPoint.side === "UP" ? entryPoint.px : clamp01(1 - entryPoint.px);
  const entryDn = entryPoint.side === "DOWN" ? entryPoint.px : clamp01(1 - entryPoint.px);
  const exitUp = endPoint.side === "UP" ? endPoint.px : clamp01(1 - endPoint.px);
  const exitDn = endPoint.side === "DOWN" ? endPoint.px : clamp01(1 - endPoint.px);

  const xMs = [entryPoint.t, endPoint.t];
  const up = [entryUp, exitUp];
  const down = [entryDn, exitDn];
  return { xMs, up, down, sourceFile: "trade_logs_fills" };
}

function buildTraceFromSessionEndpoints(sessionLike: any) {
  const sideRaw = String(sessionLike?.side || "").toUpperCase();
  const side = sideRaw === "UP" || sideRaw === "DOWN" ? (sideRaw as OutcomeSide) : null;
  const t0Raw = Number(sessionLike?.entryTsMs ?? sessionLike?.attemptTsMs);
  if (!Number.isFinite(t0Raw)) return null;
  const t0 = Number(t0Raw);
  const t1Raw = Number(sessionLike?.exitTsMs);
  const t1 = Number.isFinite(t1Raw) && t1Raw > t0 ? Number(t1Raw) : (t0 + 1000);
  const entryRaw = toFiniteOrNull(sessionLike?.entryPx ?? sessionLike?.signalPx ?? sessionLike?.intendedPx);
  const exitRaw = toFiniteOrNull(sessionLike?.exitPx ?? entryRaw);
  if (!Number.isFinite(Number(entryRaw)) || !Number.isFinite(Number(exitRaw))) return null;
  const entry = clamp01(Number(entryRaw));
  const exit = clamp01(Number(exitRaw));
  if (side === "UP") {
    return {
      xMs: [t0, t1],
      up: [entry, exit],
      down: [clamp01(1 - entry), clamp01(1 - exit)],
      sourceFile: "session_endpoints_fallback",
    };
  }
  if (side === "DOWN") {
    return {
      xMs: [t0, t1],
      up: [clamp01(1 - entry), clamp01(1 - exit)],
      down: [entry, exit],
      sourceFile: "session_endpoints_fallback",
    };
  }
  return {
    xMs: [t0, t1],
    up: [entry, exit],
    down: [clamp01(1 - entry), clamp01(1 - exit)],
    sourceFile: "session_endpoints_fallback",
  };
}

function inferSessionStartMsFromSlug(slugLike: any): number | null {
  const m = String(slugLike || "").match(/-(\d{10})$/);
  if (!m) return null;
  const sec = Number(m[1]);
  if (!Number.isFinite(sec)) return null;
  const ms = sec * 1000;
  return Number.isFinite(ms) ? ms : null;
}

function inferSessionDurationMsFromSlug(slugLike: any): number {
  const s = String(slugLike || "").toLowerCase();
  if (s.includes("updown-15m")) return 15 * 60_000;
  if (s.includes("updown-hourly")) return 60 * 60_000;
  if (s.includes("updown-daily")) return 24 * 60 * 60_000;
  return 5 * 60_000;
}

function buildNeutralTraceFromSlug(sessionLike: any) {
  const slug = String(sessionLike?.slug || "");
  const startMs =
    inferSessionStartMsFromSlug(slug) ??
    toFiniteOrNull(sessionLike?.attemptTsMs ?? sessionLike?.entryTsMs ?? sessionLike?.exitTsMs);
  if (!Number.isFinite(Number(startMs))) return null;
  const t0 = Number(startMs);
  const durationMs = inferSessionDurationMsFromSlug(slug);
  const t1 = Math.max(t0 + 1000, t0 + durationMs - 1000);
  return {
    xMs: [t0, t1],
    up: [0.5, 0.5],
    down: [0.5, 0.5],
    sourceFile: "neutral_slug_fallback",
  };
}

type ServerRunRow = { runId: number; startMs: number; startIso: string };
type ServerRunsMeta = { lastRunId: number; runs: ServerRunRow[] };

function readRunsMeta(): ServerRunsMeta {
  ensureTradeLogDir();
  try {
    const pathToRead = fs.existsSync(RUNS_META_PATH)
      ? RUNS_META_PATH
      : fs.existsSync(LEGACY_RUNS_META_PATH)
      ? LEGACY_RUNS_META_PATH
      : "";
    if (!pathToRead) return { lastRunId: 0, runs: [] };
    const raw = fs.readFileSync(pathToRead, "utf8");
    const j = JSON.parse(raw || "{}");
    const runs = Array.isArray(j?.runs)
      ? j.runs
          .map((r: any) => ({
            runId: Number(r?.runId),
            startMs: Number(r?.startMs),
            startIso: String(r?.startIso || ""),
          }))
          .filter((r: ServerRunRow) => Number.isFinite(r.runId) && Number.isFinite(r.startMs) && !!r.startIso)
          .sort((a: ServerRunRow, b: ServerRunRow) => a.startMs - b.startMs)
      : [];
    const lastRunId = Number.isFinite(Number(j?.lastRunId)) ? Number(j.lastRunId) : (runs.length ? runs[runs.length - 1].runId : 0);
    return { lastRunId, runs };
  } catch {
    return { lastRunId: 0, runs: [] };
  }
}

function writeRunsMeta(meta: ServerRunsMeta) {
  ensureTradeLogDir();
  try {
    fs.writeFileSync(RUNS_META_PATH, JSON.stringify(meta, null, 2) + "\n");
  } catch (e: any) {
    console.warn(`[RUN META WRITE ERROR] ${String(e?.message ?? e)}`);
  }
}

function registerServerRun() {
  const meta = readRunsMeta();
  if (!FORCE_NEW_SERVER_RUN_ON_START && RESUME_LATEST_RUN_ON_RESTART && Array.isArray(meta.runs) && meta.runs.length > 0) {
    const latest = meta.runs
      .slice()
      .sort((a, b) => (Number(a.startMs) - Number(b.startMs)) || (Number(a.runId) - Number(b.runId)))
      .pop() as ServerRunRow | undefined;
    if (latest && Number.isFinite(Number(latest.runId)) && Number(latest.runId) > 0) {
      SERVER_RUN_ID = Number(latest.runId);
      CURRENT_RUN_START_MS = Number(latest.startMs) > 0 ? Number(latest.startMs) : SERVER_RUN_START_MS;
      CURRENT_RUN_START_ISO = String(latest.startIso || new Date(CURRENT_RUN_START_MS).toISOString());
      RESUMED_EXISTING_RUN = true;
      console.log(`[RUN META] resume latest run enabled -> reusing runId=${SERVER_RUN_ID}`);
      return;
    }
  }
  if (FORCE_NEW_SERVER_RUN_ON_START && RESUME_LATEST_RUN_ON_RESTART) {
    console.log("[RUN META] FORCE_NEW_SERVER_RUN_ON_START=1 -> ignoring RESUME_LATEST_RUN_ON_RESTART");
  }
  const nextRunId = Math.max(0, Number(meta.lastRunId || 0)) + 1;
  SERVER_RUN_ID = nextRunId;
  CURRENT_RUN_START_MS = SERVER_RUN_START_MS;
  CURRENT_RUN_START_ISO = SERVER_RUN_START_ISO;
  RESUMED_EXISTING_RUN = false;
  const runs = [...meta.runs, { runId: nextRunId, startMs: SERVER_RUN_START_MS, startIso: SERVER_RUN_START_ISO }];
  const trimmed = runs.slice(-300);
  writeRunsMeta({ lastRunId: nextRunId, runs: trimmed });
}

function restorePaperBalanceFromTradeLogs(runId: number): number | null {
  if (!Number.isFinite(Number(runId))) return null;
  try {
    const rows = readJsonlFiles(listTradeLogFiles())
      .filter((r) => Number(r?.runId) === Number(runId) && String(r?.engine || "") === "paper")
      .sort((a, b) => Number(a?.t || 0) - Number(b?.t || 0));
    let lastBal: number | null = null;
    for (const r of rows) {
      const b = toFiniteOrNull(r?.st?.balanceUsd);
      if (Number.isFinite(b)) lastBal = Number(b);
    }
    return Number.isFinite(Number(lastBal)) ? Number(lastBal) : null;
  } catch {
    return null;
  }
}

function resolveSinceMs(scopeRaw: string, sinceMsRaw: number, runsRaw: number): number {
  const scope = String(scopeRaw || "run").toLowerCase();
  const sinceMsInput = Number.isFinite(sinceMsRaw) && sinceMsRaw > 0 ? sinceMsRaw : 0;
  if (scope === "day") return sinceMsInput;
  if (scope === "runs") {
    const n = Math.max(1, Math.min(100, Number.isFinite(runsRaw) ? Math.floor(runsRaw) : 10));
    const meta = readRunsMeta();
    const list = Array.isArray(meta.runs) ? meta.runs.slice().sort((a, b) => a.startMs - b.startMs) : [];
    const idx = Math.max(0, list.length - n);
    const base = list.length ? Number(list[idx].startMs) : CURRENT_RUN_START_MS;
    return Math.max(base, sinceMsInput);
  }
  const base = CURRENT_RUN_START_MS;
  return Math.max(base, sinceMsInput || base);
}

function getRunMetaById(runId: number): { runId: number; startMs: number; startIso: string } | null {
  const rid = Number(runId);
  if (!Number.isFinite(rid)) return null;
  const meta = readRunsMeta();
  const list = Array.isArray(meta.runs) ? meta.runs : [];
  for (const r of list) {
    if (Number(r?.runId) !== rid) continue;
    const startMs = Number(r?.startMs);
    const startIso = String(r?.startIso || "");
    if (!Number.isFinite(startMs) || startMs <= 0 || !startIso) continue;
    return { runId: rid, startMs, startIso };
  }
  return null;
}

function resolveRunScope(req: any, scopeRaw: string, sinceMsRaw: number, runsRaw: number) {
  const scope = String(scopeRaw || "run").toLowerCase();
  const sinceMsInput = Number.isFinite(Number(sinceMsRaw)) && Number(sinceMsRaw) > 0 ? Number(sinceMsRaw) : 0;
  if (scope !== "run") {
    return {
      scope,
      runId: null as number | null,
      runStartMs: null as number | null,
      runStartIso: null as string | null,
      sinceMs: resolveSinceMs(scope, sinceMsRaw, runsRaw),
    };
  }
  const runIdReqRaw = Number(req?.query?.runId);
  const selectedRunId = Number.isFinite(runIdReqRaw) ? Math.floor(runIdReqRaw) : Number(SERVER_RUN_ID);
  const selectedMeta = getRunMetaById(selectedRunId);
  if (selectedMeta) {
    const effectiveSinceMs = Math.max(Number(selectedMeta.startMs), sinceMsInput || 0);
    return {
      scope,
      runId: selectedMeta.runId,
      runStartMs: selectedMeta.startMs,
      runStartIso: selectedMeta.startIso,
      sinceMs: effectiveSinceMs,
    };
  }
  return {
    scope,
    runId: Number(SERVER_RUN_ID),
    runStartMs: Number(CURRENT_RUN_START_MS),
    runStartIso: String(CURRENT_RUN_START_ISO),
    sinceMs: resolveSinceMs(scope, sinceMsRaw, runsRaw),
  };
}

function inferScopedInstanceIdForRun(engineLike: any, runNumLike: any): string {
  const engine = String(engineLike || "paper").trim().toLowerCase();
  const targetRunNum = Math.floor(Number(runNumLike));
  if (!(Number.isFinite(targetRunNum) && targetRunNum > 0)) return "";
  const candidates = Array.from(botInstances.values())
    .map((inst: any) => ({
      instanceId: String(inst?.instanceId || "").trim(),
      mode: String(inst?.mode || "").trim().toLowerCase(),
      status: String(inst?.status || "").trim().toLowerCase(),
      runNum: Number(inst?.runNum || 0),
      launchedAtMs: Number(inst?.launchedAtMs || 0),
    }))
    .filter((inst) => !!inst.instanceId)
    .filter((inst) => inst.mode === engine)
    .filter((inst) => Math.floor(Number(inst.runNum || 0)) === targetRunNum)
    .sort((a, b) => {
      const aRunning = a.status === "running" ? 1 : 0;
      const bRunning = b.status === "running" ? 1 : 0;
      if (aRunning !== bRunning) return bRunning - aRunning;
      return Number(b.launchedAtMs || 0) - Number(a.launchedAtMs || 0);
    });
  return candidates[0]?.instanceId || "";
}

function filterTradeRowsByScope(
  rows: any[],
  engine: Engine,
  scopeRaw: string,
  sinceMs: number,
  runIdForScope?: number | null
): any[] {
  const scope = String(scopeRaw || "run").toLowerCase();
  const runId = Number.isFinite(Number(runIdForScope)) ? Number(runIdForScope) : Number(SERVER_RUN_ID);
  return rows.filter((r) => {
    if (r?.engine !== engine) return false;
    const t = Number(r?.t);
    if (!Number.isFinite(t) || t < sinceMs) return false;
    if (scope === "run") {
      const rr = Number(r?.runId);
      if (!Number.isFinite(rr) || rr !== runId) return false;
    }
    return true;
  });
}

function tradeRowSessionSlug(row: any): string {
  return String(row?.st?.marketSlug || row?.market?.slug || "").trim().toLowerCase();
}

function tradeRowSessionKey(row: any): string {
  const slug = tradeRowSessionSlug(row);
  const runId = Number.isFinite(Number(row?.runId)) ? Math.floor(Number(row.runId)) : "na";
  const instanceId = String(row?.instanceId || "").trim() || "na";
  return slug ? `${runId}:${instanceId}:${slug}` : "";
}

function tradeRowSessionTerminalMs(row: any): number | null {
  const slug = tradeRowSessionSlug(row);
  const candidates = [
    row?.sessionAudit?.sessionEndMs,
    row?.market?.endMs,
    row?.st?.exitTsMs,
    inferSessionEndMsFromSlug(slug),
    row?.t,
  ];
  for (const raw of candidates) {
    const n = Number(raw);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return null;
}

function collectPaperSessionPnlEvents(tradeRowsLike: any[]): Array<{
  key: string;
  slug: string;
  instanceId: string | null;
  runId: number | null;
  t: number;
  pnlUsd: number;
  excludeFromPnl: boolean;
  audit: boolean;
}> {
  const rows = Array.isArray(tradeRowsLike) ? tradeRowsLike.slice() : [];
  const exitRe = /^(EXIT|STOP)_(UP|DOWN)_(PAPER|LIVE)$/;
  const auditBySession = new Map<string, any>();
  const fallbackBySession = new Map<string, any>();
  for (const row of rows.sort((a, b) => Number(a?.t || 0) - Number(b?.t || 0))) {
    const key = tradeRowSessionKey(row);
    const slug = tradeRowSessionSlug(row);
    if (!key || !slug) continue;
    const terminalMs = tradeRowSessionTerminalMs(row);
    const rowRunId = Number.isFinite(Number(row?.runId)) ? Math.floor(Number(row.runId)) : null;
    const rowInstanceId = String(row?.instanceId || "").trim() || null;
    const action = String(row?.action || "");
    if (SESSION_AUDIT_PNL_ACTION_RE.test(action)) {
      const pnlUsd = Number(row?.sessionAudit?.correctedNetPnlUsd ?? row?.st?.pnlUsd);
      if (!Number.isFinite(pnlUsd) || !Number.isFinite(Number(terminalMs))) continue;
      auditBySession.set(key, {
        key,
        slug,
        instanceId: rowInstanceId,
        runId: rowRunId,
        t: Number(terminalMs),
        pnlUsd: Number(pnlUsd),
        excludeFromPnl: !!row?.sessionAudit?.excludeFromPnl,
        audit: true,
      });
      continue;
    }
    if (!exitRe.test(action)) continue;
    const pnlUsd = Number(row?.st?.pnlUsd);
    if (!Number.isFinite(pnlUsd) || !Number.isFinite(Number(terminalMs))) continue;
    const prev = fallbackBySession.get(key) || {
      key,
      slug,
      instanceId: rowInstanceId,
      runId: rowRunId,
      t: Number(terminalMs),
      pnlUsd: 0,
      excludeFromPnl: false,
      audit: false,
    };
    prev.t = Math.max(Number(prev.t || 0), Number(terminalMs));
    prev.pnlUsd = Number(prev.pnlUsd || 0) + Number(pnlUsd);
    fallbackBySession.set(key, prev);
  }
  const out = Array.from(auditBySession.values());
  for (const [key, row] of fallbackBySession.entries()) {
    if (auditBySession.has(key)) continue;
    out.push(row);
  }
  return out.sort((a, b) => Number(a.t) - Number(b.t));
}

function percentileFromSorted(nums: number[], p: number): number | null {
  if (!Array.isArray(nums) || !nums.length) return null;
  if (nums.length === 1) return nums[0];
  const idx = Math.max(0, Math.min(nums.length - 1, Math.round((nums.length - 1) * p)));
  const v = Number(nums[idx]);
  return Number.isFinite(v) ? v : null;
}

function buildSessionStreamWindowSummary(
  traceLike: any,
  sessionLike: any,
  opts?: {
    windowStartSec?: number;
    windowEndSec?: number;
    targetGapMs?: number;
  }
): Record<string, any> | null {
  try {
    const trace = traceLike && typeof traceLike === "object" ? traceLike : null;
    const xMs = Array.isArray(trace?.xMs) ? trace.xMs : [];
    if (!xMs.length) return null;
    const windowStartSec = Number.isFinite(Number(opts?.windowStartSec)) ? Number(opts?.windowStartSec) : 10;
    const windowEndSec = Number.isFinite(Number(opts?.windowEndSec)) ? Number(opts?.windowEndSec) : 70;
    const targetGapMs = Number.isFinite(Number(opts?.targetGapMs)) ? Number(opts?.targetGapMs) : 25;
    const sessionStartMsRaw = Number(
      sessionLike?.startMs ??
      sessionLike?.sessionStartMs ??
      sessionLike?.entryTsMs ??
      inferSessionStartMsFromSlug(String(sessionLike?.slug || ""))
    );
    if (!Number.isFinite(sessionStartMsRaw) || sessionStartMsRaw <= 0) return null;
    const windowStartMs = sessionStartMsRaw + (windowStartSec * 1000);
    const windowEndMs = sessionStartMsRaw + (windowEndSec * 1000);
    const points = xMs
      .map((raw: any) => Number(raw))
      .filter((ms: number) => Number.isFinite(ms) && ms >= windowStartMs && ms <= windowEndMs)
      .sort((a: number, b: number) => a - b);
    if (!points.length) {
      return {
        windowStartSec,
        windowEndSec,
        targetGapMs,
        sampleCount: 0,
        deltaCount: 0,
        avgGapMs: null,
        p50GapMs: null,
        p95GapMs: null,
        maxGapMs: null,
        overTargetCount: 0,
        overTargetPct: 0,
        effectiveHz: null,
      };
    }
    const deltas: number[] = [];
    for (let i = 1; i < points.length; i += 1) deltas.push(Math.max(0, points[i] - points[i - 1]));
    const sortedDeltas = deltas.slice().sort((a, b) => a - b);
    const avgGapMs = sortedDeltas.length
      ? sortedDeltas.reduce((sum, v) => sum + Number(v), 0) / sortedDeltas.length
      : null;
    const overTargetCount = sortedDeltas.filter((v) => Number(v) > targetGapMs).length;
    const overTargetPct = sortedDeltas.length ? (overTargetCount / sortedDeltas.length) * 100 : 0;
    const effectiveHz = Number.isFinite(Number(avgGapMs)) && Number(avgGapMs) > 0
      ? 1000 / Number(avgGapMs)
      : null;
    const roundMaybe = (v: number | null, digits: number) =>
      Number.isFinite(Number(v)) ? Number(Number(v).toFixed(digits)) : null;
    return {
      windowStartSec,
      windowEndSec,
      targetGapMs,
      sampleCount: points.length,
      deltaCount: sortedDeltas.length,
      avgGapMs: roundMaybe(avgGapMs, 1),
      p50GapMs: roundMaybe(percentileFromSorted(sortedDeltas, 0.5), 1),
      p95GapMs: roundMaybe(percentileFromSorted(sortedDeltas, 0.95), 1),
      maxGapMs: roundMaybe(sortedDeltas.length ? sortedDeltas[sortedDeltas.length - 1] : null, 1),
      overTargetCount,
      overTargetPct: roundMaybe(overTargetPct, 1),
      effectiveHz: roundMaybe(effectiveHz, 2),
    };
  } catch {
    return null;
  }
}

function buildSessionEndSnapshotSummary(
  traceLike: any,
  _sessionLike: any,
  opts?: {
    recentGapCount?: number;
    thresholdGapMs?: number[];
  }
): Record<string, any> | null {
  try {
    const trace = traceLike && typeof traceLike === "object" ? traceLike : null;
    const xMs = Array.isArray(trace?.xMs) ? trace.xMs : [];
    const points = xMs
      .map((raw: any) => Number(raw))
      .filter((ms: number) => Number.isFinite(ms))
      .sort((a: number, b: number) => a - b);
    if (points.length < 2) return null;
    const allDeltas: number[] = [];
    for (let i = 1; i < points.length; i += 1) {
      allDeltas.push(Math.max(0, points[i] - points[i - 1]));
    }
    if (!allDeltas.length) return null;
    const recentGapCount = Number.isFinite(Number(opts?.recentGapCount))
      ? Math.max(1, Math.floor(Number(opts?.recentGapCount)))
      : 500;
    const thresholds = Array.isArray(opts?.thresholdGapMs) && opts?.thresholdGapMs.length
      ? opts.thresholdGapMs
          .map((v) => Number(v))
          .filter((v) => Number.isFinite(v) && v >= 0)
      : [25, 50, 75, 100, 125, 150];
    const deltas = allDeltas.slice(-recentGapCount);
    const sortedDeltas = deltas.slice().sort((a, b) => a - b);
    const avgGapMs = sortedDeltas.reduce((sum, v) => sum + Number(v), 0) / sortedDeltas.length;
    const effectiveHz = Number.isFinite(avgGapMs) && avgGapMs > 0 ? (1000 / avgGapMs) : null;
    const lastGapMs = Number.isFinite(Number(deltas[deltas.length - 1])) ? Number(deltas[deltas.length - 1]) : null;
    const roundMaybe = (v: number | null, digits: number) =>
      Number.isFinite(Number(v)) ? Number(Number(v).toFixed(digits)) : null;
    const thresholdStats = thresholds.map((ms) => {
      const count = sortedDeltas.filter((gap) => Number(gap) > Number(ms)).length;
      const pct = sortedDeltas.length ? (count / sortedDeltas.length) * 100 : 0;
      return {
        gapMs: Number(ms),
        count,
        pct: roundMaybe(pct, 1),
      };
    });
    return {
      mode: "session_end",
      label: "300s snapshot",
      basis: "last_500_gaps",
      recentGapCountTarget: recentGapCount,
      sampleCount: points.length,
      deltaCount: sortedDeltas.length,
      firstTsMs: points[0],
      lastTsMs: points[points.length - 1],
      durationMs: Math.max(0, Number(points[points.length - 1]) - Number(points[0])),
      liveGapMs: roundMaybe(lastGapMs, 1),
      avgGapMs: roundMaybe(avgGapMs, 1),
      p50GapMs: roundMaybe(percentileFromSorted(sortedDeltas, 0.5), 1),
      p95GapMs: roundMaybe(percentileFromSorted(sortedDeltas, 0.95), 1),
      maxGapMs: roundMaybe(sortedDeltas[sortedDeltas.length - 1], 1),
      effectiveHz: roundMaybe(effectiveHz, 2),
      thresholds: thresholdStats,
    };
  } catch {
    return null;
  }
}

function sessionCardArtifactNeedsStreamWindowSummary(sessionLike: any): boolean {
  const summary = sessionLike?.streamSampleWindow;
  return !summary || typeof summary !== "object" || !Number.isFinite(Number(summary?.sampleCount));
}

function sessionCardArtifactNeedsStreamEndSnapshot(sessionLike: any): boolean {
  const summary = sessionLike?.streamEndSnapshot;
  return !summary || typeof summary !== "object" || !Number.isFinite(Number(summary?.deltaCount));
}

function latencyStats(metric: string, engine?: Engine) {
  const rows = engine
    ? (liveLatencySamplesByMetricKey.get(latencyMetricBucketKey(metric, engine)) || [])
      .filter((s) => Number.isFinite(Number(s.latencyMs)))
    : liveLatencySamples.filter((s) => {
      if (s.metric !== metric) return false;
      return Number.isFinite(Number(s.latencyMs));
    });
  if (!rows.length) {
    return {
      count: 0,
      lastMs: null as number | null,
      minMs: null as number | null,
      p50Ms: null as number | null,
      p95Ms: null as number | null,
      maxMs: null as number | null,
    };
  }
  const vals = rows.map((r) => Number(r.latencyMs)).filter((n) => Number.isFinite(n)).sort((a, b) => a - b);
  const last = Number(rows[rows.length - 1]?.latencyMs);
  return {
    count: rows.length,
    lastMs: Number.isFinite(last) ? last : null,
    minMs: Number.isFinite(vals[0]) ? vals[0] : null,
    p50Ms: percentileFromSorted(vals, 0.5),
    p95Ms: percentileFromSorted(vals, 0.95),
    maxMs: Number.isFinite(vals[vals.length - 1]) ? vals[vals.length - 1] : null,
  };
}

function computeHealthSnapshot(lite = false) {
  const botTick = botTickGapStatsNow();
  const botTickDuration = botTickDurationStatsNow();
  const now = nowMs();
  const activeBotRows = Array.from(botInstances.values())
    .filter((b) => (String(b.status || "").toLowerCase() === "running") || (String(b.status || "").toLowerCase() === "watching"));
  const activeBotStrategies = activeBotRows
    .slice()
    .sort((a, b) => Number(b.runNum || 0) - Number(a.runNum || 0))
    .slice(0, 8)
    .map((b) => ({
      instanceId: b.instanceId,
      runNum: b.runNum,
      strategyId: b.strategyId,
      strategyPath: b.strategyPath,
      mode: b.mode,
      status: b.status,
      marketSlug: b.marketSlug,
    }));
  const upLagMs = current?.upToken ? quoteAgeMs(String(current.upToken)) : null;
  const downLagMs = current?.downToken ? quoteAgeMs(String(current.downToken)) : null;
  const pairLagMs =
    quotePairCache &&
    String(quotePairCache.upToken) === String(current?.upToken || "") &&
    String(quotePairCache.downToken) === String(current?.downToken || "")
      ? Math.max(0, now - Number(quotePairCache.tsMs || 0))
      : null;
  const mainLoopAgeMs =
    Number.isFinite(Number(mainLoopLastBeatMs)) && Number(mainLoopLastBeatMs) > 0
      ? Math.max(0, now - Number(mainLoopLastBeatMs))
      : null;
  const rssMb = process.memoryUsage().rss / (1024 * 1024);
  const heapUsedMb = process.memoryUsage().heapUsed / (1024 * 1024);
  const processCpuPct = sampleProcessCpuPct();
  if (lite) {
    return {
      runtimeVersion: LIVEFIX_RUNTIME_VERSION,
      runId: SERVER_RUN_ID,
      runStartMs: CURRENT_RUN_START_MS,
      runStartIso: CURRENT_RUN_START_ISO,
      strategyBots: activeBotStrategies,
      strategyBotCount: activeBotRows.length,
      liveEnabled: !!uiLive.enabled,
      runtimeLagMs:
        Number.isFinite(Number(botTick.activeMaxRuntimeAgeMs))
          ? Number(botTick.activeMaxRuntimeAgeMs)
          : (Number.isFinite(Number(botTick.latestGapMs)) ? Number(botTick.latestGapMs) : null),
      processStats: {
        cpuPct: Number.isFinite(processCpuPct) ? Number(processCpuPct.toFixed(1)) : null,
        rssMb: Number.isFinite(rssMb) ? Number(rssMb.toFixed(1)) : null,
        heapUsedMb: Number.isFinite(heapUsedMb) ? Number(heapUsedMb.toFixed(1)) : null,
      },
      quoteFeed: {
        maxStaleMs: QUOTE_MAX_STALE_MS,
        streamHealthyMaxAgeMs: QUOTE_STREAM_HEALTHY_MAX_AGE_MS,
        pumpIntervalMs: QUOTE_PUMP_INTERVAL_MS,
        pumpHealthyIntervalMs: QUOTE_PUMP_HEALTHY_INTERVAL_MS,
        pairSource: String(quotePairCache?.source || "") || null,
        pairPure: !!quotePairCache?.pure,
        pairSynthetic: !!quotePairCache?.synthetic,
        pairSeq: Number.isFinite(Number(quotePairCache?.seq)) ? Number(quotePairCache?.seq) : null,
        pairObservedAgeMs:
          Number.isFinite(Number(quotePairCache?.observedAtMs)) && Number(quotePairCache?.observedAtMs) > 0
            ? Math.max(0, now - Number(quotePairCache?.observedAtMs))
            : null,
        upLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : (Number.isFinite(Number(upLagMs)) ? Number(upLagMs) : null),
        downLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : (Number.isFinite(Number(downLagMs)) ? Number(downLagMs) : null),
        pairLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null,
        fallbackTriggered: quoteFallbackTriggerCount,
        fallbackSucceeded: quoteFallbackSuccessCount,
        fallbackErrors: quoteFallbackErrorCount,
        streamEnabled: QUOTE_STREAM_ENABLED,
        streamConnected: quoteStreamConnected,
        streamLastMsgAgeMs:
          Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
            ? Math.max(0, now - Number(quoteStreamLastMsgMs))
            : null,
        streamLastPriceMsgAgeMs:
          Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
            ? Math.max(0, now - Number(quoteStreamLastPriceMsgMs))
            : null,
      },
      latencyWatchdog: {
        targetMs: LIVE_LATENCY_TARGET_MS,
        alertStreak: LIVE_LATENCY_ALERT_STREAK,
        unhealthyStreak: LIVE_LATENCY_UNHEALTHY_STREAK,
        sampleCount: liveLatencySamples.length,
        violationStreak: liveLatencyViolationStreak,
        violationCount: liveLatencyViolationCount,
        unhealthy:
          liveLatencyUnhealthySinceMs != null &&
          Number.isFinite(Number(liveLatencyUnhealthySinceMs)) &&
          Number(liveLatencyUnhealthySinceMs) > 0,
        unhealthySinceMs:
          liveLatencyUnhealthySinceMs != null &&
          Number.isFinite(Number(liveLatencyUnhealthySinceMs)) &&
          Number(liveLatencyUnhealthySinceMs) > 0
            ? Number(liveLatencyUnhealthySinceMs)
            : null,
        watchdogHealCount,
        watchdogAlertCount,
        watchdogLastReason: watchdogLastReason || null,
        watchdogLastHealMs: Number.isFinite(Number(watchdogLastHealMs)) && Number(watchdogLastHealMs) > 0
          ? Number(watchdogLastHealMs)
          : null,
        mainLoop: {
          lastBeatAgeMs: Number.isFinite(Number(mainLoopAgeMs)) ? Number(mainLoopAgeMs) : null,
          gapLatestMs: Number.isFinite(Number(mainLoopGapMsLatest)) ? Number(mainLoopGapMsLatest) : null,
          gapMaxMs: Number.isFinite(Number(mainLoopGapMsMax)) ? Number(mainLoopGapMsMax) : null,
          softHealMs: MAIN_LOOP_STALL_SOFT_HEAL_MS,
          hardFailMs: MAIN_LOOP_STALL_HARD_FAIL_MS,
        },
      },
    };
  }
  const base: any = {
    runtimeVersion: LIVEFIX_RUNTIME_VERSION,
    runId: SERVER_RUN_ID,
    runStartMs: CURRENT_RUN_START_MS,
    runStartIso: CURRENT_RUN_START_ISO,
    serverStartedAtMs: SERVER_RUN_START_MS,
    serverStartedIso: SERVER_RUN_START_ISO,
    strategyPath: STRATEGY_PATH,
    strategyLoaded: {
      paper: !!strategyPaperByLane.BASE && !!strategyPaperByLane.NO_CROSS_WINNER,
      live: !!strategyLive,
    },
    strategyBots: activeBotStrategies,
    entryGuard: {
      active: entryBlockActive,
      blockedSessionSlug: entryBlockedSessionSlug,
    },
    liveEnabled: !!uiLive.enabled,
    liveExecution: buildLiveExecutionSnapshot(),
    botRuntime: {
      pollMs: BOT_RUNTIME_POLL_MS,
      realtimeMaintenancePollMs: BOT_REALTIME_MAINTENANCE_POLL_MS,
      decisionSnapshotMinIntervalMs: BOT_DECISION_SNAPSHOT_MIN_INTERVAL_MS,
      strategySnapshotMinIntervalMs: BOT_STRATEGY_SNAPSHOT_MIN_INTERVAL_MS,
      ...botTick,
      tickDuration: botTickDuration,
    },
    runtimeLagMs:
      Number.isFinite(Number(botTick.activeMaxRuntimeAgeMs))
        ? Number(botTick.activeMaxRuntimeAgeMs)
        : (Number.isFinite(Number(botTick.latestGapMs)) ? Number(botTick.latestGapMs) : null),
    eventLoop: {
      sampleIntervalMs: EVENT_LOOP_MONITOR_INTERVAL_MS,
      latestLagMs: Number.isFinite(Number(eventLoopLagMsLatest)) ? Number(eventLoopLagMsLatest) : null,
      maxLagMs: Number.isFinite(Number(eventLoopLagMsMax)) ? Number(eventLoopLagMsMax) : null,
    },
    processStats: {
      cpuPct: Number.isFinite(processCpuPct) ? Number(processCpuPct.toFixed(1)) : null,
      rssMb: Number.isFinite(rssMb) ? Number(rssMb.toFixed(1)) : null,
      heapUsedMb: Number.isFinite(heapUsedMb) ? Number(heapUsedMb.toFixed(1)) : null,
      loadAvg1m: Number.isFinite(Number(os.loadavg?.()[0])) ? Number(Number(os.loadavg()[0]).toFixed(2)) : null,
      breakdown: buildProcessCpuBreakdown(processCpuPct),
    },
    comparePerformance: {
      jsonFileCacheEntries: jsonFileCache.size,
      responseCacheEntries: continuityResponseCache.size,
      hostContinuity: endpointPerfSnapshot("compare_host_continuity"),
      botContinuityHistory: endpointPerfSnapshot("bot_continuity_history"),
      sessionHistory: endpointPerfSnapshot("session_history"),
      chartHistory: endpointPerfSnapshot("chart_history"),
      hotHttpEndpoints: hotHttpEndpointPerf(12),
    },
    quoteFeed: {
      maxStaleMs: QUOTE_MAX_STALE_MS,
      streamHealthyMaxAgeMs: QUOTE_STREAM_HEALTHY_MAX_AGE_MS,
      pumpIntervalMs: QUOTE_PUMP_INTERVAL_MS,
      pumpHealthyIntervalMs: QUOTE_PUMP_HEALTHY_INTERVAL_MS,
      pairSource: String(quotePairCache?.source || "") || null,
      pairPure: !!quotePairCache?.pure,
      pairSynthetic: !!quotePairCache?.synthetic,
      pairSeq: Number.isFinite(Number(quotePairCache?.seq)) ? Number(quotePairCache?.seq) : null,
      pairObservedAgeMs:
        Number.isFinite(Number(quotePairCache?.observedAtMs)) && Number(quotePairCache?.observedAtMs) > 0
          ? Math.max(0, now - Number(quotePairCache?.observedAtMs))
          : null,
      upLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : (Number.isFinite(Number(upLagMs)) ? Number(upLagMs) : null),
      downLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : (Number.isFinite(Number(downLagMs)) ? Number(downLagMs) : null),
      pairLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null,
      fallbackTriggerMs: QUOTE_FALLBACK_TRIGGER_MS,
      fallbackTimeoutMs: QUOTE_FALLBACK_TIMEOUT_MS,
      fallbackCooldownMs: QUOTE_FALLBACK_COOLDOWN_MS,
      fallbackTriggered: quoteFallbackTriggerCount,
      fallbackSucceeded: quoteFallbackSuccessCount,
      fallbackErrors: quoteFallbackErrorCount,
      streamEnabled: QUOTE_STREAM_ENABLED,
      streamConnected: quoteStreamConnected,
      streamLastMsgAgeMs:
        Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
          ? Math.max(0, now - Number(quoteStreamLastMsgMs))
          : null,
      streamLastPriceMsgAgeMs:
        Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
          ? Math.max(0, now - Number(quoteStreamLastPriceMsgMs))
          : null,
      streamMsgCount: quoteStreamMsgCount,
      streamErrCount: quoteStreamErrCount,
      streamReconnectCount: quoteStreamReconnectCount,
      streamStaleReconnectCount: quoteStreamStaleReconnectCount,
      desiredTokens: desiredQuoteStreamTokens(),
      subscribedTokens: Array.from(quoteStreamSubscribedTokens),
    },
    routing: {
      hotServiceMode: HOT_SERVICE_MODE,
      readOnlyOrigin: READ_ONLY_ORIGIN || null,
    },
    userStream: {
      enabled: USER_STREAM_ENABLED,
      connected: userStreamConnected,
      marketsKey: userStreamLastDesiredMarketsKey || null,
      lastMsgAgeMs:
        Number.isFinite(Number(userStreamLastMsgMs)) && Number(userStreamLastMsgMs) > 0
          ? Math.max(0, now - Number(userStreamLastMsgMs))
          : null,
      msgCount: userStreamMsgCount,
      errCount: userStreamErrCount,
      reconnectCount: userStreamReconnectCount,
    },
    quoteKpi: {
      targetMs: QUOTE_KPI_TARGET_MS,
      quoteBroadcastIntervalMs: QUOTE_BROADCAST_INTERVAL_MS,
      quoteBroadcastHealthyIntervalMs: QUOTE_BROADCAST_HEALTHY_INTERVAL_MS,
      quoteBroadcastRolloverIntervalMs: QUOTE_BROADCAST_ROLLOVER_INTERVAL_MS,
      quoteBroadcastIdleIntervalMs: QUOTE_BROADCAST_IDLE_INTERVAL_MS,
      broadcastGapMsLatest: Number.isFinite(Number(quoteBroadcastGapMsLatest))
        ? Number(quoteBroadcastGapMsLatest)
        : null,
      broadcastGapMsMax: Number.isFinite(Number(quoteBroadcastGapMsMax))
        ? Number(quoteBroadcastGapMsMax)
        : null,
      gapViolationStreak: quoteBroadcastGapViolationStreak,
      gapViolationCount: quoteBroadcastGapViolationCount,
      feedViolationStreak: quoteBroadcastFeedViolationStreak,
      healTriggerCount: quoteKpiHealTriggerCount,
      unhealthy:
        quoteKpiUnhealthySinceMs != null &&
        Number.isFinite(Number(quoteKpiUnhealthySinceMs)) &&
        Number(quoteKpiUnhealthySinceMs) > 0,
      unhealthySinceMs:
        quoteKpiUnhealthySinceMs != null &&
        Number.isFinite(Number(quoteKpiUnhealthySinceMs)) &&
        Number(quoteKpiUnhealthySinceMs) > 0
          ? Number(quoteKpiUnhealthySinceMs)
          : null,
    },
    latencyWatchdog: {
      targetMs: LIVE_LATENCY_TARGET_MS,
      alertStreak: LIVE_LATENCY_ALERT_STREAK,
      unhealthyStreak: LIVE_LATENCY_UNHEALTHY_STREAK,
      sampleCount: liveLatencySamples.length,
      violationStreak: liveLatencyViolationStreak,
      violationCount: liveLatencyViolationCount,
      unhealthy:
        liveLatencyUnhealthySinceMs != null &&
        Number.isFinite(Number(liveLatencyUnhealthySinceMs)) &&
        Number(liveLatencyUnhealthySinceMs) > 0,
      unhealthySinceMs:
        liveLatencyUnhealthySinceMs != null &&
        Number.isFinite(Number(liveLatencyUnhealthySinceMs)) &&
        Number(liveLatencyUnhealthySinceMs) > 0
          ? Number(liveLatencyUnhealthySinceMs)
          : null,
      watchdogHealCount,
      watchdogAlertCount,
      watchdogLastReason: watchdogLastReason || null,
      watchdogLastHealMs: Number.isFinite(Number(watchdogLastHealMs)) && Number(watchdogLastHealMs) > 0
        ? Number(watchdogLastHealMs)
        : null,
      mainLoop: {
        lastBeatAgeMs: Number.isFinite(Number(mainLoopAgeMs)) ? Number(mainLoopAgeMs) : null,
        gapLatestMs: Number.isFinite(Number(mainLoopGapMsLatest)) ? Number(mainLoopGapMsLatest) : null,
        gapMaxMs: Number.isFinite(Number(mainLoopGapMsMax)) ? Number(mainLoopGapMsMax) : null,
        softHealMs: MAIN_LOOP_STALL_SOFT_HEAL_MS,
        hardFailMs: MAIN_LOOP_STALL_HARD_FAIL_MS,
      },
    },
  };
  if (!lite) {
    base.latencyWatchdog.metrics = {
      quoteFeedLag: latencyStats("quote_feed_lag", "live"),
      quoteBroadcastGap: latencyStats("quote_broadcast_gap", "live"),
      entrySignalToFill: latencyStats("entry_signal_to_fill", "live"),
      entrySignalToObservedFill: latencyStats("entry_signal_to_observed_fill", "live"),
      entrySubmitToFill: latencyStats("entry_submit_to_fill", "live"),
      exitSignalToFill: latencyStats("exit_signal_to_fill", "live"),
      exitSignalToObservedFill: latencyStats("exit_signal_to_observed_fill", "live"),
      stopSignalToFill: latencyStats("stop_signal_to_fill", "live"),
      stopSignalToObservedFill: latencyStats("stop_signal_to_observed_fill", "live"),
    };
    base.chronology = {
      violations: chronologyViolationCount,
      openStates: chronologyStateByKey.size,
      recentAlerts: chronologyAlerts.slice(-20),
    };
    base.paperLiveParity = {
      pending: paperLiveParityExpectations.filter((x) => !x.matched && !x.alerted).length,
      matched: paperLiveParityExpectations.filter((x) => x.matched).length,
      alerted: paperLiveParityAlerts.length,
      recentAlerts: paperLiveParityAlerts.slice(-20),
    };
  }
  return base;
}

function buildHealthSnapshot(lite = false) {
  const key = lite ? "lite" : "full";
  const cache = healthSnapshotCache[key];
  const now = nowMs();
  if (cache.value && (now - Number(cache.builtAtMs || 0)) <= HEALTH_SNAPSHOT_CACHE_MS) {
    return cache.value;
  }
  const value = computeHealthSnapshot(lite);
  healthSnapshotCache[key] = { builtAtMs: now, value };
  return value;
}

function buildLiveExecutionSnapshot() {
  const now = nowMs();
  const liveBots = Array.from(botInstances.values()).filter((b) => {
    if (!isRealLiveCapableBotInstance(b)) return false;
    return String(b.status || "").trim().toLowerCase() !== "stopped";
  });
  let botOpenExposure = false;
  let botOrderFlowActive = false;
  for (const b of liveBots) {
    const rt = botRuntimes.get(b.instanceId);
    if (!rt) continue;
    const rtAny = rt as any;
    if (!!rt.entered && (rt.side === "UP" || rt.side === "DOWN")) {
      botOpenExposure = true;
    }
    if (
      !!rtAny.enterInFlight ||
      !!rtAny.exitInFlight ||
      !!rtAny.tpOrderInFlight ||
      !!String(rtAny.tpOrderId || "").trim()
    ) {
      botOrderFlowActive = true;
    }
  }
  const hostOpenExposure = !!stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN");
  const hostOrderFlowActive =
    !!stLive.enterInFlight ||
    !!stLive.exitInFlight ||
    !!stLive.tpOrderInFlight ||
    !!String(stLive.tpOrderId || "").trim();
  const recentRealEventMs =
    Number.isFinite(Number(lastRealLiveExecutionMs)) && Number(lastRealLiveExecutionMs) > 0
      ? Number(lastRealLiveExecutionMs)
      : null;
  const recentRealEventAgeMs =
    recentRealEventMs != null
      ? Math.max(0, now - Number(recentRealEventMs))
      : null;
  const recentRealEventActive =
    recentRealEventAgeMs != null &&
    Number(recentRealEventAgeMs) <= LIVE_EXECUTION_ACTIVITY_WINDOW_MS;
  const openExposure = hostOpenExposure || botOpenExposure;
  const orderFlowActive = hostOrderFlowActive || botOrderFlowActive;
  let status: "disabled" | "idle_armed" | "active" | "active_while_disabled" | "blocked" = "disabled";
  if (liveExecutionHardBlockedReason) {
    status = "blocked";
  } else if (!!uiLive.enabled) {
    status = (openExposure || orderFlowActive || recentRealEventActive) ? "active" : "idle_armed";
  } else {
    status = (openExposure || orderFlowActive || recentRealEventActive) ? "active_while_disabled" : "disabled";
  }
  return {
    status,
    configEnabled: !!uiLive.enabled,
    hardBlocked: !!liveExecutionHardBlockedReason,
    blockedReason: liveExecutionHardBlockedReason,
    blockedAtMs:
      Number.isFinite(Number(liveExecutionHardBlockedAtMs)) && Number(liveExecutionHardBlockedAtMs) > 0
        ? Number(liveExecutionHardBlockedAtMs)
        : null,
    blockedSource: liveExecutionHardBlockedSource || null,
    openExposure,
    orderFlowActive,
    unexpectedWhileDisabled: !uiLive.enabled && (openExposure || orderFlowActive || recentRealEventActive),
    recentRealEventMs,
    recentRealEventAgeMs: Number.isFinite(Number(recentRealEventAgeMs)) ? Number(recentRealEventAgeMs) : null,
    recentRealEventKind: lastRealLiveExecutionEvent || null,
    recentRealEventInstanceId: lastRealLiveExecutionInstanceId || null,
    recentRealEventRunNum:
      Number.isFinite(Number(lastRealLiveExecutionRunNum)) && Number(lastRealLiveExecutionRunNum) > 0
        ? Number(lastRealLiveExecutionRunNum)
        : null,
    recentRealEventSlug: lastRealLiveExecutionSlug || null,
    activityWindowMs: LIVE_EXECUTION_ACTIVITY_WINDOW_MS,
    hostLiveState: {
      entered: hostOpenExposure,
      side: stLive.side ?? null,
      shares: Number.isFinite(Number(stLive.shares)) ? Number(stLive.shares) : null,
      tpOrderId: String(stLive.tpOrderId || "").trim() || null,
    },
    botRuntimeState: {
      activeBotCount: liveBots.length,
      openExposureCount: liveBots.filter((b) => {
        const rt = botRuntimes.get(b.instanceId);
        return !!rt && !!rt.entered && (rt.side === "UP" || rt.side === "DOWN");
      }).length,
      orderFlowCount: liveBots.filter((b) => {
        const rtAny = botRuntimes.get(b.instanceId) as any;
        return !!rtAny && (
          !!rtAny.enterInFlight ||
          !!rtAny.exitInFlight ||
          !!rtAny.tpOrderInFlight ||
          !!String(rtAny.tpOrderId || "").trim()
        );
      }).length,
    },
  };
}

function writeRuntimeStateSnapshot() {
  try {
    ensureTradeLogDir();
    const payload = {
      savedAtMs: nowMs(),
      savedAtIso: isoNow(),
      runtimeVersion: LIVEFIX_RUNTIME_VERSION,
      current,
      uiPaper,
      uiLive,
      pendingUiLive,
      liveManualEnabledOverride,
      liveExecutionBlock: {
        reason: liveExecutionHardBlockedReason,
        atMs: liveExecutionHardBlockedAtMs,
        source: liveExecutionHardBlockedSource,
      },
      paperAccount,
      liveAccount,
      stPaper,
      stLive,
      entryGuard: {
        entryBlockActive,
        entryBlockedSessionSlug,
      },
    };
    fs.writeFileSync(RUNTIME_SNAPSHOT_PATH, JSON.stringify(payload, null, 2) + "\n");
  } catch (e: any) {
    console.warn(`[SNAPSHOT WRITE ERROR] ${String(e?.message ?? e)}`);
  }
}

function loadRuntimeStateSnapshot() {
  try {
    const snapshotPath = fs.existsSync(RUNTIME_SNAPSHOT_PATH)
      ? RUNTIME_SNAPSHOT_PATH
      : fs.existsSync(LEGACY_RUNTIME_SNAPSHOT_PATH)
      ? LEGACY_RUNTIME_SNAPSHOT_PATH
      : "";
    if (!snapshotPath) return false;
    const raw = fs.readFileSync(snapshotPath, "utf8");
    const parsed = JSON.parse(raw || "{}");
    if (!parsed || typeof parsed !== "object") return false;

    // On fresh-paper starts, keep paper UI defaults from code instead of
    // reviving older per-run paper values from snapshot.
    if (!PAPER_RESET_ON_START) {
      if (parsed.uiPaper && typeof parsed.uiPaper === "object") uiPaper = { ...uiPaper, ...parsed.uiPaper, mode: "paper", enabled: true };
    }
    // Live-engine enablement must survive restarts even when paper mode starts
    // fresh; otherwise a restart can silently flip live trading off/on.
    if (parsed.uiLive && typeof parsed.uiLive === "object") uiLive = { ...uiLive, ...parsed.uiLive, mode: "live" };
    if (parsed.pendingUiLive && typeof parsed.pendingUiLive === "object") pendingUiLive = { ...uiLive, ...parsed.pendingUiLive, mode: "live" };
    if (typeof parsed.liveManualEnabledOverride === "boolean") liveManualEnabledOverride = parsed.liveManualEnabledOverride;
    if (parsed.liveExecutionBlock && typeof parsed.liveExecutionBlock === "object") {
      liveExecutionHardBlockedReason = normalizeLiveVenueErrorText((parsed.liveExecutionBlock as any).reason) || null;
      liveExecutionHardBlockedSource = String((parsed.liveExecutionBlock as any).source || "").trim() || null;
      liveExecutionHardBlockedAtMs = Number.isFinite(Number((parsed.liveExecutionBlock as any).atMs))
        ? Number((parsed.liveExecutionBlock as any).atMs)
        : null;
    }

    if (!PAPER_RESET_ON_START && parsed.paperAccount && Number.isFinite(Number(parsed.paperAccount.balanceUsd))) {
      paperAccount.balanceUsd = Number(parsed.paperAccount.balanceUsd);
    }
    if (parsed.liveAccount && Number.isFinite(Number(parsed.liveAccount.balanceUsd))) {
      liveAccount.balanceUsd = Number(parsed.liveAccount.balanceUsd);
    }

    if (!PAPER_RESET_ON_START && parsed.stPaper && typeof parsed.stPaper === "object") stPaper = { ...stPaper, ...parsed.stPaper };
    if (parsed.stLive && typeof parsed.stLive === "object") stLive = { ...stLive, ...parsed.stLive };
    clearEntryLatency(stPaper);
    clearExitLatency(stPaper);
    clearEntryLatency(stLive);
    clearExitLatency(stLive);

    if (parsed.current && typeof parsed.current === "object") {
      current = {
        slug: String(parsed.current.slug || current.slug),
        startMs: Number(parsed.current.startMs || current.startMs),
        endMs: Number(parsed.current.endMs || current.endMs),
        upToken: String(parsed.current.upToken || current.upToken),
        downToken: String(parsed.current.downToken || current.downToken),
        volumeUsd: Number.isFinite(Number(parsed.current.volumeUsd)) ? Number(parsed.current.volumeUsd) : current.volumeUsd,
      };
      // Snapshot tokens can be stale across process restarts and cause prolonged
      // 404 orderbook fetches / stale feed state until natural rollover.
      // Force immediate fresh market bootstrap on startup.
      current.slug = "";
      current.startMs = 0;
      current.endMs = 0;
      current.upToken = "";
      current.downToken = "";
    }

    // Do not restore entry-guard from snapshot; each process start must re-arm
    // against the first observed session to prevent mid-session fresh entries.
    entryBlockActive = true;
    entryBlockedSessionSlug = null;
    // Never resume pending entry orders across process restarts.
    clearPendingEntry(stPaper);
    clearPendingEntry(stLive);
    stPaper.buyAttemptedThisSession = false;
    stPaper.buyAttemptedSessionSlug = null;
    stLive.buyAttemptedThisSession = false;
    stLive.buyAttemptedSessionSlug = null;

    if (PAPER_RESET_ON_START) {
      if (RESUMED_EXISTING_RUN) {
        const restoredBalance = restorePaperBalanceFromTradeLogs(SERVER_RUN_ID);
        resetPaperForNewRun();
        if (Number.isFinite(Number(restoredBalance))) {
          paperAccount.balanceUsd = Number(restoredBalance);
          stPaper.balanceUsd = Number(restoredBalance);
          console.log(
            `[PAPER RESTORE] resumed runId=${SERVER_RUN_ID} restored balance=${Number(restoredBalance).toFixed(4)} from trade logs`
          );
        } else {
          console.log(
            `[PAPER RESTORE] resumed runId=${SERVER_RUN_ID} had no recoverable balance; using fresh balance=100.00`
          );
        }
      } else {
        resetPaperForNewRun();
        console.log(`[PAPER RESET] fresh run: balance=100.00 (snapshot paper state ignored)`);
      }
    }

    uiPaper.enabled = true;
    stPaper.balanceUsd = paperAccount.balanceUsd;
    const baseLane = { ...stPaper };
    const hcLane: TradeState = {
      ...stPaper,
      entered: false,
      exited: false,
      side: null,
      entryTsMs: null,
      exitTsMs: null,
      entryPx: null,
      exitPx: null,
      shares: null,
      notionalUsd: null,
      grossPnlUsd: null,
      entryFeeUsd: null,
      exitFeeUsd: null,
      totalFeesUsd: null,
      pnlUsd: null,
      roiPct: null,
      holdSec: null,
      stopFallbackTriggered: false,
      positionTokenId: null,
      buyFilledThisSession: false,
      pendingEntryMode: null,
      pendingEntrySubtype: null,
      entryMode: null,
      entrySubtype: null,
    };
    paperLaneStates.BASE = baseLane;
    paperLaneStates.NO_CROSS_WINNER = hcLane;
    clearPendingEntry(paperLaneStates.BASE);
    clearPendingEntry(paperLaneStates.NO_CROSS_WINNER);
    syncPaperAggregateState();
    if (liveAccount.balanceUsd != null) stLive.balanceUsd = liveAccount.balanceUsd;
    console.log(
      `[SNAPSHOT LOADED] path=${snapshotPath} paperBal=${paperAccount.balanceUsd.toFixed(2)} ` +
        `liveBal=${liveAccount.balanceUsd ?? "—"}`
    );
    return true;
  } catch (e: any) {
    console.warn(`[SNAPSHOT LOAD ERROR] ${String(e?.message ?? e)}`);
    return false;
  }
}

function toNum(v: any): number {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function round4(n: number): number {
  return Math.round(n * 10000) / 10000;
}

