function readRunAuditCacheMeta(outJsonPath: string): { sessionCount: number; valid: boolean } {
  try {
    if (!fs.existsSync(outJsonPath)) return { sessionCount: 0, valid: false };
    const raw = fs.readFileSync(outJsonPath, "utf8");
    const parsed = JSON.parse(raw);
    const sessions = Array.isArray(parsed?.sessions) ? parsed.sessions : [];
    return { sessionCount: sessions.length, valid: true };
  } catch {
    return { sessionCount: 0, valid: false };
  }
}

function readRunAuditSourceSessionMeta(indexPath: string, eventsPath: string): { sessionCount: number; hasEvidence: boolean } {
  let indexCount = 0;
  let eventSlugCount = 0;
  try {
    if (fs.existsSync(indexPath)) {
      const indexRaw = fs.readFileSync(indexPath, "utf8");
      const indexParsed = JSON.parse(indexRaw);
      indexCount = Array.isArray(indexParsed?.sessions) ? indexParsed.sessions.length : 0;
    }
  } catch {}
  try {
    if (fs.existsSync(eventsPath)) {
      const raw = fs.readFileSync(eventsPath, "utf8");
      const seen = new Set<string>();
      for (const line of raw.split(/\r?\n/)) {
        if (!line.trim()) continue;
        try {
          const row = JSON.parse(line);
          const slug = String(row?.marketSlug || "").trim();
          if (slug) seen.add(slug);
        } catch {}
      }
      eventSlugCount = seen.size;
    }
  } catch {}
  const sessionCount = Math.max(indexCount, eventSlugCount);
  return { sessionCount, hasEvidence: sessionCount > 0 };
}

function matchesRequestedRunIdentity(summary: any, req: express.Request): { ok: boolean; reason?: string } {
  const requestedRunId = String(req.query.runId ?? "").trim();
  const requestedStartedAtMsRaw = Number(req.query.startedAtMs ?? 0);
  const requestedStartedAtMs =
    Number.isFinite(requestedStartedAtMsRaw) && requestedStartedAtMsRaw > 0
      ? Math.floor(requestedStartedAtMsRaw)
      : 0;
  const actualRunId = String(summary?.runId || "").trim();
  const actualStartedAtMsRaw = Number(summary?.startedAtMs ?? summary?.launchedAtMs ?? 0);
  const actualStartedAtMs =
    Number.isFinite(actualStartedAtMsRaw) && actualStartedAtMsRaw > 0
      ? Math.floor(actualStartedAtMsRaw)
      : 0;
  if (requestedRunId && actualRunId && requestedRunId !== actualRunId) {
    return { ok: false, reason: `runId mismatch requested=${requestedRunId} actual=${actualRunId}` };
  }
  if (requestedStartedAtMs > 0 && actualStartedAtMs > 0 && requestedStartedAtMs !== actualStartedAtMs) {
    return { ok: false, reason: `startedAtMs mismatch requested=${requestedStartedAtMs} actual=${actualStartedAtMs}` };
  }
  return { ok: true };
}

function appendRunIdentityQuery(basePath: string, summary: any, extras: Record<string, any> = {}): string {
  const params = new URLSearchParams();
  const runNum = Number(summary?.runNum ?? 0);
  if (Number.isFinite(runNum) && runNum > 0) params.set("runNum", String(Math.floor(runNum)));
  const runId = String(summary?.runId || "").trim();
  if (runId) params.set("runId", runId);
  const startedAtMsRaw = Number(summary?.startedAtMs ?? summary?.launchedAtMs ?? 0);
  if (Number.isFinite(startedAtMsRaw) && startedAtMsRaw > 0) params.set("startedAtMs", String(Math.floor(startedAtMsRaw)));
  for (const [k, v] of Object.entries(extras || {})) {
    if (v == null) continue;
    const sv = String(v).trim();
    if (sv) params.set(k, sv);
  }
  const qs = params.toString();
  return qs ? `${basePath}?${qs}` : basePath;
}

function runAuditHasSessionEvidence(indexPath: string, eventsPath: string): boolean {
  try {
    if (fs.existsSync(indexPath)) {
      const indexRaw = fs.readFileSync(indexPath, "utf8");
      const indexParsed = JSON.parse(indexRaw);
      if (Array.isArray(indexParsed?.sessions) && indexParsed.sessions.length > 0) return true;
    }
  } catch {}
  try {
    if (!fs.existsSync(eventsPath)) return false;
    const raw = fs.readFileSync(eventsPath, "utf8");
    if (!raw.trim()) return false;
    const lines = raw.split(/\r?\n/);
    for (const line of lines) {
      if (!line.trim()) continue;
      try {
        const row = JSON.parse(line);
        if (String(row?.marketSlug || "").trim()) return true;
      } catch {}
    }
  } catch {}
  return false;
}

function runSummaryClosed(summary: any): boolean {
  const status = String(summary?.status || "").trim().toLowerCase();
  if (status === "running" || status === "starting" || status === "watching") return false;
  const endedAtMs = Number(summary?.endedAtMs ?? summary?.stoppedAtMs ?? 0);
  if (Number.isFinite(endedAtMs) && endedAtMs > 0) return true;
  return status === "stopped" || status === "finished" || status === "completed" || status === "error";
}

function runAuditCacheVerified(outJsonPath: string, indexPath: string, eventsPath: string): boolean {
  const meta = readRunAuditCacheMeta(outJsonPath);
  if (!meta.valid) return false;
  const hasSessionEvidence = runAuditHasSessionEvidence(indexPath, eventsPath);
  return !hasSessionEvidence || meta.sessionCount > 0;
}

async function trimBotRunTelemetryToRecentWindow(
  runNum: number,
  keepMs: number
): Promise<{ ok: boolean; trimmed: boolean; totalRows: number; keptRows: number; newestTsMs: number | null }> {
  const telemetryPath = botRunTelemetryPath(runNum);
  if (!fs.existsSync(telemetryPath)) {
    return { ok: true, trimmed: false, totalRows: 0, keptRows: 0, newestTsMs: null };
  }

  let newestTsMs: number | null = null;
  let totalRows = 0;
  const scan = readline.createInterface({
    input: fs.createReadStream(telemetryPath, { encoding: "utf8" }),
    crlfDelay: Infinity,
  });
  for await (const line of scan) {
    const trimmed = String(line || "").trim();
    if (!trimmed) continue;
    totalRows += 1;
    try {
      const row = JSON.parse(trimmed);
      const ts = Number(row?.t);
      if (Number.isFinite(ts) && ts > 0) newestTsMs = newestTsMs == null ? ts : Math.max(newestTsMs, ts);
    } catch {}
  }

  if (!(Number.isFinite(Number(newestTsMs)) && Number(newestTsMs) > 0) || totalRows <= 1) {
    return { ok: true, trimmed: false, totalRows, keptRows: totalRows, newestTsMs };
  }

  const cutoffMs = Math.max(0, Number(newestTsMs) - Math.max(60_000, Math.floor(Number(keepMs) || 0)));
  const tmpPath = `${telemetryPath}.trim_tmp`;
  let keptRows = 0;
  try {
    const writer = fs.createWriteStream(tmpPath, { encoding: "utf8" });
    const rewrite = readline.createInterface({
      input: fs.createReadStream(telemetryPath, { encoding: "utf8" }),
      crlfDelay: Infinity,
    });
    for await (const line of rewrite) {
      const raw = String(line || "");
      const trimmed = raw.trim();
      if (!trimmed) continue;
      let keep = false;
      try {
        const row = JSON.parse(trimmed);
        const ts = Number(row?.t);
        keep = Number.isFinite(ts) ? ts >= cutoffMs : true;
      } catch {
        keep = true;
      }
      if (!keep) continue;
      keptRows += 1;
      if (!writer.write(`${trimmed}\n`)) {
        await new Promise<void>((resolve, reject) => {
          writer.once("drain", resolve);
          writer.once("error", reject);
        });
      }
    }
    await new Promise<void>((resolve, reject) => {
      writer.end(() => resolve());
      writer.once("error", reject);
    });
    if (keptRows <= 0 || keptRows >= totalRows) {
      try { fs.unlinkSync(tmpPath); } catch {}
      return { ok: true, trimmed: false, totalRows, keptRows: Math.max(keptRows, totalRows), newestTsMs };
    }
    fs.renameSync(tmpPath, telemetryPath);
    return { ok: true, trimmed: true, totalRows, keptRows, newestTsMs };
  } catch (e) {
    try { fs.unlinkSync(tmpPath); } catch {}
    throw e;
  }
}

async function trimSessionTraceLogToRecentSlugs(
  keepSlugsLike: Iterable<string>
): Promise<{ ok: boolean; trimmed: boolean; totalRows: number; keptRows: number }> {
  const keepSlugs = new Set(Array.from(keepSlugsLike || []).map((s) => String(s || "").trim()).filter(Boolean));
  const tracePath = sessionTraceLogPathForRun(SERVER_RUN_ID);
  if (!fs.existsSync(tracePath) || !keepSlugs.size) {
    return { ok: true, trimmed: false, totalRows: 0, keptRows: 0 };
  }
  let totalRows = 0;
  let keptRows = 0;
  const tmpPath = `${tracePath}.trim_tmp`;
  try {
    const writer = fs.createWriteStream(tmpPath, { encoding: "utf8" });
    const reader = readline.createInterface({
      input: fs.createReadStream(tracePath, { encoding: "utf8" }),
      crlfDelay: Infinity,
    });
    for await (const line of reader) {
      const raw = String(line || "");
      const trimmed = raw.trim();
      if (!trimmed) continue;
      totalRows += 1;
      let keep = false;
      try {
        const row = JSON.parse(trimmed);
        const slug = String(row?.slug || "").trim();
        keep = keepSlugs.has(slug);
      } catch {}
      if (!keep) continue;
      keptRows += 1;
      if (!writer.write(`${trimmed}\n`)) {
        await new Promise<void>((resolve, reject) => {
          writer.once("drain", resolve);
          writer.once("error", reject);
        });
      }
    }
    await new Promise<void>((resolve, reject) => {
      writer.end(() => resolve());
      writer.once("error", reject);
    });
    if (keptRows <= 0 || keptRows >= totalRows) {
      try { fs.unlinkSync(tmpPath); } catch {}
      return { ok: true, trimmed: false, totalRows, keptRows: Math.max(keptRows, totalRows) };
    }
    fs.renameSync(tmpPath, tracePath);
    return { ok: true, trimmed: true, totalRows, keptRows };
  } catch (e) {
    try { fs.unlinkSync(tmpPath); } catch {}
    throw e;
  }
}

function scheduleBotRunRetentionCleanup(instance: BotInstance): void {
  try {
    if (!isRealLiveCapableBotInstance(instance)) return;
    const runNum = Math.floor(Number(instance?.runNum));
    if (!(Number.isFinite(runNum) && runNum > 0)) return;
    const cleanupKey = `${runNum}`;
    const prior = BOT_RUN_RETENTION_CLEANUP_TIMERS.get(cleanupKey);
    if (prior) clearTimeout(prior);
    const timer = setTimeout(() => {
      BOT_RUN_RETENTION_CLEANUP_TIMERS.delete(cleanupKey);
      if (BOT_RUN_RETENTION_CLEANUP_INFLIGHT.has(cleanupKey)) return;
      BOT_RUN_RETENTION_CLEANUP_INFLIGHT.add(cleanupKey);
      setImmediate(() => {
        const finish = () => BOT_RUN_RETENTION_CLEANUP_INFLIGHT.delete(cleanupKey);
        Promise.resolve()
          .then(async () => {
            const telemetryPath = botRunTelemetryPath(runNum);
            try {
              const stat = fs.existsSync(telemetryPath) ? fs.statSync(telemetryPath) : null;
              if (stat && Number(stat.size || 0) > BOT_RUN_TELEMETRY_MAX_BYTES) {
                await trimBotRunTelemetryToRecentWindow(runNum, BOT_RUN_TELEMETRY_KEEP_MS);
              }
            } catch {}

            const keepSlugs = new Set<string>();
            try {
              const indexPath = botRunIndexPath(String(instance?.strategyId || ""), runNum);
              if (fs.existsSync(indexPath)) {
                const index = JSON.parse(fs.readFileSync(indexPath, "utf8"));
                const sessions = Array.isArray(index?.sessions) ? index.sessions.slice() : [];
                sessions.sort((a, b) => {
                  const aMs = Number(a?.endMs || a?.lastTsMs || a?.startMs || 0);
                  const bMs = Number(b?.endMs || b?.lastTsMs || b?.startMs || 0);
                  return bMs - aMs;
                });
                for (const sess of sessions.slice(0, SESSION_TRACE_RAW_KEEP_RECENT_SLUGS)) {
                  const slug = String(sess?.slug || "").trim();
                  if (slug) keepSlugs.add(slug);
                }
              }
            } catch {}
            const activeSlug = String(instance?.marketSlug || "").trim();
            if (activeSlug) keepSlugs.add(activeSlug);
            if (keepSlugs.size > 0) {
              try { await trimSessionTraceLogToRecentSlugs(keepSlugs); } catch {}
              for (const slug of Array.from(sessionTraceMem.keys())) {
                if (keepSlugs.has(String(slug || "").trim())) continue;
                sessionTraceMem.delete(slug);
                lastSessionTraceWriteMsBySlug.delete(slug);
              }
            }
          })
          .finally(finish);
      });
    }, BOT_RUN_RETENTION_CLEANUP_DEBOUNCE_MS);
    BOT_RUN_RETENTION_CLEANUP_TIMERS.set(cleanupKey, timer);
  } catch {}
}

function maybeTrimRunTelemetryAfterVerifiedAudit(runNum: number, summary: any, outJsonPath: string, indexPath: string, eventsPath: string): void {
  if (!(Number.isFinite(Number(runNum)) && Number(runNum) > 0)) return;
  if (!runSummaryClosed(summary)) return;
  if (!runAuditCacheVerified(outJsonPath, indexPath, eventsPath)) return;
  const telemetryPath = botRunTelemetryPath(runNum);
  if (!fs.existsSync(telemetryPath)) return;
  const trimKey = `${Math.floor(Number(runNum))}`;
  if (RUN_AUDIT_TELEMETRY_TRIM_INFLIGHT.has(trimKey)) return;
  RUN_AUDIT_TELEMETRY_TRIM_INFLIGHT.add(trimKey);
  setImmediate(() => {
    void trimBotRunTelemetryToRecentWindow(Math.floor(Number(runNum)), RUN_AUDIT_TELEMETRY_KEEP_MS)
      .then((result) => {
        if (result.trimmed) {
          logInfo(
            `[RUN AUDIT] trimmed telemetry run=${runNum} keptRows=${result.keptRows}/${result.totalRows} keepMs=${RUN_AUDIT_TELEMETRY_KEEP_MS}`
          );
        }
      })
      .catch((err: any) => {
        logWarn(`[RUN AUDIT] telemetry trim skipped run=${runNum} err=${String(err?.message ?? err)}`);
      })
      .finally(() => {
        RUN_AUDIT_TELEMETRY_TRIM_INFLIGHT.delete(trimKey);
      });
  });
}

function scheduleRunAuditWarmRefresh(instance: BotInstance): void {
  try {
    void instance;
    return;
  } catch {}
}

function closedSessionsForMaterialization(sessionsLike: any[]): any[] {
  return (Array.isArray(sessionsLike) ? sessionsLike : [])
    .map((row: any) => ({ ...(row || {}) }))
    .filter((row: any) => {
      const slug = String(row?.slug || "").trim();
      if (!slug) return false;
      const closed = row?.closed === true || Number.isFinite(Number(row?.exitTsMs)) || Number.isFinite(Number(row?.endMs));
      return !!closed;
    })
    .sort((a: any, b: any) => {
      const ta = Number(a?.exitTsMs ?? a?.endMs ?? a?.entryTsMs ?? a?.startMs ?? 0);
      const tb = Number(b?.exitTsMs ?? b?.endMs ?? b?.entryTsMs ?? b?.startMs ?? 0);
      return tb - ta;
    });
}

function buildClosedSessionMaterializationPayload(
  instance: BotInstance,
  runNum: number,
  slug: string
): any | null {
  const payload = buildCompactSessionHistoryResponseFromRunIndex(instance, {
    engine: "paper",
    runNum,
    sinceStart: 0,
    includeTrace: false,
    marketSlugFilter: slug.toLowerCase(),
    marketPrefixFilter: "",
    maxSessions: 1,
    offset: 0,
    includeIncompleteClosedSessions: true,
  });
  const session = Array.isArray(payload?.sessions) && payload.sessions.length ? payload.sessions[0] : null;
  if (!(session && String(session?.slug || "").trim() === slug)) return null;
  const exactTrace = readRecordedServerSessionFullTraceForSlug(
    slug,
    session,
    Number.isFinite(Number(instance?.runId)) ? Number(instance.runId) : null
  );
  const eventFallbackTrace = !exactTrace
    ? buildHistoricalCardTraceFromEventDecisionSnapshots(runNum, slug, session)
    : null;
  const rawRecordedTrace = readRecordedServerSessionRawTraceForSlug(
    slug,
    session,
    Number.isFinite(Number(instance?.runId)) ? Number(instance.runId) : null
  );
  const canonicalTrace = chooseCanonicalRunAuditTrace(slug)?.trace || null;
  const chosenTrace = choosePreferredSessionTrace(canonicalTrace, exactTrace, eventFallbackTrace);
  const healthTrace = rawRecordedTrace || canonicalTrace || eventFallbackTrace;
  if (chosenTrace) {
    session.trace = chosenTrace;
    session.traceSource = String((chosenTrace as any)?.source || "session_trace_runlog");
  }
  session.streamSampleWindow = buildSessionStreamWindowSummary(healthTrace, session, {
    windowStartSec: 10,
    windowEndSec: 70,
    targetGapMs: 25,
  });
  session.streamEndSnapshot = buildSessionEndSnapshotSummary(healthTrace, session, {
    recentGapCount: 500,
    thresholdGapMs: [25, 50, 75, 100, 125, 150],
  });
  return session;
}

function scheduleClosedSessionCanonicalArtifactMaterialization(instance: BotInstance, sessionsLike: any[]): void {
  try {
    if (HOT_SERVICE_MODE) return;
    if (!instance || typeof instance !== "object") return;
    const runNum = Math.floor(Number(instance?.runNum));
    if (!(Number.isFinite(runNum) && runNum > 0)) return;
    // Keep hot-mode preservation off the critical path in practice by only
    // scheduling the newest eligible closed session per refresh. Older sessions
    // can still be rebuilt on demand through the repair/read APIs.
    const sessions = closedSessionsForMaterialization(sessionsLike).slice(0, 1);
    for (const row of sessions) {
      const slug = String(row?.slug || "").trim();
      if (!slug) continue;
      const cacheKey = `canonical:${runNum}:${slug}`;
      const prior = CLOSED_SESSION_CANONICAL_MATERIALIZE_TIMERS.get(cacheKey);
      if (prior) clearTimeout(prior);
      const timer = setTimeout(() => {
        CLOSED_SESSION_CANONICAL_MATERIALIZE_TIMERS.delete(cacheKey);
        try {
          const session = buildClosedSessionMaterializationPayload(instance, runNum, slug);
          if (!session) return;
          writeCanonicalSessionArtifacts(runNum, slug, session);
        } catch {}
      }, CLOSED_SESSION_CARD_MATERIALIZE_DEBOUNCE_MS);
      CLOSED_SESSION_CANONICAL_MATERIALIZE_TIMERS.set(cacheKey, timer);
    }
  } catch {}
}

function scheduleClosedSessionCardMaterialization(instance: BotInstance, sessionsLike: any[]): void {
  try {
    if (!SESSION_CARD_MATERIALIZE_ENABLED) return;
    if (!instance || typeof instance !== "object") return;
    const runNum = Math.floor(Number(instance?.runNum));
    if (!(Number.isFinite(runNum) && runNum > 0)) return;
    const strategyId = String(instance?.strategyId || "").trim();
    if (!strategyId) return;
    const idxPath = botRunIndexPath(strategyId, runNum);
    const sourceSig = fileCacheSignature(idxPath);
    const sessions = closedSessionsForMaterialization(sessionsLike);
    for (const row of sessions) {
      const slug = String(row?.slug || "").trim();
      if (!slug) continue;
      const cacheKey = `${runNum}:${slug}`;
      const prior = CLOSED_SESSION_CARD_MATERIALIZE_TIMERS.get(cacheKey);
      if (prior) clearTimeout(prior);
      const timer = setTimeout(() => {
        CLOSED_SESSION_CARD_MATERIALIZE_TIMERS.delete(cacheKey);
        try {
          const hasCanonicalArtifacts =
            fs.existsSync(canonicalSessionHighFidelityPath(slug)) &&
            fs.existsSync(canonicalSessionLowFidelityPath(slug)) &&
            fs.existsSync(canonicalSessionTradeLogPath(slug)) &&
            fs.existsSync(canonicalSessionHealthPath(slug));
          const existing = readSessionCardArtifact(runNum, slug, true, sourceSig);
          if (
            hasCanonicalArtifacts &&
            existing &&
            String(existing?.slug || "").trim() === slug &&
            !sessionCardArtifactNeedsRecordedTrace(existing) &&
            !sessionCardArtifactNeedsStreamWindowSummary(existing) &&
            !sessionCardArtifactNeedsStreamEndSnapshot(existing)
          ) {
            // The cached artifact is already current for this run-index signature.
          } else {
            const session = buildClosedSessionMaterializationPayload(instance, runNum, slug);
            if (session && String(session?.slug || "").trim() === slug) {
              const compact = readSessionAuditCompact(runNum, slug);
              const accountingTrace = session.trace || null;
              const corrected =
                buildCorrectedSessionAccountingFromCompact(session, compact, accountingTrace)
                || buildCorrectedSessionAccountingFromEvents(runNum, slug, accountingTrace);
              if (corrected) {
                session.actualPnlUsd = corrected.actualNetPnlUsd;
                session.actualGrossPnlUsd = corrected.actualGrossPnlUsd;
                session.actualFeesUsd = corrected.actualFeesUsd;
                session.correctedPnlUsd = corrected.correctedNetPnlUsd;
                session.correctedGrossPnlUsd = corrected.correctedGrossPnlUsd;
                session.correctedFeesUsd = corrected.correctedFeesUsd;
                session.correctedDeltaUsd = corrected.correctedDeltaUsd;
                session.projectedFillNetPnlUsd = corrected.projectedFillNetPnlUsd;
                session.settleNetPnlUsd = corrected.settleNetPnlUsd;
                session.correctedExitStrategy = corrected.correctedExitStrategy;
                session.pnlUsd = corrected.correctedNetPnlUsd;
                session.grossPnlUsd = corrected.correctedGrossPnlUsd;
                session.feesUsd = corrected.correctedFeesUsd;
              }
              writeSessionCardArtifact(runNum, slug, session, sourceSig);
            }
          }
        } catch {}
      }, CLOSED_SESSION_CARD_MATERIALIZE_DEBOUNCE_MS);
      CLOSED_SESSION_CARD_MATERIALIZE_TIMERS.set(cacheKey, timer);
    }
  } catch {}
}

function latestClosedSessionInfoFromSessions(sessionsLike: any[]): { slug: string; tsMs: number } {
  const rows = (Array.isArray(sessionsLike) ? sessionsLike : [])
    .map((row: any) => ({ ...(row || {}) }))
    .filter((row: any) => {
      const slug = String(row?.slug || "").trim();
      if (!slug) return false;
      return row?.closed === true || Number.isFinite(Number(row?.exitTsMs)) || Number.isFinite(Number(row?.endMs));
    })
    .map((row: any) => ({
      slug: String(row?.slug || "").trim(),
      tsMs: Number(row?.exitTsMs ?? row?.endMs ?? row?.entryTsMs ?? row?.startMs ?? 0),
    }))
    .filter((row: any) => row.slug && Number.isFinite(row.tsMs))
    .sort((a: any, b: any) => b.tsMs - a.tsMs);
  return rows[0] || { slug: "", tsMs: 0 };
}

function latestClosedSessionInfoForParity(instance: BotInstance, sessionsLike: any[] = []): { slug: string; tsMs: number } {
  try {
    const candidates = [
      latestClosedSessionInfoFromSessions(sessionsLike),
      ...(
        HOT_SERVICE_MODE
          ? []
          : [latestClosedSessionInfoFromSessions(buildContinuitySessionsForInstance(instance, false, 12).sessions || [])]
      ),
    ].filter((row) => row.slug && Number.isFinite(row.tsMs));
    candidates.sort((a, b) => b.tsMs - a.tsMs);
    return candidates[0] || { slug: "", tsMs: 0 };
  } catch {
    return { slug: "", tsMs: 0 };
  }
}

function isSessionParityEligibleInstance(instance: Pick<BotInstance, "instanceId" | "runNum" | "marketSlug" | "strategyId" | "watchOnly"> | null | undefined): boolean {
  if (!instance || instance.watchOnly) return false;
  const runNum = Math.floor(Number(instance.runNum));
  return (
    Number.isFinite(runNum) &&
    runNum > 0 &&
    !!String(instance.instanceId || "").trim() &&
    !!String(instance.marketSlug || "").trim() &&
    !!String(instance.strategyId || "").trim()
  );
}

function readSessionParityArtifactSummary(runNum: number): {
  latestSlug: string;
  latestOk: boolean;
  latestPartial: boolean;
  latestGeneratedAtMs: number;
  goodSlug: string;
  goodOk: boolean;
} {
  const summary = {
    latestSlug: "",
    latestOk: false,
    latestPartial: false,
    latestGeneratedAtMs: 0,
    goodSlug: "",
    goodOk: false,
  };
  try {
    const latestPath = botRunSessionParityJsonPath(runNum);
    if (fs.existsSync(latestPath)) {
      const payload = JSON.parse(fs.readFileSync(latestPath, "utf8"));
      summary.latestSlug = String(payload?.slug || "").trim();
      summary.latestOk = payload?.ok === true;
      summary.latestPartial =
        String(payload?.status || "").trim().toLowerCase() === "partial" ||
        ((Array.isArray(payload?.warnings) ? payload.warnings.length : 0) > 0);
      summary.latestGeneratedAtMs = Number(fs.statSync(latestPath).mtimeMs || 0);
    }
  } catch {}
  try {
    const goodPath = botRunSessionParityGoodJsonPath(runNum);
    if (fs.existsSync(goodPath)) {
      const payload = JSON.parse(fs.readFileSync(goodPath, "utf8"));
      summary.goodSlug = String(payload?.slug || "").trim();
      summary.goodOk = payload?.ok === true && String(payload?.status || "").trim().toLowerCase() === "ok";
    }
  } catch {}
  return summary;
}

function scheduleSessionParityWarmRefresh(instance: BotInstance, sessionsLike: any[]): void {
  try {
    if (!SESSION_PARITY_ENABLED) return;
    if (!isSessionParityEligibleInstance(instance)) return;
    if (!isSessionParityAllowedForActiveWindow()) return;
    const runNum = Math.floor(Number(instance?.runNum));
    if (!(Number.isFinite(runNum) && runNum > 0)) return;
    const slug = latestClosedSessionInfoForParity(instance, sessionsLike).slug;
    if (!slug) return;
    const parityScriptPath = sessionParityScriptPath();
    if (!parityScriptPath) return;
    const cacheKey = sessionParityRebuildKey(runNum, slug);
    const prior = SESSION_PARITY_WARM_TIMERS.get(cacheKey);
    if (prior) clearTimeout(prior);
    const timer = setTimeout(() => {
      SESSION_PARITY_WARM_TIMERS.delete(cacheKey);
      if (!isSessionParityAllowedForActiveWindow()) return;
      if (SESSION_PARITY_REBUILD_INFLIGHT.has(cacheKey)) return;
      SESSION_PARITY_REBUILD_INFLIGHT.add(cacheKey);
      const pyBin = String(process.env.PYTHON_BIN || "python3").trim() || "python3";
      const args = buildSessionParityArgs(instance, slug);
      const child = spawn(pyBin, args, {
        cwd: process.cwd(),
        detached: true,
        stdio: "ignore",
      });
      child.on("error", () => {
        SESSION_PARITY_REBUILD_INFLIGHT.delete(cacheKey);
      });
      child.on("exit", () => {
        SESSION_PARITY_REBUILD_INFLIGHT.delete(cacheKey);
      });
      child.unref();
    }, SESSION_PARITY_WARM_DEBOUNCE_MS);
    SESSION_PARITY_WARM_TIMERS.set(cacheKey, timer);
  } catch {}
}

function latestClosedSessionSlugForParity(instance: BotInstance): string {
  try {
    const runNum = Math.floor(Number(instance?.runNum));
    const strategyId = String(instance?.strategyId || "").trim();
    let sessions: any[] = [];
    if (Number.isFinite(runNum) && runNum > 0 && strategyId) {
      const idxPath = botRunIndexPath(strategyId, runNum);
      if (fs.existsSync(idxPath)) {
        const idx = JSON.parse(fs.readFileSync(idxPath, "utf8"));
        sessions = Array.isArray(idx?.sessions) ? idx.sessions : [];
      }
    }
    return latestClosedSessionInfoForParity(instance, sessions).slug;
  } catch {
    return "";
  }
}

function isSessionParityAllowedForActiveWindow(): boolean {
  try {
    // Keep parity work away from most of the live session so the trading loop
    // only pays this cost during the short comparison window we care about.
    const startMs = Number(current?.startMs);
    if (!(Number.isFinite(startMs) && startMs > 0)) return false;
    const elapsedMs = Math.max(0, nowMs() - startMs);
    return elapsedMs >= SESSION_PARITY_ACTIVE_ALLOW_START_MS && elapsedMs <= SESSION_PARITY_ACTIVE_ALLOW_END_MS;
  } catch {
    return false;
  }
}

function sessionParityScriptPath(): string {
  const parityScriptCandidates = [
    path.resolve(process.cwd(), "tools_ohio_dublin_session_window_parity.py"),
    path.resolve(process.cwd(), "src", "tools_ohio_dublin_session_window_parity.py"),
  ];
  return parityScriptCandidates.find((p) => fs.existsSync(p)) || "";
}

function sessionParityRebuildKey(runNum: number, slug: string): string {
  const safeRunNum = Number.isFinite(runNum) ? Math.floor(runNum) : 0;
  return `${safeRunNum}:${String(slug || "").trim()}`;
}

function buildSessionParityArgs(instance: BotInstance, slug: string): string[] {
  const runNum = Math.floor(Number(instance?.runNum));
  const outDir = botRunSessionParityDir(runNum);
  const args = [
    sessionParityScriptPath(),
    "--slug", slug,
    "--ohio-base", SESSION_PARITY_OHIO_BASE_URL,
    "--ohio-instance-id", String(instance?.instanceId || ""),
    "--out-dir", outDir,
  ];
  if (SESSION_PARITY_DUBLIN_BASE_URL) {
    args.push("--dublin-base", SESSION_PARITY_DUBLIN_BASE_URL);
  }
  if (SESSION_PARITY_DUBLIN_SSH_HOST) {
    args.push("--dublin-ssh-host", SESSION_PARITY_DUBLIN_SSH_HOST);
  }
  if (SESSION_PARITY_DUBLIN_SSH_USER) {
    args.push("--dublin-ssh-user", SESSION_PARITY_DUBLIN_SSH_USER);
  }
  if (SESSION_PARITY_DUBLIN_SSH_KEY) {
    args.push("--dublin-ssh-key", SESSION_PARITY_DUBLIN_SSH_KEY);
  }
  return args;
}

function enrichSessionParityLanesWithSignals(instance: BotInstance | null, slug: string, lanesLike: any[]): any[] {
  const lanes = Array.isArray(lanesLike) ? lanesLike.map((lane) => ({ ...(lane || {}) })) : [];
  const runNum = Math.floor(Number(instance?.runNum));
  const instanceId = String(instance?.instanceId || "").trim();
  if (!(Number.isFinite(runNum) && runNum > 0) || !slug || !lanes.length) return lanes;
  let rows: any[] = [];
  try {
    rows = readBotRunEventsCached(runNum).filter((row: any) => {
      const rowSlug = String(row?.marketSlug || "").trim();
      const rowInstanceId = String(row?.instanceId || "").trim();
      if (rowSlug !== slug) return false;
      if (instanceId && rowInstanceId && rowInstanceId !== instanceId) return false;
      return true;
    });
  } catch {
    return lanes;
  }
  const signalsBySide = new Map<string, any[]>();
  const ordersBySide = new Map<string, any[]>();
  for (const row of rows) {
    const side = String(row?.side || row?.st?.side || "").trim().toUpperCase();
    if (!(side === "UP" || side === "DOWN")) continue;
    const action = String(row?.action || row?.event || "").trim().toLowerCase();
    if (action === "enter_signal") {
      const arr = signalsBySide.get(side) || [];
      arr.push(row);
      signalsBySide.set(side, arr);
    } else if (action === "enter_order") {
      const arr = ordersBySide.get(side) || [];
      arr.push(row);
      ordersBySide.set(side, arr);
    }
  }
  for (const arr of signalsBySide.values()) arr.sort((a, b) => Number(a?.t || 0) - Number(b?.t || 0));
  for (const arr of ordersBySide.values()) arr.sort((a, b) => Number(a?.t || 0) - Number(b?.t || 0));
  const usedSignals = new Set<any>();
  const usedOrders = new Set<any>();
  const laneMetaByEntryKey = new Map<string, {
    signalTsMs?: number;
    signalPx?: number;
    attemptTsMs?: number;
    intendedPx?: number;
    decisionWindow?: any;
  }>();
  const entryKeyOf = (sideRaw: any, entryTsMsRaw: any): string => {
    const side = String(sideRaw || "").trim().toUpperCase();
    const entryTsMs = Number(entryTsMsRaw);
    if (!(side === "UP" || side === "DOWN") || !Number.isFinite(entryTsMs)) return "";
    return `${side}|${Math.floor(entryTsMs)}`;
  };
  const pickNearestBefore = (rowsLike: any[], entryTsMs: number, maxLeadMs: number): any | null => {
    let best: any | null = null;
    let bestDelta = Number.POSITIVE_INFINITY;
    for (const row of rowsLike) {
      if (usedSignals.has(row) || usedOrders.has(row)) continue;
      const tsMs = Number(row?.t ?? row?.signalTsMs ?? NaN);
      if (!Number.isFinite(tsMs) || tsMs > entryTsMs) continue;
      const delta = entryTsMs - tsMs;
      if (delta < 0 || delta > maxLeadMs) continue;
      if (delta < bestDelta) {
        best = row;
        bestDelta = delta;
      }
    }
    return best;
  };
  return lanes.map((lane) => {
    const next = { ...lane };
    const side = String(next?.side || "").trim().toUpperCase();
    const entryTsMs = Number(next?.entryTsMs);
    if (!(side === "UP" || side === "DOWN") || !Number.isFinite(entryTsMs)) return next;
    const entryKey = entryKeyOf(side, entryTsMs);
    const cachedMeta = entryKey ? laneMetaByEntryKey.get(entryKey) : null;
    if (cachedMeta) {
      if (Number.isFinite(Number(cachedMeta.signalTsMs))) next.signalTsMs = Number(cachedMeta.signalTsMs);
      if (Number.isFinite(Number(cachedMeta.signalPx))) next.signalPx = Number(cachedMeta.signalPx);
      if (Number.isFinite(Number(cachedMeta.attemptTsMs))) next.attemptTsMs = Number(cachedMeta.attemptTsMs);
      if (Number.isFinite(Number(cachedMeta.intendedPx))) next.intendedPx = Number(cachedMeta.intendedPx);
      if (cachedMeta.decisionWindow) next.decisionWindow = cloneJsonLike(cachedMeta.decisionWindow, null);
      return next;
    }
    const meta: {
      signalTsMs?: number;
      signalPx?: number;
      attemptTsMs?: number;
      intendedPx?: number;
      decisionWindow?: any;
    } = {};
    const signalRow = pickNearestBefore(signalsBySide.get(side) || [], entryTsMs, 30_000);
    if (signalRow) {
      usedSignals.add(signalRow);
      const signalTsMs = toFiniteOrNull(signalRow?.t ?? signalRow?.signalTsMs);
      const signalPx = toFiniteOrNull(signalRow?.signalPx ?? signalRow?.execution?.signalPx ?? signalRow?.entryPx);
      if (Number.isFinite(Number(signalTsMs))) {
        next.signalTsMs = Number(signalTsMs);
        meta.signalTsMs = Number(signalTsMs);
      }
      if (Number.isFinite(Number(signalPx))) {
        next.signalPx = Number(signalPx);
        meta.signalPx = Number(signalPx);
      }
      const decisionWindow = extractDecisionWindowFromSnapshot(signalRow?.decisionSnapshot, side);
      if (decisionWindow) {
        next.decisionWindow = cloneJsonLike(decisionWindow, null);
        meta.decisionWindow = cloneJsonLike(decisionWindow, null);
      }
    }
    const orderRow = pickNearestBefore(ordersBySide.get(side) || [], entryTsMs, 15_000);
    if (orderRow) {
      usedOrders.add(orderRow);
      const orderTsMs = toFiniteOrNull(orderRow?.t);
      const signalPx = toFiniteOrNull(orderRow?.signalPx ?? orderRow?.execution?.signalPx);
      const intendedPx = toFiniteOrNull(orderRow?.buyOrderPx ?? orderRow?.limitPx ?? orderRow?.execution?.intendedPx);
      if (Number.isFinite(Number(orderTsMs))) {
        next.attemptTsMs = Number(orderTsMs);
        meta.attemptTsMs = Number(orderTsMs);
      }
      if (!Number.isFinite(Number(next.signalTsMs)) && Number.isFinite(Number(orderTsMs))) {
        next.signalTsMs = Number(orderTsMs);
        meta.signalTsMs = Number(orderTsMs);
      }
      if (!Number.isFinite(Number(next.signalPx)) && Number.isFinite(Number(signalPx))) {
        next.signalPx = Number(signalPx);
        meta.signalPx = Number(signalPx);
      }
      if (Number.isFinite(Number(intendedPx))) {
        next.intendedPx = Number(intendedPx);
        meta.intendedPx = Number(intendedPx);
      }
      if (!next.decisionWindow) {
        const decisionWindow = extractDecisionWindowFromSnapshot(orderRow?.decisionSnapshot, side);
        if (decisionWindow) {
          next.decisionWindow = cloneJsonLike(decisionWindow, null);
          meta.decisionWindow = cloneJsonLike(decisionWindow, null);
        }
      }
    }
    if (entryKey && Object.keys(meta).length) laneMetaByEntryKey.set(entryKey, meta);
    return next;
  });
}

function ensureLatestSessionParityArtifact(
  runNum: number,
  opts: { force?: boolean; allowSpawn?: boolean } = {}
): { stale: boolean; latestClosedSlug: string } {
  try {
    if (!SESSION_PARITY_ENABLED) return { stale: false, latestClosedSlug: "" };
    const force = opts.force === true;
    const allowSpawn = opts.allowSpawn !== false;
    const active = activeBotInstances().find((inst) => isSessionParityEligibleInstance(inst) && Math.floor(Number(inst?.runNum)) === runNum)
      || activeBotInstances().find((inst) => isSessionParityEligibleInstance(inst))
      || null;
    if (!active) return { stale: false, latestClosedSlug: "" };
    const latestClosedSlug = latestClosedSessionSlugForParity(active);
    if (!latestClosedSlug) return { stale: false, latestClosedSlug: "" };
    const artifact = readSessionParityArtifactSummary(runNum);
    const partialNeedsRefresh =
      artifact.latestSlug === latestClosedSlug &&
      artifact.latestOk &&
      artifact.latestPartial &&
      (!Number.isFinite(artifact.latestGeneratedAtMs) || (Date.now() - artifact.latestGeneratedAtMs) >= SESSION_PARITY_PARTIAL_REFRESH_MS);
    const stale = artifact.latestSlug !== latestClosedSlug || !artifact.latestOk || partialNeedsRefresh;
    if (!stale) return { stale: false, latestClosedSlug };
    if (!allowSpawn) return { stale: true, latestClosedSlug };
    if (!isSessionParityAllowedForActiveWindow()) return { stale: true, latestClosedSlug };
    const parityScriptPath = sessionParityScriptPath();
    if (!parityScriptPath) return { stale: true, latestClosedSlug };
    const pyBin = String(process.env.PYTHON_BIN || "python3").trim() || "python3";
    const cacheKey = sessionParityRebuildKey(runNum, latestClosedSlug);
    if (SESSION_PARITY_REBUILD_INFLIGHT.has(cacheKey)) return { stale: true, latestClosedSlug };
    SESSION_PARITY_REBUILD_INFLIGHT.add(cacheKey);
    const args = buildSessionParityArgs(active, latestClosedSlug);
    const child = spawn(pyBin, args, {
      cwd: process.cwd(),
      detached: true,
      stdio: "ignore",
    });
    child.on("error", () => {
      SESSION_PARITY_REBUILD_INFLIGHT.delete(cacheKey);
    });
    child.on("exit", () => {
      SESSION_PARITY_REBUILD_INFLIGHT.delete(cacheKey);
    });
    child.unref();
    return { stale: true, latestClosedSlug };
  } catch {
    return { stale: false, latestClosedSlug: "" };
  }
}

app.get("/api/session-parity/latest", (req, res) => {
  try {
    const runNumRaw = Number(req.query.runNum ?? 0);
    const runNum = Number.isFinite(runNumRaw) && runNumRaw > 0
      ? Math.floor(runNumRaw)
      : (() => {
          const active = activeBotInstances().find((inst) => isSessionParityEligibleInstance(inst));
          const activeRunNum = Math.floor(Number(active?.runNum));
          return Number.isFinite(activeRunNum) && activeRunNum > 0 ? activeRunNum : maxPersistedBotRunNum();
        })();
    if (!(Number.isFinite(runNum) && runNum > 0)) {
      return res.status(404).json({ ok: false, error: "No parity run available" });
    }
    const forceRefresh = String(req.query.refresh || "").trim() === "1";
    const parityRefresh = ensureLatestSessionParityArtifact(runNum, {
      force: forceRefresh,
      allowSpawn: forceRefresh,
    });
    const wantJson = String(req.query.format || "").trim().toLowerCase() === "json";
    const primaryPath = wantJson ? botRunSessionParityJsonPath(runNum) : botRunSessionParityHtmlPath(runNum);
    const goodPath = wantJson ? botRunSessionParityGoodJsonPath(runNum) : botRunSessionParityGoodHtmlPath(runNum);
    const artifact = readSessionParityArtifactSummary(runNum);
    let outPath = primaryPath;
    let primaryOk = artifact.latestOk;
    try {
      if (fs.existsSync(primaryPath)) {
        if (wantJson) {
          const payload = JSON.parse(fs.readFileSync(primaryPath, "utf8"));
          primaryOk = payload?.ok === true;
        } else {
          const body = fs.readFileSync(primaryPath, "utf8");
          primaryOk = !/Session parity unavailable/i.test(body);
        }
      }
    } catch {}
    const shouldPreferGood = artifact.latestPartial && artifact.goodOk && fs.existsSync(goodPath);
    if (shouldPreferGood || (!primaryOk && fs.existsSync(goodPath))) {
      outPath = goodPath;
    }
    if (!fs.existsSync(outPath)) {
      if (wantJson) {
        return res.status(404).json({ ok: false, error: "Session parity artifact not found", runNum });
      }
      res.setHeader("Content-Type", "text/html; charset=utf-8");
      return res.status(404).send(
        "<!doctype html><html><body style=\"font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#0d0d10;color:#f4f4f4;padding:24px\">"
        + `<h1 style="font-size:18px;margin:0 0 12px 0">Session Parity Pending</h1>`
        + `<p style="color:#c8c8d0;max-width:760px;line-height:1.5">No post-close Ohio vs Dublin parity artifact has been generated yet for run ${runNum}. `
        + "This page will populate after a closed session is successfully exported and compared.</p>"
        + "</body></html>"
      );
    }
    res.setHeader("Cache-Control", "no-store, max-age=0");
    res.setHeader("X-MMX-Parity-Latest-Closed-Slug", parityRefresh.latestClosedSlug || "");
    if (wantJson) {
      res.setHeader("Content-Type", "application/json; charset=utf-8");
      if (parityRefresh.stale) res.setHeader("X-MMX-Parity-Stale", "1");
      if (shouldPreferGood) res.setHeader("X-MMX-Parity-Served-Good", "1");
    } else {
      res.setHeader("Content-Type", "text/html; charset=utf-8");
    }
    const body = fs.readFileSync(outPath, "utf8");
    if (wantJson) {
      try {
        const payload = JSON.parse(body || "{}");
        payload.latestClosedSlug = parityRefresh.latestClosedSlug || "";
        payload.stale = parityRefresh.stale === true;
        payload.servedGoodFallback = shouldPreferGood;
        payload.serverTimeMs = Date.now();
        return res.send(JSON.stringify(payload, null, 2));
      } catch {}
    }
    if (!wantJson && parityRefresh.stale && forceRefresh) {
      const injected = body.includes("</body>")
        ? body.replace(
            "</body>",
            `<div style="position:sticky;top:0;z-index:5;background:#2a2410;color:#f6e7a0;padding:8px 12px;font:12px ui-monospace,monospace;border-bottom:1px solid #4a3d10">Refreshing parity to latest closed session ${parityRefresh.latestClosedSlug}...</div></body>`
          )
        : body;
      return res.send(injected);
    }
    if (!wantJson && shouldPreferGood) {
      const injected = body.includes("</body>")
        ? body.replace(
            "</body>",
            `<div style="position:sticky;top:0;z-index:5;background:#10263c;color:#d8efff;padding:8px 12px;font:12px ui-monospace,monospace;border-bottom:1px solid #234764">Showing latest full Ohio vs Dublin parity (${artifact.goodSlug || "latest_good"}) while the newest closed Ohio session (${artifact.latestSlug || "latest"}) is still waiting on Dublin.</div></body>`
          )
        : body;
      return res.send(injected);
    }
    return res.send(body);
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: String(e?.message ?? e) });
  }
});

app.get("/api/session-parity/export", (req, res) => {
  try {
    const slug = String(req.query.slug || "").trim();
    const instanceId = String(req.query.instanceId || "").trim();
    if (!slug) return res.status(400).json({ ok: false, error: "Missing slug" });
    const inst = (
      instanceId
        ? botInstances.get(instanceId)
        : activeBotInstances().find((row) =>
            isRealLiveCapableBotInstance(row) && String(row?.marketSlug || "").trim() === slug
          )
    ) || activeBotInstances().find((row) => isRealLiveCapableBotInstance(row)) || null;
    if (!inst) return res.status(404).json({ ok: false, error: "instance not found" });
    const traced = buildContinuitySessionsForInstance(inst, true, 12).sessions
      .find((row: any) => String(row?.slug || "").trim() === slug) || null;
    const lined = buildContinuitySessionsForInstance(inst, false, 12).sessions
      .find((row: any) => String(row?.slug || "").trim() === slug) || null;
    if (!traced && !lined) {
      return res.status(404).json({ ok: false, error: "session not found", slug, instanceId: inst.instanceId });
    }
    const parityTraceBySlug = readSessionTracesBySlug(Date.now() - 24 * 60 * 60 * 1000, null);
    const traceCurrentFull = buildFullRecordedSessionTraceForHistory(getCurrentSessionTraceForSlug(slug));
    const traceRunFull = buildFullRecordedSessionTraceForHistory(parityTraceBySlug.get(slug) || null);
    const traceCsvFull = buildFullRecordedSessionTraceForHistory(readSessionTraceFromCsv(slug));
    const traceChosenFull = choosePreferredSessionTrace(traceCurrentFull, traceRunFull, traceCsvFull);
    const payload = {
      ok: true,
      slug,
      instanceId: String(inst.instanceId || ""),
      runNum: Number.isFinite(Number(inst.runNum)) ? Math.floor(Number(inst.runNum)) : null,
      strategyId: String(inst.strategyId || ""),
      startMs: Number.isFinite(Number(traced?.startMs ?? lined?.startMs)) ? Number(traced?.startMs ?? lined?.startMs) : null,
      endMs: Number.isFinite(Number(traced?.endMs ?? lined?.endMs)) ? Number(traced?.endMs ?? lined?.endMs) : null,
      traceSource: String(traceChosenFull?.source || traced?.traceSource || ""),
      trace: traceChosenFull || traced?.trace || null,
      lanes: enrichSessionParityLanesWithSignals(inst, slug, Array.isArray(lined?.lanes) ? lined.lanes : []),
      sidePaths: Array.isArray(lined?.sidePaths) ? lined.sidePaths : [],
      pnlUsd: Number.isFinite(Number(lined?.pnlUsd ?? traced?.pnlUsd)) ? Number(lined?.pnlUsd ?? traced?.pnlUsd) : null,
      continuityBalanceUsd: Number.isFinite(Number(lined?.continuityBalanceUsd ?? traced?.continuityBalanceUsd))
        ? Number(lined?.continuityBalanceUsd ?? traced?.continuityBalanceUsd)
        : null,
    };
    return res.json(payload);
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: String(e?.message ?? e) });
  }
});

