app.get("/api/v2/markets/volume-5m-24h", (req, res) => {
  if (rejectHeavyReadOnHotHost(req, res, "markets-volume-5m-24h")) return;
  try {
    res.setHeader("X-MMX-Read-Path", "heavy");
    const anchorSlug = String(req.query?.anchorSlug || "").trim().toLowerCase();
    const hoursRaw = Number(req.query?.hours ?? 24);
    const hours = Number.isFinite(hoursRaw) ? Math.max(1, Math.min(72, Math.floor(hoursRaw))) : 24;
    const m = anchorSlug.match(/^(.*)-(\d{10})$/);
    if (!m) {
      return res.status(400).json({
        ok: false,
        error: "anchorSlug must match *-<10digit_epoch_sec>",
      });
    }
    const base = String(m[1] || "").trim().toLowerCase();
    const anchorStartMs = Number(m[2]) * 1000;
    if (!base || !Number.isFinite(anchorStartMs) || anchorStartMs <= 0) {
      return res.status(400).json({
        ok: false,
        error: "invalid anchorSlug",
      });
    }
    const barMs = 5 * 60 * 1000;
    const barsCount = Math.max(1, Math.floor(hours * 12));
    const firstStartMs = anchorStartMs - ((barsCount - 1) * barMs);
    const prefix = `${base}-`;
    const maxVolBySlug = new Map<string, number>();
    const rows = readJsonlFiles(listTradeLogFiles());
    for (const r of rows) {
      const slug = String(r?.market?.slug || r?.st?.marketSlug || r?.marketSlug || "").trim().toLowerCase();
      if (!slug || !slug.startsWith(prefix)) continue;
      const t = Number(r?.t);
      if (Number.isFinite(t) && (t < firstStartMs || t > (anchorStartMs + barMs))) continue;
      const vol = Number(r?.market?.volumeUsd);
      if (!Number.isFinite(vol) || vol < 0) continue;
      const prev = Number(maxVolBySlug.get(slug));
      if (!Number.isFinite(prev) || vol > prev) maxVolBySlug.set(slug, vol);
    }
    const bars = [];
    for (let i = 0; i < barsCount; i++) {
      const startMs = firstStartMs + (i * barMs);
      const slug = `${base}-${Math.floor(startMs / 1000)}`;
      const v = Number(maxVolBySlug.get(slug));
      const hasVol = Number.isFinite(v) && v >= 0;
      bars.push({
        slug,
        startMs,
        volumeUsd: hasVol ? v : 0,
        missing: !hasVol,
      });
    }
    return res.json({
      ok: true,
      asOfMs: Date.now(),
      anchorSlug,
      hours,
      barMs,
      count: bars.length,
      bars,
    });
  } catch (err: any) {
    return res.status(500).json({
      ok: false,
      error: String(err?.message || err || "unknown error"),
    });
  }
});

app.get("/api/v2/markets/hot", async (req, res) => {
  if (rejectHeavyReadOnHotHost(req, res, "markets-hot")) return;
  res.setHeader("X-MMX-Read-Path", "heavy");
  try {
    const limitRaw = Number(req.query?.limit ?? 25);
    const limit = Number.isFinite(limitRaw) ? Math.max(1, Math.min(100, Math.floor(limitRaw))) : 25;
    const includeNew = String(req.query?.includeNew ?? "1") !== "0";
    const items = await discoverHotMarkets(limit, includeNew);
    return res.json({
      ok: true,
      asOfMs: Date.now(),
      count: items.length,
      items,
    });
  } catch (err: any) {
    return res.status(500).json({
      ok: false,
      error: String(err?.message || err || "unknown error"),
    });
  }
});

