app.post("/api/v2/bots", async (req, res) => {
  try {
    const body = req.body ?? {};
    const marketBucket = normalizeBotMarketBucket(body.marketBucket);
    const marketId = String(body.marketId || "").trim();
    const marketSlug = String(body.marketSlug || marketId || "").trim();
    const marketTitle = String(body.marketTitle || marketSlug || "").trim();
    const strategyIdRaw = String(body.strategyId || "momentum_hc").trim().toLowerCase();
    const strategyId: StrategyId = normalizeStrategyId(strategyIdRaw);
    if (!isStrategyAllowedOnThisHost(strategyId)) {
      return res.status(400).json({
        ok: false,
        error: `strategy blocked by host lock: requested=${strategyId} allowed=${HOST_STRATEGY_LOCK}`,
      });
    }
    const mode: Mode = String(body.mode || "paper").trim().toLowerCase() === "live" ? "live" : "paper";
    const watchOnly = body.watchOnly === true;
    const canonicalStrategy = getCanonicalStrategyArtifact(strategyId);
    const strategyPath = canonicalStrategy.path;
    const expectedStrategyHash = canonicalStrategy.hash;
    const strategyCfg = readStrategySnapshotCfgFromFile(strategyPath);
    if (!fs.existsSync(strategyPath)) {
      return res.status(400).json({
        ok: false,
        error: `strategy file missing for ${strategyId}: ${strategyPath}`,
      });
    }
    const entryDefault =
      isDeriskFamilyStrategy(strategyId) && Number.isFinite(Number((strategyCfg as any)?.buyThr))
        ? Number((strategyCfg as any).buyThr)
        : (
            Number.isFinite(Number((strategyCfg as any)?.entryBreakoutThr))
              ? Number((strategyCfg as any).entryBreakoutThr)
              : Number(uiPaper.entry)
          );
    const entry = clamp01(Number.isFinite(Number(body.entry)) ? Number(body.entry) : entryDefault);
    const isDeriskFamily = strategyId === "derisk" || strategyId === "derisk_trade3";
    const isInflectionLikeStrategy =
      strategyId === "inflection_100" ||
      strategyId === "inflection_positive_slope" ||
      strategyId === "inflection_positive_slope_500_2000" ||
      strategyId === "inflection_positive_slope_200_750" ||
      strategyId === "inflection_positive_iteration";
    const strategyTpDefault = Number.isFinite(Number((strategyCfg as any)?.tp))
      ? Number((strategyCfg as any).tp)
      : Number.NaN;
    const exitDefault =
      strategyId === "profit_locker" || strategyId === "profit_locker_inflection"
        ? 0.9
        : (
            isInflectionLikeStrategy
              ? (Number.isFinite(strategyTpDefault) ? strategyTpDefault : 0.9)
              : Number(uiPaper.exit)
          );
    const stopDefault =
      isDeriskFamily
        ? clamp01(Number((strategyCfg as any)?.stopThr)) || DERISK_STRICT_STOP_THR
        : (
            Number.isFinite(Number((strategyCfg as any)?.stopLossPx))
              ? Number((strategyCfg as any).stopLossPx)
              : ((strategyId === "profit_locker" || strategyId === "profit_locker_inflection" || isInflectionLikeStrategy) ? 0.5 : Number(uiPaper.stop))
          );
    const stopStartDefault = (strategyId === "profit_locker" || strategyId === "profit_locker_inflection" || isInflectionLikeStrategy) ? 20 : Number(uiPaper.stopStartSec || 0);
    const deriskExitDefault =
      isDeriskFamily && Number.isFinite(Number((strategyCfg as any)?.sellThr))
        ? Number((strategyCfg as any).sellThr)
        : exitDefault;
    const exit = clamp01(Number.isFinite(Number(body.exit)) ? Number(body.exit) : deriskExitDefault);
    const stop = clamp01(
      isDeriskFamily
        ? (Number.isFinite(Number((strategyCfg as any)?.stopThr)) ? Number((strategyCfg as any).stopThr) : DERISK_STRICT_STOP_THR)
        : (Number.isFinite(Number(body.stop)) ? Number(body.stop) : stopDefault)
    );
    const useStop = typeof body.useStop === "boolean" ? body.useStop : true;
    const minEntrySec = Math.max(
      0,
      Number.isFinite(Number(body.minEntrySec))
        ? Number(body.minEntrySec)
        : (
            Number.isFinite(Number((strategyCfg as any)?.minEntrySec))
              ? Number((strategyCfg as any).minEntrySec)
              : Number(uiPaper.minEntrySec || 0)
          )
    );
    const stopStartSec = Math.max(0, Number.isFinite(Number(body.stopStartSec)) ? Number(body.stopStartSec) : stopStartDefault);
    const strategyDefaultBetUsd =
      strategyId === "inflection_positive_slope_200_750"
        ? 1
        : Number(uiPaper.betUsd || 25);
    const betUsd = Math.max(1, Number.isFinite(Number(body.betUsd)) ? Number(body.betUsd) : strategyDefaultBetUsd);
    const maxBetUsd = Math.max(betUsd, Number.isFinite(Number(body.maxBetUsd)) ? Number(body.maxBetUsd) : Number(uiPaper.maxBetUsd || betUsd));
    const sizingProfile = String(body.sizingProfile || "").trim().toLowerCase() || null;
    const requestedStartBalanceUsd = Math.max(1, Number.isFinite(Number(body.startBalanceUsd)) ? Number(body.startBalanceUsd) : 100);
    const startBalanceUsd = mode === "paper" ? 100 : requestedStartBalanceUsd;
    if (activeBotInstances().length >= BOT_MAX_INSTANCES) {
      return res.status(400).json({ ok: false, error: `bot limit reached (BOT_MAX_INSTANCES=${BOT_MAX_INSTANCES})` });
    }
    if (countByStrategy(strategyId) >= BOT_MAX_PER_STRATEGY) {
      return res.status(400).json({ ok: false, error: `strategy limit reached for ${strategyId} (BOT_MAX_PER_STRATEGY=${BOT_MAX_PER_STRATEGY})` });
    }
    if (betUsd > BOT_MAX_BET_USD || maxBetUsd > BOT_MAX_BET_USD) {
      return res.status(400).json({ ok: false, error: `bet exceeds BOT_MAX_BET_USD=${BOT_MAX_BET_USD}` });
    }
    if (!marketBucket && !marketId && !marketSlug) {
      return res.status(400).json({ ok: false, error: "marketBucket (or marketId/marketSlug) is required" });
    }
    let resolvedMarketId = marketId;
    let resolvedMarketSlug = marketSlug;
    let resolvedMarketTitle = marketTitle;
    if (marketBucket) {
      const cur = await resolveCurrentBucketMarket(marketBucket);
      if (!cur) return res.status(400).json({ ok: false, error: `No current market for bucket ${marketBucket}` });
      resolvedMarketId = String(cur.slug);
      resolvedMarketSlug = String(cur.slug);
      resolvedMarketTitle = `BTC ${marketBucket} Markets`;
    }
    if (mode === "live" && !watchOnly) {
      const duplicateLive = activeBotInstances().find((b) => {
        if (String(b.mode || "").trim().toLowerCase() !== "live") return false;
        if (b.watchOnly) return false;
        if (!isBotActive(b.status) || b.status === "stopped") return false;
        const sameStrategy = String(b.strategyId || "").trim().toLowerCase() === String(strategyId || "").trim().toLowerCase();
        const sameBucket =
          String(b.marketBucket || "").trim().toLowerCase() &&
          String(marketBucket || "").trim().toLowerCase() &&
          String(b.marketBucket || "").trim().toLowerCase() === String(marketBucket || "").trim().toLowerCase();
        const sameSlug =
          String(b.marketSlug || "").trim().toLowerCase() &&
          String(resolvedMarketSlug || "").trim().toLowerCase() &&
          String(b.marketSlug || "").trim().toLowerCase() === String(resolvedMarketSlug || "").trim().toLowerCase();
        return sameStrategy && (sameBucket || sameSlug);
      });
      if (duplicateLive) {
        return res.status(409).json({
          ok: false,
          error: "duplicate live bot already active for strategy/market",
          existing: {
            instanceId: duplicateLive.instanceId,
            runNum: duplicateLive.runNum,
            strategyId: duplicateLive.strategyId,
            marketBucket: duplicateLive.marketBucket,
            marketSlug: duplicateLive.marketSlug,
            status: duplicateLive.status,
          },
        });
      }
    }
    const supersededPaperBots =
      mode === "paper" && !watchOnly
        ? cleanupSupersededPaperBotsForLaunch(strategyId, marketBucket, resolvedMarketSlug)
        : [];
    const instanceId = makeId("inst");
    const runNum = allocateNextBotRunNum();
    const runId = `run_${runNum}_${Date.now().toString(36)}`;
    const now = Date.now();
    const snap = mode === "live" ? computeLatestPnlSnapshot() : null;
    const key = resolvedMarketSlug || resolvedMarketId;
    const latest = snap ? latestSnapshotForBot(snap, { runNum, marketSlug: String(key), marketId: String(key) }) : null;
    const bot: BotInstance = {
      instanceId,
      runId,
      runNum,
      marketBucket: marketBucket ?? null,
      marketId: resolvedMarketId || resolvedMarketSlug,
      marketSlug: resolvedMarketSlug || resolvedMarketId,
      marketTitle: resolvedMarketTitle || resolvedMarketSlug || resolvedMarketId,
      strategyId,
      mode,
      watchOnly,
      status: watchOnly ? "watching" : "running",
      launchedAtMs: now,
      stoppedAtMs: null,
      latestPnlUsd: mode === "paper" ? 0 : (latest?.pnlUsd ?? null),
      latestBalanceUsd: mode === "paper" ? Number(startBalanceUsd) : (latest?.balanceUsd ?? null),
      lastError: null,
      entry,
      exit,
      stop,
      useStop,
      minEntrySec,
      stopStartSec,
      betUsd,
      maxBetUsd,
      sizingProfile,
      startBalanceUsd,
      strategyPath,
      expectedStrategyHash,
      expectedDeclaredStrategyId: strategyId,
      executionModel: executionModelForStrategy(strategyId),
    };
    botInstances.set(instanceId, bot);
    const rt = ensureRuntime(bot);
    ensureBotStrategyRuntime(bot);
    writeBotRunSummary(bot, rt);
    appendBotRunEvent(bot, rt, { event: "launch", watchOnly: bot.watchOnly, strategyId: bot.strategyId });
    persistMultiMarketState();
    await tickBotRuntime(bot);
    const rtAfter = botRuntimes.get(instanceId) || null;
    return res.json({ ok: true, ...bot, runtime: rtAfter, supersededPaperBots });
  } catch (err: any) {
    return res.status(500).json({
      ok: false,
      error: String(err?.message || err || "unknown error"),
    });
  }
});

app.get("/api/v2/bots", (req, res) => {
  if (rejectHeavyReadOnHotHost(req, res, "bots-list")) return;
  res.setHeader("X-MMX-Read-Path", "heavy");
  const purged = purgeInactiveAndOrphanBotState("api:v2/bots");
  if (purged > 0) persistMultiMarketState();
  const includeTrace = ["1", "true", "yes", "on"].includes(String(req.query?.includeTrace ?? "0").trim().toLowerCase());
  const includeTruth = ["1", "true", "yes", "on"].includes(String(req.query?.includeTruth ?? "0").trim().toLowerCase());
  const includeRecentTrades = ["1", "true", "yes", "on"].includes(String(req.query?.includeRecentTrades ?? "0").trim().toLowerCase());
  const includeStrategySnapshot = ["1", "true", "yes", "on"].includes(String(req.query?.includeStrategySnapshot ?? "0").trim().toLowerCase());
  const includeRunFees = ["1", "true", "yes", "on"].includes(String(req.query?.includeRunFees ?? "0").trim().toLowerCase());
  const internalRunId = Number(SERVER_RUN_ID);
  const snap = includeRunFees ? computeLatestPnlSnapshot() : null;
  const items = Array.from(botInstances.values()).map((b) => {
    const latest = snap ? latestSnapshotForBot(snap, b) : null;
    const rt = botRuntimes.get(b.instanceId);
    const srt = ensureBotStrategyRuntime(b);
    const identity = rt ? recoverBotOpenEntryIdentity(b, rt, srt?.lastSnapshot ?? null) : null;
    const strategyIntegrity = getBotStrategyIntegrity(b, srt);
    const truth = includeTruth ? computeBotRunTruthFromEvents(b) : { realizedPnlUsd: null, balanceUsd: null, fills: null };
    const runFeeTotals = includeRunFees ? computeBotRunFeeTotals(b.runNum, b.instanceId) : null;
    const currentRuntimeSlug = String((rt as any)?.marketSlug || b.marketSlug || "").trim();
    const currentSessionTrace = includeTrace && currentRuntimeSlug ? getCurrentSessionTraceForSlug(currentRuntimeSlug, b.instanceId) : null;
    const displaySessionTrace = includeTrace && currentRuntimeSlug
      ? (getCurrentSessionDisplayTraceForSlug(currentRuntimeSlug) || buildDisplayContinuousTrace(currentSessionTrace))
      : null;
    const recentTradeEvents = includeRecentTrades ? getRecentTradeEventsForInstance(b.instanceId) : [];
    const markerVersion = String(getLiveTradeMarkerSeqForInstance(b.instanceId) || "");
    const strategyApiSnapshot = includeStrategySnapshot && rt && srt
      ? refreshBotStrategySnapshotForApi(b, rt, srt)
      : { snapshot: srt?.lastSnapshot ?? null, decisionSnapshot: (rt as any)?.__latestDecisionSnapshot ?? null };
    return {
      ...b,
      internalRunId,
      latestPnlUsd: b.latestPnlUsd ?? latest?.pnlUsd ?? null,
      latestBalanceUsd: b.latestBalanceUsd ?? latest?.balanceUsd ?? null,
      truthRealizedPnlUsd: truth.realizedPnlUsd,
      truthBalanceUsd: truth.balanceUsd,
      truthFillCount: truth.fills,
      strategyIntegrityOk: strategyIntegrity.ok,
      strategyIntegrityReason: strategyIntegrity.reason,
      expectedStrategyPath: strategyIntegrity.expectedStrategyPath,
      expectedStrategyHash: strategyIntegrity.expectedStrategyHash,
      strategyRuntime: srt
        ? {
            strategyId: srt.strategyId,
            declaredStrategyId: srt.declaredStrategyId,
            loadedAtMs: srt.loadedAtMs,
            lastError: srt.lastError,
            strategyPath: srt.strategyPath,
            strategyHash: srt.strategyHash,
            executionModel: srt.executionModel,
            latestSnapshot: includeStrategySnapshot ? cloneJsonLike(strategyApiSnapshot.snapshot ?? null, null) : null,
          }
        : null,
      runtime: rt
        ? {
            marketSlug: currentRuntimeSlug || null,
            lastTickMs: rt.lastTickMs,
            upBid: rt.upBid,
            downBid: rt.downBid,
            ticks: rt.ticks,
            errorCount: rt.errorCount,
            lastError: rt.lastError,
            entered: rt.entered,
            side: rt.side,
            entryPx: rt.entryPx,
            entryTsMs: rt.entryTsMs,
            entryMode: identity?.mode ?? normalizeRecoveredBotEntryMode((rt as any)?.__lastEntryMode),
            entrySubtype: identity?.hcSubtype ?? normalizeRecoveredBotEntrySubtype((rt as any)?.__lastEntrySubtype),
            exitTsMs: (rt as any).exitTsMs ?? null,
            entryFeeUsd: Number.isFinite(Number(rt.entryFeeUsd)) ? rt.entryFeeUsd : (includeRunFees ? (runFeeTotals?.totalEntryFeesUsd ?? null) : null),
            exitFeeUsd: Number.isFinite(Number(rt.exitFeeUsd)) ? rt.exitFeeUsd : (includeRunFees ? (runFeeTotals?.totalExitFeesUsd ?? null) : null),
            totalFeesUsd: Number.isFinite(Number(rt.totalFeesUsd)) ? rt.totalFeesUsd : (includeRunFees ? (runFeeTotals?.totalFeesUsd ?? null) : null),
            realizedPnlUsd: rt.realizedPnlUsd,
            balanceUsd: rt.balanceUsd,
            truthRealizedPnlUsd: truth.realizedPnlUsd,
            truthBalanceUsd: truth.balanceUsd,
            truthFillCount: truth.fills,
            closedTrades: rt.closedTrades,
            wins: rt.wins,
            losses: rt.losses,
            lastAction: rt.lastAction,
            lastExitType: rt.lastExitType,
            lastQuoteMeta: cloneJsonLike((rt as any).__lastQuoteMeta || null, null),
            lastStrategyQuoteSeq: Number.isFinite(Number((rt as any).__lastStrategyQuoteSeq))
              ? Number((rt as any).__lastStrategyQuoteSeq)
              : null,
          }
        : null,
      latestDecisionSnapshot: cloneJsonLike(strategyApiSnapshot.decisionSnapshot ?? null, null),
      displaySessionTrace,
      currentSessionTrace,
      markerVersion,
      recentTradeEvents,
    };
  });
  if (!items.some((item) => String(item?.mode || "").trim().toLowerCase() === "live") && hostGlobalLiveEngineHasVisibleState()) {
    items.push({
      instanceId: "host_global_live_engine",
      runId: `host_global_${SERVER_RUN_ID}`,
      runNum: Number(SERVER_RUN_ID),
      mode: "live",
      watchOnly: false,
      status: uiLive.enabled ? "running" : "error",
      launchedAtMs: null,
      stoppedAtMs: null,
      latestPnlUsd: null,
      latestBalanceUsd: liveAccount.balanceUsd ?? stLive.balanceUsd ?? null,
      lastError: String(stLive.lastError || "").trim() || null,
      marketBucket: null,
      marketId: String(current.slug || ""),
      marketSlug: String(current.slug || ""),
      marketTitle: String(current.slug || ""),
      strategyId: "host_global_live_engine",
      entry: uiLive.entry,
      exit: uiLive.exit,
      stop: uiLive.stop,
      useStop: uiLive.useStop,
      minEntrySec: uiLive.minEntrySec,
      stopStartSec: uiLive.stopStartSec,
      betUsd: uiLive.betUsd,
      maxBetUsd: uiLive.maxBetUsd,
      sizingProfile: null,
      startBalanceUsd: liveAccount.balanceUsd ?? stLive.balanceUsd ?? null,
      strategyPath: null,
      expectedStrategyHash: null,
      expectedDeclaredStrategyId: null,
      executionModel: "legacy_host_global_live",
      internalRunId,
      truthRealizedPnlUsd: null,
      truthBalanceUsd: null,
      truthFillCount: null,
      strategyIntegrityOk: false,
      strategyIntegrityReason: "legacy_host_global_live_engine",
      expectedStrategyPath: null,
      runtime: {
        marketSlug: String(current.slug || "") || null,
        lastTickMs: stLive.lastTickMs ?? null,
        upBid: stLive.upBid ?? null,
        downBid: stLive.downBid ?? null,
        ticks: stLive.ticks ?? null,
        errorCount: stLive.errorCount ?? null,
        lastError: stLive.lastError ?? null,
        entered: stLive.entered,
        side: stLive.side,
        entryPx: stLive.entryPx,
        entryTsMs: stLive.entryTsMs,
        entryMode: stLive.entryMode ?? null,
        entrySubtype: stLive.entrySubtype ?? null,
        exitTsMs: stLive.exitTsMs ?? null,
        entryFeeUsd: stLive.entryFeeUsd ?? null,
        exitFeeUsd: stLive.exitFeeUsd ?? null,
        totalFeesUsd: stLive.totalFeesUsd ?? null,
        realizedPnlUsd: stLive.realizedPnlUsd ?? null,
        balanceUsd: stLive.balanceUsd ?? liveAccount.balanceUsd ?? null,
        truthRealizedPnlUsd: null,
        truthBalanceUsd: null,
        truthFillCount: null,
        closedTrades: stLive.closedTrades ?? null,
        wins: stLive.wins ?? null,
        losses: stLive.losses ?? null,
        lastAction: stLive.lastAction ?? null,
        lastExitType: stLive.lastExitType ?? null,
      },
      displaySessionTrace:
        getCurrentSessionDisplayTraceForSlug(String(current.slug || "").trim())
        || buildDisplayContinuousTrace(getCurrentSessionTraceForSlug(String(current.slug || "").trim(), "host_global_live_engine"))
        || null,
      currentSessionTrace: getCurrentSessionTraceForSlug(String(current.slug || "").trim(), "host_global_live_engine") ?? null,
      recentTradeEvents: includeRecentTrades ? [] : [],
    });
  }
  return res.json({
    ok: true,
    asOfMs: Date.now(),
    internalRunId,
    count: items.length,
    items,
  });
});

