app.get("/api/v2/bots/:instanceId/focused-live-session", (req, res) => {
  if (rejectHeavyReadOnHotHost(req, res, "focused-live-session")) return;
  res.setHeader("X-MMX-Read-Path", "heavy");
  try {
    const instanceId = String(req.params.instanceId || "").trim();
    const b = botInstances.get(instanceId);
    if (!b) return res.status(404).json({ ok: false, error: "instance not found" });
    const rt = botRuntimes.get(instanceId) || null;
    const slug = String(req.query.slug || rt?.marketSlug || b.marketSlug || "").trim();
    const markerVersion = getRecentTradeMarkerVersionForInstance(instanceId);
    const now = Date.now();
    const pairLagMs =
      Number.isFinite(Number(quotePairCache?.tsMs)) && Number(quotePairCache?.tsMs) > 0
        ? Math.max(0, now - Number(quotePairCache.tsMs))
        : null;
    const pairObservedAgeMs =
      Number.isFinite(Number(quotePairCache?.observedAtMs)) && Number(quotePairCache?.observedAtMs) > 0
        ? Math.max(0, now - Number(quotePairCache.observedAtMs))
        : null;
    const streamLastMsgAgeMs =
      Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
        ? Math.max(0, now - Number(quoteStreamLastMsgMs))
        : null;
    const streamLastPriceMsgAgeMs =
      Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
        ? Math.max(0, now - Number(quoteStreamLastPriceMsgMs))
        : null;
    if (!slug) {
      return res.json({
        ok: true,
        instanceId,
        slug: null,
        markerVersion,
        trace: null,
        displayTrace: null,
        markers: [],
        invariants: {
          instanceId,
          slug: null,
          entered: !!rt?.entered,
          side: String(rt?.side || "").trim().toUpperCase() || null,
          rawTracePointCount: 0,
          displayTracePointCount: 0,
          markerCount: 0,
          hasEntryMarker: false,
          missingEntryMarkerWhileEntered: !!rt?.entered,
          traceStaleVsRuntimeTickMs: null,
          runtimeLagMs: focusedLiveRuntimeLagMsNow(),
          continuityHealthy: false,
          sources: { rawTrace: null, displayTrace: null },
          rawLastMs: null,
          displayLastMs: null,
          runtimeTickMs: Number.isFinite(Number(rt?.lastTickMs)) ? Number(rt.lastTickMs) : null,
        },
      });
    }
    const focusedLiveLite =
      ["1", "true", "yes", "on"].includes(String(req.query.lite ?? "").trim().toLowerCase());
    const trace = getCurrentSessionTraceForSlug(slug, instanceId);
    const sampledDisplayTrace = getCurrentSessionDisplayTraceForSlug(slug);
    const markers = ensureRuntimeEntryLiveMarker(
      instanceId,
      slug,
      rt,
      Array.isArray(trace?.markers)
        ? trace!.markers!.map((row: any) => cloneLiveTradeMarker(row)).filter(Boolean)
        : getLiveTradeMarkersForInstance(instanceId, slug, 0)
    );
    const traceWithMarkers = trace ? { ...trace, markers } : trace;
    const fullDisplayTrace =
      sampledDisplayTrace
      || buildDisplayContinuousTrace(traceWithMarkers || trace);
    const displayTrace = focusedLiveLite
      ? compactFocusedDisplayTrace(fullDisplayTrace || traceWithMarkers || trace, 600)
      : fullDisplayTrace;
    const invariants = buildFocusedLiveSessionInvariants(b, rt, traceWithMarkers || trace, displayTrace, markers);
    return res.json({
      ok: true,
      instanceId,
      runNum: Number.isFinite(Number(b.runNum)) ? Number(b.runNum) : null,
      strategyId: String(b.strategyId || "") || null,
      slug,
      markerVersion,
      trace: focusedLiveLite ? null : (traceWithMarkers || trace),
      displayTrace,
      markers,
      invariants,
      runtime: rt
        ? {
            marketSlug: String(rt.marketSlug || "") || null,
            lastTickMs: Number.isFinite(Number(rt.lastTickMs)) ? Number(rt.lastTickMs) : null,
            upBid: Number.isFinite(Number(rt.upBid)) ? Number(rt.upBid) : null,
            downBid: Number.isFinite(Number(rt.downBid)) ? Number(rt.downBid) : null,
            entered: !!rt.entered,
            side: String(rt.side || "").trim().toUpperCase() || null,
            entryPx: Number.isFinite(Number(rt.entryPx)) ? Number(rt.entryPx) : null,
            entryTsMs: Number.isFinite(Number(rt.entryTsMs)) ? Number(rt.entryTsMs) : null,
            shares: Number.isFinite(Number(rt.shares)) ? Number(rt.shares) : null,
            realizedPnlUsd: Number.isFinite(Number(rt.realizedPnlUsd)) ? Number(rt.realizedPnlUsd) : null,
            balanceUsd: Number.isFinite(Number(rt.balanceUsd)) ? Number(rt.balanceUsd) : null,
            lastAction: String(rt.lastAction || "") || null,
            lastExitType: String(rt.lastExitType || "") || null,
            runtimeLagMs: focusedLiveRuntimeLagMsNow(),
            quotePairTsMs:
              Number.isFinite(Number((rt as any)?.__lastQuoteMeta?.pairTsMs))
                ? Number((rt as any).__lastQuoteMeta.pairTsMs)
                : (Number.isFinite(Number(quotePairCache?.tsMs)) ? Number(quotePairCache.tsMs) : null),
            quotePairAgeMs:
              Number.isFinite(Number((rt as any)?.__lastQuoteMeta?.pairAgeMs))
                ? Number((rt as any).__lastQuoteMeta.pairAgeMs)
                : (Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null),
            quoteFeed: {
              pairSource:
                String((rt as any)?.__lastQuoteMeta?.source || "").trim()
                || String(quotePairCache?.source || "").trim()
                || null,
              pairPure:
                (rt as any)?.__lastQuoteMeta?.pure === true
                ? true
                : !!quotePairCache?.pure,
              pairSynthetic:
                (rt as any)?.__lastQuoteMeta?.synthetic === true
                ? true
                : !!quotePairCache?.synthetic,
              pairSeq: Number.isFinite(Number((rt as any)?.__lastQuoteMeta?.quoteSeq))
                ? Number((rt as any).__lastQuoteMeta.quoteSeq)
                : (Number.isFinite(Number(quotePairCache?.seq)) ? Number(quotePairCache.seq) : null),
              pairObservedAgeMs: Number.isFinite(Number(pairObservedAgeMs)) ? Number(pairObservedAgeMs) : null,
              pairLagMs: Number.isFinite(Number(pairLagMs)) ? Number(pairLagMs) : null,
              streamEnabled: QUOTE_STREAM_ENABLED,
              streamConnected: quoteStreamConnected,
              streamLastMsgAgeMs: Number.isFinite(Number(streamLastMsgAgeMs)) ? Number(streamLastMsgAgeMs) : null,
              streamLastPriceMsgAgeMs: Number.isFinite(Number(streamLastPriceMsgAgeMs)) ? Number(streamLastPriceMsgAgeMs) : null,
              degradedReason:
                !QUOTE_STREAM_ENABLED ? "stream_disabled"
                : !quoteStreamConnected ? "stream_disconnected"
                : (
                    String((rt as any)?.__lastQuoteMeta?.source || "").trim()
                    || String(quotePairCache?.source || "").trim()
                  ) !== "ws_direct" ? "non_websocket_source"
                : (Number.isFinite(Number(pairLagMs)) && Number(pairLagMs) > 100) ? "pair_lag_too_high"
                : (Number.isFinite(Number(streamLastPriceMsgAgeMs)) && Number(streamLastPriceMsgAgeMs) > 100) ? "stream_price_age_too_high"
                : null,
            },
          }
        : null,
    });
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: String(e?.message ?? e) });
  }
});

app.get("/api/v2/bots/:instanceId/live-markers", (req, res) => {
  try {
    const instanceId = String(req.params.instanceId || "").trim();
    const inst = botInstances.get(instanceId);
    if (!inst) return res.status(404).json({ ok: false, error: "instance not found" });
    const rt = botRuntimes.get(instanceId) || null;
    const slug = String(req.query.slug || inst.marketSlug || "").trim();
    if (!slug) return res.status(400).json({ ok: false, error: "missing slug" });
    const latestSeq = getLiveTradeMarkerSeqForInstance(instanceId);
    const sinceSeq = Math.max(0, Math.floor(Number(req.query.sinceSeq || 0)));
    const markerVersion = String(latestSeq || "");
    const markerVersionIfKnown = String(req.query.markerVersion || "").trim();
    if ((sinceSeq > 0 && sinceSeq >= latestSeq) || (markerVersionIfKnown && markerVersionIfKnown === markerVersion)) {
      return res.json({
        ok: true,
        instanceId,
        runNum: Math.floor(Number(inst.runNum || 0)),
        strategyId: String(inst.strategyId || ""),
        slug,
        markerVersion,
        latestSeq,
        sinceSeq,
        count: 0,
        notModified: true,
        markers: [],
      });
    }
    const markers = ensureRuntimeEntryLiveMarker(
      instanceId,
      slug,
      rt,
      getLiveTradeMarkersForInstance(instanceId, slug, sinceSeq)
    );
    return res.json({
      ok: true,
      instanceId,
      runNum: Math.floor(Number(inst.runNum || 0)),
      strategyId: String(inst.strategyId || ""),
      slug,
      markerVersion,
      latestSeq,
      sinceSeq,
      count: markers.length,
      markers,
    });
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: String(e?.message ?? e) });
  }
});

