app.post("/api/host-servers/:port/stop", async (req, res) => {
  try {
    const port = Math.floor(Number(req.params.port));
    if (!HOST_MANAGED_SERVER_PORTS.includes(port)) {
      return res.status(400).json({ ok: false, error: "unsupported port" });
    }
    const scriptPath = path.resolve(__dirname, `manage_${port}.sh`);
    if (!fs.existsSync(scriptPath)) {
      return res.status(404).json({ ok: false, error: "manage script not found" });
    }
    const child = spawn("/bin/bash", ["-lc", `cd ${JSON.stringify(__dirname)} && ./manage_${port}.sh stop`], {
      detached: true,
      stdio: "ignore",
    });
    child.unref();
    return res.json({
      ok: true,
      port,
      requestedAtMs: nowMs(),
      self: port === Number(PORT),
      status: "stop_requested",
    });
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: String(e?.message ?? e) });
  }
});

app.post("/api/v2/bots/:instanceId/stop", async (req, res) => {
  try {
    const instanceId = String(req.params.instanceId || "").trim();
    const item = botInstances.get(instanceId);
    if (!item) return res.status(404).json({ ok: false, error: "instance not found" });
    stopLatencyEntryWorker(instanceId, "manual_stop");
    const rt = botRuntimes.get(instanceId);
    const isRealLiveBot = !!(rt && isRealLiveCapableBotInstance(item));
    if (rt && isRealLiveBot && rt.entered && (rt.side === "UP" || rt.side === "DOWN")) {
      await flattenBotRuntimeLiveExposureNow(item, rt, "manual_stop");
    }
    const result = hardTerminateBotInstance(instanceId, "manual_stop");
    persistMultiMarketState();
    broadcast({ type: "bot_status", t: nowMs(), instanceId, status: "stopped", stoppedAtMs: result.stoppedAtMs, removed: true });
    return res.json({ ok: true, instanceId, status: "stopped", stoppedAtMs: result.stoppedAtMs, removed: true });
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: String(e?.message ?? e) });
  }
});

app.get("/api/v2/portfolio/summary", (req, res) => {
  if (rejectHeavyReadOnHotHost(req, res, "portfolio-summary")) return;
  res.setHeader("X-MMX-Read-Path", "heavy");
  const snap = computeLatestPnlSnapshot();
  const items = Array.from(botInstances.values()).map((b) => {
    const latest = latestSnapshotForBot(snap, b);
    return {
      ...b,
      latestPnlUsd: b.latestPnlUsd ?? latest?.pnlUsd ?? null,
      latestBalanceUsd: b.latestBalanceUsd ?? latest?.balanceUsd ?? null,
    };
  });
  const running = items.filter((x) => x.status === "running").length;
  const watching = items.filter((x) => x.status === "watching").length;
  const stopped = items.filter((x) => x.status === "stopped").length;
  const errors = items.filter((x) => x.status === "error").length;
  const totalLatestPnlUsd = Number(
    items.reduce((acc, x) => acc + (Number.isFinite(Number(x.latestPnlUsd)) ? Number(x.latestPnlUsd) : 0), 0).toFixed(2)
  );
  const totalLatestBalanceUsd = Number(
    items.reduce((acc, x) => acc + (Number.isFinite(Number(x.latestBalanceUsd)) ? Number(x.latestBalanceUsd) : 0), 0).toFixed(2)
  );
  return res.json({
    ok: true,
    asOfMs: Date.now(),
    totals: {
      markets: items.length,
      running,
      watching,
      stopped,
      errors,
      totalLatestPnlUsd,
      totalLatestBalanceUsd,
    },
  });
});

