// ===== Polymarket lookups (Gamma) =====
async function gammaEventBySlug(slug: string): Promise<any | null> {
  const data = await getJson(`${GAMMA_BASE}/events`, { slug });
  if (Array.isArray(data)) return data[0] ?? null;
  if (data && typeof data === "object") {
    if (Array.isArray((data as any).data)) return (data as any).data[0] ?? null;
    if ((data as any).slug === slug) return data;
  }
  return null;
}

type SessionMarketResolution = {
  slug: string;
  startMs: number;
  endMs: number;
  upToken: string;
  downToken: string;
  volumeUsd: number | null;
  resolvedAtMs: number;
};

const SESSION_MARKET_CACHE_TTL_MS = Math.max(15_000, Number(process.env.SESSION_MARKET_CACHE_TTL_MS || 10 * 60_000));
const sessionMarketCache = new Map<string, SessionMarketResolution>();

function buildSessionMarketResolutionFromEvent(
  slugLike: any,
  evt: any,
  startMsHint?: number | null
): SessionMarketResolution | null {
  const slug = String(slugLike || evt?.slug || evt?.marketSlug || "").trim();
  if (!slug || !evt || typeof evt !== "object") return null;
  const markets = Array.isArray(evt?.markets) ? evt.markets : [];
  const mkt = markets.length ? markets[0] : evt;
  const { up, down } = extractUpDownTokensFromMarket(mkt);
  if (!up || !down) return null;
  const endMs =
    parseEpochMsLike(mkt?.endDate) ??
    parseEpochMsLike(mkt?.end_time) ??
    parseEpochMsLike(mkt?.endTime) ??
    parseEpochMsLike(mkt?.endTimestamp) ??
    parseEpochMsLike(mkt?.endTs) ??
    parseEpochMsLike(evt?.endDate) ??
    parseEpochMsLike(evt?.end_time) ??
    parseEpochMsLike(evt?.endTime) ??
    parseEpochMsLike(evt?.endTimestamp) ??
    parseEpochMsLike(evt?.endTs);
  if (!(Number.isFinite(Number(endMs)) && Number(endMs) > 0)) return null;
  const startMs =
    parseEpochMsLike(mkt?.startDate) ??
    parseEpochMsLike(mkt?.start_time) ??
    parseEpochMsLike(mkt?.startTime) ??
    parseEpochMsLike(mkt?.startTimestamp) ??
    parseEpochMsLike(mkt?.startTs) ??
    parseEpochMsLike(evt?.startDate) ??
    parseEpochMsLike(evt?.start_time) ??
    parseEpochMsLike(evt?.startTime) ??
    parseEpochMsLike(evt?.startTimestamp) ??
    parseEpochMsLike(evt?.startTs) ??
    (Number.isFinite(Number(startMsHint)) ? Number(startMsHint) : null);
  if (!(Number.isFinite(Number(startMs)) && Number(startMs) >= 0 && Number(endMs) > Number(startMs))) return null;
  return {
    slug,
    startMs: Number(startMs),
    endMs: Number(endMs),
    upToken: String(up),
    downToken: String(down),
    volumeUsd: parseMarketVolumeUsd(mkt),
    resolvedAtMs: nowMs(),
  };
}

function rememberSessionMarketResolution(resolution: SessionMarketResolution | null | undefined): void {
  if (!resolution) return;
  const slug = String(resolution.slug || "").trim();
  if (!slug) return;
  sessionMarketCache.set(slug, resolution);
  const now = nowMs();
  for (const [key, value] of sessionMarketCache.entries()) {
    if (!value || (now - Number(value.resolvedAtMs || 0)) > SESSION_MARKET_CACHE_TTL_MS) {
      sessionMarketCache.delete(key);
    }
  }
}

function getCachedSessionMarketResolution(slugLike: any, startMsHint?: number | null, endMsHint?: number | null): SessionMarketResolution | null {
  const slug = String(slugLike || "").trim();
  if (!slug) return null;
  const hit = sessionMarketCache.get(slug);
  if (!hit) return null;
  const now = nowMs();
  if ((now - Number(hit.resolvedAtMs || 0)) > SESSION_MARKET_CACHE_TTL_MS) {
    sessionMarketCache.delete(slug);
    return null;
  }
  if (Number.isFinite(Number(startMsHint)) && Math.abs(Number(hit.startMs) - Number(startMsHint)) > 1000) return null;
  if (Number.isFinite(Number(endMsHint)) && Math.abs(Number(hit.endMs) - Number(endMsHint)) > 1000) return null;
  return hit;
}

async function gammaEventBySlugQuick(slug: string, timeoutMs = 900): Promise<any | null> {
  try {
    const ctl = new AbortController();
    const to = setTimeout(() => ctl.abort(), Math.max(120, Math.floor(Number(timeoutMs) || 900)));
    const u = new URL(`${GAMMA_BASE}/events`);
    u.searchParams.set("slug", String(slug || ""));
    const r = await fetch(u.toString(), { method: "GET", signal: ctl.signal });
    clearTimeout(to);
    if (!r.ok) return null;
    const data = await r.json().catch(() => null);
    if (Array.isArray(data)) {
      const evt = data[0] ?? null;
      rememberSessionMarketResolution(buildSessionMarketResolutionFromEvent(slug, evt));
      return evt;
    }
    if (data && typeof data === "object") {
      if (Array.isArray((data as any).data)) {
        const evt = (data as any).data[0] ?? null;
        rememberSessionMarketResolution(buildSessionMarketResolutionFromEvent(slug, evt));
        return evt;
      }
      if ((data as any).slug === slug) {
        rememberSessionMarketResolution(buildSessionMarketResolutionFromEvent(slug, data));
        return data;
      }
    }
    return null;
  } catch {
    return null;
  }
}

function parseMarketVolumeUsd(mkt: any): number | null {
  const candidates = [mkt?.volumeNum, mkt?.volume, mkt?.volumeUsd, mkt?.volumeUSD, mkt?.totalVolume];
  for (const c of candidates) {
    const n = Number(c);
    if (Number.isFinite(n) && n >= 0) return n;
  }
  return null;
}

type HotMarket = {
  marketId: string;
  slug: string;
  title: string;
  category: string;
  volume24hUsd: number;
  volume1hUsd: number;
  volumeVelocity: number;
  launchedAtMs: number | null;
  hotScore: number;
  isNew: boolean;
  recommendationReason: string;
};

function toScannerText(m: any): string {
  const tags =
    Array.isArray(m?.tags)
      ? m.tags
          .map((t: any) => (typeof t === "string" ? t : t?.name || t?.label || t?.slug || ""))
          .filter(Boolean)
          .join(" ")
      : "";
  return [
    m?.slug,
    m?.marketSlug,
    m?.question,
    m?.title,
    m?.description,
    m?.category,
    m?.groupItemTitle,
    m?.eventCategory,
    tags,
  ]
    .map((v) => String(v || ""))
    .join(" ")
    .toLowerCase();
}

function parseEpochMsLike(v: any): number | null {
  const n = Number(v);
  if (Number.isFinite(n)) {
    if (n > 1e12) return n;
    if (n > 1e9) return n * 1000;
  }
  if (typeof v === "string" && v.trim()) {
    const p = Date.parse(v);
    if (Number.isFinite(p)) return p;
  }
  return null;
}

function classifyDurationBucketByMinutes(mins: number): "5m" | "15m" | "hourly" | "daily" | "weekly" | "monthly" | null {
  if (!Number.isFinite(mins) || mins <= 0) return null;
  if (mins <= 7) return "5m";
  if (mins <= 20) return "15m";
  if (mins <= 90) return "hourly";
  if (mins <= 36 * 60) return "daily";
  if (mins <= 10 * 24 * 60) return "weekly";
  if (mins <= 45 * 24 * 60) return "monthly";
  return null;
}

function marketDurationBucket(m: any): "5m" | "15m" | "hourly" | "daily" | "weekly" | "monthly" | null {
  const startMs =
    parseEpochMsLike(m?.startDate) ??
    parseEpochMsLike(m?.start_time) ??
    parseEpochMsLike(m?.startTime) ??
    parseEpochMsLike(m?.startTimestamp) ??
    parseEpochMsLike(m?.startTs);
  const endMs =
    parseEpochMsLike(m?.endDate) ??
    parseEpochMsLike(m?.end_time) ??
    parseEpochMsLike(m?.endTime) ??
    parseEpochMsLike(m?.endTimestamp) ??
    parseEpochMsLike(m?.endTs);
  if (startMs != null && endMs != null && endMs > startMs) {
    const mins = (endMs - startMs) / 60000;
    return classifyDurationBucketByMinutes(mins);
  }
  return null;
}

function hasAllowedDurationToken(text: string): boolean {
  return (
    /(?:\b5m\b|\b5[- ]?min(?:ute)?s?\b)/i.test(text) ||
    /(?:\b15m\b|\b15[- ]?min(?:ute)?s?\b)/i.test(text) ||
    /(?:\bhourly\b|\b1h\b|\b1 hour\b)/i.test(text) ||
    /(?:\bdaily\b|\b1d\b)/i.test(text) ||
    /(?:\bweekly\b|\b1w\b)/i.test(text) ||
    /(?:\bmonthly\b|\b1mo\b|\b1 month\b)/i.test(text)
  );
}

function isCryptoScannerMarket(m: any): boolean {
  const text = toScannerText(m);
  const isCrypto =
    /\bcrypto\b/i.test(text) ||
    /\bbitcoin\b|\bbtc\b|\beth(?:ereum)?\b|\bsol(?:ana)?\b|\bdoge\b|\bxrp\b|\bbnb\b|\bltc\b|\bavax\b|\bada\b/i.test(text);
  if (!isCrypto) return false;
  const byDuration = marketDurationBucket(m);
  if (byDuration) return true;
  return hasAllowedDurationToken(text);
}

function isCryptoMarketRelaxed(m: any): boolean {
  const text = toScannerText(m);
  return (
    /\bcrypto\b/i.test(text) ||
    /\bbitcoin\b|\bbtc\b|\beth(?:ereum)?\b|\bsol(?:ana)?\b|\bdoge\b|\bxrp\b|\bbnb\b|\bltc\b|\bavax\b|\bada\b/i.test(text)
  );
}

async function fetchGammaMarkets(limit: number): Promise<any[]> {
  const capped = Math.max(25, Math.min(500, limit));
  const candidates = [
    `${GAMMA_BASE}/markets?active=true&closed=false&limit=${capped}`,
    `${GAMMA_BASE}/markets?limit=${capped}`,
  ];
  for (const url of candidates) {
    try {
      const r = await fetch(url, { method: "GET" });
      if (!r.ok) continue;
      const data = await r.json();
      const rows = Array.isArray(data)
        ? data
        : (Array.isArray((data as any)?.data) ? (data as any).data : null);
      if (Array.isArray(rows)) {
        for (const row of rows) {
          const slug = String(row?.slug || row?.marketSlug || "").trim();
          if (!slug) continue;
          rememberSessionMarketResolution(buildSessionMarketResolutionFromEvent(slug, row));
        }
        return rows;
      }
    } catch {}
  }
  return [];
}

function toHotMarket(m: any): HotMarket | null {
  const slug = String(m?.slug || m?.marketSlug || "").trim();
  if (!slug) return null;
  const marketId = String(m?.id || m?.marketId || slug);
  const title = String(m?.question || m?.title || slug);
  const category = String(m?.category || m?.groupItemTitle || "unknown");
  const text = toScannerText(m);
  const volume24hUsd = Number(parseMarketVolumeUsd(m) ?? 0);
  const volume1hUsd = Math.max(0, volume24hUsd * 0.2);
  const volumeVelocity = volume24hUsd > 0 ? Math.max(0.1, Math.min(10, volume1hUsd / Math.max(1, volume24hUsd / 24))) : 0;
  const launchedAtMsRaw = Number(
    m?.createdAtTimestamp ??
      m?.createdAtEpochMs ??
      (m?.createdAt ? Date.parse(String(m.createdAt)) : NaN)
  );
  const launchedAtMs = Number.isFinite(launchedAtMsRaw) ? launchedAtMsRaw : null;
  const ageMs = launchedAtMs != null ? Math.max(0, Date.now() - launchedAtMs) : Number.POSITIVE_INFINITY;
  const isNew = ageMs <= 48 * 60 * 60 * 1000;
  const freshnessBoost = isNew ? 1.2 : 1.0;
  const durationBoost = (marketDurationBucket(m) || hasAllowedDurationToken(text)) ? 8 : 0;
  const btcUpDownBoost = /\bbitcoin\b.*\bup\b.*\bdown\b|\bbtc\b.*\bup\b.*\bdown\b|up-or-down/i.test(text) ? 12 : 0;
  const hotScore = Number((Math.log10(volume24hUsd + 1) * 25 * freshnessBoost + volumeVelocity * 10 + durationBoost + btcUpDownBoost).toFixed(2));
  const reason =
    btcUpDownBoost > 0
      ? "Bitcoin up/down priority market"
      : isNew
      ? "High-volume new listing"
      : "Top volume market";
  return {
    marketId,
    slug,
    title,
    category,
    volume24hUsd: Number(volume24hUsd.toFixed(2)),
    volume1hUsd: Number(volume1hUsd.toFixed(2)),
    volumeVelocity: Number(volumeVelocity.toFixed(3)),
    launchedAtMs,
    hotScore,
    isNew,
    recommendationReason: reason,
  };
}

async function discoverHotMarkets(limit: number, includeNew: boolean): Promise<HotMarket[]> {
  const gammaRows = await fetchGammaMarkets(Math.max(240, limit * 12));
  let hot = gammaRows
    .filter((m) => isCryptoScannerMarket(m))
    .map(toHotMarket)
    .filter((x): x is HotMarket => !!x);
  // Gamma rows sometimes omit duration/category fields; avoid empty scanner by
  // relaxing to crypto-only symbols/categories when strict duration parsing yields nothing.
  if (!hot.length) {
    hot = gammaRows
      .filter((m) => isCryptoMarketRelaxed(m))
      .map(toHotMarket)
      .filter((x): x is HotMarket => !!x);
  }
  if (!hot.length) {
    const fallback = await getMostCurrent5mMarket().catch(() => null);
    if (fallback) {
      hot = [
        {
          marketId: fallback.slug,
          slug: fallback.slug,
          title: fallback.slug,
          category: "crypto",
          volume24hUsd: Number(fallback.volumeUsd || 0),
          volume1hUsd: Number((Number(fallback.volumeUsd || 0) * 0.2).toFixed(2)),
          volumeVelocity: 1,
          launchedAtMs: Number(fallback.startMs),
          hotScore: 50,
          isNew: true,
          recommendationReason: "Fallback current tradable market",
        },
      ];
    }
  }
  const intervalRows = await getCurrentBtcIntervalMarkets().catch(() => []);
  if (Array.isArray(intervalRows) && intervalRows.length) {
    const intervalHot: HotMarket[] = intervalRows.map((x) => ({
      marketId: x.slug,
      slug: x.slug,
      title: x.slug,
      category: "crypto",
      volume24hUsd: Number(x.volumeUsd || 0),
      volume1hUsd: Number((Number(x.volumeUsd || 0) * 0.2).toFixed(2)),
      volumeVelocity: 1.5,
      launchedAtMs: Number(x.startMs),
      hotScore: x.bucket === "5m" ? 99 : x.bucket === "15m" ? 96 : x.bucket === "hourly" ? 94 : 92,
      isNew: true,
      recommendationReason: `Current BTC ${x.bucket} market`,
    }));
    hot = [...intervalHot, ...hot];
  }
  hot = dedupeHotMarketsBySlug(hot);
  hot = hot
    .filter((x) => includeNew || !x.isNew)
    .sort((a, b) => Number(b.hotScore) - Number(a.hotScore) || Number(b.volume24hUsd) - Number(a.volume24hUsd))
    .slice(0, limit);
  return hot;
}

type IntervalBucket = "5m" | "15m" | "hourly" | "daily";

function inferIntervalBucketFromSlug(slugLike: string): IntervalBucket | null {
  const slug = String(slugLike || "").toLowerCase();
  if (!slug) return null;
  if (/(?:^|-)5m-/.test(slug) || slug.includes("updown-5m")) return "5m";
  if (/(?:^|-)15m-/.test(slug) || slug.includes("updown-15m") || slug.includes("updown-15min")) return "15m";
  if (slug.includes("hourly") || slug.includes("updown-1h")) return "hourly";
  if (slug.includes("daily") || slug.includes("updown-1d")) return "daily";
  return null;
}

async function auditBtcIntervalMarkets(limit: number = 80) {
  const mustHave: IntervalBucket[] = ["5m", "15m", "hourly", "daily"];
  const currentRows = await getCurrentBtcIntervalMarkets().catch(() => []);
  const hot = await discoverHotMarkets(Math.max(20, limit), true).catch(() => []);

  const byBucket: Record<IntervalBucket, { fromCurrent: boolean; fromHot: boolean; ok: boolean; slugCurrent: string | null; slugHot: string | null }> = {
    "5m": { fromCurrent: false, fromHot: false, ok: false, slugCurrent: null, slugHot: null },
    "15m": { fromCurrent: false, fromHot: false, ok: false, slugCurrent: null, slugHot: null },
    "hourly": { fromCurrent: false, fromHot: false, ok: false, slugCurrent: null, slugHot: null },
    "daily": { fromCurrent: false, fromHot: false, ok: false, slugCurrent: null, slugHot: null },
  };

  for (const row of currentRows || []) {
    const b = (row as any)?.bucket as IntervalBucket;
    if (!b || !byBucket[b]) continue;
    byBucket[b].fromCurrent = true;
    byBucket[b].slugCurrent = String((row as any)?.slug || "") || null;
  }
  for (const item of hot || []) {
    const slug = String((item as any)?.slug || "");
    const reason = String((item as any)?.recommendationReason || "").toLowerCase();
    let b = inferIntervalBucketFromSlug(slug);
    if (!b) {
      if (reason.includes("btc 5m")) b = "5m";
      else if (reason.includes("btc 15m")) b = "15m";
      else if (reason.includes("btc hourly")) b = "hourly";
      else if (reason.includes("btc daily")) b = "daily";
    }
    if (!b || !byBucket[b]) continue;
    byBucket[b].fromHot = true;
    byBucket[b].slugHot = slug || byBucket[b].slugHot;
  }
  for (const b of mustHave) {
    byBucket[b].ok = !!(byBucket[b].fromCurrent && byBucket[b].fromHot);
  }
  const okCount = mustHave.filter((b) => byBucket[b].ok).length;
  return {
    ok: okCount === mustHave.length,
    asOfMs: Date.now(),
    required: mustHave,
    okCount,
    total: mustHave.length,
    byBucket,
  };
}

function dedupeHotMarketsBySlug(items: HotMarket[]): HotMarket[] {
  const bySlug = new Map<string, HotMarket>();
  for (const row of items || []) {
    const slug = String(row?.slug || "").trim();
    if (!slug) continue;
    const prev = bySlug.get(slug);
    if (!prev) {
      bySlug.set(slug, row);
      continue;
    }
    const prevScore = Number(prev.hotScore || 0);
    const nextScore = Number(row.hotScore || 0);
    bySlug.set(slug, nextScore >= prevScore ? row : prev);
  }
  return Array.from(bySlug.values());
}

let latestPnlSnapshotCache:
  | {
      builtAtMs: number;
      filesSig: string;
      snap: Map<string, { pnlUsd: number | null; balanceUsd: number | null; tsMs: number }>;
    }
  | null = null;

function tradeLogFilesSig(files: string[]): string {
  const parts: string[] = [];
  for (const f of files) {
    try {
      const st = fs.statSync(f);
      parts.push(`${path.basename(f)}:${Math.round(Number(st.mtimeMs || 0))}:${Number(st.size || 0)}`);
    } catch {
      parts.push(`${path.basename(f)}:0:0`);
    }
  }
  return parts.join("|");
}

function computeLatestPnlSnapshot(): Map<string, { pnlUsd: number | null; balanceUsd: number | null; tsMs: number }> {
  const out = new Map<string, { pnlUsd: number | null; balanceUsd: number | null; tsMs: number }>();
  const files = listTradeLogFiles();
  const sig = tradeLogFilesSig(files);
  const now = Date.now();
  if (
    latestPnlSnapshotCache &&
    latestPnlSnapshotCache.filesSig === sig &&
    (now - Number(latestPnlSnapshotCache.builtAtMs || 0)) <= SNAPSHOT_CACHE_TTL_MS
  ) {
    return latestPnlSnapshotCache.snap;
  }
  const rows = readJsonlFiles(files);
  for (const r of rows) {
    const slug = String(r?.market?.slug || r?.st?.marketSlug || "").trim();
    if (!slug) continue;
    const action = String(r?.action || "");
    if (!/^(EXIT|STOP)_(UP|DOWN)_(PAPER|LIVE)$/.test(action)) continue;
    const t = Number(r?.t);
    if (!Number.isFinite(t)) continue;
    const runIdRaw = Number(r?.runId);
    const runId = Number.isFinite(runIdRaw) ? Math.floor(runIdRaw) : null;
    const keys = [slug];
    if (runId != null) keys.push(`${runId}:${slug}`);
    const pnlUsdRaw = Number(r?.st?.pnlUsd);
    const balRaw = Number(r?.st?.balanceUsd);
    const nextVal = {
      pnlUsd: Number.isFinite(pnlUsdRaw) ? Number(pnlUsdRaw) : null,
      balanceUsd: Number.isFinite(balRaw) ? Number(balRaw) : null,
      tsMs: t,
    };
    for (const k of keys) {
      const prev = out.get(k);
      if (prev && Number(prev.tsMs) > t) continue;
      out.set(k, nextVal);
    }
  }
  latestPnlSnapshotCache = {
    builtAtMs: now,
    filesSig: sig,
    snap: out,
  };
  return out;
}

function latestSnapshotForBot(
  snap: Map<string, { pnlUsd: number | null; balanceUsd: number | null; tsMs: number }>,
  bot: Pick<BotInstance, "runNum" | "marketSlug" | "marketId">
) {
  const slug = String(bot.marketSlug || bot.marketId || "").trim();
  if (!slug) return null;
  const runNum = Number(bot.runNum);
  const byRun = Number.isFinite(runNum) ? snap.get(`${Math.floor(runNum)}:${slug}`) : null;
  if (byRun) return byRun;
  return snap.get(slug) || null;
}

function floorToIntervalEpoch(tsSec: number, intervalSec: number) {
  const iv = Math.max(60, Math.floor(Number(intervalSec) || 60));
  return tsSec - (tsSec % iv);
}

async function findCurrentMarketForBaseSlugs(
  baseSlugs: string[],
  intervalSec: number
): Promise<{ slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null } | null> {
  const nowSec = Math.floor(Date.now() / 1000);
  const floorTs = floorToIntervalEpoch(nowSec, intervalSec);
  const starts = [floorTs, floorTs + intervalSec, floorTs - intervalSec];
  for (const base of baseSlugs) {
    const baseSlug = String(base || "").trim();
    if (!baseSlug) continue;
    for (const startTs of starts) {
      const slug = `${baseSlug}-${startTs}`;
      const evt = await gammaEventBySlug(slug).catch(() => null);
      if (!evt) continue;
      const markets = evt?.markets;
      if (!Array.isArray(markets) || !markets.length) continue;
      const mkt = markets[0];
      const { up, down } = extractUpDownTokensFromMarket(mkt);
      const volumeUsd = parseMarketVolumeUsd(mkt);
      const endDate = mkt?.endDate ?? evt?.endDate;
      if (!endDate) continue;
      const endMs = parseIsoZ(String(endDate)).getTime();
      const startMs = startTs * 1000;
      const n = Date.now();
      if (n >= startMs && n < endMs) {
        return { slug, startMs, endMs, upToken: up, downToken: down, volumeUsd };
      }
    }
  }
  return null;
}

async function getCurrentBtcIntervalMarkets(): Promise<Array<{ bucket: "5m" | "15m" | "hourly" | "daily"; slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null }>> {
  const out: Array<{ bucket: "5m" | "15m" | "hourly" | "daily"; slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null }> = [];
  const defs: Array<{ bucket: "5m" | "15m" | "hourly" | "daily"; intervalSec: number; baseSlugs: string[] }> = [
    { bucket: "5m", intervalSec: 300, baseSlugs: Array.from(new Set(BTC_INTERVAL_SLUGS["5m"].filter(Boolean))) },
    { bucket: "15m", intervalSec: 900, baseSlugs: Array.from(new Set(BTC_INTERVAL_SLUGS["15m"].filter(Boolean))) },
    { bucket: "hourly", intervalSec: 3600, baseSlugs: Array.from(new Set(BTC_INTERVAL_SLUGS["hourly"].filter(Boolean))) },
    { bucket: "daily", intervalSec: 86400, baseSlugs: Array.from(new Set(BTC_INTERVAL_SLUGS["daily"].filter(Boolean))) },
  ];

  // First pass: discover currently-live interval markets directly from Gamma metadata,
  // which supports human-time slugs like "bitcoin-up-or-down-march-1-5am-et".
  try {
    const rows = await fetchGammaMarkets(260);
    const now = Date.now();
    const byBucket = new Map<"5m" | "15m" | "hourly" | "daily", any>();
    for (const m of rows) {
      if (!isCryptoMarketRelaxed(m)) continue;
      const bucket = marketDurationBucket(m);
      if (!(bucket === "5m" || bucket === "15m" || bucket === "hourly" || bucket === "daily")) continue;
      const startMs =
        parseEpochMsLike(m?.startDate) ??
        parseEpochMsLike(m?.start_time) ??
        parseEpochMsLike(m?.startTime) ??
        parseEpochMsLike(m?.startTimestamp) ??
        parseEpochMsLike(m?.startTs);
      const endMs =
        parseEpochMsLike(m?.endDate) ??
        parseEpochMsLike(m?.end_time) ??
        parseEpochMsLike(m?.endTime) ??
        parseEpochMsLike(m?.endTimestamp) ??
        parseEpochMsLike(m?.endTs);
      if (!(Number.isFinite(Number(startMs)) && Number.isFinite(Number(endMs)) && Number(endMs) > Number(startMs))) continue;
      if (!(now >= Number(startMs) && now < Number(endMs))) continue;
      const prev = byBucket.get(bucket);
      const prevVol = Number(parseMarketVolumeUsd(prev) || 0);
      const vol = Number(parseMarketVolumeUsd(m) || 0);
      if (!prev || vol >= prevVol) byBucket.set(bucket, m);
    }

    for (const [bucket, m] of byBucket.entries()) {
      try {
        const slug = String(m?.slug || m?.marketSlug || "").trim();
        if (!slug) continue;
        const marketStartMs =
          parseEpochMsLike(m?.startDate) ??
          parseEpochMsLike(m?.start_time) ??
          parseEpochMsLike(m?.startTime) ??
          parseEpochMsLike(m?.startTimestamp) ??
          parseEpochMsLike(m?.startTs);
        const marketEndMs =
          parseEpochMsLike(m?.endDate) ??
          parseEpochMsLike(m?.end_time) ??
          parseEpochMsLike(m?.endTime) ??
          parseEpochMsLike(m?.endTimestamp) ??
          parseEpochMsLike(m?.endTs);
        if (!(Number.isFinite(Number(marketStartMs)) && Number.isFinite(Number(marketEndMs)))) continue;
        const evt = await gammaEventBySlug(slug).catch(() => null);
        const mkt = Array.isArray(evt?.markets) && evt?.markets?.length ? evt.markets[0] : m;
        const { up, down } = extractUpDownTokensFromMarket(mkt);
        out.push({
          bucket,
          slug,
          startMs: Number(marketStartMs),
          endMs: Number(marketEndMs),
          upToken: up,
          downToken: down,
          volumeUsd: parseMarketVolumeUsd(mkt),
        });
      } catch {}
    }
  } catch {}

  const seenBuckets = new Set(out.map((x) => x.bucket));
  // Fallback pass: fixed base slug patterns.
  for (const def of defs) {
    if (seenBuckets.has(def.bucket)) continue;
    const one = await findCurrentMarketForBaseSlugs(def.baseSlugs, def.intervalSec).catch(() => null);
    if (!one) continue;
    out.push({ bucket: def.bucket, ...one });
  }
  return out;
}

async function getMostCurrent5mMarket(): Promise<{ slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null }> {
  const baseSlugs = Array.from(new Set([BASE_SLUG, ...BTC_INTERVAL_SLUGS["5m"].filter(Boolean)].map((s) => String(s || "").trim()).filter(Boolean)));
  for (;;) {
    const nowSec = Math.floor(Date.now() / 1000);
    const floorTs = floorTo5mEpoch(nowSec);
    const starts = [floorTs, floorTs - 300, floorTs + 300];
    const candidateRows: Array<{ slug: string; startTs: number }> = [];
    for (const base of baseSlugs) {
      for (const ts of starts) candidateRows.push({ slug: `${base}-${ts}`, startTs: ts });
    }
    const settled = await Promise.all(
      candidateRows.map(async (c) => ({
        slug: c.slug,
        startTs: c.startTs,
        evt: await gammaEventBySlugQuick(c.slug, 900),
      }))
    );
    let best: { slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null } | null = null;
    const n = Date.now();
    for (const row of settled) {
      const evt = row.evt;
      if (!evt) continue;
      const markets = evt?.markets;
      if (!Array.isArray(markets) || !markets.length) continue;
      const mkt = markets[0];
      const { up, down } = extractUpDownTokensFromMarket(mkt);
      const endDate = mkt?.endDate ?? evt?.endDate;
      if (!endDate) continue;
      const endMs = parseIsoZ(String(endDate)).getTime();
      const startMs = Number(row.startTs) * 1000;
      if (!(n >= startMs && n < endMs)) continue;
      const volumeUsd = parseMarketVolumeUsd(mkt);
      const cand = { slug: row.slug, startMs, endMs, upToken: up, downToken: down, volumeUsd };
      if (!best || Number(cand.startMs) > Number(best.startMs)) best = cand;
    }
    if (best) return best;
    await sleep(250);
  }
}

function inferCurrent5mSessionWindow(tsMsRaw: number = Date.now()): { slug: string; startMs: number; endMs: number } {
  const tsMs = Number.isFinite(Number(tsMsRaw)) ? Number(tsMsRaw) : Date.now();
  const startSec = floorTo5mEpoch(Math.floor(tsMs / 1000));
  const startMs = startSec * 1000;
  return {
    slug: `${BASE_SLUG}-${startSec}`,
    startMs,
    endMs: startMs + 5 * 60 * 1000,
  };
}

async function getMostCurrent5mMarketOnce(): Promise<{ slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null } | null> {
  const nowSec = Math.floor(Date.now() / 1000);
  const floorTs = floorTo5mEpoch(nowSec);
  const starts = [floorTs, floorTs - 300, floorTs + 300];
  const baseSlugs = Array.from(new Set([BASE_SLUG, ...BTC_INTERVAL_SLUGS["5m"].filter(Boolean)].map((s) => String(s || "").trim()).filter(Boolean)));
  const candidateRows: Array<{ slug: string; startTs: number }> = [];
  for (const base of baseSlugs) {
    for (const ts of starts) candidateRows.push({ slug: `${base}-${ts}`, startTs: ts });
  }
  const settled = await Promise.all(
    candidateRows.map(async (c) => ({
      slug: c.slug,
      startTs: c.startTs,
      evt: await gammaEventBySlugQuick(c.slug, 500),
    }))
  );
  let best: { slug: string; startMs: number; endMs: number; upToken: string; downToken: string; volumeUsd: number | null } | null = null;
  const n = Date.now();
  for (const row of settled) {
    const evt = row.evt;
    if (!evt) continue;
    const markets = evt?.markets;
    if (!Array.isArray(markets) || !markets.length) continue;
    const mkt = markets[0];
    const { up, down } = extractUpDownTokensFromMarket(mkt);
    const endDate = mkt?.endDate ?? evt?.endDate;
    if (!endDate || !up || !down) continue;
    const endMs = parseIsoZ(String(endDate)).getTime();
    const startMs = Number(row.startTs) * 1000;
    if (!(n >= startMs && n < endMs)) continue;
    const volumeUsd = parseMarketVolumeUsd(mkt);
    const cand = { slug: row.slug, startMs, endMs, upToken: up, downToken: down, volumeUsd };
    if (!best || Number(cand.startMs) > Number(best.startMs)) best = cand;
  }
  return best;
}

function maybeStartCurrent5mMarketResolve(reason: string): void {
  if (current5mMarketResolveInFlight) return;
  const targetSlug = String(current.slug || "").trim();
  if (!targetSlug) return;
  current5mMarketResolveTargetSlug = targetSlug;
  current5mMarketResolveInFlight = (async () => {
    try {
      const next = await getMostCurrent5mMarketOnce();
      if (!next) return;
      if (String(next.slug || "").trim() !== String(current5mMarketResolveTargetSlug || "").trim()) return;
      const prevUpToken = String(current.upToken || "");
      const prevDownToken = String(current.downToken || "");
      const tokensChanged = prevUpToken !== String(next.upToken || "") || prevDownToken !== String(next.downToken || "");
      current = {
        slug: String(next.slug || ""),
        startMs: Number(next.startMs),
        endMs: Number(next.endMs),
        upToken: String(next.upToken || ""),
        downToken: String(next.downToken || ""),
        volumeUsd: Number.isFinite(Number(next.volumeUsd)) ? Number(next.volumeUsd) : null,
      };
      if (tokensChanged) {
        quotePairCache = null;
        lastObservedBids = { upBid: null, downBid: null, tsMs: null };
        lastGoodObservedBids = { upBid: null, downBid: null, tsMs: null };
      }
      console.log(
        `[SESSION TOKENS READY] reason=${reason} slug=${current.slug} up=${current.upToken} down=${current.downToken}`
      );
      broadcast({
        type: "market",
        t: nowMs(),
        current: { slug: current.slug, startMs: current.startMs, endMs: current.endMs, volumeUsd: current.volumeUsd },
      });
      broadcastState();
      ensureQuoteStreamSubscription();
      void quotePumpTick();
    } catch (e: any) {
      console.warn(
        `[SESSION RESOLVE MISS] reason=${reason} slug=${targetSlug} err=${String(e?.message ?? e)}`
      );
    } finally {
      current5mMarketResolveInFlight = null;
      current5mMarketResolveTargetSlug = "";
    }
  })();
}

function maybePrefetch5mSessionWindow(tsMsRaw: number, reason: string): void {
  const inferred = inferCurrent5mSessionWindow(tsMsRaw);
  if (!inferred.slug) return;
  if (getCachedSessionMarketResolution(inferred.slug, inferred.startMs, inferred.endMs)) return;
  void gammaEventBySlugQuick(inferred.slug, 250)
    .then((evt) => {
      rememberSessionMarketResolution(buildSessionMarketResolutionFromEvent(inferred.slug, evt, inferred.startMs));
    })
    .catch(() => {});
}

let lastMarketMetricsRefreshMs = 0;
let marketMetricsRefreshInFlight = false;
async function refreshCurrentMarketMetricsMaybe(force = false) {
  const now = nowMs();
  if (!force && now - lastMarketMetricsRefreshMs < 10_000) return;
  if (!current.slug) return;
  if (marketMetricsRefreshInFlight) return;
  lastMarketMetricsRefreshMs = now;
  marketMetricsRefreshInFlight = true;
  try {
    const evt = await gammaEventBySlugQuick(current.slug, 800);
    const mkt = Array.isArray(evt?.markets) && evt.markets.length ? evt.markets[0] : null;
    if (!mkt) return;
    const volumeUsd = parseMarketVolumeUsd(mkt);
    if (Number.isFinite(Number(volumeUsd))) current.volumeUsd = Number(volumeUsd);
  } catch {
  } finally {
    marketMetricsRefreshInFlight = false;
  }
}

// ===== LIVE balance polling =====
async function refreshLiveBalanceMaybe() {
  // In paper-only mode (or when live creds are absent), skip live balance polling.
  if (!uiLive.enabled) return;
  if (!process.env.POLY_PRIVATE_KEY) {
    const now = nowMs();
    const last = ((refreshLiveBalanceMaybe as any).__lastNoKeyWarnMs ?? 0) as number;
    if (now - last > 30_000) {
      (refreshLiveBalanceMaybe as any).__lastNoKeyWarnMs = now;
      console.warn("[LIVE BAL] Skipping live balance poll: POLY_PRIVATE_KEY not configured");
    }
    return;
  }

  const now = Date.now();
  if (now - liveAccount.lastFetchMs < 4000) return;
  if ((refreshLiveBalanceMaybe as any).__inFlight) return;
  liveAccount.lastFetchMs = now;
  (refreshLiveBalanceMaybe as any).__inFlight = true;
  void (async () => {
    try {
      const client = await getClobClient();
      await (client as any).updateBalanceAllowance?.({ asset_type: "COLLATERAL" });
      const resp = await (client as any).getBalanceAllowance?.({ asset_type: "COLLATERAL" });

      const bal = Number(resp?.balance ?? "0");
      if (Number.isFinite(bal) && bal > 0) {
        liveAccount.balanceUsd = bal / 1e6;
        const nowLog = nowMs();
        const last = Number(((refreshLiveBalanceMaybe as any).__lastBalOkLogMs ?? 0));
        if (!Number.isFinite(last) || nowLog - last > 30_000) {
          (refreshLiveBalanceMaybe as any).__lastBalOkLogMs = nowLog;
          console.log(`[LIVE BAL] updated=${liveAccount.balanceUsd} USDC`);
        }
      } else {
        const nowWarn = nowMs();
        const last = Number(((refreshLiveBalanceMaybe as any).__lastBalWarnMs ?? 0));
        if (!Number.isFinite(last) || nowWarn - last > 30_000) {
          (refreshLiveBalanceMaybe as any).__lastBalWarnMs = nowWarn;
          console.warn(`[LIVE BAL] Zero or invalid balance=${String(bal)}`);
        }
      }
    } catch (e: any) {
      console.error("[LIVE BAL ERROR]", e.message, e.stack);
      broadcast({ type: "status", t: nowMs(), status: `live balance error: ${e.message}` });
    } finally {
      (refreshLiveBalanceMaybe as any).__inFlight = false;
    }
  })();
}

// ===== Trading =====

async function getTickNegRisk(tokenID: string): Promise<{ tickSize: string; negRisk: boolean }> {
  // Cache token metadata to avoid extra RTT before every order.
  const cacheKey = String(tokenID);
  const hit = (getTickNegRisk as any).__cache?.get(cacheKey);
  if (hit) return hit;
  const client = await getClobClient();
  // @ts-ignore
  const tickSize = (await client.getTickSize(tokenID)) || "0.01";
  // @ts-ignore
  const negRisk = Boolean(await client.getNegRisk(tokenID));
  const out = { tickSize: String(tickSize), negRisk };
  if (!(getTickNegRisk as any).__cache) (getTickNegRisk as any).__cache = new Map<string, { tickSize: string; negRisk: boolean }>();
  (getTickNegRisk as any).__cache.set(cacheKey, out);
  return out;
}

function prewarmLatencyCriticalOrderPathForCurrentSession(reason: string): void {
  const tokens = Array.from(new Set(
    [String(current?.upToken || ""), String(current?.downToken || "")]
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  if (!tokens.length) return;
  void getClobClient()
    .then(() => Promise.all(tokens.map(async (tokenId) => {
      try {
        await getTickNegRisk(tokenId);
      } catch (e: any) {
        console.warn(
          `[LATENCY PREWARM WARN] reason=${reason} tokenId=${tokenId} err=${String(e?.message ?? e)}`
        );
      }
    })))
    .catch((e: any) => {
      console.warn(`[LATENCY PREWARM WARN] reason=${reason} client=${String(e?.message ?? e)}`);
    });
}

function myAddressSetFromClient(client: any): Set<string> {
  const signerAddr = String((client as any)?.signer?.address || "").toLowerCase();
  const funderAddr = String((client as any)?.funder || process.env.POLY_FUNDER_ADDRESS || "").toLowerCase();
  return new Set<string>([signerAddr, funderAddr].filter(Boolean));
}

function extractOrderIdLike(raw: any): string | null {
  const candidates = [
    raw?.orderID,
    raw?.orderId,
    raw?.id,
    raw?.order?.orderID,
    raw?.order?.orderId,
    raw?.order?.id,
    raw?.data?.orderID,
    raw?.data?.orderId,
    raw?.data?.id,
    raw?.response?.data?.orderID,
    raw?.response?.data?.orderId,
    raw?.response?.data?.id,
    Array.isArray(raw?.orders) ? raw.orders[0]?.orderID : null,
    Array.isArray(raw?.orders) ? raw.orders[0]?.orderId : null,
    Array.isArray(raw?.orders) ? raw.orders[0]?.id : null,
  ];
  for (const value of candidates) {
    const orderId = String(value || "").trim();
    if (orderId) return orderId;
  }
  return null;
}

function summarizeOrderLike(raw: any): string {
  try {
    return JSON.stringify(raw).slice(0, 400);
  } catch {
    return String(raw);
  }
}

function normalizeLiveVenueErrorText(raw: any): string {
  return String(raw || "").trim().replace(/^\[LIVE EXCHANGE BLOCKED\]\s*/i, "").trim();
}

function extractLiveVenueErrorText(raw: any): string {
  const candidates = [
    raw?.error,
    raw?.message,
    raw?.data?.error,
    raw?.data?.message,
    raw?.response?.data?.error,
    raw?.response?.data?.message,
    raw?.response?.statusText,
    raw?.statusText,
  ];
  for (const value of candidates) {
    const text = normalizeLiveVenueErrorText(value);
    if (text) return text;
  }
  const summary = summarizeOrderLike(raw);
  return normalizeLiveVenueErrorText(summary || "unknown_live_execution_error");
}

function isLiveVenueRegionBlockedError(raw: any): boolean {
  const msg = extractLiveVenueErrorText(raw).toLowerCase();
  return (
    msg.includes("trading restricted in your region") ||
    msg.includes("available regions") ||
    msg.includes("geoblock")
  );
}

function liveExecutionBlockedErrorMessage(reason: string): string {
  return `[LIVE EXCHANGE BLOCKED] ${String(reason || "unknown_reason")}`;
}

function liveKillSwitchErrorMessage(reason: string): string {
  return `[LIVE KILL SWITCH] ${String(reason || "live_disabled")}`;
}

function isLiveTpMinimumSizeError(reasonLike: any): boolean {
  const msg = String(reasonLike?.message ?? reasonLike ?? "").toLowerCase();
  return msg.includes("lower than the minimum");
}

function requiresImmediateVenueTpProtection(strategyIdLike: any): boolean {
  return isMhc3LatencyStrategy(strategyIdLike) || isLatencyProbeStrategy(strategyIdLike);
}

function estimatedLiveSharesForNotional(notionalUsdLike: number, priceLike: number): number {
  const notionalUsd = Number(notionalUsdLike);
  const price = Number(priceLike);
  if (!(Number.isFinite(notionalUsd) && notionalUsd > 0 && Number.isFinite(price) && price > 0 && price < 1)) return 0;
  return floorTo6(Math.max(0, notionalUsd / price));
}

async function armBotRuntimeImmediateTpOrder(
  instance: BotInstance,
  rt: BotRuntime,
  meta: {
    side: OutcomeSide;
    entryPx: number;
    shares: number;
    enterModeLike?: string | null;
    acceptedAtMs?: number | null;
    buyOrderId?: string | null;
    source?: string | null;
    retryAttempts?: number | null;
  }
): Promise<string | null> {
  if (!shouldUseRealLiveExecutionForBot(instance)) return null;
  if (!requiresImmediateVenueTpProtection(instance.strategyId)) return null;
  if (isInflectionPositiveSlopeFamilyStrategy(instance.strategyId)) return null;
  const rtAny = rt as any;
  const side = meta.side === "UP" || meta.side === "DOWN" ? meta.side : null;
  const entryPx = Number(meta.entryPx);
  const shares = Number(meta.shares);
  if (!side) return null;
  if (!(Number.isFinite(entryPx) && entryPx > 0 && Number.isFinite(shares) && shares > 0)) return null;
  if (rtAny.__liveExitInProgress || rtAny.__suppressTpRearmUntilFlat) return null;
  const existingTpOrderId = String(rtAny.tpOrderId || "").trim();
  if (existingTpOrderId) return existingTpOrderId;
  if (rtAny.tpOrderInFlight) return null;

  const tokenId = runtimeTokenIdForSide(rt, side);
  const botUi = buildUiConfigForBotInstance(instance);
  const tpPx = computeImmediateTpSellPx(botUi, entryPx);
  const acceptedAtMs =
    Number.isFinite(Number(meta.acceptedAtMs)) && Number(meta.acceptedAtMs) > 0
      ? Number(meta.acceptedAtMs)
      : nowMs();
  const attempts = Math.max(1, Math.min(3, Number(meta.retryAttempts || 2)));

  if (!tokenId) {
    const errMsg = `missing runtime tokenId for early TP side=${side}`;
    appendBotRunEvent(instance, rt, {
      event: "tp_arm_failed",
      side,
      exitType: "exit",
      exitReasonRaw: "BOT_LIVE_TP_LIMIT_FAILED_AFTER_ENTRY_ORDER",
      exitPx: tpPx,
      sharesRequested: shares,
      mode: meta.enterModeLike || null,
      executionMode: "real",
      fillSource: "live_exchange",
      orderId: String(meta.buyOrderId || "").trim() || null,
      error: errMsg,
      source: String(meta.source || "entry_order_accept"),
    });
    rt.lastError = errMsg;
    rt.lastAction = "tp_arm_failed_after_entry_order";
    return null;
  }

  rtAny.tpOrderInFlight = true;
  rtAny.pendingTpLimitPx = tpPx;
  rtAny.pendingExitType = "exit";
  try {
    for (let attempt = 1; attempt <= attempts; attempt++) {
      try {
        const tp = await placeImmediateTpSellAfterBuy(side, shares, botUi, tokenId, {
          source: String(meta.source || "entry_order_accept"),
          entryFillPx: entryPx,
          buyFilledAtMs: acceptedAtMs,
          strategyId: instance.strategyId,
          fastPath: isLatencyProbeStrategy(instance.strategyId),
          limitPxOverride: tpPx,
          exitType: "EXIT",
        });
        rtAny.pendingTpLimitPx = tpPx;
        rtAny.pendingTpShares = Number(tp.placedShares);
        rtAny.pendingTpExitType = "exit";
        rtAny.tpOrderId = tp.orderId;
        rtAny.__tpAccountedFilledShares = 0;
        rt.lastError = null;
        rt.lastAction = "tp_order_placed_after_entry_order";
        appendBotRunEvent(instance, rt, {
          event: "exit_order",
          side,
          exitType: "exit",
          exitReasonRaw: "BOT_LIVE_TP_LIMIT_PLACED_AFTER_ENTRY_ORDER",
          exitPx: tpPx,
          sharesRequested: Number(tp.placedShares),
          ttlMs: null,
          mode: meta.enterModeLike || null,
          executionMode: "real",
          fillSource: "live_exchange",
          orderId: tp.orderId,
          source: String(meta.source || "entry_order_accept"),
          parentOrderId: String(meta.buyOrderId || "").trim() || null,
        });
        return tp.orderId;
      } catch (e: any) {
        const errMsg = extractLiveVenueErrorText(e);
        appendBotRunEvent(instance, rt, {
          event: "tp_arm_failed",
          side,
          exitType: "exit",
          exitReasonRaw:
            attempt < attempts
              ? "BOT_LIVE_TP_LIMIT_FAILED_AFTER_ENTRY_ORDER_RETRYING"
              : "BOT_LIVE_TP_LIMIT_FAILED_AFTER_ENTRY_ORDER",
          exitPx: tpPx,
          sharesRequested: shares,
          ttlMs: null,
          mode: meta.enterModeLike || null,
          executionMode: "real",
          fillSource: "live_exchange",
          orderId: String(meta.buyOrderId || "").trim() || null,
          error: errMsg,
          source: String(meta.source || "entry_order_accept"),
          tpRetryAttempt: attempt,
        });
        rt.lastError = errMsg;
        rt.lastAction = "tp_arm_failed_after_entry_order";
        if (attempt < attempts) {
          await sleep(75);
          continue;
        }
      }
    }
  } finally {
    rtAny.tpOrderInFlight = false;
  }
  return null;
}

async function suppressBotRuntimeTpProtectionForStopSignal(
  instance: BotInstance,
  rt: BotRuntime,
  reasonTag: string,
  runtimeTokenId?: string | null
): Promise<void> {
  const rtAny = rt as any;
  rtAny.__suppressTpRearmUntilFlat = true;
  rtAny.__liveExitInProgress = true;
  rtAny.tpOrderInFlight = false;
  rtAny.tpOrderId = null;
  rtAny.pendingTpLimitPx = null;
  rtAny.pendingTpShares = null;
  rtAny.pendingTpExitType = null;
  clearBotRuntimeRunnerTpArtifacts(rt);
  try {
    await cancelOpenSellOrdersForSide(rt.side as OutcomeSide, `${reasonTag}-cancel_tp_on_stop_signal`, runtimeTokenId || null);
  } catch (e: any) {
    console.warn(
      `[BOT STOP TP CANCEL WARN] inst=${instance.instanceId} run=${instance.runNum} side=${String(rt.side || "")} ` +
      `reason=${reasonTag} err=${String(e?.message ?? e)}`
    );
  }
}

function buildLiveTpMinimumSizeBlockMessage(meta: {
  strategyId?: string | null;
  instanceId?: string | null;
  runNum?: number | null;
  side?: OutcomeSide | null;
  notionalUsd?: number | null;
  estimatedBuyPx?: number | null;
  estimatedShares?: number | null;
  tpPx?: number | null;
}): string {
  return (
    `TP_IMPOSSIBLE_MIN_SIZE strategy=${String(meta.strategyId || "")} ` +
    `inst=${String(meta.instanceId || "")} run=${Number(meta.runNum || 0)} side=${String(meta.side || "")} ` +
    `notionalUsd=${roundTo6(Number(meta.notionalUsd || 0))} ` +
    `estBuyPx=${roundTo6(Number(meta.estimatedBuyPx || 0))} ` +
    `estShares=${roundTo6(Number(meta.estimatedShares || 0))} ` +
    `tpPx=${roundTo6(Number(meta.tpPx || 0))} minSellableShares=${roundTo6(LIVE_MIN_SELLABLE_SHARES)}`
  );
}

function assertLiveOrderSubmissionAllowed(action: string): void {
  if (uiLive.enabled) return;
  const msg = liveKillSwitchErrorMessage(`${action}:live_disabled`);
  console.warn(msg);
  throw new Error(msg);
}

function clearLiveExecutionHardBlock(reason: string): void {
  if (!liveExecutionHardBlockedReason && !liveExecutionHardBlockedAtMs && !liveExecutionHardBlockedSource) return;
  console.warn(
    `[LIVE HARD BLOCK CLEAR] reason=${reason} prev=${liveExecutionHardBlockedReason ?? "-"} ` +
    `source=${liveExecutionHardBlockedSource ?? "-"}`
  );
  liveExecutionHardBlockedReason = null;
  liveExecutionHardBlockedAtMs = null;
  liveExecutionHardBlockedSource = null;
  writeRuntimeStateSnapshot();
}

function noteLiveExecutionHardBlock(reasonLike: any, source: string): string | null {
  if (!isLiveVenueRegionBlockedError(reasonLike)) return null;
  const reason = extractLiveVenueErrorText(reasonLike);
  const blockedMsg = liveExecutionBlockedErrorMessage(reason);
  const alreadyBlocked =
    liveExecutionHardBlockedReason === reason &&
    liveExecutionHardBlockedSource === source &&
    uiLive.enabled === false;

  liveExecutionHardBlockedReason = reason;
  liveExecutionHardBlockedAtMs = nowMs();
  liveExecutionHardBlockedSource = source;
  uiLive.enabled = false;
  if (pendingUiLive) pendingUiLive.enabled = false;
  liveManualEnabledOverride = false;
  stLive.enterInFlight = false;
  stLive.exitInFlight = false;
  stLive.tpOrderInFlight = false;

  let botsChanged = false;
  for (const instance of activeBotInstances()) {
    if (!isRealLiveCapableBotInstance(instance)) continue;
    const prevStatus = String(instance.status || "");
    const prevError = String(instance.lastError || "");
    if (prevStatus !== "error" || prevError !== blockedMsg) {
      instance.status = "error";
      instance.lastError = blockedMsg;
      botInstances.set(instance.instanceId, instance);
      botsChanged = true;
    }
    const rt = botRuntimes.get(instance.instanceId);
    if (rt) {
      rt.lastError = blockedMsg;
      rt.lastAction = "live_execution_blocked";
      botRuntimes.set(instance.instanceId, rt);
    }
  }
  if (botsChanged) persistMultiMarketState();
  if (!alreadyBlocked) {
    console.error(`[LIVE HARD BLOCK] source=${source} reason=${reason}`);
    broadcast({
      type: "status",
      t: nowMs(),
      status: `LIVE DISABLED venue_blocked source=${source} reason=${reason}`,
    });
    broadcastState();
    writeRuntimeStateSnapshot();
    void enforceLiveDisableKillSwitch(`venue_blocked_${source}`);
  }
  return reason;
}

function maybeThrowLiveExecutionHardBlock(reasonLike: any, source: string): void {
  const reason = noteLiveExecutionHardBlock(reasonLike, source);
  if (reason) throw new Error(liveExecutionBlockedErrorMessage(reason));
}

async function inferRecentBuyFillFromTrades(
  client: any,
  tokenId: string,
  fallbackPx: number,
  startedAtMs: number
): Promise<{ filledPx: number; shares: number; firstFillTsMs: number | null; lastFillTsMs: number | null } | null> {
  const trades = await (client as any).getTrades?.({ asset_id: tokenId }, true);
  const list = coerceTradesList(trades);
  const mine = myAddressSetFromClient(client);
  let inferredShares = 0;
  let inferredNotional = 0;
  let firstFillTsMs: number | null = null;
  let lastFillTsMs: number | null = null;
  for (const tr of list) {
    const tsMs = tradeTsMs(tr);
    if (Number.isFinite(tsMs as number) && (tsMs as number) < startedAtMs - 10_000) continue;
    const delta = signedTradeDeltaForMe(tr, mine);
    if (delta <= 0) continue;
    const px = Number(tr?.price ?? tr?.avgPrice ?? tr?.avg_fill_price ?? fallbackPx);
    const usePx = Number.isFinite(px) && px > 0 ? px : fallbackPx;
    inferredShares += delta;
    inferredNotional += delta * usePx;
    if (Number.isFinite(Number(tsMs))) {
      const tradeTime = Number(tsMs);
      firstFillTsMs = Number.isFinite(Number(firstFillTsMs)) ? Math.min(Number(firstFillTsMs), tradeTime) : tradeTime;
      lastFillTsMs = Number.isFinite(Number(lastFillTsMs)) ? Math.max(Number(lastFillTsMs), tradeTime) : tradeTime;
    }
  }
  if (!(inferredShares > 0)) return null;
  const inferredPx = inferredNotional > 0 ? inferredNotional / inferredShares : fallbackPx;
  return { filledPx: inferredPx, shares: inferredShares, firstFillTsMs, lastFillTsMs };
}

async function inferRecentSellFillFromTrades(
  client: any,
  tokenId: string,
  fallbackPx: number,
  startedAtMs: number
): Promise<{ filledPx: number; shares: number; firstFillTsMs: number | null; lastFillTsMs: number | null } | null> {
  const trades = await (client as any).getTrades?.({ asset_id: tokenId }, true);
  const list = coerceTradesList(trades);
  const mine = myAddressSetFromClient(client);
  let inferredShares = 0;
  let inferredNotional = 0;
  let firstFillTsMs: number | null = null;
  let lastFillTsMs: number | null = null;
  for (const tr of list) {
    const tsMs = tradeTsMs(tr);
    if (Number.isFinite(tsMs as number) && (tsMs as number) < startedAtMs - 10_000) continue;
    const delta = signedTradeDeltaForMe(tr, mine);
    if (delta >= 0) continue;
    const px = Number(tr?.price ?? tr?.avgPrice ?? tr?.avg_fill_price ?? fallbackPx);
    const usePx = Number.isFinite(px) && px > 0 ? px : fallbackPx;
    const soldShares = Math.abs(delta);
    inferredShares += soldShares;
    inferredNotional += soldShares * usePx;
    if (Number.isFinite(Number(tsMs))) {
      const tradeTime = Number(tsMs);
      firstFillTsMs = Number.isFinite(Number(firstFillTsMs)) ? Math.min(Number(firstFillTsMs), tradeTime) : tradeTime;
      lastFillTsMs = Number.isFinite(Number(lastFillTsMs)) ? Math.max(Number(lastFillTsMs), tradeTime) : tradeTime;
    }
  }
  if (!(inferredShares > 0)) return null;
  const inferredPx = inferredNotional > 0 ? inferredNotional / inferredShares : fallbackPx;
  return { filledPx: inferredPx, shares: inferredShares, firstFillTsMs, lastFillTsMs };
}

async function explicitTradeFillForOrderId(
  client: any,
  orderId: string,
  tokenId: string | null,
  startedAtMs: number
): Promise<{ filledPx: number; shares: number; firstFillTsMs: number; lastFillTsMs: number } | null> {
  const wantedOrderId = String(orderId || "").trim();
  if (!wantedOrderId) return null;
  const params: any = {};
  if (String(tokenId || "").trim()) params.asset_id = String(tokenId).trim();
  const trades = await (client as any).getTrades?.(params, true);
  const list = coerceTradesList(trades);
  const seen = new Set<string>();
  let totalShares = 0;
  let totalNotional = 0;
  let firstFillTsMs: number | null = null;
  let lastFillTsMs: number | null = null;
  for (const tr of list) {
    if (String(tr?.taker_order_id || "").trim() !== wantedOrderId) continue;
    const tsMs = tradeTsMs(tr);
    if (!(Number.isFinite(Number(tsMs)) && Number(tsMs) > 0)) continue;
    if (Number(tsMs) < startedAtMs - 10_000) continue;
    const px = Number(tr?.price ?? tr?.avgPrice ?? tr?.avg_fill_price ?? tr?.matched_price ?? NaN);
    const shares = Number(tr?.size ?? tr?.matched_amount ?? tr?.amount ?? NaN);
    if (!(Number.isFinite(px) && px > 0 && Number.isFinite(shares) && shares > 0)) continue;
    const dedupeKey =
      String(tr?.id || "").trim() ||
      `${Number(tsMs)}|${Number(px).toFixed(6)}|${Number(shares).toFixed(6)}`;
    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);
    totalShares += Number(shares);
    totalNotional += Number(shares) * Number(px);
    firstFillTsMs = Number.isFinite(Number(firstFillTsMs)) ? Math.min(Number(firstFillTsMs), Number(tsMs)) : Number(tsMs);
    lastFillTsMs = Number.isFinite(Number(lastFillTsMs)) ? Math.max(Number(lastFillTsMs), Number(tsMs)) : Number(tsMs);
  }
  if (!(Number.isFinite(totalShares) && totalShares > 0 && Number.isFinite(totalNotional) && totalNotional > 0)) return null;
  if (!(Number.isFinite(Number(firstFillTsMs)) && Number(firstFillTsMs) > 0)) return null;
  return {
    filledPx: totalNotional / totalShares,
    shares: totalShares,
    firstFillTsMs: Number(firstFillTsMs),
    lastFillTsMs: Number.isFinite(Number(lastFillTsMs)) && Number(lastFillTsMs) > 0
      ? Number(lastFillTsMs)
      : Number(firstFillTsMs),
  };
}

async function collectSessionVenueTruthForTokens(
  client: any,
  slug: string,
  tokenBySide: { UP?: string | null; DOWN?: string | null }
): Promise<Record<string, any> | null> {
  const startMs = inferSessionStartMsFromSlug(slug);
  if (!(Number.isFinite(Number(startMs)) && Number(startMs) > 0)) return null;
  const endMs = Number(startMs) + 300_000;
  const mine = myAddressSetFromClient(client);
  const walletAddresses = Array.from(mine.values());
  const fills: any[] = [];
  const bySide: Record<string, any> = {};

  for (const side of ["UP", "DOWN"] as const) {
    const tokenId = String(tokenBySide?.[side] || "").trim();
    if (!tokenId) continue;
    let tradesRaw: any = null;
    try {
      tradesRaw = await (client as any).getTrades?.({ asset_id: tokenId }, true);
    } catch {
      continue;
    }
    const list = coerceTradesList(tradesRaw);
    let buyShares = 0;
    let buyNotional = 0;
    let sellShares = 0;
    let sellNotional = 0;
    for (const tr of list) {
      const tsMs = tradeTsMs(tr);
      if (!(Number.isFinite(Number(tsMs)) && Number(tsMs) >= Number(startMs) - 120_000 && Number(tsMs) <= Number(endMs) + 120_000)) continue;
      const delta = signedTradeDeltaForMe(tr, mine);
      if (!Number.isFinite(Number(delta)) || Math.abs(Number(delta)) <= 1e-9) continue;
      const pxRaw = Number(tr?.price ?? tr?.avgPrice ?? tr?.avg_fill_price ?? tr?.matched_price ?? NaN);
      if (!(Number.isFinite(pxRaw) && pxRaw > 0)) continue;
      const sharesAbs = Math.abs(Number(delta));
      const dir = Number(delta) > 0 ? "BUY" : "SELL";
      fills.push({
        slug,
        side,
        tokenId,
        tsMs: Number(tsMs),
        iso: new Date(Number(tsMs)).toISOString(),
        dir,
        price: roundTo6(pxRaw),
        shares: roundTo6(sharesAbs),
        notionalUsd: roundTo6(pxRaw * sharesAbs),
        tradeId: String(tr?.id || tr?.trade_id || "").trim() || null,
        orderId: String(tr?.taker_order_id || tr?.maker_order_id || "").trim() || null,
        assetId: String(tr?.asset_id || tr?.assetId || tr?.token_id || tr?.tokenId || tokenId).trim(),
      });
      if (dir === "BUY") {
        buyShares += sharesAbs;
        buyNotional += sharesAbs * pxRaw;
      } else {
        sellShares += sharesAbs;
        sellNotional += sharesAbs * pxRaw;
      }
    }
    bySide[side] = {
      tokenId,
      buyShares: roundTo6(buyShares),
      avgBuyPx: buyShares > 0 ? roundTo6(buyNotional / buyShares) : null,
      sellShares: roundTo6(sellShares),
      avgSellPx: sellShares > 0 ? roundTo6(sellNotional / sellShares) : null,
    };
  }

  fills.sort((a, b) => Number(a?.tsMs || 0) - Number(b?.tsMs || 0));
  return {
    slug,
    startMs: Number(startMs),
    endMs,
    fillCount: fills.length,
    fills,
    bySide,
    walletAddresses,
    truthSource: "venue_trade_history",
  };
}

const sessionVenueTruthCaptureInFlight = new Set<string>();

function captureBotRunSessionVenueTruth(
  instance: BotInstance,
  slug: string,
  tokenBySide: { UP?: string | null; DOWN?: string | null },
  reason: string
): void {
  if (!shouldUseRealLiveExecutionForBot(instance)) return;
  const safeSlug = String(slug || "").trim();
  if (!safeSlug) return;
  const upToken = String(tokenBySide?.UP || "").trim();
  const downToken = String(tokenBySide?.DOWN || "").trim();
  if (!upToken && !downToken) return;
  const key = `${Math.floor(Number(instance.runNum || 0))}:${safeSlug}`;
  if (sessionVenueTruthCaptureInFlight.has(key)) return;
  sessionVenueTruthCaptureInFlight.add(key);
  void (async () => {
    try {
      const client = await getClobClient();
      const venueTruth = await collectSessionVenueTruthForTokens(client as any, safeSlug, {
        UP: upToken || null,
        DOWN: downToken || null,
      });
      appendBotRunSessionVenueTruth(Number(instance.runNum || 0), {
        runNum: Number(instance.runNum || 0),
        runId: String(instance.runId || ""),
        instanceId: String(instance.instanceId || ""),
        strategyId: String(instance.strategyId || ""),
        reconciliationReason: String(reason || "session_rollover"),
        ...(venueTruth || {
          slug: safeSlug,
          startMs: inferSessionStartMsFromSlug(safeSlug),
          endMs: Number(inferSessionStartMsFromSlug(safeSlug) || 0) + 300_000,
          fillCount: 0,
          fills: [],
          bySide: {
            UP: { tokenId: upToken || null, buyShares: 0, avgBuyPx: null, sellShares: 0, avgSellPx: null },
            DOWN: { tokenId: downToken || null, buyShares: 0, avgBuyPx: null, sellShares: 0, avgSellPx: null },
          },
          walletAddresses: [],
          truthSource: "venue_trade_history_empty",
        }),
      });
    } catch (e: any) {
      console.warn(
        `[SESSION VENUE TRUTH] capture failed instance=${instance.instanceId} slug=${safeSlug} reason=${reason} err=${String(e?.message ?? e)}`
      );
      try {
        appendBotRunSessionVenueTruth(Number(instance.runNum || 0), {
          runNum: Number(instance.runNum || 0),
          runId: String(instance.runId || ""),
          instanceId: String(instance.instanceId || ""),
          strategyId: String(instance.strategyId || ""),
          slug: safeSlug,
          startMs: inferSessionStartMsFromSlug(safeSlug),
          endMs: Number(inferSessionStartMsFromSlug(safeSlug) || 0) + 300_000,
          fillCount: 0,
          fills: [],
          bySide: {
            UP: { tokenId: upToken || null, buyShares: 0, avgBuyPx: null, sellShares: 0, avgSellPx: null },
            DOWN: { tokenId: downToken || null, buyShares: 0, avgBuyPx: null, sellShares: 0, avgSellPx: null },
          },
          walletAddresses: [],
          reconciliationReason: String(reason || "session_rollover"),
          truthSource: "venue_trade_history_error",
          reconciliationError: String(e?.message ?? e),
        });
      } catch {}
    } finally {
      sessionVenueTruthCaptureInFlight.delete(key);
    }
  })();
}

function userStreamFillSnapshot(orderId: string | null | undefined): {
  filledPx: number;
  shares: number;
  filledAtMs: number | null;
  entryEventTsMs: number | null;
} | null {
  const state = getUserStreamOrderState(orderId);
  if (!state) return null;
  const shares = Math.max(
    Number(state.totalMatchedShares || 0),
    Number(state.orderMatchedShares || 0)
  );
  if (!(Number.isFinite(shares) && shares > 0)) return null;
  const filledAtMs =
    extractUserStreamTsMs(state.firstMatchedAtMs) ??
    extractUserStreamTsMs(state.lastMatchedAtMs) ??
    extractUserStreamTsMs(state.confirmedAtMs) ??
    extractUserStreamTsMs(state.minedAtMs) ??
    extractUserStreamTsMs(state.lastOrderUpdateAtMs) ??
    null;
  const entryEventTsMs =
    extractUserStreamTsMs(state.placedAtMs) ??
    extractUserStreamTsMs(state.lastOrderUpdateAtMs) ??
    filledAtMs;
  const filledPx = Number.isFinite(Number(state.fillPx)) && Number(state.fillPx) > 0
    ? Number(state.fillPx)
    : NaN;
  return {
    filledPx,
    shares,
    filledAtMs,
    entryEventTsMs,
  };
}

function userStreamPrimaryFillSnapshot(orderId: string | null | undefined): {
  filledPx: number;
  shares: number;
  filledAtMs: number;
  entryEventTsMs: number | null;
} | null {
  const snapshot = userStreamFillSnapshot(orderId);
  if (!snapshot) return null;
  if (!(Number.isFinite(Number(snapshot.filledPx)) && Number(snapshot.filledPx) > 0)) return null;
  if (!(Number.isFinite(Number(snapshot.shares)) && Number(snapshot.shares) > 0)) return null;
  if (!(Number.isFinite(Number(snapshot.filledAtMs)) && Number(snapshot.filledAtMs) > 0)) return null;
  return {
    filledPx: Number(snapshot.filledPx),
    shares: Number(snapshot.shares),
    filledAtMs: Number(snapshot.filledAtMs),
    entryEventTsMs:
      Number.isFinite(Number(snapshot.entryEventTsMs)) && Number(snapshot.entryEventTsMs) > 0
        ? Number(snapshot.entryEventTsMs)
        : null,
  };
}

async function resolveLiveOrderFillSnapshot(
  client: any,
  orderId: string | null | undefined,
  tokenId: string | null,
  startedAtMsRaw: number | null | undefined
): Promise<{
  filledPx: number;
  shares: number;
  filledAtMs: number | null;
  entryEventTsMs: number | null;
  source: "user_stream" | "trade_history" | "order_status";
} | null> {
  const wantedOrderId = String(orderId || "").trim();
  if (!wantedOrderId) return null;
  const wsFill = userStreamPrimaryFillSnapshot(wantedOrderId);
  if (wsFill) {
    return {
      filledPx: Number(wsFill.filledPx),
      shares: Number(wsFill.shares),
      filledAtMs: Number(wsFill.filledAtMs),
      entryEventTsMs:
        Number.isFinite(Number(wsFill.entryEventTsMs)) && Number(wsFill.entryEventTsMs) > 0
          ? Number(wsFill.entryEventTsMs)
          : null,
      source: "user_stream",
    };
  }

  const startedAtMs =
    Number.isFinite(Number(startedAtMsRaw)) && Number(startedAtMsRaw) > 0
      ? Number(startedAtMsRaw)
      : (nowMs() - 60_000);
  const tradeFill = await explicitTradeFillForOrderId(client, wantedOrderId, tokenId, startedAtMs).catch(() => null);
  if (
    tradeFill &&
    Number.isFinite(Number(tradeFill.filledPx)) &&
    Number(tradeFill.filledPx) > 0 &&
    Number.isFinite(Number(tradeFill.shares)) &&
    Number(tradeFill.shares) > 0
  ) {
    return {
      filledPx: Number(tradeFill.filledPx),
      shares: Number(tradeFill.shares),
      filledAtMs:
        Number.isFinite(Number(tradeFill.firstFillTsMs)) && Number(tradeFill.firstFillTsMs) > 0
          ? Number(tradeFill.firstFillTsMs)
          : null,
      entryEventTsMs:
        Number.isFinite(Number(tradeFill.firstFillTsMs)) && Number(tradeFill.firstFillTsMs) > 0
          ? Number(tradeFill.firstFillTsMs)
          : null,
      source: "trade_history",
    };
  }

  try {
    const ord = await (client as any).getOrder(wantedOrderId);
    const filledShares = extractOrderMatchedShares(ord);
    const filledPxRaw = Number(extractOrderAvgFillPx(ord) ?? NaN);
    const filledAtMs = extractOrderFillTsMs(ord);
    if (
      Number.isFinite(filledShares) &&
      filledShares > 0 &&
      Number.isFinite(filledPxRaw) &&
      filledPxRaw > 0
    ) {
      return {
        filledPx: filledPxRaw,
        shares: filledShares,
        filledAtMs:
          Number.isFinite(Number(filledAtMs)) && Number(filledAtMs) > 0
            ? Number(filledAtMs)
            : null,
        entryEventTsMs:
          Number.isFinite(Number(extractOrderEntryTsMs(ord))) && Number(extractOrderEntryTsMs(ord)) > 0
            ? Number(extractOrderEntryTsMs(ord))
            : (
                Number.isFinite(Number(filledAtMs)) && Number(filledAtMs) > 0
                  ? Number(filledAtMs)
                  : null
              ),
        source: "order_status",
      };
    }
  } catch {}
  return null;
}

async function confirmRecentBuyFillFast(
  client: any,
  tokenId: string,
  fallbackPx: number,
  startedAtMs: number,
  orderId?: string | null
): Promise<{ filledPx: number; shares: number; filledAtMs: number | null; entryEventTsMs: number | null; fillTimestampSource: "order_timeline" | "trade_infer" } | null> {
  const deadline = nowMs() + BUY_FAST_CONFIRM_WINDOW_MS;
  while (nowMs() <= deadline) {
    if (orderId) {
      const wsFill = userStreamFillSnapshot(orderId);
      if (wsFill && wsFill.shares > 0) {
        return {
          filledPx: Number.isFinite(Number(wsFill.filledPx)) && Number(wsFill.filledPx) > 0 ? Number(wsFill.filledPx) : fallbackPx,
          shares: Number(wsFill.shares),
          filledAtMs: wsFill.filledAtMs,
          entryEventTsMs: wsFill.entryEventTsMs,
          fillTimestampSource: "order_timeline",
        };
      }
      try {
        const ord = await (client as any).getOrder(orderId);
        const filledSharesRaw = extractOrderMatchedShares(ord);
        const avgPxRaw = Number(extractOrderAvgFillPx(ord) ?? NaN);
        if (Number.isFinite(filledSharesRaw) && filledSharesRaw > 0) {
          return {
            filledPx: Number.isFinite(avgPxRaw) && avgPxRaw > 0 ? avgPxRaw : fallbackPx,
            shares: filledSharesRaw,
            filledAtMs: extractOrderFillTsMs(ord),
            entryEventTsMs: extractOrderEntryTsMs(ord) ?? extractOrderFillTsMs(ord),
            fillTimestampSource: "order_timeline",
          };
        }
      } catch {}
    }
    try {
      const inferred = await inferRecentBuyFillFromTrades(client as any, tokenId, fallbackPx, startedAtMs);
      if (inferred && inferred.shares > 0) {
        return {
          filledPx: inferred.filledPx,
          shares: inferred.shares,
          filledAtMs: inferred.firstFillTsMs,
          entryEventTsMs: inferred.firstFillTsMs,
          fillTimestampSource: "trade_infer",
        };
      }
    } catch {}
    const waitMs = Math.max(5, Math.min(40, deadline - nowMs()));
    if (orderId) {
      await waitForUserStreamOrderState(
        orderId,
        (state) => {
          if (!state) return false;
          return (
            Math.max(Number(state.totalMatchedShares || 0), Number(state.orderMatchedShares || 0)) > 0
          );
        },
        waitMs
      ).catch(() => null);
    } else {
      await sleep(waitMs);
    }
  }
  return null;
}

async function getLiveTokenPositionShares(client: any, tokenId: string): Promise<number | null> {
  try {
    const positions =
      (await (client as any).getPositions?.()) ??
      (await (client as any).getOpenPositions?.()) ??
      null;
    const posList = Array.isArray(positions) ? positions : [];
    if (posList.length) {
      const p = posList.find(
        (x: any) => String(x?.asset_id ?? x?.assetId ?? x?.token_id ?? x?.tokenId ?? "") === String(tokenId)
      );
      const v = Number(p?.size ?? p?.position ?? p?.shares ?? p?.quantity ?? p?.balance ?? 0);
      return Number.isFinite(v) ? Math.max(0, v) : 0;
    }
  } catch (e: any) {
    console.warn(`[POSITION SHARES] positions lookup failed tokenId=${tokenId}: ${String(e?.message ?? e)}`);
  }

  try {
    const trades = await (client as any).getTrades?.({ asset_id: tokenId }, true);
    const list = coerceTradesList(trades);
    const mine = myAddressSetFromClient(client);
    let net = 0;
    for (const tr of list) net += signedTradeDeltaForMe(tr, mine);
    return Math.max(0, net);
  } catch (e: any) {
    console.warn(`[POSITION SHARES] trade fallback failed tokenId=${tokenId}: ${String(e?.message ?? e)}`);
  }

  return null;
}

async function reconcileLiveSharesFromPosition(
  st: TradeState,
  side: OutcomeSide,
  reason: string
): Promise<void> {
  try {
    const tokenId = String(st.positionTokenId || tokenIdForSide(side) || "");
    if (!tokenId) return;
    const client = await getClobClient();
    const posShares = await getLiveTokenPositionShares(client as any, tokenId);
    if (!Number.isFinite(posShares as number)) return;
    const pos = floorTo6(Math.max(0, Number(posShares)));
    if (!(pos > 0)) return;
    const cur = floorTo6(Math.max(0, Number(st.shares ?? 0)));
    if (pos > cur + 1e-9) {
      console.warn(
        `[LIVE SHARES RECONCILE] reason=${reason} side=${side} shares=${roundTo6(cur)} -> ${roundTo6(pos)} tokenId=${tokenId}`
      );
      st.shares = pos;
    }
  } catch {}
}

function normalizeConditionalUnits(raw: any): number | null {
  const v = Number(raw);
  if (!Number.isFinite(v) || v < 0) return null;
  // CLOB allowance/balance fields are commonly 1e6-scaled.
  return v > 100000 ? v / 1e6 : v;
}

function normalizeAllowanceUnits(raw: any): number | null {
  if (raw === null || raw === undefined || raw === "") return null;
  const s = String(raw).trim();
  if (!s) return null;
  // Large uint approvals are commonly returned as full-precision strings.
  if (/^\d+$/.test(s)) {
    try {
      const bi = BigInt(s);
      if (bi <= 0n) return 0;
      if (bi > BigInt(Number.MAX_SAFE_INTEGER)) return Number.MAX_SAFE_INTEGER;
      return Number(bi);
    } catch {}
  }
  const n = Number(s);
  if (!Number.isFinite(n) || n < 0) return null;
  return n > Number.MAX_SAFE_INTEGER ? Number.MAX_SAFE_INTEGER : n;
}

function shouldClampImmediateTpToVerifiedShares(
  requestedShares: number,
  verifiedAvailableShares: number
): boolean {
  const requested = floorTo6(Math.max(0, Number(requestedShares || 0)));
  const verified = floorTo6(Math.max(0, Number(verifiedAvailableShares || 0)));
  if (!(requested > 1e-6 && verified > 1e-6)) return false;
  if (!(verified < requested - 1e-6)) return false;
  return verified <= (requested * 0.75);
}

async function getConditionalBalanceAllowanceShares(client: any, tokenId: string): Promise<{
  balanceShares: number | null;
  allowanceShares: number | null;
  allowanceSpenderCount: number;
  error: string | null;
}> {
  try {
    await (client as any).updateBalanceAllowance?.({ asset_type: "CONDITIONAL", token_id: tokenId });
    const resp = await (client as any).getBalanceAllowance?.({ asset_type: "CONDITIONAL", token_id: tokenId });
    let allowance = normalizeAllowanceUnits(resp?.allowance);
    const allowancesObj = resp?.allowances && typeof resp.allowances === "object" ? resp.allowances : null;
    let allowanceSpenderCount = 0;
    if (allowancesObj) {
      for (const v of Object.values(allowancesObj as Record<string, any>)) {
        const parsed = normalizeAllowanceUnits(v);
        if (parsed == null) continue;
        allowance = allowance == null ? parsed : Math.max(allowance, parsed);
        allowanceSpenderCount += 1;
      }
    }
    return {
      balanceShares: normalizeConditionalUnits(resp?.balance),
      allowanceShares: allowance,
      allowanceSpenderCount,
      error: null,
    };
  } catch (e: any) {
    return {
      balanceShares: null,
      allowanceShares: null,
      allowanceSpenderCount: 0,
      error: String(e?.message ?? e),
    };
  }
}

async function refreshPolymarketStateAfterFill(st: TradeState, side: OutcomeSide, reason: string): Promise<void> {
  try {
    const tokenId = String(st.positionTokenId || tokenIdForSide(side) || "");
    if (!tokenId) return;
    const client = await getClobClient();
    const [posRaw, cond] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    const pos = Number.isFinite(Number(posRaw)) ? floorTo6(Math.max(0, Number(posRaw))) : null;
    const condBal = Number.isFinite(Number(cond.balanceShares)) ? floorTo6(Math.max(0, Number(cond.balanceShares))) : null;
    const condAllow = Number.isFinite(Number(cond.allowanceShares)) ? floorTo6(Math.max(0, Number(cond.allowanceShares))) : null;
    st.lastPostFillSyncMs = nowMs();
    st.lastPositionShares = pos;
    st.lastConditionalBalanceShares = condBal;
    st.lastConditionalAllowanceShares = condAllow;
    st.lastConditionalQueryError = cond.error ? String(cond.error) : null;
    if (Number.isFinite(pos as number) && Number(pos) > 0) {
      st.shares = Number(pos);
    }
    console.log(
      `[POST FILL REFRESH] reason=${reason} side=${side} tokenId=${tokenId} ` +
        `pos=${pos ?? "-"} condBal=${condBal ?? "-"} condAllow=${condAllow ?? "-"} ` +
        `condErr=${st.lastConditionalQueryError ?? "-"}`
    );
  } catch (e: any) {
    console.warn(`[POST FILL REFRESH ERROR] reason=${reason} side=${side} err=${String(e?.message ?? e)}`);
  }
}

async function reconcileLiveBuyFillFromVenue(
  client: any,
  tokenId: string,
  seedShares: number,
  seedFillPx: number,
  meta?: {
    reason?: string;
    prePositionShares?: number | null;
    preConditionalBalanceShares?: number | null;
    preCollateralBalanceUsd?: number | null;
    startedAtMs?: number | null;
    orderId?: string | null;
  }
): Promise<{ shares: number; filledPx: number }> {
  const tol = 1e-6;
  const prePos = Number.isFinite(Number(meta?.prePositionShares)) ? Math.max(0, Number(meta?.prePositionShares)) : 0;
  const preCondBal = Number.isFinite(Number(meta?.preConditionalBalanceShares))
    ? Math.max(0, Number(meta?.preConditionalBalanceShares))
    : 0;
  const preCollateralUsd = Number.isFinite(Number(meta?.preCollateralBalanceUsd))
    ? Math.max(0, Number(meta?.preCollateralBalanceUsd))
    : null;
  const startedAtMs = Number.isFinite(Number(meta?.startedAtMs)) ? Number(meta?.startedAtMs) : null;
  const orderId = String(meta?.orderId || "").trim() || null;
  let resolvedShares = 0;
  let resolvedPx = Number.isFinite(Number(seedFillPx)) && Number(seedFillPx) > 0 ? Number(seedFillPx) : 0;

  for (let attempt = 1; attempt <= SELLABILITY_SYNC_ATTEMPTS; attempt++) {
    let explicitOrderShares = 0;
    let explicitOrderPx = Number.isFinite(Number(seedFillPx)) && Number(seedFillPx) > 0 ? Number(seedFillPx) : NaN;
    if (orderId) {
      try {
        const ord = await (client as any).getOrder(orderId);
        const filledSharesRaw = extractOrderMatchedShares(ord);
        const avgPxRaw = Number(extractOrderAvgFillPx(ord) ?? NaN);
        explicitOrderShares = Number.isFinite(filledSharesRaw) ? Math.max(0, filledSharesRaw) : 0;
        if (Number.isFinite(avgPxRaw) && avgPxRaw > 0) explicitOrderPx = avgPxRaw;
      } catch (e: any) {
        console.warn(
          `[BUY FILL RECONCILE] getOrder failed reason=${meta?.reason ?? "market_buy"} orderId=${orderId} ` +
          `attempt=${attempt}/${SELLABILITY_SYNC_ATTEMPTS} err=${String(e?.message ?? e)}`
        );
      }
    }

    const [posRaw, cond] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    const pos = Number.isFinite(Number(posRaw)) ? Math.max(0, Number(posRaw)) : null;
    const condBal = Number.isFinite(Number(cond.balanceShares)) ? Math.max(0, Number(cond.balanceShares)) : null;
    const deltaPos = pos != null ? Math.max(0, pos - prePos) : 0;
    const deltaCondBal = condBal != null ? Math.max(0, condBal - preCondBal) : 0;
    let tradeConfirmedShares = 0;
    let tradeConfirmedPx = Number.isFinite(Number(seedFillPx)) && Number(seedFillPx) > 0 ? Number(seedFillPx) : NaN;
    if (startedAtMs != null && startedAtMs > 0) {
      try {
        const inferred = await inferRecentBuyFillFromTrades(
          client as any,
          tokenId,
          Number.isFinite(resolvedPx) && resolvedPx > 0 ? resolvedPx : Number(seedFillPx),
          startedAtMs
        );
        if (inferred && inferred.shares > 0) {
          tradeConfirmedShares = Math.max(0, Number(inferred.shares));
          if (Number.isFinite(Number(inferred.filledPx)) && Number(inferred.filledPx) > 0) {
            tradeConfirmedPx = Number(inferred.filledPx);
          }
        }
      } catch (e: any) {
        console.warn(
          `[BUY FILL RECONCILE] trade confirm failed reason=${meta?.reason ?? "market_buy"} tokenId=${tokenId} ` +
          `attempt=${attempt}/${SELLABILITY_SYNC_ATTEMPTS} err=${String(e?.message ?? e)}`
        );
      }
    }

    const venueOwnedShares = floorTo6(Math.max(0, deltaPos, deltaCondBal));
    const explicitConfirmedShares = floorTo6(Math.max(0, explicitOrderShares));
    const tradedConfirmedShares = floorTo6(Math.max(0, tradeConfirmedShares));
    const confirmedCandidates = [venueOwnedShares, explicitConfirmedShares, tradedConfirmedShares].filter((v) => v > tol);
    const candidateShares =
      confirmedCandidates.length >= 2
        ? floorTo6(Math.max(0, Math.min(...confirmedCandidates)))
        : (confirmedCandidates.length === 1 ? confirmedCandidates[0] : 0);

    if (candidateShares > tol && Math.abs(candidateShares - resolvedShares) > tol) {
      console.warn(
        `[BUY FILL RECONCILE] reason=${meta?.reason ?? "market_buy"} tokenId=${tokenId} ` +
          `shares=${roundTo6(resolvedShares)} -> ${roundTo6(candidateShares)} ` +
          `owned=${roundTo6(venueOwnedShares)} order=${roundTo6(explicitOrderShares)} ` +
          `deltaPos=${roundTo6(deltaPos)} deltaCondBal=${roundTo6(deltaCondBal)} trades=${roundTo6(tradeConfirmedShares)}`
      );
      appendLiveBotDiagnosticEventForCurrentSlug({
        event: "buy_fill_reconcile",
        entryPx: Number.isFinite(Number(explicitOrderPx)) && Number(explicitOrderPx) > 0
          ? Number(explicitOrderPx)
          : (Number.isFinite(Number(tradeConfirmedPx)) && Number(tradeConfirmedPx) > 0
            ? Number(tradeConfirmedPx)
            : (Number.isFinite(Number(seedFillPx)) && Number(seedFillPx) > 0 ? Number(seedFillPx) : null)),
        shares: candidateShares,
        sharesRequested: Number.isFinite(Number(seedShares)) ? Number(seedShares) : null,
        orderId,
        reason:
          `BUY_FILL_RECONCILE reason=${meta?.reason ?? "market_buy"} ` +
          `owned=${roundTo6(venueOwnedShares)} order=${roundTo6(explicitOrderShares)} ` +
          `deltaPos=${roundTo6(deltaPos)} deltaCondBal=${roundTo6(deltaCondBal)} trades=${roundTo6(tradeConfirmedShares)}`,
        eventTsMs:
          Number.isFinite(Number(startedAtMs)) && Number(startedAtMs) > 0
            ? Number(startedAtMs)
            : nowMs(),
      }, { tokenId, marketSlug: current.slug });
      resolvedShares = candidateShares;
    }
    if (explicitOrderShares > tol && Number.isFinite(explicitOrderPx) && explicitOrderPx > 0) {
      resolvedPx = explicitOrderPx;
    } else if (tradeConfirmedShares > tol && Number.isFinite(tradeConfirmedPx) && tradeConfirmedPx > 0) {
      resolvedPx = tradeConfirmedPx;
    }

    if (preCollateralUsd != null) {
      try {
        await (client as any).updateBalanceAllowance?.({ asset_type: "COLLATERAL" });
        const balResp = await (client as any).getBalanceAllowance?.({ asset_type: "COLLATERAL" });
        const postBalRaw = Number(balResp?.balance ?? NaN);
        const postBalUsd = Number.isFinite(postBalRaw) ? postBalRaw / 1e6 : NaN;
        if (Number.isFinite(postBalUsd) && postBalUsd >= 0) {
          const spentUsd = Math.max(0, preCollateralUsd - postBalUsd);
          if (spentUsd > 0 && resolvedShares > 0) {
            const inferredPx = spentUsd / resolvedShares;
            if (Number.isFinite(inferredPx) && inferredPx > 0 && inferredPx < 1) resolvedPx = inferredPx;
          }
        }
      } catch {}
    }

    const hasExplicitVenueConfirmation = explicitConfirmedShares > tol || tradedConfirmedShares > tol;
    if (resolvedShares > tol) {
      if (orderId && !hasExplicitVenueConfirmation && attempt < SELLABILITY_SYNC_ATTEMPTS) {
        await sleep(SELLABILITY_SYNC_SLEEP_MS);
        continue;
      }
      break;
    }
    if (attempt < SELLABILITY_SYNC_ATTEMPTS) await sleep(SELLABILITY_SYNC_SLEEP_MS);
  }

  if (!(resolvedShares > tol)) {
    throw new Error(
      `[BUY FILL RECONCILE] unable to verify bought shares tokenId=${tokenId} ` +
      `seedShares=${roundTo6(seedShares)} orderId=${orderId || "none"}`
    );
  }
  try {
    const sellability = await syncSellableShares(
      client as any,
      tokenId,
      resolvedShares,
      `buy_reconcile_${meta?.reason ?? "market_buy"}`
    );
    const sellableShares = floorTo6(Math.max(0, Number(sellability.sellableShares || 0)));
    if (sellableShares > tol && sellableShares < resolvedShares - tol) {
      console.warn(
        `[BUY FILL CLAMP] reason=${meta?.reason ?? "market_buy"} tokenId=${tokenId} ` +
          `shares=${roundTo6(resolvedShares)} -> ${roundTo6(sellableShares)} ` +
          `pos=${sellability.positionShares ?? "-"} condBal=${sellability.conditionalBalanceShares ?? "-"}`
      );
      appendLiveBotDiagnosticEventForCurrentSlug({
        event: "buy_fill_clamp",
        entryPx: Number.isFinite(Number(resolvedPx)) && Number(resolvedPx) > 0 ? Number(resolvedPx) : null,
        shares: sellableShares,
        sharesRequested: resolvedShares,
        sharesRemaining: sellableShares,
        orderId,
        reason:
          `BUY_FILL_CLAMP reason=${meta?.reason ?? "market_buy"} ` +
          `pos=${sellability.positionShares ?? "-"} condBal=${sellability.conditionalBalanceShares ?? "-"}`,
        eventTsMs: nowMs(),
      }, { tokenId, marketSlug: current.slug });
      resolvedShares = sellableShares;
      if (preCollateralUsd != null && resolvedShares > tol && (!Number.isFinite(resolvedPx) || resolvedPx <= 0 || resolvedPx >= 1)) {
        try {
          await (client as any).updateBalanceAllowance?.({ asset_type: "COLLATERAL" });
          const balResp = await (client as any).getBalanceAllowance?.({ asset_type: "COLLATERAL" });
          const postBalRaw = Number(balResp?.balance ?? NaN);
          const postBalUsd = Number.isFinite(postBalRaw) ? postBalRaw / 1e6 : NaN;
          if (Number.isFinite(postBalUsd) && postBalUsd >= 0) {
            const spentUsd = Math.max(0, preCollateralUsd - postBalUsd);
            const inferredPx = spentUsd / resolvedShares;
            if (Number.isFinite(inferredPx) && inferredPx > 0 && inferredPx < 1) resolvedPx = inferredPx;
          }
        } catch {}
      }
    }
  } catch {}
  return { shares: resolvedShares, filledPx: resolvedPx };
}

async function reconcileLiveSellFillFromVenue(
  client: any,
  tokenId: string,
  requestedShares: number,
  seedFilledShares: number,
  seedFillPx: number,
  meta?: {
    reason?: string;
    prePositionShares?: number | null;
    preConditionalBalanceShares?: number | null;
    preCollateralBalanceUsd?: number | null;
    startedAtMs?: number | null;
    orderId?: string | null;
  }
): Promise<{ filledShares: number; filledPx: number; filledAtMs: number | null }> {
  const tol = 1e-6;
  const requested = floorTo6(Math.max(0, Number(requestedShares || 0)));
  const explicit = floorTo6(Math.max(0, Number(seedFilledShares || 0)));
  const prePos = Number.isFinite(Number(meta?.prePositionShares)) ? Math.max(0, Number(meta?.prePositionShares)) : 0;
  const preCondBal = Number.isFinite(Number(meta?.preConditionalBalanceShares))
    ? Math.max(0, Number(meta?.preConditionalBalanceShares))
    : 0;
  const prePositionLike = Math.max(prePos, preCondBal);
  const preCollateralUsd = Number.isFinite(Number(meta?.preCollateralBalanceUsd))
    ? Math.max(0, Number(meta?.preCollateralBalanceUsd))
    : null;
  const startedAtMs = toFiniteOrNull(meta?.startedAtMs);
  const orderId = String(meta?.orderId || "").trim() || null;
  let resolvedShares = explicit;
  let resolvedPx = Number.isFinite(Number(seedFillPx)) && Number(seedFillPx) > 0 ? Number(seedFillPx) : 0.01;
  let resolvedFillTsMs: number | null = null;

  for (let attempt = 1; attempt <= SELLABILITY_SYNC_ATTEMPTS; attempt++) {
    let explicitConfirmedShares = explicit;
    let explicitConfirmedPx = Number.isFinite(Number(seedFillPx)) && Number(seedFillPx) > 0 ? Number(seedFillPx) : NaN;
    let explicitConfirmedFillTsMs: number | null = null;
    if (orderId) {
      try {
        const resolvedFill = await resolveLiveOrderFillSnapshot(
          client as any,
          orderId,
          tokenId,
          Number.isFinite(Number(startedAtMs)) ? Number(startedAtMs) : nowMs()
        );
        if (resolvedFill && Number.isFinite(Number(resolvedFill.shares)) && Number(resolvedFill.shares) > 0) {
          explicitConfirmedShares = Math.max(explicitConfirmedShares, floorTo6(Number(resolvedFill.shares)));
          if (Number.isFinite(Number(resolvedFill.filledPx)) && Number(resolvedFill.filledPx) > 0) {
            explicitConfirmedPx = Number(resolvedFill.filledPx);
          }
          explicitConfirmedFillTsMs = toFiniteOrNull(resolvedFill.filledAtMs);
        }
      } catch (e: any) {
        console.warn(
          `[SELL FILL RECONCILE] order snapshot failed reason=${meta?.reason ?? "market_sell"} orderId=${orderId} ` +
          `attempt=${attempt}/${SELLABILITY_SYNC_ATTEMPTS} err=${String(e?.message ?? e)}`
        );
      }
    }

    const [posRaw, cond] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    const pos = Number.isFinite(Number(posRaw)) ? Math.max(0, Number(posRaw)) : null;
    const condBal = Number.isFinite(Number(cond.balanceShares)) ? Math.max(0, Number(cond.balanceShares)) : null;
    const postPositionLike = Math.max(pos ?? 0, condBal ?? 0);
    const soldDelta = floorTo6(Math.max(0, prePositionLike - postPositionLike));
    const candidateShares = floorTo6(Math.min(requested, Math.max(soldDelta, explicitConfirmedShares)));
    if (candidateShares > resolvedShares + tol) {
      console.warn(
        `[SELL FILL RECONCILE] reason=${meta?.reason ?? "market_sell"} tokenId=${tokenId} ` +
          `filledShares=${roundTo6(resolvedShares)} -> ${roundTo6(candidateShares)} ` +
          `pre=${roundTo6(prePositionLike)} post=${roundTo6(postPositionLike)} ` +
          `delta=${roundTo6(soldDelta)} explicit=${roundTo6(explicitConfirmedShares)}`
      );
      resolvedShares = candidateShares;
    }
    if (explicitConfirmedShares > tol && Number.isFinite(Number(explicitConfirmedPx)) && Number(explicitConfirmedPx) > 0) {
      resolvedPx = Number(explicitConfirmedPx);
    }
    if (explicitConfirmedFillTsMs != null) {
      resolvedFillTsMs = resolvedFillTsMs != null
        ? Math.min(Number(resolvedFillTsMs), Number(explicitConfirmedFillTsMs))
        : Number(explicitConfirmedFillTsMs);
    }

    if (preCollateralUsd != null && resolvedShares > tol) {
      try {
        await (client as any).updateBalanceAllowance?.({ asset_type: "COLLATERAL" });
        const balResp = await (client as any).getBalanceAllowance?.({ asset_type: "COLLATERAL" });
        const postBalRaw = Number(balResp?.balance ?? NaN);
        const postBalUsd = Number.isFinite(postBalRaw) ? postBalRaw / 1e6 : NaN;
        if (Number.isFinite(postBalUsd) && postBalUsd >= 0) {
          const receivedUsd = Math.max(0, postBalUsd - preCollateralUsd);
          if (receivedUsd > 0) {
            const inferredPx = receivedUsd / resolvedShares;
            if (Number.isFinite(inferredPx) && inferredPx > 0 && inferredPx < 1) resolvedPx = inferredPx;
          }
        }
      } catch {}
    }

    if (resolvedShares > tol) break;
    if (attempt < SELLABILITY_SYNC_ATTEMPTS) await sleep(SELLABILITY_SYNC_SLEEP_MS);
  }

  return {
    filledShares: floorTo6(Math.min(requested, Math.max(0, resolvedShares))),
    filledPx: resolvedPx,
    filledAtMs: resolvedFillTsMs,
  };
}

type StopPrecheckResult = {
  ok: boolean;
  code: string;
  approvedShares: number | null;
  meta: Record<string, any>;
};
const STOP_BLOCKED_EMIT_COOLDOWN_MS = Math.max(1000, Number(process.env.STOP_BLOCKED_EMIT_COOLDOWN_MS || 15000));
const ENTRY_BLOCKED_EMIT_COOLDOWN_MS = Math.max(1000, Number(process.env.ENTRY_BLOCKED_EMIT_COOLDOWN_MS || 15000));
const STOP_ALLOWANCE_REFRESH_ATTEMPTS = Math.max(0, Number(process.env.STOP_ALLOWANCE_REFRESH_ATTEMPTS || 2));
const STOP_ALLOWANCE_REFRESH_SLEEP_MS = Math.max(0, Number(process.env.STOP_ALLOWANCE_REFRESH_SLEEP_MS || 120));
const STOP_ALLOWANCE_BYPASS_WITH_POSITION = String(process.env.STOP_ALLOWANCE_BYPASS_WITH_POSITION ?? "1") !== "0";
const SELLABILITY_SYNC_ATTEMPTS = Math.max(1, Number(process.env.SELLABILITY_SYNC_ATTEMPTS || 4));
const SELLABILITY_SYNC_SLEEP_MS = Math.max(20, Number(process.env.SELLABILITY_SYNC_SLEEP_MS || 120));
const IMMEDIATE_TP_FORCE_POST_AFTER_ATTEMPTS = Math.max(1, Number(process.env.IMMEDIATE_TP_FORCE_POST_AFTER_ATTEMPTS || 3));
const STOP_INITIAL_SLICE_TTL_MS = Math.max(300, Number(process.env.STOP_INITIAL_SLICE_TTL_MS || 300));
const STOP_WALK_REPRICE_MS = Math.max(50, Number(process.env.STOP_WALK_REPRICE_MS || 100));
const STOP_WALK_SLICE_TTL_MS = Math.max(50, Number(process.env.STOP_WALK_SLICE_TTL_MS || 100));
const STOP_WALK_MAX_ATTEMPTS = Math.max(2, Number(process.env.STOP_WALK_MAX_ATTEMPTS || 5));
const STOP_FORCE_MARKET_AFTER_FIRST_TTL =
  String(process.env.STOP_FORCE_MARKET_AFTER_FIRST_TTL ?? "1").trim().toLowerCase() !== "0";
const ENTRY_RESTING_AUTOTRIGGER_ENABLED =
  String(process.env.ENTRY_RESTING_AUTOTRIGGER_ENABLED ?? "1").trim().toLowerCase() !== "0";
const ENTRY_RESTING_TTL_MS = Math.max(100, Number(process.env.ENTRY_RESTING_TTL_MS || 300));

type SellabilitySnapshot = {
  sellableShares: number;
  positionShares: number | null;
  conditionalBalanceShares: number | null;
  conditionalAllowanceShares: number | null;
  conditionalError: string | null;
  attempts: number;
};

async function syncSellableShares(
  client: any,
  tokenId: string,
  requestedShares: number,
  reasonTag: string
): Promise<SellabilitySnapshot> {
  const requested = floorTo6(Math.max(0, Number(requestedShares || 0)));
  let out: SellabilitySnapshot = {
    sellableShares: 0,
    positionShares: null,
    conditionalBalanceShares: null,
    conditionalAllowanceShares: null,
    conditionalError: null,
    attempts: 0,
  };
  for (let i = 0; i < SELLABILITY_SYNC_ATTEMPTS; i++) {
    out.attempts = i + 1;
    const [posRaw, cond] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    const pos = Number.isFinite(Number(posRaw)) ? Math.max(0, Number(posRaw)) : null;
    const condBal = Number.isFinite(Number(cond.balanceShares)) ? Math.max(0, Number(cond.balanceShares)) : null;
    const condAllow = Number.isFinite(Number(cond.allowanceShares)) ? Math.max(0, Number(cond.allowanceShares)) : null;
    const positionLike = Math.max(pos ?? 0, condBal ?? 0);
    const allowanceCap = Number.isFinite(Number(condAllow)) ? Number(condAllow) : Number.POSITIVE_INFINITY;
    const sellable = floorTo6(Math.max(0, Math.min(requested, positionLike, allowanceCap)));
    out = {
      sellableShares: sellable,
      positionShares: pos,
      conditionalBalanceShares: condBal,
      conditionalAllowanceShares: condAllow,
      conditionalError: cond.error ? String(cond.error) : null,
      attempts: i + 1,
    };
    if (sellable > 1e-9) break;
    if (i + 1 < SELLABILITY_SYNC_ATTEMPTS) await sleep(SELLABILITY_SYNC_SLEEP_MS);
  }
  console.log(
    `[SELLABILITY] reason=${reasonTag} tokenId=${tokenId} requested=${roundTo6(requested)} ` +
      `sellable=${roundTo6(out.sellableShares)} pos=${out.positionShares ?? "-"} ` +
      `condBal=${out.conditionalBalanceShares ?? "-"} condAllow=${out.conditionalAllowanceShares ?? "-"} ` +
      `condErr=${out.conditionalError ?? "-"} attempts=${out.attempts}`
  );
  return out;
}

function shouldEmitStopBlockedEvent(st: TradeState, side: OutcomeSide, code: string): boolean {
  const now = nowMs();
  const key = `${String(current.slug || "")}|${String(side || "")}|${String(code || "")}`;
  const lastMs = Number((st as any).__lastStopBlockedEmitMs ?? 0);
  const lastKey = String((st as any).__lastStopBlockedEmitKey || "");
  if (lastKey === key && Number.isFinite(lastMs) && now - lastMs < STOP_BLOCKED_EMIT_COOLDOWN_MS) return false;
  (st as any).__lastStopBlockedEmitMs = now;
  (st as any).__lastStopBlockedEmitKey = key;
  return true;
}

function shouldEmitEntryBlockedEvent(st: TradeState, side: OutcomeSide, code: string): boolean {
  const now = nowMs();
  const key = `${String(current.slug || "")}|${String(side || "")}|${String(code || "")}`;
  const lastMs = Number((st as any).__lastEntryBlockedEmitMs ?? 0);
  const lastKey = String((st as any).__lastEntryBlockedEmitKey || "");
  if (lastKey === key && Number.isFinite(lastMs) && now - lastMs < ENTRY_BLOCKED_EMIT_COOLDOWN_MS) return false;
  (st as any).__lastEntryBlockedEmitMs = now;
  (st as any).__lastEntryBlockedEmitKey = key;
  return true;
}

type EntryPrecheckResult = {
  ok: boolean;
  code: string;
  meta: Record<string, any>;
};

async function validateLiveEntryPreconditions(
  side: OutcomeSide,
  requestedNotionalUsdRaw: number,
  reasonTag: string
): Promise<EntryPrecheckResult> {
  const requestedNotionalUsd = Number(requestedNotionalUsdRaw);
  const tokenId = String(tokenIdForSide(side) || "");
  const fail = (code: string, meta: Record<string, any>): EntryPrecheckResult => ({
    ok: false,
    code,
    meta: {
      reasonTag,
      side,
      tokenId,
      requestedNotionalUsd: Number.isFinite(requestedNotionalUsd) ? requestedNotionalUsd : null,
      ...meta,
    },
  });

  if (!tokenId) return fail("MISSING_TOKEN_ID", {});
  const optimisticRecovery = activeOptimisticLiveStopRecovery();

  if (stLive.enterInFlight) {
    return fail("ENTER_IN_FLIGHT", {
      localEntered: !!stLive.entered,
      localExited: !!stLive.exited,
      localSide: stLive.side ?? null,
    });
  }
  if (stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) {
    return fail("LIVE_STATE_ALREADY_ENTERED", {
      localEntered: !!stLive.entered,
      localExited: !!stLive.exited,
      localSide: stLive.side ?? null,
      localShares: Number.isFinite(Number(stLive.shares)) ? Number(stLive.shares) : null,
      localEntryPx: Number.isFinite(Number(stLive.entryPx)) ? Number(stLive.entryPx) : null,
      localTokenId: stLive.positionTokenId ?? null,
    });
  }

  const client = await getClobClient();
  const signerAddr = String((client as any)?.signer?.address || "").toLowerCase();
  const funderAddr = String((client as any)?.funder || process.env.POLY_FUNDER_ADDRESS || "").toLowerCase();
  await reconcileLivePositionMaybe(true, `${reasonTag}-entry-precheck`);
  if (!stLive.entered || stLive.exited || !(stLive.side === "UP" || stLive.side === "DOWN")) {
    await hydrateLivePositionFromTokenBalances(`${reasonTag}-entry-precheck`);
  }
  if (!optimisticRecovery && stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) {
    return fail("LIVE_POSITION_EXISTS", {
      localEntered: !!stLive.entered,
      localExited: !!stLive.exited,
      localSide: stLive.side ?? null,
      localShares: Number.isFinite(Number(stLive.shares)) ? Number(stLive.shares) : null,
      localEntryPx: Number.isFinite(Number(stLive.entryPx)) ? Number(stLive.entryPx) : null,
      localTokenId: stLive.positionTokenId ?? null,
    });
  }
  const exposureTokenIds = Array.from(new Set(
    [String(current.upToken || ""), String(current.downToken || ""), tokenId].filter(Boolean)
  ));
  const [openBuySummary, openSellSummary, allConditional] = await Promise.all([
    getOpenBuyOrderSummaryForTokens(client as any, exposureTokenIds),
    getOpenSellOrderSummaryForTokens(client as any, exposureTokenIds),
    Promise.all(
      exposureTokenIds.map(async (tid) => ({ tokenId: tid, ...(await getConditionalBalanceAllowanceShares(client as any, tid)) }))
    ),
  ]);
  if (openBuySummary.count > 0) {
    return fail("OPEN_BUY_ORDER_EXISTS", {
      openBuyOrderCount: openBuySummary.count,
      openBuyOrderIds: openBuySummary.orderIds,
      openBuyOrderTokenIds: openBuySummary.tokenIds,
    });
  }
  if (!optimisticRecovery && openSellSummary.count > 0) {
    return fail("OPEN_SELL_ORDER_EXISTS", {
      openSellOrderCount: openSellSummary.count,
      openSellOrderIds: openSellSummary.orderIds,
      openSellOrderTokenIds: openSellSummary.tokenIds,
    });
  }
  const cond =
    allConditional.find((x) => String(x.tokenId || "") === tokenId) ||
    { balanceShares: null, allowanceShares: null, allowanceSpenderCount: 0, error: "missing_token_probe" };
  const condBal = Number.isFinite(Number(cond.balanceShares)) ? Math.max(0, Number(cond.balanceShares)) : null;
  const condAllow = Number.isFinite(Number(cond.allowanceShares)) ? Math.max(0, Number(cond.allowanceShares)) : null;
  const existingConditionalExposure = allConditional
    .map((x) => ({
      tokenId: x.tokenId,
      balanceShares: Number.isFinite(Number(x.balanceShares)) ? Math.max(0, Number(x.balanceShares)) : 0,
    }))
    .filter((x) => x.balanceShares > 1e-6);
  const baseMeta = {
    signerAddr,
    funderAddr,
    conditionalBalanceShares: condBal,
    conditionalAllowanceShares: condAllow,
    conditionalAllowanceSpenderCount: Number(cond.allowanceSpenderCount || 0),
    conditionalQueryError: cond.error,
    openBuyOrderCount: openBuySummary.count,
    openSellOrderCount: openSellSummary.count,
    existingConditionalExposure,
  };

  if (!optimisticRecovery && existingConditionalExposure.length > 0) return fail("CONDITIONAL_POSITION_EXISTS", baseMeta);
  if (cond.error) return fail("CONDITIONAL_ALLOWANCE_UNCONFIRMED", baseMeta);
  if (condAllow == null) return fail("CONDITIONAL_ALLOWANCE_UNCONFIRMED", baseMeta);
  if (!(condAllow > 1e-9)) return fail("CONDITIONAL_ALLOWANCE_ZERO", baseMeta);
  return { ok: true, code: "OK", meta: { reasonTag, side, tokenId, ...baseMeta } };
}

async function validateLiveStopPreconditions(
  side: OutcomeSide,
  st: TradeState,
  requestedSharesRaw: number,
  reasonTag: string
): Promise<StopPrecheckResult> {
  const requestedShares = floorTo6(Number(requestedSharesRaw));
  const tokenId = String(st.positionTokenId || tokenIdForSide(side) || "");
  const fail = (code: string, meta: Record<string, any>): StopPrecheckResult => ({
    ok: false,
    code,
    approvedShares: null,
    meta: {
      reasonTag,
      side,
      tokenId,
      requestedShares,
      ...meta,
    },
  });

  if (!tokenId) return fail("MISSING_TOKEN_ID", {});
  if (!(requestedShares > 0)) return fail("INVALID_REQUESTED_SHARES", { requestedSharesRaw });

  await reconcileLivePositionMaybe(true, `${reasonTag}-stop-precheck`);

  const client = await getClobClient();
  const signerAddr = String((client as any)?.signer?.address || "").toLowerCase();
  const funderAddr = String((client as any)?.funder || process.env.POLY_FUNDER_ADDRESS || "").toLowerCase();
  const availableShares = await getLiveTokenPositionShares(client as any, tokenId);
  let cond = await getConditionalBalanceAllowanceShares(client as any, tokenId);
  const available = Number.isFinite(Number(availableShares)) ? Math.max(0, Number(availableShares)) : null;
  let condBal = Number.isFinite(Number(cond.balanceShares)) ? Math.max(0, Number(cond.balanceShares)) : null;
  let condAllow = Number.isFinite(Number(cond.allowanceShares)) ? Math.max(0, Number(cond.allowanceShares)) : null;
  let allowanceRefreshAttempts = 0;

  const shouldRefreshAllowance =
    Boolean(cond.error) ||
    condBal == null ||
    condAllow == null ||
    (!(condAllow > 1e-9) && ((Number.isFinite(Number(condBal)) && Number(condBal) > 1e-9) || (Number.isFinite(Number(available)) && Number(available) > 1e-9)));
  if (shouldRefreshAllowance && STOP_ALLOWANCE_REFRESH_ATTEMPTS > 0) {
    for (let i = 0; i < STOP_ALLOWANCE_REFRESH_ATTEMPTS; i++) {
      allowanceRefreshAttempts += 1;
      if (STOP_ALLOWANCE_REFRESH_SLEEP_MS > 0) await sleep(STOP_ALLOWANCE_REFRESH_SLEEP_MS);
      const probe = await getConditionalBalanceAllowanceShares(client as any, tokenId);
      const probeBal = Number.isFinite(Number(probe.balanceShares)) ? Math.max(0, Number(probe.balanceShares)) : null;
      const probeAllow = Number.isFinite(Number(probe.allowanceShares)) ? Math.max(0, Number(probe.allowanceShares)) : null;
      const improved =
        (!cond.error && !!probe.error) ? false :
        (!!cond.error && !probe.error) ? true :
        ((probeBal ?? -1) > (condBal ?? -1)) || ((probeAllow ?? -1) > (condAllow ?? -1));
      if (improved) {
        cond = probe;
        condBal = probeBal;
        condAllow = probeAllow;
      } else if (!cond.error && !probe.error) {
        cond = probe;
        condBal = probeBal;
        condAllow = probeAllow;
      }
      if (!cond.error && condBal != null && condAllow != null && condAllow > 1e-9) break;
    }
  }

  const effectivePositionShares =
    Number.isFinite(Number(available)) && Number(available) > 0
      ? Number(available)
      : (Number.isFinite(Number(condBal)) ? Number(condBal) : null);
  const allowanceBypassEnabled = STOP_ALLOWANCE_BYPASS_WITH_POSITION;
  const allowanceBypassApplied =
    allowanceBypassEnabled &&
    !cond.error &&
    Number.isFinite(Number(condBal)) &&
    Number(condBal) > 1e-9 &&
    Number.isFinite(Number(effectivePositionShares)) &&
    Number(effectivePositionShares) > 1e-9 &&
    (!(condAllow > 1e-9));
  const baseMeta = {
    signerAddr,
    funderAddr,
    availableShares: available,
    effectivePositionShares,
    conditionalBalanceShares: condBal,
    conditionalAllowanceShares: condAllow,
    conditionalAllowanceSpenderCount: Number(cond.allowanceSpenderCount || 0),
    conditionalQueryError: cond.error,
    allowanceRefreshAttempts,
    allowanceBypassEnabled,
    allowanceBypassApplied,
  };

  // Stop path: favor execution when position shares are confirmed, even if allowance reads stale/zero.
  if (cond.error) return fail("CONDITIONAL_ALLOWANCE_UNCONFIRMED", baseMeta);
  if (condBal == null || condAllow == null) return fail("CONDITIONAL_BALANCE_ALLOWANCE_UNCONFIRMED", baseMeta);
  if (!(condBal > 1e-9)) {
    if (available == null) return fail("POSITION_UNCONFIRMED", baseMeta);
    return fail("NO_POSITION_SHARES", baseMeta);
  }
  if (!(condAllow > 1e-9) && !allowanceBypassApplied) return fail("CONDITIONAL_ALLOWANCE_ZERO", baseMeta);

  if (!(effectivePositionShares != null && effectivePositionShares > 1e-9)) {
    return fail("NO_POSITION_SHARES", baseMeta);
  }

  const allowanceCap = allowanceBypassApplied ? Number.POSITIVE_INFINITY : condAllow;
  const approvedShares = floorTo6(Math.min(requestedShares, effectivePositionShares, allowanceCap));
  if (!(approvedShares > 1e-9)) return fail("APPROVED_SHARES_ZERO", baseMeta);
  if (approvedShares + 1e-9 < requestedShares) {
    // Do not hard-block stop execution on partial approval snapshots.
    // Allow stop-walk to attempt execution and rely on live order errors/retries
    // plus market fallback instead of leaving the position unprotected.
    return {
      ok: true,
      code: "INSUFFICIENT_APPROVED_SHARES_BEST_EFFORT",
      approvedShares: requestedShares,
      meta: {
        reasonTag,
        side,
        tokenId,
        requestedShares,
        approvedShares,
        precheckPartialApproved: true,
        ...baseMeta,
      },
    };
  }

  return {
    ok: true,
    code: "OK",
    approvedShares,
    meta: {
      reasonTag,
      side,
      tokenId,
      requestedShares,
      approvedShares,
      ...baseMeta,
    },
  };
}

async function cancelOrderRobust(client: any, orderId: string): Promise<void> {
  const attempts: Array<() => Promise<any>> = [
    // @polymarket/clob-client v5 expects OrderPayload: { orderID: string }
    () => (client as any).cancelOrder?.({ orderID: orderId }),
    // Compatible fallback for some gateway variants.
    () => (client as any).cancelOrders?.([orderId]),
    // Legacy payload variants as last resort.
    () => (client as any).cancelOrder?.({ orderId: orderId }),
    () => (client as any).cancelOrder?.({ id: orderId }),
    () => (client as any).cancelOrder?.(orderId),
  ];
  let lastErr: any = null;
  for (const a of attempts) {
    try {
      await a();
      return;
    } catch (e: any) {
      lastErr = e;
    }
  }
  throw lastErr ?? new Error(`cancel failed orderId=${orderId}`);
}

function orderStatusUpper(order: any): string {
  return String(order?.status || "").toUpperCase();
}

function isTerminalOrderStatus(status: string): boolean {
  return (
    status.includes("FILLED") ||
    status.includes("CANCEL") ||
    status.includes("EXPIRED") ||
    status.includes("REJECT")
  );
}

function openOrderId(order: any): string {
  return String(order?.id ?? order?.orderID ?? order?.orderId ?? "");
}

function openOrderTokenId(order: any): string {
  return String(order?.asset_id ?? order?.assetId ?? order?.token_id ?? order?.tokenId ?? "");
}

async function getOpenOrderIdsForToken(client: any, tokenId: string, sideWanted: "BUY" | "SELL"): Promise<Set<string>> {
  const open = await (client as any).getOpenOrders?.({ asset_id: tokenId });
  const openOrders = Array.isArray(open) ? open : [];
  const ids = new Set<string>();
  for (const o of openOrders) {
    if (String(o?.side || "").toUpperCase() !== sideWanted) continue;
    if (openOrderTokenId(o) !== String(tokenId)) continue;
    const oid = openOrderId(o);
    if (oid) ids.add(oid);
  }
  return ids;
}

async function getOpenBuyOrderIdsForToken(client: any, tokenId: string): Promise<Set<string>> {
  return getOpenOrderIdsForToken(client, tokenId, "BUY");
}

async function getOpenSellOrderIdsForToken(client: any, tokenId: string): Promise<Set<string>> {
  return getOpenOrderIdsForToken(client, tokenId, "SELL");
}

async function getOpenBuyOrderSummaryForTokens(
  client: any,
  tokenIdsRaw: string[]
): Promise<{ count: number; orderIds: string[]; tokenIds: string[] }> {
  const tokenIds = Array.from(new Set(
    (Array.isArray(tokenIdsRaw) ? tokenIdsRaw : [])
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  const orderIds = new Set<string>();
  const seenTokenIds = new Set<string>();
  const rows = await Promise.all(
    tokenIds.map(async (tokenId) => {
      try {
        const ids = await getOpenBuyOrderIdsForToken(client, tokenId);
        return { tokenId, ids };
      } catch {
        return { tokenId, ids: new Set<string>() };
      }
    })
  );
  for (const row of rows) {
    if (row.ids.size) seenTokenIds.add(row.tokenId);
    for (const id of row.ids) orderIds.add(id);
  }
  return {
    count: orderIds.size,
    orderIds: Array.from(orderIds.values()),
    tokenIds: Array.from(seenTokenIds.values()),
  };
}

async function getOpenSellOrderSummaryForTokens(
  client: any,
  tokenIdsRaw: string[]
): Promise<{ count: number; orderIds: string[]; tokenIds: string[] }> {
  const tokenIds = Array.from(new Set(
    (Array.isArray(tokenIdsRaw) ? tokenIdsRaw : [])
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  const orderIds = new Set<string>();
  const seenTokenIds = new Set<string>();
  const rows = await Promise.all(
    tokenIds.map(async (tokenId) => {
      try {
        const ids = await getOpenSellOrderIdsForToken(client, tokenId);
        return { tokenId, ids };
      } catch {
        return { tokenId, ids: new Set<string>() };
      }
    })
  );
  for (const row of rows) {
    if (row.ids.size) seenTokenIds.add(row.tokenId);
    for (const id of row.ids) orderIds.add(id);
  }
  return {
    count: orderIds.size,
    orderIds: Array.from(orderIds.values()),
    tokenIds: Array.from(seenTokenIds.values()),
  };
}

async function assertNoVenueExposureBeforeLiveEntry(client: any, reasonTag: string, tokenIdsRaw: string[]): Promise<void> {
  if (activeOptimisticLiveStopRecovery()) {
    console.warn(`[${reasonTag}] bypass venue exposure gate due to optimistic stop recovery`);
    return;
  }
  const tokenIds = Array.from(new Set(
    (Array.isArray(tokenIdsRaw) ? tokenIdsRaw : [])
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  const openSellSummary = await getOpenSellOrderSummaryForTokens(client as any, tokenIds);
  if (openSellSummary.count > 0) {
    throw new Error(
      `[${reasonTag}] open sell order already exists count=${openSellSummary.count} tokenIds=${openSellSummary.tokenIds.join(",")}`
    );
  }
  const cond = await Promise.all(
    tokenIds.map(async (tokenId) => ({ tokenId, ...(await getConditionalBalanceAllowanceShares(client as any, tokenId)) }))
  );
  const exposure = cond.filter((x) => Number.isFinite(Number(x.balanceShares)) && Number(x.balanceShares) > 1e-6);
  if (exposure.length > 0) {
    throw new Error(
      `[${reasonTag}] conditional exposure exists ` +
      exposure.map((x) => `${x.tokenId}:${roundTo6(Number(x.balanceShares ?? 0))}`).join(",")
    );
  }
}

async function cancelBuyOrderAndVerifyClosed(
  client: any,
  orderId: string,
  tokenId: string,
  reason: string
): Promise<boolean> {
  for (let attempt = 1; attempt <= 4; attempt++) {
    try {
      await cancelOrderRobust(client, orderId);
    } catch (e: any) {
      console.warn(
        `[BUY LIMIT] cancel attempt failed reason=${reason} orderId=${orderId} attempt=${attempt}: ${String(
          e?.message ?? e
        )}`
      );
    }

    try {
      const ord = await (client as any).getOrder(orderId);
      const status = orderStatusUpper(ord);
      if (isTerminalOrderStatus(status)) {
        console.log(`[BUY LIMIT] cancel verified by status reason=${reason} orderId=${orderId} status=${status}`);
        return true;
      }
    } catch {}

    try {
      const openBuyIds = await getOpenBuyOrderIdsForToken(client, tokenId);
      if (!openBuyIds.has(orderId)) {
        console.log(`[BUY LIMIT] cancel verified by open-orders reason=${reason} orderId=${orderId}`);
        return true;
      }
    } catch {}

    await sleep(250);
  }
  return false;
}

async function placeLiveLimitBuy(
  side: OutcomeSide,
  price: number,
  notionalUsd: number,
  ui: UiConfig,
  ttlMs: number,
  opts?: { armTpAfterBuy?: boolean; strategyIdLike?: string | null }
): Promise<{ filledPx: number; shares: number; tpOrderId: string | null; tokenId: string; filledAtMs: number | null; entryEventTsMs: number | null; orderId: string | null; fillTimestampSource: "order_timeline" | "trade_infer" | "unknown" }> {
  assertLiveOrderSubmissionAllowed(`buy_limit_${side}`);
  if (side == null) {
    console.error("[CRITICAL] side is undefined in placeLiveLimitBuy");
    console.trace();
    throw new Error("side is undefined - cannot place buy order");
  }
  if (!["UP", "DOWN"].includes(side)) throw new Error(`Invalid side value: ${side}`);

  console.log(`[BUY LIMIT] Attempt: slug=${current.slug} side=${side}, price=${price}, notionalUsd=${notionalUsd}`);

  if (!Number.isFinite(price) || price <= 0 || price >= 1) throw new Error(`invalid buy price: ${price} (must be >0 and <1)`);
  assertEntryBelowTakeProfit(price, ui, `buy_limit_submit_${side}`, ui?.strategyId);
  if (!Number.isFinite(notionalUsd) || notionalUsd <= 0) throw new Error(`invalid notionalUsd: ${notionalUsd}`);
  const preBuyBalanceUsd = Number(liveAccount.balanceUsd);

  const rawSize = notionalUsd / price;
  let size = Math.min(rawSize, MAX_SHARES_PER_TRADE);
  if (!Number.isFinite(size) || size <= 0) throw new Error(`invalid calculated size: ${size}`);
  if (rawSize > MAX_SHARES_PER_TRADE) {
    console.log(`[BUY] share cap applied rawSize=${roundTo6(rawSize)} cappedSize=${roundTo6(size)} max=${MAX_SHARES_PER_TRADE}`);
  }
  if (size < MIN_LIVE_ORDER_SHARES) {
    const minSize = Math.min(MIN_LIVE_ORDER_SHARES, MAX_SHARES_PER_TRADE);
    const minNotionalUsd = minSize * price;
    const balUsd = Number.isFinite(preBuyBalanceUsd) ? preBuyBalanceUsd : 0;
    if (balUsd >= minNotionalUsd) {
      console.log(
        `[BUY] auto-bump size ${roundTo6(size)} -> ${roundTo6(minSize)} to satisfy minimum ` +
        `${MIN_LIVE_ORDER_SHARES} shares (minNotionalUsd=${roundTo6(minNotionalUsd)})`
      );
      size = minSize;
    } else {
      throw new Error(
        `[BUY] size ${roundTo6(size)} below exchange minimum ${MIN_LIVE_ORDER_SHARES} shares ` +
        `(notionalUsd=${notionalUsd}, price=${price}, minNotionalUsd=${roundTo6(minNotionalUsd)}, balanceUsd=${roundTo6(balUsd)})`
      );
    }
  }

  const client = await getClobClient();
  const tokenId = tokenIdForSide(side);
  await assertNoVenueExposureBeforeLiveEntry(client as any, "BUY LIMIT", [
    String(current.upToken || ""),
    String(current.downToken || ""),
  ]);
  const openBuySummary = await getOpenBuyOrderSummaryForTokens(client as any, [
    String(current.upToken || ""),
    String(current.downToken || ""),
  ]);
  if (openBuySummary.count > 0) {
    throw new Error(
      `[BUY LIMIT] open buy order already exists count=${openBuySummary.count} tokenIds=${openBuySummary.tokenIds.join(",")}`
    );
  }
  await reconcileLivePositionMaybe(true, "limit-buy-helper-preflight");
  if (!stLive.entered || stLive.exited || !(stLive.side === "UP" || stLive.side === "DOWN")) {
    await hydrateLivePositionFromTokenBalances("limit-buy-helper-preflight");
  }
  if (stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) {
    throw new Error(
      `[BUY LIMIT] live position already exists side=${stLive.side} shares=${roundTo6(Number(stLive.shares ?? 0))}`
    );
  }

  const { tickSize, negRisk } = await getTickNegRisk(tokenId);

  const ttl = Math.max(0, Number(ttlMs) || 0);
  if (!Number.isFinite(ttl) || ttl <= 0) throw new Error(`[BUY] invalid ttlMs: ${ttlMs}`);
  const buyStartedAtMs = Date.now();
  const deadline = Date.now() + ttl;

  console.log(`[BUY] tokenId=${tokenId}, tickSize=${tickSize}, negRisk=${negRisk}, size=${roundTo6(size)} ttlMs=${ttl}`);

  let order: any;
  try {
    order = await client.createAndPostOrder(
      {
        tokenID: tokenId,
        price: roundTo6(price),
        side: ClobSide.BUY,
        size: roundTo6(size),
        feeRateBps: 1000,
      },
      { tickSize: tickSize as any, negRisk },

      OrderType.GTC
    );
  } catch (e: any) {
    maybeThrowLiveExecutionHardBlock(e, `buy_limit_post_${side}`);
    console.error("[BUY LIMIT ERROR]", e?.message || e, e?.stack || "");
    broadcast({ type: "status", t: nowMs(), status: `buy limit failed: ${String(e?.message ?? e)}` });
    throw e;
  }

  maybeThrowLiveExecutionHardBlock(order, `buy_limit_response_${side}`);
  const orderId = (order as any)?.orderID || (order as any)?.orderId || (order as any)?.id;
  if (!orderId) {
    maybeThrowLiveExecutionHardBlock(order, `buy_limit_missing_order_id_${side}`);
    const errHint =
      (order as any)?.error ||
      (order as any)?.message ||
      (order ? JSON.stringify(order).slice(0, 300) : "empty response");
    throw new Error(`[BUY] order did not return orderID: ${String(errHint)}`);
  }
  const orderFillTsMs = extractOrderFillTsMs(order);
  const orderEntryTsMs = extractOrderEntryTsMs(order) ?? orderFillTsMs;
  console.log(`[BUY LIMIT] Placed orderId=${orderId}`);
  broadcast({ type: "status", t: nowMs(), status: `BUY ORDER PLACED side=${side} orderId=${orderId}` });

  // ✅ CHANGE: accept ANY filled shares (partial or complete)
  let lastTradeCheckMs = 0;
  while (Date.now() < deadline) {
    const loopNow = Date.now();
    const st = await (client as any).getOrder(orderId);
    const status = String(st?.status || "").toUpperCase();

    const filledShares = extractOrderMatchedShares(st);
    const avgPx = Number(extractOrderAvgFillPx(st) ?? NaN);

    if (Number.isFinite(filledShares) && filledShares > 0) {
      const filledPx = Number.isFinite(avgPx) ? avgPx : price;
      const filledAtMs = extractOrderFillTsMs(st) ?? orderFillTsMs ?? null;
      const entryEventTsMs = extractOrderEntryTsMs(st) ?? orderEntryTsMs ?? filledAtMs ?? null;
      await rejectInvalidFilledLiveBuyAtOrAboveTp(side, filledPx, filledShares, ui, tokenId, "buy_limit_order_poll", ui?.strategyId);
      console.log(`[BUY LIMIT] FILLED(partial/complete) orderId=${orderId} status=${status} px=${filledPx} shares=${filledShares}`);
      broadcast({
        type: "status",
        t: filledAtMs ?? nowMs(),
        status: `BUY ORDER FILLED orderId=${orderId} px=${filledPx} shares=${roundTo6(filledShares)}`,
      });
      let tpOrderId: string | null = null;
      if (opts?.armTpAfterBuy !== false) {
        try {
          tpOrderId = (await placeImmediateTpSellAfterBuy(side, filledShares, ui, tokenId, {
            buyFilledAtMs: filledAtMs,
            source: "order_poll",
            entryFillPx: filledPx,
            strategyId: opts?.strategyIdLike || null,
          })).orderId;
        } catch (tpErr: any) {
          console.error(`[IMMEDIATE TP SELL ERROR] ${String(tpErr?.message ?? tpErr)}`);
        }
      }
      if (filledShares + 1e-6 < size) {
        const canceled = await cancelBuyOrderAndVerifyClosed(client as any, String(orderId), tokenId, "partial_fill");
        if (!canceled) {
          console.warn(
            `[BUY LIMIT] partial fill remainder cancel not confirmed orderId=${orderId} filled=${roundTo6(
              filledShares
            )} original=${roundTo6(size)}`
          );
        }
      }
      return { filledPx, shares: filledShares, tpOrderId, tokenId, filledAtMs, entryEventTsMs, orderId: String(orderId) };
    }

    if (loopNow - lastTradeCheckMs >= BUY_TRADE_CHECK_MS) {
      lastTradeCheckMs = loopNow;
      try {
        const inferred = await inferRecentBuyFillFromTrades(client as any, tokenId, price, buyStartedAtMs);
        if (inferred && inferred.shares > 0) {
          const filledAtMs = inferred.firstFillTsMs ?? orderFillTsMs ?? null;
          const entryEventTsMs = orderEntryTsMs ?? filledAtMs ?? null;
          await rejectInvalidFilledLiveBuyAtOrAboveTp(side, inferred.filledPx, inferred.shares, ui, tokenId, "buy_limit_trade_infer_fast", ui?.strategyId);
          console.log(
            `[BUY LIMIT] FAST INFERRED FILLED from trades orderId=${orderId} px=${inferred.filledPx} shares=${roundTo6(inferred.shares)}`
          );
          broadcast({
            type: "status",
            t: filledAtMs ?? nowMs(),
            status: `BUY ORDER FILLED inferred_from_trades_fast orderId=${orderId} px=${inferred.filledPx} shares=${roundTo6(
              inferred.shares
            )}`,
          });
          let tpOrderId: string | null = null;
          if (opts?.armTpAfterBuy !== false) {
            try {
              tpOrderId = (await placeImmediateTpSellAfterBuy(side, inferred.shares, ui, tokenId, {
                buyFilledAtMs: filledAtMs,
                source: "trade_infer_fast",
                entryFillPx: inferred.filledPx,
                strategyId: opts?.strategyIdLike || null,
              })).orderId;
            } catch (tpErr: any) {
              console.error(`[IMMEDIATE TP SELL ERROR] ${String(tpErr?.message ?? tpErr)}`);
            }
          }
          return { filledPx: inferred.filledPx, shares: inferred.shares, tpOrderId, tokenId, filledAtMs, entryEventTsMs, orderId: String(orderId) };
        }
      } catch (e: any) {
        console.warn(`[BUY LIMIT] fast trade check failed orderId=${orderId}: ${String(e?.message ?? e)}`);
      }
    }

    await sleep(BUY_FILL_POLL_MS);
  }

  console.log(`[BUY LIMIT] TTL expired -> cancel orderId=${orderId}`);
  const timeoutCanceled = await cancelBuyOrderAndVerifyClosed(client as any, String(orderId), tokenId, "ttl_expired");
  if (!timeoutCanceled) {
    throw new Error(`[BUY LIMIT] ttl expired and cancel not confirmed (orderId=${orderId})`);
  }

  // ✅ TTL edge re-check (also accepts partial fills)
  try {
    const st2 = await (client as any).getOrder(orderId);
    const status2 = String(st2?.status || "").toUpperCase();

    const filledShares2 = Number(extractOrderMatchedShares(st2));
    const avgPx2 = Number(extractOrderAvgFillPx(st2) ?? NaN);

    if (Number.isFinite(filledShares2) && filledShares2 > 0) {
      const filledPx = Number.isFinite(avgPx2) ? avgPx2 : price;
      const filledAtMs = extractOrderFillTsMs(st2) ?? orderFillTsMs ?? null;
      const entryEventTsMs = extractOrderEntryTsMs(st2) ?? orderEntryTsMs ?? filledAtMs ?? null;
      await rejectInvalidFilledLiveBuyAtOrAboveTp(side, filledPx, filledShares2, ui, tokenId, "buy_limit_ttl_edge", ui?.strategyId);
      console.log(`[BUY LIMIT] FILLED after TTL edge orderId=${orderId} status=${status2} px=${filledPx} shares=${filledShares2}`);
      broadcast({
        type: "status",
        t: filledAtMs ?? nowMs(),
        status: `BUY ORDER FILLED orderId=${orderId} px=${filledPx} shares=${roundTo6(filledShares2)}`,
      });
      let tpOrderId: string | null = null;
      if (opts?.armTpAfterBuy !== false) {
        try {
          tpOrderId = (await placeImmediateTpSellAfterBuy(side, filledShares2, ui, tokenId, {
            buyFilledAtMs: filledAtMs,
            source: "ttl_edge",
            entryFillPx: filledPx,
            strategyId: opts?.strategyIdLike || null,
          })).orderId;
        } catch (tpErr: any) {
          console.error(`[IMMEDIATE TP SELL ERROR] ${String(tpErr?.message ?? tpErr)}`);
        }
      }
      return { filledPx, shares: filledShares2, tpOrderId, tokenId, filledAtMs, entryEventTsMs, orderId: String(orderId) };
    }
  } catch {}

  // Final fallback: infer fill from recent exchange trades for this token.
  try {
    const inferred = await inferRecentBuyFillFromTrades(client as any, tokenId, price, buyStartedAtMs);
    if (inferred && inferred.shares > 0) {
      const inferredPx = inferred.filledPx;
      const inferredShares = inferred.shares;
      const filledAtMs = inferred.firstFillTsMs ?? orderFillTsMs ?? null;
      const entryEventTsMs = orderEntryTsMs ?? filledAtMs ?? null;
      await rejectInvalidFilledLiveBuyAtOrAboveTp(side, inferredPx, inferredShares, ui, tokenId, "buy_limit_trade_infer", ui?.strategyId);
      console.log(`[BUY LIMIT] INFERRED FILLED from trades px=${inferredPx} shares=${roundTo6(inferredShares)} tokenId=${tokenId}`);
      broadcast({
        type: "status",
        t: filledAtMs ?? nowMs(),
        status: `BUY ORDER FILLED inferred_from_trades px=${inferredPx} shares=${roundTo6(inferredShares)}`,
      });
      let tpOrderId: string | null = null;
      if (opts?.armTpAfterBuy !== false) {
        try {
          tpOrderId = (await placeImmediateTpSellAfterBuy(side, inferredShares, ui, tokenId, {
            buyFilledAtMs: filledAtMs,
            source: "trade_infer",
            entryFillPx: inferredPx,
            strategyId: opts?.strategyIdLike || null,
          })).orderId;
        } catch (tpErr: any) {
          console.error(`[IMMEDIATE TP SELL ERROR] ${String(tpErr?.message ?? tpErr)}`);
        }
      }
      return { filledPx: inferredPx, shares: inferredShares, tpOrderId, tokenId, filledAtMs, entryEventTsMs, orderId: String(orderId) };
    }
  } catch (e: any) {
    console.warn(`[BUY LIMIT] trade-infer fallback failed: ${String(e?.message ?? e)}`);
  }

  // Last-resort fallback: infer fill from balance delta when order polling is inconsistent.
  // This is intentionally conservative and only applies right after a live buy attempt.
  try {
    await (client as any).updateBalanceAllowance?.({ asset_type: "COLLATERAL" });
    const balResp = await (client as any).getBalanceAllowance?.({ asset_type: "COLLATERAL" });
    const postBalRaw = Number(balResp?.balance ?? NaN);
    const postBalUsd = Number.isFinite(postBalRaw) ? postBalRaw / 1e6 : NaN;
    if (Number.isFinite(postBalUsd) && postBalUsd > 0) liveAccount.balanceUsd = postBalUsd;

    if (Number.isFinite(preBuyBalanceUsd) && Number.isFinite(postBalUsd)) {
      const spentUsd = Math.max(0, preBuyBalanceUsd - postBalUsd);
      if (spentUsd >= 0.25) {
      const inferredSharesRaw = spentUsd / price;
      let inferredShares = Math.min(Math.max(inferredSharesRaw, 0), MAX_SHARES_PER_TRADE);
      if (Number.isFinite(inferredShares) && inferredShares > 0) {
        // Balance-delta inference can under-estimate actual fills; trust token position when available.
        try {
          const posShares = await getLiveTokenPositionShares(client as any, tokenId);
          if (Number.isFinite(posShares as number)) {
            const pos = Math.max(0, Number(posShares));
            if (pos > inferredShares + 1e-6) {
              console.warn(
                `[BUY LIMIT] balance-infer corrected by position shares inferred=${roundTo6(inferredShares)} position=${roundTo6(pos)} tokenId=${tokenId}`
              );
              inferredShares = pos;
            }
          }
        } catch {}
        console.warn(
          `[BUY LIMIT] reject balance-delta inferred fill without venue timestamp spent=${roundTo6(spentUsd)} ` +
            `pre=${preBuyBalanceUsd} post=${postBalUsd} px=${price} shares=${roundTo6(inferredShares)} tokenId=${tokenId}`
        );
        throw new Error("[BUY LIMIT] inferred balance delta without venue fill timestamp");
        }
      }
    }
  } catch (e: any) {
    console.warn(`[BUY LIMIT] balance-infer fallback failed: ${String(e?.message ?? e)}`);
  }

  throw new Error(`[BUY LIMIT] Not filled within ttlMs=${ttl} (orderId=${orderId})`);
}

async function placeLiveMarketBuy(
  side: OutcomeSide,
  notionalUsd: number,
  ui: UiConfig,
  opts?: {
    armTpAfterBuy?: boolean;
    strictMarketOnly?: boolean;
    tokenIdOverride?: string | null;
    exposureTokenIds?: string[] | null;
    strategyIdLike?: string | null;
    orderType?: OrderType.FOK | OrderType.FAK;
    skipVenuePreflight?: boolean;
    skipHostLiveStateCheck?: boolean;
    fallbackPxOverride?: number | null;
    requireOrderTimelineFillTs?: boolean;
    onAccepted?: (meta: { acceptedAtMs: number; side: OutcomeSide; tokenId: string; orderId: string | null; notionalUsd: number }) => void | Promise<void>;
    onPostReturned?: (meta: { postReturnedAtMs: number; side: OutcomeSide; tokenId: string; orderId: string | null; notionalUsd: number }) => void | Promise<void>;
    onFirstFillSeen?: (meta: { firstFillSeenAtMs: number; side: OutcomeSide; tokenId: string; orderId: string | null; filledPx: number; shares: number; filledAtMs: number | null }) => void | Promise<void>;
    onFilledConfirmed?: (meta: { filledConfirmedAtMs: number; side: OutcomeSide; tokenId: string; orderId: string | null; filledPx: number; shares: number; filledAtMs: number | null }) => void | Promise<void>;
  }
): Promise<{ filledPx: number; shares: number; tpOrderId: string | null; tokenId: string; filledAtMs: number | null; entryEventTsMs: number | null; orderId: string | null }> {
  assertLiveOrderSubmissionAllowed(`buy_market_${side}`);
  if (!["UP", "DOWN"].includes(side)) throw new Error(`Invalid side value: ${side}`);
  if (!Number.isFinite(notionalUsd) || notionalUsd <= 0) throw new Error(`invalid notionalUsd: ${notionalUsd}`);
  const buyStartedAtMs = nowMs();
  const client = await getClobClient();
  const tokenId = String(opts?.tokenIdOverride || tokenIdForSide(side) || "");
  if (!tokenId) throw new Error(`[BUY MARKET] missing tokenId for side=${side}`);
  const tickNegRiskPromise = getTickNegRisk(tokenId);
  const latencyCritical = shouldUseLatencyCriticalLivePath(opts?.strategyIdLike);
  const skipVenuePreflight = !!opts?.skipVenuePreflight || latencyCritical;
  const marketOrderType = opts?.orderType || liveMarketOrderTypeForStrategy(opts?.strategyIdLike);
  const exposureTokenIds = Array.from(new Set(
    (Array.isArray(opts?.exposureTokenIds) ? opts?.exposureTokenIds : [String(current.upToken || ""), String(current.downToken || "")])
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  let prePositionShares = 0;
  let preConditionalBalanceShares = 0;
  if (!skipVenuePreflight) {
    await assertNoVenueExposureBeforeLiveEntry(client as any, "BUY MARKET", exposureTokenIds);
    const [prePositionSharesRaw, preConditional] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    prePositionShares = Number.isFinite(Number(prePositionSharesRaw)) ? Math.max(0, Number(prePositionSharesRaw)) : 0;
    preConditionalBalanceShares = Number.isFinite(Number(preConditional.balanceShares))
      ? Math.max(0, Number(preConditional.balanceShares))
      : 0;
  } else {
    prePositionShares = Number.isFinite(Number((stLive as any)?.lastPositionShares))
      ? Math.max(0, Number((stLive as any).lastPositionShares))
      : 0;
    preConditionalBalanceShares = Number.isFinite(Number((stLive as any)?.lastConditionalBalanceShares))
      ? Math.max(0, Number((stLive as any).lastConditionalBalanceShares))
      : 0;
  }
  const preCollateralBalanceUsd = Number.isFinite(Number(liveAccount.balanceUsd)) ? Number(liveAccount.balanceUsd) : null;
  if (!skipVenuePreflight) {
    const openBuySummary = await getOpenBuyOrderSummaryForTokens(client as any, exposureTokenIds);
    if (openBuySummary.count > 0) {
      throw new Error(
        `[BUY MARKET] open buy order already exists count=${openBuySummary.count} tokenIds=${openBuySummary.tokenIds.join(",")}`
      );
    }
  }
  if (!opts?.skipHostLiveStateCheck) {
    await reconcileLivePositionMaybe(true, "market-buy-helper-preflight");
    if (!stLive.entered || stLive.exited || !(stLive.side === "UP" || stLive.side === "DOWN")) {
      await hydrateLivePositionFromTokenBalances("market-buy-helper-preflight");
    }
    if (stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) {
      throw new Error(
        `[BUY MARKET] live position already exists side=${stLive.side} shares=${roundTo6(Number(stLive.shares ?? 0))}`
      );
    }
  }
  const quotePair = getCachedQuotePair(String(current.upToken), String(current.downToken), Number.POSITIVE_INFINITY);
  const bidPx = side === "UP" ? Number(quotePair?.upBid) : Number(quotePair?.downBid);
  const askPx = side === "UP" ? Number((quotePair as any)?.upAsk) : Number((quotePair as any)?.downAsk);
  const overrideFallbackPx = Number(opts?.fallbackPxOverride);
  const fallbackPx =
    Number.isFinite(overrideFallbackPx) && overrideFallbackPx > 0
      ? overrideFallbackPx
      : Number.isFinite(askPx) && askPx > 0
      ? askPx
      : (Number.isFinite(bidPx) && bidPx > 0 ? bidPx : 0.55);
  const explicitMarketPrice = latencyCritical ? latencyMarketBuyPriceForSide(side, fallbackPx) : null;
  assertEntryBelowTakeProfit(fallbackPx, ui, `buy_market_submit_${side}`, ui?.strategyId);
  const requestedNotionalUsd = floorTo6(Number(notionalUsd));
  if (!Number.isFinite(requestedNotionalUsd) || requestedNotionalUsd <= 0) {
    throw new Error(`invalid requestedNotionalUsd: ${requestedNotionalUsd}`);
  }
  const recoverFilledBuyAfterVenueError = async (
    source: string,
    reasonLike: any
  ): Promise<{ filledPx: number; shares: number; filledAtMs: number | null; entryEventTsMs: number | null; fillTimestampSource: "order_timeline" | "trade_infer" } | null> => {
    const reasonText = String(reasonLike?.message ?? reasonLike ?? "").trim();
    try {
      const fastConfirmed = await confirmRecentBuyFillFast(client as any, tokenId, fallbackPx, buyStartedAtMs, null);
      const fastFillTsMs =
        Number.isFinite(Number(fastConfirmed?.filledAtMs)) && Number(fastConfirmed?.filledAtMs) > 0
          ? Number(fastConfirmed?.filledAtMs)
          : null;
      if (fastConfirmed && fastConfirmed.shares > 0) {
        console.warn(
          `[BUY MKT RECOVER] source=${source} side=${side} tokenId=${tokenId} ` +
          `shares=${roundTo6(fastConfirmed.shares)} px=${roundTo6(fastConfirmed.filledPx)} ` +
          `filledAtMs=${fastFillTsMs ?? "-"} reason=${reasonText || "-"}`
        );
        return {
          filledPx: Number(fastConfirmed.filledPx),
          shares: Number(fastConfirmed.shares),
          filledAtMs: fastFillTsMs,
          entryEventTsMs:
            Number.isFinite(Number(fastConfirmed?.entryEventTsMs)) && Number(fastConfirmed?.entryEventTsMs) > 0
              ? Number(fastConfirmed.entryEventTsMs)
              : fastFillTsMs,
          fillTimestampSource: String(fastConfirmed?.fillTimestampSource || "trade_infer") === "order_timeline" ? "order_timeline" : "trade_infer",
        };
      }
      const fallbackSeedShares =
        Number.isFinite(fallbackPx) && fallbackPx > 0
          ? floorTo6(requestedNotionalUsd / fallbackPx)
          : 0;
      const reconciled = await reconcileLiveBuyFillFromVenue(client as any, tokenId, fallbackSeedShares, fallbackPx, {
        reason: source,
        prePositionShares,
        preConditionalBalanceShares,
        preCollateralBalanceUsd,
        startedAtMs: buyStartedAtMs,
        orderId: null,
      }).catch(() => null);
      if (!reconciled || !(Number(reconciled.shares) > 0)) return null;
      const tradeConfirmed = await inferRecentBuyFillFromTrades(
        client as any,
        tokenId,
        Number(reconciled.filledPx),
        buyStartedAtMs
      ).catch(() => null);
      const tradeFillTsMs =
        Number.isFinite(Number(tradeConfirmed?.firstFillTsMs)) && Number(tradeConfirmed?.firstFillTsMs) > 0
          ? Number(tradeConfirmed?.firstFillTsMs)
          : null;
      console.warn(
        `[BUY MKT RECOVER] source=${source} side=${side} tokenId=${tokenId} ` +
        `shares=${roundTo6(reconciled.shares)} px=${roundTo6(reconciled.filledPx)} ` +
        `filledAtMs=${tradeFillTsMs ?? "-"} reason=${reasonText || "-"}`
      );
      return {
        filledPx: Number(reconciled.filledPx),
        shares: Number(reconciled.shares),
        filledAtMs: tradeFillTsMs,
        entryEventTsMs: tradeFillTsMs,
        fillTimestampSource: "trade_infer",
      };
    } catch (recoverErr: any) {
      console.warn(
        `[BUY MKT RECOVER] source=${source} side=${side} tokenId=${tokenId} failed=${String(recoverErr?.message ?? recoverErr)} ` +
        `reason=${reasonText || "-"}`
      );
      return null;
    }
  };
  const { tickSize, negRisk } = await tickNegRiskPromise;
  const marketFn = (client as any).createAndPostMarketOrder;
  let order: any;
  if (typeof marketFn === "function") {
    let lastErr: any = null;
    for (let attempt = 1; attempt <= LIVE_MARKET_BUY_RETRY_ATTEMPTS; attempt++) {
      try {
        order = await marketFn.call(
          client,
          {
            tokenID: tokenId,
            side: ClobSide.BUY,
            amount: requestedNotionalUsd,
            feeRateBps: 1000,
            ...(Number.isFinite(Number(explicitMarketPrice)) && Number(explicitMarketPrice) > 0
              ? { price: Number(explicitMarketPrice), orderType: marketOrderType }
              : {}),
          },
          { tickSize, negRisk },
          marketOrderType,
          false
        );
        maybeThrowLiveExecutionHardBlock(order, `buy_market_response_${side}`);
        try {
          await opts?.onPostReturned?.({
            postReturnedAtMs: nowMs(),
            side,
            tokenId,
            orderId: extractOrderIdLike(order),
            notionalUsd: requestedNotionalUsd,
          });
        } catch (cbErr: any) {
          console.warn(`[BUY MKT POST RETURN CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
        }
        lastErr = null;
        break;
      } catch (e: any) {
        maybeThrowLiveExecutionHardBlock(e, `buy_market_post_${side}`);
        const recovered = await recoverFilledBuyAfterVenueError("market_buy_post_error", e);
        if (recovered && recovered.shares > 0) {
          order = {
            avgPrice: recovered.filledPx,
            filledSize: recovered.shares,
            ...(hasVerifiedVenueFillTs(recovered.filledAtMs) ? { filledAt: recovered.filledAtMs } : {}),
            ...(Number.isFinite(Number(recovered.entryEventTsMs)) && Number(recovered.entryEventTsMs) > 0
              ? { createdAt: recovered.entryEventTsMs }
              : {}),
          };
          lastErr = null;
          break;
        }
        lastErr = e;
        const msg = String(e?.message ?? e);
        const rearmable = shouldRearmLiveEntryAfterError(msg);
        const canRetry = rearmable && attempt < LIVE_MARKET_BUY_RETRY_ATTEMPTS;
        if (canRetry) {
          console.warn(
            `[BUY MKT RETRY] attempt=${attempt}/${LIVE_MARKET_BUY_RETRY_ATTEMPTS} side=${side} tokenId=${tokenId} reason=${msg}`
          );
          await sleep(LIVE_MARKET_BUY_RETRY_SLEEP_MS);
          continue;
        }
        throw e;
      }
    }
    if (!order) {
      throw lastErr ?? new Error("[BUY MKT] market order failed without response");
    }
  } else {
    throw new Error("[BUY MKT] market order API unavailable");
  }
  const orderId = extractOrderIdLike(order);
  const orderAcceptedAtMs = extractOrderEntryTsMs(order);
  const requireOrderTimelineFillTs = !!opts?.requireOrderTimelineFillTs;
  let acceptedCallbackEmitted = false;
  const emitAcceptedMaybe = async (acceptedAtMs: number | null, source: "user_ws" | "order_response") => {
    if (acceptedCallbackEmitted) return;
    if (!(Number.isFinite(Number(acceptedAtMs)) && Number(acceptedAtMs) > 0)) return;
    acceptedCallbackEmitted = true;
    try {
      await opts?.onAccepted?.({
        acceptedAtMs: Number(acceptedAtMs),
        side,
        tokenId,
        orderId,
        notionalUsd: requestedNotionalUsd,
        source,
      } as any);
    } catch (cbErr: any) {
      console.warn(`[BUY MKT ACCEPT CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
    }
  };
  const wsAcceptedNow = Number(getUserStreamOrderState(orderId)?.placedAtMs ?? NaN);
  if (Number.isFinite(wsAcceptedNow) && wsAcceptedNow > 0) {
    await emitAcceptedMaybe(wsAcceptedNow, "user_ws");
  } else if (orderId) {
    void waitForUserStreamOrderState(
      orderId,
      (state) => !!state && Number.isFinite(Number(state.placedAtMs)) && Number(state.placedAtMs) > 0,
      USER_STREAM_ACCEPT_WAIT_MS
    )
      .then(async (state) => {
        const wsAcceptedAtMs = Number(state?.placedAtMs ?? NaN);
        if (Number.isFinite(wsAcceptedAtMs) && wsAcceptedAtMs > 0) {
          await emitAcceptedMaybe(wsAcceptedAtMs, "user_ws");
          return;
        }
        if (Number.isFinite(Number(orderAcceptedAtMs)) && Number(orderAcceptedAtMs) > 0) {
          await emitAcceptedMaybe(Number(orderAcceptedAtMs), "order_response");
        }
      })
      .catch(() => {});
  } else if (Number.isFinite(Number(orderAcceptedAtMs)) && Number(orderAcceptedAtMs) > 0) {
    await emitAcceptedMaybe(Number(orderAcceptedAtMs), "order_response");
  }
  if (!orderId) {
    console.warn(
      `[BUY MKT] response missing orderId side=${side} tokenId=${tokenId} raw=${summarizeOrderLike(order)}`
    );
  }
  const orderFillTsMs = extractOrderFillTsMs(order);
  const orderEntryTsMs = extractOrderEntryTsMs(order) ?? orderFillTsMs;
  let fillTimestampSource: "order_timeline" | "trade_infer" | "unknown" =
    hasVerifiedVenueFillTs(orderFillTsMs) ? "order_timeline" : "unknown";
  const filledPxRaw = Number(extractOrderAvgFillPx(order) ?? NaN);
  let filledPx = Number.isFinite(filledPxRaw) && filledPxRaw > 0 ? filledPxRaw : fallbackPx;
  const filledSharesRaw = Number(extractOrderMatchedShares(order));
  let shares =
    Number.isFinite(filledSharesRaw) && filledSharesRaw > 0
      ? filledSharesRaw
      : (Number.isFinite(filledPx) && filledPx > 0 ? requestedNotionalUsd / filledPx : NaN);
  const fastConfirmed = await confirmRecentBuyFillFast(client as any, tokenId, filledPx, buyStartedAtMs, orderId);
  if (fastConfirmed && fastConfirmed.shares > 0) {
    shares = Number(fastConfirmed.shares);
    filledPx = Number.isFinite(Number(fastConfirmed.filledPx)) && Number(fastConfirmed.filledPx) > 0
      ? Number(fastConfirmed.filledPx)
      : filledPx;
    const filledAtMs = Number.isFinite(Number(fastConfirmed.filledAtMs)) && Number(fastConfirmed.filledAtMs) > 0
      ? Number(fastConfirmed.filledAtMs)
      : (orderFillTsMs ?? null);
    fillTimestampSource = String(fastConfirmed.fillTimestampSource || fillTimestampSource) === "order_timeline"
      ? "order_timeline"
      : (String(fastConfirmed.fillTimestampSource || fillTimestampSource) === "trade_infer" ? "trade_infer" : fillTimestampSource);
    const entryEventTsMs =
      Number.isFinite(Number(fastConfirmed.entryEventTsMs)) && Number(fastConfirmed.entryEventTsMs) > 0
        ? Number(fastConfirmed.entryEventTsMs)
        : (orderEntryTsMs ?? filledAtMs ?? null);
    if (!requireOrderTimelineFillTs || fillTimestampSource === "order_timeline") {
      try {
        await opts?.onFirstFillSeen?.({
          firstFillSeenAtMs: filledAtMs ?? nowMs(),
          side,
          tokenId,
          orderId,
          filledPx,
          shares,
          filledAtMs,
        });
      } catch (cbErr: any) {
        console.warn(`[BUY MKT FIRST FILL CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
      }
    }
    await rejectInvalidFilledLiveBuyAtOrAboveTp(side, filledPx, shares, ui, tokenId, "buy_market_fast_confirm", ui?.strategyId);
    broadcast({ type: "status", t: filledAtMs ?? nowMs(), status: `BUY ORDER FILLED market side=${side} px=${filledPx} shares=${roundTo6(shares)}` });
    let tpOrderId: string | null = null;
    if (opts?.armTpAfterBuy !== false) {
      try {
        tpOrderId = (await placeImmediateTpSellAfterBuy(side, shares, ui, tokenId, {
          buyFilledAtMs: filledAtMs,
          source: "market_buy_fast_confirm",
          entryFillPx: filledPx,
          strategyId: opts?.strategyIdLike || null,
        })).orderId;
      } catch {}
    }
    if (!requireOrderTimelineFillTs || fillTimestampSource === "order_timeline") {
      try {
        await opts?.onFilledConfirmed?.({
          filledConfirmedAtMs: filledAtMs ?? nowMs(),
          side,
          tokenId,
          orderId,
          filledPx,
          shares,
          filledAtMs,
        });
      } catch (cbErr: any) {
        console.warn(`[BUY MKT FILLED CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
      }
    }
    return { filledPx, shares, tpOrderId, tokenId, filledAtMs, entryEventTsMs, orderId, fillTimestampSource };
  }
  if (!Number.isFinite(shares) || shares <= 0) {
    throw new Error(`[BUY MKT] invalid filled share count response side=${side} filledPx=${filledPx} notionalUsd=${requestedNotionalUsd}`);
  }
  const reconciled = await reconcileLiveBuyFillFromVenue(client as any, tokenId, shares, filledPx, {
    reason: "market_buy",
    prePositionShares,
    preConditionalBalanceShares,
    preCollateralBalanceUsd,
    startedAtMs: buyStartedAtMs,
    orderId,
  });
  shares = reconciled.shares;
  filledPx = reconciled.filledPx;
  const tradeConfirmed = await inferRecentBuyFillFromTrades(client as any, tokenId, filledPx, buyStartedAtMs).catch(() => null);
  const filledAtMs =
    Number.isFinite(Number(tradeConfirmed?.firstFillTsMs)) && Number(tradeConfirmed?.firstFillTsMs) > 0
      ? Number(tradeConfirmed?.firstFillTsMs)
      : (orderFillTsMs ?? null);
  fillTimestampSource =
    Number.isFinite(Number(tradeConfirmed?.firstFillTsMs)) && Number(tradeConfirmed?.firstFillTsMs) > 0
      ? "trade_infer"
      : (hasVerifiedVenueFillTs(orderFillTsMs) ? "order_timeline" : "unknown");
  const entryEventTsMs = orderEntryTsMs ?? filledAtMs ?? null;
  if (!requireOrderTimelineFillTs || fillTimestampSource === "order_timeline") {
    try {
      await opts?.onFirstFillSeen?.({
        firstFillSeenAtMs: filledAtMs ?? nowMs(),
        side,
        tokenId,
        orderId,
        filledPx,
        shares,
        filledAtMs,
      });
    } catch (cbErr: any) {
      console.warn(`[BUY MKT FIRST FILL CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
    }
  }
  await rejectInvalidFilledLiveBuyAtOrAboveTp(side, filledPx, shares, ui, tokenId, "buy_market_reconcile", ui?.strategyId);
  if (!hasVerifiedVenueFillTs(filledAtMs)) {
    console.warn(
      `[BUY MKT] venue fill timestamp unavailable after buy reconcile side=${side} tokenId=${tokenId} ` +
      `orderId=${orderId || "none"} shares=${roundTo6(shares)} px=${roundTo6(filledPx)}`
    );
  }
  broadcast({ type: "status", t: filledAtMs ?? nowMs(), status: `BUY ORDER FILLED market side=${side} px=${filledPx} shares=${roundTo6(shares)}` });
  let tpOrderId: string | null = null;
  if (opts?.armTpAfterBuy !== false) {
    try {
      tpOrderId = (await placeImmediateTpSellAfterBuy(side, shares, ui, tokenId, {
        buyFilledAtMs: filledAtMs,
        source: "market_buy",
        entryFillPx: filledPx,
        strategyId: opts?.strategyIdLike || null,
      })).orderId;
    } catch {}
  }
  if (!requireOrderTimelineFillTs || fillTimestampSource === "order_timeline") {
    try {
      await opts?.onFilledConfirmed?.({
        filledConfirmedAtMs: filledAtMs ?? nowMs(),
        side,
        tokenId,
        orderId,
        filledPx,
        shares,
        filledAtMs,
      });
    } catch (cbErr: any) {
      console.warn(`[BUY MKT FILLED CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
    }
  }
  return { filledPx, shares, tpOrderId, tokenId, filledAtMs, entryEventTsMs, orderId, fillTimestampSource };
}

function clearLiveHcReentryFlags(st: TradeState) {
  (st as any).__baseMissForHc = false;
  (st as any).__baseMissAtMs = null;
  (st as any).__baseMissSide = null;
  (st as any).__allowHcAfterBaseTerminal = false;
  (st as any).__allowHcAfterBaseTerminalSide = null;
}

function clearLivePositionStateAfterTerminalExit(st: TradeState): void {
  st.entered = false;
  st.side = null;
  st.entryTsMs = null;
  st.entryPx = null;
  st.entryMode = null;
  st.entrySubtype = null;
  st.shares = null;
  st.notionalUsd = null;
  st.positionTokenId = null;
  st.buyFilledAtMs = null;
  st.firstSellAttemptAtMs = null;
  st.enterInFlight = false;
  st.exitInFlight = false;
  st.tpOrderInFlight = false;
  st.tpOrderId = null;
  st.pendingTpLimitPx = null;
  st.pendingTpPlacedAtMs = null;
  st.pendingTpShares = null;
  st.pendingTpExitType = null;
  (st as any).__suppressTpRearmUntilFlat = false;
}

async function suppressHostLiveTpProtectionForStopSignal(
  side: OutcomeSide,
  st: TradeState,
  reasonTag: string
): Promise<void> {
  const stAny = st as any;
  stAny.__suppressTpRearmUntilFlat = true;
  st.tpOrderInFlight = false;
  st.tpOrderId = null;
  st.pendingTpLimitPx = null;
  st.pendingTpPlacedAtMs = null;
  st.pendingTpShares = null;
  st.pendingTpExitType = null;
  try {
    await cancelOpenSellOrdersForSide(side, `${reasonTag}-cancel_tp_on_stop_signal`, st.positionTokenId);
  } catch (e: any) {
    console.warn(`[STOP TP CANCEL WARN] side=${side} reason=${reasonTag} err=${String(e?.message ?? e)}`);
  }
}

function activeOptimisticLiveStopRecovery():
  | { id: string; side: OutcomeSide; tokenId: string | null; startedAtMs: number; untilMs: number; reasonTag: string }
  | null {
  const stAny = stLive as any;
  const raw = stAny.__optimisticStopRecovery;
  if (!raw || typeof raw !== "object") return null;
  const untilMs = Number(raw.untilMs);
  if (!Number.isFinite(untilMs) || untilMs <= nowMs()) {
    stAny.__optimisticStopRecovery = null;
    return null;
  }
  const side = raw.side === "UP" || raw.side === "DOWN" ? raw.side : null;
  if (!side) {
    stAny.__optimisticStopRecovery = null;
    return null;
  }
  return {
    id: String(raw.id || ""),
    side,
    tokenId: String(raw.tokenId || "").trim() || null,
    startedAtMs: Number(raw.startedAtMs || nowMs()),
    untilMs,
    reasonTag: String(raw.reasonTag || "optimistic_stop_recovery"),
  };
}

function setOptimisticLiveStopRecovery(meta: {
  id: string;
  side: OutcomeSide;
  tokenId?: string | null;
  startedAtMs?: number | null;
  untilMs?: number | null;
  reasonTag?: string | null;
}): void {
  const stAny = stLive as any;
  stAny.__optimisticStopRecovery = {
    id: String(meta.id || ""),
    side: meta.side,
    tokenId: String(meta.tokenId || "").trim() || null,
    startedAtMs: Number.isFinite(Number(meta.startedAtMs)) ? Number(meta.startedAtMs) : nowMs(),
    untilMs:
      Number.isFinite(Number(meta.untilMs)) && Number(meta.untilMs) > 0
        ? Number(meta.untilMs)
        : (nowMs() + LIVE_OPTIMISTIC_STOP_REARM_WINDOW_MS),
    reasonTag: String(meta.reasonTag || "optimistic_stop_recovery"),
  };
}

function clearOptimisticLiveStopRecovery(recoveryId?: string | null): void {
  const stAny = stLive as any;
  const cur = stAny.__optimisticStopRecovery;
  if (!cur) return;
  if (recoveryId && String(cur.id || "") !== String(recoveryId || "")) return;
  stAny.__optimisticStopRecovery = null;
}

function rearmLiveSessionForNextLane(
  st: TradeState,
  priorEntryMode?: string | null,
  priorSide?: OutcomeSide | null,
  strategyIdLike?: any,
): void {
  clearLiveHcReentryFlags(st);
  if (shouldLimitLiveEntryToOnePerSlug(strategyIdLike)) {
    st.buyAttemptedSessionSlug = current.slug;
    st.buyAttemptedThisSession = true;
    st.buyFilledThisSession = true;
    return;
  }
  st.buyAttemptedSessionSlug = current.slug;
  st.buyAttemptedThisSession = false;
  st.buyFilledThisSession = false;
  st.lastEnterAttemptMs = null;
  const mode = String(priorEntryMode || "").toUpperCase();
  const side = priorSide === "UP" || priorSide === "DOWN" ? priorSide : null;
  if (mode === "BASE" && side) {
    (st as any).__allowHcAfterBaseTerminal = true;
    (st as any).__allowHcAfterBaseTerminalSide = side;
  }
}

async function placeImmediateTpSellAfterBuy(
  side: OutcomeSide,
  shares: number,
  ui: UiConfig,
  tokenIdOverride?: string | null,
  meta?: {
    buyFilledAtMs?: number;
    source?: string;
    entryFillPx?: number;
    strategyId?: string | null;
    fastPath?: boolean;
    limitPxOverride?: number | null;
    exitType?: string | null;
  }
): Promise<{ orderId: string; placedShares: number }> {
  assertLiveOrderSubmissionAllowed(`tp_limit_${side}`);
  if (!Number.isFinite(shares) || shares <= 0) throw new Error(`invalid shares for immediate TP sell: ${shares}`);
  const requestedShares = floorTo6(shares);
  if (!(requestedShares > 0)) throw new Error(`[IMMEDIATE TP SELL] invalid floored shares: ${requestedShares}`);
  const tpSource = String(meta?.source || "").trim().toLowerCase();
  const explicitLimitPx = clamp01(Number(meta?.limitPxOverride));
  const genericAfterBuyTpSource =
    tpSource === "bot_live_entry" ||
    tpSource === "order_poll" ||
    tpSource === "trade_infer_fast" ||
    tpSource === "ttl_edge" ||
    tpSource === "trade_infer" ||
    tpSource === "market_buy_fast_confirm" ||
    tpSource === "market_buy" ||
    tpSource === "tp_rearm";
  if (genericAfterBuyTpSource && !(Number.isFinite(explicitLimitPx) && explicitLimitPx > 0)) {
    throw new Error("GENERIC_IMMEDIATE_TP_DISABLED");
  }
  if (
    isInflectionPositiveSlopeFamilyStrategy(meta?.strategyId) &&
    !(Number.isFinite(explicitLimitPx) && explicitLimitPx > 0)
  ) {
    throw new Error("INFLECTION_GENERIC_TP_DISABLED");
  }
  const useFastPath =
    !!meta?.fastPath ||
    isLatencyProbeStrategy(meta?.strategyId) ||
    isInflectionPositiveSlopeFamilyStrategy(meta?.strategyId);
  const entryFillPx = Number(meta?.entryFillPx);
  const tpPx =
    Number.isFinite(explicitLimitPx) && explicitLimitPx > 0
      ? explicitLimitPx
      : computeImmediateTpSellPx(ui, entryFillPx);
  const exitTypeLabel = String(meta?.exitType || "EXIT").trim().toUpperCase() || "EXIT";
  const tpStartMs = nowMs();
  const buyToTpStartMs = Number.isFinite(Number(meta?.buyFilledAtMs)) ? Math.max(0, tpStartMs - Number(meta?.buyFilledAtMs)) : null;
  console.log(
    `[TP LATENCY] source=${meta?.source ?? "unknown"} side=${side} ` +
    `buyFilledToTpStartMs=${buyToTpStartMs ?? "na"} shares=${roundTo6(shares)} ` +
    `tpPx=${tpPx} exitType=${exitTypeLabel} mode=${Number.isFinite(explicitLimitPx) ? "explicit_limit" : "absolute_ui_exit"} entryFillPx=${Number.isFinite(entryFillPx) ? entryFillPx : "na"}`
  );

  const client = await getClobClient();
  const tokenId = tokenIdOverride || tokenIdForSide(side);
  const { tickSize, negRisk } = await getTickNegRisk(tokenId);
  const reuseOrClearExistingSell = async (
    minShares: number
  ): Promise<{ orderId: string; placedShares: number } | null> => {
    const open = await (client as any).getOpenOrders?.({ asset_id: tokenId });
    const openOrders = Array.isArray(open) ? open : [];
    const existingSell = openOrders.find((o: any) => String(o?.side || "").toUpperCase() === "SELL");
    if (!existingSell) return null;
    const existingId = String(existingSell?.id ?? existingSell?.orderID ?? existingSell?.orderId ?? "");
    const existingSize = floorTo6(Number(existingSell?.original_size ?? existingSell?.size ?? existingSell?.initialSize ?? 0));
    if (existingId && existingSize >= minShares - 1e-6) {
      console.log(
        `[IMMEDIATE TP SELL] existing open sell reused orderId=${existingId} side=${side} tokenId=${tokenId} ` +
        `existingShares=${roundTo6(existingSize)} requestedShares=${roundTo6(minShares)}`
      );
      return { orderId: existingId, placedShares: existingSize };
    }
    if (existingId) {
      console.warn(
        `[IMMEDIATE TP SELL] cancel undersized existing sell orderId=${existingId} side=${side} tokenId=${tokenId} ` +
        `existingShares=${roundTo6(existingSize)} requestedShares=${roundTo6(minShares)}`
      );
      try {
        await cancelOrderRobust(client as any, existingId);
      } catch (e: any) {
        console.warn(`[IMMEDIATE TP SELL] failed to cancel undersized sell orderId=${existingId}: ${String(e?.message ?? e)}`);
      }
    }
    return null;
  };

  // Idempotency guard: if a TP sell is already open for this token, reuse it.
  if (!useFastPath) {
    try {
      const reused = await reuseOrClearExistingSell(requestedShares);
      if (reused) return reused;
    } catch (e: any) {
      console.warn(`[IMMEDIATE TP SELL] open-order precheck failed: ${String(e?.message ?? e)}`);
    }
  }
  let lastErr: any = null;
  let loggedWaitSellabilityEvent = false;
  let loggedForcePostEvent = false;
  let loggedClampEvent = false;
  let loggedSellableEvent = false;
  let loggedFirstSubmitEvent = false;
  const shareTolerance = 1e-6;
  for (let attempt = 1; attempt <= 40; attempt++) {
    const sellability = await syncSellableShares(client as any, tokenId, requestedShares, "immediate_tp");
    const sellableShares = floorTo6(Math.max(0, Number(sellability.sellableShares ?? 0)));
    const posLike = Math.max(Number(sellability.positionShares ?? 0), Number(sellability.conditionalBalanceShares ?? 0));
    const posLikeRounded = floorTo6(Math.max(0, posLike));
    const verifiedAvailableShares = floorTo6(
      Math.max(0, Math.min(requestedShares, Math.max(sellableShares, posLikeRounded)))
    );
    const fullRequestedAvailable =
      sellableShares >= requestedShares - shareTolerance ||
      posLikeRounded >= requestedShares - shareTolerance;
    const shouldForcePostAttempt = attempt >= (useFastPath ? 1 : IMMEDIATE_TP_FORCE_POST_AFTER_ATTEMPTS);
    const shouldClampToVerifiedShares =
      !fullRequestedAvailable &&
      shouldClampImmediateTpToVerifiedShares(requestedShares, verifiedAvailableShares);
    if (!loggedSellableEvent && verifiedAvailableShares > shareTolerance) {
      const detectedAtMs = nowMs();
      const buyToSellableMs = Number.isFinite(Number(meta?.buyFilledAtMs))
        ? Math.max(0, detectedAtMs - Number(meta?.buyFilledAtMs))
        : null;
      appendLiveBotDiagnosticEventForCurrentSlug({
          event: "tp_sellable_detected",
          side,
          exitType: exitTypeLabel.toLowerCase(),
          exitPx: tpPx,
        sharesRequested: requestedShares,
        sharesRemaining: verifiedAvailableShares,
        reason:
          `TP_SELLABLE_DETECTED requested=${roundTo6(requestedShares)} sellable=${roundTo6(verifiedAvailableShares)} ` +
          `attempt=${attempt} buyFilledToSellableMs=${buyToSellableMs ?? "na"} fastPath=${useFastPath ? 1 : 0}`,
        eventTsMs: detectedAtMs,
      }, { side, tokenId, marketSlug: current.slug });
      loggedSellableEvent = true;
    }
    if (!fullRequestedAvailable && !shouldForcePostAttempt && !shouldClampToVerifiedShares) {
      console.log(
        `[IMMEDIATE TP SELL] waiting for full sellability tokenId=${tokenId} ` +
        `requested=${roundTo6(requestedShares)} sellable=${roundTo6(sellableShares)} ` +
        `position=${roundTo6(posLikeRounded)} attempt=${attempt}`
      );
      if (!loggedWaitSellabilityEvent) {
        appendLiveBotDiagnosticEventForCurrentSlug({
          event: "tp_wait_sellability",
          side,
          exitType: exitTypeLabel.toLowerCase(),
          exitPx: tpPx,
          sharesRequested: requestedShares,
          sharesRemaining: sellableShares,
          reason:
            `TP_WAIT_SELLABILITY requested=${roundTo6(requestedShares)} ` +
            `sellable=${roundTo6(sellableShares)} position=${roundTo6(posLikeRounded)} attempt=${attempt}`,
          eventTsMs: nowMs(),
        }, { side, tokenId, marketSlug: current.slug });
        loggedWaitSellabilityEvent = true;
      }
      await sleep(useFastPath ? Math.min(25 + 10 * attempt, 90) : Math.min(200 + 100 * attempt, 1200));
      continue;
    }
    if (!fullRequestedAvailable && shouldForcePostAttempt) {
      console.warn(
        `[IMMEDIATE TP SELL] forcing post attempt before full sellability tokenId=${tokenId} ` +
        `requested=${roundTo6(requestedShares)} sellable=${roundTo6(sellableShares)} ` +
        `position=${roundTo6(posLikeRounded)} attempt=${attempt}`
      );
      if (!loggedForcePostEvent) {
        appendLiveBotDiagnosticEventForCurrentSlug({
          event: "tp_force_post",
          side,
          exitType: exitTypeLabel.toLowerCase(),
          exitPx: tpPx,
          sharesRequested: requestedShares,
          sharesRemaining: sellableShares,
          reason:
            `TP_FORCE_POST requested=${roundTo6(requestedShares)} ` +
            `sellable=${roundTo6(sellableShares)} position=${roundTo6(posLikeRounded)} attempt=${attempt}`,
          eventTsMs: nowMs(),
        }, { side, tokenId, marketSlug: current.slug });
        loggedForcePostEvent = true;
      }
    }
    const sellShares =
      (!fullRequestedAvailable && (shouldForcePostAttempt || shouldClampToVerifiedShares) && verifiedAvailableShares > shareTolerance)
        ? verifiedAvailableShares
        : requestedShares;
    if (sellShares < requestedShares - shareTolerance) {
      console.warn(
        `[IMMEDIATE TP SELL] clamp to verified venue shares tokenId=${tokenId} ` +
        `requested=${roundTo6(requestedShares)} posting=${roundTo6(sellShares)} ` +
        `sellable=${roundTo6(sellableShares)} position=${roundTo6(posLikeRounded)} attempt=${attempt}`
      );
      if (!loggedClampEvent) {
        appendLiveBotDiagnosticEventForCurrentSlug({
          event: "tp_clamp_shares",
          side,
          exitType: exitTypeLabel.toLowerCase(),
          exitPx: tpPx,
          shares: sellShares,
          sharesRequested: requestedShares,
          sharesRemaining: verifiedAvailableShares,
          reason:
            `TP_CLAMP_SHARES requested=${roundTo6(requestedShares)} posting=${roundTo6(sellShares)} ` +
            `sellable=${roundTo6(sellableShares)} position=${roundTo6(posLikeRounded)} attempt=${attempt}`,
          eventTsMs: nowMs(),
        }, { side, tokenId, marketSlug: current.slug });
        loggedClampEvent = true;
      }
    }

    try {
      // Avoid posting duplicates if a previous attempt already placed a sell.
      if (!useFastPath || attempt > 1) {
        const reused = await reuseOrClearExistingSell(sellShares);
        if (reused) return reused;
      }

      if (!useFastPath || attempt > 1) {
        await (client as any).updateBalanceAllowance?.({ asset_type: "CONDITIONAL", token_id: tokenId });
      }
      if (!loggedFirstSubmitEvent) {
        const submitAtMs = nowMs();
        const buyToFirstSubmitMs = Number.isFinite(Number(meta?.buyFilledAtMs))
          ? Math.max(0, submitAtMs - Number(meta?.buyFilledAtMs))
          : null;
        appendLiveBotDiagnosticEventForCurrentSlug({
          event: "tp_first_submit",
          side,
          exitType: exitTypeLabel.toLowerCase(),
          exitPx: tpPx,
          sharesRequested: requestedShares,
          shares: sellShares,
          reason:
            `TP_FIRST_SUBMIT requested=${roundTo6(requestedShares)} posting=${roundTo6(sellShares)} ` +
            `attempt=${attempt} buyFilledToFirstSubmitMs=${buyToFirstSubmitMs ?? "na"} fastPath=${useFastPath ? 1 : 0}`,
          eventTsMs: submitAtMs,
        }, { side, tokenId, marketSlug: current.slug });
        loggedFirstSubmitEvent = true;
      }

      const ord = await client.createAndPostOrder(
        {
          tokenID: tokenId,
          price: roundTo6(tpPx),
          side: ClobSide.SELL,
          size: sellShares,
          feeRateBps: 1000,
        },
        { tickSize: tickSize as any, negRisk },
        OrderType.GTC
      );

      maybeThrowLiveExecutionHardBlock(ord, `tp_limit_response_${side}`);
      let orderId = extractOrderIdLike(ord);
      if (!orderId) {
        maybeThrowLiveExecutionHardBlock(ord, `tp_limit_missing_order_id_${side}`);
        for (let postCheck = 1; postCheck <= 5; postCheck++) {
          await sleep(Math.min(150 * postCheck, 600));
          const reusedAfterPost = await reuseOrClearExistingSell(sellShares);
          if (reusedAfterPost) return reusedAfterPost;
        }
        throw new Error(`[IMMEDIATE TP SELL] no orderId returned raw=${summarizeOrderLike(ord)}`);
      }
      const tpPlacedMs = nowMs();
      const tpRoundTripMs = tpPlacedMs - tpStartMs;
      const buyToTpPlacedMs = Number.isFinite(Number(meta?.buyFilledAtMs)) ? Math.max(0, tpPlacedMs - Number(meta?.buyFilledAtMs)) : null;

      console.log(
        `[IMMEDIATE TP SELL] placed side=${side} px=${tpPx} shares=${roundTo6(sellShares)} orderId=${orderId} slug=${current.slug} ` +
        `tpSubmitRoundTripMs=${tpRoundTripMs} buyFilledToTpPlacedMs=${buyToTpPlacedMs ?? "na"} attempt=${attempt}`
      );
      appendLiveBotDiagnosticEventForCurrentSlug({
        event: "tp_placed",
        side,
        exitType: exitTypeLabel.toLowerCase(),
        exitPx: tpPx,
        sharesRequested: requestedShares,
        shares: sellShares,
        reason:
          `TP_PLACED orderId=${orderId} requested=${roundTo6(requestedShares)} posting=${roundTo6(sellShares)} ` +
          `attempt=${attempt} buyFilledToTpPlacedMs=${buyToTpPlacedMs ?? "na"} tpSubmitRoundTripMs=${tpRoundTripMs} fastPath=${useFastPath ? 1 : 0}`,
        eventTsMs: tpPlacedMs,
      }, { side, tokenId, marketSlug: current.slug });
      broadcast({
        type: "status",
        t: nowMs(),
        status:
          `SELL ORDER PLACED orderId=${orderId} px=${tpPx} shares=${roundTo6(sellShares)} (immediate TP)` +
          ` latencyMs=${buyToTpPlacedMs ?? "na"}`,
      });
      return { orderId: String(orderId), placedShares: sellShares };
    } catch (e: any) {
      maybeThrowLiveExecutionHardBlock(e, `tp_limit_post_${side}`);
      lastErr = e;
      const msg = String(e?.message ?? e).toLowerCase();
      if (msg.includes("lower than the minimum")) {
        const available2 = await getLiveTokenPositionShares(client as any, tokenId);
        if (Number.isFinite(available2 as number) && Number(available2) >= LIVE_MIN_SELLABLE_SHARES) {
          await sleep(useFastPath ? Math.min(25 + 10 * attempt, 90) : Math.min(200 + 100 * attempt, 1200));
          continue;
        }
      }
      if (msg.includes("not enough balance") || msg.includes("allowance")) {
        await (client as any).updateBalanceAllowance?.({ asset_type: "CONDITIONAL", token_id: tokenId });
        await sleep(useFastPath ? Math.min(25 + 10 * attempt, 90) : Math.min(200 + 100 * attempt, 1200));
        continue;
      }
      throw e;
    }
  }
  throw lastErr ?? new Error("[IMMEDIATE TP SELL] failed after retries");
}

async function syncLiveSharesForFullExit(
  st: TradeState,
  side: OutcomeSide,
  reason: string
): Promise<number> {
  const tokenId = String(st.positionTokenId || tokenIdForSide(side) || "");
  const localShares = floorTo6(Math.max(0, Number(st.shares ?? 0)));
  if (!tokenId) return localShares;
  try {
    const client = await getClobClient();
    const [posRaw, cond] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    const posShares = Number.isFinite(Number(posRaw)) ? floorTo6(Math.max(0, Number(posRaw))) : 0;
    const condBal = Number.isFinite(Number(cond.balanceShares)) ? floorTo6(Math.max(0, Number(cond.balanceShares))) : 0;
    const resolvedShares = Math.max(localShares, posShares, condBal);
    if (resolvedShares > localShares + 1e-6) {
      console.warn(
        `[LIVE EXIT SHARES SYNC] reason=${reason} side=${side} shares=${roundTo6(localShares)} -> ${roundTo6(resolvedShares)} tokenId=${tokenId}`
      );
      st.shares = resolvedShares;
    }
    return resolvedShares;
  } catch (e: any) {
    console.warn(`[LIVE EXIT SHARES SYNC ERROR] reason=${reason} side=${side} err=${String(e?.message ?? e)}`);
    return localShares;
  }
}

function applyLiveSellLegAccounting(
  st: TradeState,
  exitPxRaw: number,
  sellSharesRaw: number,
  exitFeeMode: ExitFeeMode
) {
  return applyPaperSellLegAccounting(st, exitPxRaw, sellSharesRaw, exitFeeMode);
}

async function getLiveVenueSharesSnapshot(
  side: OutcomeSide,
  st?: Pick<TradeState, "positionTokenId">
): Promise<{
  tokenId: string;
  positionShares: number | null;
  conditionalBalanceShares: number | null;
  conditionalAllowanceShares: number | null;
  shares: number | null;
  error: string | null;
}> {
  const tokenId = String(st?.positionTokenId || tokenIdForSide(side) || "");
  if (!tokenId) {
    return {
      tokenId: "",
      positionShares: null,
      conditionalBalanceShares: null,
      conditionalAllowanceShares: null,
      shares: null,
      error: "missing_token_id",
    };
  }
  try {
    const client = await getClobClient();
    const [posRaw, cond] = await Promise.all([
      getLiveTokenPositionShares(client as any, tokenId),
      getConditionalBalanceAllowanceShares(client as any, tokenId),
    ]);
    const positionShares = Number.isFinite(Number(posRaw)) ? floorTo6(Math.max(0, Number(posRaw))) : null;
    const conditionalBalanceShares = Number.isFinite(Number(cond.balanceShares))
      ? floorTo6(Math.max(0, Number(cond.balanceShares)))
      : null;
    const conditionalAllowanceShares = Number.isFinite(Number(cond.allowanceShares))
      ? floorTo6(Math.max(0, Number(cond.allowanceShares)))
      : null;
    const shares = Math.max(positionShares ?? 0, conditionalBalanceShares ?? 0);
    return {
      tokenId,
      positionShares,
      conditionalBalanceShares,
      conditionalAllowanceShares,
      shares: Number.isFinite(shares) ? floorTo6(shares) : null,
      error: cond.error ? String(cond.error) : null,
    };
  } catch (e: any) {
    return {
      tokenId,
      positionShares: null,
      conditionalBalanceShares: null,
      conditionalAllowanceShares: null,
      shares: null,
      error: String(e?.message ?? e),
    };
  }
}

async function recoverLiveSharesForExit(
  st: TradeState,
  side: OutcomeSide,
  reason: string,
  preSnapshot?: {
    tokenId: string;
    positionShares: number | null;
    conditionalBalanceShares: number | null;
    conditionalAllowanceShares: number | null;
    shares: number | null;
    error: string | null;
  } | null
): Promise<number> {
  const shouldEmitLiveExitRecoverWarn = (warnKeyLike: string, cooldownMs = 5000): boolean => {
    const warnKey = String(warnKeyLike || "").trim();
    if (!warnKey) return true;
    const stAny = st as any;
    const bucket = stAny.__liveExitRecoverWarnAtByKey && typeof stAny.__liveExitRecoverWarnAtByKey === "object"
      ? stAny.__liveExitRecoverWarnAtByKey
      : {};
    const now = nowMs();
    const lastAt = Number(bucket[warnKey] || 0);
    if (Number.isFinite(lastAt) && lastAt > 0 && (now - lastAt) < Math.max(250, Number(cooldownMs) || 0)) {
      stAny.__liveExitRecoverWarnAtByKey = bucket;
      return false;
    }
    bucket[warnKey] = now;
    stAny.__liveExitRecoverWarnAtByKey = bucket;
    return true;
  };
  const localShares = floorTo6(Math.max(0, Number(st.shares ?? 0)));
  const snap = preSnapshot ?? await getLiveVenueSharesSnapshot(side, st);
  const venueShares = Number.isFinite(Number(snap.shares)) ? floorTo6(Math.max(0, Number(snap.shares))) : 0;
  const killSwitchReason = String(reason || "").toLowerCase().includes("kill_switch");
  const resolvedShares = snap.error
    ? (killSwitchReason ? 0 : localShares)
    : venueShares;

  if (killSwitchReason && snap.error) {
    const warnKey = `blocked|${String(reason || "")}|${String(side || "")}|${String(snap.tokenId || "-")}|${String(snap.error || "")}`;
    if (shouldEmitLiveExitRecoverWarn(warnKey, 5000)) {
      console.warn(
        `[LIVE EXIT RECOVER BLOCKED] reason=${reason} side=${side} ` +
        `localShares=${roundTo6(localShares)} tokenId=${snap.tokenId || "-"} err=${snap.error}`
      );
    }
  }

  if (resolvedShares > 0) {
    if (Math.abs(resolvedShares - localShares) > 1e-6) {
      const warnKey =
        `recover|${String(reason || "")}|${String(side || "")}|${String(snap.tokenId || "-")}|` +
        `${roundTo6(localShares)}|${roundTo6(resolvedShares)}|${String(snap.positionShares ?? "-")}|${String(snap.conditionalBalanceShares ?? "-")}`;
      if (shouldEmitLiveExitRecoverWarn(warnKey, 5000)) {
        console.warn(
          `[LIVE EXIT RECOVER] reason=${reason} side=${side} shares=${roundTo6(localShares)} -> ${roundTo6(resolvedShares)} ` +
          `tokenId=${snap.tokenId} pos=${snap.positionShares ?? "-"} condBal=${snap.conditionalBalanceShares ?? "-"}`
        );
      }
    }
    st.entered = true;
    st.exited = false;
    st.side = side;
    st.positionTokenId = snap.tokenId || st.positionTokenId || tokenIdForSide(side);
    st.shares = resolvedShares;
    st.marketSlug = current.slug || st.marketSlug;
    st.marketStartMs = current.startMs || st.marketStartMs;
    st.marketEndMs = current.endMs || st.marketEndMs;
    st.buyAttemptedSessionSlug = current.slug || st.buyAttemptedSessionSlug || null;
    st.buyAttemptedThisSession = true;
    st.buyFilledThisSession = true;
  }
  return resolvedShares;
}

async function executeLiveVerifiedMarketExit(
  side: OutcomeSide,
  shares: number,
  ui: UiConfig,
  st: Pick<TradeState, "positionTokenId">,
  reasonTag: string,
  opts?: {
    onSubmitted?: (meta: { submittedAtMs: number; side: OutcomeSide; shares: number; tokenId: string; orderId: string | null }) => void | Promise<void>;
    preSnapshot?: {
      tokenId: string;
      positionShares: number | null;
      conditionalBalanceShares: number | null;
      conditionalAllowanceShares: number | null;
      shares: number | null;
      error: string | null;
    } | null;
  }
): Promise<{ filledPx: number; filledShares: number; remainingShares: number; attempts: number; orderId: string | null; filledAtMs: number | null; exitEventTsMs: number | null }> {
  let remaining = floorTo6(Math.max(0, Number(shares || 0)));
  let filledSharesTotal = 0;
  let filledNotional = 0;
  let attempts = 0;
  let lastErr: any = null;
  let lastOrderId: string | null = null;
  let lastFilledAtMs: number | null = null;
  let lastExitEventTsMs: number | null = null;
  const killSwitchReason = String(reasonTag || "").toLowerCase().includes("kill_switch");

  while (attempts < LIVE_EXIT_VERIFY_ATTEMPTS && remaining > 1e-9) {
    const before = attempts === 0 && opts?.preSnapshot
      ? opts.preSnapshot
      : await getLiveVenueSharesSnapshot(side, st);
    const venueBefore = Number.isFinite(Number(before.shares)) ? floorTo6(Math.max(0, Number(before.shares))) : NaN;
    const requested = Number.isFinite(venueBefore) && venueBefore > 0 ? venueBefore : remaining;
    if (killSwitchReason && !(Number.isFinite(venueBefore) && venueBefore > 0)) {
      console.warn(
        `[LIVE EXIT VERIFY BLOCKED] reason=${reasonTag} attempt=${attempts + 1}/${LIVE_EXIT_VERIFY_ATTEMPTS} ` +
        `side=${side} staleLocalRemaining=${roundTo6(remaining)} venueShares=${Number.isFinite(venueBefore) ? roundTo6(venueBefore) : "na"} ` +
        `err=${before.error ?? "-"}`
      );
      remaining = 0;
      break;
    }
    if (!(requested > 1e-9)) {
      remaining = 0;
      break;
    }
    attempts += 1;

    try {
      const out = await placeLiveMarketSell(side, requested, ui, st as TradeState, {
        onSubmitted: attempts === 1 ? opts?.onSubmitted : undefined,
        preSellSnapshot: attempts === 1
          ? {
              positionShares: Number.isFinite(Number(before.positionShares)) ? Number(before.positionShares) : null,
              conditionalBalanceShares: Number.isFinite(Number(before.conditionalBalanceShares)) ? Number(before.conditionalBalanceShares) : null,
            }
          : undefined,
      });
      lastOrderId = out.orderId ?? lastOrderId;
      lastFilledAtMs = out.filledAtMs ?? lastFilledAtMs;
      lastExitEventTsMs = out.exitEventTsMs ?? lastExitEventTsMs;
      const after = await getLiveVenueSharesSnapshot(side, st);
      const venueAfterRaw = Number.isFinite(Number(after.shares))
        ? floorTo6(Math.max(0, Number(after.shares)))
        : null;
      const venueAfter = computeVerifiedExitRemainingShares(requested, Number(out.filledShares || 0), venueAfterRaw);
      const soldActual = floorTo6(Math.max(0, requested - venueAfter));
      if (soldActual > 1e-9) {
        filledSharesTotal += soldActual;
        filledNotional += Number(out.filledPx) * soldActual;
      }
      remaining = venueAfter;
      const stAny = st as any;
      if ("shares" in stAny) stAny.shares = remaining;
      console.log(
        `[LIVE EXIT VERIFY] reason=${reasonTag} attempt=${attempts}/${LIVE_EXIT_VERIFY_ATTEMPTS} ` +
        `side=${side} requested=${roundTo6(requested)} sold=${roundTo6(soldActual)} remaining=${roundTo6(remaining)}`
      );
      if (remaining <= 1e-9) break;
    } catch (e: any) {
      lastErr = e;
      console.warn(
        `[LIVE EXIT VERIFY WARN] reason=${reasonTag} attempt=${attempts}/${LIVE_EXIT_VERIFY_ATTEMPTS} ` +
        `side=${side} err=${String(e?.message ?? e)}`
      );
      if (attempts < LIVE_EXIT_VERIFY_ATTEMPTS) await sleep(LIVE_MARKET_SELL_RETRY_SLEEP_MS);
    }
  }

  if (filledSharesTotal <= 1e-9 && lastErr) throw lastErr;
  const avgFilledPx = filledSharesTotal > 0 ? (filledNotional / filledSharesTotal) : 0;
  return {
    filledPx: avgFilledPx > 0 ? avgFilledPx : 0.01,
    filledShares: floorTo6(filledSharesTotal),
    remainingShares: floorTo6(Math.max(0, remaining)),
    attempts,
    orderId: lastOrderId,
    filledAtMs: lastFilledAtMs,
    exitEventTsMs: lastExitEventTsMs,
  };
}

async function cancelOpenOrdersForToken(
  tokenIdRaw: string,
  reason: string,
  sideFilter?: "BUY" | "SELL" | null
): Promise<number> {
  const tokenId = String(tokenIdRaw || "").trim();
  if (!tokenId) return 0;
  const client = await getClobClient();
  const open = await (client as any).getOpenOrders?.({ asset_id: tokenId });
  const openOrders = Array.isArray(open) ? open : [];
  let canceled = 0;
  for (const o of openOrders) {
    const side = String(o?.side || "").toUpperCase();
    if (sideFilter && side !== sideFilter) continue;
    const oid = openOrderId(o);
    if (!oid) continue;
    try {
      await cancelOrderRobust(client as any, oid);
      canceled += 1;
      console.log(`[CANCEL OPEN ORDER] reason=${reason} tokenId=${tokenId} side=${side} orderId=${oid}`);
    } catch (e: any) {
      console.warn(
        `[CANCEL OPEN ORDER ERROR] reason=${reason} tokenId=${tokenId} side=${side} orderId=${oid} ` +
        `err=${String(e?.message ?? e)}`
      );
    }
  }
  return canceled;
}

async function cancelOpenOrdersForTokens(
  tokenIdsRaw: string[],
  reason: string,
  sideFilter?: "BUY" | "SELL" | null
): Promise<number> {
  const tokenIds = Array.from(new Set(
    (Array.isArray(tokenIdsRaw) ? tokenIdsRaw : [])
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  let canceled = 0;
  for (const tokenId of tokenIds) {
    canceled += await cancelOpenOrdersForToken(tokenId, reason, sideFilter);
  }
  return canceled;
}

async function cancelOpenSellOrdersForSide(side: OutcomeSide, reason: string, tokenIdOverride?: string | null): Promise<number> {
  if (!side) return 0;
  const tokenId = tokenIdOverride || tokenIdForSide(side);
  const canceled = await cancelOpenOrdersForToken(tokenId, reason, "SELL");
  if (canceled > 0) {
    if (stLive.side === side) stLive.tpOrderId = null;
    broadcast({
      type: "status",
      t: nowMs(),
      status: `Canceled ${canceled} open sell order(s) for ${side} before ${reason}`,
    });
  }
  return canceled;
}

async function maybeResolveHostLiveTpFill(reasonTag = "periodic"): Promise<boolean> {
  if (!uiLive.enabled) return false;
  if (!stLive.entered || stLive.exited || !stLive.side || !(Number(stLive.shares) > 1e-9)) return false;
  const orderId = String(stLive.tpOrderId || "").trim();
  if (!orderId) return false;
  const side = stLive.side;
  const tokenId = String(stLive.positionTokenId || tokenIdForSide(side) || "");
  if (!tokenId) return false;
  const stAny = stLive as any;
  const client = await getClobClient();
  let ord: any = null;
  try {
    ord = await (client as any).getOrder(orderId);
  } catch (e: any) {
    console.warn(`[HOST TP WATCH] getOrder failed orderId=${orderId} err=${String(e?.message ?? e)}`);
    return false;
  }
  const status = String(ord?.status || "").toUpperCase();
  const startedAtMs =
    Number.isFinite(Number(stLive.pendingTpPlacedAtMs)) && Number(stLive.pendingTpPlacedAtMs) > 0
      ? Number(stLive.pendingTpPlacedAtMs)
      : (
          Number.isFinite(Number(stLive.buyFilledAtMs)) && Number(stLive.buyFilledAtMs) > 0
            ? Number(stLive.buyFilledAtMs)
            : (
                Number.isFinite(Number(stLive.entryTsMs)) && Number(stLive.entryTsMs) > 0
                  ? Number(stLive.entryTsMs)
                  : nowMs()
              )
        );
  const resolvedFill = await resolveLiveOrderFillSnapshot(client as any, orderId, tokenId, startedAtMs);
  const filledShares = Math.max(
    0,
    extractOrderMatchedShares(ord),
    Number(resolvedFill?.shares || 0)
  );
  const avgPxRaw = Number(extractOrderAvgFillPx(ord) ?? NaN);
  const avgPx =
    Number.isFinite(Number(resolvedFill?.filledPx)) && Number(resolvedFill?.filledPx) > 0
      ? Number(resolvedFill?.filledPx)
      : (Number.isFinite(avgPxRaw) && avgPxRaw > 0 ? avgPxRaw : Number(stLive.pendingTpLimitPx || uiLive.exit || 0.96));
  const actualFillTsMs =
    Number.isFinite(Number(resolvedFill?.filledAtMs)) && Number(resolvedFill?.filledAtMs) > 0
      ? Number(resolvedFill?.filledAtMs)
      : (
          Number.isFinite(Number(extractOrderFillTsMs(ord))) && Number(extractOrderFillTsMs(ord)) > 0
            ? Number(extractOrderFillTsMs(ord))
            : null
        );
  const accountedFilledShares = Math.max(0, Number(stAny.__tpAccountedFilledShares || 0));
  const deltaFilledShares = Math.max(0, filledShares - accountedFilledShares);
  const statusKeepsOrderOpen =
    status === "OPEN" ||
    status === "LIVE" ||
    status === "PARTIALLY_FILLED" ||
    status === "UNMATCHED";
  const positionShares = await getLiveTokenPositionShares(client as any, tokenId);
  const livePositionShares = Number.isFinite(Number(positionShares)) ? Math.max(0, Number(positionShares)) : NaN;
  const positionIsFlat = Number.isFinite(livePositionShares) ? livePositionShares <= 1e-6 : false;

  if (deltaFilledShares > 1e-9) {
    const closedShares = Math.max(0, Math.min(Number(stLive.shares || 0), deltaFilledShares));
    if (closedShares > 1e-9) {
      const leg = applyLiveSellLegAccounting(stLive, avgPx, closedShares, "maker");
      stAny.__tpAccountedFilledShares = filledShares;
      stLive.exitTsMs = actualFillTsMs ?? nowMs();
      stLive.exitPx = avgPx;
      stLive.stopFallbackTriggered = false;
      stLive.shares = Number.isFinite(Number(leg.remainingShares)) ? Number(leg.remainingShares) : Number(stLive.shares ?? 0);
      stLive.notionalUsd =
        Number(stLive.shares ?? 0) > 0 && Number.isFinite(Number(stLive.entryPx))
          ? Number(stLive.shares) * Number(stLive.entryPx)
          : 0;
      if (positionIsFlat || Number(stLive.shares ?? 0) <= 1e-9) {
        stLive.exited = true;
        stLive.positionTokenId = null;
        stLive.tpOrderId = null;
        stLive.pendingTpLimitPx = null;
        stLive.pendingTpPlacedAtMs = null;
        stLive.pendingTpShares = null;
        stLive.pendingTpExitType = null;
        stLive.holdSec = stLive.entryTsMs && stLive.exitTsMs ? (stLive.exitTsMs - stLive.entryTsMs) / 1000 : null;
        finalizeExitLatency(stLive, Number(stLive.exitTsMs ?? nowMs()), {
          via: "tp_order_watchdog",
          exitType: pendingExitTypeRaw,
          fillPx: Number(avgPx),
          signalPx: Number(stLive.pendingTpLimitPx ?? avgPx),
          orderId,
          fillSource: resolvedFill?.source || "order_status",
        });
        emitTrade("live", `EXIT_${side}_LIVE`, {
          via: "tp_order_watchdog",
          exitType: pendingExitTypeRaw,
          orderId,
          executionOrderStatus: status,
          filledShares: Number(leg.soldShares ?? closedShares),
          remainingShares: Number(leg.remainingShares ?? 0),
          partial: false,
          actualFillPx: Number(avgPx),
          actualFillTsMs,
        });
        clearLivePositionStateAfterTerminalExit(stLive);
        console.log(
          `[HOST TP WATCH FILLED] reason=${reasonTag} side=${side} orderId=${orderId} ` +
          `filledPx=${avgPx} sold=${roundTo6(Number(leg.soldShares ?? closedShares))}`
        );
        return true;
      }
      stLive.entered = true;
      stLive.exited = false;
      if (!statusKeepsOrderOpen) {
        stLive.tpOrderId = null;
        stLive.pendingTpLimitPx = null;
        stLive.pendingTpPlacedAtMs = null;
        stLive.pendingTpShares = null;
        stLive.pendingTpExitType = null;
        stAny.__tpAccountedFilledShares = 0;
        if (isSinglePartialTp) {
          markPaperSinglePartialCompleted(stLive, side);
        }
      }
      console.warn(
        `[HOST TP WATCH PARTIAL] reason=${reasonTag} side=${side} orderId=${orderId} ` +
        `sold=${roundTo6(Number(leg.soldShares ?? closedShares))} remaining=${roundTo6(Number(stLive.shares ?? 0))}`
      );
      emitTrade("live", `EXIT_${side}_LIVE`, {
        via: "tp_order_watchdog",
        exitType: pendingExitTypeRaw,
        orderId,
        executionOrderStatus: status,
        filledShares: Number(leg.soldShares ?? closedShares),
        remainingShares: Number(leg.remainingShares ?? 0),
        partial: true,
        actualFillPx: Number(avgPx),
        actualFillTsMs,
      });
      return true;
    }
  }

  if (positionIsFlat && (status === "FILLED" || filledShares > 0)) {
    const closedShares = Math.max(0, Number(stLive.shares || 0));
    if (closedShares > 1e-9) {
      const leg = applyLiveSellLegAccounting(stLive, avgPx, closedShares, "maker");
      stLive.exited = true;
      stLive.exitTsMs = actualFillTsMs ?? nowMs();
      stLive.exitPx = avgPx;
      stLive.stopFallbackTriggered = false;
      stLive.positionTokenId = null;
      stLive.tpOrderId = null;
      stLive.pendingTpLimitPx = null;
      stLive.pendingTpPlacedAtMs = null;
      stLive.pendingTpShares = null;
      stLive.pendingTpExitType = null;
      stLive.holdSec = stLive.entryTsMs && stLive.exitTsMs ? (stLive.exitTsMs - stLive.entryTsMs) / 1000 : null;
      finalizeExitLatency(stLive, Number(stLive.exitTsMs ?? nowMs()), {
        via: "tp_order_watchdog",
        exitType: pendingExitTypeRaw,
        fillPx: Number(avgPx),
        signalPx: Number(stLive.pendingTpLimitPx ?? avgPx),
        orderId,
        fillSource: resolvedFill?.source || "order_status",
      });
      emitTrade("live", `EXIT_${side}_LIVE`, {
        via: "tp_order_watchdog",
        exitType: pendingExitTypeRaw,
        orderId,
        executionOrderStatus: status,
        filledShares: Number(leg.soldShares ?? closedShares),
        remainingShares: Number(leg.remainingShares ?? 0),
        partial: false,
        actualFillPx: Number(avgPx),
        actualFillTsMs,
      });
      clearLivePositionStateAfterTerminalExit(stLive);
      return true;
    }
  }

  if (positionIsFlat && !statusKeepsOrderOpen) {
    const exitTs = actualFillTsMs ?? nowMs();
    stLive.exited = true;
    stLive.exitTsMs = exitTs;
    stLive.exitPx = Number.isFinite(avgPx) ? avgPx : stLive.exitPx;
    stLive.pendingTpLimitPx = null;
    stLive.pendingTpPlacedAtMs = null;
    stLive.pendingTpShares = null;
    stLive.pendingTpExitType = null;
    finalizeExitLatency(stLive, Number(stLive.exitTsMs ?? nowMs()), {
      via: "tp_order_watchdog",
      exitType: pendingExitTypeRaw,
      fillPx: Number.isFinite(avgPx) ? Number(avgPx) : null,
      signalPx: Number(stLive.pendingTpLimitPx ?? avgPx),
      orderId,
      fillSource: resolvedFill?.source || "order_status",
      venueAlreadyFlat: true,
    });
    emitTrade("live", `EXIT_${side}_LIVE`, {
      via: "tp_order_watchdog",
      exitType: pendingExitTypeRaw,
      orderId,
      executionOrderStatus: status,
      venueAlreadyFlat: true,
      actualFillPx: Number.isFinite(avgPx) ? avgPx : null,
      actualFillTsMs,
    });
    clearLivePositionStateAfterTerminalExit(stLive);
    console.warn(
      `[HOST TP WATCH FLAT] reason=${reasonTag} side=${side} orderId=${orderId} status=${status || "unknown"}`
    );
    return true;
  }

  if (!statusKeepsOrderOpen) {
    stLive.tpOrderId = null;
    stLive.pendingTpLimitPx = null;
    stLive.pendingTpPlacedAtMs = null;
    stLive.pendingTpShares = null;
    stLive.pendingTpExitType = null;
    stAny.__tpAccountedFilledShares = 0;
  }
  return false;
}

async function flattenHostLiveExposureNow(reason: string): Promise<void> {
  const side = stLive.side === "UP" || stLive.side === "DOWN" ? stLive.side : null;
  if (!side) return;
  const tokenId = String(stLive.positionTokenId || tokenIdForSide(side) || "");
  if (!tokenId) return;
  const recoveredShares = await recoverLiveSharesForExit(stLive, side, `kill_switch_${reason}`);
  if (!(recoveredShares > 1e-9)) {
    clearLivePositionStateAfterTerminalExit(stLive);
    console.warn(`[LIVE KILL SWITCH] host position already flat side=${side} tokenId=${tokenId} reason=${reason}`);
    return;
  }
  await cancelOpenOrdersForToken(tokenId, `kill_switch_${reason}`, null);
  const out = await executeLiveVerifiedMarketExit(side, recoveredShares, uiLive, stLive, `kill_switch_${reason}`);
  if (Number(out.remainingShares || 0) > 1e-9) {
    stLive.entered = true;
    stLive.exited = false;
    stLive.shares = Number(out.remainingShares);
    throw new Error(
      `[LIVE KILL SWITCH] host flatten incomplete side=${side} remaining=${roundTo6(Number(out.remainingShares || 0))}`
    );
  }
  stLive.exited = true;
  stLive.exitTsMs = toFiniteOrNull(out.filledAtMs ?? out.exitEventTsMs) ?? nowMs();
  stLive.exitPx = Number(out.filledPx || stLive.entryPx || uiLive.stop);
  stLive.stopFallbackTriggered = true;
  emitTrade("live", `STOP_${side}_LIVE`, {
    via: "kill_switch",
    stopSource: "manual_disable_market_exit",
    stopMeta: {
      reason,
      filledShares: Number(out.filledShares || 0),
      remainingShares: Number(out.remainingShares || 0),
      attempts: Number(out.attempts || 0),
      orderId: String(out.orderId || "").trim() || null,
    },
    actualFillPx: Number(out.filledPx || 0),
    actualFillTsMs: toFiniteOrNull(out.filledAtMs),
  });
  clearLivePositionStateAfterTerminalExit(stLive);
}

async function flattenBotRuntimeLiveExposureNow(instance: BotInstance, rt: BotRuntime, reason: string): Promise<void> {
  if (!isRealLiveCapableBotInstance(instance)) return;
  const side = rt.side === "UP" || rt.side === "DOWN" ? rt.side : null;
  if (!side) return;
  const tokenId = runtimeTokenIdForSide(rt, side);
  if (!tokenId) return;
  const sharesHint =
    Number.isFinite(Number(rt.shares)) && Number(rt.shares) > 1e-9
      ? Number(rt.shares)
      : Number(hydrateRuntimeSharesForExitFallback(rt) || 0);
  const stAdapter = {
    side,
    shares: sharesHint,
    entryPx: rt.entryPx,
    positionTokenId: tokenId,
  } as any;
  await cancelOpenOrdersForToken(tokenId, `kill_switch_${reason}`, null);
  const recoveredShares = await recoverLiveSharesForExit(stAdapter, side, `bot_kill_switch_${reason}`);
  if (!(recoveredShares > 1e-9)) {
    updateBotRuntimeAfterVenueAlreadyFlat(instance, rt, "stop", `KILL_SWITCH_${reason}_VENUE_ALREADY_FLAT`, {
      executionMode: "real",
      fillSource: "live_exchange",
      positionTokenId: tokenId,
    });
    return;
  }
  const out = await executeLiveVerifiedMarketExit(side, recoveredShares, buildUiConfigForBotInstance(instance), stAdapter, `bot_kill_switch_${reason}`);
  const soldShares = Math.max(0, Number(out.filledShares || 0));
  const remainingShares = Math.max(0, Number(out.remainingShares || 0));
  if (remainingShares <= 1e-9 && soldShares <= 1e-9) {
    updateBotRuntimeAfterVenueAlreadyFlat(instance, rt, "stop", `KILL_SWITCH_${reason}_VENUE_ALREADY_FLAT`, {
      executionMode: "real",
      fillSource: "live_exchange",
      positionTokenId: tokenId,
    });
    return;
  }
  if (remainingShares <= 1e-9) {
    updateBotRuntimeAfterTerminalExit(instance, rt, Number(out.filledPx), soldShares, "stop", `KILL_SWITCH_${reason}`, {
      executionMode: "real",
      fillSource: "live_exchange",
      positionTokenId: tokenId,
      attempts: Number(out.attempts || 0),
      orderId: String(out.orderId || "").trim() || null,
      actualFillTsMs: toFiniteOrNull(out.filledAtMs),
      exitTsMs: toFiniteOrNull(out.exitEventTsMs ?? out.filledAtMs),
    });
    return;
  }
  updateBotRuntimeAfterPartialExit(instance, rt, Number(out.filledPx), soldShares, "stop", `KILL_SWITCH_${reason}`, {
    executionMode: "real",
    fillSource: "live_exchange",
    positionTokenId: tokenId,
    attempts: Number(out.attempts || 0),
    remainingSharesVerified: remainingShares,
    orderId: String(out.orderId || "").trim() || null,
    actualFillTsMs: toFiniteOrNull(out.filledAtMs),
    exitTsMs: toFiniteOrNull(out.exitEventTsMs ?? out.filledAtMs),
  });
  throw new Error(
    `[LIVE KILL SWITCH] bot flatten incomplete instance=${instance.instanceId} side=${side} remaining=${roundTo6(remainingShares)}`
  );
}

async function flattenAllKnownLiveExposureNow(reason: string): Promise<void> {
  if (!(stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN"))) {
    for (const side of ["UP", "DOWN"] as OutcomeSide[]) {
      const snap = await getLiveVenueSharesSnapshot(side, { positionTokenId: tokenIdForSide(side) });
      if (Number.isFinite(Number(snap.shares)) && Number(snap.shares) > 1e-9) {
        stLive.entered = true;
        stLive.exited = false;
        stLive.side = side;
        stLive.shares = Number(snap.shares);
        stLive.positionTokenId = snap.tokenId || tokenIdForSide(side);
        break;
      }
    }
  }
  if (stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) {
    await flattenHostLiveExposureNow(reason);
  }
  for (const instance of activeBotInstances()) {
    if (!isRealLiveCapableBotInstance(instance)) continue;
    const rt = botRuntimes.get(instance.instanceId);
    if (!rt || !rt.entered || rt.side == null) continue;
    await flattenBotRuntimeLiveExposureNow(instance, rt, reason);
    botRuntimes.set(rt.instanceId, rt);
  }
}

async function enforceLiveDisableKillSwitch(reason: string): Promise<void> {
  if (!process.env.POLY_PRIVATE_KEY) return;
  const tokenIds = Array.from(new Set(
    [
      String(current.upToken || ""),
      String(current.downToken || ""),
      String(stLive.positionTokenId || ""),
      ...activeBotInstances()
        .filter((b) => isRealLiveCapableBotInstance(b))
        .flatMap((b) => {
          const rt = botRuntimes.get(b.instanceId);
          if (!rt) return [];
          return [
            String(rt.upToken || ""),
            String(rt.downToken || ""),
            String(runtimeTokenIdForSide(rt, rt.side) || ""),
          ];
        }),
    ]
      .map((v) => String(v || "").trim())
      .filter(Boolean)
  ));
  const killSwitchHardOff = !uiLive.enabled;
  if (tokenIds.length) {
    const canceled = await cancelOpenOrdersForTokens(tokenIds, `live_disable_${reason}`, null);
    if (canceled > 0) {
      broadcast({
        type: "status",
        t: nowMs(),
        status: `LIVE DISABLE canceled ${canceled} open order(s) reason=${reason}`,
      });
    }
  }
  if (killSwitchHardOff) {
    stLive.enterInFlight = false;
    stLive.exitInFlight = false;
    stLive.tpOrderInFlight = false;
    stLive.tpOrderId = null;
    for (const instance of activeBotInstances()) {
      if (!isRealLiveCapableBotInstance(instance)) continue;
      const rt = botRuntimes.get(instance.instanceId);
      if (!rt) continue;
      const rtAny = rt as any;
      rtAny.__liveExitInProgress = false;
      rtAny.tpOrderId = null;
      rt.lastAction = "live_kill_switch_armed";
      botRuntimes.set(instance.instanceId, rt);
    }
    broadcast({
      type: "status",
      t: nowMs(),
      status: `LIVE KILL SWITCH armed reason=${reason}; all new live order submissions blocked`,
    });
    return;
  }
  await flattenAllKnownLiveExposureNow(reason);
}

async function activateManualLiveKillSwitch(reason: string): Promise<{
  ok: true;
  reason: string;
  liveEnabled: boolean;
  pendingLiveEnabled: boolean;
  hardBlocked: boolean;
  flattenAttempted: boolean;
  flattenError: string | null;
}> {
  const resolvedReason = String(reason || "manual_kill_switch").trim() || "manual_kill_switch";
  const flattenAttempted =
    !!uiLive.enabled ||
    (stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN")) ||
    activeBotInstances().some((instance) => {
      if (!isRealLiveCapableBotInstance(instance)) return false;
      const rt = botRuntimes.get(instance.instanceId);
      return !!(rt && rt.entered && !rt.exited && (rt.side === "UP" || rt.side === "DOWN"));
    });
  let flattenError: string | null = null;

  if (flattenAttempted) {
    try {
      await flattenAllKnownLiveExposureNow(resolvedReason);
    } catch (e: any) {
      flattenError = String(e?.message ?? e);
      console.error(`[LIVE MANUAL KILL SWITCH FLATTEN ERROR] reason=${resolvedReason} err=${flattenError}`);
    }
  }

  uiLive.enabled = false;
  if (pendingUiLive) pendingUiLive.enabled = false;
  liveManualEnabledOverride = false;
  liveExecutionHardBlockedReason = `manual_kill_switch:${resolvedReason}`;
  liveExecutionHardBlockedAtMs = nowMs();
  liveExecutionHardBlockedSource = "manual_kill_switch";
  stLive.enterInFlight = false;
  stLive.exitInFlight = false;
  stLive.tpOrderInFlight = false;
  stLive.tpOrderId = null;

  for (const instance of activeBotInstances()) {
    if (!isRealLiveCapableBotInstance(instance)) continue;
    const rt = botRuntimes.get(instance.instanceId);
    if (rt) {
      const rtAny = rt as any;
      rtAny.__liveExitInProgress = false;
      rtAny.tpOrderId = null;
      rt.lastError = liveKillSwitchErrorMessage(resolvedReason);
      rt.lastAction = "manual_live_kill_switch";
      botRuntimes.set(instance.instanceId, rt);
    }
  }

  try {
    await enforceLiveDisableKillSwitch(`${resolvedReason}_armed`);
  } catch (e: any) {
    if (!flattenError) flattenError = String(e?.message ?? e);
    console.error(`[LIVE MANUAL KILL SWITCH ARM ERROR] reason=${resolvedReason} err=${String(e?.message ?? e)}`);
  }

  broadcast({
    type: "status",
    t: nowMs(),
    status:
      `LIVE MANUAL KILL SWITCH fired reason=${resolvedReason}; ` +
      `future live submissions blocked${flattenError ? ` flattenErr=${flattenError}` : ""}`,
  });
  persistMultiMarketState();
  broadcastState();
  writeRuntimeStateSnapshot();

  return {
    ok: true,
    reason: resolvedReason,
    liveEnabled: !!uiLive.enabled,
    pendingLiveEnabled: !!pendingUiLive?.enabled,
    hardBlocked: true,
    flattenAttempted,
    flattenError,
  };
}

async function flushLiveDisabledExposureWatchdog(): Promise<void> {
  if (uiLive.enabled) return;
  const hostActive = !!stLive.entered && !stLive.exited && (stLive.side === "UP" || stLive.side === "DOWN");
  const hostOrdersActive =
    !!stLive.enterInFlight ||
    !!stLive.exitInFlight ||
    !!stLive.tpOrderInFlight ||
    !!String(stLive.tpOrderId || "").trim();
  const botActive = activeBotInstances().some((b) => {
    if (!isRealLiveCapableBotInstance(b)) return false;
    const rt = botRuntimes.get(b.instanceId);
    if (!rt) return false;
    const rtAny = rt as any;
    return (
      (!!rt.entered && (rt.side === "UP" || rt.side === "DOWN")) ||
      !!rtAny.__liveExitInProgress ||
      !!String(rtAny.tpOrderId || "").trim()
    );
  });
  if (!hostActive && !hostOrdersActive && !botActive) return;
  try {
    await enforceLiveDisableKillSwitch("disabled_watchdog");
  } catch (e: any) {
    console.warn(`[LIVE DISABLE WATCHDOG] err=${String(e?.message ?? e)}`);
  }
}

async function maybeEnsureLiveTakeProfitOrder() {
  if (!uiLive.enabled) return;
  if (isInflectionPositiveSlopeFamilyStrategy((strategyLive as any)?.STRATEGY_ID || null)) return;
  if (!stLive.entered || stLive.exited || !stLive.side) return;
  if (stLive.exitInFlight || !!(stLive as any).__suppressTpRearmUntilFlat) return;
  if (!Number.isFinite(stLive.shares) || (stLive.shares as number) <= 0) return;
  if (await maybeResolveHostLiveTpFill("tp_order_watchdog")) return;
  if (String(stLive.tpOrderId || "").trim()) return;
  if (stLive.tpOrderInFlight) return;

  const now = Date.now();
  if (stLive.lastTpArmAttemptMs && now - stLive.lastTpArmAttemptMs < 3000) return;
  stLive.lastTpArmAttemptMs = now;
  stLive.tpOrderInFlight = true;

  try {
    const client = await getClobClient();
    const tokenId = stLive.positionTokenId || tokenIdForSide(stLive.side);
    const open = await (client as any).getOpenOrders?.({ asset_id: tokenId });
    const openOrders = Array.isArray(open) ? open : [];
    const existingSell = openOrders.find((o: any) => String(o?.side || "").toUpperCase() === "SELL");
    if (existingSell) {
      const existingId = String(existingSell?.id ?? existingSell?.orderID ?? existingSell?.orderId ?? "");
      const existingSize = floorTo6(Number(existingSell?.original_size ?? existingSell?.size ?? existingSell?.initialSize ?? 0));
      const requestedShares = floorTo6(Number(stLive.shares || 0));
      if (existingId && existingSize >= requestedShares - 1e-6) {
        stLive.tpOrderId = existingId;
        return;
      }
      if (existingId) {
        try {
          await cancelOrderRobust(client as any, existingId);
          console.warn(
            `[TP ARM REPAIR] canceled undersized sell orderId=${existingId} tokenId=${tokenId} ` +
            `existingShares=${roundTo6(existingSize)} requestedShares=${roundTo6(requestedShares)}`
          );
        } catch (e: any) {
          console.warn(`[TP ARM REPAIR] failed to cancel undersized sell orderId=${existingId}: ${String(e?.message ?? e)}`);
        }
      }
    }

    const oid = (await placeImmediateTpSellAfterBuy(stLive.side, Number(stLive.shares), uiLive, tokenId, {
      source: "tp_rearm",
      entryFillPx: Number(stLive.entryPx),
      buyFilledAtMs: Number(stLive.buyFilledAtMs ?? NaN),
    })).orderId;
    stLive.tpOrderId = oid;
  } catch (e: any) {
    console.error(`[TP ARM ERROR] ${String(e?.message ?? e)}`);
    broadcast({ type: "status", t: nowMs(), status: `tp arm failed: ${String(e?.message ?? e)}` });
  } finally {
    stLive.tpOrderInFlight = false;
  }
}

async function placeLiveMarketSell(
  side: OutcomeSide,
  shares: number,
  _ui: UiConfig,
  st?: TradeState,
  opts?: {
    onSubmitted?: (meta: { submittedAtMs: number; side: OutcomeSide; shares: number; tokenId: string; orderId: string | null }) => void | Promise<void>;
    preSellSnapshot?: { positionShares: number | null; conditionalBalanceShares: number | null } | null;
  }
): Promise<{ filledPx: number; filledShares: number; orderId: string | null; filledAtMs: number | null; exitEventTsMs: number | null }> {
  assertLiveOrderSubmissionAllowed(`sell_market_${side}`);
  if (side == null) {
    console.error("[CRITICAL] side is undefined in placeLiveMarketSell");
    console.trace();
    throw new Error("side is undefined - cannot place market sell order");
  }
  if (!["UP", "DOWN"].includes(side)) throw new Error(`Invalid side value: ${side}`);

  console.log(`[SELL MKT] Attempt: slug=${current.slug} side=${side} shares=${shares}`);

  const client = await getClobClient();
  const tokenId = st?.positionTokenId || tokenIdForSide(side);
  if (!Number.isFinite(shares) || shares <= 0) throw new Error(`invalid shares: ${shares}`);

  const marketFn = (client as any).createAndPostMarketOrder;
  if (typeof marketFn !== "function") {
    throw new Error("[SELL MKT] market order API unavailable");
  }
  const { tickSize, negRisk } = await getTickNegRisk(tokenId);
  let remaining = floorTo6(Number(shares));
  let filledSharesTotal = 0;
  let filledNotional = 0;
  let lastErr: any = null;
  let submittedNotified = false;
  let lastOrderId: string | null = null;
  let lastFilledAtMs: number | null = null;
  let lastExitEventTsMs: number | null = null;
  const sellStartedAtMs = nowMs();

  for (let attempt = 1; attempt <= LIVE_MARKET_SELL_RETRY_ATTEMPTS && remaining > 1e-9; attempt++) {
    const prefetchedSnapshot = attempt === 1 ? opts?.preSellSnapshot : null;
    const prePositionSharesRaw = prefetchedSnapshot
      ? Number(prefetchedSnapshot.positionShares)
      : await getLiveTokenPositionShares(client as any, tokenId);
    const preConditional = prefetchedSnapshot
      ? { balanceShares: prefetchedSnapshot.conditionalBalanceShares }
      : await getConditionalBalanceAllowanceShares(client as any, tokenId);
    const prePositionShares = Number.isFinite(Number(prePositionSharesRaw)) ? Math.max(0, Number(prePositionSharesRaw)) : 0;
    const preConditionalBalanceShares = Number.isFinite(Number(preConditional.balanceShares))
      ? Math.max(0, Number(preConditional.balanceShares))
      : 0;
    const preCollateralBalanceUsd = Number.isFinite(Number(liveAccount.balanceUsd)) ? Number(liveAccount.balanceUsd) : null;
    try {
      const order = await marketFn.call(
        client,
        { tokenID: tokenId, side: ClobSide.SELL, amount: remaining, feeRateBps: 1000 },
        { tickSize, negRisk }
      );
      const orderId = extractOrderIdLike(order);
      lastOrderId = orderId || lastOrderId;
      maybeThrowLiveExecutionHardBlock(order, `sell_market_response_${side}`);
      if (!submittedNotified) {
        submittedNotified = true;
        try {
          await opts?.onSubmitted?.({
            submittedAtMs: nowMs(),
            side,
            shares: remaining,
            tokenId,
            orderId,
          });
        } catch (cbErr: any) {
          console.warn(`[SELL MKT SUBMIT CALLBACK WARN] side=${side} tokenId=${tokenId} err=${String(cbErr?.message ?? cbErr)}`);
        }
      }
      const filledPxRaw = Number(extractOrderAvgFillPx(order) ?? NaN);
      const filledSharesRaw = Number(extractOrderMatchedShares(order));
      let filledShares = Number.isFinite(filledSharesRaw) && filledSharesRaw > 0
        ? Math.min(remaining, filledSharesRaw)
        : 0;
      let filledPx = Number.isFinite(filledPxRaw) && filledPxRaw > 0 ? filledPxRaw : 0.01;
      const reconciled = await reconcileLiveSellFillFromVenue(client as any, tokenId, remaining, filledShares, filledPx, {
        reason: "market_sell",
        prePositionShares,
        preConditionalBalanceShares,
        preCollateralBalanceUsd,
        startedAtMs: sellStartedAtMs,
        orderId,
      });
      filledShares = reconciled.filledShares;
      filledPx = reconciled.filledPx;
      if (Number.isFinite(Number(reconciled.filledAtMs)) && Number(reconciled.filledAtMs) > 0) {
        lastFilledAtMs = Number(reconciled.filledAtMs);
        lastExitEventTsMs = Number(reconciled.filledAtMs);
      }
      const orderFilledAtMs = extractOrderFillTsMs(order);
      const orderEventTsMs = extractOrderEntryTsMs(order) ?? orderFilledAtMs;
      if (Number.isFinite(Number(orderFilledAtMs)) && Number(orderFilledAtMs) > 0) lastFilledAtMs = Number(orderFilledAtMs);
      if (Number.isFinite(Number(orderEventTsMs)) && Number(orderEventTsMs) > 0) lastExitEventTsMs = Number(orderEventTsMs);
      if (!(filledShares > 0)) {
        throw new Error("[SELL MKT] no venue-confirmed fill delta");
      }
      filledSharesTotal += filledShares;
      filledNotional += filledPx * filledShares;
      remaining = floorTo6(Math.max(0, remaining - filledShares));
      console.log(
        `[SELL MKT] attempt=${attempt}/${LIVE_MARKET_SELL_RETRY_ATTEMPTS} ` +
        `filledPx=${filledPx} filledShares=${roundTo6(filledShares)} remaining=${roundTo6(remaining)}`
      );
      if (remaining <= 1e-9) {
        const avgPx = filledSharesTotal > 0 ? filledNotional / filledSharesTotal : filledPx;
        return {
          filledPx: avgPx,
          filledShares: filledSharesTotal,
          orderId: lastOrderId,
          filledAtMs: lastFilledAtMs,
          exitEventTsMs: lastExitEventTsMs,
        };
      }
    } catch (e: any) {
      maybeThrowLiveExecutionHardBlock(e, `sell_market_post_${side}`);
      lastErr = e;
      try {
        const reconciled = await reconcileLiveSellFillFromVenue(client as any, tokenId, remaining, 0, 0.01, {
          reason: "market_sell_error_path",
          prePositionShares,
          preConditionalBalanceShares,
          preCollateralBalanceUsd,
          startedAtMs: sellStartedAtMs,
          orderId: lastOrderId,
        });
        if (reconciled.filledShares > 0) {
          filledSharesTotal += reconciled.filledShares;
          filledNotional += reconciled.filledPx * reconciled.filledShares;
          if (Number.isFinite(Number(reconciled.filledAtMs)) && Number(reconciled.filledAtMs) > 0) {
            lastFilledAtMs = Number(reconciled.filledAtMs);
            lastExitEventTsMs = Number(reconciled.filledAtMs);
          }
          remaining = floorTo6(Math.max(0, remaining - reconciled.filledShares));
          console.warn(
            `[SELL MKT RECONCILED] side=${side} tokenId=${tokenId} err=${String(e?.message ?? e)} ` +
            `filledPx=${reconciled.filledPx} filledShares=${roundTo6(reconciled.filledShares)} remaining=${roundTo6(remaining)}`
          );
          if (remaining <= 1e-9) {
            const avgPx = filledSharesTotal > 0 ? filledNotional / filledSharesTotal : reconciled.filledPx;
            return {
              filledPx: avgPx,
              filledShares: filledSharesTotal,
              orderId: lastOrderId,
              filledAtMs: lastFilledAtMs,
              exitEventTsMs: lastExitEventTsMs,
            };
          }
        }
      } catch {}
      const msg = String(e?.message ?? e);
      const canRetry = shouldRearmLiveEntryAfterError(msg) && attempt < LIVE_MARKET_SELL_RETRY_ATTEMPTS;
      console.warn(
        `[SELL MKT RETRY] attempt=${attempt}/${LIVE_MARKET_SELL_RETRY_ATTEMPTS} side=${side} tokenId=${tokenId} reason=${msg}`
      );
      if (!canRetry) break;
      await sleep(LIVE_MARKET_SELL_RETRY_SLEEP_MS);
    }
  }

  if (filledSharesTotal > 0) {
    const avgPx = filledSharesTotal > 0 ? filledNotional / filledSharesTotal : 0.01;
    console.warn(
      `[SELL MKT PARTIAL] side=${side} tokenId=${tokenId} filledShares=${roundTo6(filledSharesTotal)} remaining=${roundTo6(remaining)}`
    );
    return {
      filledPx: avgPx,
      filledShares: filledSharesTotal,
      orderId: lastOrderId,
      filledAtMs: lastFilledAtMs,
      exitEventTsMs: lastExitEventTsMs,
    };
  }
  throw lastErr ?? new Error("[SELL MKT] market sell failed without response");
}

async function startOptimisticLiveStopRecovery(
  side: OutcomeSide,
  targetSellPx: number,
  ui: UiConfig,
  st: TradeState,
  tag: string,
  meta?: {
    priorEntryMode?: string | null;
    priorSide?: OutcomeSide | null;
    exitType?: string | null;
    resolvedStopReason?: string | null;
    stopMeta?: Record<string, any> | null;
  }
): Promise<{ submittedAtMs: number; recoveryId: string }> {
  const recoveryId = `optimistic-stop-${String(current.slug || "na")}-${side}-${nowMs()}`;
  const tokenId = String(st.positionTokenId || tokenIdForSide(side) || "").trim() || null;
  const snapshotEntryPx = Number.isFinite(Number(st.entryPx)) ? Number(st.entryPx) : null;
  const snapshotShares = Number.isFinite(Number(st.shares)) ? Math.max(0, Number(st.shares)) : 0;
  const snapshot = {
    positionTokenId: tokenId,
    entryPx: snapshotEntryPx,
    shares: snapshotShares,
  } as TradeState;
  let submitted = false;
  let submitResolve: ((value: { submittedAtMs: number; recoveryId: string }) => void) | null = null;
  let submitReject: ((reason?: any) => void) | null = null;
  const submittedPromise = new Promise<{ submittedAtMs: number; recoveryId: string }>((resolve, reject) => {
    submitResolve = resolve;
    submitReject = reject;
  });

  setOptimisticLiveStopRecovery({
    id: recoveryId,
    side,
    tokenId,
    startedAtMs: nowMs(),
    untilMs: nowMs() + LIVE_OPTIMISTIC_STOP_REARM_WINDOW_MS,
    reasonTag: tag,
  });

  void (async () => {
    try {
      broadcast({
        type: "status",
        t: nowMs(),
        status: `STOP RECOVERY START optimistic side=${side} shares=${roundTo6(snapshotShares)}`,
      });
      const out = await executeLiveStopWithWalk(side, targetSellPx, ui, snapshot, `${tag}_optimistic`, {
        onImmediateMarketSubmitted: ({ submittedAtMs }) => {
          if (!submitted) {
            submitted = true;
            emitTrade("live", `STOP_ORDER_${side}_LIVE`, {
              eventTsMs: submittedAtMs,
              orderPlacedAtMs: submittedAtMs,
              exitType: String(meta?.exitType || "STOP"),
              exitPx: Number.isFinite(Number(targetSellPx)) ? Number(targetSellPx) : null,
              signalPx: Number.isFinite(Number(targetSellPx)) ? Number(targetSellPx) : null,
              intendedPx: Number.isFinite(Number(targetSellPx)) ? Number(targetSellPx) : null,
              sharesRequested: snapshotShares,
              stopReason: String(meta?.resolvedStopReason || "STOP"),
              stopSource: "optimistic_market_submit",
              stopMeta: {
                ...(meta?.stopMeta || {}),
                optimisticRecovery: true,
                recoveryId,
              },
            }, snapshot, ui);
            emitTrade("live", `EXIT_ORDER_${side}_LIVE`, {
              eventTsMs: submittedAtMs,
              exitType: String(meta?.exitType || "STOP"),
              exitPx: Number.isFinite(Number(targetSellPx)) ? Number(targetSellPx) : null,
              signalPx: Number.isFinite(Number(targetSellPx)) ? Number(targetSellPx) : null,
              intendedPx: Number.isFinite(Number(targetSellPx)) ? Number(targetSellPx) : null,
              sharesRequested: snapshotShares,
              stopReason: String(meta?.resolvedStopReason || "STOP"),
              stopSource: "optimistic_market_submit",
              stopMeta: {
                ...(meta?.stopMeta || {}),
                optimisticRecovery: true,
                recoveryId,
              },
            }, snapshot, ui);
            setOptimisticLiveStopRecovery({
              id: recoveryId,
              side,
              tokenId,
              startedAtMs: submittedAtMs,
              untilMs: submittedAtMs + LIVE_OPTIMISTIC_STOP_REARM_WINDOW_MS,
              reasonTag: tag,
            });
            submitResolve?.({ submittedAtMs, recoveryId });
          }
        },
      });
      clearOptimisticLiveStopRecovery(recoveryId);
      if (Number(out.remainingShares || 0) > 1e-9) {
        throw new Error(
          `[OPTIMISTIC STOP RECOVERY] incomplete side=${side} remaining=${roundTo6(Number(out.remainingShares || 0))}`
        );
      }
      emitTrade("live", `STOP_${side}_LIVE`, {
        actualFillPx: Number(out.filledPx),
        fillPx: Number(out.filledPx),
        eventTsMs: nowMs(),
        actualFillTsMs: nowMs(),
        exitType: String(meta?.exitType || "STOP"),
        stopReason: String(meta?.resolvedStopReason || "STOP"),
        stopSource: out.usedMarketFallback ? "market_fallback" : "stop_walk",
        stopMeta: {
          ...(meta?.stopMeta || {}),
          stopFilledShares: out.filledShares,
          stopWalkMarketFallback: out.usedMarketFallback,
          stopRemainingShares: out.remainingShares,
          limitAttempts: out.limitAttempts,
          optimisticRecovery: true,
          recoveryId,
        },
      }, snapshot, ui);
    } catch (e: any) {
      clearOptimisticLiveStopRecovery(recoveryId);
      const msg = String(e?.message ?? e);
      console.error(`[OPTIMISTIC STOP RECOVERY ERROR] recoveryId=${recoveryId} side=${side} err=${msg}`);
      broadcast({ type: "status", t: nowMs(), status: `optimistic stop recovery failed: ${msg}` });
      uiLive.enabled = false;
      liveManualEnabledOverride = false;
      broadcast({ type: "status", t: nowMs(), status: `LIVE DISABLED optimistic_stop_recovery_failed reason=${msg}` });
      if (!submitted && submitReject) submitReject(e);
      return;
    }
  })();

  try {
    return await submittedPromise;
  } catch (e) {
    clearOptimisticLiveStopRecovery(recoveryId);
    throw e;
  }
}

async function placeLiveLimitSell(
  side: OutcomeSide,
  price: number,
  shares: number,
  _ui: UiConfig,
  st: TradeState,
  opts: { retryEveryMs: number; perOrderTtlMs: number; untilTsMs: number; tag: string; maxOrderAttempts?: number }
): Promise<{ filledPx: number; filledShares: number }> {
  assertLiveOrderSubmissionAllowed(`sell_limit_${side}_${String(opts?.tag || "").toLowerCase() || "na"}`);
  if (side == null) throw new Error("side is undefined - cannot place sell order");
  if (!["UP", "DOWN"].includes(side)) throw new Error(`Invalid side value: ${side}`);
  if (!Number.isFinite(price) || price <= 0 || price >= 1) throw new Error(`invalid sell price: ${price} (must be >0 and <1)`);
  if (!Number.isFinite(shares) || shares <= 0) throw new Error(`invalid shares: ${shares}`);

  const client = await getClobClient();
  const tokenId = st.positionTokenId || tokenIdForSide(side);
  const { tickSize, negRisk } = await getTickNegRisk(tokenId);

  const until = Number(opts.untilTsMs);
  const retryEvery = Math.max(100, Number(opts.retryEveryMs) || 1000);
  const perTtl = Math.max(250, Number(opts.perOrderTtlMs) || 1000);
  const maxOrderAttempts =
    Number.isFinite(Number(opts.maxOrderAttempts)) && Number(opts.maxOrderAttempts) > 0
      ? Math.floor(Number(opts.maxOrderAttempts))
      : Number.POSITIVE_INFINITY;

  let remaining = shares;
  let filledSharesTotal = 0;
  let filledNotional = 0; // sum(px * filledShares)
  let consecutiveAllowanceOrBalanceErrors = 0;
  let orderAttempts = 0;

  console.log(
    `[SELL LIMIT] START tag=${opts.tag} slug=${current.slug} side=${side} ` +
    `price=${price} shares=${roundTo6(shares)} remaining=${roundTo6(remaining)} ` +
    `retryEveryMs=${retryEvery} perOrderTtlMs=${perTtl} until=${new Date(until).toISOString()}`
  );

  while (Date.now() < until && remaining > 1e-9 && orderAttempts < maxOrderAttempts) {
    const sellability = await syncSellableShares(client as any, tokenId, remaining, `limit_sell_${opts.tag}`);
    const capped = floorTo6(Math.min(remaining, Number(sellability.sellableShares || 0)));
    if (!(capped > 0)) {
      if (opts.tag === "SL") {
        throw new Error("[SELL LIMIT] stop blocked by unsellable position/allowance snapshot");
      }
      await sleep(retryEvery);
      continue;
    }
    if (capped < remaining - 1e-9) {
      console.log(`[SELL LIMIT] clamp remaining ${roundTo6(remaining)} -> ${roundTo6(capped)} from sellability`);
      remaining = capped;
    }

    console.log(
      `[SELL LIMIT] PLACE tag=${opts.tag} slug=${current.slug} side=${side} px=${price} remaining=${roundTo6(remaining)}`
    );
    orderAttempts += 1;

    let order: any;
    try {
      order = await client.createAndPostOrder(
        {
          tokenID: tokenId,
          price: roundTo6(price),
          side: ClobSide.SELL,
          size: floorTo6(remaining),
          feeRateBps: 1000,
        },
        { tickSize: tickSize as any, negRisk },
        OrderType.GTC
      );
      maybeThrowLiveExecutionHardBlock(order, `sell_limit_response_${side}`);
      consecutiveAllowanceOrBalanceErrors = 0;
    } catch (e: any) {
      maybeThrowLiveExecutionHardBlock(e, `sell_limit_post_${side}`);
      console.error(`[SELL LIMIT ERROR] create/post failed tag=${opts.tag}:`, e?.message ?? e);
      const msg = String(e?.message ?? e).toLowerCase();
      if (msg.includes("not enough balance") || msg.includes("allowance")) {
        consecutiveAllowanceOrBalanceErrors += 1;
        const avail2 = await getLiveTokenPositionShares(client as any, tokenId);
        if (Number.isFinite(avail2 as number) && Number(avail2) > 0) {
          const capped2 = floorTo6(Math.min(remaining, Number(avail2)));
          if (capped2 > 0 && capped2 < remaining) {
            console.log(`[SELL LIMIT] rebalance remaining ${roundTo6(remaining)} -> ${roundTo6(capped2)} after allowance error`);
            remaining = capped2;
          }
        } else if (opts.tag === "SL") {
          // Stop path must fail fast into market fallback instead of looping until session end.
          if (consecutiveAllowanceOrBalanceErrors >= 3) {
            throw new Error("[SELL LIMIT] stop blocked by balance/allowance and no sellable token balance");
          }
        }
      }
      await sleep(retryEvery);
      continue;
    }

    const orderId = (order as any)?.orderID || (order as any)?.orderId || (order as any)?.id;
    if (!orderId) {
      maybeThrowLiveExecutionHardBlock(order, `sell_limit_missing_order_id_${side}`);
      console.error(`[SELL LIMIT ERROR] no orderId returned tag=${opts.tag}`);
      await sleep(retryEvery);
      continue;
    }
    const orderKind = opts.tag === "SL" ? "STOP" : "SELL";
    broadcast({
      type: "status",
      t: nowMs(),
      status: `${orderKind} ORDER PLACED orderId=${orderId} px=${price} shares=${roundTo6(remaining)}`,
    });

    console.log(`[SELL LIMIT] ORDER tag=${opts.tag} orderId=${orderId} perOrderTtlMs=${perTtl}`);

    const orderDeadline = Date.now() + perTtl;

    // IMPORTANT: track delta fills for THIS order
    let lastSeenFilledThisOrder = 0;

    while (Date.now() < orderDeadline) {
      let ord: any;
      try {
        ord = await (client as any).getOrder(orderId);
      } catch (e: any) {
        console.warn(`[SELL LIMIT] getOrder failed tag=${opts.tag} orderId=${orderId}: ${e?.message ?? e}`);
        await sleep(250);
        continue;
      }

      const status = String(ord?.status || "").toUpperCase();
      const filledThisOrder = Number(extractOrderMatchedShares(ord));
      const avgPx = Number(extractOrderAvgFillPx(ord) ?? NaN);

      // delta fill since last poll for this order
      if (Number.isFinite(filledThisOrder) && filledThisOrder > lastSeenFilledThisOrder + 1e-9) {
        const deltaRaw = filledThisOrder - lastSeenFilledThisOrder;
        const delta = Math.min(deltaRaw, remaining);
        const px = Number.isFinite(avgPx) ? avgPx : price;

        lastSeenFilledThisOrder = filledThisOrder;

        filledSharesTotal += delta;
        filledNotional += px * delta;
        remaining = Math.max(0, remaining - delta);

        console.log(
          `[SELL LIMIT] FILL tag=${opts.tag} orderId=${orderId} status=${status} ` +
          `delta=${roundTo6(delta)} filledTotal=${roundTo6(filledSharesTotal)} remaining=${roundTo6(remaining)} px=${px}`
        );

        if (remaining <= 1e-9) {
          const avgFilledPx = filledSharesTotal > 0 ? filledNotional / filledSharesTotal : price;
          const orderKindFilled = opts.tag === "SL" ? "STOP" : "SELL";
          broadcast({
            type: "status",
            t: nowMs(),
            status: `${orderKindFilled} ORDER FILLED orderId=${orderId} px=${avgFilledPx} shares=${roundTo6(filledSharesTotal)}`,
          });
          return { filledPx: avgFilledPx, filledShares: filledSharesTotal };
        }
      }

      if (status === "FILLED") {
        // If status says FILLED but we didn't catch delta (timing), treat as fully filled for this order.
        const px = Number.isFinite(avgPx) ? avgPx : price;

        // If nothing recorded, assume this order filled the remaining
        if (filledSharesTotal <= 0) {
          filledSharesTotal = shares;
          filledNotional = px * shares;
          remaining = 0;
        }

        const avgFilledPx = filledSharesTotal > 0 ? filledNotional / filledSharesTotal : px;
        console.log(`[SELL LIMIT] FILLED tag=${opts.tag} orderId=${orderId} avgPx=${avgFilledPx} filledShares=${roundTo6(filledSharesTotal)}`);
        const orderKindFilled = opts.tag === "SL" ? "STOP" : "SELL";
        broadcast({
          type: "status",
          t: nowMs(),
          status: `${orderKindFilled} ORDER FILLED orderId=${orderId} px=${avgFilledPx} shares=${roundTo6(filledSharesTotal)}`,
        });
        return { filledPx: avgFilledPx, filledShares: filledSharesTotal };
      }

      await sleep(250);
    }

    console.log(`[SELL LIMIT] TTL expired -> cancel tag=${opts.tag} orderId=${orderId}`);
    try {
      await cancelOrderRobust(client as any, String(orderId));
    } catch (e: any) {
      console.warn(`[SELL LIMIT] cancel failed tag=${opts.tag} orderId=${orderId}: ${e?.message ?? e}`);
    }

    await sleep(retryEvery);
  }

  const avgFilledPx = filledSharesTotal > 0 ? filledNotional / filledSharesTotal : price;

  if (filledSharesTotal > 0) {
    console.log(
      `[SELL LIMIT] END (partial fill) tag=${opts.tag} filledShares=${roundTo6(filledSharesTotal)} remaining=${roundTo6(remaining)} avgPx=${avgFilledPx}`
    );
    const err: any = new Error(
      `[SELL LIMIT] Partially filled by untilTsMs tag=${opts.tag} filled=${roundTo6(filledSharesTotal)} remaining=${roundTo6(remaining)}`
    );
    err.partialFilledShares = filledSharesTotal;
    err.remainingShares = remaining;
    err.avgFilledPx = avgFilledPx;
    throw err;
  }

  console.log(`[SELL LIMIT] END (no fill) tag=${opts.tag} sold=0 remaining=${roundTo6(remaining)}`);
  throw new Error(`[SELL LIMIT] Not filled by untilTsMs tag=${opts.tag} remaining=${roundTo6(remaining)}`);
}

async function computeStopWalkLimitPx(side: OutcomeSide, baseStopPx: number, tokenId: string): Promise<number> {
  const sideLabel = side === "UP" ? "UP" : "DOWN";
  let askPx: number | null = null;
  try {
    const ba = await getBestBidAskSafe(tokenId, sideLabel);
    const ask = Number(ba?.ask);
    if (Number.isFinite(ask) && ask > 0) askPx = ask;
  } catch {}
  // Fee-aware stop: start from configured stop limit and walk up to current ask.
  const candidate = askPx != null ? Math.max(Number(baseStopPx), askPx) : Number(baseStopPx);
  return clamp01(candidate);
}

async function executeLiveStopWithWalk(
  side: OutcomeSide,
  baseStopPx: number,
  ui: UiConfig,
  st: TradeState,
  tag: string,
  opts?: { onImmediateMarketSubmitted?: (meta: { submittedAtMs: number; side: OutcomeSide; shares: number; tokenId: string; orderId: string | null }) => void | Promise<void> }
): Promise<{ filledPx: number; filledShares: number; remainingShares: number; usedMarketFallback: boolean; limitAttempts: number; orderId: string | null; filledAtMs: number | null; exitEventTsMs: number | null }> {
  const initialStopSnapshot = await getLiveVenueSharesSnapshot(side, st);
  let remaining = await recoverLiveSharesForExit(st, side, `${tag}-preflight`, initialStopSnapshot);
  if (!(remaining > 0)) throw new Error(`[STOP WALK] invalid remaining shares: ${remaining}`);

  const tokenId = String(st.positionTokenId || tokenIdForSide(side) || "");

  let filledSharesTotal = 0;
  let filledNotional = 0;
  let limitAttempts = 0;
  let usedMarketFallback = false;
  let lastOrderId: string | null = null;
  let lastFilledAtMs: number | null = null;
  let lastExitEventTsMs: number | null = null;
  let walkPx = clamp01(baseStopPx);
  if (tokenId) {
    try {
      walkPx = await computeStopWalkLimitPx(side, baseStopPx, tokenId);
    } catch {}
  }

  // Emergency stop path: submit the verified market exit immediately and let the
  // venue auto-cancel overlapping TP sells if supported. Cleanup/retry happens after.
  broadcast({
    type: "status",
    t: nowMs(),
    status: `STOP ORDER SUBMIT immediate_market side=${side} shares=${roundTo6(remaining)}`,
  });
  try {
    const marketOut = await executeLiveVerifiedMarketExit(side, remaining, ui, st, `${tag}-immediate-market-stop`, {
      onSubmitted: opts?.onImmediateMarketSubmitted,
      preSnapshot: initialStopSnapshot,
    });
    usedMarketFallback = true;
    lastOrderId = marketOut.orderId ?? lastOrderId;
    lastFilledAtMs = marketOut.filledAtMs ?? lastFilledAtMs;
    lastExitEventTsMs = marketOut.exitEventTsMs ?? lastExitEventTsMs;
    if (marketOut.filledShares > 1e-9) {
      filledSharesTotal += Number(marketOut.filledShares);
      filledNotional += Number(marketOut.filledPx) * Number(marketOut.filledShares);
      broadcast({
        type: "status",
        t: nowMs(),
        status:
          `STOP ORDER FILLED immediate_market px=${marketOut.filledPx} ` +
          `shares=${roundTo6(Number(marketOut.filledShares))} remaining=${roundTo6(Number(marketOut.remainingShares))}`,
      });
    }
    remaining = floorTo6(Math.max(0, Number(marketOut.remainingShares)));
    st.shares = remaining;
  } catch (e: any) {
    console.warn(`[STOP IMMEDIATE MARKET] side=${side} err=${String(e?.message ?? e)}`);
  }

  // Cleanup any resting TP after the stop submission so lingering sell orders do not
  // continue to reserve shares if the venue did not auto-cancel them.
  await cancelOpenSellOrdersForSide(side, `${tag}-post-stop-submit`, st.positionTokenId);
  if (remaining <= 1e-9) {
    const filledPx = filledNotional > 0 ? filledNotional / filledSharesTotal : baseStopPx;
    return {
      filledPx,
      filledShares: filledSharesTotal,
      remainingShares: 0,
      usedMarketFallback,
      limitAttempts,
      orderId: lastOrderId,
      filledAtMs: lastFilledAtMs,
      exitEventTsMs: lastExitEventTsMs,
    };
  }

  for (let attempt = 1; attempt <= STOP_WALK_MAX_ATTEMPTS && remaining > 1e-9; attempt++) {
    limitAttempts += 1;
    const isFirst = attempt === 1;
    const sliceTtlMs = isFirst ? STOP_INITIAL_SLICE_TTL_MS : STOP_WALK_SLICE_TTL_MS;
    if (!isFirst) {
      // After initial 1s stop attempt, walk toward current ask every 100ms.
      try {
        const ba = await getBestBidAskSafe(tokenId, side === "UP" ? "UP" : "DOWN");
        const ask = Number(ba?.ask);
        if (Number.isFinite(ask) && ask > 0) {
          walkPx = clamp01(Math.min(walkPx, ask));
        }
      } catch {}
    }
    const limitPx = walkPx;
    const sliceUntilMs = nowMs() + sliceTtlMs + 40;

    broadcast({
      type: "status",
      t: nowMs(),
      status:
        `STOP WALK ATTEMPT side=${side} px=${limitPx} shares=${roundTo6(remaining)} ` +
        `attempt=${limitAttempts}/${STOP_WALK_MAX_ATTEMPTS} ttlMs=${sliceTtlMs}`,
    });

    const sharesBefore = remaining;
    let attemptFillPx = limitPx;
    try {
      const out = await placeLiveLimitSell(side, limitPx, remaining, ui, st, {
        retryEveryMs: sliceTtlMs,
        perOrderTtlMs: sliceTtlMs,
        untilTsMs: sliceUntilMs,
        tag: "SL",
        maxOrderAttempts: 1,
      });
      attemptFillPx = Number.isFinite(Number(out.filledPx)) ? Number(out.filledPx) : limitPx;
    } catch (e: any) {
      attemptFillPx = Number.isFinite(Number(e?.avgFilledPx)) ? Number(e.avgFilledPx) : limitPx;
      await cancelOpenSellOrdersForSide(side, `${tag}-walk-reprice`, st.positionTokenId);
      if (isFirst && STOP_FORCE_MARKET_AFTER_FIRST_TTL) {
        // Hard latency cap for stops: after the first stop-limit TTL window,
        // do not keep walking for additional seconds; fall back to market.
        const afterFastFail = await getLiveVenueSharesSnapshot(side, st);
        remaining = Number.isFinite(Number(afterFastFail.shares))
          ? floorTo6(Math.max(0, Number(afterFastFail.shares)))
          : remaining;
        break;
      }
    }

    const after = await getLiveVenueSharesSnapshot(side, st);
    const remainingAfter = Number.isFinite(Number(after.shares))
      ? floorTo6(Math.max(0, Number(after.shares)))
      : remaining;
    const soldActual = floorTo6(Math.max(0, sharesBefore - remainingAfter));
    if (soldActual > 1e-9) {
      filledSharesTotal += soldActual;
      filledNotional += attemptFillPx * soldActual;
    }
    remaining = remainingAfter;
    st.shares = remaining;
    if (remaining <= 1e-9) break;
    if (remaining > 1e-9 && attempt < STOP_WALK_MAX_ATTEMPTS) await sleep(STOP_WALK_REPRICE_MS);
  }

  if (remaining > 1e-9) {
    usedMarketFallback = true;
    await cancelOpenSellOrdersForSide(side, `${tag}-walk-market-fallback`, st.positionTokenId);
    broadcast({
      type: "status",
      t: nowMs(),
      status: `STOP ORDER PLACED market_fallback side=${side} shares=${roundTo6(remaining)}`,
    });
    const marketOut = await executeLiveVerifiedMarketExit(side, remaining, ui, st, `${tag}-walk-market-fallback`);
    lastOrderId = marketOut.orderId ?? lastOrderId;
    lastFilledAtMs = marketOut.filledAtMs ?? lastFilledAtMs;
    lastExitEventTsMs = marketOut.exitEventTsMs ?? lastExitEventTsMs;
    if (marketOut.filledShares > 1e-9) {
      filledSharesTotal += Number(marketOut.filledShares);
      filledNotional += Number(marketOut.filledPx) * Number(marketOut.filledShares);
      broadcast({
        type: "status",
        t: nowMs(),
        status:
          `STOP ORDER FILLED market_fallback px=${marketOut.filledPx} ` +
          `shares=${roundTo6(Number(marketOut.filledShares))} remaining=${roundTo6(Number(marketOut.remainingShares))}`,
      });
    }
    remaining = floorTo6(Math.max(0, Number(marketOut.remainingShares)));
    st.shares = remaining;
  }

  if (!(filledSharesTotal > 1e-9)) throw new Error("[STOP WALK] no stop fill completed");
  const filledPx = filledNotional > 0 ? filledNotional / filledSharesTotal : baseStopPx;
  return {
    filledPx,
    filledShares: filledSharesTotal,
    remainingShares: floorTo6(Math.max(0, remaining)),
    usedMarketFallback,
    limitAttempts,
    orderId: lastOrderId,
    filledAtMs: lastFilledAtMs,
    exitEventTsMs: lastExitEventTsMs,
  };
}


// ===== Session lifecycle =====
function resetEngineForNewSession(engine: Engine, newSession: { slug: string; startMs: number; endMs: number }) {
  if (engine === "live") {
    liveEnteredSidesThisSession = new Set<OutcomeSide>();
    if (pendingUiLive) {
      uiLive = pendingUiLive;
      pendingUiLive = null;
      broadcast({ type: "status", t: nowMs(), status: "applied queued config at new session (live engine)", live: { ui: uiLive } });
    }

    stLive = {
      marketSlug: newSession.slug,
      marketStartMs: newSession.startMs,
      marketEndMs: newSession.endMs,

      entered: false,
      exited: false,
      side: null,

      entryTsMs: null,
      exitTsMs: null,

      entryPx: null,
      exitPx: null,

      shares: null,
      notionalUsd: null,
      grossPnlUsd: null,
      entryFeeUsd: null,
      exitFeeUsd: null,
      totalFeesUsd: null,

      pnlUsd: null,
      roiPct: null,
      holdSec: null,

      balanceUsd: liveAccount.balanceUsd,

      stopFallbackTriggered: false,
      exitInFlight: false,

      enterInFlight: false,
      lastEnterAttemptMs: 0,
      buyAttemptedThisSession: false,
      buyAttemptedSessionSlug: newSession.slug,
      buyFilledThisSession: false,
      tpOrderInFlight: false,
      lastTpArmAttemptMs: 0,
      tpOrderId: null,
      buyFilledAtMs: null,
      firstSellAttemptAtMs: null,
      positionTokenId: null,
      pendingEntrySide: null,
      pendingEntrySignalPx: null,
      pendingEntryLimitPx: null,
      pendingEntryBaseLimitPx: null,
      pendingEntryRepriceCount: 0,
      pendingEntryMode: null,
      pendingEntrySubtype: null,
      pendingEntryPlacedAtMs: null,
      pendingEntryExpiresAtMs: null,
      pendingEntryNotionalUsd: null,
      pendingTpLimitPx: null,
      pendingTpPlacedAtMs: null,
      entryMode: null,
      entrySubtype: null,
    };

    reloadEngineStrategy("live", "new session");
    void syncArtifactsToPara("new_session_live");
    return;
  }

  // Settle each paper strategy lane independently at session boundary.
  for (const lane of PAPER_LANES) {
    const laneSt = paperLaneStates[lane];
    if (
      laneSt.entered &&
      !laneSt.exited &&
      (laneSt.side === "UP" || laneSt.side === "DOWN") &&
      Number.isFinite(Number(laneSt.entryPx)) &&
      Number.isFinite(Number(laneSt.shares))
    ) {
      const side = laneSt.side as OutcomeSide;
      const now = nowMs();
      const entryPx = Number(laneSt.entryPx);
      const shares = Number(laneSt.shares);
      const notionalUsd = Number.isFinite(Number(laneSt.notionalUsd)) && Number(laneSt.notionalUsd) > 0
        ? Number(laneSt.notionalUsd)
        : entryPx * shares;
      const lastSideBid = inferSideBid(
        side,
        { bid: lastObservedBids.upBid },
        { bid: lastObservedBids.downBid }
      );
      const exitPx = Number.isFinite(Number(lastSideBid)) && Number(lastSideBid) > 0.5 ? 1 : 0;

      laneSt.exited = true;
      laneSt.exitTsMs = now;
      laneSt.exitPx = exitPx;
      const { pnlUsd } = applyExitAccounting(laneSt, exitPx, "none");
      clearPendingTp(laneSt);
      laneSt.roiPct = notionalUsd > 0 ? (pnlUsd / notionalUsd) * 100 : null;
      laneSt.holdSec = laneSt.entryTsMs ? (now - laneSt.entryTsMs) / 1000 : null;
      paperAccount.balanceUsd += pnlUsd;
      laneSt.balanceUsd = paperAccount.balanceUsd;

      emitTrade("paper", `EXIT_${side}_PAPER`, {
        strategyLane: lane,
        mode: lane,
        via: "session_rollover",
        exitType: "SETTLE_ROUND",
        reason: "session_end_round_last_bid",
        targetSellPx: exitPx,
        fillPx: exitPx,
        actualFillPx: exitPx,
        signalPx: Number.isFinite(Number(lastSideBid)) ? Number(lastSideBid) : null,
      }, laneSt, uiPaper);
    }
  }

  const blankPaper = {
    marketSlug: newSession.slug,
    marketStartMs: newSession.startMs,
    marketEndMs: newSession.endMs,

    entered: false,
    exited: false,
    side: null,

    entryTsMs: null,
    exitTsMs: null,

    entryPx: null,
    exitPx: null,

    shares: null,
    notionalUsd: null,
    grossPnlUsd: null,
    entryFeeUsd: null,
    exitFeeUsd: null,
    totalFeesUsd: null,

    pnlUsd: null,
    roiPct: null,
    holdSec: null,

    balanceUsd: paperAccount.balanceUsd,

    stopFallbackTriggered: false,
    exitInFlight: false,

    enterInFlight: false,
    lastEnterAttemptMs: 0,
    buyAttemptedThisSession: false,
    buyAttemptedSessionSlug: newSession.slug,
    buyFilledThisSession: false,
    tpOrderInFlight: false,
    lastTpArmAttemptMs: 0,
    tpOrderId: null,
    buyFilledAtMs: null,
    firstSellAttemptAtMs: null,
    positionTokenId: null,
    pendingEntrySide: null,
    pendingEntrySignalPx: null,
    pendingEntryLimitPx: null,
    pendingEntryBaseLimitPx: null,
    pendingEntryRepriceCount: 0,
    pendingEntryMode: null,
    pendingEntrySubtype: null,
    pendingEntryPlacedAtMs: null,
    pendingEntryExpiresAtMs: null,
    pendingEntryNotionalUsd: null,
    pendingTpLimitPx: null,
    pendingTpPlacedAtMs: null,
    entryMode: null,
    entrySubtype: null,
    __stoppedThisSession: false,
  };
  stPaper = { ...blankPaper };
  paperLaneStates.BASE = { ...blankPaper };
  paperLaneStates.NO_CROSS_WINNER = { ...blankPaper };
  paperEnteredSidesThisSession = new Set<OutcomeSide>();
  paperSessionLockLane = null;
  syncPaperAggregateState();

  reloadEngineStrategy("paper", "new session");
  void syncArtifactsToPara("new_session_paper");
}

// ===== Fallback Bot decision engine =====
async function maybeEnterGeneric(
  engine: Engine,
  upBA: { bid: number | null; ask?: number | null },
  dnBA: { bid: number | null; ask?: number | null },
  elapsedSec: number
) {
  const ui = engine === "paper" ? uiPaper : uiLive;
  const st = engine === "paper" ? stPaper : stLive;

  if (engine === "live" && !ui.enabled) return;
  if (st.entered || st.exited) return;
  if (!isNewEntryAllowed(engine, st)) return;
  if (elapsedSec < ui.minEntrySec) return;

  const upBid = upBA.bid;
  const dnBid = dnBA.bid;

  const upHit = Number.isFinite(upBid) && (upBid as number) >= ui.entry;
  const dnHit = Number.isFinite(dnBid) && (dnBid as number) >= ui.entry;
  if (!upHit && !dnHit) return;

  let side: OutcomeSide;
  if (upHit && dnHit) side = (upBid as number) >= (dnBid as number) ? "UP" : "DOWN";
  else side = upHit ? "UP" : "DOWN";

  const entryPx = side === "UP" ? (upBid as number) : (dnBid as number);

  const balanceUsd = engine === "paper" ? paperAccount.balanceUsd : liveAccount.balanceUsd ?? 0;
  const dynamicNotionalUsd = calcNotionalUsd({
    balanceUsd,
    betUsd: ui.betUsd,
    maxBetUsd: ui.maxBetUsd,
    kellyOn: ui.kellyOn,
    kellyMult: ui.kellyMult,
    kellyCap: ui.kellyCap,
  });
  // Paper should always use the configured bet sizing (no Kelly override).
  const notionalUsd =
    engine === "paper"
      ? clamp(ui.betUsd, 0, Math.min(ui.maxBetUsd, balanceUsd))
      : dynamicNotionalUsd;
  if (notionalUsd <= 0) return;

  if (engine === "paper") {
    markEntrySignalLatency(st, engine, side, null, "generic_threshold_touch", Number(entryPx));
    markEntrySubmitLatency(st);
    st.entered = true;
    st.side = side;
    st.entryTsMs = nowMs();
    st.entryPx = entryPx;
    st.notionalUsd = notionalUsd;
    st.entryMode = null;
    st.entrySubtype = null;
    st.shares = Number(computeEntryFromBudgetUsd(notionalUsd, entryPx, "taker").shares ?? 0);
    resetPaperDeriskExecutionState(st);
    st.notionalUsd = notionalUsd;
    applyEntryFeeAccounting(st, entryPx, Number(st.shares ?? 0), "taker", notionalUsd);
    initPositionAccountingOnEntry(st, notionalUsd);
    st.balanceUsd = paperAccount.balanceUsd;
    finalizeEntryLatency(st, Number(st.entryTsMs ?? nowMs()), {
      via: "generic_market_entry",
      signalPx: Number(entryPx),
      fillPx: Number(entryPx),
    });
    const lagEventTsMs = Number(st.entryTsMs ?? nowMs());

    emitTrade("paper", `ENTER_${side}_PAPER`, {
      signalPx: entryPx,
      signalThresholdPx: ui.entry,
      buyOrderPx: entryPx,
      fillPx: entryPx,
      actualFillPx: entryPx,
      slippageFromSignalPx: 0,
      slippageFromThresholdPx: entryPx - ui.entry,
      via: "generic",
      lagSnapshotAtEvent: currentQuoteLagSnapshotAt(lagEventTsMs),
      lagWindowBaseLookbackMs: Math.round(entryLagWindowRadiusMsForStrategy("generic") / 2),
    });
    scheduleEntryLagWindowCapture("paper", `ENTER_${side}_PAPER`, side, lagEventTsMs, "generic", {
      via: "generic",
      signalPx: entryPx,
      signalThresholdPx: ui.entry,
    });
    const tpPx = computeImmediateTpSellPx(ui, Number(entryPx));
    const tpPlacedAtMs = nowMs();
    st.pendingTpLimitPx = tpPx;
    st.pendingTpPlacedAtMs = tpPlacedAtMs;
    st.pendingTpShares = Number(st.shares ?? 0);
    st.pendingTpExitType = "EXIT";
    st.tpOrderId = `paper-tp-${current.slug}-${side}-${tpPlacedAtMs}`;
    emitTrade("paper", `EXIT_ORDER_${side}_PAPER`, {
      phase: "exit_order",
      via: "tp_limit_after_entry_fill",
      exitType: "EXIT",
      signalPx: entryPx,
      targetSellPx: tpPx,
      limitPx: tpPx,
      orderPlacedAtMs: tpPlacedAtMs,
      shares: Number(st.shares ?? 0),
      tpOrderId: st.tpOrderId,
    });
    return;
  }

  // LIVE: one-buy-per-session + in-flight + cooldown
  if ((st.buyAttemptedSessionSlug ?? null) !== (current.slug ?? null)) {
    st.buyAttemptedSessionSlug = current.slug;
    st.buyAttemptedThisSession = false;
    st.buyFilledThisSession = false;
  }
  if (st.buyFilledThisSession) return;
  if (st.buyAttemptedThisSession) return;
  if (st.enterInFlight) return;

  const now = nowMs();
  const liveEntryCooldownMs = liveEntryAttemptCooldownMsForStrategy((strategyLive as any)?.STRATEGY_ID || null);
  if (st.lastEnterAttemptMs && now - st.lastEnterAttemptMs < liveEntryCooldownMs) return;

  st.lastEnterAttemptMs = now;

  if (!shouldSkipHeavyLiveEntryPrecheckForStrategy((strategyLive as any)?.STRATEGY_ID || null)) {
    const entryPrecheck = await validateLiveEntryPreconditions(side, notionalUsd, "generic_enter_precheck");
    if (!entryPrecheck.ok) {
      console.warn(
        `[ENTER BLOCKED] engine=live(generic) side=${side} code=${entryPrecheck.code} ` +
        `tokenId=${entryPrecheck.meta?.tokenId ?? "-"} allow=${entryPrecheck.meta?.conditionalAllowanceShares ?? "-"}`
      );
      if (shouldEmitEntryBlockedEvent(st, side, entryPrecheck.code)) {
        broadcast({
          type: "status",
          t: nowMs(),
          status: `ENTER BLOCKED code=${entryPrecheck.code} side=${side} token=${entryPrecheck.meta?.tokenId ?? "-"}`,
        });
        emitTrade("live", `ENTER_BLOCKED_${side}_LIVE`, {
          via: "generic",
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: entryPrecheck.code,
          entryBlockReason: entryPrecheck.code,
          entryBlockMeta: entryPrecheck.meta,
        });
      }
      return;
    }
  }
  markEntrySignalLatency(st, engine, side, null, "generic_threshold_touch", Number(entryPx));

  st.enterInFlight = true;
  st.buyAttemptedThisSession = true;
  st.buyAttemptedSessionSlug = current.slug;

  st.entered = true;
  st.side = side;
  st.entryTsMs = nowMs();
  st.entryPx = entryPx;
  st.notionalUsd = notionalUsd;
  markEntrySubmitLatency(st);

  try {
    const immediate = shouldUseAggressiveLiveMarketEntry() || LIVE_ENTRY_STYLE !== "limit";
    const buyPx = immediate
      ? immediateBuyPxForSide(side, upBA, dnBA, ui.entry)
      : buyPxForSide(side, upBA, dnBA, configuredEntryLimitPx(ui));
    let executedBuyPx = buyPx;
    const ttlMs = immediate ? LIVE_ENTRY_IMMEDIATE_TTL_MS : LIVE_BUY_TTL_MS;
    console.log(`[ENTER LIVE][generic] style=${immediate ? "immediate" : "limit"} side=${side} buyPx=${buyPx} ttlMs=${ttlMs}`);
    let out: { filledPx: number; shares: number; tpOrderId: string | null; tokenId: string; filledAtMs: number | null; entryEventTsMs: number | null; orderId: string | null };
    if (immediate) {
      emitTrade("live", `ENTER_SUBMIT_START_${side}_LIVE`, {
        via: "generic",
        signalPx: entryPx,
        signalThresholdPx: ui.entry,
        buyOrderPx: buyPx,
        orderType: "MARKET",
      });
      out = await placeLiveMarketBuy(side, notionalUsd, ui, {
        strictMarketOnly: true,
        strategyIdLike: (strategyLive as any)?.STRATEGY_ID || null,
        fallbackPxOverride: buyPx,
        requireOrderTimelineFillTs: requiresOrderTimelineLatency((strategyLive as any)?.STRATEGY_ID || null),
        onAccepted: ({ acceptedAtMs, orderId }) => {
          emitTrade("live", `ENTER_SUBMIT_ACCEPTED_${side}_LIVE`, {
            via: "generic",
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            buyOrderPx: buyPx,
            orderType: "MARKET",
            eventTsMs: acceptedAtMs,
            orderId: orderId ?? null,
          });
        },
        onFirstFillSeen: ({ firstFillSeenAtMs, orderId, filledPx, shares, filledAtMs }) => {
          emitTrade("live", `ENTER_FIRST_FILL_SEEN_${side}_LIVE`, {
            via: "generic",
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            eventTsMs: firstFillSeenAtMs,
            actualFillTsMs: filledAtMs,
            fillPx: filledPx,
            actualFillPx: filledPx,
            shares,
            orderId: orderId ?? null,
          });
        },
        onFilledConfirmed: ({ filledConfirmedAtMs, orderId, filledPx, shares, filledAtMs }) => {
          emitTrade("live", `ENTER_FILL_CONFIRMED_${side}_LIVE`, {
            via: "generic",
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            eventTsMs: filledConfirmedAtMs,
            actualFillTsMs: filledAtMs,
            fillPx: filledPx,
            actualFillPx: filledPx,
            shares,
            orderId: orderId ?? null,
          });
        },
      });
      executedBuyPx = out.filledPx;
    } else {
      try {
        out = await placeLiveLimitBuy(side, buyPx, notionalUsd, ui, ttlMs, {
          strategyIdLike: (strategyLive as any)?.STRATEGY_ID || null,
        });
      } catch (e1: any) {
        const msg1 = String(e1?.message ?? e1);
        if (isLikelyUnfilledLiveBuy(msg1)) {
          const askNowRaw = side === "UP" ? Number((upBA as any)?.ask) : Number((dnBA as any)?.ask);
          const bidNowRaw = side === "UP" ? Number((upBA as any)?.bid) : Number((dnBA as any)?.bid);
          const basePx = Number.isFinite(askNowRaw) ? askNowRaw : (Number.isFinite(bidNowRaw) ? bidNowRaw : buyPx);
          const escalateLimitPx = clamp01(basePx);
          const escalateBuyPx = buyPxForSide(side, upBA as any, dnBA as any, escalateLimitPx);
          emitTrade("live", `ENTER_REPRICE_${side}_LIVE`, {
            phase: "entry_reprice",
            via: "base_ttl_escalate_to_ask",
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            oldLimitPx: buyPx,
            buyOrderPx: escalateBuyPx,
            limitPx: escalateLimitPx,
            ttlMs: LIVE_BASE_ESCALATE_TTL_MS,
          });
          executedBuyPx = escalateBuyPx;
          out = await placeLiveLimitBuy(side, escalateBuyPx, notionalUsd, ui, LIVE_BASE_ESCALATE_TTL_MS, {
            strategyIdLike: (strategyLive as any)?.STRATEGY_ID || null,
          });
        } else {
          throw e1;
        }
      }
    }
    st.entryPx = out.filledPx;
    st.entryTsMs = out.filledAtMs ?? st.entryTsMs ?? nowMs();
    st.shares = out.shares;
    st.positionTokenId = out.tokenId ?? st.positionTokenId ?? tokenIdForSide(side);
    await reconcileLiveSharesFromPosition(st, side, "generic_entry_fill");
    await refreshPolymarketStateAfterFill(st, side, "generic_entry_fill");
    resetPaperDeriskExecutionState(st);
    st.notionalUsd =
      Number.isFinite(Number(st.shares)) && Number.isFinite(out.filledPx)
        ? Number(st.shares) * out.filledPx
        : st.notionalUsd;
    applyEntryFeeAccounting(st, Number(st.entryPx), Number(st.shares ?? 0));
    initPositionAccountingOnEntry(st, Number(st.notionalUsd ?? 0));
    st.balanceUsd = liveAccount.balanceUsd;
    st.buyFilledThisSession = true;
    st.tpOrderId = out.tpOrderId ?? null;
    st.buyFilledAtMs = hasVerifiedVenueFillTs(out.filledAtMs) ? out.filledAtMs : null;
    st.firstSellAttemptAtMs = null;
    const strictLatencyFillOk =
      !requiresOrderTimelineLatency((strategyLive as any)?.STRATEGY_ID || null) ||
      out.fillTimestampSource === "order_timeline";
    if (hasVerifiedVenueFillTs(st.buyFilledAtMs) && strictLatencyFillOk) {
      finalizeEntryLatency(st, Number(st.buyFilledAtMs), {
        via: "generic_live_entry",
        signalPx: Number(entryPx),
        fillPx: Number(out.filledPx),
      });
      const lagEventTsMs = Number(st.buyFilledAtMs ?? st.entryTsMs ?? nowMs());
      emitTrade("live", `ENTER_${side}_LIVE`, {
        actualFillTsMs: out.filledAtMs,
        eventTsMs: out.entryEventTsMs ?? out.filledAtMs,
        signalPx: entryPx,
        signalThresholdPx: ui.entry,
        buyOrderPx: executedBuyPx,
        fillPx: out.filledPx,
        actualFillPx: out.filledPx,
        orderId: out.orderId ?? null,
        slippageFromSignalPx: Number(out.filledPx) - Number(entryPx),
        slippageFromThresholdPx: Number(out.filledPx) - Number(ui.entry),
        via: "generic",
        lagSnapshotAtEvent: currentQuoteLagSnapshotAt(lagEventTsMs),
        lagWindowBaseLookbackMs: Math.round(entryLagWindowRadiusMsForStrategy((strategyLive as any)?.STRATEGY_ID || "generic_live") / 2),
      });
      scheduleEntryLagWindowCapture(
        "live",
        `ENTER_${side}_LIVE`,
        side,
        lagEventTsMs,
        (strategyLive as any)?.STRATEGY_ID || "generic_live",
        {
          via: "generic",
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          buyOrderPx: executedBuyPx,
        }
      );
    } else {
      console.warn(
        `[LIVE ENTER HYDRATED WITHOUT VENUE TS] via=generic side=${side} slug=${current.slug} ` +
        `shares=${roundTo6(Number(out.shares ?? 0))} px=${roundTo6(Number(out.filledPx ?? 0))} ` +
        `fillTsSource=${String(out.fillTimestampSource || "unknown")}`
      );
    }
  } catch (e: any) {
    st.entered = false;
    st.side = null;
    st.entryTsMs = null;
    st.entryPx = null;
    st.entryMode = null;
    st.entrySubtype = null;
    st.shares = null;
    st.notionalUsd = null;
    st.grossPnlUsd = null;
    st.entryFeeUsd = null;
    st.exitFeeUsd = null;
    st.totalFeesUsd = null;
    st.positionTokenId = null;
    st.buyFilledAtMs = null;
    st.firstSellAttemptAtMs = null;
    const errMsg = String(e?.message ?? e);
    if (shouldRearmLiveEntryAfterErrorForStrategy((strategyLive as any)?.STRATEGY_ID || null, errMsg)) {
      st.buyAttemptedThisSession = false;
      console.warn(`[LIVE ENTER REARM] generic reason=${errMsg}`);
    }
    clearEntryLatency(st);

    console.log("[LIVE] enter failed:", e);
    broadcast({ type: "status", t: nowMs(), status: `enter failed (live): ${e?.stack ?? e?.message ?? String(e)}` });
  } finally {
    st.enterInFlight = false;
  }
}

async function maybeExitGeneric(
  engine: Engine,
  upBA: { bid: number | null },
  dnBA: { bid: number | null },
  opts?: { stopOnly?: boolean }
) {
  const ui = engine === "paper" ? uiPaper : uiLive;
  const st = engine === "paper" ? stPaper : stLive;

  if (engine === "live" && !ui.enabled) return;
  if (!st.entered || st.exited || !st.side) {
    if (engine === "live" && opts?.stopOnly && ui.useStop) {
      await reconcileLivePositionMaybe(true, "stop-only-no-live-state");
      if (!st.entered || st.exited || !st.side) {
        await hydrateLivePositionFromTokenBalances("stop-only-no-live-state");
      }
      if (st.entered && !st.exited && st.side) {
        console.warn(
          `[LIVE POS SYNC] recovered during stop-only path side=${st.side} shares=${roundTo6(Number(st.shares ?? 0))} slug=${current.slug}`
        );
        // Continue in this same tick using recovered state.
      } else {
      const t = nowMs();
      if (!((st as any).__lastNoLivePositionStopLogMs) || t - (st as any).__lastNoLivePositionStopLogMs >= STOP_SKIP_LOG_INTERVAL_MS) {
        console.log(
          `[STOP SKIP] engine=live reason=no_live_position entered=${st.entered} exited=${st.exited} side=${st.side ?? "-"}`
        );
        (st as any).__lastNoLivePositionStopLogMs = t;
      }
      }
    }
    if (!st.entered || st.exited || !st.side) return;
  }
  if (engine === "live" && st.exitInFlight) return;

  const side = st.side;
  const curBid = inferSideBid(side, upBA, dnBA);
  if (!Number.isFinite(Number(curBid))) return;

  const px = Number(curBid);
  const elapsedSec = current.startMs > 0 ? Math.max(0, (nowMs() - current.startMs) / 1000) : 0;
  const shouldProfitExit = !opts?.stopOnly && px >= ui.exit;
  const shouldStop = shouldTriggerStop(ui, side, px, elapsedSec, engine, "generic");
  if (!shouldProfitExit && !shouldStop) return;

  const exitReason = shouldStop ? "STOP" : "EXIT";
  markExitSignalLatency(st, engine, side, null, "generic_exit_signal", exitReason);
  console.log(
    `[SELL SIGNAL] (generic) slug=${current.slug} engine=${engine} reason=${exitReason} side=${side} px=${px} ` +
      `shares=${st.shares ?? "—"} entryPx=${st.entryPx ?? "—"}`
  );
  emitTrade(engine, `SIGNAL_${exitReason}_${side}_${engine.toUpperCase()}`, {
    phase: "signal",
    via: "generic",
    signalPx: px,
    exitType: exitReason,
  });

  if (engine === "paper") {
    markExitSubmitLatency(st);
    st.exited = true;
    st.exitTsMs = nowMs();
    st.exitPx = px;
    st.stopFallbackTriggered = false;
    const exitFeeMode: ExitFeeMode = shouldStop ? "taker" : "maker";
    const { pnlUsd } = applyExitAccounting(st, px, exitFeeMode);
    clearPendingTp(st);
    clearPendingStop(st);
    st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;

    paperAccount.balanceUsd += pnlUsd;
    st.balanceUsd = paperAccount.balanceUsd;
    finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
      via: "generic_exit",
      exitType: exitReason,
      fillPx: Number(px),
      signalPx: Number(px),
    });

    emitTrade("paper", `${exitReason}_${side}_PAPER`);
    return;
  }

  try {
    if (exitReason !== "EXIT") {
      emitTrade("live", `SIGNAL_STOP_${side}_LIVE`, {
        phase: "signal_stop",
        via: "generic",
        signalPx: Number(px),
        intendedPx: Number(px),
        exitPx: Number(px),
        exitType: "STOP",
        stopReason: "STOP",
        stopSource: "generic_stop_signal",
      }, st, ui);
    }
    const recoveredShares = await recoverLiveSharesForExit(st, side, `generic_${exitReason.toLowerCase()}`);
    if (!(recoveredShares > 0)) {
      st.exited = true;
      st.exitTsMs = nowMs();
      st.exitPx = Number(px);
      emitTrade("live", `${exitReason}_${side}_LIVE`, {
        via: "venue_reconcile",
        actualFillPx: Number(px),
        venueAlreadyFlat: true,
        signalPx: Number(px),
        intendedPx: Number(px),
        exitPx: Number(px),
        exitType: exitReason === "EXIT" ? "EXIT" : "STOP",
        stopReason: exitReason === "EXIT" ? null : "STOP",
        stopSource: exitReason === "EXIT" ? null : "generic_stop_venue_flat",
      });
      clearLivePositionStateAfterTerminalExit(st);
      const stAny = st as any;
      const flatWarnKey = `generic_flat|${String(exitReason || "")}|${String(side || "")}|${String(st.marketSlug || "")}`;
      const flatWarnBucket = stAny.__liveExitRecoverWarnAtByKey && typeof stAny.__liveExitRecoverWarnAtByKey === "object"
        ? stAny.__liveExitRecoverWarnAtByKey
        : {};
      const flatLastAt = Number(flatWarnBucket[flatWarnKey] || 0);
      if (!Number.isFinite(flatLastAt) || (nowMs() - flatLastAt) >= 5000) {
        flatWarnBucket[flatWarnKey] = nowMs();
        stAny.__liveExitRecoverWarnAtByKey = flatWarnBucket;
        console.warn(`[LIVE EXIT RECOVER FLAT] reason=${exitReason} side=${side} venue already flat; clearing local state`);
      }
      return;
    }

    const sessionEndMs = st.marketEndMs ?? (Date.now() + 60_000);
    if (st.firstSellAttemptAtMs == null) st.firstSellAttemptAtMs = nowMs();
    const buyFillToSellAttemptMs =
      Number.isFinite(Number(st.buyFilledAtMs)) ? Math.max(0, Number(st.firstSellAttemptAtMs) - Number(st.buyFilledAtMs)) : null;
    console.log(
      `[EXIT LATENCY] engine=${engine} reason=${exitReason} side=${side} ` +
      `buyFillToSellAttemptMs=${buyFillToSellAttemptMs ?? "na"}`
    );

    if (exitReason === "EXIT") {
      console.log(`[SELL EXPECTED] (generic TP) retryEvery=5000ms slug=${current.slug} side=${side} targetPx=${ui.exit}`);
      markExitSubmitLatency(st);

      const out = await placeLiveLimitSell(side, ui.exit, st.shares, ui, st, {
        retryEveryMs: 5000,
        perOrderTtlMs: 4500,
        untilTsMs: sessionEndMs,
        tag: "TP",
      });

      st.exited = true;
      st.exitTsMs = nowMs();
      st.exitPx = out.filledPx;
      st.stopFallbackTriggered = false;
      st.positionTokenId = null;
      applyExitAccounting(st, Number(st.exitPx), "maker");

      st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;
      finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
        via: "generic_tp_limit",
        exitType: "EXIT",
        fillPx: Number(out.filledPx),
        signalPx: Number(px),
      });
      emitTrade("live", `EXIT_${side}_LIVE`, {
        orderId: (out as any).orderId ?? null,
        actualFillTsMs: (out as any).filledAtMs ?? null,
        eventTsMs: (out as any).filledAtMs ?? null,
        actualFillPx: Number(out.filledPx),
        fillPx: Number(out.filledPx),
        via: "generic_tp_limit",
      });
      clearLivePositionStateAfterTerminalExit(st);
      return;
    }

    await suppressHostLiveTpProtectionForStopSignal(side, st, "generic-stop");
    console.log(`[SELL EXPECTED] (generic SL) retryEvery=1000ms slug=${current.slug} side=${side} targetPx=${ui.stop}`);

    const precheck = await validateLiveStopPreconditions(side, st, Number(st.shares), "generic_stop");
    if (!precheck.ok) {
      console.warn(
        `[STOP BLOCKED] engine=live side=${side} code=${precheck.code} ` +
        `tokenId=${precheck.meta?.tokenId ?? "-"} req=${precheck.meta?.requestedShares ?? "-"} ` +
        `avail=${precheck.meta?.availableShares ?? "-"} allow=${precheck.meta?.conditionalAllowanceShares ?? "-"}`
      );
      if (shouldEmitStopBlockedEvent(st, side, precheck.code)) {
        broadcast({
          type: "status",
          t: nowMs(),
          status: `STOP PRECHECK WARN code=${precheck.code} side=${side} token=${precheck.meta?.tokenId ?? "-"}; continuing`,
        });
        emitTrade("live", `STOP_BLOCKED_${side}_LIVE`, {
          via: "generic",
          signalPx: px,
          exitType: "STOP_BLOCKED",
          stopReason: precheck.code,
          stopBlockCode: precheck.code,
          stopMeta: precheck.meta,
        });
      }
      console.warn(`[STOP CONTINUE] engine=live side=${side} proceeding despite precheck code=${precheck.code}`);
    }
    st.exitInFlight = true;
    const stopSignalPx = Number.isFinite(Number(px)) ? Number(px) : Number(ui.stop);
    markExitSubmitLatency(st);
    const priorEntryMode = String(st.entryMode || "");
    const priorSide = side;
    await recoverLiveSharesForExit(st, side, "generic_stop");
    const stopSubmitStartMs = nowMs();
    const stopRequestedShares = Number(st.shares ?? 0);
    emitTrade("live", `STOP_SUBMIT_START_${side}_LIVE`, {
      eventTsMs: stopSubmitStartMs,
      signalPx: Number(stopSignalPx),
      intendedPx: Number(stopSignalPx),
      exitPx: Number(stopSignalPx),
      sharesRequested: stopRequestedShares,
      exitType: "STOP",
      stopReason: "STOP",
      stopSource: "generic_stop_submit_start",
      via: "generic",
    });
    const submitted = await startOptimisticLiveStopRecovery(side, stopSignalPx, ui, st, "generic_stop", {
      priorEntryMode,
      priorSide,
      exitType: "STOP",
      resolvedStopReason: "STOP",
      stopMeta: {
        stopSignalPx,
        stopRequestedShares,
        via: "generic",
      },
    });
    broadcast({
      type: "status",
      t: submitted.submittedAtMs,
      status: `STOP ORDER SUBMITTED optimistic_rearm side=${side} recoveryId=${submitted.recoveryId}`,
    });
    clearLivePositionStateAfterTerminalExit(st);
    rearmLiveSessionForNextLane(st, priorEntryMode, priorSide, (strategyLive as any)?.STRATEGY_ID || null);
    return;
  } catch (e: any) {
    console.error("[LIVE SELL ERROR]", e.message, e.stack || e);
    throw e;
  } finally {
    if (engine === "live") st.exitInFlight = false;
  }
}

// ===== Strategy-driven engine tick =====
async function runEngineTick(
  engine: Engine,
  upBA: { bid: number | null; ask?: number | null },
  dnBA: { bid: number | null; ask?: number | null },
  elapsedSec: number,
  isFinal: boolean,
  lane?: StrategyLane
) {
  const ui = engine === "paper" ? uiPaper : uiLive;
  const st = engine === "paper" && lane ? paperLaneStates[lane] : engine === "paper" ? stPaper : stLive;
  const strat = engine === "paper" && lane ? strategyPaperByLane[lane] : engine === "paper" ? strategyPaper : strategyLive;
  const laneTag = lane ? ` lane=${lane}` : "";
  const emitTradeScoped = (action: string, extra?: Record<string, any>) => {
    const payload = { ...(extra || {}) };
    if (lane) {
      if (payload.mode == null) payload.mode = lane;
      payload.strategyLane = lane;
    }
    emitTrade(engine, action, payload, st, ui);
  };
  const computePaperTpLimitPx = (entryFillPx: number | null): number => {
    const mode = String(st.entryMode ?? st.pendingEntryMode ?? "").toUpperCase();
    const subtype = String(st.entrySubtype ?? st.pendingEntrySubtype ?? "").toUpperCase();
    if (mode === "NO_CROSS_WINNER") {
      return subtype === "HC_SAME_SIDE" ? 0.99 : 0.96;
    }
    return computeImmediateTpSellPx(ui, Number(entryFillPx));
  };
  const isDeriskLaneMode = (modeHint?: string | null) => {
    return strategyAllowsDualLaneEntries(modeHint ?? lane ?? null);
  };
  const computeDeriskSharesFromState = (deriskPxRaw?: number | null): number => {
    const curShares = Math.max(0, Number(st.shares ?? 0));
    if (!(curShares > 0)) return 0;
    const entryPx = Number(st.entryPx);
    const entryFeeUsd = Math.max(0, Number(st.entryFeeUsd ?? 0));
    const deriskPx = clamp01(
      Number.isFinite(Number(deriskPxRaw)) ? Number(deriskPxRaw) : Number(DERISK_STRICT_DERISK_THR)
    );
    if (!Number.isFinite(deriskPx) || deriskPx <= 0) return 0;
    const principalUsd = (Number.isFinite(entryPx) ? curShares * entryPx : 0) + entryFeeUsd;
    if (!(principalUsd > 0)) return 0;
    return Math.max(0, Math.min(curShares, principalUsd / deriskPx));
  };
  const armPaperTpOrder = (
    side: OutcomeSide,
    entryFillPx: number | null,
    sharesToSell?: number | null,
    exitType?: string | null,
    explicitLimitPx?: number | null,
    forceReplace?: boolean
  ) => {
    if (engine !== "paper" || st.exited || !st.entered || !side || !Number.isFinite(Number(st.shares)) || Number(st.shares) <= 0) {
      return;
    }
    const tpPxRaw = Number.isFinite(Number(explicitLimitPx))
      ? Number(explicitLimitPx)
      : computePaperTpLimitPx(Number(entryFillPx));
    const tpPx = clamp01(tpPxRaw);
    if (!Number.isFinite(tpPx) || tpPx <= 0 || tpPx >= 1) return;
    const curShares = Number(st.shares);
    const sellShares = Number.isFinite(Number(sharesToSell))
      ? Math.max(0, Math.min(curShares, Number(sharesToSell)))
      : curShares;
    if (!(sellShares > 0)) return;
    const normalizedExitType = String(exitType || "EXIT").toUpperCase();
    if (
      isSinglePartialExitTypeRaw(normalizedExitType) &&
      paperSinglePartialCompletedForCurrentPosition(st, side)
    ) {
      return;
    }
    if (
      normalizedExitType === "DERISK" &&
      String(st.paperDeriskCompletedSessionSlug || "") === String(current.slug || "") &&
      String(st.paperDeriskCompletedSide || "").toUpperCase() === String(side || "").toUpperCase() &&
      Number.isFinite(Number(st.paperDeriskCompletedEntryTsMs)) &&
      Number.isFinite(Number(st.entryTsMs)) &&
      Math.abs(Number(st.paperDeriskCompletedEntryTsMs) - Number(st.entryTsMs)) <= 1
    ) {
      return;
    }
    const alreadyArmed =
      Number.isFinite(Number(st.pendingTpLimitPx)) &&
      Number(st.pendingTpLimitPx) > 0 &&
      !!st.tpOrderId;
    if (alreadyArmed && !forceReplace) return;
    if (alreadyArmed && forceReplace) {
      clearPendingTp(st);
    }
    const orderPlacedAtMs = nowMs();
    st.pendingTpLimitPx = tpPx;
    st.pendingTpPlacedAtMs = orderPlacedAtMs;
    st.pendingTpShares = sellShares;
    st.pendingTpExitType = normalizedExitType;
    st.pendingTpArmedPositionShares = curShares;
    st.pendingTpFillLockId = null;
    st.tpOrderId = `paper-tp-${current.slug}-${side}-${orderPlacedAtMs}`;
    markExitSignalLatency(st, engine, side, lane ?? null, "paper_resting_tp_order", st.pendingTpExitType);
    markExitSubmitLatency(st);
    const emitTpOrder = async () => {
      const fillCapacityEstimate =
        shouldTrackPaperFillCapacity(engine)
          ? await estimateFillCapacitySnapshot(tokenIdForSide(side), "sell", tpPx)
          : null;
      emitTradeScoped(`EXIT_ORDER_${side}_PAPER`, {
        phase: "exit_order",
        via: "tp_limit_after_entry_fill",
        exitType: st.pendingTpExitType,
        signalPx: Number.isFinite(Number(entryFillPx)) ? Number(entryFillPx) : null,
        targetSellPx: tpPx,
        limitPx: tpPx,
        orderPlacedAtMs,
        shares: sellShares,
        tpOrderId: st.tpOrderId,
        mode: lane ?? null,
        fillCapacityEstimate,
      });
    };
    void emitTpOrder();
  };

  if (engine === "live" && !ui.enabled) return;

  if (!strat) {
    if ((st as any).__lastNoStrategyLogMs == null) (st as any).__lastNoStrategyLogMs = 0;
    const tNow = nowMs();
    if (tNow - (st as any).__lastNoStrategyLogMs > 2000) {
      console.warn(`[NO STRATEGY] engine=${engine}${laneTag} trading disabled until external makeStrategy loads`);
      broadcast({
        type: "status",
        t: tNow,
        status: `NO STRATEGY (${engine}${lane ? ":" + lane : ""}): trading disabled until external makeStrategy loads`,
      });
      (st as any).__lastNoStrategyLogMs = tNow;
    }
    return;
  }

  // Infer missing side from opposite bid in binary markets (UP ~= 1 - DOWN).
  const upBidRaw = Number(upBA.bid ?? NaN);
  const dnBidRaw = Number(dnBA.bid ?? NaN);
  const upBid = Number.isFinite(upBidRaw) ? upBidRaw : (Number.isFinite(dnBidRaw) ? clamp01(1 - dnBidRaw) : NaN);
  const dnBid = Number.isFinite(dnBidRaw) ? dnBidRaw : (Number.isFinite(upBidRaw) ? clamp01(1 - upBidRaw) : NaN);

  const rawAction = strat.onTick({
    elapsedSec,
    upBid,
    downBid: dnBid,
    isFinal,
    position: {
      entered: !!st.entered,
      side: (st.side as OutcomeSide | null) ?? null,
      shares: Number.isFinite(Number(st.shares)) ? Number(st.shares) : null,
      entryPx: Number.isFinite(Number(st.entryPx)) ? Number(st.entryPx) : null,
      entryFeeUsd: Number.isFinite(Number(st.entryFeeUsd)) ? Number(st.entryFeeUsd) : null,
      notionalUsd: Number.isFinite(Number(st.notionalUsd)) ? Number(st.notionalUsd) : null,
    },
  });
  let action = normalizeStrategyAction(rawAction);
  const deriskModeActive = strategyAllowsDualLaneEntries(
    String(action?.enter?.mode || st?.pendingEntryMode || st?.entryMode || lane || "").trim() || null
  );
  if (engine === "paper" && deriskModeActive && st.enterInFlight && st.pendingEntrySide) {
    clearPendingEntry(st);
  }
  // Resting entry auto-trigger: avoid strategy-side latency for initial entry arming.
  if (
    ENTRY_RESTING_AUTOTRIGGER_ENABLED &&
    !strategyAllowsDualLaneEntries(null) &&
    strategyAllowsDualLaneEntries(lane ?? null) &&
    !action?.enter &&
    !st.entered &&
    !st.exited &&
    !st.enterInFlight &&
    !st.pendingEntrySide
  ) {
    const minEntrySec = Number(ui.minEntrySec ?? 0);
    const upHit = Number.isFinite(upBid) && upBid >= Number(ui.entry);
    const dnHit = Number.isFinite(dnBid) && dnBid >= Number(ui.entry);
    if ((Number.isFinite(elapsedSec) ? elapsedSec >= minEntrySec : true) && (upHit || dnHit)) {
      const sideAuto: OutcomeSide = upHit && dnHit ? (upBid >= dnBid ? "UP" : "DOWN") : (upHit ? "UP" : "DOWN");
      const signalPx = sideAuto === "UP" ? Number(upBid) : Number(dnBid);
      const entryCapPx = activeEntryPriceCapPx();
      const capOk =
        !Number.isFinite(Number(entryCapPx)) ||
        Number(entryCapPx) <= 0 ||
        (Number.isFinite(signalPx) && signalPx < Number(entryCapPx));
      if (Number.isFinite(signalPx) && signalPx < Number(ui.exit) && capOk) {
        const modeAuto = strategyAllowsDualLaneEntries(lane ?? null)
          ? "SINGLE_INSTANCE_DERISK"
          : (lane ?? "BASE");
        action = {
          ...(action || {}),
          enter: {
            side: sideAuto,
            entryPx: signalPx,
            limitPx: Number(ui.entry),
            ttlMs: ENTRY_RESTING_TTL_MS,
            mode: modeAuto,
          },
        };
      }
    }
  }
  // Live stop fail-safe: inject immediate stop action as soon as threshold is touched.
  if (
    !action?.exit &&
    engine === "live" &&
    !strategyAllowsDualLaneEntries(null) &&
    st.entered &&
    !st.exited &&
    (st.side === "UP" || st.side === "DOWN") &&
    !st.exitInFlight
  ) {
    const sideLive = st.side as OutcomeSide;
    const sideBidLive = inferSideBid(sideLive, upBA, dnBA);
    if (
      Number.isFinite(Number(sideBidLive)) &&
      shouldTriggerStop(ui, sideLive, Number(sideBidLive), elapsedSec, engine, "resting_server")
    ) {
      action = {
        ...(action || {}),
        exit: {
          type: "STOP",
          side: sideLive,
          exitPx: Number(sideBidLive),
          stopSource: "RESTING_SERVER",
          stopReason: "RESTING_STOP_THRESHOLD",
        },
      };
    }
  }
  if (!action && rawAction && typeof rawAction === "object") {
    if ((st as any).__lastUnrecognizedActionLogMs == null) (st as any).__lastUnrecognizedActionLogMs = 0;
    const tNow = nowMs();
    if (tNow - (st as any).__lastUnrecognizedActionLogMs > 2000) {
      console.warn(`[STRAT ACTION IGNORED] engine=${engine}${laneTag} raw=${JSON.stringify(rawAction)}`);
      (st as any).__lastUnrecognizedActionLogMs = tNow;
    }
  }
  // Momentum entry fallback injectors are disabled: entries are now strategy-driven
  // market orders and should not be synthesized by server fallback paths.
  const allowMomentumFallbackEntry = false;

  // HC safeguard: if BASE exited in this same 5m session, allow HC entry from
  // server state even if strategy shared-state missed the transition.
  // Priority: opposite-side (legacy best hitter), then same-side-after-stop.
  if (
    engine === "paper" &&
    lane === "NO_CROSS_WINNER" &&
    allowMomentumFallbackEntry &&
    !deriskModeActive &&
    !action &&
    !st.entered &&
    !st.exited &&
    !st.enterInFlight
  ) {
    const sec = Number(elapsedSec);
    const nearClose = Number.isFinite(sec) && sec >= (300 - HC_BLOCK_LAST_SEC);
    if (nearClose) {
      const stAny = st as any;
      stAny.__hcFallbackSameSideStreak = 0;
    } else {
    const stAny = st as any;
    const baseLane = paperLaneStates.BASE;
    const baseExitedSameSession =
      !!baseLane &&
      !!baseLane.exited &&
      !!baseLane.side &&
      String(baseLane.marketSlug || "") === String(current.slug || "");
    if (baseExitedSameSession) {
      const baseSide: OutcomeSide = baseLane.side as OutcomeSide;
      const oppositeSide: OutcomeSide = baseSide === "UP" ? "DOWN" : "UP";
      const oppositeBid = inferSideBid(oppositeSide, upBA, dnBA);
      const oppositeLead = Number(HC_OPPOSITE_MIN_BID);

      let selectedSide: OutcomeSide | null = null;
      let selectedBid: number | null = null;
      let selectedReason = "";

      if (Number.isFinite(Number(oppositeBid)) && Number.isFinite(oppositeLead) && Number(oppositeBid) >= oppositeLead) {
        selectedSide = oppositeSide;
        selectedBid = Number(oppositeBid);
        selectedReason = "opposite_after_base_exit";
      } else if (!!baseLane.stopFallbackTriggered) {
        const sameSide: OutcomeSide = baseSide;
        const sameSideBid = inferSideBid(sameSide, upBA, dnBA);
        const rearmEntryThr = Number(ui.entry);
        if (
          stAny.__hcFallbackSameSideNeedsRearmBelowEntry !== true ||
          String(stAny.__hcFallbackSameSideRearmSlug || "") !== String(current.slug || "") ||
          String(stAny.__hcFallbackSameSideRearmSide || "") !== String(sameSide || "")
        ) {
          stAny.__hcFallbackSameSideNeedsRearmBelowEntry = true;
          stAny.__hcFallbackSameSideRearmedBelowEntry = false;
          stAny.__hcFallbackSameSideRearmSlug = String(current.slug || "");
          stAny.__hcFallbackSameSideRearmSide = String(sameSide || "");
        }
        if (
          stAny.__hcFallbackSameSideNeedsRearmBelowEntry === true &&
          stAny.__hcFallbackSameSideRearmedBelowEntry !== true &&
          Number.isFinite(Number(sameSideBid)) &&
          Number.isFinite(rearmEntryThr) &&
          Number(sameSideBid) < rearmEntryThr
        ) {
          stAny.__hcFallbackSameSideRearmedBelowEntry = true;
        }
        if (Number.isFinite(Number(sameSideBid)) && Number(sameSideBid) >= HC_SAME_SIDE_MIN_BID) {
          stAny.__hcFallbackSameSideStreak = Number(stAny.__hcFallbackSameSideStreak || 0) + 1;
        } else {
          stAny.__hcFallbackSameSideStreak = 0;
        }
        const stopTsMs = Number(baseLane.exitTsMs ?? 0);
        const sinceStopSec = Number.isFinite(stopTsMs) && stopTsMs > 0 ? (nowMs() - stopTsMs) / 1000 : NaN;
        if (
          stAny.__hcFallbackSameSideRearmedBelowEntry === true &&
          Number(stAny.__hcFallbackSameSideStreak || 0) >= HC_SAME_SIDE_PERSISTENCE_TICKS &&
          Number.isFinite(sinceStopSec) &&
          sinceStopSec >= HC_SAME_SIDE_MIN_SEC_AFTER_STOP
        ) {
          selectedSide = sameSide;
          selectedBid = Number(sameSideBid);
          selectedReason = "same_side_after_stop";
        }
      }

      if (selectedSide && Number.isFinite(Number(selectedBid))) {
        const fallbackLimitPx = clamp01(Math.min(0.9, Number(selectedBid) + 0.03));
        const hcSubtype = selectedReason === "same_side_after_stop" ? "HC_SAME_SIDE" : "HC_OPPOSITE";
        action = {
          enter: {
            side: selectedSide,
            entryPx: Number(selectedBid),
            limitPx: fallbackLimitPx,
            ttlMs: LIVE_BUY_TTL_MS,
            mode: "NO_CROSS_WINNER",
            hcSubtype,
          },
        };
        console.log(
          `[HC FALLBACK SIGNAL] lane=${lane} slug=${current.slug} side=${selectedSide} reason=${selectedReason} ` +
          `bid=${Number(selectedBid).toFixed(2)} oppLead=${Number(HC_OPPOSITE_MIN_BID).toFixed(2)} ` +
          `sameMinBid=${HC_SAME_SIDE_MIN_BID.toFixed(2)} samePersist=${Number(stAny.__hcFallbackSameSideStreak || 0)}/${HC_SAME_SIDE_PERSISTENCE_TICKS} ` +
          `limit=${fallbackLimitPx.toFixed(2)}`
        );
      }
    } else {
      stAny.__hcFallbackSameSideStreak = 0;
      stAny.__hcFallbackSameSideNeedsRearmBelowEntry = false;
      stAny.__hcFallbackSameSideRearmedBelowEntry = false;
      stAny.__hcFallbackSameSideRearmSlug = null;
      stAny.__hcFallbackSameSideRearmSide = null;
    }
  }
  }
  // Server-side HC stop guard: only for HC opposite-side positions.
  // Same-side HC stop behavior remains strategy-driven.
  if (engine === "paper" && lane === "NO_CROSS_WINNER" && !deriskModeActive) {
    const stAny = st as any;
    const hcSubtype = String(st.entrySubtype ?? st.pendingEntrySubtype ?? "HC_OPPOSITE").toUpperCase();
    const isOpposite = hcSubtype === "HC_OPPOSITE";
    if (st.entered && !st.exited && (st.side === "UP" || st.side === "DOWN") && isOpposite) {
      const hcSideBid = inferSideBid(st.side as OutcomeSide, upBA, dnBA);
      const bid = Number(hcSideBid);
      if (Number.isFinite(bid)) {
        let kx = Number(stAny.__hcOppStopKalmanX);
        let kp = Number(stAny.__hcOppStopKalmanP);
        const kPrev = Number(stAny.__hcOppStopKalmanPrev);
        if (!Number.isFinite(kx)) {
          kx = bid;
          kp = 1;
        } else {
          kp = (Number.isFinite(kp) ? kp : 1) + HC_OPP_STOP_KALMAN_Q;
          const gain = kp / (kp + HC_OPP_STOP_KALMAN_R);
          kx = kx + gain * (bid - kx);
          kp = (1 - gain) * kp;
        }
        const kSlope = Number.isFinite(kPrev) ? (kx - kPrev) : 0;
        stAny.__hcOppStopKalmanX = kx;
        stAny.__hcOppStopKalmanP = kp;
        stAny.__hcOppStopKalmanPrev = kx;

        if (bid <= HC_OPP_STOP_HARD_FAILSAFE_PX && !(action && action.exit)) {
          action = {
            ...(action || {}),
            exit: {
              type: "STOP",
              side: st.side as OutcomeSide,
              exitPx: HC_OPP_STOP_HARD_FAILSAFE_PX,
              stopSource: "HC_OPP_SERVER_FILTER",
              stopReason: "HC_OPP_HARD_FAILSAFE",
              stopMeta: {
                lane,
                hcSubtype,
                armed: Boolean(stAny.__hcOppStopArmed),
                bid,
                thr: HC_OPP_STOP_THR,
                hardFailPx: HC_OPP_STOP_HARD_FAILSAFE_PX,
                rawStreak: Number(stAny.__hcOppStopRawStreak || 0),
                rawNeed: HC_OPP_STOP_RAW_CONFIRM_TICKS,
                kalStreak: Number(stAny.__hcOppStopKalmanStreak || 0),
                kalNeed: HC_OPP_STOP_KALMAN_CONFIRM_TICKS,
                kalmanPx: kx,
                kalmanSlope: kSlope,
                elapsedSec,
              },
            },
          };
          console.log(
            `[HC SERVER STOP FAILSAFE] lane=${lane} slug=${current.slug} side=${st.side} ` +
              `bid=${bid.toFixed(3)} hard=${HC_OPP_STOP_HARD_FAILSAFE_PX.toFixed(3)}`
          );
        } else {
          if (!stAny.__hcOppStopArmed && bid <= HC_OPP_STOP_HYST_ARM_PX) stAny.__hcOppStopArmed = true;
          if (stAny.__hcOppStopArmed && bid >= HC_OPP_STOP_HYST_DISARM_PX) {
            stAny.__hcOppStopArmed = false;
            stAny.__hcOppStopRawStreak = 0;
            stAny.__hcOppStopKalmanStreak = 0;
          }

          if (stAny.__hcOppStopArmed && bid <= HC_OPP_STOP_THR) {
            stAny.__hcOppStopRawStreak = Number(stAny.__hcOppStopRawStreak || 0) + 1;
          } else {
            stAny.__hcOppStopRawStreak = 0;
          }
          if (stAny.__hcOppStopArmed && kx <= HC_OPP_STOP_THR && kSlope <= 0) {
            stAny.__hcOppStopKalmanStreak = Number(stAny.__hcOppStopKalmanStreak || 0) + 1;
          } else {
            stAny.__hcOppStopKalmanStreak = 0;
          }

          const earlyExtra = Number.isFinite(elapsedSec) && Number(elapsedSec) < HC_OPP_STOP_EARLY_SEC
            ? HC_OPP_STOP_EARLY_EXTRA_TICKS
            : 0;
          const rawNeed = HC_OPP_STOP_RAW_CONFIRM_TICKS + earlyExtra;
          const kalNeed = HC_OPP_STOP_KALMAN_CONFIRM_TICKS + earlyExtra;
          const rawStreak = Number(stAny.__hcOppStopRawStreak || 0);
          const kalStreak = Number(stAny.__hcOppStopKalmanStreak || 0);
          if (rawStreak >= rawNeed && kalStreak >= kalNeed && !(action && action.exit)) {
            action = {
              ...(action || {}),
              exit: {
                type: "STOP",
                side: st.side as OutcomeSide,
                exitPx: HC_OPP_STOP_THR,
                stopSource: "HC_OPP_SERVER_FILTER",
                stopReason: "HC_OPP_FILTER_CONFIRM",
                stopMeta: {
                  lane,
                  hcSubtype,
                  armed: Boolean(stAny.__hcOppStopArmed),
                  bid,
                  thr: HC_OPP_STOP_THR,
                  hardFailPx: HC_OPP_STOP_HARD_FAILSAFE_PX,
                  rawStreak,
                  rawNeed,
                  kalStreak,
                  kalNeed,
                  kalmanPx: kx,
                  kalmanSlope: kSlope,
                  elapsedSec,
                },
              },
            };
            console.log(
              `[HC SERVER STOP] lane=${lane} slug=${current.slug} side=${st.side} subtype=${hcSubtype} ` +
                `bid=${bid.toFixed(3)} kf=${kx.toFixed(3)} slope=${kSlope.toFixed(5)} ` +
                `thr=${HC_OPP_STOP_THR.toFixed(3)} raw=${rawStreak}/${rawNeed} kal=${kalStreak}/${kalNeed}`
            );
          }
        }
      } else {
        stAny.__hcOppStopRawStreak = 0;
        stAny.__hcOppStopKalmanStreak = 0;
      }
    } else {
      stAny.__hcServerStopStreak = 0;
      stAny.__hcOppStopRawStreak = 0;
      stAny.__hcOppStopKalmanStreak = 0;
      stAny.__hcOppStopArmed = false;
      stAny.__hcOppStopKalmanX = NaN;
      stAny.__hcOppStopKalmanP = NaN;
      stAny.__hcOppStopKalmanPrev = NaN;
    }
  }
  // DEBUG: log strategy decisions (throttled)
if ((st as any).__lastStratLogMs == null) (st as any).__lastStratLogMs = 0;
const _n = nowMs();
if (_n - (st as any).__lastStratLogMs > 1000) {
  console.log(
    `[STRAT OUT] engine=${engine}${laneTag} entered=${st.entered} exited=${st.exited} side=${st.side} ` +
    `elapsed=${elapsedSec.toFixed(2)} up=${upBid} down=${dnBid} action=${JSON.stringify(action)}`
  );
  (st as any).__lastStratLogMs = _n;
}

  // LIVE fallback: if BASE entry missed/unfilled, allow/promote opposite-side HC entry
  // once opposite lead is strong enough.
  if (
    engine === "live" &&
    allowMomentumFallbackEntry &&
    !deriskModeActive &&
    !st.entered &&
    !st.exited &&
    !st.enterInFlight &&
    Boolean((st as any).__baseMissForHc)
  ) {
    const missAtMs = Number((st as any).__baseMissAtMs ?? 0);
    const missSide = String((st as any).__baseMissSide ?? "").toUpperCase();
    const missTooOld = Number.isFinite(missAtMs) && missAtMs > 0 && nowMs() - missAtMs > 120_000;
    if (missTooOld || (missSide !== "UP" && missSide !== "DOWN")) {
      (st as any).__baseMissForHc = false;
      (st as any).__baseMissAtMs = null;
      (st as any).__baseMissSide = null;
    } else {
      const sec = Number(elapsedSec);
      const nearClose = Number.isFinite(sec) && sec >= (300 - HC_BLOCK_LAST_SEC);
      const oppositeSide: OutcomeSide = missSide === "UP" ? "DOWN" : "UP";
      const oppositeBid = inferSideBid(oppositeSide, upBA, dnBA);
      const existingEnterMode = String(action?.enter?.mode || "").toUpperCase();
      const canPromote = !action?.enter || existingEnterMode === "BASE";
      if (!nearClose && canPromote && Number.isFinite(Number(oppositeBid)) && Number(oppositeBid) >= HC_OPPOSITE_MIN_BID) {
        const hcLimitPx = clamp01(Math.min(0.9, Number(oppositeBid) + 0.03));
        action = {
          ...(action || {}),
          enter: {
            side: oppositeSide,
            entryPx: Number(oppositeBid),
            limitPx: hcLimitPx,
            ttlMs: LIVE_BUY_TTL_MS,
            mode: "NO_CROSS_WINNER",
            hcSubtype: "HC_OPPOSITE",
          },
        };
        console.log(
          `[LIVE HC FALLBACK] slug=${current.slug} reason=base_entry_unfilled ` +
            `missSide=${missSide} hcSide=${oppositeSide} bid=${Number(oppositeBid).toFixed(2)} ` +
            `thr=${HC_OPPOSITE_MIN_BID.toFixed(2)} limit=${hcLimitPx.toFixed(2)}`
        );
      }
    }
  }

  if (engine === "paper" && st.enterInFlight && !st.entered) {
    const pendingSide = st.pendingEntrySide as OutcomeSide | null;
    const pendingLimitPx = Number(st.pendingEntryLimitPx);
    const now = nowMs();
    const expiresAt = Number(st.pendingEntryExpiresAtMs ?? 0);
    const sideBid = pendingSide ? inferSideBid(pendingSide, upBA, dnBA) : null;

    const pendingTtlMsRaw = Number(st.pendingEntryExpiresAtMs ?? 0) - Number(st.pendingEntryPlacedAtMs ?? 0);
    const pendingTtlMs = Number.isFinite(pendingTtlMsRaw) && pendingTtlMsRaw > 0 ? pendingTtlMsRaw : LIVE_BUY_TTL_MS;
    const pendingPlacedAt = Number(st.pendingEntryPlacedAtMs ?? 0);
    const pendingMode = String(st.pendingEntryMode || "").toUpperCase();

    // Adaptive HC entry repricing for second-path opposite entries.
    // Reprice schedule uses equally-spaced checkpoints across TTL.
    if (
      pendingMode === "NO_CROSS_WINNER" &&
      !deriskModeActive &&
      pendingSide &&
      Number.isFinite(pendingPlacedAt) &&
      Number.isFinite(expiresAt) &&
      pendingPlacedAt > 0 &&
      expiresAt > pendingPlacedAt &&
      HC_ENTRY_REPRICE_OFFSETS.length > 0
    ) {
      const baseLimitRaw = Number(st.pendingEntryBaseLimitPx);
      const baseLimit = Number.isFinite(baseLimitRaw) && baseLimitRaw > 0 ? baseLimitRaw : Number(st.pendingEntryLimitPx);
      const ttlMs = Math.max(1, expiresAt - pendingPlacedAt);
      const elapsedMs = Math.max(0, now - pendingPlacedAt);
      let desiredRepriceCount = 0;
      for (let i = 0; i < HC_ENTRY_REPRICE_OFFSETS.length; i++) {
        const triggerMs = ((i + 1) / (HC_ENTRY_REPRICE_OFFSETS.length + 1)) * ttlMs;
        if (elapsedMs >= triggerMs) desiredRepriceCount = i + 1;
      }
      const currentRepriceCount = Math.max(0, Math.floor(Number(st.pendingEntryRepriceCount ?? 0)));
      if (desiredRepriceCount > currentRepriceCount && Number.isFinite(baseLimit) && baseLimit > 0) {
        const nextRepriceCount = Math.min(desiredRepriceCount, HC_ENTRY_REPRICE_OFFSETS.length);
        const oldLimitPx = Number(st.pendingEntryLimitPx);
        const offset = HC_ENTRY_REPRICE_OFFSETS[nextRepriceCount - 1];
        const nextLimitPx = clamp01(Math.min(HC_ENTRY_REPRICE_CAP_PX, baseLimit + offset));
        if (Number.isFinite(nextLimitPx) && nextLimitPx > 0 && (!Number.isFinite(oldLimitPx) || nextLimitPx > oldLimitPx + 1e-9)) {
          st.pendingEntryLimitPx = nextLimitPx;
          st.pendingEntryRepriceCount = nextRepriceCount;
          emitTradeScoped(`ENTER_REPRICE_${pendingSide}_PAPER`, {
            phase: "entry_reprice",
            via: "adaptive_hc_reprice",
            mode: st.pendingEntryMode ?? null,
            signalPx: st.pendingEntrySignalPx,
            signalThresholdPx: ui.entry,
            oldLimitPx: Number.isFinite(oldLimitPx) ? oldLimitPx : null,
            buyOrderPx: nextLimitPx,
            limitPx: nextLimitPx,
            ttlMs: pendingTtlMs,
            repriceCount: nextRepriceCount,
            repriceOffsetPx: offset,
            repriceCapPx: HC_ENTRY_REPRICE_CAP_PX,
          });
        }
      }
    }

    if (Number.isFinite(expiresAt) && now > expiresAt) {
      // Entry TTL fallback: if resting limit did not fill within TTL, execute
      // immediate market buy at current side bid (exchange-style trigger+fallback).
      const mktPx = Number(sideBid);
      const entryCapPx = activeEntryPriceCapPx();
      const capBreached =
        Number.isFinite(Number(entryCapPx)) &&
        Number(entryCapPx) > 0 &&
        Number.isFinite(mktPx) &&
        mktPx > Number(entryCapPx) + 1e-9;
      const hasFallbackFill =
        !!pendingSide &&
        Number.isFinite(mktPx) &&
        mktPx > 0 &&
        !capBreached &&
        Number.isFinite(Number(st.pendingEntryNotionalUsd)) &&
        Number(st.pendingEntryNotionalUsd) > 0;
      if (hasFallbackFill) {
        const fillPx = mktPx;
        const notionalUsd = Number(st.pendingEntryNotionalUsd ?? 0);
        st.entered = true;
        st.exited = false;
        st.side = pendingSide as OutcomeSide;
        st.entryTsMs = now;
        st.entryPx = fillPx;
        st.notionalUsd = notionalUsd;
        // Pending paper entries in this path are exchange-style fallback buys; charge entry taker fees
        // and reduce bought shares from the fixed cash budget accordingly.
        st.shares = Number(computeEntryFromBudgetUsd(notionalUsd, fillPx, "taker").shares ?? 0);
        resetPaperDeriskExecutionState(st);
        st.entryMode = st.pendingEntryMode ?? null;
        st.entrySubtype = st.pendingEntrySubtype ?? null;
        st.buyAttemptedSessionSlug = current.slug;
        st.buyAttemptedThisSession = true;
        st.buyFilledThisSession = true;
        applyEntryFeeAccounting(st, fillPx, Number(st.shares ?? 0), "taker", notionalUsd);
        initPositionAccountingOnEntry(st, notionalUsd);
        if (pendingSide === "UP" || pendingSide === "DOWN") {
          paperEnteredSidesThisSession.add(pendingSide);
        }
        st.balanceUsd = paperAccount.balanceUsd;
        finalizeEntryLatency(st, now, {
          via: "entry_ttl_market_fallback",
          signalPx: Number(st.pendingEntrySignalPx ?? NaN),
          fillPx,
        });
        emitTradeScoped(`ENTER_${pendingSide}_PAPER`, {
          via: "entry_ttl_market_fallback",
          mode: st.pendingEntryMode ?? null,
          hcSubtype: st.pendingEntrySubtype ?? null,
          signalPx: st.pendingEntrySignalPx,
          signalThresholdPx: ui.entry,
          buyOrderPx: st.pendingEntryLimitPx,
          limitPx: st.pendingEntryLimitPx,
          fillPx,
          actualFillPx: fillPx,
          ttlMs: Number.isFinite(pendingTtlMs) ? pendingTtlMs : null,
          slippageFromSignalPx:
            Number.isFinite(Number(st.pendingEntrySignalPx)) ? fillPx - Number(st.pendingEntrySignalPx) : null,
          slippageFromThresholdPx: fillPx - ui.entry,
        });
        if (isDeriskLaneMode(String(st.pendingEntryMode ?? lane ?? ""))) {
          const deriskPx = Number(DERISK_STRICT_DERISK_THR);
          const deriskShares = computeDeriskSharesFromState(deriskPx);
          armPaperTpOrder(pendingSide as OutcomeSide, fillPx, deriskShares, "DERISK", deriskPx, true);
        } else {
          armPaperTpOrder(pendingSide as OutcomeSide, fillPx);
        }
        clearPendingStop(st);
        st.pendingStopShares = Number(st.shares ?? 0);
        if (engine === "paper" && lane) lockPaperSessionLane(lane, "open");
        clearPendingEntry(st);
      } else {
        emitTradeScoped(`ENTER_CANCEL_${pendingSide ?? "UP"}_PAPER`, {
          via: "strategy",
          reason: capBreached ? "ttl_expired_cap_breached" : "ttl_expired",
          signalPx: st.pendingEntrySignalPx,
          signalThresholdPx: ui.entry,
          buyOrderPx: st.pendingEntryLimitPx,
          limitPx: st.pendingEntryLimitPx,
          marketPx: Number.isFinite(mktPx) ? mktPx : null,
          entryCapPx: Number.isFinite(Number(entryCapPx)) ? Number(entryCapPx) : null,
          ttlMs: pendingTtlMs,
        });
        if (engine === "paper" && lane) unlockPaperSessionLane(lane);
        clearEntryLatency(st);
        clearPendingEntry(st);
      }
    } else if (
      pendingSide &&
      Number.isFinite(pendingLimitPx) &&
      Number.isFinite(Number(sideBid)) &&
      Number(sideBid) <= pendingLimitPx
    ) {
      // Buy limit semantics: only fill at or below the posted buy limit.
      const fillPx = Number(sideBid);
      const notionalUsd = Number(st.pendingEntryNotionalUsd ?? 0);
      st.entered = true;
      st.exited = false;
      st.side = pendingSide;
      st.entryTsMs = now;
      st.entryPx = fillPx;
      st.notionalUsd = notionalUsd;
      // Pending paper limit fills should still consume the entry fee from the budget so the
      // acquired share count matches the engine's cash accounting.
      st.shares = Number(computeEntryFromBudgetUsd(notionalUsd, fillPx, "taker").shares ?? 0);
      resetPaperDeriskExecutionState(st);
      st.entryMode = st.pendingEntryMode ?? null;
      st.entrySubtype = st.pendingEntrySubtype ?? null;
      st.buyAttemptedSessionSlug = current.slug;
      st.buyAttemptedThisSession = true;
      st.buyFilledThisSession = true;
      applyEntryFeeAccounting(st, fillPx, Number(st.shares ?? 0), "taker", notionalUsd);
      initPositionAccountingOnEntry(st, notionalUsd);
      if (pendingSide === "UP" || pendingSide === "DOWN") {
        paperEnteredSidesThisSession.add(pendingSide);
      }
      st.balanceUsd = paperAccount.balanceUsd;
      finalizeEntryLatency(st, now, {
        via: "entry_limit_fill",
        signalPx: Number(st.pendingEntrySignalPx ?? NaN),
        fillPx,
      });

      emitTradeScoped(`ENTER_${pendingSide}_PAPER`, {
        via: "strategy",
        mode: st.pendingEntryMode ?? null,
        hcSubtype: st.pendingEntrySubtype ?? null,
        signalPx: st.pendingEntrySignalPx,
        signalThresholdPx: ui.entry,
        buyOrderPx: st.pendingEntryLimitPx,
        limitPx: st.pendingEntryLimitPx,
        fillPx,
        actualFillPx: fillPx,
        slippageFromSignalPx:
          Number.isFinite(Number(st.pendingEntrySignalPx)) ? fillPx - Number(st.pendingEntrySignalPx) : null,
        slippageFromThresholdPx: fillPx - ui.entry,
      });
      if (isDeriskLaneMode(String(st.pendingEntryMode ?? lane ?? ""))) {
        const deriskPx = Number(DERISK_STRICT_DERISK_THR);
        const deriskShares = computeDeriskSharesFromState(deriskPx);
        armPaperTpOrder(pendingSide, fillPx, deriskShares, "DERISK", deriskPx, true);
      } else {
        armPaperTpOrder(pendingSide, fillPx);
      }
      clearPendingStop(st);
      st.pendingStopShares = Number(st.shares ?? 0);
      if (engine === "paper" && lane) lockPaperSessionLane(lane, "open");
      clearPendingEntry(st);
    }
  }

  if (
    engine === "paper" &&
    st.entered &&
    !st.exited &&
    (st.side === "UP" || st.side === "DOWN") &&
    Number.isFinite(Number(st.pendingTpLimitPx)) &&
    Number(st.pendingTpLimitPx) > 0 &&
    Number.isFinite(Number(st.shares)) &&
    Number(st.shares) > 0
  ) {
    const side = st.side as OutcomeSide;
    const sideBid = inferSideBid(side, upBA, dnBA);
    const tpLimitPx = Number(st.pendingTpLimitPx);
    if (Number.isFinite(Number(sideBid)) && Number(sideBid) >= tpLimitPx) {
      const currentShares = Number(st.shares);
      const requiredSharesRaw = Number(st.pendingTpShares);
      const requiredShares = Number.isFinite(requiredSharesRaw)
        ? Math.max(0, Math.min(currentShares, requiredSharesRaw))
        : currentShares;
      const pendingExitTypeRaw = String(st.pendingTpExitType || "EXIT").toUpperCase();
      if (
        isSinglePartialExitTypeRaw(pendingExitTypeRaw) &&
        paperSinglePartialCompletedForCurrentPosition(st, side)
      ) {
        clearPendingTp(st);
        return;
      }
      const fillLockId = [
        String(current.slug || ""),
        side,
        pendingExitTypeRaw,
        roundTo6(tpLimitPx),
        roundTo6(currentShares),
        roundTo6(requiredShares),
        roundTo6(Number(st.entryTsMs ?? 0)),
      ].join(":");
      if (String(st.pendingTpFillLockId || "") === fillLockId) {
        return;
      }
      st.pendingTpFillLockId = fillLockId;
      try {
        if (!(requiredShares > 0)) {
          clearPendingTp(st);
          return;
        }
        // Paper resting limit semantics: once touched, assume posted limit fills.
        if (true) {
          // Resting paper limit semantics: once touched, assume maker fill at the
          // posted limit price (not at the overshoot tick price).
          const fillPx = clamp01(tpLimitPx);
          if (pendingExitTypeRaw === "DERISK") {
            const sharesTol = 1e-6;
            const armedPositionShares = Number(st.pendingTpArmedPositionShares);
            const deriskAlreadyCompletedForPosition =
              String(st.paperDeriskCompletedSessionSlug || "") === String(current.slug || "") &&
              String(st.paperDeriskCompletedSide || "").toUpperCase() === String(side || "").toUpperCase() &&
              Number.isFinite(Number(st.paperDeriskCompletedEntryTsMs)) &&
              Number.isFinite(Number(st.entryTsMs)) &&
              Math.abs(Number(st.paperDeriskCompletedEntryTsMs) - Number(st.entryTsMs)) <= 1;
            const staleOrOverfilledDeriskOrder =
              !Number.isFinite(armedPositionShares) ||
              !(armedPositionShares > 0) ||
              currentShares < armedPositionShares - sharesTol ||
              requiredShares > armedPositionShares + sharesTol ||
              requiredShares >= currentShares - sharesTol;
            if (deriskAlreadyCompletedForPosition || staleOrOverfilledDeriskOrder) {
              clearPendingTp(st);
              return;
            }
          }
          const leg = applyPaperSellLegAccounting(st, fillPx, requiredShares, "maker");
          st.exitTsMs = nowMs();
          st.exitPx = fillPx;
          st.stopFallbackTriggered = false;
          const isFullClose = Number(leg.remainingShares) <= 1e-6;
          st.exited = isFullClose;
          if (!isFullClose) st.entered = true;
          const pnlUsd = Number(leg.legPnlUsd ?? 0);
          clearPendingTp(st);
          if (isFullClose) clearPendingStop(st);
          else st.pendingStopShares = Number(leg.remainingShares ?? 0);
          st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;
          paperAccount.balanceUsd += pnlUsd;
          st.balanceUsd = paperAccount.balanceUsd;
          const exitType = pendingExitTypeRaw;
          finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
            via: "tp_limit_order",
            exitType,
            fillPx,
            signalPx: Number(sideBid ?? NaN),
          });
          emitTradeScoped(`EXIT_${side}_PAPER`, {
            via: "tp_limit_order",
            exitType,
            signalPx: Number(sideBid),
            targetSellPx: tpLimitPx,
            limitPx: tpLimitPx,
            fillPx,
            actualFillPx: fillPx,
            soldShares: requiredShares,
            remainingShares: leg.remainingShares,
            partial: !isFullClose,
            legPnlUsd: pnlUsd,
          });
          if (!isFullClose && isSinglePartialExitTypeRaw(exitType)) {
            markPaperSinglePartialCompleted(st, side);
          }
          // Derisk chain: immediately place runner TP at .96 for remaining shares.
          if (!isFullClose && exitType === "DERISK") {
            st.paperDeriskCompletedSessionSlug = String(current.slug || "");
            st.paperDeriskCompletedSide = side;
            st.paperDeriskCompletedEntryTsMs = Number(st.entryTsMs ?? nowMs());
            const remaining = Number(leg.remainingShares ?? 0);
            if (remaining > 1e-6) {
              armPaperTpOrder(side, fillPx, remaining, "EXIT", Number(ui.exit));
            }
          }
          if (isFullClose && lane) unlockPaperSessionLane(lane);
          if (isFullClose && lane === "BASE") {
            rearmPaperLaneStrategy("NO_CROSS_WINNER", "base_exited_rearm_hc_second_path");
          }
          return;
        }
      } finally {
        if (String(st.pendingTpFillLockId || "") === fillLockId) {
          st.pendingTpFillLockId = null;
        }
      }
    }
  }

  // Resting paper stop: trigger at stop threshold, place a 300ms limit at stop,
  // then fall back to market (current bid) if still unfilled.
  if (
    engine === "paper" &&
    st.entered &&
    !st.exited &&
    (st.side === "UP" || st.side === "DOWN") &&
    Number.isFinite(Number(st.shares)) &&
    Number(st.shares) > 0
  ) {
    const side = st.side as OutcomeSide;
    const sideBid = inferSideBid(side, upBA, dnBA);
    const hasStrategyStop = !!action?.exit && String(action?.exit?.type || "").toUpperCase().includes("STOP");
    const activeDeriskStopThr =
      String(st.pendingTpExitType || "").toUpperCase() === "EXIT"
        ? Number(DERISK_STRICT_RUNNER_STOP_THR)
        : Number(DERISK_STRICT_STOP_THR);
    const deriskStopTouched =
      deriskModeActive &&
      Number.isFinite(Number(sideBid)) &&
      Number.isFinite(activeDeriskStopThr) &&
      Number(sideBid) <= activeDeriskStopThr;
    const stopTouched =
      !deriskModeActive &&
      !hasStrategyStop &&
      Number.isFinite(Number(sideBid)) &&
      shouldTriggerStop(ui, side, Number(sideBid), elapsedSec, engine, "resting_stop");
    const stopArmed =
      Number.isFinite(Number(st.pendingStopPlacedAtMs)) &&
      Number.isFinite(Number(st.pendingStopLimitPx)) &&
      Number(st.pendingStopLimitPx) > 0;
    if (deriskStopTouched) {
      const reqShares = Math.max(0, Number(st.shares ?? 0));
      if (reqShares > 0) {
        const fillPx = Number.isFinite(Number(sideBid)) ? Number(sideBid) : activeDeriskStopThr;
        markExitSignalLatency(st, engine, side, lane ?? null, "paper_derisk_resting_stop", "STOP");
        markExitSubmitLatency(st);
        const leg = applyPaperSellLegAccounting(st, fillPx, reqShares, "taker");
        const isFullClose = Number(leg.remainingShares) <= 1e-6;
        st.exited = isFullClose;
        st.exitTsMs = nowMs();
        st.exitPx = fillPx;
        st.stopFallbackTriggered = true;
        st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;
        if (!isFullClose) st.entered = true;
        clearPendingTp(st);
        clearPendingStop(st);
        const pnlUsd = Number(leg.legPnlUsd ?? 0);
        paperAccount.balanceUsd += pnlUsd;
        st.balanceUsd = paperAccount.balanceUsd;
        finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
          via: "derisk_market_stop",
          exitType: "STOP",
          fillPx,
          signalPx: Number(sideBid ?? NaN),
        });
        emitTradeScoped(`STOP_${side}_PAPER`, {
          via: "derisk_market_stop",
          exitType: "STOP",
          stopReason: "RESTING_STOP_THRESHOLD",
          stopSource: "RESTING_STOP",
          orderType: "MARKET",
          soldShares: Number(leg.soldShares ?? reqShares),
          remainingShares: Number(leg.remainingShares ?? 0),
          partial: !isFullClose,
          legPnlUsd: pnlUsd,
          signalPx: Number(sideBid),
          targetSellPx: activeDeriskStopThr,
          fillPx,
          actualFillPx: fillPx,
        });
        if (lane === "BASE" && isFullClose) {
          (st as any).__stoppedThisSession = true;
        }
        if (isFullClose && lane) unlockPaperSessionLane(lane);
        if (isFullClose && lane === "BASE") {
          rearmPaperLaneStrategy("NO_CROSS_WINNER", "base_exited_rearm_hc_second_path");
        }
        return;
      }
    }
    if (deriskModeActive) {
      // Derisk mode intentionally bypasses maker-first TTL stop slices.
      return;
    }
    if (stopTouched && !stopArmed) {
      const nowStop = nowMs();
      const stopLimitPx = clamp01(Number(ui.stop));
      st.pendingStopLimitPx = stopLimitPx;
      st.pendingStopPlacedAtMs = nowStop;
      st.pendingStopExpiresAtMs = nowStop + STOP_INITIAL_SLICE_TTL_MS;
      st.pendingStopShares = Math.max(0, Number(st.shares ?? 0));
      st.pendingStopOrderId = `paper-stop-${current.slug}-${side}-${nowStop}`;
      markExitSignalLatency(st, engine, side, lane ?? null, "paper_resting_stop_order", "STOP");
      markExitSubmitLatency(st);
      const fillCapacityEstimate =
        shouldTrackPaperFillCapacity(engine)
          ? await estimateFillCapacitySnapshot(tokenIdForSide(side), "sell", stopLimitPx)
          : null;
      emitTradeScoped(`STOP_ORDER_${side}_PAPER`, {
        phase: "exit_order",
        via: "resting_stop_trigger",
        exitType: "STOP",
        signalPx: Number(sideBid),
        targetSellPx: stopLimitPx,
        limitPx: stopLimitPx,
        ttlMs: STOP_INITIAL_SLICE_TTL_MS,
        orderPlacedAtMs: nowStop,
        shares: Number(st.pendingStopShares ?? 0),
        stopOrderId: st.pendingStopOrderId,
        stopReason: "RESTING_STOP_THRESHOLD",
        stopSource: "RESTING_STOP",
        fillCapacityEstimate,
      });
    }
    const stopPlacedAtMs = Number(st.pendingStopPlacedAtMs);
    const stopLimitPx = Number(st.pendingStopLimitPx);
    if (
      Number.isFinite(stopPlacedAtMs) &&
      Number.isFinite(stopLimitPx) &&
      stopLimitPx > 0 &&
      Number.isFinite(Number(sideBid))
    ) {
      const reqShares = Math.max(
        0,
        Math.min(
          Number(st.shares ?? 0),
          Number.isFinite(Number(st.pendingStopShares)) ? Number(st.pendingStopShares) : Number(st.shares ?? 0)
        )
      );
      if (!(reqShares > 0)) {
        clearPendingStop(st);
      } else {
        const expired = Number.isFinite(Number(st.pendingStopExpiresAtMs)) && nowMs() >= Number(st.pendingStopExpiresAtMs);
        const canLimitFill = Number(sideBid) >= stopLimitPx;
        if (canLimitFill || expired) {
          const fillPx = canLimitFill ? stopLimitPx : Number(sideBid);
          const leg = applyPaperSellLegAccounting(st, fillPx, reqShares, canLimitFill ? "maker" : "taker");
          const isFullClose = Number(leg.remainingShares) <= 1e-6;
          st.exited = isFullClose;
          st.exitTsMs = nowMs();
          st.exitPx = fillPx;
          st.stopFallbackTriggered = !canLimitFill;
          st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;
          if (!isFullClose) st.entered = true;
          clearPendingTp(st);
          clearPendingStop(st);
          const pnlUsd = Number(leg.legPnlUsd ?? 0);
          paperAccount.balanceUsd += pnlUsd;
          st.balanceUsd = paperAccount.balanceUsd;
          finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
            via: canLimitFill ? "resting_stop_limit" : "resting_stop_market_fallback",
            exitType: "STOP",
            fillPx,
            signalPx: Number(sideBid ?? NaN),
          });
          emitTradeScoped(`STOP_${side}_PAPER`, {
            via: canLimitFill ? "resting_stop_limit" : "resting_stop_market_fallback",
            exitType: "STOP",
            stopReason: "RESTING_STOP_THRESHOLD",
            stopSource: "RESTING_STOP",
            soldShares: Number(leg.soldShares ?? reqShares),
            remainingShares: Number(leg.remainingShares ?? 0),
            partial: !isFullClose,
            legPnlUsd: pnlUsd,
            signalPx: Number(sideBid),
            targetSellPx: stopLimitPx,
            limitPx: stopLimitPx,
            fillPx,
            actualFillPx: fillPx,
            ttlMs: STOP_INITIAL_SLICE_TTL_MS,
          });
          if (lane === "BASE" && isFullClose) {
            (st as any).__stoppedThisSession = true;
          }
          if (isFullClose && lane) unlockPaperSessionLane(lane);
          if (isFullClose && lane === "BASE") {
            rearmPaperLaneStrategy("NO_CROSS_WINNER", "base_exited_rearm_hc_second_path");
          }
          return;
        }
      }
    }
  }

  if (!action) return;

  const hasOpenOrClosingPosition =
    !!st.entered ||
    !!st.exitInFlight ||
    (!!Number.isFinite(Number(st.shares)) && Number(st.shares) > 0) ||
    (!!st.positionTokenId && String(st.positionTokenId).trim().length > 0) ||
    (
      Number.isFinite(Number(st.entryTsMs)) &&
      !Number.isFinite(Number(st.exitTsMs))
    );

  // ===== ENTER =====
  if (action.enter && !st.entered && !st.exited && !st.enterInFlight) {
    const candidateSide = action.enter.side as OutcomeSide;
    // Hard invariant: never place a new entry while any prior position is still
    // open or currently exiting. This prevents BASE->HC overlap.
    if (hasOpenOrClosingPosition) {
      if (engine === "paper" && lane) {
        rearmPaperLaneStrategy(lane, "blocked_open_or_closing_position");
      }
      if (engine === "live" && shouldEmitEntryBlockedEvent(st, candidateSide, "OPEN_OR_CLOSING_POSITION")) {
        emitTradeScoped(`ENTER_BLOCKED_${candidateSide}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: Number.isFinite(Number(action?.enter?.entryPx)) ? Number(action?.enter?.entryPx) : null,
          signalThresholdPx: ui.entry,
          entryBlockCode: "OPEN_OR_CLOSING_POSITION",
          entryBlockReason: "OPEN_OR_CLOSING_POSITION",
          entryBlockMeta: {
            entered: !!st.entered,
            exitInFlight: !!st.exitInFlight,
            shares: Number(st.shares ?? 0),
            positionTokenId: st.positionTokenId ?? null,
            entryTsMs: st.entryTsMs ?? null,
            exitTsMs: st.exitTsMs ?? null,
          },
        });
      }
      return;
    }
    if (
      String(action?.enter?.mode || "").toUpperCase() === "NO_CROSS_WINNER" &&
      !(engine === "paper" && strategyAllowsDualLaneEntries(String(action?.enter?.mode || "")))
    ) {
      const sec = Number(elapsedSec);
      if (Number.isFinite(sec) && sec >= (300 - HC_BLOCK_LAST_SEC)) {
        if (engine === "paper" && lane) rearmPaperLaneStrategy(lane, "blocked_hc_last2s");
        return;
      }
    }
    const dualLaneModeHint =
      String(action?.enter?.mode || st?.pendingEntryMode || st?.entryMode || "").trim() || null;
    const dualLaneAllowedForStrategy = engine === "paper" && strategyAllowsDualLaneEntries(dualLaneModeHint);
    if (engine === "paper" && lane && dualLaneAllowedForStrategy && !!st.buyFilledThisSession) {
      rearmPaperLaneStrategy(lane, "blocked_lane_already_entered_this_session");
      emitTradeScoped(`ENTER_BLOCKED_${candidateSide}_PAPER`, {
        via: "strategy",
        mode: action?.enter?.mode ?? null,
        hcSubtype: action?.enter?.hcSubtype ?? null,
        signalPx: Number.isFinite(Number(action?.enter?.entryPx)) ? Number(action?.enter?.entryPx) : null,
        signalThresholdPx: ui.entry,
        entryBlockCode: "LANE_ALREADY_ENTERED_THIS_SESSION",
        entryBlockReason: "LANE_ALREADY_ENTERED_THIS_SESSION",
        entryBlockMeta: { slug: current.slug, lane, engine: "paper" },
      });
      return;
    }
    // Prevent simultaneous dual-lane entries in a single tick/session unless
    // strategy explicitly supports dual-lane trading (derisk profile).
    if (engine === "paper" && lane && !dualLaneAllowedForStrategy) {
      // Hard invariant: if any other lane is pending/open, this lane cannot enter.
      if (hasOtherPaperLanePendingOrOpen(lane)) {
        rearmPaperLaneStrategy(lane, "blocked_other_lane_pending_or_open");
        return;
      }
      if (isPaperSessionLockedForLane(lane)) {
        rearmPaperLaneStrategy(lane, "blocked_session_lock");
        return;
      }
      const baseLane = paperLaneStates.BASE;
      const hcLane = paperLaneStates.NO_CROSS_WINNER;
      if (lane === "NO_CROSS_WINNER") {
        const baseActive =
          !!baseLane &&
          ((baseLane.enterInFlight && !baseLane.entered) || (baseLane.entered && !baseLane.exited));
        if (baseActive) {
          // HC second path is allowed only after momentum is fully off.
          rearmPaperLaneStrategy(lane, "blocked_base_active_wait_for_exit");
          return;
        }
      } else if (lane === "BASE") {
        const baseStoppedThisSession = !!(baseLane as any)?.__stoppedThisSession;
        if (baseStoppedThisSession) {
          rearmPaperLaneStrategy(lane, "blocked_base_reentry_wait_hc_after_stop");
          return;
        }
        const hcEverEntered = !!hcLane && !!hcLane.entered;
        if (hcEverEntered) return; // If HC got in first, momentum stays off this session.
        const hcActive =
          !!hcLane &&
          ((hcLane.enterInFlight && !hcLane.entered) || (hcLane.entered && !hcLane.exited));
        if (hcActive) return;
      }
    }
    const side = action.enter.side;
    const enforcePerSideSessionLock = strategyAllowsDualLaneEntries(dualLaneModeHint);
    if (enforcePerSideSessionLock && engine === "paper" && paperEnteredSidesThisSession.has(side)) {
      if (lane) rearmPaperLaneStrategy(lane, "blocked_side_already_entered_this_session");
      emitTradeScoped(`ENTER_BLOCKED_${side}_PAPER`, {
        via: "strategy",
        mode: action?.enter?.mode ?? null,
        hcSubtype: action?.enter?.hcSubtype ?? null,
        signalPx: Number.isFinite(Number(action?.enter?.entryPx)) ? Number(action?.enter?.entryPx) : null,
        signalThresholdPx: ui.entry,
        entryBlockCode: "SIDE_ALREADY_ENTERED_THIS_SESSION",
        entryBlockReason: "SIDE_ALREADY_ENTERED_THIS_SESSION",
        entryBlockMeta: { slug: current.slug, side, engine: "paper" },
      });
      return;
    }
    if (engine === "paper" && lane && dualLaneAllowedForStrategy) {
      // Derisk dual-lane invariant: allow UP+DOWN concurrently, but never the
      // same side twice across lanes in one session/tick window.
      if (hasOtherPaperLaneSameSidePendingOrOpen(lane, side)) {
        rearmPaperLaneStrategy(lane, "blocked_same_side_pending_or_open");
        return;
      }
    }
    if (!isNewEntryAllowed(engine, st)) {
      if (engine === "live" && shouldEmitEntryBlockedEvent(st, side, "STARTUP_MID_SESSION_GUARD")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: Number.isFinite(Number(action?.enter?.entryPx)) ? Number(action?.enter?.entryPx) : null,
          signalThresholdPx: ui.entry,
          entryBlockCode: "STARTUP_MID_SESSION_GUARD",
          entryBlockReason: "STARTUP_MID_SESSION_GUARD",
          entryBlockMeta: {
            currentSlug: current.slug,
            blockedSessionSlug: entryBlockedSessionSlug,
            entryBlockActive,
          },
        });
      }
      return;
    }

    const entryPx = Number.isFinite(Number(action.enter.entryPx))
      ? Number(action.enter.entryPx)
      : side === "UP"
      ? upBid
      : dnBid;

    const balanceUsd = engine === "paper" ? paperAccount.balanceUsd : liveAccount.balanceUsd ?? 0;

    const dynamicNotionalUsd = calcNotionalUsd({
      balanceUsd,
      betUsd: ui.betUsd,
      maxBetUsd: ui.maxBetUsd,
      kellyOn: ui.kellyOn,
      kellyMult: ui.kellyMult,
      kellyCap: ui.kellyCap,
    });
    // Paper should always use the configured bet sizing (no Kelly override).
    const notionalUsd =
      engine === "paper"
        ? clamp(ui.betUsd, 0, Math.min(ui.maxBetUsd, balanceUsd))
        : dynamicNotionalUsd;
    if (notionalUsd <= 0) {
      if (engine === "live" && shouldEmitEntryBlockedEvent(st, side, "NON_POSITIVE_NOTIONAL")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "NON_POSITIVE_NOTIONAL",
          entryBlockReason: "NON_POSITIVE_NOTIONAL",
          entryBlockMeta: {
            notionalUsd,
            balanceUsd,
            betUsd: ui.betUsd,
            maxBetUsd: ui.maxBetUsd,
            kellyOn: !!ui.kellyOn,
          },
        });
      }
      return;
    }

    const actionLimitPxRaw = Number(action.enter.limitPx);
    const actionLimitPx = Number.isFinite(actionLimitPxRaw) ? clampEntryBuyPx(actionLimitPxRaw) : null;
    const actionRestingEntryPxRaw = Number((action.enter as any).restingEntryPx);
    const actionRestingEntryPx =
      Number.isFinite(actionRestingEntryPxRaw) && actionRestingEntryPxRaw > 0
        ? clampEntryBuyPx(actionRestingEntryPxRaw)
        : null;
    const actionEntryStyle = String((action.enter as any).entryStyle || "").trim().toUpperCase();
    const useRestingThresholdFill =
      actionEntryStyle === "RESTING_TRIGGER_LIMIT" &&
      Number.isFinite(Number(actionRestingEntryPx)) &&
      Number(actionRestingEntryPx) > 0;
    const actionOrderType = String(action?.enter?.orderType || "").trim().toUpperCase();
    const forceMarketEntry = actionOrderType === "MARKET";
    const actionEntryFeeModeRaw = String((action.enter as any).entryFeeMode || "").trim().toLowerCase();
    const actionEntryFeeMode: ExitFeeMode =
      actionEntryFeeModeRaw === "maker"
        ? "maker"
        : actionEntryFeeModeRaw === "none"
        ? "none"
        : "taker";
    const actionTtlMsRaw = Number(action.enter.ttlMs);
    const actionTtlMs = Number.isFinite(actionTtlMsRaw) && actionTtlMsRaw > 0 ? Math.floor(actionTtlMsRaw) : LIVE_BUY_TTL_MS;
    const actionNoTtl = actionEntryStyle === "RESTING_LIMIT_NO_TTL";
    const entryQuoteFreshness = engine === "live"
      ? await refreshCurrentEntryQuoteFreshness()
      : getCurrentEntryQuoteFreshness();
    if (!entryQuoteFreshness.fresh) {
      if (engine === "live" && shouldEmitEntryBlockedEvent(st, side, "ENTRY_QUOTES_STALE")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "ENTRY_QUOTES_STALE",
          entryBlockReason: "ENTRY_QUOTES_STALE",
          entryBlockMeta: {
            pairAgeMs: entryQuoteFreshness.pairAgeMs,
            upBid: entryQuoteFreshness.upBid,
            downBid: entryQuoteFreshness.downBid,
            slug: current.slug,
            retryCount: Number((entryQuoteFreshness as any)?.retryCount || 0),
          },
        });
      }
      return;
    }

    if (engine === "paper") {
      if (enforcePerSideSessionLock || forceMarketEntry) {
        const usePaperTouchFill = shouldUsePaperTouchFillForAction(action?.enter, null);
        const marketFillPx = usePaperTouchFill
          ? Number(entryPx)
          : (
            useRestingThresholdFill
              ? Number(actionRestingEntryPx)
              : (side === "UP" ? Number(upBid) : Number(dnBid))
          );
        if (!(Number.isFinite(marketFillPx) && marketFillPx > 0)) return;
        if (enforcePerSideSessionLock && !(marketFillPx < Number(DERISK_STRICT_DERISK_THR))) {
          if (lane) rearmPaperLaneStrategy(lane, "blocked_entry_at_or_above_derisk");
          emitTradeScoped(`ENTER_BLOCKED_${side}_PAPER`, {
            via: "strategy",
            mode: action?.enter?.mode ?? null,
            hcSubtype: action?.enter?.hcSubtype ?? null,
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            entryBlockCode: "ENTRY_AT_OR_ABOVE_DERISK",
            entryBlockReason: "ENTRY_AT_OR_ABOVE_DERISK",
            entryBlockMeta: {
              signalPx: Number(entryPx),
              fillPx: Number(marketFillPx),
              deriskPx: Number(DERISK_STRICT_DERISK_THR),
            },
          });
          return;
        }
        markEntrySignalLatency(st, engine, side, lane ?? null, "strategy_on_tick", Number(entryPx));
        markEntrySubmitLatency(st);
        st.entered = true;
        st.exited = false;
        st.side = side;
        st.entryTsMs = nowMs();
        st.entryPx = marketFillPx;
        st.notionalUsd = notionalUsd;
        st.shares = Number(computeEntryFromBudgetUsd(notionalUsd, marketFillPx, actionEntryFeeMode).shares ?? 0);
        resetPaperDeriskExecutionState(st);
        st.entryMode = action?.enter?.mode ?? null;
        st.entrySubtype = action?.enter?.hcSubtype ?? null;
        st.buyAttemptedSessionSlug = current.slug;
        st.buyAttemptedThisSession = true;
        st.buyFilledThisSession = true;
        applyEntryFeeAccounting(st, marketFillPx, Number(st.shares ?? 0), actionEntryFeeMode, notionalUsd);
        initPositionAccountingOnEntry(st, notionalUsd);
        st.balanceUsd = paperAccount.balanceUsd;
        if (side === "UP" || side === "DOWN") {
          paperEnteredSidesThisSession.add(side);
        }
        finalizeEntryLatency(st, nowMs(), {
          via: "strategy_market_entry",
          signalPx: Number(entryPx),
          fillPx: Number(marketFillPx),
        });
        const emitPaperEnter = async () => {
          const lagEventTsMs = Number(st.entryTsMs ?? nowMs());
          emitTradeScoped(`ENTER_${side}_PAPER`, {
            via: "strategy_market_entry",
            mode: action?.enter?.mode ?? null,
            hcSubtype: action?.enter?.hcSubtype ?? null,
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            fillPx: marketFillPx,
            actualFillPx: marketFillPx,
            orderType: "MARKET",
            fillSource: usePaperTouchFill ? "paper_touch_signal" : "paper_modeled_marketable",
            slippageFromSignalPx:
              Number.isFinite(Number(entryPx)) ? marketFillPx - Number(entryPx) : null,
            slippageFromThresholdPx: marketFillPx - ui.entry,
            fillCapacityEstimate: null,
            lagSnapshotAtEvent: currentQuoteLagSnapshotAt(lagEventTsMs),
            lagWindowBaseLookbackMs: Math.round(entryLagWindowRadiusMsForStrategy(String((strategyPaper as any)?.STRATEGY_ID || "")) / 2),
          });
          scheduleEntryLagWindowCapture(
            "paper",
            `ENTER_${side}_PAPER`,
            side,
            lagEventTsMs,
            String((strategyPaper as any)?.STRATEGY_ID || ""),
            {
              via: "strategy_market_entry",
              mode: action?.enter?.mode ?? null,
              hcSubtype: action?.enter?.hcSubtype ?? null,
              signalPx: entryPx,
              signalThresholdPx: ui.entry,
            }
          );
        };
        await emitPaperEnter();
        if (isDeriskLaneMode(String(action?.enter?.mode ?? lane ?? ""))) {
          const deriskPx = Number(DERISK_STRICT_DERISK_THR);
          const deriskShares = computeDeriskSharesFromState(deriskPx);
          armPaperTpOrder(side, marketFillPx, deriskShares, "DERISK", deriskPx, true);
        } else {
          armPaperTpOrder(side, marketFillPx);
        }
        clearPendingStop(st);
        st.pendingStopShares = Number(st.shares ?? 0);
        if (lane) lockPaperSessionLane(lane, "open");
        return;
      }
      const placedAt = nowMs();
      const limitPx = actionLimitPx ?? configuredEntryLimitPx(ui);
      if (action?.enter?.mode === "NO_CROSS_WINNER") {
        const hcSubtype = String(action?.enter?.hcSubtype || "HC_OPPOSITE");
        console.log(
          `[HC SIGNAL] engine=paper side=${side} signalPx=${entryPx} limitPx=${limitPx} ttlMs=${actionTtlMs} ` +
          `subtype=${hcSubtype} oppLead=${HC_OPPOSITE_MIN_BID} ` +
          `sameMinBid=${HC_SAME_SIDE_MIN_BID} samePersist=${HC_SAME_SIDE_PERSISTENCE_TICKS} sameWaitSec=${HC_SAME_SIDE_MIN_SEC_AFTER_STOP}`
        );
        broadcast({
          type: "status",
          t: nowMs(),
          status:
            `HC signal (paper): side=${side} signal=${entryPx.toFixed(2)} limit=${limitPx.toFixed(2)} ` +
            `subtype=${hcSubtype}`,
        });
      }
      st.enterInFlight = true;
      st.pendingEntrySide = side;
      st.pendingEntrySignalPx = entryPx;
      st.pendingEntryLimitPx = limitPx;
      st.pendingEntryBaseLimitPx = limitPx;
      st.pendingEntryRepriceCount = 0;
      st.pendingEntryPlacedAtMs = placedAt;
      st.pendingEntryExpiresAtMs = actionNoTtl ? null : (placedAt + actionTtlMs);
      st.pendingEntryNotionalUsd = notionalUsd;
      st.pendingEntryMode = action?.enter?.mode ?? null;
      st.pendingEntrySubtype = action?.enter?.hcSubtype ?? null;
      if (lane) lockPaperSessionLane(lane, "pending");
      markEntrySignalLatency(st, engine, side, lane ?? null, "strategy_on_tick", Number(entryPx));
      markEntrySubmitLatency(st);

      emitTradeScoped(`ENTER_ORDER_${side}_PAPER`, {
        via: "strategy",
        mode: action?.enter?.mode ?? null,
        hcSubtype: action?.enter?.hcSubtype ?? null,
        signalPx: entryPx,
        signalThresholdPx: ui.entry,
        buyOrderPx: limitPx,
        limitPx,
        ttlMs: actionNoTtl ? null : actionTtlMs,
        orderPlacedAtMs: placedAt,
        fillEstimate: null,
        fillCapacityEstimate: null,
      });
      return;
    }

    // LIVE: 1 buy attempt per session + no overlap
    if ((st.buyAttemptedSessionSlug ?? null) !== current.slug) {
      st.buyAttemptedSessionSlug = current.slug;
      st.buyAttemptedThisSession = false;
      st.buyFilledThisSession = false;
    }
    if (enforcePerSideSessionLock && liveEnteredSidesThisSession.has(side)) {
      if (shouldEmitEntryBlockedEvent(st, side, "SIDE_ALREADY_ENTERED_THIS_SESSION")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "SIDE_ALREADY_ENTERED_THIS_SESSION",
          entryBlockReason: "SIDE_ALREADY_ENTERED_THIS_SESSION",
          entryBlockMeta: { slug: current.slug, side, engine: "live" },
        });
      }
      return;
    }
    if (st.buyFilledThisSession) {
      if (shouldEmitEntryBlockedEvent(st, side, "BUY_FILLED_THIS_SESSION")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "BUY_FILLED_THIS_SESSION",
          entryBlockReason: "BUY_FILLED_THIS_SESSION",
          entryBlockMeta: { slug: current.slug },
        });
      }
      return;
    }
    const candidateMode = String(action?.enter?.mode ?? "BASE").toUpperCase();
    const allowHcAfterBaseMiss =
      candidateMode === "NO_CROSS_WINNER" &&
      Boolean((st as any).__baseMissForHc) &&
      !st.buyFilledThisSession;
    if (st.buyAttemptedThisSession && !allowHcAfterBaseMiss) {
      if (shouldEmitEntryBlockedEvent(st, side, "BUY_ATTEMPTED_THIS_SESSION")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "BUY_ATTEMPTED_THIS_SESSION",
          entryBlockReason: "BUY_ATTEMPTED_THIS_SESSION",
          entryBlockMeta: { slug: current.slug, candidateMode },
        });
      }
      return;
    }
    if (st.enterInFlight) {
      if (shouldEmitEntryBlockedEvent(st, side, "ENTER_IN_FLIGHT")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "ENTER_IN_FLIGHT",
          entryBlockReason: "ENTER_IN_FLIGHT",
          entryBlockMeta: { slug: current.slug },
        });
      }
      return;
    }
    const now = nowMs();
    const liveStrategyIdLike = (strategyLive as any)?.STRATEGY_ID || null;
    const useFastLivePath = shouldUseAggressiveLiveMarketEntry(liveStrategyIdLike);
    const liveEntryCooldownMs = liveEntryAttemptCooldownMsForStrategy(liveStrategyIdLike);
    if (st.lastEnterAttemptMs && now - st.lastEnterAttemptMs < liveEntryCooldownMs) {
      if (shouldEmitEntryBlockedEvent(st, side, "ENTER_ATTEMPT_COOLDOWN")) {
        emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
          via: "strategy",
          mode: action?.enter?.mode ?? null,
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          entryBlockCode: "ENTER_ATTEMPT_COOLDOWN",
          entryBlockReason: "ENTER_ATTEMPT_COOLDOWN",
          entryBlockMeta: {
            slug: current.slug,
            lastEnterAttemptMs: st.lastEnterAttemptMs,
            cooldownMs: liveEntryCooldownMs,
            elapsedMs: now - Number(st.lastEnterAttemptMs),
          },
        });
      }
      return;
    }

    st.lastEnterAttemptMs = now;

    if (!shouldSkipHeavyLiveEntryPrecheckForStrategy(liveStrategyIdLike)) {
      const entryPrecheck = await validateLiveEntryPreconditions(side, notionalUsd, "strategy_enter_precheck");
      if (!entryPrecheck.ok) {
        console.warn(
          `[ENTER BLOCKED] engine=live(strategy) side=${side} code=${entryPrecheck.code} ` +
          `tokenId=${entryPrecheck.meta?.tokenId ?? "-"} allow=${entryPrecheck.meta?.conditionalAllowanceShares ?? "-"}`
        );
        if (shouldEmitEntryBlockedEvent(st, side, entryPrecheck.code)) {
          broadcast({
            type: "status",
            t: nowMs(),
            status: `ENTER BLOCKED code=${entryPrecheck.code} side=${side} token=${entryPrecheck.meta?.tokenId ?? "-"}`,
          });
          emitTradeScoped(`ENTER_BLOCKED_${side}_LIVE`, {
            via: "strategy",
            mode: action?.enter?.mode ?? null,
            hcSubtype: action?.enter?.hcSubtype ?? null,
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            entryBlockCode: entryPrecheck.code,
            entryBlockReason: entryPrecheck.code,
            entryBlockMeta: entryPrecheck.meta,
          });
        }
        return;
      }
    }
    markEntrySignalLatency(st, engine, side, lane ?? null, "strategy_on_tick", Number(entryPx));

    st.buyAttemptedThisSession = true;
    st.enterInFlight = true;
    markEntrySubmitLatency(st);

    const attemptedMode = String(action?.enter?.mode || "BASE").toUpperCase();
    try {
      if (
        enforcePerSideSessionLock ||
        forceMarketEntry ||
        shouldUseAggressiveLiveMarketEntry((strategyLive as any)?.STRATEGY_ID || null)
      ) {
        emitTradeScoped(`ENTER_SUBMIT_START_${side}_LIVE`, {
          via: "strategy_market_entry",
          mode: action?.enter?.mode ?? "BASE",
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          orderType: "MARKET",
        });
        const out = await placeLiveMarketBuy(side, notionalUsd, ui, {
          strictMarketOnly: true,
          strategyIdLike: liveStrategyIdLike,
          requireOrderTimelineFillTs: requiresOrderTimelineLatency(liveStrategyIdLike),
          onAccepted: ({ acceptedAtMs, orderId }) => {
            emitTradeScoped(`ENTER_SUBMIT_ACCEPTED_${side}_LIVE`, {
              via: "strategy_market_entry",
              mode: action?.enter?.mode ?? "BASE",
              hcSubtype: action?.enter?.hcSubtype ?? null,
              signalPx: entryPx,
              signalThresholdPx: ui.entry,
              orderType: "MARKET",
              eventTsMs: acceptedAtMs,
              orderId: orderId ?? null,
            });
          },
          onFirstFillSeen: ({ firstFillSeenAtMs, orderId, filledPx, shares, filledAtMs }) => {
            emitTradeScoped(`ENTER_FIRST_FILL_SEEN_${side}_LIVE`, {
            via: "strategy_market_entry",
            mode: action?.enter?.mode ?? "BASE",
            hcSubtype: action?.enter?.hcSubtype ?? null,
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            eventTsMs: firstFillSeenAtMs,
            actualFillTsMs: filledAtMs,
            fillPx: filledPx,
            actualFillPx: filledPx,
            shares,
            orderId: orderId ?? null,
          });
          },
          onFilledConfirmed: ({ filledConfirmedAtMs, orderId, filledPx, shares, filledAtMs }) => {
            emitTradeScoped(`ENTER_FILL_CONFIRMED_${side}_LIVE`, {
              via: "strategy_market_entry",
              mode: action?.enter?.mode ?? "BASE",
              hcSubtype: action?.enter?.hcSubtype ?? null,
              signalPx: entryPx,
              signalThresholdPx: ui.entry,
              eventTsMs: filledConfirmedAtMs,
              actualFillTsMs: filledAtMs,
              fillPx: filledPx,
              actualFillPx: filledPx,
              shares,
              orderId: orderId ?? null,
            });
          },
        });
        st.entered = true;
        st.side = side;
        st.entryTsMs = out.filledAtMs ?? nowMs();
        st.entryPx = out.filledPx;
        st.shares = out.shares;
        st.entryMode = action?.enter?.mode ?? "BASE";
        st.entrySubtype = action?.enter?.hcSubtype ?? null;
        st.positionTokenId = out.tokenId ?? st.positionTokenId ?? tokenIdForSide(side);
        await reconcileLiveSharesFromPosition(st, side, "strategy_entry_fill_market");
        await refreshPolymarketStateAfterFill(st, side, "strategy_entry_fill_market");
        resetPaperDeriskExecutionState(st);
        st.notionalUsd =
          Number.isFinite(Number(st.shares)) && Number.isFinite(out.filledPx)
            ? Number(st.shares) * out.filledPx
            : st.notionalUsd;
        applyEntryFeeAccounting(st, Number(st.entryPx), Number(st.shares ?? 0));
        initPositionAccountingOnEntry(st, Number(st.notionalUsd ?? 0));
        st.balanceUsd = liveAccount.balanceUsd;
        st.buyFilledThisSession = true;
        liveEnteredSidesThisSession.add(side);
        (st as any).__baseMissForHc = false;
        (st as any).__baseMissAtMs = null;
        (st as any).__baseMissSide = null;
        st.tpOrderId = out.tpOrderId ?? null;
        st.buyFilledAtMs = hasVerifiedVenueFillTs(out.filledAtMs) ? out.filledAtMs : null;
        st.firstSellAttemptAtMs = null;
        const strictLatencyFillOk =
          !requiresOrderTimelineLatency(liveStrategyIdLike) ||
          out.fillTimestampSource === "order_timeline";
        if (hasVerifiedVenueFillTs(st.buyFilledAtMs) && strictLatencyFillOk) {
          finalizeEntryLatency(st, Number(st.buyFilledAtMs), {
            via: "strategy_market_entry",
            signalPx: Number(entryPx),
            fillPx: Number(out.filledPx),
          });
          const lagEventTsMs = Number(st.buyFilledAtMs ?? st.entryTsMs ?? nowMs());
          emitTradeScoped(`ENTER_${side}_LIVE`, {
            actualFillTsMs: out.filledAtMs,
            eventTsMs: out.entryEventTsMs ?? out.filledAtMs,
            via: "strategy_market_entry",
            mode: action?.enter?.mode ?? "BASE",
            hcSubtype: action?.enter?.hcSubtype ?? null,
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            fillPx: out.filledPx,
            actualFillPx: out.filledPx,
            orderType: "MARKET",
            orderId: out.orderId ?? null,
            slippageFromSignalPx: Number(out.filledPx) - Number(entryPx),
            slippageFromThresholdPx: Number(out.filledPx) - Number(ui.entry),
            fillEstimate: null,
            lagSnapshotAtEvent: currentQuoteLagSnapshotAt(lagEventTsMs),
            lagWindowBaseLookbackMs: Math.round(entryLagWindowRadiusMsForStrategy(liveStrategyIdLike) / 2),
          });
          scheduleEntryLagWindowCapture(
            "live",
            `ENTER_${side}_LIVE`,
            side,
            lagEventTsMs,
            liveStrategyIdLike,
            {
              via: "strategy_market_entry",
              mode: action?.enter?.mode ?? "BASE",
              hcSubtype: action?.enter?.hcSubtype ?? null,
              signalPx: entryPx,
              signalThresholdPx: ui.entry,
            }
          );
        } else {
          console.warn(
            `[LIVE ENTER HYDRATED WITHOUT VENUE TS] via=strategy_market side=${side} slug=${current.slug} ` +
            `shares=${roundTo6(Number(out.shares ?? 0))} px=${roundTo6(Number(out.filledPx ?? 0))} ` +
            `fillTsSource=${String(out.fillTimestampSource || "unknown")}`
          );
        }
        return;
      }
      const strictLimitPx = actionLimitPx ?? configuredEntryLimitPx(ui);
    const requiredSharesEst = strictLimitPx > 0 ? notionalUsd / strictLimitPx : null;
    const fillEstimate =
      side && Number.isFinite(Number(requiredSharesEst))
        ? await estimateBuyLimitFillability(tokenIdForSide(side), strictLimitPx, Number(requiredSharesEst))
        : null;
    if (action?.enter?.mode === "NO_CROSS_WINNER") {
      const hcSubtype = String(action?.enter?.hcSubtype || "HC_OPPOSITE");
      console.log(
        `[HC SIGNAL] engine=live side=${side} signalPx=${entryPx} limitPx=${strictLimitPx} ttlMs=${actionTtlMs} ` +
        `subtype=${hcSubtype} oppLead=${HC_OPPOSITE_MIN_BID} ` +
        `sameMinBid=${HC_SAME_SIDE_MIN_BID} samePersist=${HC_SAME_SIDE_PERSISTENCE_TICKS} sameWaitSec=${HC_SAME_SIDE_MIN_SEC_AFTER_STOP}`
      );
      broadcast({
        type: "status",
        t: nowMs(),
        status:
          `HC signal (live): side=${side} signal=${entryPx.toFixed(2)} limit=${strictLimitPx.toFixed(2)} ` +
          `subtype=${hcSubtype}`,
      });
    }
      const buyPx = buyPxForSide(side, upBA, dnBA, strictLimitPx);
      let executedBuyPx = buyPx;
      const ttlMs = actionTtlMs;
      console.log(
        `[ENTER LIVE][strategy] style=limit_strict ` +
          `attempt side=${side} buyPx=${buyPx} limitPx=${strictLimitPx} notionalUsd=${notionalUsd} ttlMs=${ttlMs} slug=${current.slug}`
      );
      let out: { filledPx: number; shares: number; tpOrderId: string | null; tokenId: string; filledAtMs: number | null; entryEventTsMs: number | null; orderId: string | null };
      try {
        out = await placeLiveLimitBuy(side, buyPx, notionalUsd, ui, ttlMs, {
          strategyIdLike: liveStrategyIdLike,
        });
      } catch (e1: any) {
        const msg1 = String(e1?.message ?? e1);
        const entryMode = attemptedMode;
        if (entryMode === "BASE" && isLikelyUnfilledLiveBuy(msg1)) {
          const askNowRaw = side === "UP" ? Number((upBA as any)?.ask) : Number((dnBA as any)?.ask);
          const bidNowRaw = side === "UP" ? Number((upBA as any)?.bid) : Number((dnBA as any)?.bid);
          const basePx = Number.isFinite(askNowRaw) ? askNowRaw : (Number.isFinite(bidNowRaw) ? bidNowRaw : buyPx);
          const escalateLimitPx = clampEntryBuyPx(basePx);
          const escalateBuyPx = buyPxForSide(side, upBA as any, dnBA as any, escalateLimitPx);
          emitTradeScoped(`ENTER_REPRICE_${side}_LIVE`, {
            phase: "entry_reprice",
            via: "base_ttl_escalate_to_ask",
            mode: "BASE",
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            oldLimitPx: buyPx,
            buyOrderPx: escalateBuyPx,
            limitPx: escalateLimitPx,
            ttlMs: LIVE_BASE_ESCALATE_TTL_MS,
          });
          executedBuyPx = escalateBuyPx;
          out = await placeLiveLimitBuy(side, escalateBuyPx, notionalUsd, ui, LIVE_BASE_ESCALATE_TTL_MS, {
            strategyIdLike: liveStrategyIdLike,
          });
        } else {
          throw e1;
        }
      }
      st.entryPx = out.filledPx;
      st.entered = true;
      st.side = side;
      st.entryTsMs = out.filledAtMs ?? nowMs();
      st.shares = out.shares;
      st.entryMode = action?.enter?.mode ?? "BASE";
      st.entrySubtype = action?.enter?.hcSubtype ?? null;
      st.positionTokenId = out.tokenId ?? st.positionTokenId ?? tokenIdForSide(side);
      await reconcileLiveSharesFromPosition(st, side, "strategy_entry_fill");
      await refreshPolymarketStateAfterFill(st, side, "strategy_entry_fill");
      resetPaperDeriskExecutionState(st);
      st.notionalUsd =
        Number.isFinite(Number(st.shares)) && Number.isFinite(out.filledPx)
          ? Number(st.shares) * out.filledPx
          : st.notionalUsd;
      applyEntryFeeAccounting(st, Number(st.entryPx), Number(st.shares ?? 0));
      initPositionAccountingOnEntry(st, Number(st.notionalUsd ?? 0));
      st.balanceUsd = liveAccount.balanceUsd;
      st.buyFilledThisSession = true;
      liveEnteredSidesThisSession.add(side);
      (st as any).__baseMissForHc = false;
      (st as any).__baseMissAtMs = null;
      (st as any).__baseMissSide = null;
      st.tpOrderId = out.tpOrderId ?? null;
      st.buyFilledAtMs = hasVerifiedVenueFillTs(out.filledAtMs) ? out.filledAtMs : null;
      st.firstSellAttemptAtMs = null;
      if (hasVerifiedVenueFillTs(st.buyFilledAtMs)) {
        finalizeEntryLatency(st, Number(st.buyFilledAtMs), {
          via: "strategy_limit_entry",
          signalPx: Number(entryPx),
          fillPx: Number(out.filledPx),
        });
        const lagEventTsMs = Number(st.buyFilledAtMs ?? st.entryTsMs ?? nowMs());

        emitTradeScoped(`ENTER_${side}_LIVE`, {
          actualFillTsMs: out.filledAtMs,
          eventTsMs: out.entryEventTsMs ?? out.filledAtMs,
          via: "strategy",
          mode: action?.enter?.mode ?? "BASE",
          hcSubtype: action?.enter?.hcSubtype ?? null,
          signalPx: entryPx,
          signalThresholdPx: ui.entry,
          buyOrderPx: executedBuyPx,
          fillPx: out.filledPx,
          actualFillPx: out.filledPx,
          orderId: out.orderId ?? null,
          slippageFromSignalPx: Number(out.filledPx) - Number(entryPx),
          slippageFromThresholdPx: Number(out.filledPx) - Number(ui.entry),
          fillEstimate,
          lagSnapshotAtEvent: currentQuoteLagSnapshotAt(lagEventTsMs),
          lagWindowBaseLookbackMs: Math.round(entryLagWindowRadiusMsForStrategy(liveStrategyIdLike) / 2),
        });
        scheduleEntryLagWindowCapture(
          "live",
          `ENTER_${side}_LIVE`,
          side,
          lagEventTsMs,
          liveStrategyIdLike,
          {
            via: "strategy",
            mode: action?.enter?.mode ?? "BASE",
            hcSubtype: action?.enter?.hcSubtype ?? null,
            signalPx: entryPx,
            signalThresholdPx: ui.entry,
            buyOrderPx: executedBuyPx,
          }
        );
      } else {
        console.warn(
          `[LIVE ENTER HYDRATED WITHOUT VENUE TS] via=strategy_limit side=${side} slug=${current.slug} ` +
          `shares=${roundTo6(Number(out.shares ?? 0))} px=${roundTo6(Number(out.filledPx ?? 0))}`
        );
      }
    } catch (e: any) {
      console.error(`[LIVE ENTER ERROR] ${String(e?.message ?? e)}`);
      st.entered = false;
      st.side = null;
      st.entryTsMs = null;
      st.entryPx = null;
      st.entryMode = null;
      st.entrySubtype = null;
      st.shares = null;
      st.notionalUsd = null;
      st.grossPnlUsd = null;
      st.entryFeeUsd = null;
      st.exitFeeUsd = null;
      st.totalFeesUsd = null;
      st.positionTokenId = null;
      st.buyFilledAtMs = null;
      st.firstSellAttemptAtMs = null;
      st.buyAttemptedSessionSlug = current.slug;
      st.buyFilledThisSession = false;
      const errMsg = String(e?.message ?? e);
      if (attemptedMode === "BASE" && isLikelyUnfilledLiveBuy(errMsg)) {
        (st as any).__baseMissForHc = true;
        (st as any).__baseMissAtMs = nowMs();
        (st as any).__baseMissSide = side;
      }
      if (shouldRearmLiveEntryAfterErrorForStrategy(liveStrategyIdLike, errMsg)) {
        st.buyAttemptedThisSession = false;
        console.warn(`[LIVE ENTER REARM] strategy reason=${errMsg}`);
      }
      clearEntryLatency(st);

      broadcast({ type: "status", t: nowMs(), status: `enter failed (live,strategy): ${String(e?.message ?? e)}` });
    } finally {
      st.enterInFlight = false;
    }
  }

    // ===== EXIT =====
  if (action.exit) {
    const exitTypePre = String(action.exit.type || "EXIT").toUpperCase();
    const isStopPre = exitTypePre.includes("STOP");
    if (engine === "live" && isStopPre && (!st.entered || st.exited || !st.side)) {
      syncHostLiveStateFromCurrentOpenBotRuntime("strategy-stop-no-live-state");
      await reconcileLivePositionMaybe(true, "strategy-stop-no-live-state");
      if (!st.entered || st.exited || !st.side) {
        await hydrateLivePositionFromTokenBalances("strategy-stop-no-live-state");
      }
      if (st.entered && !st.exited && st.side) {
        console.warn(
          `[LIVE POS SYNC] recovered during strategy stop path side=${st.side} shares=${roundTo6(Number(st.shares ?? 0))} slug=${current.slug}`
        );
      }
    }
    if (engine === "live" && isStopPre && (!st.entered || st.exited || !st.side)) {
      const t = nowMs();
      if (!((st as any).__lastNoLivePositionStopLogMs) || t - (st as any).__lastNoLivePositionStopLogMs >= STOP_SKIP_LOG_INTERVAL_MS) {
        console.log(
          `[STOP SKIP] engine=live reason=no_live_position entered=${st.entered} exited=${st.exited} side=${st.side ?? "-"}`
        );
        (st as any).__lastNoLivePositionStopLogMs = t;
      }
    }
  }
  if (action.exit && st.entered && !st.exited) {
  const side = (st.side ?? action.exit.side) as ("UP" | "DOWN");
  if (!side) return;


    // guard against overlapping exits
    if (engine === "live" && st.exitInFlight) {
      return;
    }

    const exitType = String(action.exit.type || "EXIT").toUpperCase();
    const exitPx = Number.isFinite(Number(action.exit.exitPx))
      ? Number(action.exit.exitPx)
      : side === "UP"
        ? upBid
        : dnBid;
    const stopReason = action?.exit?.stopReason != null ? String(action.exit.stopReason) : null;
    const stopSource = action?.exit?.stopSource != null ? String(action.exit.stopSource) : null;
    const stopMeta = action?.exit?.stopMeta && typeof action.exit.stopMeta === "object"
      ? (action.exit.stopMeta as Record<string, any>)
      : null;

    const isStop = exitType.includes("STOP");
    markExitSignalLatency(st, engine, side, lane ?? null, "strategy_signal", exitType);
    const defaultStopSource =
      isStop
        ? String(st.entryMode ?? "").toUpperCase() === "NO_CROSS_WINNER"
          ? "STRATEGY_HC"
          : "STRATEGY_MOMENTUM"
        : null;
    const resolvedStopSource = stopSource ?? defaultStopSource;
    const resolvedStopReason = stopReason ?? (isStop ? "STRATEGY_STOP_THRESHOLD" : null);
    const label = isStop ? "STOP" : "EXIT";
    const sidePxInferred = inferSideBid(side, upBA, dnBA);
    const stopGatePx = Number.isFinite(Number(sidePxInferred))
      ? Number(sidePxInferred)
      : exitPx;
    // For strategy-emitted STOP signals, prefer explicit strategy stop threshold
    // (e.g. derisk runner stop=0.43) over UI baseline stop (often 0.40).
    const explicitStrategyStopThr =
      isStop && Number.isFinite(Number(action?.exit?.exitPx))
        ? clamp01(Number(action.exit.exitPx))
        : NaN;
    if (isStop) {
      if (Number.isFinite(Number(explicitStrategyStopThr)) && Number(explicitStrategyStopThr) > 0) {
        const gatePx = Number(stopGatePx);
        if (!(Number.isFinite(gatePx) && gatePx <= Number(explicitStrategyStopThr))) {
          console.warn(
            `[STRATEGY STOP HONOR] engine=${engine} side=${side} gatePx=${Number.isFinite(gatePx) ? gatePx : "na"} ` +
            `thr=${Number(explicitStrategyStopThr)} slug=${current.slug} source=strategy_exit`
          );
        }
      } else if (!shouldTriggerStop(ui, side, Number(stopGatePx), elapsedSec, engine, "strategy")) {
        console.warn(
          `[STRATEGY STOP HONOR] engine=${engine} side=${side} gatePx=${Number.isFinite(Number(stopGatePx)) ? Number(stopGatePx) : "na"} ` +
          `uiStop=${Number.isFinite(Number(ui.stop)) ? Number(ui.stop) : "na"} slug=${current.slug} source=strategy_exit`
        );
      }
    }
    const targetSellPx = clamp01(
      Number.isFinite(exitPx)
        ? exitPx
        : isStop
          ? ui.stop
          : ui.exit
    );
    // For paper STOPs, book at current side price to reflect slippage/gaps.
    const paperExecPx =
      isStop && Number.isFinite(Number(action?.exit?.exitPx))
        ? Number(action?.exit?.exitPx)
        : isStop && Number.isFinite(Number(sidePxInferred))
        ? Number(sidePxInferred)
        : exitPx;

    // 🔥 LOG ALWAYS when we *intend* to exit
    console.log(
      `[EXIT SIGNAL][strategy] engine=${engine} label=${label} exitType=${exitType} side=${side} ` +
      `exitPx=${exitPx} shares=${st.shares} entered=${st.entered} exited=${st.exited} market=${current.slug}`
    );
    broadcast({
      type: "status",
      t: nowMs(),
      status:
        `EXIT SIGNAL (strategy) engine=${engine} label=${label} side=${side} ` +
        `exitPx=${exitPx} shares=${st.shares ?? "null"} market=${current.slug}`,
    });
    const shouldEmitSignalEvent = !(
      engine === "paper" &&
      !isStop &&
      String(exitType || "").toUpperCase() === "DERISK"
    );
    if (shouldEmitSignalEvent) {
      emitTradeScoped(`SIGNAL_${label}_${side}_${engine.toUpperCase()}`, {
        phase: "signal",
        via: "strategy",
        exitType,
        signalPx: exitPx,
        targetSellPx,
        stopReason: resolvedStopReason,
        stopSource: resolvedStopSource,
        stopMeta,
      });
    }

    // PAPER: STOP exits immediately; profitable exits fill immediately if already
    // marketable on this tick, otherwise they arm a resting TP limit order.
    if (engine === "paper") {
      const curShares = Math.max(0, Number(st.shares ?? 0));
      const reqSharesRaw = Number(action?.exit?.shares);
      const qtyPctRaw = Number(action?.exit?.qtyPct);
      const desiredExitType = String(action?.exit?.type || "EXIT").toUpperCase();
      const requestedShares = resolveRequestedExitShares(curShares, reqSharesRaw, qtyPctRaw, desiredExitType);
      if (!(requestedShares > 0)) return;

      if (!isStop) {
        const explicitExitPx = Number(action?.exit?.exitPx);
        const desiredTpPx = Number.isFinite(explicitExitPx)
          ? clamp01(explicitExitPx)
          : computePaperTpLimitPx(Number(st.entryPx));
        const currentPaperPx = Number.isFinite(Number(sidePxInferred))
          ? Number(sidePxInferred)
          : Number(exitPx);
        const limitSatisfiedNow =
          Number.isFinite(currentPaperPx) &&
          Number.isFinite(desiredTpPx) &&
          currentPaperPx >= desiredTpPx;
        const shouldImmediateFill = desiredExitType === "SETTLE" || limitSatisfiedNow;
        if (shouldImmediateFill) {
          const fillPx =
            desiredExitType === "SETTLE"
              ? currentPaperPx
              : Math.max(currentPaperPx, desiredTpPx);
          if (Number.isFinite(fillPx) && fillPx > 0) {
            markExitSubmitLatency(st);
            const feeMode: ExitFeeMode = desiredExitType === "SETTLE" ? "none" : "maker";
            const leg = applyPaperSellLegAccounting(st, fillPx, requestedShares, feeMode);
            const isFullClose = Number(leg.remainingShares) <= 1e-6;
            st.exited = isFullClose;
            st.exitTsMs = nowMs();
            st.exitPx = fillPx;
            st.stopFallbackTriggered = false;
            st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;
            if (!isFullClose) st.entered = true;
            clearPendingTp(st);
            if (isFullClose) clearPendingStop(st);
            else st.pendingStopShares = Number(leg.remainingShares ?? 0);

            const pnlUsd = Number(leg.legPnlUsd ?? 0);
            paperAccount.balanceUsd += pnlUsd;
            st.balanceUsd = paperAccount.balanceUsd;
            finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
              via: desiredExitType === "SETTLE" ? "strategy_settle_immediate" : "strategy_tp_limit_immediate",
              exitType: desiredExitType,
              fillPx,
              signalPx: Number(exitPx),
            });

            emitTradeScoped(`EXIT_${side}_PAPER`, {
              via: desiredExitType === "SETTLE" ? "strategy_settle_immediate" : "strategy_tp_limit_immediate",
              exitType: desiredExitType,
              signalPx: Number(exitPx),
              targetSellPx: desiredTpPx,
              limitPx: desiredTpPx,
              fillPx,
              actualFillPx: fillPx,
              soldShares: Number(leg.soldShares ?? requestedShares),
              remainingShares: Number(leg.remainingShares ?? 0),
              partial: !isFullClose,
              legPnlUsd: pnlUsd,
              stopReason: resolvedStopReason,
              stopSource: resolvedStopSource,
              stopMeta,
            });
            if (!isFullClose && isSinglePartialExitTypeRaw(desiredExitType)) {
              markPaperSinglePartialCompleted(st, side);
            }
            if (isFullClose && lane) unlockPaperSessionLane(lane);
            if (isFullClose && lane === "BASE") {
              rearmPaperLaneStrategy("NO_CROSS_WINNER", "base_exited_rearm_hc_second_path");
            }
            return;
          }
        }
        const hasPendingTp =
          Number.isFinite(Number(st.pendingTpLimitPx)) &&
          Number(st.pendingTpLimitPx) > 0 &&
          !!st.tpOrderId;
        const pendingTpPx = Number(st.pendingTpLimitPx);
        const pendingTpType = String(st.pendingTpExitType || "EXIT").toUpperCase();
        const sameType = pendingTpType === desiredExitType;
        const samePx = Number.isFinite(pendingTpPx) && Math.abs(pendingTpPx - desiredTpPx) <= 1e-9;
        const shouldReplaceExisting = hasPendingTp && (!sameType || !samePx);
        if (!hasPendingTp || shouldReplaceExisting) {
          armPaperTpOrder(
            side,
            Number.isFinite(Number(sidePxInferred)) ? Number(sidePxInferred) : Number(exitPx),
            requestedShares,
            desiredExitType,
            desiredTpPx,
            shouldReplaceExisting
          );
        }
        return;
      }

      markExitSubmitLatency(st);
      const leg = applyPaperSellLegAccounting(st, Number(paperExecPx), requestedShares, "taker");
      const isFullClose = Number(leg.remainingShares) <= 1e-6;
      st.exited = isFullClose;
      st.exitTsMs = nowMs();
      st.exitPx = Number.isFinite(paperExecPx) ? paperExecPx : null;
      st.stopFallbackTriggered = isStop;
      st.holdSec = st.entryTsMs && st.exitTsMs ? (st.exitTsMs - st.entryTsMs) / 1000 : null;
      if (!isFullClose) st.entered = true;
      clearPendingTp(st);
      clearPendingStop(st);

      const pnlUsd = Number(leg.legPnlUsd ?? 0);
      paperAccount.balanceUsd += pnlUsd;
      st.balanceUsd = paperAccount.balanceUsd;
      finalizeExitLatency(st, Number(st.exitTsMs ?? nowMs()), {
        via: "strategy_stop_market",
        exitType,
        fillPx: Number(paperExecPx),
        signalPx: Number(exitPx),
      });

      console.log(
        `[PAPER EXIT] label=${label} side=${side} exitPx=${paperExecPx} pnlUsd=${pnlUsd} ` +
        `soldShares=${Number(leg.soldShares ?? requestedShares)} remainingShares=${Number(leg.remainingShares ?? 0)}`
      );
      emitTradeScoped(`${label}_${side}_PAPER`, {
        via: "strategy",
        exitType,
        stopReason: resolvedStopReason,
        stopSource: resolvedStopSource,
        stopMeta,
        soldShares: Number(leg.soldShares ?? requestedShares),
        remainingShares: Number(leg.remainingShares ?? 0),
        partial: !isFullClose,
        legPnlUsd: pnlUsd,
      });
      if (lane === "BASE" && isStop && isFullClose) {
        (st as any).__stoppedThisSession = true;
      }
      if (isFullClose && lane) unlockPaperSessionLane(lane);
      if (isFullClose && lane === "BASE") {
        rearmPaperLaneStrategy("NO_CROSS_WINNER", "base_exited_rearm_hc_second_path");
      }
      return;
    }

    // LIVE: must have shares to sell
    if (isStop) {
      emitTradeScoped(`SIGNAL_STOP_${side}_LIVE`, {
        phase: "signal_stop",
        via: "strategy",
        signalPx: Number(exitPx),
        intendedPx: Number(exitPx),
        exitPx: Number(exitPx),
        exitType,
        stopReason: resolvedStopReason,
        stopSource: resolvedStopSource || "strategy_stop_signal",
        stopMeta,
      });
    }
    const recoveredShares = await recoverLiveSharesForExit(st, side, `strategy_${label.toLowerCase()}`);
    if (!(recoveredShares > 0)) {
      st.exited = true;
      st.exitTsMs = nowMs();
      st.exitPx = Number.isFinite(Number(exitPx)) ? Number(exitPx) : null;
      emitTradeScoped(`${label}_${side}_LIVE`, {
        via: "venue_reconcile",
        actualFillPx: Number.isFinite(Number(exitPx)) ? Number(exitPx) : null,
        venueAlreadyFlat: true,
        signalPx: Number.isFinite(Number(exitPx)) ? Number(exitPx) : null,
        intendedPx: Number.isFinite(Number(exitPx)) ? Number(exitPx) : null,
        exitPx: Number.isFinite(Number(exitPx)) ? Number(exitPx) : null,
        exitType,
        stopReason: resolvedStopReason,
        stopSource: resolvedStopSource || "strategy_stop_venue_flat",
        stopMeta,
      });
      clearLivePositionStateAfterTerminalExit(st);
      const stAny = st as any;
      const flatWarnKey = `strategy_flat|${String(label || "")}|${String(side || "")}|${String(st.marketSlug || "")}`;
      const flatWarnBucket = stAny.__liveExitRecoverWarnAtByKey && typeof stAny.__liveExitRecoverWarnAtByKey === "object"
        ? stAny.__liveExitRecoverWarnAtByKey
        : {};
      const flatLastAt = Number(flatWarnBucket[flatWarnKey] || 0);
      if (!Number.isFinite(flatLastAt) || (nowMs() - flatLastAt) >= 5000) {
        flatWarnBucket[flatWarnKey] = nowMs();
        stAny.__liveExitRecoverWarnAtByKey = flatWarnBucket;
        console.warn(`[LIVE EXIT RECOVER FLAT] label=${label} side=${side} venue already flat; clearing local state`);
      }
      return;
    }

    st.exitInFlight = true;

    try {
      const sessionEndMs = st.marketEndMs ?? (Date.now() + 60_000);
      if (st.firstSellAttemptAtMs == null) st.firstSellAttemptAtMs = nowMs();
      const buyFillToSellAttemptMs =
        Number.isFinite(Number(st.buyFilledAtMs)) ? Math.max(0, Number(st.firstSellAttemptAtMs) - Number(st.buyFilledAtMs)) : null;
      console.log(
        `[EXIT LATENCY] engine=${engine} label=${label} side=${side} ` +
        `buyFillToSellAttemptMs=${buyFillToSellAttemptMs ?? "na"}`
      );

      // 🔥 LOG: sell attempt about to happen
      console.log(
        `[SELL ATTEMPT] label=${label} side=${side} targetPx=${targetSellPx} ` +
        `shares=${st.shares} sessionEnd=${new Date(sessionEndMs).toISOString()}`
      );
      broadcast({
        type: "status",
        t: nowMs(),
        status:
          `SELL ATTEMPT live label=${label} side=${side} targetPx=${targetSellPx} shares=${st.shares}`,
      });

    if (!isStop) {
      const desiredExitType = String(action?.exit?.type || "EXIT").toUpperCase();
      const curShares = Math.max(0, Number(st.shares ?? 0));
      const reqSharesRaw = Number(action?.exit?.shares);
      const qtyPctRaw = Number(action?.exit?.qtyPct);
      const requestedShares = resolveRequestedExitShares(curShares, reqSharesRaw, qtyPctRaw, desiredExitType);
      const desiredTpPx = Number.isFinite(Number(action?.exit?.exitPx))
        ? clamp01(Number(action?.exit?.exitPx))
        : computePaperTpLimitPx(Number(st.entryPx));
      const samePendingTp =
        !!String(st.tpOrderId || "").trim() &&
        Number.isFinite(Number(st.pendingTpLimitPx)) &&
        Math.abs(Number(st.pendingTpLimitPx) - Number(desiredTpPx)) <= 1e-9 &&
        Number.isFinite(Number(st.pendingTpShares)) &&
        Math.abs(Number(st.pendingTpShares) - Number(requestedShares)) <= 1e-9 &&
        String(st.pendingTpExitType || "EXIT").toUpperCase() === desiredExitType;
      if (!(requestedShares > 0)) return;
      if (
        isSinglePartialExitTypeRaw(desiredExitType) &&
        paperSinglePartialCompletedForCurrentPosition(st, side)
      ) {
        return;
      }
      if (samePendingTp) return;
      markExitSubmitLatency(st);
      if (String(st.tpOrderId || "").trim() || isSinglePartialExitTypeRaw(desiredExitType)) {
        await cancelOpenSellOrdersForSide(
          side,
          isSinglePartialExitTypeRaw(desiredExitType) ? "strategy_partial_tp_replace" : "strategy_tp_replace",
          st.positionTokenId
        );
        st.tpOrderId = null;
        st.pendingTpLimitPx = null;
        st.pendingTpPlacedAtMs = null;
        st.pendingTpShares = null;
        st.pendingTpExitType = null;
        (st as any).__tpAccountedFilledShares = 0;
      }
      const placed = await placeImmediateTpSellAfterBuy(side, requestedShares, ui, st.positionTokenId, {
        source: "strategy_tp_signal",
        entryFillPx: Number(st.entryPx),
        buyFilledAtMs: Number(st.buyFilledAtMs ?? st.entryTsMs ?? nowMs()),
        strategyId: (strategyLive as any)?.STRATEGY_ID || null,
        limitPxOverride: desiredTpPx,
        exitType: desiredExitType,
      });
      st.pendingTpLimitPx = desiredTpPx;
      st.pendingTpPlacedAtMs = nowMs();
      st.pendingTpShares = Number(placed.placedShares);
      st.pendingTpExitType = desiredExitType;
      st.pendingTpArmedPositionShares = curShares;
      st.tpOrderId = placed.orderId;
      (st as any).__tpAccountedFilledShares = 0;
      emitTradeScoped(`EXIT_ORDER_${side}_LIVE`, {
        phase: "exit_order",
        via: "strategy_tp_limit_order",
        exitType: desiredExitType,
        signalPx: Number(exitPx),
        targetSellPx: desiredTpPx,
        limitPx: desiredTpPx,
        orderPlacedAtMs: Number(st.pendingTpPlacedAtMs),
        shares: Number(placed.placedShares),
        tpOrderId: placed.orderId,
        stopReason: resolvedStopReason,
        stopSource: resolvedStopSource,
        stopMeta,
      });
      return;
    }

      // STOP: walk limit every 250ms and force market fallback if still open.

      const precheck = await validateLiveStopPreconditions(side, st, Number(st.shares), "strategy_stop");
      if (!precheck.ok) {
        console.warn(
          `[STOP BLOCKED] engine=live(strategy) side=${side} code=${precheck.code} ` +
          `tokenId=${precheck.meta?.tokenId ?? "-"} req=${precheck.meta?.requestedShares ?? "-"} ` +
          `avail=${precheck.meta?.availableShares ?? "-"} allow=${precheck.meta?.conditionalAllowanceShares ?? "-"}`
        );
        if (shouldEmitStopBlockedEvent(st, side, precheck.code)) {
          broadcast({
            type: "status",
            t: nowMs(),
            status: `STOP PRECHECK WARN code=${precheck.code} side=${side} token=${precheck.meta?.tokenId ?? "-"}; continuing`,
          });
          emitTradeScoped(`STOP_BLOCKED_${side}_LIVE`, {
            via: "strategy",
            exitType: "STOP_BLOCKED",
            stopReason: precheck.code,
            stopBlockCode: precheck.code,
            stopMeta: precheck.meta,
            signalPx: exitPx,
          });
        }
        console.warn(`[STOP CONTINUE] engine=live(strategy) side=${side} proceeding despite precheck code=${precheck.code}`);
      }
      markExitSubmitLatency(st);
      const priorEntryMode = String(st.entryMode || "");
      const priorSide = side;
      const liveStrategyIdLike = (strategyLive as any)?.STRATEGY_ID || null;
      await suppressHostLiveTpProtectionForStopSignal(side, st, "strategy-stop");
      await recoverLiveSharesForExit(st, side, "strategy_stop");
      const stopSubmitStartMs = nowMs();
      const stopRequestedShares = Number(st.shares ?? 0);
      emitTradeScoped(`STOP_SUBMIT_START_${side}_LIVE`, {
        eventTsMs: stopSubmitStartMs,
        signalPx: Number(exitPx),
        intendedPx: Number(exitPx),
        exitPx: Number(exitPx),
        sharesRequested: stopRequestedShares,
        via: "strategy",
        exitType,
        stopReason: resolvedStopReason,
        stopSource: "strategy_stop_submit_start",
        stopMeta,
      });
      const submitted = await startOptimisticLiveStopRecovery(side, targetSellPx, ui, st, "strategy_stop", {
        priorEntryMode,
        priorSide,
        exitType,
        resolvedStopReason,
        stopMeta: {
          ...(stopMeta || {}),
          stopRequestedShares,
          via: "strategy",
        },
      });
      broadcast({
        type: "status",
        t: submitted.submittedAtMs,
        status: `STOP ORDER SUBMITTED optimistic_rearm side=${side} recoveryId=${submitted.recoveryId}`,
      });
      clearLivePositionStateAfterTerminalExit(st);
      if (resolvedStopReason !== "session_expired") {
        rearmLiveSessionForNextLane(st, priorEntryMode, priorSide, liveStrategyIdLike);
      }
      return;
    } catch (e: any) {
      // ✅ IMPORTANT: do NOT leave exited=true on failure; allow retries next tick
      console.error(`[LIVE EXIT ERROR] ${String(e?.message ?? e)}`);
      broadcast({ type: "status", t: nowMs(), status: `exit failed (live,strategy): ${String(e?.message ?? e)}` });

      // keep exited=false so it tries again
      st.exited = false;
      st.exitTsMs = null;
      st.exitPx = null;
    } finally {
      st.exitInFlight = false;
    }
  }

}

function recordCanonicalQuoteSample(
  slugRaw: any,
  startMsRaw: any,
  tMsRaw: any,
  upBidRaw: any,
  downBidRaw: any
) {
  const slug = String(slugRaw || "").trim();
  const tMs = Number(tMsRaw);
  const upBid = toFiniteOrNull(upBidRaw);
  const downBid = toFiniteOrNull(downBidRaw);
  if (!slug || !Number.isFinite(tMs) || !Number.isFinite(upBid) || !Number.isFinite(downBid)) return;
  recordAlgoInputTracePoint(slug, tMs, Number(upBid), Number(downBid));
  appendBtc5mCsvTracePoint(
    slug,
    startMsRaw,
    tMs,
    Number(upBid),
    Number(downBid),
    currentQuoteLagSnapshotAt(nowMs())
  );
}

// ===== Main loop =====
async function mainLoop() {
  const periodMs = Math.max(25, Number(process.env.MAIN_LOOP_PERIOD_MS || 25));
  console.log(`[${isoNow()}] server starting main loop @${(1000 / periodMs).toFixed(1)}Hz`);
  let lastHeartbeat = 0;
  const awaitWarnAfterMs = 750;
  const awaitLogged = async <T,>(label: string, work: Promise<T>): Promise<T> => {
    const startedAtMs = nowMs();
    const timer = setTimeout(() => {
      console.warn(
        `[MAIN LOOP AWAIT SLOW] slug=${String(current?.slug || "")} label=${label} durationMs=${Math.round(Math.max(0, nowMs() - startedAtMs))}`
      );
    }, awaitWarnAfterMs);
    try { (timer as any)?.unref?.(); } catch {}
    try {
      return await work;
    } finally {
      clearTimeout(timer);
    }
  };

  for (;;) {
    const workStartedAtMs = nowMs();
    const loopTiming: Record<string, number> = {};
    let loopStageStartedAtMs = workStartedAtMs;
    const markLoopStage = (label: string) => {
      const nowStageMs = nowMs();
      loopTiming[label] = Number(loopTiming[label] || 0) + Math.max(0, nowStageMs - loopStageStartedAtMs);
      loopStageStartedAtMs = nowStageMs;
    };
    try {
      const now = Date.now();
      updateMainLoopHeartbeat(now);
      void maybeWarmUserStream();
      if (current.slug && Number.isFinite(Number(current.endMs)) && Number(current.endMs) > now) {
        const msToRollover = Number(current.endMs) - now;
        if (msToRollover <= 15_000) {
          maybePrefetch5mSessionWindow(Number(current.endMs) + 1000, "pre_rollover");
        }
      }

      if (!current.slug || now >= current.endMs) {
        const prevSlug = String(current.slug || "");
        const prevEndMs = Number(current.endMs || 0);
        const prevUpToken = String(current.upToken || "");
        const prevDownToken = String(current.downToken || "");
        const next = inferCurrent5mSessionWindow(now);
        const cachedNext = getCachedSessionMarketResolution(next.slug, next.startMs, next.endMs);
        current = {
          slug: next.slug,
          startMs: next.startMs,
          endMs: next.endMs,
          upToken: String(cachedNext?.upToken || ""),
          downToken: String(cachedNext?.downToken || ""),
          volumeUsd: Number.isFinite(Number(cachedNext?.volumeUsd)) ? Number(cachedNext?.volumeUsd) : null,
        };
        const nextUpToken = String(current.upToken || "");
        const nextDownToken = String(current.downToken || "");
        const sessionTokensChanged = prevUpToken !== nextUpToken || prevDownToken !== nextDownToken;
        if (sessionTokensChanged) {
          quotePairCache = null;
          lastObservedBids = { upBid: null, downBid: null, tsMs: null };
          lastGoodObservedBids = { upBid: null, downBid: null, tsMs: null };
        }
        sessionRolloverCriticalUntilMs = nowMs() + ROLLOVER_CRITICAL_WINDOW_MS;
        if (sessionRolloverDeferredLiveReconcileTimer) {
          clearTimeout(sessionRolloverDeferredLiveReconcileTimer);
          sessionRolloverDeferredLiveReconcileTimer = null;
        }
        entryGuardResyncSessionSlug = null;

        if (entryBlockedSessionSlug == null) {
          entryBlockedSessionSlug = current.slug;
          entryBlockActive = true;
          console.log(`[ENTRY GUARD] armed on startup session=${current.slug}; new entries blocked until next session`);
        } else if (entryBlockActive && current.slug !== entryBlockedSessionSlug) {
          entryBlockActive = false;
          console.log(`[ENTRY GUARD] released at new session=${current.slug}; new entries now allowed`);
        }

        resetEngineForNewSession("paper", { slug: current.slug, startMs: current.startMs, endMs: current.endMs });
        resetEngineForNewSession("live", { slug: current.slug, startMs: current.startMs, endMs: current.endMs });

        const rolloverLagMs = Number.isFinite(prevEndMs) && prevEndMs > 0 ? Math.max(0, Date.now() - prevEndMs) : 0;
        console.log(`[${isoNow()}] NEW SESSION ${current.slug} up=${current.upToken} down=${current.downToken}`);
        console.log(`[ROLLOVER] prev=${prevSlug || "none"} next=${current.slug} lagMs=${rolloverLagMs}`);
        if (cachedNext) {
          console.log(
            `[ROLLOVER TOKENS PREFILLED] slug=${current.slug} up=${current.upToken} down=${current.downToken} cacheAgeMs=${Math.max(0, nowMs() - Number(cachedNext.resolvedAtMs || 0))}`
          );
        }
        if (sessionTokensChanged) {
          console.log(`[ROLLOVER QUOTE RESET] prevTokens(${prevUpToken},${prevDownToken}) -> nextTokens(${nextUpToken},${nextDownToken})`);
        }
        broadcast({
          type: "market",
          t: nowMs(),
          current: { slug: current.slug, startMs: current.startMs, endMs: current.endMs, volumeUsd: current.volumeUsd },
        });
        broadcastState();
        ensureQuoteStreamSubscription();
        if (shouldRunHostGlobalLiveMaintenance()) {
          prewarmLatencyCriticalOrderPathForCurrentSession("session_rollover");
        }
        maybeStartCurrent5mMarketResolve("session_rollover");
        if (shouldRunHostGlobalLiveMaintenance()) {
          sessionRolloverDeferredLiveReconcileTimer = setTimeout(() => {
            sessionRolloverDeferredLiveReconcileTimer = null;
            void reconcileLivePositionMaybe(true, "startup-session_deferred");
          }, ROLLOVER_DEFERRED_LIVE_RECONCILE_MS);
        }
      }
      markLoopStage("session_rollover");

      if (current.slug && (!current.upToken || !current.downToken)) {
        maybeStartCurrent5mMarketResolve("token_backfill");
      }

      const rolloverWindowActive = inRolloverCriticalWindow(nowMs());
      const sessionAgeMs =
        Number.isFinite(Number(current.startMs)) && Number(current.startMs) > 0
          ? Math.max(0, nowMs() - Number(current.startMs))
          : Number.POSITIVE_INFINITY;
      const liveStateNeedsPriorityMaintenance = !!stLive.entered || !!stLive.exitInFlight;
      if (
        !rolloverWindowActive ||
        liveStateNeedsPriorityMaintenance ||
        sessionAgeMs >= ROLLOVER_DEFERRED_BALANCE_REFRESH_MS
      ) {
        await awaitLogged("refreshLiveBalanceMaybe", refreshLiveBalanceMaybe());
      }
      markLoopStage("live_balance");
      if (shouldRunHostGlobalLiveMaintenance() && (!rolloverWindowActive || liveStateNeedsPriorityMaintenance)) {
        await awaitLogged("reconcileLivePositionMaybe", reconcileLivePositionMaybe(false, "periodic"));
      }
      markLoopStage("live_reconcile");
      if (!rolloverWindowActive || sessionAgeMs >= ROLLOVER_DEFERRED_MARKET_METRICS_MS) {
        void refreshCurrentMarketMetricsMaybe(false);
      }
      ensureQuoteStreamSubscription();
      markLoopStage("market_metrics");

      let pair = getCachedQuotePair(String(current.upToken), String(current.downToken), QUOTE_MAX_STALE_MS);
      if (!pair) {
        // Missing pair quotes should always trigger active recovery, even if
        // websocket is connected but carrying non-price/irrelevant messages.
        void quotePumpTick();
        void triggerQuoteFallbackIfLagged(QUOTE_FALLBACK_TRIGGER_MS + 1, "missing_pair");
        pair = getCachedQuotePair(String(current.upToken), String(current.downToken), QUOTE_MAX_STALE_MS);
      }
      if (!pair) {
        void triggerQuoteFallbackIfLagged(QUOTE_FALLBACK_TRIGGER_MS + 1, "missing_pair_stale_cache");
        pair = getCachedQuotePair(String(current.upToken), String(current.downToken), Number.POSITIVE_INFINITY);
      }
      let upBid = Number.isFinite(Number(pair?.upBid)) ? Number(pair!.upBid) : null;
      let dnBid = Number.isFinite(Number(pair?.downBid)) ? Number(pair!.downBid) : null;
      const nowTickMs = nowMs();
      const pairAgeMs =
        Number.isFinite(Number(pair?.tsMs)) && Number(pair!.tsMs) > 0 ? Math.max(0, nowTickMs - Number(pair!.tsMs)) : null;
      const pairFresh = Number.isFinite(Number(pairAgeMs)) && Number(pairAgeMs) <= QUOTE_MAX_STALE_MS;
      const streamAgeForPair =
        Number.isFinite(Number(quoteStreamLastPriceMsgMs)) && Number(quoteStreamLastPriceMsgMs) > 0
          ? Math.max(0, nowTickMs - Number(quoteStreamLastPriceMsgMs))
          : (
            Number.isFinite(Number(quoteStreamLastMsgMs)) && Number(quoteStreamLastMsgMs) > 0
              ? Math.max(0, nowTickMs - Number(quoteStreamLastMsgMs))
              : null
          );
      const pairUsableFromHealthyStream =
        !!pair &&
        Number.isFinite(Number(upBid)) &&
        Number.isFinite(Number(dnBid)) &&
        isQuoteStreamHealthyForPairUse(streamAgeForPair);
      const pairUsable = pairFresh || pairUsableFromHealthyStream;
      if (!pairUsable) {
        const shouldKickRestFallback =
          !quoteStreamConnected ||
          !Number.isFinite(Number(streamAgeForPair)) ||
          Number(streamAgeForPair) >= QUOTE_FALLBACK_TRIGGER_MS;
        if (shouldKickRestFallback) {
          void triggerQuoteFallbackIfLagged(pairAgeMs, pair ? "stale_pair" : "missing_pair");
        }
      }
      const lastGoodAgeMs =
        Number.isFinite(Number(lastGoodObservedBids.tsMs)) && Number(lastGoodObservedBids.tsMs) > 0
          ? Math.max(0, nowTickMs - Number(lastGoodObservedBids.tsMs))
          : null;
      const canHoldLastGood =
        Number.isFinite(Number(lastGoodAgeMs)) &&
        Number(lastGoodAgeMs) <= QUOTE_HOLD_LAST_GOOD_MS &&
        Number.isFinite(Number(lastGoodObservedBids.upBid)) &&
        Number.isFinite(Number(lastGoodObservedBids.downBid));
      if ((!pairUsable || upBid == null || dnBid == null) && canHoldLastGood) {
        upBid = Number(lastGoodObservedBids.upBid);
        dnBid = Number(lastGoodObservedBids.downBid);
      }
      if ((!pairUsable || upBid == null || dnBid == null) && !canHoldLastGood) {
        const prevUsable =
          Number.isFinite(Number(lastObservedBids.upBid)) &&
          Number.isFinite(Number(lastObservedBids.downBid));
        if (prevUsable) {
          upBid = Number(lastObservedBids.upBid);
          dnBid = Number(lastObservedBids.downBid);
        }
      }
      const upBA = { bid: upBid, ask: Number.isFinite(Number(pair?.upAsk)) ? Number(pair!.upAsk) : null };
      const dnBA = { bid: dnBid, ask: Number.isFinite(Number(pair?.downAsk)) ? Number(pair!.downAsk) : null };
      if (!pairUsable) {
        const key = `pair_hold:${current.slug}`;
        const last = Number(((mainLoop as any).__lastPairHoldWarnMs?.get(key) ?? 0));
        if (!Number.isFinite(last) || (nowTickMs - last) > 15000) {
          if (!(mainLoop as any).__lastPairHoldWarnMs) (mainLoop as any).__lastPairHoldWarnMs = new Map<string, number>();
          (mainLoop as any).__lastPairHoldWarnMs.set(key, nowTickMs);
          console.warn(
            `[QUOTE HOLD] session=${current.slug} reason=${pair ? "stale_pair" : "missing_pair"} ` +
            `pairAgeMs=${String(pairAgeMs)} up=${String(upBA.bid)} down=${String(dnBA.bid)}`
          );
        }
      }
      const nextUpBid = Number.isFinite(Number(upBA?.bid)) ? Number(upBA.bid) : null;
      const nextDnBid = Number.isFinite(Number(dnBA?.bid)) ? Number(dnBA.bid) : null;
      if (nextUpBid != null && nextDnBid != null) {
        lastObservedBids = {
          upBid: nextUpBid,
          downBid: nextDnBid,
          tsMs: nowTickMs,
        };
      }
      if (pairUsable && nextUpBid != null && nextDnBid != null) {
        lastGoodObservedBids = {
          upBid: nextUpBid,
          downBid: nextDnBid,
          tsMs: nowTickMs,
        };
      }
      const pairSource = String(pair?.source || "");
      const shouldRecordCanonicalLoopSample =
        String(current?.slug || "").trim() &&
        pairUsable &&
        pairFresh &&
        nextUpBid != null &&
        nextDnBid != null &&
        pairSource === "ws_direct";
      if (shouldRecordCanonicalLoopSample) {
        recordCanonicalQuoteSample(
          String(current.slug || ""),
          current?.startMs,
          nowTickMs,
          nextUpBid,
          nextDnBid
        );
      }
      recordSessionTracePoint(current.slug, nowTickMs, lastObservedBids.upBid, lastObservedBids.downBid);
      sampleQuoteLagTimeline(nowTickMs);
      markLoopStage("quote_path");

      const elapsedSec = current.startMs ? (nowMs() - current.startMs) / 1000 : 0;
      const isFinal = Date.now() >= current.endMs;

      stPaper.balanceUsd = paperAccount.balanceUsd;
      for (const lane of PAPER_LANES) {
        paperLaneStates[lane].balanceUsd = paperAccount.balanceUsd;
      }
      stLive.balanceUsd = liveAccount.balanceUsd ?? stLive.balanceUsd ?? null;

      const suppressHostGlobalStrategyEngines = hasActiveExecutionBotInstances();
      if (!suppressHostGlobalStrategyEngines) {
        const laneOrder: StrategyLane[] =
          Math.floor(elapsedSec * 10) % 2 === 0
            ? ["BASE", "NO_CROSS_WINNER"]
            : ["NO_CROSS_WINNER", "BASE"];
        for (const lane of laneOrder) {
          await awaitLogged(`runEngineTick:paper:${lane}`, runEngineTick("paper", upBA, dnBA, elapsedSec, isFinal, lane));
        }
        syncPaperAggregateState();
      }
      if (uiLive.enabled && !hasActiveRealLiveExecutionBots()) {
        await awaitLogged("disableOrphanHostGlobalLiveEngine", disableOrphanHostGlobalLiveEngine("main_loop_no_active_live_bots"));
      }
      const suppressHostGlobalLiveEngine = suppressHostGlobalStrategyEngines || hasActiveRealLiveExecutionBots();
      if (uiLive.enabled && !suppressHostGlobalLiveEngine) {
        await awaitLogged("maybeResolveHostLiveTpFill", maybeResolveHostLiveTpFill("main_loop"));
      }
      if (uiLive.enabled && !suppressHostGlobalLiveEngine) {
        await awaitLogged("runEngineTick:live", runEngineTick("live", upBA, dnBA, elapsedSec, isFinal));
      }
      if (uiLive.enabled && !suppressHostGlobalLiveEngine) {
        await awaitLogged("maybeExitGeneric:live", maybeExitGeneric("live", upBA, dnBA, { stopOnly: true }));
      }
      if (!suppressHostGlobalLiveEngine) {
        await awaitLogged("maybeEnsureLiveTakeProfitOrder", maybeEnsureLiveTakeProfitOrder());
      }
      if (!uiLive.enabled) {
        await awaitLogged("flushLiveDisabledExposureWatchdog", flushLiveDisabledExposureWatchdog());
      }
      markLoopStage("engines");

      const shouldBroadcastPrices =
        PRICES_CLIENT_BROADCAST_ENABLED &&
        hasOpenWsClients() &&
        ((now - lastPricesClientBroadcastMs) >= PRICES_CLIENT_BROADCAST_INTERVAL_MS);
      if (shouldBroadcastPrices) {
        const pricesPayload: any = {
          type: "prices",
          t: nowMs(),
          elapsed: elapsedSec,
          up: { bid: upBA.bid },
          down: { bid: dnBA.bid },
          market: { slug: current.slug, startMs: current.startMs, endMs: current.endMs, volumeUsd: current.volumeUsd },
        };
        const shouldAttachState =
          !PRICES_CLIENT_BROADCAST_MINIMAL ||
          ((now - lastPricesStateBroadcastMs) >= PRICES_STATE_BROADCAST_INTERVAL_MS);
        if (shouldAttachState) {
          pricesPayload.ui = withDerivedUi(activeUi(), activeBalanceUsd());
          pricesPayload.st = activeSt();
          pricesPayload.paper = {
            ui: withDerivedUi(uiPaper, paperAccount.balanceUsd),
            st: stPaper,
            balanceUsd: paperAccount.balanceUsd,
          };
          pricesPayload.live = {
            ui: withDerivedUi(uiLive, liveAccount.balanceUsd ?? stLive.balanceUsd ?? null),
            st: stLive,
            balanceUsd: liveAccount.balanceUsd,
          };
          pricesPayload.pendingUiLive = pendingUiLive;
          lastPricesStateBroadcastMs = now;
        }
        if ((now - lastPricesHealthBroadcastMs) >= PRICES_HEALTH_BROADCAST_INTERVAL_MS) {
          pricesPayload.health = buildHealthSnapshot(true);
          lastPricesHealthBroadcastMs = now;
        }
        lastPricesClientBroadcastMs = now;
        broadcast(pricesPayload);
      }
      markLoopStage("prices_broadcast");

      if (now - lastHeartbeat >= 10000) {
        const strategyFile = path.basename(STRATEGY_PATH);
        const strategyIsDerisk = isDeriskModeLabel(STRATEGY_PATH) || isDeriskModeLabel(path.basename(STRATEGY_PATH));
        const paperEntryShown = strategyIsDerisk ? 0.55 : Number(uiPaper.entry);
        const paperExitShown = strategyIsDerisk ? 0.96 : Number(uiPaper.exit);
        const paperStopShown = strategyIsDerisk ? Number(DERISK_STRICT_STOP_THR) : Number(uiPaper.stop);
        const strategyState = `strategyFile=${strategyFile} strategyPath=${STRATEGY_PATH} strategyLoaded(paper=${!!strategyPaper},live=${!!strategyLive})`;
        const paperCfg =
          `en=${uiPaper.enabled} paper buy limit=${paperEntryShown} paper take profit=${paperExitShown} ` +
          `paper stop loss=${paperStopShown} useStop=${uiPaper.useStop} stopGate=${uiPaper.useStopTimeGate} ` +
          `stopStartSec=${uiPaper.stopStartSec} minEntrySec=${uiPaper.minEntrySec} ` +
          `hcSpread=${uiPaper.highConfidenceSpread} hcLead=${uiPaper.highConfidenceLead}`;
        const liveCfg =
          `en=${uiLive.enabled} live buy limit=${uiLive.entry} live take profit=${uiLive.exit} ` +
          `live stop loss=${uiLive.stop} useStop=${uiLive.useStop} stopGate=${uiLive.useStopTimeGate} ` +
          `stopStartSec=${uiLive.stopStartSec} minEntrySec=${uiLive.minEntrySec} ` +
          `hcSpread=${uiLive.highConfidenceSpread} hcLead=${uiLive.highConfidenceLead} ` +
          `entryStyle=${LIVE_ENTRY_STYLE} immTtlMs=${LIVE_ENTRY_IMMEDIATE_TTL_MS}`;
        const pendingLiveCfg = pendingUiLive
          ? ` pendingLive(entry=${pendingUiLive.entry} tp=${pendingUiLive.exit} sl=${pendingUiLive.stop} ` +
            `useStop=${pendingUiLive.useStop} stopGate=${pendingUiLive.useStopTimeGate} ` +
            `stopStartSec=${pendingUiLive.stopStartSec} en=${pendingUiLive.enabled})`
          : "";

        const upQuoteLagMs = quoteAgeMs(String(current.upToken));
        const downQuoteLagMs = quoteAgeMs(String(current.downToken));
        console.log(
          `[HEARTBEAT ${isoNow()}] v=${LIVEFIX_RUNTIME_VERSION} ${current.slug} t=${elapsedSec.toFixed(2)}s | ` +
            `UP bid=${upBA.bid} DOWN bid=${dnBA.bid} quoteLagMs(up=${upQuoteLagMs ?? "na"},down=${downQuoteLagMs ?? "na"}) | ` +
            `${strategyState} | ` +
            `PAPER_CFG(${paperCfg}) bal=${paperAccount.balanceUsd.toFixed(2)} st(side=${stPaper.side ?? "-"} entered=${stPaper.entered} exited=${stPaper.exited} shares=${stPaper.shares ?? "-"}) | ` +
            `LIVE_CFG(${liveCfg}) bal=${liveAccount.balanceUsd ?? "—"} st(side=${stLive.side ?? "-"} entered=${stLive.entered} exited=${stLive.exited} shares=${stLive.shares ?? "-"} token=${stLive.positionTokenId ?? "-"})${pendingLiveCfg}`
        );
        lastHeartbeat = now;
      }
      markLoopStage("heartbeat");

      const mainLoopDurationMs = Math.max(0, nowMs() - workStartedAtMs);
      if (mainLoopDurationMs >= 500) {
        const parts = Object.entries(loopTiming)
          .filter(([, ms]) => Number.isFinite(Number(ms)) && Number(ms) > 0)
          .sort((a, b) => Number(b[1]) - Number(a[1]))
          .map(([label, ms]) => `${label}=${Math.round(Number(ms))}`)
          .join(" ");
        console.warn(
          `[MAIN LOOP SLOW] slug=${String(current?.slug || "")} durationMs=${Math.round(mainLoopDurationMs)} ` +
          `quotePairAgeMs=${String(
            Number.isFinite(Number(quotePairCache?.tsMs)) ? Math.max(0, nowMs() - Number(quotePairCache?.tsMs)) : null
          )} hasWsClients=${hasOpenWsClients()} ${parts}`
        );
      }
      recordCpuWork("main_loop", nowMs() - workStartedAtMs);
      await sleep(periodMs);
    } catch (e: any) {
      console.log(`[${isoNow()}] loop error: ${String(e?.message ?? e)}`);
      broadcast({ type: "status", t: nowMs(), status: `loop error: ${String(e?.message ?? e)}` });
      recordCpuWork("main_loop", nowMs() - workStartedAtMs);
      await sleep(500);
    }
  }
}

// ===== Start =====
const BIND_HOST = String(process.env.HOST || process.env.BIND_HOST || "127.0.0.1").trim() || "127.0.0.1";
server.listen(PORT, BIND_HOST, () => {
  registerServerRun();
  console.log(`[${isoNow()}] listening on http://${BIND_HOST}:${PORT} runtime=${LIVEFIX_RUNTIME_VERSION}`);
  console.log(`[RUN META] tradeLogDir=${TRADE_LOG_DIR} runMeta=${RUNS_META_PATH} runId=${SERVER_RUN_ID}`);
  appendServerRestartEvent("server_boot");
  broadcast({ type: "status", t: nowMs(), status: `listening on :${PORT} runId=${SERVER_RUN_ID}` });

  loadRuntimeStateSnapshot();
  loadMultiMarketState();
  ensureLiveEngineEnabledForActiveLiveBots("startup_restore");
  if (!entryBlockedSessionSlug && current.slug) {
    entryBlockedSessionSlug = current.slug;
    entryBlockActive = true;
    console.log(`[ENTRY GUARD] armed from snapshot session=${current.slug}; new entries blocked until next session`);
  }

  if (BACKGROUND_REPORTS_ENABLED) {
    writeTradeSummarySnapshot();
    setInterval(writeTradeSummarySnapshot, 60_000);
    writeRunPathSummarySnapshot();
    setInterval(writeRunPathSummarySnapshot, 30_000);
    writeSessionVolatilitySnapshot();
    setInterval(writeSessionVolatilitySnapshot, 30_000);
    writeMissedSameSideHcSnapshot();
    setInterval(writeMissedSameSideHcSnapshot, 30_000);
    const initialDaily = trailing24hDailyReport();
    if (initialDaily) {
      broadcast({
        type: "status",
        t: nowMs(),
        status: `daily report updated: pnl24h=${Number(initialDaily?.pnlUsd?.total ?? 0).toFixed(2)} winRate=${initialDaily?.performance?.winRatePct ?? "n/a"}%`,
      });
    }
    setInterval(() => {
      const rep = trailing24hDailyReport();
      if (rep) {
        broadcast({
          type: "status",
          t: nowMs(),
          status: `daily report updated: pnl24h=${Number(rep?.pnlUsd?.total ?? 0).toFixed(2)} winRate=${rep?.performance?.winRatePct ?? "n/a"}%`,
        });
      }
    }, 15 * 60_000);
  } else {
    console.log("[PERF] background report writers disabled (set BACKGROUND_REPORTS_ENABLED=1 to enable)");
  }
  writeRuntimeStateSnapshot();
  setInterval(writeRuntimeStateSnapshot, RUNTIME_STATE_SNAPSHOT_INTERVAL_MS);
  setInterval(flushPaperLiveParityWatchdog, PAPER_LIVE_PARITY_WATCHDOG_MS);
  setInterval(persistMultiMarketState, MULTI_STATE_PERSIST_INTERVAL_MS);
  void tickAllBotRuntimes();
  setInterval(() => {
    void tickAllBotRuntimes();
  }, BOT_RUNTIME_POLL_MS);
  console.log(`[BOT RUNTIME] poll interval=${BOT_RUNTIME_POLL_MS}ms`);
  if (PARA_SYNC_ENABLED) {
    void bootstrapParaFolders()
      .then(() => syncArtifactsToPara("startup"))
      .catch((e: any) => {
        console.warn(`[PARA BOOTSTRAP ERROR] ${String(e?.message ?? e)}`);
      });
    setInterval(() => {
      void syncArtifactsToPara("interval");
    }, PARA_SYNC_INTERVAL_MS);
  }

  reloadStrategyFactorySafe("startup");
  reloadEngineStrategy("paper", "startup");
  reloadEngineStrategy("live", "startup");
  setupStrategyHotReloadWatcher();

  startEventLoopMonitor();
  startQuoteStream();
  startQuotePump();
  startQuoteBroadcast();
  console.log(
    `[QUOTE FEED] mode=${QUOTE_STREAM_ENABLED ? "websocket_primary+rest_fallback" : "direct_clob_server"} wsUrl=${QUOTE_STREAM_URL} pumpIntervalMs=${QUOTE_PUMP_INTERVAL_MS} quoteBroadcastMs=${QUOTE_BROADCAST_INTERVAL_MS} quoteBroadcastHealthyMs=${QUOTE_BROADCAST_HEALTHY_INTERVAL_MS} quoteBroadcastRolloverMs=${QUOTE_BROADCAST_ROLLOVER_INTERVAL_MS} quoteBroadcastIdleMs=${QUOTE_BROADCAST_IDLE_INTERVAL_MS} fetchTimeoutMs=${QUOTE_FETCH_TIMEOUT_MS} maxStaleMs=${QUOTE_MAX_STALE_MS} pairSkewMaxMs=${QUOTE_PAIR_SKEW_MAX_MS} fallback(triggerMs=${QUOTE_FALLBACK_TRIGGER_MS},timeoutMs=${QUOTE_FALLBACK_TIMEOUT_MS},cooldownMs=${QUOTE_FALLBACK_COOLDOWN_MS}) streamReconnect(staleMs=${QUOTE_STREAM_STALE_RECONNECT_MS},hardMs=${QUOTE_STREAM_HARD_RECONNECT_MS})`
  );

  void mainLoop();
});
